window.BANNANJE_VERSE_MEANINGS_HI = {
  "1.1": "धृतराष्ट्र उवाच — धृतराष्ट्र बोले:\n\nधर्मक्षेत्रे कुरुक्षेत्रे समवेताः युयुत्सवः ।\n\nमामकाः पाण्डवाश्च एव किम् अकुर्वत सञ्जय -- धर्म की भूमि कुरुक्षेत्र में युद्ध की इच्छा से एकत्र हुए मेरे लोगों और पांडवों ने क्या किया, हे संजय?\n\nजैसा पहले कहा गया, अंधे धृतराष्ट्र का यह प्रश्न वास्तव में जीव का ही अंधा प्रश्न है। हम इतने अंधे हैं कि हमें यह भी नहीं पता कि हमें कुछ नहीं पता! इसीलिए गीता धृतराष्ट्र के प्रश्न से ही आरंभ होती है।\n\nअंधे धृतराष्ट्र ने संजय से — जिन्हें व्यास से दूरदृष्टि और दूरश्रवण की शक्ति मिली थी — यह प्रश्न पूछा; यही गीता का पहला श्लोक है। परशुराम द्वारा समन्तपञ्चक (चारों ओर पाँच सरोवर) के रूप में निर्मित यह युद्धभूमि, बाद में 'कुरु' नामक राजा के समय परम धर्मक्षेत्र बनकर कुरुक्षेत्र कहलाई। इसी को यहाँ \"धर्मक्षेत्रे कुरुक्षेत्रे\" कहा गया है। हमारा हृदय ही धर्मक्षेत्र है। जो मन यह निर्णय करता है कि क्या धर्म है और क्या अधर्म, वही कुरुक्षेत्र (कर्मक्षेत्र) है। मन का यह संघर्ष ही महाभारत है। यहाँ अंधे धृतराष्ट्र संजय से पूछते हैं — 'युद्ध की इच्छा से आमने-सामने खड़े मेरे लोगों और पांडवों ने क्या किया?' 'मेरे लोग और पांडव' कहकर संबोधित करने से शासक धृतराष्ट्र अपने भीतर की दुर्बलता को ही प्रकट कर रहे हैं — यह इस श्लोक में स्पष्ट झलकता है।",
  "1.2": "संजय उवाच — संजय बोले:\n\nदृष्ट्वा तु पाण्डवानीकं व्यूढं दुर्योधनस्तदा ।\n\nआचार्यमुपसङ्गम्य राजा वचनमब्रवीत् -- तब राजा दुर्योधन ने व्यूह में सजी पांडव सेना को देखकर, आचार्य के पास जाकर यह बात कही।\n\nइस श्लोक को समझने से पहले यहाँ आए 'अनीक' शब्द का अर्थ जान लें। जैसा आप जानते हैं, महाभारत युद्ध में अठारह अक्षौहिणी सेनाएँ शामिल थीं — इनमें सात पांडवों की ओर से लड़ीं, शेष कौरवों की ओर से। अक्षौहिणी सेना का सबसे बड़ा विभाग है, जो नौ छोटे विभागों (पत्ति, सेनामुख, गुल्म, गण, वाहिनी, पृतना, चमू, अनीकिनी, अक्षौहिणी) से मिलकर बनता है — एक अक्षौहिणी में 21,870 हाथी, 21,870 रथ, 65,610 घोड़े और 1,09,350 पैदल सैनिक होते हैं।\n\nव्यूह की विशिष्ट रचना में अनुशासित खड़ी पांडव सेना की एक 'अनीक' को देखकर ही दुर्योधन की चिंता बढ़ जाती है — यह उसका पहला मानसिक आघात है। इसी मनःस्थिति में वह आचार्य द्रोण के पास जाता है — यहाँ आचार्य से तात्पर्य गुरुओं में ज्येष्ठ द्रोणाचार्य से है। उनके पास जाकर, शिष्य की तरह नहीं बल्कि राजा के अहंकार से, वह बोलने लगता है।\n\nइस श्लोक में मनोविज्ञान की एक सूक्ष्म बात है — 'मैं तो जीतूँगा ही' यह सोचकर युद्धभूमि में आया दुर्योधन, पांडवों की एक छोटी-सी अनीक देखते ही मानसिक संतुलन खो बैठता है। अपने पास ग्यारह अक्षौहिणी सेना होते हुए भी, अपनी सेना का उत्साह बढ़ाने के बजाय पांडव सेना के वीरों के बारे में बात करने लगना — यही उसकी मनःस्थिति को दर्शाता है।",
  "1.3": "पश्येतां पाण्डुपुत्राणामाचार्य महतीं चमूम् ।\n\nव्यूढां द्रुपदपुत्रेण तव शिष्येण धीमता -- आचार्य, देखिए पाण्डु-पुत्रों की इस बड़ी सेना को, जिसे आपके ही बुद्धिमान शिष्य द्रुपद-पुत्र ने व्यूह में सजाया है।\n\nदुर्योधन सेनापति भीष्म के पास न जाकर द्रोणाचार्य के पास जाता है, और ऐसी बात कहता है जो भीष्म को भी सुनाई दे — द्रोण को व्यंग्य से 'पांडवों का आचार्य' कहकर संबोधित करते हुए। द्रुपद-पुत्र धृष्टद्युम्न पांडव सेना का सेनापति है। द्रुपद और द्रोण बचपन के मित्र थे, पर राजा बनने पर द्रुपद ने द्रोण का अपमान किया था। इसी वैर के कारण द्रोण कौरव-पांडवों के गुरु बने, और शिक्षा पूर्ण होने पर द्रुपद का आधा राज्य छीनकर कहा — 'अब मैं तुम्हारे समान हूँ।' इसी प्रतिशोध से द्रुपद ने यज्ञ द्वारा जो पुत्र पाया, वही धृष्टद्युम्न है — जिसे द्रोण ने ही शिक्षा दी। दुर्योधन उसे 'तुम्हारा ही शिष्य' कहकर स्मरण कराता है — यह उसके भीतर के भय और मानसिक अस्थिरता का पहला प्रमाण है, जो राज्यलोभ, द्वेष और ईर्ष्या से जन्मता है।",
  "1.4": "अत्र शूरा महेष्वासा भीमार्जुनसमा युधि ।\n\nयुयुधानो विराटश्च द्रुपदश्च महारथः -- यहाँ सभी वीर, महान धनुर्धर, युद्ध में भीम-अर्जुन के समान हैं — सात्यकि, विराट और द्रुपद भी महारथी हैं।\n\nपांडव सेना को देखकर मानसिक रूप से विचलित दुर्योधन, द्रोणाचार्य के पास जाकर वहाँ खड़े वीरों के बारे में बताता है। सामान्यतः जिससे हमें भय होता है, वही हमें हर जगह दिखाई देने लगता है — जैसे कंस को कृष्ण दिखते थे। यही मनोविज्ञान है। यहाँ दुर्योधन को भीम-अर्जुन का भय है, इसीलिए वह कहता है कि वहाँ के सभी वीर भीम-अर्जुन के समान हैं। वस्तुतः उस समय का सबसे बड़ा धनुष गांडीव था, जिसे लेकर युद्ध करने वाले केवल अर्जुन, भीम और श्रीकृष्ण ही थे। सात्यकि, विराट और द्रुपद — ये तीनों वास्तव में कौरवों के पक्ष में होने योग्य थे, पर विभिन्न कारणों से पांडवों के पक्ष में जा मिले। यही दुर्योधन के भीतरी विषाद का कारण है।",
  "1.5": "धृष्टकेतुश्चेकितानः काशिराजश्च वीर्यवान् ।\n\nपुरुजित्कुन्तिभोजश्च शैब्यश्च नरपुङ्गवः -- धृष्टकेतु, चेकितान, बलशाली काशिराज, तथा पुरुजित्, कुन्तिभोज और नरश्रेष्ठ शैब्य।\n\nऊपर से इस श्लोक में हमें छह वीरों के नाम मिलते हैं, पर यहाँ केवल इन छह व्यक्तियों को ही नहीं देखना है — इनके नाम गिनाते समय दुर्योधन की मनःस्थिति और उसकी वेदना को देखना है। धृष्टकेतु शिशुपाल का पुत्र है — शिशुपाल को कृष्ण ने मारा था, अब वही शत्रु-पुत्र पांडवों के पक्ष में है! चेकितान यादव वीर है, जो बलराम की अनुपस्थिति में पांडव-शिविर में जा मिला। काशिराज भीमसेन के श्वसुर हैं। पुरुजित् और कुन्तिभोज कुंती के दत्तक बंधु हैं — वे भी पांडवों के पक्षधर हैं। शैब्य — जिसे अपने पुत्र जयद्रथ की सहायता करने के कारण भीमसेन ने मार डाला था — वह शैब्य भी पांडवों के पक्ष में खड़ा है।",
  "1.6": "युधामन्युश्च विक्रान्त उत्तमौजाश्च वीर्यवान् ।\n\nसौभद्रो द्रौपदेयाश्च सर्व एव महारथाः -- पराक्रमी युधामन्यु, बलशाली उत्तमौज, सुभद्रा का पुत्र, तथा द्रौपदी के पुत्र — ये सभी निश्चय ही महारथी हैं।\n\nपांडव सेना देखकर भीतर से घबराया दुर्योधन, एक ही परिवार के प्रत्येक व्यक्ति का यहाँ उल्लेख करता है। युधामन्यु और उत्तमौज द्रुपद के अन्य दो पुत्र हैं, जिन्हें वह पराक्रमी कहता है। इतना ही नहीं, वह सुभद्रा के पुत्र अभिमन्यु तथा तेरह से अठारह वर्ष की आयु के, अभी पूर्ण प्रौढ़ भी न हुए द्रौपदी के पाँच पुत्रों को भी 'महारथी' कहकर संबोधित करता है!\n\nयहाँ स्पष्ट देखने योग्य बात यह है कि एक बार भय हमें घेर ले तो रस्सी भी सांप जैसी दिखने लगती है, और ऐसे में हमारी वास्तविक शक्ति भी व्यर्थ हो जाती है। अपने पास ग्यारह अक्षौहिणी सेना होते हुए भी, युद्ध से पहले अपनी सेना को उत्साहित करने के बजाय दुर्योधन पांडव सेना के वीरों के बारे में ही बोलता जा रहा है — यह स्पष्टतः उसकी मनःस्थिति को दर्शाता है। ध्यान दें कि उसने यहाँ ग्यारह वीरों के नाम गिनाए हैं (सात्यकि, विराट, द्रुपद, धृष्टकेतु, चेकितान, काशिराज, पुरुजित्, कुन्तिभोज, शैब्य, युधामन्यु और उत्तमौज)। अपने पास ग्यारह अक्षौहिणी सेना का प्रतिनिधित्व करने वाले वीर होते हुए भी, उसे सात अक्षौहिणी वाली पांडव सेना के ग्यारह वीर ही अधिक उभरकर दिखते हैं — भगवान से दूर खड़े प्रत्येक अधर्मी की यही दशा होती है। वे सदा भीतर के भय में जीते हैं, और उस भय को छिपाने के लिए अनुचित बातें बोलते हैं।",
  "1.7": "अस्माकं तु विशिष्टा ये तान्निबोध द्विजोत्तम ।\n\nनायका मम सैन्यस्य संज्ञार्थं तान्ब्रवीमि ते -- हे द्विजोत्तम, हमारे पक्ष के जो विशिष्ट लोग हैं, उन्हें भी जानिए — मेरी सेना के नायकों को मैं आपकी जानकारी हेतु बताता हूँ।\n\nएक सच्चा वीर, शक्ति कम होने पर भी, युद्धकाल में युक्ति से कार्य करता है। एक नायक अपनी सेना को, अपने अनुयायियों को उत्साहित करता है — उन्हें यह विश्वास दिलाता है कि वे शत्रु-सेना से अधिक बलशाली हैं। पर यहाँ दुर्योधन अपने सेनापति भीष्म से सलाह लेने के बजाय, आचार्य द्रोण के सामने शत्रु-सेना के वीरों की विशेष चर्चा करके कहता है — 'आपकी जानकारी के लिए मैं अपनी सेना के नायकों के बारे में बताता हूँ!' यह क्रम ही उलटा है।",
  "1.8": "भवान्भीष्मश्च कर्णश्च कृपश्च समितिञ्जयः ।\n\nअश्वत्थामा विकर्णश्च सौमदत्तिस्तथैव च -- पूज्य आप, भीष्म, कर्ण, विजयशील कृप, अश्वत्थामा, विकर्ण, तथा सोमदत्त-पुत्र भी।\n\nपांडव सेना के ग्यारह महावीरों और छह कुमारों की वीरता का वर्णन करने वाले दुर्योधन को अपने पक्ष में एक भी वीर नहीं दिखता! यहाँ वह व्यंग्य से अपने सात वीरों के नाम गिनाता है — पूज्य आप द्रोण, युद्ध से पहले धर्मराज को विजय का आशीर्वाद देने वाले भीष्माचार्य, भीष्म के रणभूमि में रहते हुए न लड़ने की शपथ लेकर बैठे कर्ण, वेदपारंगत आचार्य कृप, विक्षिप्त मन वाले अश्वत्थामा, द्रौपदी के अपमान की निंदा करते हुए भी उससे लाभ उठाने का प्रयास करने वाले विकर्ण, तथा शिष्टाचारवश आए भीष्म के पिता शांतनु के भाई के पुत्र — सोमदत्त-पुत्र भूरिश्रवा।\n\nयदि हम ध्यान से देखें तो कौरव पक्ष में ग्यारह अक्षौहिणी सेना का नेतृत्व करने योग्य वीर थे, उसके निन्यानबे भाई थे, शल्य और भगदत्त जैसे वीराधिवीर उसके साथ थे। पर पांडव सेना देखकर भयभीत हुआ दुर्योधन यह सब भूलकर अपने ही वीरों की तुच्छता से चर्चा करता है — इससे स्पष्ट होता है कि वह मानसिक रूप से कितना विचलित था। युद्ध के परिणाम की चिंता में वह अपना कर्तव्य ही भूल बैठा था!",
  "1.9": "अन्ये च बहवः शूरा मदर्थे त्यक्तजीविताः ।\n\nनानाशस्त्रप्रहरणाः सर्वे युद्धविशारदाः -- और भी बहुत से शूरवीर हैं, जो मेरे लिए प्राण त्यागने को तैयार हैं, विविध शस्त्रों से प्रहार करने वाले, सभी युद्ध में निपुण।\n\nऊपर से देखने पर लगता है कि दुर्योधन अपने पक्ष के वीरों के विषय में कह रहा है, पर यहाँ वह जो कह रहा है वह कुछ और ही है। वह यह बात द्रोण से कह रहा है, और अपनी बात 'पांडवों के आचार्य' कहकर आरंभ करता है। यहाँ वह — 'हमारे पास भी बहुत शूरवीर हैं, सभी अपने प्राण देने को तैयार हैं' — यह बात व्यंग्य से कहता है। विविध शस्त्र चलाने में समर्थ इन सबका उल्लेख करते हुए दुर्योधन वास्तव में यही भाव व्यक्त कर रहा है कि उसके अपने पक्ष में कोई सचमुच उसका अपना नहीं है।",
  "1.10": "अपर्याप्तं तदस्माकं बलं भीष्माभिरक्षितम् ।\n\nपर्याप्तं त्विदमेतेषां बलं भीमाभिरक्षितम् -- भीष्म द्वारा रक्षित हमारी वह सेना पर्याप्त नहीं है, जबकि भीम द्वारा रक्षित इनकी यह सेना पर्याप्त है।\n\nयहाँ दुर्योधन की बात का निष्कर्ष है। वह कहता है — 'पांडव-पक्षधर भीष्माचार्य के नेतृत्व वाली हमारी वह सेना, भीम द्वारा रक्षित इस सेना के सामने पर्याप्त नहीं है।' यदि सूक्ष्मता से देखें तो भीष्म कौरव-सेनापति हैं, पर भीम पांडव-सेनापति नहीं हैं। दुर्योधन को भीम से द्वेष भी है और भय भी, इसीलिए वह पांडव सेना को 'भीम द्वारा रक्षित' कहकर संबोधित करता है। और भी सूक्ष्मता से देखें तो — दुर्योधन स्वयं युद्धभूमि में अपनी सेना के अग्रभाग में खड़ा है, जबकि पांडव सेना उससे दूर है; फिर भी बोलते समय वह 'यह पांडव सेना' और 'वह हमारी सेना' कहता है — मानो पांडव सेना पहले ही उसके निकट आ खड़ी हो और उसकी अपनी सेना उससे बहुत दूर हो।",
  "1.11": "अयनेषु च सर्वेषु यथाभागमवस्थिताः ।\n\nभीष्ममेवाभिरक्षन्तु भवन्तः सर्व एव हि -- सभी मोर्चों पर अपने-अपने विभाग के अनुसार स्थित रहते हुए, आप सब लोग केवल भीष्म की ही रक्षा करें।\n\n'सब लोग उचित स्थान पर खड़े होकर भीष्म की रक्षा करते रहें' — यह दुर्योधन द्रोण को संबोधित करके कहता है। मानो वह कह रहा हो — 'हमारे वृद्ध सेनापति भीष्माचार्य का थोड़ा ध्यान रखो' — यह उसके अपने ही सेनापति पर अविश्वास को दर्शाता है!\n\nयह सुनकर भीष्माचार्य के हृदय को कितनी पीड़ा हुई होगी, इसकी कल्पना करना भी कठिन है। अपनी अंतरात्मा के विरुद्ध, अपने कुल की राजाज्ञा के बंधन में, अपने प्रिय पौत्रों के विरुद्ध युद्ध में ईमानदारी से खड़े होने पर भी, आत्मविश्वास खोए हुए दुर्योधन के ऐसे व्यंग्यपूर्ण शब्द उन्हें कितना दुःख पहुँचाए होंगे — यह हम अनुमान भी नहीं लगा सकते। यह सुनकर भीष्माचार्य ने क्या किया, यह हम अगले श्लोक में देखेंगे।",
  "1.12": "तस्य सञ्जनयन्हर्षं कुरुवृद्धः पितामहः ।\n\nसिंहनादं विनद्योच्चैः शङ्खं दध्मौ प्रतापवान् -- उसे प्रसन्न करने के लिए कुरुकुल के प्रतापी वृद्ध पितामह भीष्म ने ऊँचे स्वर में सिंहनाद करके शंख बजाया।\n\nयुद्ध से पहले आत्मविश्वास खोकर विषाद से बोल रहे दुर्योधन का उत्साह बढ़ाने के लिए, कुरुवंश के सबसे वयोवृद्ध और प्रतापी भीष्माचार्य ने सिंहनाद करके अपने कर्तव्य के अनुरूप शंख बजाया।\n\nशंख अत्यंत बड़ी दुष्ट-संहारक शक्ति है। प्राचीन काल में प्रातः-सायं घर के हर कोने से आठों दिशाओं तक सुनाई देने योग्य शंखनाद किया जाता था, क्योंकि शंखनाद में दुष्टशक्ति का हृदय विदीर्ण करने की सामर्थ्य होती है। जहाँ तक शंखनाद सुनाई देता है, वहाँ तक कोई दुष्टशक्ति नहीं फटक सकती। मृत्यु के तांडव-स्थल रणभूमि में आसुरी शक्ति का प्रभाव न रहे, अपने पक्ष को युद्ध के लिए तैयार करने तथा शत्रुओं को अपनी तैयारी का संकेत देने के लिए ही पूर्वकाल में शंख का प्रयोग किया जाता था। यहाँ भीष्माचार्य ने शंखनाद द्वारा अपनी तैयारी का यह संकेत कौरव और पांडव — दोनों सेनाओं तक पहुँचाया।",
  "1.13": "ततः शङ्खाश्च भेर्यश्च पणवानकगोमुखाः ।\n\nसहसैवाभ्यहन्यन्त स शब्दस्तुमुलोऽभवत् -- इसके बाद शंख, नगाड़े, ढोल-मृदंग और गोमुख (कहरवा) सहसा एक साथ बज उठे। उनकी ध्वनि कानों को फाड़ने वाला कोलाहल बन गई।\n\nप्रधान सेनापति भीष्माचार्य के शंख बजाने के बाद, कौरव सेना की ओर से शंख, नगाड़े-ढोल-गोमुख एक साथ बज उठे। यह ध्वनि कर्णभेदी शोर बन गई। यहाँ न दुर्योधन ने और न उसके भाइयों ने शंख बजाया — शंखनाद सेनापति से आरंभ हुआ, उसके पीछे सेना के नायकों और सैनिकों से हुआ। इस प्रकार बिना किसी व्यवस्थित क्रम के हुई यह ध्वनि केवल शोर जैसी प्रतीत होती थी। इससे स्पष्ट होता है कि दुर्योधन ने अपनी शक्ति को व्यवस्थित रूप से संगठित नहीं किया था। हमारे पास चाहे कितना भी साधन (संसाधन) क्यों न हो, जब तक हमें उसे अनुशासित ढंग से उपयोग करना नहीं आता, तब तक वह साधन होते हुए भी व्यर्थ है। साधन हाथ में रखकर सत्ता की लालसा में मनःस्थिति खो बैठने वाला नेता कभी सफलता नहीं देख सकता।",
  "1.14": "ततः श्वेतैर्हयैर्युक्ते महति स्यन्दने स्थितौ ।\n\nमाधवः पाण्डवश्चैव दिव्यौ शङ्खौ प्रदध्मतुः -- इसके बाद श्वेत घोड़ों से युक्त विशाल रथ में बैठे माधव (श्रीकृष्ण) और पाण्डव (अर्जुन) ने अपने दिव्य शंख बजाए।\n\nकौरव सेना के शंख-नगाड़ों के कोलाहल के बाद, चार श्वेत घोड़ों से सजे, वहाँ के सभी रथों में सबसे बड़े रथ पर बैठे श्रीकृष्ण और अर्जुन अपने दिव्य शंखनाद करते हैं (पहले श्रीकृष्ण, फिर अर्जुन)।\n\nइस श्लोक में 'माधव' और 'पांडव' — दो विशेषणों का प्रयोग हुआ है। यहाँ भगवान को 'माधवः' कहा गया है। 'मा' का अर्थ है माता लक्ष्मी, अतः माधव का अर्थ है लक्ष्मीपति भगवान — श्रीमन्नारायण। 'मा' का अर्थ ज्ञान भी है — भगवान ज्ञान के स्वामी हैं, इसलिए भी वे माधव हैं। श्रीकृष्ण के अवतार में मधुवंश में जन्म लेने के कारण भी उन्हें माधव कहा जाता है। वेद में 'मातृ' शब्द वाणी या वाङ्मय के अर्थ में प्रयुक्त हुआ है — ऋग्वेद, यजुर्वेद, सामवेद, अथर्ववेद, रामायण, महाभारत तथा पुराण — इन सात महान ग्रंथों को 'मातृ' कहा जाता है, अतः समस्त वैदिक वाङ्मय के प्रतिपाद्य भगवान माधव हैं।\n\nयहाँ अर्जुन को 'पांडव' कहा गया है। अर्जुन कुंती के तीन पुत्रों में सबसे छोटे हैं, और सामान्यतः सबसे छोटे पुत्र पर स्नेह अधिक होता है — इसीलिए उन्हें पार्थ, कौन्तेय, पांडव कहा जाता था। अर्जुन में भगवान का विशेष सान्निध्य था — वे नारायण के सखा 'नर' के रूप भी हैं। हमारा शरीर भी एक रथ है, जिसमें जीव को चलाने वाले भगवान विराजमान हैं। चार घोड़े चार वेदों के प्रतीक हैं, और श्वेत रंग सत्त्वगुण का संकेत है।",
  "1.15": "पाञ्चजन्यं हृषीकेशो देवदत्तं धनञ्जयः ।\n\nपौण्ड्रं दध्मौ महाशङ्खं भीमकर्मा वृकोदरः -- श्रीकृष्ण ने पाञ्चजन्य, अर्जुन ने देवदत्त, तथा भीषण कर्म करने वाले भीम ने पौण्ड्र नामक महाशंख बजाया।\n\nपांडव पक्ष से सबसे पहले श्रीकृष्ण अपना शंख बजाते हैं। श्रीकृष्ण के शंख का नाम पाञ्चजन्य है, और इस शंख के पीछे एक कथा है — श्रीकृष्ण ने अपनी शिक्षा सांदीपनि मुनि के आश्रम में पूर्ण की थी। शिक्षा समाप्त होने पर गुरुदक्षिणा देना प्रथा थी, और यहाँ कृष्ण ने अपने गुरु को जो गुरुदक्षिणा दी, वह अत्यंत विशिष्ट थी। 'पाञ्चजन' नामक असुर ने सांदीपनि मुनि के पुत्र का वध किया था। शिक्षा समाप्त कर लौटते समय कृष्ण ने गुरुदंपति को गुरुदक्षिणा स्वरूप उनका पुत्र ही लौटा दिया। उसी पाञ्चजन नामक राक्षस के शरीर में रहने वाला शंख ही पाञ्चजन्य है — असुर-संहार और ज्ञानानंद का प्रतीक।\n\nकृष्ण के शंखनाद के तुरंत बाद अर्जुन ने अपना 'देवदत्त' नामक शंख बजाया। वनवास काल में असुरों के विरुद्ध युद्ध करने पर इंद्र ने अर्जुन को देवलोक में विशेष मुकुट पहनाकर यह शंख उपहार में दिया था — यह शंख भी दुष्ट-निग्रह का प्रतीक है।\n\nअर्जुन के शंखनाद के बाद वृकोदर भीम ने पौण्ड्र नामक महाशंख बजाया। यहाँ भीम को 'वृकोदर' कहा गया है — वृकोदर का अर्थ है समस्त विश्व को भस्म कर सकने वाली अग्नि को अपने उदर में धारण करने वाला। भीम कितना पराक्रमी था, यह इस प्रकार व्यक्त किया गया है।\n\nइस श्लोक में श्रीकृष्ण को 'हृषीकेश' कहा गया है। हृषीकेश का अर्थ है हृषीकों अर्थात इंद्रियों के ईश — इंद्रियों के स्वामी। हमें प्रत्येक इंद्रिय प्रदान कर, उसमें स्थित रहकर उसे संचालित करने वाला ही हृषीकेश है। 'केश' शब्द का अर्थ सूर्यकिरण भी है — सूर्यकिरण में सात रंग होते हैं, और इन सातों वर्णों से भरकर जीवन को हर्ष देने वाला भगवान ही हृषीकेश है।",
  "1.16": "अनन्तविजयं राजा कुन्तीपुत्रो युधिष्ठिरः ।\n\nनकुलः सहदेवश्च सुघोषमणिपुष्पकौ -- कुंती-पुत्र राजा युधिष्ठिर ने अनंतविजय, तथा नकुल-सहदेव ने सुघोष और मणिपुष्पक नामक शंख बजाए।\n\nभीम के बाद कुंती के ज्येष्ठ पुत्र, राजा युधिष्ठिर ने धर्म और विजय के प्रतीक 'अनंतविजय' नामक शंख बजाया। नकुल और सहदेव ने क्रमबद्ध रूप से सुघोष और मणिपुष्पक नामक शंख बजाए।\n\nमहाभारत में अन्य किसी राजा के शंख के नाम का उल्लेख कहीं नहीं मिलता। पांडवों के पाँचों शंखों के नाम केवल भगवद्गीता में ही मिलते हैं — शायद यह हमें सदा स्मरण रहे, इसी उद्देश्य से गीता में इन पाँच नामों का विशेष उल्लेख किया गया हो।",
  "1.17": "काश्यश्च परमेष्वासः शिखण्डी च महारथः ।\n\nधृष्टद्युम्नो विराटश्च सात्यकिश्चापराजितः -- महान धनुर्धर काशिराज, महारथी शिखंडी, धृष्टद्युम्न, विराट तथा अपराजित सात्यकि — इन्होंने एक-एक कर शंखनाद किया।\n\nइसके बाद महान धनुर्धर काशिराज, महारथी शिखंडी, धृष्टद्युम्न, विराट तथा अजेय सात्यकि — इस प्रकार एक-एक कर सबने शंखनाद किया।\n\nयहाँ शिखंडी को 'महारथी' कहा गया है, इस पर ध्यान देना चाहिए। बहुत से लोग जानते हैं कि शिखंडी का अर्थ नपुंसक है — पर यह सही नहीं है। शिखंडी का मूल अर्थ है शिखंड (शिखा) रखने वाला। यहाँ शिखा का अर्थ है सिर के बाल — जो लोग बालों को अच्छी तरह संवारकर पीछे मोटी चोटी बाँधते हैं, वे शिखंडी कहलाते हैं। महाभारत के इस शिखंडी का जन्म कन्या रूप में हुआ था, और बाद में यह पुरुष बना महारथी। 'पहले स्त्री होने' के कारण ही भीष्माचार्य ने इसके विरुद्ध बाण का प्रयोग नहीं किया था।",
  "1.18": "द्रुपदो द्रौपदेयाश्च सर्वशः पृथिवीपते ।\n\nसौभद्रश्च महाबाहुः शङ्खान्दध्मुः पृथक्पृथक् -- हे राजन्, द्रुपद, द्रौपदी के पुत्र, तथा महाबाहु सुभद्रा-पुत्र अभिमन्यु — इन सबने भी अलग-अलग शंख बजाए।\n\nयहाँ सूक्ष्मता से देखने पर पांडवों के पक्ष में रहा अनुशासन स्पष्ट झलकता है। कौरव-शिविर से उठे शोरनुमा शंख-नगाड़ों की ध्वनि के उत्तर में, पांडव अनुशासित और क्रमबद्ध ढंग से शंखनाद करते हैं। मनोविज्ञान की दृष्टि से देखें तो एक अनुशासित छोटी सेना, अनुशासनहीन बहुत बड़ी सेना के हृदय को कैसे कंपा सकती है — यह हम यहाँ देख सकते हैं। भगवान के प्रति संपूर्ण समर्पण के भाव में, बिना किसी अहंकार के, भगवान के सारथ्य में धर्मयुद्ध के लिए सज्ज पांडव सेना मानसिक रूप से पूर्णतः तैयार थी। अहंकार के नशे में, सत्ता की लालसा से मानसिक संतुलन खोकर भगवान के विरुद्ध खड़े दुर्योधन के नेतृत्व वाली कौरव सेना पहले ही आत्मविश्वास खो चुकी थी।\n\nयहाँ एक और विशेषता देखने योग्य है — पांडवों की ओर से क्रमबद्ध रूप से अठारह लोगों ने शंखनाद किया। अंकशास्त्र की दृष्टि से देखें तो अक्षरांक पद्धति में अठारह का अर्थ है 'जय' — ज-य। अक्षरांक में पहला अंक इकाई का स्थान, दूसरा दहाई का — इसलिए ज-य का अर्थ इक्यासी नहीं, अठारह है। विजय के प्रतीक इस 'अठारह शंखनाद' के पांडव-शिविर में गूँजने के साथ ही भगवद्गीता का यह अठारहवाँ श्लोक पूर्ण होता है!",
  "1.19": "स घोषो धार्तराष्ट्राणां हृदयानि व्यदारयत् ।\n\nनभश्च पृथिवीं चैव तुमुलो व्यनुनादयन् -- वह ध्वनि आकाश और पृथ्वी को गुँजाती हुई, धृतराष्ट्र के पुत्रों के हृदय को विदीर्ण कर गई।\n\nयहाँ संजय धृतराष्ट्र के पुत्रों को 'धार्तराष्ट्राणाम्' कहकर संबोधित करता है, क्योंकि यह उनका ही उपनाम (surname) है। पहले 'मेरे पुत्र और पांडव' कहकर संबोधन करने वाले धृतराष्ट्र को यह संजय का व्यंग्यपूर्ण उत्तर है।\n\nसंजय कहता है — 'पांडवों की ओर से क्रमबद्ध रूप से गूँजा शंखनाद, आकाश और पृथ्वी को भरकर, प्रतिध्वनित होते हुए, धार्तराष्ट्र नामक तुम्हारे पुत्रों के हृदय को चीर गया।' जैसा पहले कहा गया, पांडवों का यह अनुशासित आचरण युद्ध आरंभ होने से पहले ही कौरवों के हृदय को भेद चुका था — युद्ध शुरू होने से पहले ही पांडवों ने कौरवों को मानसिक रूप से पराजित कर दिया था।",
  "1.20": "अथ व्यवस्थितान्दृष्ट्वा धार्तराष्ट्रान्कपिध्वजः ।\n\nप्रवृत्ते शस्त्रसम्पाते धनुरुद्यम्य पाण्डवः ।\n\nहृषीकेशं तदा वाक्यमिदमाह महीपते -- हे राजन्, तब हनुमद्ध्वज अर्जुन ने धार्तराष्ट्रों को सज्ज देखकर, युद्ध आरंभ होने पर अपना धनुष उठाकर, हृषीकेश (श्रीकृष्ण) से यह वचन कहा।\n\nदोनों ओर से शंखनाद होने पर युद्ध आरंभ होता है। इस अवसर पर, अपने रथ पर हनुमान के विशेष सान्निध्य से युक्त अर्जुन, इंद्रियों के स्वामी श्रीकृष्ण (हृषीकेश) से बात करता है।\n\nअर्जुन के रथ में प्राणदेव (हनुमान) का विशेष सान्निध्य था। हमारे शरीर रूपी रथ में भी जीव की रक्षा सदा प्राण 'भगवान के सान्निध्य में' करता है — जहाँ प्राण है, वहाँ भगवान का सान्निध्य है। पौराणिक कथा के अनुसार अर्जुन के रथ पर हनुमान के सान्निध्य का कारण है वायुदेव का ही दूसरा रूप भीमसेन — सौगंधिक पुष्प लेने निकले भीमसेन को हनुमान ने अपनी पूँछ से रोका था, और उस प्रसंग में हनुमान ने भीमसेन को वचन दिया था कि वे विशेष रूप से अर्जुन के रथ पर सन्निहित रहेंगे। भीमसेन और हनुमान — दोनों प्राणदेव के ही दो रूप हैं (जैसे राम और परशुराम)।\n\nअपनी ध्वजा में हनुमान का सान्निध्य, हाथ में गांडीव, रथ का सारथी स्वयं कृष्ण, और साथ में महापराक्रमी भीमसेन — इस प्रकार युद्ध के लिए सज्ज अर्जुन को अहंकार सताने लगता है। इसी अहंकार में वह कृष्ण से यह बात कहता है।",
  "1.21": "अर्जुन उवाच — अर्जुन ने कहा:\n\nसेनयोरुभयोर्मध्ये रथं स्थापय मेऽच्युत -- हे अच्युत, दोनों सेनाओं के बीच मेरा रथ खड़ा कीजिए।\n\nइस श्लोक में हमें अर्जुन के अहंकार की ध्वनि को सूक्ष्मता से देखना चाहिए। 'मे' का अर्थ है 'मेरा' — अर्जुन के रथ का सारथ्य स्वयं श्रीकृष्ण कर रहे थे, फिर भी यहाँ अहंकार में वह कृष्ण को एक साधारण सारथी की तरह संबोधित कर, 'मेरा रथ दोनों सेनाओं के बीच खड़ा करो' — इस आज्ञा के स्वर में कहता है।\n\nयहाँ अर्जुन श्रीकृष्ण को 'अच्युत' कहकर संबोधित करता है। अच्युत का अर्थ है — स्वयं च्युति-रहित, और भक्तों की च्युति का हरण करने वाला भगवान। बाहर से अहंकार प्रकट होते हुए भी, अर्जुन की अंतरात्मा सजग थी — उसी अंतरात्मा ने उसके मुख से यह नाम बुलवाया। अहंकार बड़े-बड़े महात्माओं को भी नहीं छोड़ता। जब एक बार हमें लगता है कि हमारे हाथ में बल है, तब हम सब कुछ भूलकर अहंकार के दास बन जाते हैं, और यह अहंकार हमें अधोगति की ओर धकेलता है। अर्जुन महाज्ञानी और श्रीकृष्ण का भक्त है — अपने भक्त को अहंकार से घिरा देखकर श्रीकृष्ण किस प्रकार प्रतिक्रिया देते हैं, यह हम आगे के श्लोकों में देखेंगे।",
  "1.22": "यावदेतान्निरीक्षेऽहं योद्धुकामानवस्थितान् ।\n\nकैर्मया सह योद्धव्यमस्मिन्रणसमुद्यमे -- जब तक मैं युद्ध की इच्छा से खड़े इन लोगों को देख न लूँ — इस युद्ध के प्रयास में मुझे किनके साथ युद्ध करना है।\n\nमहाभारत युद्ध इतिहास में दर्ज पहला वैश्विक युद्ध है। ऐसे युद्ध के अग्रभाग में खड़ा अर्जुन अहंकार से बोल रहा है। वह श्रीकृष्ण से कहता है — 'यहाँ जुटे इन लोगों पर एक बार दृष्टि डालनी है। मेरे विरुद्ध युद्ध करने कौन आए हैं, और मेरे साथ मिलकर युद्ध करने कौन आए हैं, यह मुझे एक बार देखना है।' यहाँ 'मेरे साथ युद्ध करने आए लोगों को एक बार देखना है' — इस कथन में अहंकार से भरा व्यंग्य छिपा है। स्वयं महावीर होने और अपने सामने खड़ी इस सेना का कुछ भी महत्व न होने का यह दर्पयुक्त कथन है।",
  "1.23": "योत्स्यमानानवेक्षेऽहं य एतेऽत्र समागताः ।\n\nधार्तराष्ट्रस्य दुर्बुद्धेर्युद्धे प्रियचिकीर्षवः -- दुर्बुद्धि धृतराष्ट्र-पुत्र (दुर्योधन) का प्रिय करने की इच्छा से युद्ध में जुटे इन लोगों को, जो यहाँ युद्ध करने आए हैं, मैं देखना चाहता हूँ।\n\n'बुद्धिहीन दुर्योधन की विजय चाहकर, हमें कष्ट देने के लिए मेरे विरुद्ध खड़े लोगों को मुझे एक बार देखना है' — यह अर्जुन श्रीकृष्ण से आज्ञा के स्वर में कहता है। यहाँ 'मेरे विरुद्ध खड़े लोगों को मुझे देखना है' — ऐसा कहने वाला अर्जुन स्पष्टतः अहंकार का दास बना दिखता है। इसी अहंकार में अर्जुन भगवान को ही भूलकर बोल रहा है।",
  "1.24": "सञ्जय उवाच — संजय ने कहा:\n\nएवमुक्तो हृषीकेशो गुडाकेशेन भारत ।\n\nसेनयोरुभयोर्मध्ये स्थापयित्वा रथोत्तमम् -- हे भरतवंशी राजन्, गुडाकेश (अर्जुन) के इस प्रकार कहने पर, हृषीकेश (श्रीकृष्ण) ने दोनों सेनाओं के बीच उत्तम रथ को खड़ा किया।\n\nइंद्रियों के स्वामी श्रीकृष्ण कुछ भी न कहते हुए रथ को दोनों सेनाओं के बीच खड़ा कर देते हैं। यहाँ से आगे हम श्रीकृष्ण के हर कदम में मनोवैज्ञानिक चिकित्सा-पद्धति (Psychotherapy) देख सकते हैं। अहंकार एक मानसिक स्थिति है — इससे बाहर निकलने के लिए मानसिक चिकित्सा चाहिए। वही कृष्ण यहाँ करके दिखाते हैं। ऐसे श्रीकृष्ण को यदि हम मनोविज्ञान का जनक (Father of Psychology) कहें, तो यह अनुचित नहीं होगा — गीता के पहले अध्याय में ही मनोविज्ञान की अनेक बातें छिपी हैं।\n\nइस श्लोक में कृष्ण को 'हृषीकेश' तथा अर्जुन को 'गुडाकेश' कहा गया है। गुडाकेश का अर्थ है — निद्रा को जीतने वाला वीर।",
  "1.25": "भीष्मद्रोणप्रमुखतः सर्वेषां च महीक्षिताम् ।\n\nउवाच पार्थ पश्यैतान्समवेतान्कुरूनिति -- भीष्म, द्रोण तथा अन्य सभी राजाओं के सामने रथ खड़ा कर, कृष्ण कहते हैं — 'हे पार्थ, यहाँ जुटे इन कुरुओं को देखो।'\n\nअर्जुन की इच्छा के अनुसार श्रीकृष्ण रथ को दोनों सेनाओं के बीच लाकर, भीष्म-द्रोण तथा सभी राजाओं को सीधे दिखाई देने योग्य ढंग से खड़ा कर, बंधुत्व को झकझोरने वाले स्वर में कहते हैं — हे पार्थ, यहाँ जुटे तुम्हारे कुरुओं को देखो।\n\nयह श्रीकृष्ण की अद्भुत मानसिक चिकित्सा (Psychotherapy) है। यहाँ अर्जुन की मनःस्थिति की परीक्षा हो रही है। अर्जुन एक राजा है — उसका मूल कर्तव्य है धर्म के पक्ष में लड़ना और प्रजा का पालन करना। इस कर्तव्य का पालन करते हुए, धर्म के विरुद्ध खड़ा कोई भी हो, उसे दंड देना उसका कर्तव्य है — वह मानो एक न्यायाधीश है। यहाँ 'मेरे परिवार वाले, मेरे बंधु, मेरे मित्र' जैसा कोई भेदभाव उचित नहीं। इस उत्तरदायित्वपूर्ण कार्य में लगे अर्जुन को अपने निकट संबंधियों और गुरुजनों को देखकर कैसी वेदना होती है, यह हम अगले श्लोक में देखेंगे।",
  "1.26": "तत्रापश्यत्स्थितान्पार्थः पितॄनथ पितामहान् ।\n\nआचार्यान्मातुलान्भ्रातॄन्पुत्रान्पौत्रान्सखींस्तथा ।\n\nश्वशुरान्सुहृदश्चैव सेनयोरुभयोरपि -- वहाँ अर्जुन ने दोनों सेनाओं में खड़े पिता-तुल्य जनों, पितामहों, आचार्यों, मामाओं, भाइयों, पुत्रों, पौत्रों, मित्रों, श्वसुरों तथा हितैषियों को देखा।\n\nकृष्ण ने रथ को अर्जुन के आत्मीय बंधुओं के सामने ही खड़ा किया था, इसलिए वहाँ जुटे सभी लोगों को अर्जुन देखता है। अभी तक घमंड से बोल रहे अर्जुन को अब अपने सामने खड़े पिता-समान जन, पितामह, विद्या देने वाले आचार्य, मामा, भाई-बंधु, पुत्र, पौत्र, मित्र-सखा, श्वसुर, हितैषी — ये सभी दोनों ओर दिखाई देते हैं।\n\nयदि सजगता से इस श्लोक को देखें, तो युद्धभूमि में अनेक महत्वपूर्ण लोग होते हुए भी, अर्जुन को केवल गुरुजन, बंधु-बांधव और आत्मीयजन ही दिखाई देते हैं — यहाँ उसमें बंधुप्रेम का जागृत होना स्पष्ट दिखता है। कर्तव्यनिष्ठ, प्रजा का पालन करने वाले राजा के लिए बंधुप्रेम उचित नहीं। प्रजापालक का मूल धर्म है प्रजा का पालन, जिसे उसे कभी विचलित हुए बिना निभाना चाहिए। इस प्रकार कार्य करते हुए 'मेरे बंधु, मेरा परिवार' कहकर कोई भेदभाव करना उचित नहीं।",
  "1.27": "तान्समीक्ष्य स कौन्तेयः सर्वान्बन्धूनवस्थितान् ।\n\nकृपया परयाविष्टो विषीदन्निदमब्रवीत् -- वे सभी बंधुगण एकत्र खड़े देखकर, कौंतेय अर्जुन गहरी करुणा से भरकर, विषाद में यह बोले।\n\nवे सारे बंधु एकत्र खड़े हैं यह देखकर, अर्जुन करुणा से आविष्ट होकर, दुःख से अपनी व्याकुलता कृष्ण के सामने प्रकट करता है।\n\nयहाँ से आगे हम अर्जुन को कई प्रकार से अपनी वेदना श्रीकृष्ण के सामने व्यक्त करते देखते हैं। आगे के श्लोकों को देखने से पहले यहाँ एक छोटा विश्लेषण कर लें। गीता पढ़ते समय कुछ लोगों को श्रीकृष्ण का व्यवहार समझ में नहीं आता — 'हाय, अपने बंधुओं के विरुद्ध कैसे लड़ूँ' अर्जुन के पूछने पर कृष्ण 'युद्ध करो' कहते हैं। क्या यह न्यायसंगत है — यह प्रश्न बहुतों को कचोटता है। यहाँ ध्यान देने योग्य बात यह है — यदि अर्जुन एक सामान्य व्यक्ति के रूप में यह बात कहता, तो निश्चय ही हमें उसे स्वीकार करना चाहिए था। पर यहाँ वह भरतखंड का रक्षक, धर्म के पक्ष में धर्मराज के लिए लड़ने खड़ा राजा है। यदि वह कहता — 'हमारे लिए भरतखंड के लोग न मरें' — तो यह स्वीकार्य होता। पर उसने ऐसा नहीं कहा। उसे वहाँ केवल बंधु ही दिखे। राजा के लिए धर्म के पक्ष में खड़ा व्यक्ति ही बंधु है। धर्म के विरुद्ध जो भी खड़ा हो, वह केवल अपराधी है — उसे दंड देना राजा का परम धर्म है। जैसे न्यायासन पर बैठा न्यायाधीश अन्याय करने वाले अपने बंधु को 'यह मेरा अपना है' कहकर क्षमा नहीं कर सकता, वैसे ही राजा को भी यहाँ धर्म ही देखना चाहिए, बंधुत्व नहीं।\n\nआगे अर्जुन कई प्रकार के तर्कों (Arguments) से श्रीकृष्ण को समझाने (Convince) का प्रयत्न करता है। पर श्रीकृष्ण कहीं भी इन तर्कों का सीधा उत्तर नहीं देते — क्योंकि ऐसा करने से वे मानो अनुचित तर्क को ही मान्यता दे देते। मानसिक उथल-पुथल में डूबे अर्जुन की हर बात को एक अच्छे श्रोता की तरह सुनकर, फिर एक मानसिक रोगी को चिकित्सा देने जैसे ढंग से कृष्ण आगे बढ़ते हैं, यह हम देखेंगे।",
  "1.28": "अर्जुन उवाच — अर्जुन ने कहा:\n\nदृष्ट्वेमं स्वजनं कृष्ण युयुत्सुं समुपस्थितम् ।\n\nसीदन्ति मम गात्राणि मुखं च परिशुष्यति ।\n\nवेपथुश्च शरीरे मे रोमहर्षश्च जायते -- कृष्ण, युद्ध की इच्छा से यहाँ जुटे अपने इन लोगों को देखकर मेरे अंग शिथिल हो रहे हैं, मुख सूख रहा है, तथा शरीर में कँपकँपी और रोमांच हो रहा है।\n\n[बन्नंजे गोविंदाचार्य के भाष्य में श्लोक 1.28 और 1.29 को एक साथ व्याख्यायित किया गया है। व्याख्या इसी 1.28 श्लोक में समाहित है।]\n\nअर्जुन कहता है — 'यहाँ जुटे अपने वयोवृद्ध बंधुओं को देखकर मेरे अंग सिकुड़ रहे हैं। जो हमें परस्पर स्नेह से जीना चाहिए था, वे आज इस रणभूमि में आमने-सामने लड़ने को खड़े हैं — यह देखकर मेरा मुख लज्जा से मुरझा रहा है। समझदार होते हुए भी हम ऐसे घृणित कार्य में उतर आए! यह निर्णय हमने स्वयं लिया और उसी में बंधकर रणभूमि में खड़े हैं। अपने लोगों को देखकर शरीर सिकुड़ रहा है, मुख सूखकर बोल पाना भी कठिन हो रहा है। हम कितने नीचे गिर गए! यह सोचते ही कँपकँपी छूट रही है।' यहाँ अर्जुन के इस कथन में पहले करुणा, फिर लज्जा, फिर भय, फिर विस्मय — क्रमशः प्रकट होते हुए हम देखते हैं।",
  "1.29": "[बन्नंजे गोविंदाचार्य के भाष्य में श्लोक 1.28 और 1.29 को एक साथ व्याख्यायित किया गया है। व्याख्या इसी 1.28 श्लोक में समाहित है।]",
  "1.30": "गाण्डीवं स्रंसते हस्तात्त्वक्चैव परिदह्यते ।\n\nन च शक्नोम्यवस्थातुं भ्रमतीव च मे मनः -- गांडीव हाथ से गिरा जा रहा है, त्वचा भी जल रही है, मैं खड़ा भी नहीं रह पा रहा, और मेरा मन मानो भ्रमित हो रहा है।\n\nजब कोई व्यक्ति अपना आत्मविश्वास खो देता है, तो उसका आंतरिक अनुभव शरीर में किस प्रकार प्रकट होता है, यह यहाँ देखा जा सकता है। आत्मविश्वासहीन व्यक्ति अपनी मुट्ठी दृढ़ता से नहीं भींच सकता। अर्जुन की स्थिति भी वैसी ही हो गई है। वह कहता है — 'गांडीव मेरे हाथ से फिसल रहा है, पूरा शरीर जल रहा जैसा कष्ट हो रहा है।' यह भीतर के भाव, उथल-पुथल की अभिव्यक्ति है। एक बार मन अस्थिर हो जाए तो शरीर भी स्थिर नहीं रह सकता, और वैसे ही शरीर अस्थिर हो तो मन को स्थिर करना संभव नहीं। 'इस रथ में बैठना भी मुश्किल हो रहा है, मन भ्रमित हो रहा है' कहकर अर्जुन कृष्ण के सामने व्याकुल होता है।",
  "1.31": "निमित्तानि च पश्यामि विपरीतानि केशव ।\n\nन च श्रेयोऽनुपश्यामि हत्वा स्वजनमाहवे -- हे केशव, मुझे विपरीत शकुन ही दिखाई दे रहे हैं। युद्ध में अपने लोगों को मारकर भी कोई कल्याण मुझे नहीं दिखता।\n\n'निमित्त' का अर्थ है शकुन। यहाँ अर्जुन पहले देखे गए कुछ अपशकुनों को स्मरण करता है, जिन्हें उसने रणभूमि में आने से पहले ही देखा था, पर अब उसे यह याद आ रहा है।\n\nपुराने लोग शकुनों को बहुत महत्व देते थे। इस संसार में सब कुछ आपस में जुड़ा है — एक परमाणु से लेकर ब्रह्मांड तक सब कुछ गणितबद्ध है। इसी कारण जो भी घटित हो, उसे गणितबद्ध रूप से जाना जा सकता है — यही ज्योतिष, शकुन, पंचांग आदि हैं। यहाँ कुछ भी आकस्मिक नहीं है — केवल हमें न जानने के कारण वह आकस्मिक प्रतीत होता है।\n\nमहाभारत काल में देखे गए कुछ शकुन देखें — हाथी-घोड़े युद्ध से पहले आँसू बहाते थे, सियार सेना के इर्द-गिर्द रोते फिरते थे। पशुओं में रक्तपात और मृत्यु की पूर्वसूचना पाने की क्षमता होती है — आगे क्या होगा, वे यह सटीकता से भाँप सकते हैं। यह महाभारत युद्ध से पहले देखा गया एक शकुन था। इसके अतिरिक्त तेरह दिनों के अंतर में दो ग्रहण भी उसी काल में हुए — युद्ध आरंभ होने के पाँचवें दिन एक ग्रहण, फिर तेरह दिनों बाद दूसरा ग्रहण। यह मृत्युसूचक भीषण शकुन था, जिसे व्यास ने पहले ही धृतराष्ट्र को बता दिया था — 'लोक के लिए कंटक बने तुम्हारे पुत्र से लोक का नाश होगा' कहकर।\n\nइस प्रकार पूर्व में देखे शकुनों को स्मरण करते हुए अर्जुन कृष्ण को 'केशव' कहकर संबोधित करता है। आरंभ में उसने 'कृष्ण' कहकर संबोधित किया था, यह हमने देखा। कृष्ण का अर्थ है कृषि-ण — अर्थात भूमि को आनंद देने, बल भरने आया हुआ। केशव का अर्थ है का-ईश-व — यहाँ 'का' का अर्थ है सृष्टि के कारणभूत चतुर्मुख ब्रह्मा; 'ईश' का अर्थ है संहार के कारणभूत शंकर; केशव का अर्थ है सृष्टि-संहार दोनों की कारणभूत परम शक्ति।\n\nयहाँ अर्जुन कृष्ण को 'केशव' कहकर संबोधित करने का विशेष कारण है — 'भूमि को आनंद और बल देने उतरे हुए सृष्टिकर्ता तुम स्वयं ही संहारकारक बनकर, इस युगांत के महायुद्ध के सूत्रधार क्यों बने? तुम्हारा उद्देश्य क्या है?' — यही इस विशेषण के पीछे की ध्वनि है। महाभारत युद्ध के अठारहवें दिन द्वापरयुग समाप्त होकर कलियुग आरंभ हुआ था, यह भी यहाँ स्मरणीय है।\n\nयहाँ से आगे बढ़ते हुए अर्जुन अपने युद्ध न करने के कुछ कारण देने लगता है — 'नच श्रेयोऽनुपश्यामि हत्वा स्वजनमाहवे' — 'अपने बंधुओं को मारने से हमारा नाम इतिहास में, आने वाले युगों में प्रशंसनीय बना रहेगा, ऐसा मुझे किसी भी दृष्टि से नहीं लगता' — यह अर्जुन कहता है।",
  "1.32": "न काङ्क्षे विजयं कृष्ण न च राज्यं सुखानि च ।\n\nकिं नो राज्येन गोविन्द किं भोगैर्जीवितेन वा -- हे कृष्ण, मुझे न विजय चाहिए, न राज्य, न सुख। हे गोविंद, हमें राज्य से क्या, भोगों से या जीवन से भी क्या?\n\nअर्जुन धर्मराज के पक्ष में युद्ध के लिए खड़ा है। युद्ध रोकने या कोई निर्णय लेने का अंतिम अधिकार धर्मराज के विवेक पर ही निर्भर होना चाहिए। यहाँ अर्जुन मानो स्वयं ही निर्णायक हो, ऐसे बोलता है — 'किसे चाहिए यह विजय, हे कृष्ण? मुझे विजय नहीं चाहिए, गुरुजनों को मारकर विजय की कामना मुझे नहीं है' — यह वह कहता है। इस श्लोक में वह पुनः 'कृष्ण' कहकर संबोधित करता है — कृष्ण का अर्थ है आकर्षण करने वाला, अपने सौंदर्य से आकर्षित कर उत्कर्ष करने वाला। 'संसार की आकर्षण-शक्ति स्वरूप तुमने हमें, इस अठारह अक्षौहिणी सेना को, रणभूमि में क्यों खींच लाया?' — इसी भाव में अर्जुन बोल रहा है।\n\nआगे अर्जुन कहता है — 'हमें यह राज्य पाकर क्या करना है? यह राज्य पाकर, भोग पाकर क्या लाभ, हे गोविंद?' यहाँ वह भगवान को 'गोविंद' कहकर संबोधित करता है। गोविंद का अर्थ है वेदों द्वारा वाच्य, वेदों का समग्र अर्थ जानने वाला, भूमि पर अवतरित होने वाला, गायों की रक्षा करने वाला आदि। कृष्ण ने कितने ही दुष्ट राक्षसों और राजाओं का संहार किया, पर कहीं भी सिंहासन पर बैठकर राज्य नहीं किया — गोपालकों के साथ मिलकर गायों की रक्षा की। यहाँ अर्जुन यह कह रहा है कि 'तुम्हारी तरह मुझे भी किसी सिंहासन पर बैठने की इच्छा नहीं है। भूमि पर अवतरित होकर तुम मुझे युद्ध के लिए क्यों प्रेरित कर रहे हो?' — इसी भाव में उसने भगवान को 'गोविंद' कहकर संबोधित किया है।",
  "1.33": "येषामर्थे काङ्क्षितं नो राज्यं भोगाः सुखानि च ।\n\nत इमेऽवस्थिता युद्धे प्राणांस्त्यक्त्वा धनानि च -- जिनके लिए हम राज्य, भोग और सुख चाहते हैं, वे ही ये लोग प्राण और धन का मोह त्यागकर युद्ध में खड़े हैं।\n\n'यदि यह राजभोग चाहिए भी, तो किसके लिए? हमें अपने सभी गुरुजनों के बीच प्रसन्नता से रहना चाहिए। उन्हें मारकर हमें क्या प्रसन्नता मिलेगी? जिनके लिए हम इस जीवन का सुख, साम्राज्य चाहते हैं, वे सभी प्राण की चिंता छोड़कर, सर्वस्व खोने को तैयार होकर हमारे सामने युद्ध के लिए खड़े हैं।'",
  "1.34": "आचार्याः पितरः पुत्रास्तथैव च पितामहाः ।\n\nमातुलाः श्वशुराः पौत्राः श्यालाः सम्बन्धिनस्तथा -- आचार्य, पिता-तुल्य जन, पुत्र, तथा पितामह, मामा, श्वसुर, पौत्र, साले तथा अन्य संबंधी।\n\nअर्जुन अपने बंधुओं, परिवार के सदस्यों की सूची कृष्ण के सामने गिनाता है — गुरुजन, पिता-समान, पुत्र, पितामह, मामा, ससुर, पौत्र, पत्नी के भाई तथा अन्य संबंधी। इस प्रकार केवल अपने संबंधियों की सूची गिनाते हुए अर्जुन अपना सामाजिक कर्तव्य भूलकर पूर्णतः व्यक्तिगत स्तर पर बोल रहा है, यह यहाँ स्पष्ट हो जाता है।",
  "1.35": "एतान्न हन्तुमिच्छामि घ्नतोऽपि मधुसूदन ।\n\nअपि त्रैलोक्यराज्यस्य हेतोः किं नु महीकृते -- हे मधुसूदन, ये मुझे मारने आएँ तब भी मैं इन्हें मारना नहीं चाहता। त्रैलोक्य के राज्य के लिए भी नहीं, फिर भूमि के लिए तो क्या ही!\n\nमुझे इन्हें मारने की इच्छा नहीं है। यदि ये मुझे मारने आएँ तब भी मैं इन्हें नहीं मार सकता। पूरे ब्रह्मांड का स्वामित्व मिले तो भी मैं युद्ध नहीं करूँगा — फिर इस छोटी-सी भूमि के लिए युद्ध क्यों?\n\nयहाँ अर्जुन श्रीकृष्ण को 'मधुसूदन' कहकर संबोधित करता है। मधु का अर्थ है आनंद। मधुसूदन का अर्थ है — आनंद-नाशक — धर्म-मार्ग छोड़कर, अधर्मी होकर, मद (अहंकार) में चलने वालों के आनंद का नाश कर, सज्जनों का उद्धार करने वाला आनंद-स्वरूप भगवान। 'सात्त्विक जनों को आनंद देकर तामसिकों का आनंद हरने वाले तुम, यहाँ क्या करने आए हो?' — यही ध्वनि इस संबोधन में है। यहाँ 'युद्ध करना चाहिए या नहीं' यह असमंजस मुझे सता रहा है, ऐसा कहकर अर्जुन अपनी व्याकुलता कृष्ण के सामने व्यक्त करता है।",
  "1.36": "निहत्य धार्तराष्ट्रान्नः का प्रीतिः स्याज्जनार्दन ।\n\nपापमेवाश्रयेदस्मान्हत्वैतानाततायिनः -- धृतराष्ट्र-पुत्रों को मारकर हमें क्या प्रसन्नता होगी, हे जनार्दन? इन आततायियों को मारकर पाप ही हमें प्राप्त होगा।\n\n'धृतराष्ट्र-पुत्रों को मारकर हमें कौन-सा सुख मिलेगा, हे जनार्दन? इन कुलघातियों को मारने से हमें पाप ही लगेगा' — यह अर्जुन कहता है। यदि हम धार्तराष्ट्रों को मारते हैं तो हमें आनंद क्या मिलेगा? इससे मृत्यु तक निरंतर पाप-बोध हमें सताता रहेगा। इन्हें मारकर पाप-बोध के साथ जीना ही होगा, इसके अतिरिक्त कोई लाभ नहीं — यह अर्जुन का तर्क है।\n\nइस श्लोक में अर्जुन ने 'आततायी' शब्द का प्रयोग किया है। आततायी वह है जो दूसरे के घर में आग लगाए, दूसरे के भोजन में विष मिलाए, दूसरे की संपत्ति हड़पे, या पराई स्त्री पर हाथ डाले। शास्त्र कहता है — आततायी को देखते ही मार डालो। यहाँ दुर्योधन ने ये सभी बुरे कर्म किए थे — भीम को विष दिया, द्रौपदी का वस्त्र-हरण किया, पांडवों के लाक्षागृह में आग लगाई। फिर भी अर्जुन में बंधु-प्रेम इतना हावी है कि वह कहता है — 'ये आततायी होते हुए भी मेरे बड़े पिता के ही पुत्र नहीं हैं क्या?' — यह कृष्ण से कहकर व्याकुल होता है।\n\nइस श्लोक में अर्जुन श्रीकृष्ण को 'जनार्दन' कहकर संबोधित करता है। जनार्दन का अर्थ है — दुर्जनों का संहारक, तथा सज्जनों को पुनर्जन्म-रहित मोक्षदायी मृत्यु देने वाला। 'मोक्ष देने वाले तुम, फिर इस जन्म-मृत्यु के चक्र में डालने वाले युद्ध में हमें क्यों उलझा रहे हो? युद्ध कभी मोक्षदायी नहीं होता, वह सदा वैर-द्वेष से भरा होता है — फिर यह युद्ध क्यों?' — यही इस संबोधन के पीछे की ध्वनि है।",
  "1.37": "तस्मान्नार्हा वयं हन्तुं धार्तराष्ट्रान्स्वबान्धवान् ।\n\nस्वजनं हि कथं हत्वा सुखिनः स्याम माधव -- अतः अपने बांधव धृतराष्ट्र-पुत्रों को मारना हमें उचित नहीं। अपने ही लोगों को मारकर हम सुखी कैसे हो सकते हैं, हे माधव?\n\nधार्तराष्ट्र हमारे भाई हैं, उन्हें मारना उचित नहीं। अपने लोगों को मारकर हम कैसे सुखी हो सकते हैं — यह अर्जुन का प्रश्न है। सूक्ष्मता से देखने पर यहाँ स्पष्ट होता है कि अर्जुन यह पूर्णतः भूलकर बोल रहा है कि वह एक प्रजापालक है, और धर्म की रक्षा करना उसका कर्तव्य है।\n\nयहाँ अर्जुन कृष्ण को 'माधव' कहकर संबोधित करता है। 'मा' का अर्थ है माता लक्ष्मी, अतः माधव का अर्थ है लक्ष्मीपति भगवान। 'मा' का अर्थ ज्ञान भी है — भगवान ज्ञान के स्वामी हैं, इसलिए भी वे माधव हैं। श्रीकृष्ण मधुवंश में जन्म लेने के कारण भी माधव कहलाते हैं। वेद में 'मातृ' शब्द वाणी या वाङ्मय के अर्थ में प्रयुक्त हुआ है — समस्त वैदिक वाङ्मय के प्रतिपाद्य भगवान माधव हैं। अर्जुन के श्रीकृष्ण को इस प्रकार संबोधित करने का कारण है — कृष्ण केवल मामा के पुत्र नहीं, बल्कि कोई अतिमानवीय शक्ति हैं, यह सजगता उसमें थी। इसी कारण वह कभी एक प्रकार से, कभी दूसरे प्रकार से भगवान की उस अतिमानवीय शक्ति को स्मरण करता है। 'तुम इस जगत की आदिशक्ति हो, यह मुझे ज्ञात है। फिर भी इस समझौते में मूक दर्शक बनकर क्यों बैठे हो?' — यही इस संबोधन का तात्पर्य है।\n\nयह कितना विचित्र है! भगवान के साथ रहकर, कृष्ण को अतिमानवीय शक्ति जानने वाला महाज्ञानी अर्जुन भी हर क्षण दुविधा में पड़ जाता है। तो फिर हम-आप की क्या बिसात? यह विचित्र माया है — मिट्टी खाने वाले श्रीकृष्ण के मुख में भगवान का विश्वरूप देखने के बाद भी यशोदा उन्हें दंड देने को तत्पर हो जाती हैं, क्योंकि वे 'यह मेरा बालक है' इस ममता की माया में हैं। अर्जुन की स्थिति भी यही है।",
  "1.38": "यद्यप्येते न पश्यन्ति लोभोपहतचेतसः ।\n\nकुलक्षयकृतं दोषं मित्रद्रोहे च पातकम् -- यद्यपि लोभ से ग्रस्त हृदय वाले ये लोग कुलक्षय से होने वाले दोष तथा मित्र-द्रोह के पातक को नहीं देख पाते।\n\nधन के लोभ से अंधे होकर इनका मन सोचने की शक्ति खो चुका है। इससे कुलक्षय होगा, संपूर्ण भरतवंश निर्वंश हो जाएगा। बंधु होने के नाते हमें परस्पर मित्रवत् आत्मीयता से जीना चाहिए था, पर हम एक-दूसरे से द्वेष कर रहे हैं — यही द्रोह है।\n\nयहाँ 'मित्र' शब्द का प्रयोग हुआ है। सच्चा मित्र कौन है? जो हमें आने वाली विपत्ति का हमसे पहले ही अनुमान लगाकर, बिना किसी प्रतिफल की अपेक्षा के, प्राण के बदले प्राण दे दे — वही 'मित्र' है।",
  "1.39": "कथं न ज्ञेयमस्माभिः पापादस्मान्निवर्तितुम् ।\n\nकुलक्षयकृतं दोषं प्रपश्यद्भिर्जनार्दन -- हे जनार्दन, कुल-नाश से होने वाले दोष को स्पष्ट देखते हुए भी हमें यह क्यों न सूझे कि इस पाप से निवृत्त हो जाना चाहिए?\n\nऐसा महापाप नहीं करना चाहिए, यह यदि हम न समझें, तो दुर्योधन और हममें अंतर ही क्या रह जाता है? जन्म-मृत्यु के बंधन से मुक्त कराने वाले हे जनार्दन, कुल का नाश करने वाला दोष मुझे स्पष्ट दिखाई दे रहा है। युद्ध के बाद के भारत का चित्र मेरी आँखों में साकार हो रहा है। युद्ध से होने वाला अनिष्ट जानते हुए भी यदि हम युद्ध की ओर पैर बढ़ाने की बुद्धि दिखाएँ, तो क्या हम दुर्योधन जैसे नीच स्तर पर नहीं उतर जाते? यह अर्जुन का प्रश्न है।",
  "1.40": "कुलक्षये प्रणश्यन्ति कुलधर्माः सनातनाः ।\n\nधर्मे नष्टे कुलं कृत्स्नमधर्मोऽभिभवत्युत -- कुल के नष्ट होने पर सनातन कुलधर्म भी नष्ट हो जाते हैं; धर्म के नष्ट होने पर संपूर्ण कुल को अधर्म आ घेरता है।\n\nयुद्ध से होने वाली सबसे बड़ी समस्या है 'कुलधर्म' का नाश। इस श्लोक में अर्जुन धर्म से संबंधित कुछ शब्दों का प्रयोग करता है — जातिधर्म, कुलधर्म, सनातनधर्म आदि। इन्हें समझने के लिए पहले धर्म क्या है और उसके कितने प्रकार हैं, यह जानना आवश्यक है।\n\nजातिधर्म का अर्थ है हमारा सहज जन्मजात स्वभाव। प्रत्येक जीव का अपना विशिष्ट स्वभाव होता है, पर उसे पहचानना कठिन है क्योंकि उस पर दो आवरण चढ़े होते हैं — एक आनुवंशिक, दूसरा जिस वातावरण में हम पले-बढ़े उसका प्रभाव। ये दोनों वास्तविक स्वभाव को ढक देते हैं।\n\nकुलधर्म का अर्थ है समाजधर्म (Religion of Society)। हम अकेले, बिना दूसरों की सहायता के नहीं जी सकते, इसलिए संगठन के लिए एक पृथक धर्म है — व्यक्तिगत रुचि को समाजधर्म के लिए बदलना पड़ता है (उदाहरण के लिए ज़ोर से बोलना मेरा व्यक्तिगत स्वभाव है, पर अस्पताल में मौन रखना समाजधर्म है)। समाज बदलने के साथ यह भी बदलता रहता है — जैसे विवाह की उचित आयु काल के अनुसार बदलती रही है। वैदिक काल में गुरुकुल-पद्धति के कारण बाल-विवाह की प्रथा थी, पर रामायण-महाभारत काल तक ऐसा नहीं था; बाद में विदेशी आक्रमण के दबाव में यह प्रथा फिर आई — यह सामाजिक दबाव से हुआ परिवर्तन है।\n\nसनातनधर्म वह है जो हर काल में, हर स्थिति में कभी नहीं बदलता — जैसे ईमानदारी से जीना, दूसरे की वस्तु न चुराना, सत्य बोलना, ईश्वर पर श्रद्धा रखना। यह शाश्वत धर्म है।\n\nसनातन धर्म के अनुरूप ही सामाजिक धर्म को समायोजित करना चाहिए, और जातिधर्म को समाजधर्म के अनुरूप। किसी वस्तु का असाधारण गुण ही उसका धर्म है — जैसे देखना आँख का धर्म है, सुनना कान का। पर जो धर्म है वही सीमा लाँघने पर अधर्म बन जाता है — जो नहीं देखना चाहिए उसे देखना अधर्म है।\n\nयहाँ अर्जुन कहता है — 'कुल के नष्ट होने पर समाजधर्म चलाने वाली न्याय-व्यवस्था नष्ट होकर समाजधर्म ही नष्ट हो जाता है। सामाजिक व्यवस्था ढह जाती है, संपूर्ण समाज अधर्म में डूब जाता है — युद्ध करने से समाज को हम यही भेंट देंगे।'",
  "1.41": "अधर्माभिभवात्कृष्ण प्रदुष्यन्ति कुलस्त्रियः ।\n\nस्त्रीषु दुष्टासु वार्ष्णेय जायते वर्णसङ्करः -- हे कृष्ण, अधर्म के बढ़ने से कुल की स्त्रियाँ बिगड़ जाती हैं, और हे वार्ष्णेय, स्त्रियों के बिगड़ने पर वर्णसंकर उत्पन्न होता है।\n\nयुद्ध होने से सभी युवा मारे जाते हैं। अधर्म समाज पर आक्रमण करता है, युवाहीन समाज बन जाता है। सामाजिक रूप से स्त्री को सुरक्षा नहीं मिलती, जिसका परिणाम उसकी निर्दोषता का दुरुपयोग होता है, और इससे समाज में वर्णसंकर उत्पन्न होता है — यह अर्जुन कहता है।\n\nयहाँ वर्णसंकर का अर्थ है जीव के स्वभाव या रंग का बिगड़ जाना। शास्त्रों में उल्लेख है कि स्त्री को उसकी इच्छा के विरुद्ध बलपूर्वक उच्च शिक्षा नहीं देनी चाहिए, क्योंकि इसका प्रभाव उसके गर्भ पर पड़ता है, और उसका असर होने वाली संतान पर होता है। स्त्री जब अनिच्छा से स्वयं को उलझाती है, अनेक पुरुषों का संग करती है, तो आगे की संतान पर घोर दुष्प्रभाव पड़ता है — विक्षिप्त, किसी की बात न मानने वाली, किसी नियम के अधीन न रहने वाली संतान जन्म ले सकती है। यही यहाँ अर्जुन 'वर्णसंकर' कह रहा है।\n\nयहाँ अर्जुन कृष्ण को 'वार्ष्णेय' कहकर संबोधित करता है — यादव-कुल के वयोवृद्ध राजा वृष्णि के वंश में अवतरित होने के कारण कृष्ण वार्ष्णेय कहलाते हैं। इस नाम का उल्लेख वेद में भी है — इच्छित अभीष्ट देने वाली वरिष्ठ शक्तियों, देवताओं के स्वामी भगवान वार्ष्णेय हैं। 'सबकी अभीष्ट-पूर्ति करने वाले, धर्म-संस्थापन के लिए अवतरित हुए तुम, यह युद्ध क्यों नहीं रोक रहे' — यही ध्वनि इस संबोधन में है।",
  "1.42": "सङ्करो नरकायैव कुलघ्नानां कुलस्य च ।\n\nपतन्ति पितरो ह्येषां लुप्तपिण्डोदकक्रियाः -- यह वर्णसंकर, कुल का नाश करने वालों तथा कुल को ही नरक में ले जाने वाला है — इनके पितर पिंड-जल की क्रिया के बिना अधोगति को प्राप्त होते हैं।\n\nविक्षिप्त मन वाली संतानों के जन्म लेने से पूरा समाज नरक की ओर जाता है, और उसके कारणभूत हम भी नरक जाते हैं। समाज जब इस प्रकार संकीर्ण हो जाता है, सारी श्रद्धा खो देता है, तो पितर पिंड के बिना नरक में गिरते हैं — यह युद्धोत्तर परिणाम की भयावहता की अर्जुन की कल्पना है।\n\nयहाँ पिंड क्या है, उसका महत्व क्या है, वह किसे और कैसे पहुँचता है — यह समझ लें। हम जो स्थूल पिंड चढ़ाते हैं, वह सीधे मृत जीव तक नहीं पहुँचता। मृत्यु के बाद सूक्ष्म शरीर में स्थित जीव को स्थूल पिंड की आवश्यकता नहीं होती — जीव अपने कर्मानुसार जहाँ जाना है वहाँ जाता है। हम जो पिंड चढ़ाते हैं, वह पितृ-देवताओं के लिए होता है। यह एक देवगण है, जिसमें कुल सौ देवता हैं, उनमें तीन प्रमुख 'पितर' कहलाते हैं। जीवित काल में जैसे हम तत्त्वाभिमानी देवताओं की पूजा करते हैं, वैसे ही मृत्यु के बाद, इस स्थूल शरीर से बाहर आने पर, जीव की रक्षा करने वाला देवगण ही पितृगण है। इन पितरों को वसु-रुद्र-आदित्य नियंत्रित करते हैं। हमारे पूर्वजों की पुण्यतिथि पर इन पितृ-देवताओं की आराधना करना परंपरा है। पितरों को पिंड अर्पित करने का कारण यह है कि यदि किसी विशेष कारण से हमारे पूर्वजों के मार्ग में कोई बाधा हो, तो उसे दूर करने की प्रार्थना ही पिंडदान है — 'प्रारब्ध कर्म से उनकी रक्षा करें' यही पितृ-देवताओं की पूजा है। कौआ का पिंड को छूना, पितृ-देवताओं द्वारा हमारी पूजा स्वीकार किए जाने का शकुन-संकेत माना जाता है।",
  "1.43": "दोषैरेतैः कुलघ्नानां वर्णसङ्करकारकैः ।\n\nउत्साद्यन्ते जातिधर्माः कुलधर्माश्च शाश्वताः -- वर्णसंकर उत्पन्न करने वाले कुल-घातियों के इन्हीं दोषों से सहज जातिधर्म तथा शाश्वत कुलधर्म नष्ट हो जाते हैं।\n\nयुद्ध से समाज पर सीधा प्रभाव यह पड़ता है — नेतृत्वहीन, युवाहीन समाज; स्त्री-पुरुष का अनुपात बिगड़ जाना। यह ठीक होने में कितने वर्ष लगेंगे? महाभारत युद्ध में कम से कम पचास लाख लोग मारे गए थे। ऐसे महायुद्ध से पूरे समाज का विनाश करने वाले कुल-कंटक हम बन जाएँगे — यही अर्जुन की व्यथा है। 'सामाजिक व्यवस्था के नष्ट होने से स्वभाव नष्ट होता है, इससे प्रत्येक जीव के स्वभाव का विकास नहीं होता, व्यक्तित्व-विकास नष्ट होता है। शाश्वत मूल्यों वाला समाजधर्म नष्ट होता है। अनादिकाल से समाज द्वारा स्वीकृत स्थिर धर्म बह जाता है' — यह अर्जुन कृष्ण के सामने अपना तर्क प्रस्तुत करता है।",
  "1.44": "उत्सन्नकुलधर्माणां मनुष्याणां जनार्दन ।\n\nनरके नियतं वासो भवतीत्यनुशुश्रुम -- हे जनार्दन, कुलधर्म से भ्रष्ट हुए मनुष्यों का नरक में ही निश्चित निवास होता है, ऐसा हमने सुना है।\n\nइस लोक में भी नरक, परलोक में भी नरक — इस प्रकार जन्म भर नरक में ही रहना पड़ता है, ऐसा जानकार लोग कहते हैं, यह मैंने सुनकर जाना है। इस प्रकार इहलोक और परलोक दोनों को नरक बनाने के लिए हम स्वयं ही कारण बनते हैं।",
  "1.45": "अहो बत महत्पापं कर्तुं व्यवसिता वयम् ।\n\nयद्राज्यसुखलोभेन हन्तुं स्वजनमुद्यताः -- हाय! कितना बड़ा पाप करने पर हम उतारू हो गए हैं, कि राज्य-सुख के लोभ में अपने ही स्वजनों को मारने को तत्पर हैं!\n\nयहाँ अर्जुन ढहते हुए स्वर में कहता है — 'हाय, कितनी बड़ी विपत्ति, कितना बड़ा पाप-कार्य हमारे सामने घटित हो रहा था? कितनी बड़ी भूल हो जाती! हम एक बड़ा अपराध करने को हाथ बढ़ा रहे थे। राज्य-सुख के लोभ में अपने ही लोगों को मारकर पूरे कुल को अधःपतन में धकेलने का काम हमसे होने जा रहा था' — यह कहता है।",
  "1.46": "यदि मामप्रतीकारमशस्त्रं शस्त्रपाणयः ।\n\nधार्तराष्ट्रा रणे हन्युस्तन्मे क्षेमतरं भवेत् -- यदि निःशस्त्र और प्रतिकार न करने वाले मुझे शस्त्रधारी धृतराष्ट्र-पुत्र रणभूमि में मार डालें, तो वह भी मेरे लिए अधिक श्रेयस्कर होगा।\n\n'मैं प्रतिकार ही नहीं करूँगा। यदि वे मुझे मारने आएँ तो भी मैं पलटकर वार नहीं करूँगा। हाथ में शस्त्र लेकर वे मुझे मार डालें तो वह मेरा सौभाग्य समझकर मैं मर जाऊँगा। ऐसा दुःखद दृश्य देखकर जीना ही क्यों? कुछ भी हो, मुझे युद्ध नहीं चाहिए' — कहकर अर्जुन हाथ खड़े कर देता है।\n\nयुद्ध के आरंभ में 'सेनयोरुभयोर्मध्ये रथं स्थापय मेऽच्युत' कहकर दर्प से बोलने वाला अर्जुन, क्षण भर में ही पूर्णतः पिघल गया। यह उसकी सुप्त-प्रज्ञा में बिना उसकी जानकारी के छिपा हुआ भाव था। कृष्ण ने अपनी मनोवैज्ञानिक चिकित्सा से इसे पूर्णतः बाहर ला दिया। मानसिक संघर्ष से ग्रस्त व्यक्ति के लिए यही प्रथम चिकित्सा है। मनुष्य के मनोरोग को कैसे ठीक किया जा सकता है, यह संसार को दिखाने वाले प्रथम महान मनोवैज्ञानिक स्वयं कृष्ण ही हैं। यदि कृष्ण अर्जुन के आत्मीय-जनों के सामने रथ खड़ा न करते, तो ये सारे विचार उसके मन से बाहर ही न आते। श्रीकृष्ण की यह मानसिक चिकित्सा तत्त्वशास्त्र के साथ मनोविज्ञान को समझकर विश्लेषित करने पर ही हमें समझ में आती है।",
  "1.47": "सञ्जय उवाच — संजय ने कहा:\n\nएवमुक्त्वार्जुनः सङ्ख्ये रथोपस्थ उपाविशत् ।\n\nविसृज्य सशरं चापं शोकसंविग्नमानसः -- ऐसा कहकर अर्जुन युद्ध-भूमि में शर-सहित धनुष को त्यागकर, शोक से व्याकुल मन से रथ के मध्य बैठ गया।\n\nरथ में खड़े होकर इतना कहने वाला अर्जुन, रथ के बीचोबीच ढहकर बैठ गया। अपने सभी शस्त्रास्त्र नीचे छोड़कर, हाथ खड़े करके बैठ गया।\n\nइस अध्याय में अर्जुन ने अपने सारे भाव कृष्ण के सामने खोलकर रख दिए हैं। अर्जुन ने जो कुछ भी कहा, वह हमें ज्ञात विषय है, पर आगे कृष्ण जो कहने वाले हैं, वह हमारे लिए अज्ञात है। अंधकार से प्रकाश की ओर ले जाने वाले भगवान के उत्तर को हम आगे के अध्यायों में देखेंगे।\n\nअगले अध्याय में जाने से पहले एक छोटा विश्लेषण। हम में से बहुतों को एक संशय रहता है — रणभूमि में कृष्ण और अर्जुन ने यह सात सौ श्लोकों वाला संवाद कैसे किया? क्या उनके पास इतना समय था? इस प्रश्न का उत्तर पाने के लिए पहले हमें महाभारत-कालीन युद्ध-पद्धति जाननी होगी। उस समय के युद्ध-नियम के अनुसार, प्रतिद्वंद्वी तैयार न हो तो उस पर आक्रमण नहीं किया जा सकता था। एक पक्ष पूरी तरह सज्ज हुए बिना युद्ध आरंभ नहीं होता था। फिर उनका संवाद कितनी देर चला, यह प्रश्न है। अर्जुन उस काल के महामेधावियों में से एक था। यहाँ संवाद दो मेधावियों के बीच हो रहा है — उस स्तर का ज्ञान आज हमारे लिए कल्पना करना भी कठिन है। उनका संपूर्ण संवाद आज दिखने वाले इन सात सौ श्लोकों के रूप में नहीं हुआ था — वेदव्यास ने उस संवाद को हमारे लिए समझने योग्य बनाकर सात सौ श्लोकों के रूप में प्रस्तुत किया, बस इतना ही। आज भी यह श्लोक हमें समझ में नहीं आता, इसीलिए गीता के भाष्य हज़ारों पृष्ठों में मिलते हैं। पर महामेधावी इसे अत्यंत संक्षेप में, अत्यंत कम समय में कह और समझ सकते हैं। कृष्ण-अर्जुन का संवाद भी ऐसा ही विषय-गर्भित संक्षिप्त संवाद था।\n\nएक अन्य महत्वपूर्ण प्रश्न — गीता कृष्ण ने अर्जुन को ही क्यों सुनाई? उसके बड़े भाई भीम या अन्य किसी को क्यों नहीं? इसका उत्तर बहुत सरल है — रोग जिसे हो, दवा उसी को दी जाती है, दूसरों को नहीं। वहाँ मानसिक उथल-पुथल में केवल अर्जुन ही था। इसीलिए श्रीकृष्ण ने अर्जुन को (उसके माध्यम से हम सबको) गीता का उपदेश दिया।",
  "2.1": "सञ्जय उवाच — संजय ने कहा:\n\nतं तथा कृपयाविष्टमश्रुपूर्णाकुलेक्षणम् ।\n\nविषीदन्तमिदं वाक्यमुवाच मधुसूदनः -- करुणा से आविष्ट, आँसुओं से भरी व्याकुल दृष्टि वाले, विषाद में डूबे उसे देखकर मधुसूदन ने यह वचन कहा।\n\nकरुणा से अभिभूत, आँसुओं से भरी और व्याकुल आँखों वाले, शोक में डूबे अर्जुन को देखकर, मधुसूदन (श्रीकृष्ण) ने ये वचन कहे — ऐसा संजय कहते हैं।",
  "2.2": "भगवानुवाच — भगवान ने कहा:\n\nकुतस्त्वा कश्मलमिदं विषमे समुपस्थितम् ।\n\nअनार्यजुष्टमस्वर्ग्यमकीर्तिकरमर्जुन -- अर्जुन, ऐसे संकट में, अनार्यों द्वारा सेवित, स्वर्ग के अयोग्य, अपकीर्तिकारक यह मैल तुझ पर कहाँ से आ पड़ा?\n\n\"यह बुद्धि तुझमें कहाँ से आई? यह भौतिक मैल तुझमें कैसे चिपक गया? ऐसी आपातस्थिति में, जब तुझे तुरंत कार्यरत होना चाहिए, इस क्षण यह कैसा गंदा विचार? आर्य कहलाने वाला कोई भी व्यक्ति कभी ऐसा नहीं सोचता। ऐसे विचार से न परलोक में स्वर्ग मिलता है, न इस लोक में कीर्ति। ज्ञानी, विद्वान, वयोवृद्ध जन कभी ऐसा नहीं सोचते\" — इन कठोर शब्दों से कृष्ण ने अर्जुन के संपूर्ण तर्क को एक ही वाक्य में ध्वस्त कर दिया। यहाँ प्रयुक्त 'आर्य' शब्द किसी जाति-विशेष का वाचक नहीं है। आर्य का अर्थ है — समझदार, वयोवृद्ध ज्ञानी, आदरणीय जन। कन्नड़ में 'अय्या' शब्द का भी यही अर्थ है।",
  "2.3": "क्लैब्यं मा स्म गमः पार्थ नैतत्त्वय्युपपद्यते ।\n\nक्षुद्रं हृदयदौर्बल्यं त्यक्त्वोत्तिष्ठ परन्तप -- हे पार्थ, कायरता मत अपनाओ, यह तुझे शोभा नहीं देता। हे परंतप, हृदय की इस क्षुद्र दुर्बलता को त्यागकर उठ खड़ा हो।\n\n\"नपुंसक की तरह बात मत करो। अर्जुन में ऐसी कायरता मुझे अपेक्षित नहीं थी। ऐसी क्षुद्र मानसिक दुर्बलता को त्यागकर, वीर बनकर अन्याय के विरुद्ध लड़ो\" — यह कहकर कृष्ण अर्जुन को चौंकाने वाली एक झटकेदार चिकित्सा (Shock Treatment) देते हैं।\n\nकृष्ण ने ऐसा क्यों कहा? क्या वे युद्ध और रक्तपात चाहते थे? ऐसे प्रश्न हमारे मन में उठना स्वाभाविक है। यहाँ सूक्ष्मता से देखें — यदि युद्ध न होता, तो अर्जुन ने जिस सामाजिक हानि की आशंका जताई थी, उससे दस गुना अधिक अन्याय हुआ होता। दुर्योधन उस काल का महान लोक-कंटक था — भरी सभा में अपनी ही भाभी का अपमान करने को उद्यत हुआ व्यक्ति। ऐसा व्यक्ति यदि राजगद्दी पर बैठता, तो समाज की क्या दशा होती, यह सोचिए। यहाँ कृष्ण की चिंता यह है कि इस देश का नेतृत्व आगे किसके हाथ में जाना चाहिए — बंधु-प्रेम नहीं। जीतने-हारने से अधिक महत्वपूर्ण है अन्याय के विरुद्ध आवाज़ उठाना। अन्याय से लड़ते हुए मर जाना भी कोई हानि नहीं, पर उसके विरुद्ध डटकर खड़ा होना ही चाहिए — यही कृष्ण का संदेश है।\n\nमहाभारत के माध्यम से श्रीकृष्ण ने हमें धर्म का एक नया सिद्धांत दिया। महाभारत से पहले धर्म की कल्पना कुछ और ही थी। उदाहरण के लिए सत्य बोलना — जो जैसा है वैसा ही कहना सत्य माना जाता था। पर कृष्ण के अनुसार — जिस असत्य से समाज का हित होता है, वही सत्य है; जिस सत्य से समाज की हानि होती है, वही असत्य है। इसी तरह हिंसा — यदि एक हिंसा से अनेक अहिंसा संभव हों, तो वह स्वयं अहिंसा ही है। उदाहरण के लिए, यदि कोई नरभक्षी बाघ प्रतिदिन गाँव पर आक्रमण कर एक-एक व्यक्ति को खा जाए, तो उसे मार डालना पशु-हिंसा नहीं है। यदि एक युद्ध से पीढ़ियों तक अहिंसा स्थापित हो सके, तो ऐसा युद्ध करने में कोई दोष नहीं। जिससे सज्जनों की रक्षा हो, वही सत्य है। धर्म में भाव ही मुख्य है — हम किस उद्देश्य के लिए लड़ रहे हैं, यही महत्वपूर्ण है।",
  "2.4": "अर्जुन उवाच — अर्जुन ने कहा:\n\nकथं भीष्ममहं सङ्ख्ये द्रोणं च मधुसूदन ।\n\nइषुभिः प्रतियोत्स्यामि पूजार्हावरिसूदन -- हे मधुसूदन, अरिसूदन, पूजनीय भीष्म और द्रोण से युद्ध में मैं बाणों से कैसे लड़ूँगा?\n\nकृष्ण के तीखे उत्तर और उनके मुस्कुराते मुख को देखकर अर्जुन के बोलने का ढंग अब बदल जाता है। भावावेश छोड़कर वह अब भावुकता से शरणागति की ओर मुड़ने लगता है।\n\nअर्जुन कहता है — \"मेरी आँखों के सामने खड़े भीष्माचार्य और द्रोणाचार्य का मैं कैसे सामना करूँ? एक हमारे वंश के मूल-पुरुष राजर्षि हैं; दूसरे सभी क्षत्रियों को विद्या देने वाले महर्षि हैं। ऐसे पूजनीय महानुभावों पर मैं बाण कैसे चलाऊँ? सृष्टि के आरंभ में मधु-कैटभ का संहार करने वाले हे मधुसूदन, दुष्टों के संहार के लिए अवतरित हुए हे अरिसूदन, ज्ञानियों और आचार्यों की हत्या तुम्हारा मूल उद्देश्य नहीं हो सकता\" — इस बदले हुए स्वर में अर्जुन अपनी बात आगे बढ़ाता है।",
  "2.5": "गुरूनहत्वा हि महानुभावाञ्छ्रेयो भोक्तुं भैक्ष्यमपीह लोके ।\n\nहत्वार्थकामांस्तु गुरूनिहैव भुञ्जीय भोगान्रुधिरप्रदिग्धान् -- इन महानुभावों को मारने के बजाय इसी लोक में भिक्षा माँगकर जीवन बिताना अच्छा है। धन-कामना से भरे गुरुजनों को मारकर, यहीं रक्त से सने भोगों को भोगना पड़ेगा।\n\nगुरुजनों को मारकर वैभव भोगने से बेहतर नहीं है भिक्षा माँगकर जीना? जो सिंहासन भीष्म-द्रोण जैसे, अपने भीतर के सत्य को साक्षात्कार कर चुके महानुभावों को मारे बिना नहीं पाया जा सकता, ऐसा सिंहासन हमें क्यों चाहिए?\n\nदुर्योधन के वेतनभोगी सेवक बनकर, राजमहल के ऋण के कारण युद्ध में खड़े हुए इन्हें मारकर सिंहासन पर बैठें, तो यह गुरुजनों के रक्त से सने भोग को भोगने जैसा ही होगा।",
  "2.6": "न चैतद्विद्मः कतरन्नो गरीयो यद्वा जयेम यदि वा नो जयेयुः ।\n\nयानेव हत्वा न जिजीविषामस्तेऽवस्थिताः प्रमुखे धार्तराष्ट्राः -- यह भी नहीं जानते कि हमारे लिए क्या बेहतर है — हमारा जीतना, या उनका हमें जीतना। जिन्हें मारकर हम जीना भी नहीं चाहते, वे ही धृतराष्ट्र-पुत्र हमारे सामने खड़े हैं।\n\nअब तक अपना ही तर्क प्रस्तुत करने वाला अर्जुन अब कृष्ण की शरण में जाकर पूछता है कि उसके लिए क्या भला है। \"हमें युद्ध में विजय पाने में कल्याण है, या गुरुजनों की विजय में — यह मुझे समझ नहीं आ रहा। युद्ध जीतने की इच्छा भी मुझमें नहीं रही\" — यह कहकर अर्जुन अपने मन की दुविधा कृष्ण के सामने खोलकर रख देता है। पिता-समान धृतराष्ट्र, और उनके पुत्र हमारे सामने युद्ध के लिए खड़े हैं। जिनके पुत्रों के लिए हम प्राण तक त्याग दें, ऐसे अपने बड़े पिता के विरुद्ध लड़ने की इच्छा नहीं है, यह अर्जुन कहता है।",
  "2.7": "कार्पण्यदोषोपहतस्वभावः पृच्छामि त्वां धर्मसम्मूढचेताः ।\n\nयच्छ्रेयः स्यान्निश्चितं ब्रूहि तन्मे शिष्यस्तेऽहं शाधि मां त्वां प्रपन्नम् -- कायरता के दोष से मेरा स्वभाव क्षीण हो गया है, धर्म के विषय में मन भ्रमित हो गया है। मुझे निश्चित रूप से बताओ जो कल्याणकारी हो — मैं तुम्हारा शिष्य हूँ, तुम्हारी शरण में आए मुझे मार्ग दिखाओ।\n\n\"मुझमें कायरता का दोष आ गया है। क्या उचित है और क्या अनुचित, यह निर्णय न कर पाने की दयनीय स्थिति में हूँ। धर्म को लेकर मेरी सोचने की शक्ति उलझन का घर बन गई है। युद्ध करना चाहिए या नहीं, यह दुविधा मुझे सता रही है। मेरे लिए क्या हितकर है, यह नहीं जानता। तुम्हारा शिष्य बनकर तुम्हारी शरण में आया हूँ — मुझे मार्गदर्शन दो\" — यह अर्जुन कृष्ण से प्रार्थना करता है। अब तक भगवान के सामने पंडित की तरह बोलने वाला अर्जुन अब भगवान से शरणागति माँग रहा है, यह यहाँ स्पष्ट दिखता है।",
  "2.8": "न हि प्रपश्यामि ममापनुद्याद्यच्छोकमुच्छोषणमिन्द्रियाणाम् ।\n\nअवाप्य भूमावसपत्नमृद्धं राज्यं सुराणामपि चाधिपत्यम् -- मेरी इंद्रियों को सुखा देने वाले इस शोक को दूर करने का मुझे कोई उपाय नहीं दिखता — भूमि पर निष्कंटक समृद्ध राज्य पाकर, या देवताओं का आधिपत्य पाकर भी।\n\n\"मेरी इंद्रियाँ क्षीण हुई जा रही हैं। मेरे दुःख को दूर करने का मार्ग मुझे नहीं दिखता। पृथ्वी पर या स्वर्ग में प्रभुत्व पाकर भी मैं यह दुःख दूर नहीं कर सकूँगा\" — यह अर्जुन कहता है।",
  "2.9": "सञ्जय उवाच — संजय ने कहा:\n\nएवमुक्त्वा हृषीकेशं गुडाकेशः परन्तपः ।\n\nन योत्स्य इति गोविन्दमुक्त्वा तूष्णीं बभूव ह -- इस प्रकार कहकर, शत्रु-तापक गुडाकेश (अर्जुन) ने हृषीकेश गोविंद से 'मैं युद्ध नहीं करूँगा' कहकर मौन धारण कर लिया।\n\nसंजय, रणभूमि में अर्जुन की स्थिति धृतराष्ट्र को वर्णन करते हुए कहते हैं — \"संपूर्ण ब्रह्मांड में व्याप्त, हमारी इंद्रियों के स्वामी गोविंद के सामने, निद्रा को जीतने वाला अर्जुन 'मैं युद्ध नहीं करूँगा' कहकर मौन हो गया।\"",
  "2.10": "तमुवाच हृषीकेशः प्रहसन्निव भारत ।\n\nसेनयोरुभयोर्मध्ये विषीदन्तमिदं वचः -- हे भारत, दोनों सेनाओं के बीच विषाद में डूबे उस अर्जुन से हृषीकेश ने मंद मुस्कुराते हुए यह वचन कहा।\n\nअर्जुन जब पूर्णतः शरण होकर अपने सामने गिड़गिड़ाते हुए खड़ा हुआ, तब श्रीकृष्ण मंद मुस्कुराते हुए अपनी बात आरंभ करते हैं। यहाँ अर्जुन कृष्ण की बात स्वीकार करने की स्थिति में पहुँच चुका है — उसका भावावेश जा चुका है, शरणागति आ चुकी है। भगवान यदि हमें मार्गदर्शन देना चाहें, तो हमें अपना अहंकार त्यागकर उनकी पूर्ण शरण में जाना होगा। तभी हमें निश्चित रूप से मार्गदर्शन मिलता है। यहाँ कृष्ण अर्जुन को जो उपदेश देते हैं, वह हम सबके लिए दिया गया उपदेश है — यह बात मन में रखकर आइए कृष्ण का उपदेश सुनें।",
  "2.11": "भगवानुवाच -- भगवान ने कहा:\n\nअशोच्यानन्वशोचस्त्वं प्रज्ञावादांश्च भाषसे ।\n\nगतासूनगतासूंश्च नानुशोचन्ति पण्डिताः -- तुम उनके लिए शोक कर रहे हो जिनके लिए शोक नहीं करना चाहिए, और जैसा सूझे वैसे ज्ञानियों जैसी बातें बोल रहे हो। ज्ञानी न तो मृतकों के लिए शोक करते हैं, न जीवितों के लिए।\n\nयह भगवान के उपदेश का पहला वचन है, जो सम्पूर्ण गीता के लिए बीजरूप है। यहाँ कृष्ण अर्जुन से कहते हैं: 'जिनके लिए शोक नहीं करना चाहिए, तुम उनके लिए शोक कर रहे हो, और बड़े ज्ञानी की तरह बातें कर रहे हो।' यह अर्जुन की दुर्बलता के सामने कृष्ण द्वारा रखा गया दर्पण है। यहाँ 'तुम्हें कुछ भी नहीं मालूम' का भाव भी स्पष्ट है। अर्जुन को जो सता रहा है वह यह भय है कि कुछ लोग (गुरुजन-बड़े) मरेंगे और कुछ लोग (दुष्ट) जीवित रहेंगे — इसी से दुःख होता है। दुःख का मूल भय है, भय का मूल अज्ञान है।\n\nयहाँ यह प्रश्न उठ सकता है — यदि भीष्म-द्रोण जैसे महात्मा मरें तो क्या रोना गलत है? इस प्रश्न का उत्तर तभी मिलता है जब हम जन्म-मृत्यु का रहस्य जान लें। जीव अनादि-नित्य है, उसकी कभी मृत्यु नहीं होती। यह भौतिक शरीर जीव के लिए एक पिंजरे के समान है। इस पिंजरे में फँसना जन्म है, पिंजरे से बाहर जाना मृत्यु है। इस दृष्टि से देखें तो नया वस्त्र पहनना जन्म है, पुराना वस्त्र त्यागना मृत्यु है। यह ज्ञान होने पर मृत्यु का भय नहीं रहता।\n\nयहाँ कृष्ण कहते हैं: 'ज्ञानी जो बात कहते हैं वह तुम नहीं कह रहे' — क्योंकि ज्ञानी जन्म-मृत्यु के रहस्य को भली-भाँति जानते हैं। तुम जो बोल रहे हो वह समझदारी की बात नहीं है। कृष्ण कहते हैं कि तुम इस भ्रम से बोल रहे हो कि तुम्हारी समझ ही विश्व का सत्य है।\n\nयहाँ कृष्ण अर्जुन के सभी लौकिक प्रश्नों को छोड़कर उसे सत्य का साक्षात्कार करा रहे हैं। अर्जुन ने जो देखा वह केवल ऐहिक संसार है, कृष्ण उसे उससे परे सत्य का दूसरा पक्ष परिचित करा रहे हैं।\n\nमृत्यु भयानक नहीं है — जो जन्मा है उसकी मृत्यु अनिवार्य है। आत्मा की कभी मृत्यु नहीं होती, आत्मा अनादि-नित्य है। परन्तु देह का नाश अनिवार्य है। मनुष्य का अपनी विकृति से प्रकृति की ओर यात्रा करना ही मृत्यु है। इसलिए मृतकों के लिए हो या जीवितों के लिए, ज्ञानी शोक नहीं करते — यही बात कृष्ण यहाँ अर्जुन को समझा रहे हैं।",
  "2.12": "न त्वेवाहं जातु नासं न त्वं नेमे जनाधिपाः ।\n\nन चैव न भविष्यामः सर्वे वयमतः परम् -- ऐसा कभी नहीं था कि मैं न रहा होऊँ, न तुम, न ये सब राजा। और आगे भी हम सब कभी नहीं रहेंगे, ऐसा नहीं होगा।\n\nकृष्ण यहाँ पहले कहे गए इस वचन के समर्थन में कि मृत्यु के विषय में हमें चिंता क्यों नहीं करनी चाहिए, इसे पुष्ट करने वाली बात कहते हैं। वे कहते हैं: 'मैं-तुम और ये सब राजा, पहले भी थे, आज भी हैं, और आगे भी रहेंगे। देह का नाश होने पर जीव का नाश नहीं होता। जैसे मैं अनादि-नित्य हूँ वैसे ही प्रत्येक जीव भी अनादि-नित्य है। आत्मा को मारना असम्भव है।' अनंत जीव का विस्तार अनंत काल तक निरंतर बना रहता है। आत्मा सदा अजर-अमर है। प्रत्येक जीव का अपना ही स्वभाव है। जीव एक बीज के समान है, भगवान एक माली के समान हैं। उन्होंने इस संसाररूपी बगीचे की सृष्टि करके इस जीव को उस बगीचे में बोकर उसे अस्तित्व दिया। प्रत्येक जीव अपने स्वभाव के अनुसार इस संसार में बढ़ता है। एक जीव का स्वभाव दूसरे जीव के स्वभाव से भिन्न है। इसी कारण यह संसार इतना विविधतापूर्ण है।",
  "2.13": "देहिनोऽस्मिन् यथा देहे कौमारं यौवनं जरा ।\n\nतथा देहान्तरप्राप्तिर्धीरस्तत्र न मुह्यति -- देह में रहने वाले जीव के लिए जैसे इसी देह में बचपन, जवानी, बुढ़ापा होता है, वैसे ही देह का बदलना भी है। ऐसी स्थिति में धीर पुरुष विचलित नहीं होता।\n\nदेह का नाश स्वरूप का नाश नहीं है। इस देह में रहने वाला जीव प्रतिक्षण अपने देह के परिवर्तन का अनुभव करता रहता है। बचपन का देह जवानी में नहीं है, जवानी का देह बुढ़ापे में नहीं है। मरने के बाद फिर से पुनर्जन्म के साथ नया देह मिलता है। परन्तु हमें यह ज्ञान नहीं है कि हम कहाँ से आए और कहाँ जा रहे हैं। हमें केवल अपने वर्तमान अस्तित्व का ज्ञान है। देह नष्ट होकर नया देह आ सकता है, परन्तु जो कभी नष्ट नहीं होता वह चैतन्य ही यह 'जीव' है। एक दिन नष्ट होने वाले इस देह के विषय में धीर पुरुष कभी शोक नहीं करता, ऐसा कृष्ण कहते हैं। यहाँ धीर का अर्थ है बोध के आनंद का अनुभव करने वाला ज्ञानी (धी+रः)। जहाँ ज्ञान है वहाँ दुःख नहीं है।",
  "2.14": "मात्रास्पर्शास्तु कौन्तेय शीतोष्णसुखदुःखदाः ।\n\nआगमापायिनोऽनित्यास्तांस्तितिक्षस्व भारत -- हे कौन्तेय, विषयों का सम्पर्क ही सर्दी-गर्मी का, सुख-दुःख का अनुभव देने वाला है। ये आते-जाते रहते हैं, स्थायी नहीं हैं। हे भारत, इन्हें सहन करो।\n\nहम बचपन का देह छोड़कर जवानी का देह पाते हैं। जवानी का देह छोड़कर बुढ़ापे का देह पाते हैं। इस कारण कोई दुःखी नहीं होता। परन्तु मृत्यु में 'दिखने वाला' दूसरा देह समाप्त हो जाता है — तब दुःख होता है। जिस देह के माध्यम से हमने स्नेह का नाता जोड़ा होता है, वह न रहेगा — यह दुःख सामान्यतः हमें सताता है।\n\nजीवन में हम जो सुख-दुःख अनुभव करते हैं उसका मूल 'मात्रा-स्पर्श' है। यह सबका मूल है। हम अपनी इंद्रियों के माध्यम से जो ग्रहण करते हैं वह मात्रा है। शब्द, स्पर्श, रूप, रस, गंध — ये ही हमारे सुख-दुःख के कारणभूत पाँच मात्राएँ हैं।\n\nसुख-दुःख की कोई व्यवस्था नहीं है। एक के लिए सुखद जो है वह दूसरे के लिए दुःखद हो सकता है। विषयों के स्पर्श से सुख-दुःख आता है — यह सर्दी-गर्मी जैसा है। पहले सुख देने वाली वस्तु ही आगे दुःख में परिणत हो सकती है। सुख-दुःख जीव का धर्म नहीं है। यह आने-जाने वाला है। यह हमारी मानसिक कल्पना का फल है। 'मेरा' यह भाव ही दुःख का मूल कारण है। नींद में हमें 'मेरा' यह भाव नहीं रहता, इसलिए नींद में कभी दुःख नहीं होता। यह समस्या केवल जाग्रत और स्वप्न में है। नींद में सब कुछ निर्मल है।\n\nहम स्वयं अपनी मानसिक भावनाओं और अनुभवों से इस सुख-दुःख का निर्माण करते हैं। इससे पार पाने का उपाय हमें स्वयं सीखना होगा। दुःख के मूल की खोज करने पर दुःख सह्य हो जाता है। हमें अपनी भावनाओं को सहन करना सीखना चाहिए। जो आया उसे स्वीकार करना सीखना चाहिए। मुझे 'वही चाहिए', 'ऐसा ही होना चाहिए' — यह सोच ही दुःख का मूल कारण है। जो आया उसका सामना जैसे आया वैसे करूँगा, यह आत्मस्थैर्य हो तो दुःख नहीं रहता।",
  "2.15": "यं हि न व्यथयन्त्येते पुरुषं पुरुषर्षभ ।\n\nसमदुःखसुखं धीरं सोऽमृतत्वाय कल्पते -- हे पुरुषश्रेष्ठ, जिस पुरुष को ये [इन्द्रिय-सम्पर्क] नहीं सताते, जो सुख-दुःख को समान देख सकता है, वह धीर है। ऐसा पुरुष अमृतत्व के योग्य हो जाता है।\n\nकृष्ण आगे कहते हैं: 'जिस पुरुष को मात्रा-स्पर्श नहीं सताता, वह सुख-दुःख को समान देखने वाला धीर है।' यहाँ 'पुरुष' शब्द आया है। हमारे यहाँ यह अंधविश्वास है कि 'पुरुष' का अर्थ पुरुष (नर) है, और केवल पुरुषों के लिए ही साधना-मोक्ष है। परन्तु पुरुष का अर्थ है 'पुर में रहने वाला जीव'। पुर का अर्थ है पूर्ण देह, अर्थात मानव देह। इसलिए पुरुष का अर्थ है मानव (Human being) अथवा साधक जीव। स्थूल शरीर में रहते हुए भी जिसे मात्रा-स्पर्श से आने वाला सुख-दुःख अलग-अलग नहीं दिखता, वह सुख-दुःख को समान देखने वाला धीर कहलाता है।\n\nपुरुष का एक और अर्थ है 'सबसे बड़े भगवान को जानने वाला'। हमें सुख-दुःख क्यों आते हैं इसका ज्ञान होने पर, हम सुख आने पर फूलते नहीं, दुःख आने पर घबराते नहीं। हमारे जीवन में आने वाले हर सुख-दुःख का एक कारण है। सुख-दुःख जीवन में आने वाली लहरें हैं। इसमें एक चाहिए, दूसरा नहीं चाहिए — यह चुनाव सही नहीं है। जो आया उसी में रहना चाहिए, ऐसे जीना चाहिए। हमें सुख-दुःख कोई द्वेष से नहीं देता, वह हमारा कर्मफल है। सुख-दुःख देने वाला भगवान है। जैसे माता अपने बच्चे के उद्धार के लिए दंड देती है, वैसे ही भगवान हमारे उद्धार के लिए हमें दुःख देते हैं। यह दंड नहीं है — शिक्षा है। मनुष्य दुःख में जो अनुभव प्राप्त करता है वह कभी सुख में प्राप्त नहीं कर सकता। दुःख जीवन का वास्तविक अनुभव है। यह हमें दिया जाने वाला दुःख भगवान की महान करुणा है। यह ज्ञान होने पर ही हमें सुख-दुःख को एकरूप में देखने की मनःस्थिति आती है। ऐसा ज्ञान रखने वाला धीर बनता है। समझ से धैर्य आता है। जो एक जन्म में सुख-दुःख को समान देखने की समझ और धैर्य पा लेते हैं, वे फिर कभी इस संसार-बंधन में जन्म नहीं लेते। ऐसे मानसिक संतुलन के द्वारा भगवान को जानकर मोक्ष पाते हैं।",
  "2.16": "नासतो विद्यते भावो नाभावो विद्यते सतः ।\n\nउभयोरपि दृष्टोऽन्तस्त्वनयोस्तत्त्वदर्शिभिः -- न तो प्रकृति का कभी नाश होता है, न भगवान का। [बुरा करने से भला नहीं होता, भले से बुरा नहीं होता।] सत्य को देखने वाले इन दोनों का निर्णय जानते हैं।\n\nसुख-दुःख से ऊपर उठकर खड़ा हुआ जा सकता है — यह एक मानसिक स्थिति है। परन्तु अर्जुन का प्रश्न है — अपने गुरुजनों-बड़ों को मारना क्या पाप नहीं है? इस प्रश्न का उत्तर यहाँ है। 'सत् से अभाव नहीं होता, असत् में भाव नहीं होता' का अर्थ है — अच्छा काम करने से कभी दुःख नहीं होता, बुरा काम करने से सुख नहीं होता। कभी-कभी बुरा काम करने वाले सुखी दिखाई देते हैं, परन्तु वह अस्थायी होता है। अधर्म के मार्ग पर चलने वाला कभी सच्ची सफलता नहीं पाता। महाभारत युद्ध का विश्लेषण करें तो युद्ध के कारण पांडव नहीं हैं। पांडव धर्म-रक्षा के दायित्व से युद्ध के लिए तैयार हुए हैं। यहाँ कृष्ण स्पष्ट कहते हैं: 'अच्छा काम करते समय किसी का भय मत रखो, उससे दुःख नहीं होता।' धर्म-रक्षा के मार्ग पर 'ये मेरे अपने हैं' यह भाव उचित नहीं है। यही अंतिम सत्य है जो जगत के तत्त्व का साक्षात्कार करने वाले ज्ञानियों ने पाया है।\n\nकहते हैं कि महाभारत के हर श्लोक के दस अर्थ होते हैं। ऊपर के श्लोक को यदि हम एक और दृष्टि से देखें — 'न असतः अभावः सतः अभावः न विद्यति' — अर्थात सत् का भी अभाव नहीं, असत् का भी अभाव नहीं। असत् का अर्थ है स्थूल संसार का कारण, सूक्ष्म मूलप्रकृति। प्रकृति अनादि-नित्य है। इस प्रकृति की सृष्टि करने वाला भगवान (पुरुष) भी अनादि-नित्य है। प्रकृति और पुरुष के अधीन रहने वाला जीव भी अनादि-नित्य है। जीव को यह स्थूल देह मिलने से पहले भी जीव था, और आगे भी रहेगा। पांचभौतिक शरीर में जीव केवल अतिथि है। ऐसे में देह के प्रति अभिमान उचित नहीं है।",
  "2.17": "अविनाशि तु तद्विद्धि येन सर्वमिदं ततम् ।\n\nविनाशमव्ययस्यास्य न कश्चित्कर्तुमर्हति -- जो इस सबमें व्याप्त है, उसे अविनाशी जानो। उस अपरिवर्तनीय का नाश करने की शक्ति किसी में नहीं है।\n\nजो सर्वत्र व्याप्त है उसका नाश नहीं होता। जैसे रूपात्मक संसार है, वैसे ही नामात्मक संसार भी है। वह नित्य है। यहाँ नामात्मक का अर्थ है 'अक्षर' — अ से क्ष तक के इक्यावन वर्ण। ये इक्यावन अक्षर ही सम्पूर्ण शब्द-संसार के मूल हैं। यह नाश न होने वाला तत्त्व है। इसलिए भगवान, प्रकृति, जीव तथा इन सब तत्त्वों का प्रतिपादन करने वाला शब्द [वेद] अनादि-नित्य है। इसे कोई नष्ट नहीं कर सकता। इस नामात्मक संसार में वेद-स्वरूप भगवान अविनाशी हैं। उन्हें स्वरूप-नाश, देह-नाश, दुःख-प्राप्ति, अपूर्णता — इस प्रकार का कोई भी नाश नहीं है। वे काल से, देश से, गुण से व्याप्त अनंत स्वरूप हैं। वे अव्यय हैं, किसी विकार-परिवर्तन के अधीन नहीं, अनादि-नित्य स्वरूप हैं।",
  "2.18": "अन्तवन्त इमे देहा नित्यस्योक्ताः शरीरिणः ।\n\nअनाशिनोऽप्रमेयस्य तस्माद्युध्यस्व भारत -- न नष्ट होने वाले, अप्रमेय जीव के ये देह अंतवाले कहे गए हैं। इसलिए हे भारत, युद्ध करो।\n\nभौतिक शरीर अंतवत् है (नष्ट होने वाला)। केवल आँखों से दिखने वाला स्थूल शरीर ही नष्ट होता है, आत्मा नहीं। क्योंकि जीव भगवान का ही प्रतिबिंब है। वह सर्वव्यापी भगवान का प्रतिबिंब है। इसलिए सब जगह विद्यमान भगवान का प्रतिबिंब यह जीव नित्य है। यहाँ कृष्ण अर्जुन से कहते हैं: 'सम्राट बनने के स्वार्थ से, या दुर्योधन के प्रति द्वेष से नहीं, बल्कि अन्याय के विरुद्ध युद्ध ही भगवान की पूजा है, ऐसे भाव से युद्ध करो।'\n\nहम अपने दैनंदिन जीवन में जो भी कर्म करते हैं वह भी ऐसा ही होना चाहिए। वह भगवान को अर्पण के रूप में होना चाहिए। हमें देह भगवान ने ही दिया है। इसलिए वह देह जाने पर रोने की आवश्यकता नहीं है। अपने प्रत्येक कर्तव्य को भगवान की पूजा मानकर, मृत्यु से न डरते हुए जीने पर ही यह जीवन सार्थक होता है।",
  "2.19": "य एनं वेत्ति हन्तारं यश्चैनं मन्यते हतम् ।\n\nउभौ तौ न विजानीतो नायं हन्ति न हन्यते -- जो इसे 'मारने वाला' समझता है, और जो इसे 'मरा हुआ' समझता है — वे दोनों ही नहीं जानते। यह न मारता है, न मारा जाता है।\n\nजो लोग यह मानते हैं कि जीव को मार सकते हैं / मार रहे हैं, और जो यह मानते हैं कि वह नष्ट हो गया / मारा गया, उन्हें सच्चा ज्ञान नहीं है। क्योंकि जीव न मारता है, न मारा जाता है। आत्मा को मारना सम्भव ही नहीं है। हमें जो मरना या मर जाना दिखाई देता है, वह केवल भौतिक शरीर है। जीव को देह के माध्यम से भी मारने या मरने की स्वतंत्रता नहीं है। यहाँ अर्जुन का यह विचार कि 'कौरव मेरे हाथों मरेंगे' केवल भ्रम है। सृष्टि-संहार करने वाले भगवान की इच्छा के बिना कुछ भी नहीं होता। उनकी इच्छा के विरुद्ध हम कुछ भी नहीं कर सकते।",
  "2.20": "न जायते म्रियते वा कदाचिन्नायं भूत्वा भविता वा न भूयः ।\n\nअजो नित्यः शाश्वतोऽयं पुराणो न हन्यते हन्यमाने शरीरे -- यह जीव कभी जन्म नहीं लेता, न कभी मरता है। यह न होकर फिर होने वाला भी नहीं है। यह अजन्मा, नित्य, शाश्वत, पुरातन है — शरीर के मारे जाने पर भी यह मारा नहीं जाता।\n\nयह जीव कभी जन्म नहीं लेता; न मरता है। भगवान की जानकारी के अनुसार छिपा हुआ रहकर फिर कुछ और बन जाने वाला भी यह नहीं है। यह जन्म-रहित, मृत्यु-रहित, अपरिवर्तनीय — भगवान का प्रतिरूप है। [परम पुरुष भी कभी जन्म नहीं लेते, न मरते हैं। स्वरूप से रहते हुए देह से जन्म लेते हैं, यह भी उचित नहीं। यह जीव भी जन्म-रहित, मृत्यु-रहित, अपरिवर्तनीय तत्त्व है।] देह से देह में भटकने वाला यह जीव देह के नष्ट होने पर भी स्वयं नष्ट नहीं होता।\n\nयहाँ कृष्ण ने 'जीव-स्वरूप' का अर्थ क्या है यह समझाया है। यह जीव स्वरूप से कभी जन्म नहीं लेता और कभी नष्ट नहीं होता। यह सदा एकरूप रहता है, क्योंकि जीव-स्वरूप भगवान का प्रतिबिंब है। भगवान का जन्म नहीं होता। वे नित्य और शाश्वत हैं। जीव सदा शरीर से शरीर में संचरण करता रहता है (पुर-अण)। परन्तु देह के बदलने पर भी जीव-स्वरूप नहीं बदलता। जैसे भौतिक शरीर को बुढ़ापा आता है, वैसे जीव-स्वरूप को बुढ़ापा नहीं आता। वह सदा एकरूप रहता है। परन्तु प्रभाव से आई हुई मान्यता बदल सकती है। उदाहरण के लिए, एक जन्म में नास्तिक रहने वाला दूसरे जन्म में पूर्ण आस्तिक बन सकता है। अपने स्वभाव से विशिष्ट जीव सदा अपरिवर्तित, अविनष्ट बना रहता है।",
  "2.21": "वेदाविनाशिनं नित्यं य एनमजमव्ययम् ।\n\nकथं स पुरुषः पार्थ कं घातयति हन्ति कम् -- हे पार्थ, जन्म-मृत्यु रहित, न बदलने वाले, किसी से भी न नष्ट होने वाले इस जीव [अथवा शरीर से भी नष्ट न होने वाले भगवान] को जानने वाला जीव, किसे कैसे मरवाए? किसे कैसे मारे?\n\nजिस दोषरहित, नित्य, कभी न बदलने वाले जीव-स्वरूप को कोई जानता है, वह मनुष्य किसी को कैसे मार सकता है, या मरवा सकता है? स्वरूप से जीव का नाश नहीं होता — यह जानने पर, स्थूल संसार में जन्म-मृत्यु भगवान की इच्छा के अनुसार चल रही है यह जानने पर, कौन किसे मारे या मरवाए? हमें केवल जन्म-मृत्यु के पीछे स्थित भगवत्शक्ति को जानना है, बस।\n\nजीव का नाश नहीं होता, उसके लिए जन्म-मृत्यु नहीं है। तो फिर हम लौकिक रूप से दिखने वाले जन्म-मृत्यु को कैसे समझें? इस प्रश्न का उत्तर कृष्ण अगले श्लोक में देते हैं।",
  "2.22": "वासांसि जीर्णानि यथा विहाय नवानि गृह्णाति नरोऽपराणि ।\n\nतथा शरीराणि विहाय जीर्णान्यन्यानि संयाति नवानि देही -- जैसे मनुष्य पुराने वस्त्रों को त्यागकर दूसरे नए वस्त्र पहनता है, वैसे ही जीव एक देह को छोड़कर दूसरी नई देह प्राप्त करता है।\n\nजैसे हम पहने हुए वस्त्र पुराने होने पर उन्हें बदल देते हैं, वैसे ही जीव एक देह छोड़कर दूसरी देह पाता है। यहाँ एक विशेष बात यह है कि जैसे माता अपने बच्चे के वस्त्र अपनी इच्छा से बदलती है, वैसे ही भगवान जीव की देह बदलते हैं। जीव को स्वयं देह बदलने की स्वतंत्रता नहीं है। इसका एक अपवाद है आत्मसाक्षात्कार प्राप्त योगी — वे भगवान की कृपा से अपनी इच्छा से देह बदलने की शक्ति पाते हैं। [इस विषय में स्वामी राम द्वारा लिखी गई \"Living with Himalayan Masters\" नामक पुस्तक में अनेक वास्तविक उदाहरण देखे जा सकते हैं।] ऐसे महान योगियों को छोड़कर अन्य किसी को अपनी इच्छा से देह बदलने की स्वतंत्रता नहीं है। इसलिए भौतिक रूप से जन्म-मृत्यु का अर्थ है पहने हुए वस्त्र उतारकर नए वस्त्र पहनाना। स्वरूप से जीव को कभी जन्म-मृत्यु नहीं होती, और नई देह से उसका मूल स्वभाव नहीं बदलता।\n\nतो क्या आत्मा को नष्ट करना सम्भव ही नहीं है? कभी नहीं, ऐसा कृष्ण अगले श्लोक में कहते हैं।",
  "2.23": "नैनं छिन्दन्ति शस्त्राणि नैनं दहति पावकः ।\n\nन चैनं क्लेदयन्त्यापो न शोषयति मारुतः -- इस जीव को [भगवान को] शस्त्र नहीं काट सकते। इसे आग नहीं जला सकती। इसे पानी नहीं भिगो सकता, हवा नहीं सुखा सकती।\n\nकिसी भी वस्तु को नष्ट करने के चार मुख्य साधन हैं — मिट्टी (ठोस अस्त्र के रूप में), पानी, आग, और हवा। जीव सूक्ष्म से भी सूक्ष्म है। शास्त्रकारों के अनुसार, घोड़े की पूँछ के एक बाल की नोक को दस हज़ार भागों में बाँटा जाए तो जो एक भाग मिलता है, जीव उतना ही सूक्ष्म है। ऐसे जीव को कोई शस्त्र नहीं काट सकता। आग जीव को नहीं जला सकती। पानी से जीव नहीं भीगता। हवा जीव को नहीं सुखाती। अत्यंत सूक्ष्म जीव को कोई भी शस्त्र नष्ट नहीं कर सकता।\n\nयहाँ हमारे मन में एक और प्रश्न उठता है — 'जो जीव आज नष्ट नहीं किया जा सकता, क्या वह सदा के लिए ही अविनाशी है?' हाँ, ऐसा कृष्ण अगले श्लोक में कहते हैं।",
  "2.24": "अच्छेद्योऽयमदाह्योऽयमक्लेद्योऽशोष्य एव च ।\n\nनित्यः सर्वगतस्थाणुरचलोऽयं सनातनः -- इस जीव को काटा नहीं जा सकता। इसे जलाया नहीं जा सकता। इसे भिगोया नहीं जा सकता; सुखाया भी नहीं जा सकता। सदा सर्वत्र व्याप्त, किसी से भी न बदलने वाला, अचल, यह पुरातन पुरुष का प्रतिरूप है। [सर्वत्र व्याप्त भगवान को सदा धारण करने वाला अणुरूपी। यह किसी से भी न बदलने वाली नियति से बद्ध है — वेद के विधि-निषेधों से भी।]\n\nजीव को आज नहीं, आगे भी कभी कोई नष्ट नहीं कर सकता। क्योंकि वह अपने गुण-धर्म से सदा अपरिवर्तित, सर्वव्यापी, अविचलित — भगवान का प्रतिरूप है। किसी भी शस्त्र की पहुँच से परे, सभी काल में एकरूप रहने वाला, सर्वत्र स्थिर, बिना परिवर्तन वाला गुण-धर्म जीव में है। जीव सनातन है, अर्थात नातन से सहित। यहाँ 'नातन' का अर्थ है 'नादन', अर्थात वेदनाद। जीव वेदनाद से सहित होकर, सम्पूर्ण वेद द्वारा प्रतिपादित भगवान की गोद में वेद के विधि-निषेधों से बद्ध रहता है। यह सर्वव्यापी भगवान का आश्रय लेने वाला महान अणु है।",
  "2.25": "अव्यक्तोऽयमचिन्त्योऽयमविकार्योऽयमुच्यते ।\n\nतस्मादेवं विदित्वैनं नानुशोचितुमर्हसि -- भगवान आँखों से नहीं दिखते; वे चिंतन की पहुँच से परे हैं; वे कभी नहीं बदलते — ऐसा वेद कहता है। इसलिए उनका [और जीव का] स्वरूप ऐसा जानकर शोक करना उचित नहीं है।\n\nभगवान अव्यक्त हैं। उनका प्रतिबिंब जीव भौतिक शरीर में रहते हुए भी अव्यक्त ही है। इस कारण भगवान और जीव हमारे चिंतन की पहुँच से परे हैं। मैं कौन हूँ? कहाँ से आया? मैं क्या हूँ? यह भी हमें नहीं मालूम। भगवान और जीव-स्वरूप कभी नहीं बदलते, फिर भी वे हमारे चिंतन की पकड़ में नहीं आते। यह कठोर सत्य जानने के बाद जीव नष्ट हो जाएगा यह सोचकर दुःखी होने की आवश्यकता नहीं है।",
  "2.26": "अथ चैनं नित्यजातं नित्यं वा मन्यसे मृतम् ।\n\nतथापि त्वं महाबाहो नैनं शोचितुमर्हसि -- फिर भी यदि तुम यह मानते हो कि यह जीव देह के माध्यम से सदा जन्म लेता है और मरता है, तो भी हे महावीर, तुम्हें इसके लिए शोक करना उचित नहीं है।\n\nवेदांत को छोड़कर लौकिक दृष्टि से विचार करें तो, आत्मा देह के माध्यम से व्यक्त होती है और मृत्यु के माध्यम से अव्यक्त होती है। जन्म-मृत्यु से ऊपर उठकर खड़ा होना कभी सम्भव नहीं है। इसलिए मृत्यु के विषय में दुःख करने की आवश्यकता नहीं है। 'महाबलशाली तुमने इससे पहले कितने युद्ध किए हैं? तब न रही समस्या अब क्यों? तुम जो कर रहे हो वह तुम्हारा कर्तव्य ही है, और कुछ नहीं' — ऐसा कृष्ण अर्जुन को समझाकर कहते हैं।",
  "2.27": "जातस्य हि ध्रुवो मृत्युर्ध्रुवं जन्म मृतस्य च ।\n\nतस्मादपरिहार्येऽर्थे न त्वं शोचितुमर्हसि -- जन्म लेने वाले की मृत्यु निश्चित है; मरने वाले का पुनर्जन्म भी निश्चित है। ऐसे में, अनिवार्य विषय के लिए तुम्हारा रोना उचित नहीं है।\n\nजन्म-मृत्यु, सुख-दुःख, एक ही सिक्के के दो पहलू हैं। रात के बिना दिन नहीं होता। जन्म लेने के बाद मृत्यु बँधी हुई पोटली है। हमें जीवन में जो अनिवार्य है उसे स्वीकार करना सीखना चाहिए। इसके अतिरिक्त कष्ट आने पर दुःखी होना उचित नहीं है। अनिवार्य कर्तव्य के पालन में हमें कभी दुःखी नहीं होना चाहिए।",
  "2.28": "अव्यक्तादीनि भूतानि व्यक्तमध्यानि भारत ।\n\nअव्यक्तनिधनान्येव तत्र का परिदेवना -- हे भरतवंशी, प्राणियों के जीवन की जड़ आरम्भ में नहीं दिखती। केवल मध्य भाग दिखता है। अंत भी नहीं दिखता। ऐसे में विलाप क्यों?\n\nयहाँ तक हमने कृष्ण के वचनों में जीव, जीव के अस्तित्व, जन्म-मृत्यु के विषय में अनेक प्रकार से विश्लेषण देखा है। परन्तु मूल रूप से अर्जुन को जो समस्या सता रही है वह है 'मेरे गुरु, मेरे दादा' यह सम्बन्ध का खिंचाव। ऐसे महान ज्ञानियों के विरुद्ध निर्लिप्त होकर युद्ध कैसे करें, यही उसकी समस्या है। यहाँ कृष्ण उसकी समस्या का उत्तर देते हैं।\n\nएक व्यक्ति हमारा सम्बन्धी उसके जन्म के बाद ही बनता है, परन्तु जन्म से पहले वह क्या था? मरने के बाद कहाँ जाता है? इस जन्म-मृत्यु के पहले और बाद हमारा उस जीव से कोई सम्बन्ध नहीं है। यह सम्बन्ध जीव के निरंतर जीवन की सरल रेखा का एक बिंदु मात्र है। वह बिंदु ही हमें व्यक्त है। शेष अव्यक्त है। इसलिए सरल रेखा के एक बिंदु पर खड़े होकर दुःखी होना उचित नहीं है।\n\nयहाँ इसका अर्थ यह नहीं कि हम जीवित रहते हुए एक-दूसरे से प्रेम न करें। जब तक हैं तब तक प्रेम करो, परन्तु जब न रहें तब भगवान ने बुला लिया यह सोचकर निश्चिंत रहने के लिए मन को प्रशिक्षित करो। इस प्रकार जीना न सीखे तो जीवन असह्य हो जाता है। जब हैं तब प्रसन्न रहो, जब न रहें तब दुःखी मत हो — यही कृष्ण का सन्देश है।",
  "2.29": "आश्चर्यवत्पश्यति कश्चिदेनमाश्चर्यवद्वदति तथैव चान्यः ।\n\nआश्चर्यवच्चैनमन्यः शृणोति श्रुत्वाप्येनं वेद न चैव कश्चित् -- कोई इस जीवतत्त्व या भगवान को आश्चर्य के समान देखता है। कोई अन्य आश्चर्य के समान इसका वर्णन करता है। कोई अन्य आश्चर्य के समान इसे सुनता है। सुनकर भी कोई इसे पूरी तरह नहीं जानता।\n\nयदि कोई इस जीव-तत्त्व अथवा भगवान को पा लेता है तो वह एक आश्चर्य जैसा है। कोई अन्य उसे दिखाए तो वह भी आश्चर्य जैसा है। कोई अन्य उसे सुनकर जान ले तो वह भी आश्चर्य जैसा है। [कोई भगवान को आश्चर्य से देखता है। कोई आश्चर्य से बोलता है। कोई उन्हें आश्चर्य से सुनता है।] कितना भी सुना जाए, जीव को या भगवान को ठीक-ठीक जानने वाला कोई नहीं है।\n\nयह जीव और भगवान के विषय में श्लोक है। भगवान को देखने वाले विरले हैं। यदि बड़ी साधना से उन्हें पा लिया जाए, तो पाने वाले का उद्गार केवल आश्चर्य होता है। यह एक विस्मय है। यह विश्व ही एक अद्भुत वस्तु है, तो विश्व बनाने वाला वह भगवान कितना अद्भुत होगा? इसलिए उन्हें देखने वाले उनका वर्णन नहीं कर पाते। यदि वर्णन करें भी तो सुनने वाले को वह आश्चर्य ही लगता है। कोई कितना भी सुने, अंत में भगवान केवल आश्चर्य बनकर ही रह जाते हैं, क्योंकि भगवान को जानना असम्भव है।\n\nयही बात जीव के विषय में भी है। आत्मसाक्षात्कार होने पर हमें केवल विस्मय होता है। उसका वर्णन करना असम्भव है। जीव प्रकाश का एक पुंज है। वह एक महान आश्चर्य है। वह सूर्य से भी तेज़, चंद्रमा से भी शीतल प्रकाश है। जीव-तत्त्व के विषय में सुनकर उसके बारे में निश्चित निर्णय पर पहुँचना असम्भव है।",
  "2.30": "देही नित्यमवध्योऽयं देहे सर्वस्य भारत ।\n\nतस्मात्सर्वाणि भूतानि न त्वं शोचितुमर्हसि -- हे भारत, सबकी देह में रहने वाला यह जीव कभी मारा नहीं जा सकता। [इस जीव को मारना कभी सम्भव नहीं है, क्योंकि सबकी देह में भगवान जीव की रक्षा के लिए बैठे हैं।] इसलिए सब प्राणियों के लिए तुम्हारा रोना उचित नहीं है।\n\nमूल रूप से किसी की भी देह में रहने वाले जीव को मारना सम्भव नहीं है। देह का मरना विधि-नियम है, और उसके लिए दुःखी होने की आवश्यकता नहीं है। अपनी स्वयं की इच्छा से देह त्यागना सम्भव नहीं है, और न त्यागना भी सम्भव नहीं है। 'अयं देहे सर्वस्य भारत' — 'रक्षा करने वाले भगवान अंदर बैठे होने पर तुम जन्म-मृत्यु के लिए उत्तरदायी नहीं हो सकते। भरतवंश में जन्मे तुम यह सत्य जान लो' ऐसा कृष्ण कहते हैं। जीव नामक प्रकाश की चिनगारी को जानने पर, उसका बोध होने पर, जन्म-मृत्यु का रहस्य समझ में आता है। तब मृत्यु आनंद का अनुभव बन जाती है।\n\nकृष्ण के इस पूरे विश्लेषण को सुनकर हममें एक विचार आ सकता है — 'मारना गलत नहीं है, क्योंकि जीव को मृत्यु नहीं है। सब कुछ ईश्वर की इच्छा है। जो चाहे जिसे मार सकता है।' परन्तु यह सही नहीं है, क्योंकि अब तक जो हमने देखा वह केवल जीवन का आंतरिक दृष्टिकोण है। समाज में रहने वाले हम इस आंतरिक बोध का समाज के विरुद्ध उपयोग करें तो वह अधर्म होगा। शास्त्र के अनुरूप समाज-धर्म का पालन प्रत्येक को करना ही चाहिए। अगले श्लोक में कृष्ण इस विषय को अर्जुन के माध्यम से हमें स्पष्ट करते हैं।",
  "2.31": "स्वधर्ममपि चावेक्ष्य न विकम्पितुमर्हसि ।\n\nधर्म्याद्धि युद्धाच्छ्रेयोऽन्यत्क्षत्रियस्य न विद्यते -- अपने धर्म को देखकर भी तुम्हें विचलित नहीं होना चाहिए। क्षत्रिय के लिए न्याय से प्राप्त युद्ध से बढ़कर कोई कल्याण नहीं है।\n\nयहाँ अर्जुन का सनातन धर्म क्या है? समाज धर्म क्या है? और स्वधर्म क्या है? सनातन धर्म कहता है — अन्याय के विरुद्ध लड़ना ही चाहिए। समाज धर्म कहता है — क्षत्रिय को अधर्म के विरुद्ध लड़ना चाहिए, समाज की रक्षा करनी चाहिए, और इस पुण्य कार्य में 'ये मेरे अपने हैं' यह नहीं देखना चाहिए। अर्जुन मूलतः क्षत्रिय है, इसलिए उसका स्वधर्म है 'अन्याय के विरुद्ध लड़ना'। यहाँ व्यक्तिधर्म, समाजधर्म और सनातनधर्म एक ही हैं। इसलिए अन्याय के विरुद्ध लड़ना महापुण्य का काम है। समाज की सुरक्षा के लिए लड़ना क्षत्रिय की महातपस्या है। इससे बढ़कर पुण्यकार्य कोई नहीं है।",
  "2.32": "यदृच्छया चोपपन्नं स्वर्गद्वारमपावृतम् ।\n\nसुखिनः क्षत्रियाः पार्थ लभन्ते युद्धमीदृशम् -- बिना किसी प्रयत्न के अपने आप प्राप्त हुआ, खुला हुआ स्वर्ग का द्वार है यह। भाग्यशाली क्षत्रिय ही ऐसा युद्ध पाते हैं, हे पार्थ।\n\nझगड़ा मोल लेकर युद्ध करना गलत है। परन्तु यहाँ सामूहिक रूप से आया हुआ युद्ध का दायित्व पांडवों का नहीं है। अपने आप आकर टूट पड़ा यह युद्ध दैवेच्छा है। ईश्वर की इच्छा से सब कुछ होने पर, जो आया उसे वैसे ही स्वीकार करना चाहिए। अन्याय के विरुद्ध धर्मयुद्ध करने वाले के लिए स्वर्ग का द्वार सदा खुला रहता है। ऐसे युद्ध का अवसर एक क्षत्रिय को मिलने के लिए उसने पुण्य किया होना चाहिए। ऐसे समय क्षत्रिय का आँखें मूँदकर बैठे रहना महापाप है।\n\nयहाँ हमें स्पष्ट समझ में आता है कि कृष्ण अर्जुन से युद्ध करने को क्यों कह रहे हैं। प्रत्येक मनुष्य को सनातनधर्म, उसके अनुरूप समाजधर्म, तथा समाज और सनातनधर्म के अनुरूप स्वधर्म — इस आधार पर अपना कर्तव्य निभाना चाहिए। इस आधार पर किया गया कोई भी कार्य पापकर्म नहीं होता। अगले श्लोक में कृष्ण इस विषय में और अधिक विवरण देते हैं। सनातनधर्म, समाजधर्म और स्वधर्म का अर्थ क्या है यह पहले अध्याय में (श्लोक ४०) विस्तार से बताया जा चुका है।",
  "2.33": "अथ चेत्त्वं धर्म्यमिमं संग्रामं न करिष्यसि ।\n\nततः स्वधर्मं कीर्तिं च हित्वा पापमवाप्स्यसि -- यदि न्याय से प्राप्त इस युद्ध को तुम नहीं करोगे, तो अपना धर्म और नाम दोनों खोकर पाप ही प्राप्त करोगे।\n\nआगे कृष्ण अर्जुन से कहते हैं: 'तुम पाप के भय से युद्ध नहीं चाहते, ऐसा कह रहे हो। परन्तु युद्ध करने से ही धर्म बचेगा, और तुम्हारे लिए स्वर्ग का द्वार खुलेगा। ऐसा न करने पर नरक का द्वार तुम्हारा स्वागत करेगा।'\n\nयहाँ चल रहा है एक धर्मसंग्राम। अर्जुन धर्म के पक्ष में खड़ा महारथी है। ऐसे धर्मसंग्राम में धर्म के पक्ष में न लड़ना अपने स्वाभाविक धर्म के विरुद्ध तथा सामाजिक धर्म को छोड़ना होगा। यह एक कलंक और महापाप बन जाएगा। इस प्रकार पाप के भय से पीड़ित अर्जुन को कृष्ण सच्चा पाप क्या है यह समझा रहे हैं।\n\nपाप कर्म क्या है यह प्रसंग तय करता है। उदाहरण के लिए 'सत्य बोलना पुण्य का काम है' यह हमेशा नहीं कहा जा सकता। वह पाप है या पुण्य यह प्रसंग निर्धारित करता है। डाकुओं से बचने के लिए आश्रय माँगकर आए व्यक्ति को छिपाकर, डाकुओं के पूछने पर सत्य बोलना पाप का काम है। छिपाए गए व्यक्ति की रक्षा के लिए झूठ बोलना पुण्य का काम है। इसी प्रकार यहाँ अर्जुन के लिए धर्म की रक्षा हेतु गुरु-पितामह के विरुद्ध खड़े होकर लड़ना ही महापुण्य का काम है, यह कृष्ण समझा रहे हैं।",
  "2.34": "अकीर्तिं चापि भूतानि कथयिष्यन्ति तेऽव्ययाम् ।\n\nसंभावितस्य चाकीर्तिर्मरणादतिरिच्यते -- लोग तुम्हारे न मिटने वाले कलंक की कथा कहते रहेंगे। मर्यादित मनुष्य के लिए बदनामी मृत्यु से भी भयंकर है।\n\nसामाजिक परिणाम के बारे में बताते हुए कृष्ण कहते हैं: एक क्षत्रिय की कीर्ति नष्ट होने पर वह अपमानित होता है, इससे वह अपना अस्तित्व ही खो सकता है। संसार में महान धनुर्धर की कीर्ति पाने वाला अर्जुन यदि इस धर्मयुद्ध में भाग न ले, तो लोग उसे कायर कहकर बदनाम करेंगे। इतिहास के पन्नों में उसका कायरपन आगे की पीढ़ी के लिए बुरा उदाहरण बनकर रहेगा। 'बंधु-स्नेह के लिए युद्ध से पीछे हटा' ऐसा कोई नहीं कहेगा। युद्ध से डरकर भागा कायर कहकर नीचता से गाली देंगे। एक मर्यादित मनुष्य के लिए अकीर्ति मृत्यु से भी नीची चीज़ है। एक क्षत्रिय इसे सहन नहीं कर सकता।",
  "2.35": "भयाद्रणादुपरतं मंस्यन्ते त्वां महारथाः ।\n\nयेषां च त्वं बहुमतो भूत्वा यास्यसि लाघवम् -- जिनके लिए तुम सम्मान की वस्तु थे, वे बड़े महारथी तुम्हें भय से युद्ध से पीछे हटा हुआ मानेंगे; उनके सामने तुम हल्के हो जाओगे, वे तुम्हें डरकर लड़ने से हिचकिचाया कायर समझेंगे।",
  "2.36": "अवाच्यवादांश्च बहून्वदिष्यन्ति तवाहिताः ।\n\nनिन्दन्तस्तव सामर्थ्यं ततो दुःखतरं नु किम् -- तुम्हारे शत्रु तुम्हारे पराक्रम की निंदा करते हुए बहुत सी न कहने योग्य बातें कहेंगे। इससे बढ़कर दुःख क्या हो सकता है?\n\n'जो तुम्हें बड़ा वीर मानकर हाथ जोड़कर सिर झुकाकर खड़े होते थे, वे तुम्हें घास से भी नीचा देखेंगे। समाज में उच्च पुरुष तुम अपमानित होकर जीना पड़ेगा। न कहने योग्य अशिष्ट बातें उठेंगी। इससे तुम्हारी पहले की सारी साधना भी झूठी कहकर निंदा की जाएगी।'\n\n'उत्तम न्यायाधीश' नाम पाने वाला व्यक्ति किसी प्रसंग में अपने आत्मीय बंधु के लिए बुरा फैसला दे दे, तो वह अपना पूरा व्यक्तित्व खो देता है। उसकी पहले की सारी उपलब्धियाँ एक क्षण में मिट्टी में मिल जाती हैं। उससे दंडित अपराधी भी उसे अशिष्टता से निंदा करते हैं। यहाँ श्रीकृष्ण अर्जुन को यह सामाजिक बोध दे रहे हैं।",
  "2.37": "हतो वा प्राप्स्यसि स्वर्गं जित्वा वा भोक्ष्यसे महीम् ।\n\nतस्मादुत्तिष्ठ कौन्तेय युद्धाय कृतनिश्चयः -- मरने पर स्वर्ग पाओगे, जीतने पर धरती का उपभोग करोगे। इसलिए, हे कौन्तेय, लड़ने का निश्चय करके उठ खड़े हो जाओ।\n\n'युद्ध करने से हम जीतेंगे यह निश्चित नहीं है। धर्मयुद्ध में मरने पर भी मोक्ष, जीतने पर भी मोक्ष। यह किसी स्वार्थ के लिए किया जाने वाला युद्ध नहीं है। अन्याय के विरुद्ध लड़ूँगा इस संकल्प से उठकर खड़े होकर लड़ो' ऐसा कृष्ण कहते हैं।\n\nहम जो भी कार्य करते हैं उसमें धर्म का ज्ञान महत्वपूर्ण है। बिना किसी स्वार्थ के धर्म के मार्ग का अनुसरण करने वाले को कभी किसी बात से डरने की आवश्यकता नहीं है। धर्म के मार्ग पर चलने पर मुझे क्या होगा इसका भय आवश्यक नहीं, क्योंकि धर्म के मार्ग पर चलने का परिणाम जो भी हो, वह हमें मोक्ष तक ले जाने का साधन बनता है।",
  "2.38": "सुखदुःखे समे कृत्वा लाभालाभौ जयाजयौ ।\n\nततो युद्धाय युज्यस्व नैवं पापमवाप्स्यसि -- सुख-दुःख, लाभ-हानि, जय-पराजय को समान करके फिर युद्ध में लग जाओ। तब तुम्हें कोई पाप नहीं लगेगा।\n\nजीवन में सुख-दुःख अनिवार्य है। सुख-दुःख, लाभ-हानि, जय-पराजय — सबको समान देखने वाले को कोई पाप नहीं छूता। सबको समदृष्टि से देखते हुए, केवल कर्तव्य-बुद्धि से युद्ध करना जीवन की सफलता का सूत्र है। जीतना ही है यह स्वार्थ न रखते हुए, वे मिट्टी में मिलें यह द्वेष न रखते हुए, सब कुछ भगवान का प्रसाद है यह मनोभाव रखकर लड़ो, ऐसा कृष्ण कहते हैं।\n\nभगवान के इस वचन को मनुष्य अपने जीवन में अपना ले तो वह कभी दुःखी नहीं हो सकता। 'जो भी आए आने दो, गोविंद की कृपा बनी रहे' ऐसा कहकर धर्म के मार्ग पर आगे बढ़ने वाले के लिए स्वर्ग का द्वार सदा खुला रहता है। उसे दुःख दुःख के रूप में नहीं दिखता, हार हार के रूप में नहीं दिखती। उसके लिए यह लोक भी स्वर्ग है, परलोक भी स्वर्ग है।\n\nयहाँ तक कृष्ण ने आत्मतत्त्व के बारे में अर्जुन को पर्याप्त विवरण दिया। जीवन क्या है? मृत्यु क्या है? आत्मा-परमात्मा, उन तत्त्वों का अंतरंग रहस्य क्या है? ये कैसे बिना किसी परिवर्तन के अनादि-नित्य हैं यह समझाकर युद्ध की आवश्यकता बताई। यहाँ से आगे कृष्ण सांख्य से कर्म की ओर मुड़ते हैं।\n\nहम मन में वेदांत को कितना भी दृढ़ करें, तत्काल के मनुष्य का दुःख अदम्य ही रहता है, यह गीता स्पष्ट बताती है। भगवान से गीता का उपदेश पाने वाला अर्जुन, अपने पुत्र अभिमन्यु के युद्ध में मरने पर पुनः विचलित होते हुए हम महाभारत में देखते हैं। पूर्ण आत्मसाक्षात्कार पाना इतना आसान नहीं है। आत्मा अजर-अमर है यह जानना पर्याप्त नहीं, पूर्ण रूप से जानना चाहिए। ऐसी स्थिति में सारा दुःख भुलाया जा सकता है। परन्तु इस आत्मतत्त्व को जानने का तरीका क्या है? आत्मज्ञान पाने का साधन क्या है? सुनते ही साक्षात्कार होकर मन में दृढ़ता से बैठ जाने वाला विषय यह नहीं है।\n\nइसलिए मानसिक रूप से इस उच्चतम स्थिति तक पहुँचना कैसे है यह कृष्ण आगे बताते हैं।",
  "2.39": "एषा तेऽभिहिता सांख्ये बुद्धिर्योगे त्विमां शृणु ।\n\nबुद्ध्वा युक्तो यया पार्थ कर्मबन्धं प्रहास्यसि -- यह आत्मविज्ञान की बुद्धि तुम्हें सांख्य में बताई गई। अब योग में इसे सुनो। हे पार्थ, इसे समझकर तुम कर्म के बंधन से मुक्त हो जाओगे।\n\nकृष्ण कहते हैं: 'अब तक सांख्य के बारे में बताया गया। अब योग के बारे में बताता हूँ, सुनो।' यहाँ कृष्ण जो सांख्य कह रहे हैं वह है 'वैदिक सांख्य'। वैदिक सांख्य का प्रचार करने वाले कपिल वासुदेव थे। सांख्या का अर्थ है सम्यक् ख्याति अथवा सही बोध। यह आत्मा का बोध देने वाला मूल तत्त्व है। इस कारण प्राचीनों ने ज्ञान को सांख्य कहा। यहाँ सांख्य का अर्थ है निश्चित आत्मज्ञान।\n\nयहाँ बताया जा रहा योग पतंजलि का योग नहीं है, वैदिक योग है। सामान्य योग के लिए ईश्वर के अस्तित्व में दृढ़ विश्वास आवश्यक नहीं है। मन को किसी एक वस्तु पर निरंतर एकाग्रता करने से अनेक चमत्कार किए जा सकते हैं। परन्तु यह सच्चा आत्मसाक्षात्कार नहीं है। दस वर्ष योग साधना करके पानी पर चलना सीखने वाले की कथा हम सबने सुनी है। इस प्रकार योग से चमत्कार सीखकर प्रदर्शन करना वैदिक योग निषिद्ध करता है। कैसी भी अंतःशक्ति प्राप्त हो, उसका प्रदर्शन नहीं करना चाहिए। पानी पर चलना सीखते ही हमें आत्मसाक्षात्कार नहीं होता। ऐसा इंद्रजाल कोई भी प्राप्त कर सकता है। यहाँ कृष्ण जो कह रहे हैं वह है आत्मतत्त्व पाने के लिए जीवन में करने योग्य साधना क्या है, यह विषय।\n\nसांख्य को जानने की बात कही, अब ज्ञान के मार्ग पर आगे बढ़कर सिद्धि पाने के लिए आवश्यक उपाय (योग) बताता हूँ, सुनो, ऐसा कृष्ण कहते हैं। कौन सा बोध पाने पर साधना के मार्ग में कर्म बंधन को पार करके आगे बढ़ा जा सकता है यह कृष्ण आगे बताते हैं। अध्यात्म की साधना क्या है, हमारे जीवन में अध्यात्म की साधना कैसी होनी चाहिए, उसे साधना कैसे है — यह हमें जानने योग्य मुख्य विषय है।\n\nबहुत से लोग बाहर से कैसा होना चाहिए यह अनेक प्रकार से बताते हैं। परन्तु अंदर से कैसा होना चाहिए यह कोई नहीं बताता। इतनी देर जप करना चाहिए, इस प्रकार शुद्ध रहना चाहिए, इतना मंत्र कहना चाहिए इत्यादि विचार सब बताते हैं। परन्तु अंतरंग कैसा होना चाहिए यह अधिकांश को नहीं मालूम। अंतरंग साधना के बिना केवल बाहरी वेश से, जप-तप से, कुछ भी साधना संभव नहीं है। योग साधना का अर्थ है नहीं कि हम कौन सा वस्त्र पहनते हैं, शरीर पर क्या लगाते हैं। वह हमारा अंतरंग आचरण है। अंतरंग और बहिरंग एक हो जाने की स्थिति। हमारा आचरण, हमारा विश्वास, हमारी प्रामाणिकता ही हमारा सच्चा धर्म है। ऐसी अंतरंग साधना अत्यंत महत्वपूर्ण है। इसे कृष्ण आगे बताते हैं।\n\nज्ञान चाहिए यह सच है, परन्तु आत्मज्ञान पाने के लिए हमारी साधना क्या होनी चाहिए, इस संसार बंधन से मुक्त होने की साधना कौन सी है, यह अगले श्लोकों में विस्तार से देखेंगे।",
  "2.40": "नेहाभिक्रमनाशोऽस्ति प्रत्यवायो न विद्यते ।\n\nस्वल्पमप्यस्य धर्मस्य त्रायते महतो भयात् -- यहाँ शुरुआती कदम भी व्यर्थ नहीं जाता। यहाँ कोई बाधा नहीं है; इस धर्म का एक टुकड़ा भी बड़े भय से बचा सकता है।\n\nसाधना के बारे में बताने से पहले कृष्ण इस श्लोक में हमें आने वाली एक शंका का समाधान करते हैं। सबको एक प्रश्न सता सकता है — पहले जन्म, फिर अध्ययन-साधना, फिर मृत्यु। फिर पुनर्जन्म, फिर वही साधना, फिर मृत्यु! इससे क्या लाभ? एक जन्म में ब्रह्मसाक्षात्कार न हो तो वह सारी साधना व्यर्थ है क्या? बिल्कुल नहीं, ऐसा कृष्ण कहते हैं। हमारे जीवन में कमाई गई ऐहिक संपत्ति (धन, गहने, कीर्ति, संपत्ति इत्यादि) मृत्यु के बाद हमारे साथ नहीं आती, यह सच है। परन्तु अध्यात्म साधना ऐसी नहीं है। एक जन्म में की गई अध्यात्म साधना कभी नष्ट नहीं होती। इस जन्म में अध्यात्म की एक सीढ़ी चढ़ें तो अगले जन्म में जन्म लेते ही हम दूसरी सीढ़ी पर होते हैं। पिछले जन्म में जहाँ रुके थे वहीं से आगे बढ़ने वाले वातावरण में हमारा जन्म होता है। सामाजिक रूप से आप असाधारण प्रतिभा वाले बच्चों का जन्म, तथा बहुत कम समय में महान साधना करना देखते हैं। यह उनका पिछले जन्म से लाया हुआ ज्ञान है। पिछले जन्म की अध्यात्म साधना का आगे बढ़ा हुआ भाग ही यह जन्म है। हम उस जन्म में जहाँ रुके थे वहीं से इस जन्म की साधना शुरू होकर आगे बढ़ती है।\n\nयदि हमें अध्यात्म साधना करनी है यह अंतरंग की तड़प हो, और उसे इस जन्म में साध न सकें, तो अगले जन्म में साधना के लिए आवश्यक वातावरण में, विद्वानों के संग वाली जगह हमारा जन्म होता है। इसलिए हमारे अध्यात्म चिंतन में हमारा एक-एक जन्म एक-एक कक्षा जैसा है। एक ग्रंथ को पूर्ण रूप से जानने के लिए हमें अनेक जन्म साधना करनी पड़ सकती है। इस कारण अध्यात्म साधना कभी व्यर्थ नहीं है। आज आप अपने जीवन के किसी भी पड़ाव पर हों, अध्यात्म साधना के लिए यही सही समय है। आज ही अपनी साधना शुरू करो। वह तुम्हें मोक्ष मार्ग की ओर ले जाएगी यह कड़वा सच है। अध्यात्म प्रदर्शन की वस्तु नहीं है, वह अंतरंग की साधना है। हमारे जन्म में हम अध्यात्म की थोड़ी सी भी साधना करें तो भी वह हमें भय से बचाती है। भय से अभय की ओर हमें ले जाने वाला एकमात्र साधन अध्यात्म है।\n\nसाधकों में तीन प्रकार होते हैं — उत्तम साधक, मध्यम साधक, अधम साधक। उत्तम साधक भगवान एक ही है यह मानता है। ऐसे भक्तों को भागवत कहते हैं। उसकी भगवान में एकनिष्ठा होती है। भगवान को किसी भी शब्द से पुकारें, वह उसी आदिशक्ति परम शक्ति को कहता है यह सत्य वह जानता है। यही सच्चा साधक है, और यही साधना का सच्चा मार्ग है। अब मध्यम साधक: ये हर देवता को अलग-अलग रूप से पूजकर अंत में 'कृष्णार्पणमस्तु' कहकर भगवान को अर्पित करते हैं। इन्हें त्रैविध्य कहते हैं। अब अधम साधक: यह भगवान सैकड़ों हैं ऐसा मानकर पूजता है। भगवान सर्वांतर्यामी हैं यह भावना इसमें नहीं होती। इसे अध्यात्म की सच्ची कल्पना नहीं होती। इसलिए यह सच्ची अध्यात्म साधना नहीं बनती।\n\nहम एकनिष्ठा से जो साधना करते हैं वह कभी व्यर्थ नहीं होती। यहाँ दिखावे की आवश्यकता नहीं है। परन्तु प्रामाणिक निष्ठा आवश्यक है। गणपति को पूजो, वायु को पूजो, सूर्य को पूजो, अल्लाह कहकर, ईसा कहकर, शिव कहकर, विष्णु कहकर, जो भी कहकर पूजो, सारे शब्द आदिशक्ति परम शक्ति को ही कहते हैं यह सत्य जानकर, एकनिष्ठा रखकर, शुद्ध प्रामाणिक चिंतन करने पर वह सच्ची अध्यात्म साधना बनती है तथा व्यर्थ हुए बिना हमारे साथ आती है। ऐसी साधना में द्वेष, स्वार्थ, अहंकार, दुःख कभी नहीं होते। सब कुछ भगवान का प्रसाद है यह भावना हमें ऊँचाई तक ले जाती है।",
  "2.41": "व्यवसायात्मिका बुद्धिरेका इह कुरुनन्दन ।\n\nबहुशाखा ह्यनन्ताश्च बुद्धयोऽव्यवसायिनाम् -- हे कुरुनन्दन, इस मार्ग में मनन से पके हुए वचन एक ही प्रकार के होते हैं। जिनमें ऐसा निश्चय नहीं है, उनकी अंतहीन बातें कई शाखाओं में बँट जाती हैं।\n\nहमें यह ज्ञान हुआ कि एकनिष्ठा से किया गया साधन व्यर्थ नहीं है, परन्तु सही और गलत जानने का तरीका क्या है? कृष्ण इस श्लोक में हमारे प्रश्न का उत्तर देते हैं।\n\nहर काल में निर्णायक वचन एकरूप होता है। बिना निश्चय के बोला गया वचन अलग-अलग प्रकार का होता है। बिना जाने अज्ञान से बोले गए वचनों की अनगिनत निराधार शाखाएँ होती हैं। परन्तु सच में जानने वालों का निर्णयात्मक वचन सदा एक ही होता है। इसलिए सत्य को जानने वालों के मार्गदर्शन के अनुसार चलो, ऐसा कृष्ण कहते हैं।",
  "2.42": "यामिमां पुष्टितां वाचं प्रवदन्त्यविपश्चितः ।\n\nवेदवादरतः पार्थ नान्यदस्तीति वादिनः -- हे पार्थ, अधकचरा जानने वाले कहते हैं: यह वेदवाणी स्वर्ग रूपी फूलती हुई बेल है। जन्म-कर्म के बंधन वाला संसार ही इसका फल है।",
  "2.43": "कामात्मानः स्वर्गपरा जन्मकर्मफलप्रदाम् ।\n\nक्रियाविशेषबहुलां भोगैश्वर्यगतिं प्रति -- ऐश्वर्य और भोग वाले जीवन के लिए वे कई प्रकार के कर्मकांड करते हैं। वे वेद के ऊपरी अर्थ में ही अटके रहते हैं। [वेद में विवाद बढ़ाने वाले, या अर्थ जाने बिना केवल रटने वाले।] उससे परे कुछ नहीं है ऐसा मानने वाले, इच्छा से भरे हुए, स्वर्ग के सपने देखने वाले।",
  "2.44": "भोगैश्वर्यप्रसक्तानां तयापहृतचेतसाम् ।\n\nव्यवसायात्मिका बुद्धिः समाधौ न विधीयते -- भोग में फँसे, अधकचरे ज्ञान की बातों से मोहित बुद्धि खो चुके ऐसे लोगों के लिए, परिपक्व समझदार बात भी मन की स्थिरता में सहायक नहीं होती।\n\nऊपर के तीन श्लोक अत्यंत महत्वपूर्ण हैं। अधिकांश लोगों को यह समझ में ही नहीं आता। बिना समझे इस श्लोक की आलोचना करने वाले भी हैं! प्राचीन ग्रंथों में, वेदों में, श्रुतियों में, केवल अध्यात्म ही नहीं बल्कि अनेक सांसारिक विषय भी भरे हुए दिखते हैं। केवल वेद ग्रंथ पढ़ने से मुझे जानना संभव नहीं है, ऐसा कृष्ण कहते हैं। कृष्ण कहते हैं कि वेदवादी लोग वेद के ऊपरी अर्थ रूपी फूल को तोड़कर गहरे ज्ञान सागर रूपी फल से वंचित रह जाते हैं। वेद को गहराई से न समझते हुए, केवल ऊपरी अर्थ में रुककर वेद इतना ही है ऐसा कहने वालों से कृष्ण यह बात कहते हैं। यहाँ 'वेदवाद' का अर्थ है वेद का अर्थ जाने बिना उसके बारे में विवाद करने वाले। वेद को रटकर उसका अर्थ जाने बिना बोलने वाले। वेद के ऊपरी अर्थ में रुके हुए लोग। ये ऊपर से तैरने वाले हैं। इन्हें तल में स्थित मोती-रत्नों का बोध नहीं है। वेद को सच में समझे बिना, उसके बारे में गलत कल्पना करके, वही लोगों को कहना नरक का सीधा रास्ता है। पौरोहित्य भी ऐसा ही है। सच्चे ज्ञान के बिना, मंत्र का अर्थ जाने बिना पौरोहित्य करना भी उतना ही खतरनाक है। पौरोहित्य एक जिम्मेदारी भरा काम है। एक मनुष्य के पाप को दूर कर उसे ऊँचा उठाने के लिए पुरोहित को भी ऊँचाई पर होना चाहिए। वेदमंत्र का रहस्य जानने वाला होना चाहिए। कृष्ण यहाँ कहते हैं: 'वेद का अंतरंग अर्थ न जानने पर सब कुछ अपार्थ हो जाता है। जो प्राचीन ग्रंथों का ऊपरी अर्थ बताकर समाज को धोखा देते हैं वे अविपश्चित हैं।' 'विपश्चित' का अर्थ है जिन्होंने ज्ञान-स्वरूप आत्मा को देखा है, आत्मज्ञानी। अविपश्चित शास्त्र का ऊपरी अर्थ बताने वाले हैं — वे नासमझ हैं, ऐसा कृष्ण कहते हैं! यह बात संसार के हर धर्मग्रंथ में है। बाइबिल में इसे गूढ़ार्थ कहते हैं। कुरान में भी इस बारे में सचेत करने वाली बात है: 'इसमें ऐसी आयतें हैं जो स्पष्ट हैं, और अन्य आयतें हैं जो संदिग्ध हैं।' यह कुरान में आने वाली एक बात है। सभी प्राचीन अनुभावी साहित्य में यह चेतावनी दी गई है। प्राचीन ग्रंथ पहेली जैसे हैं। उनका ऊपरी अर्थ जानने पर वह असंगत हो जाता है। अध्यात्म ग्रंथों में हमें उच्चतर स्थिति तक ले जाने के लिए इस प्रकार पहेली जैसी भाषा (symbolic language) का उपयोग किया गया है। वेद प्रतीकात्मक भाषा है यह न जानने पर अध्यात्म चिंतन अनर्थ हो जाता है। इस प्रकार बिना जाने की गई साधना से कोई उपयोग नहीं है।\n\nप्राचीन ग्रंथों में अनेक कथाएँ मिलती हैं। उन्हें ऊपर से देखें तो मनोरंजक लगती हैं। परन्तु उनका सार जानने पर जीवन सार्थक होता है। इसका उत्तम उदाहरण है गणपति की कथा। 'पार्वती ने अपने शरीर की मिट्टी से गणपति का निर्माण किया, उनका सिर शिव ने काटा, फिर उन्हें उत्तर दिशा में सिर वाले हाथी का सिर जोड़ा गया, कड़बू खाने वाले गणेश ने पेट पर साँप लपेटा'। इसका क्या अर्थ है? यह कथा न सुनने वाला कोई नहीं है, परन्तु इसका अर्थ जानने वाला हज़ार में एक नहीं है! इस कथा का सूक्ष्मता से विश्लेषण करने पर ही हमें कथा का महत्व, पूजा का महत्व, विश्वास का महत्व समझ में आता है। गणपति आकाश के देवता हैं। आकाश पंच भूतों में सबसे महान है। गणपति का स्थान इक्कीसवाँ है, इसलिए उन्हें इक्कीस मोदक अर्पण किए जाते हैं। पाँच अंतःकरण, पाँच ज्ञानेंद्रियाँ, पाँच कर्मेंद्रियाँ, पाँच तन्मात्राएँ (शब्द, स्पर्श, रूप, रस, गंध) — इनसे आगे आकाश, वायु, अग्नि, जल, पृथ्वी। यहाँ आकाश इक्कीसवीं सीढ़ी पर है, यह इक्कीसवाँ तत्व है। गणपति से पहले स्तर पर बीस तत्त्वाभिमानी हैं — ब्रह्मा, वायु, गरुड़, शेष, रुद्र, इंद्र, काम, अहंप्राण, अनिरुद्ध, स्वायंभुव मनु, बृहस्पति, दक्षप्रजापति, प्रवहवायु, चंद्र, सूर्य, यमधर्म, वरुण, वह्नि, मित्र और निर्ऋति। गणपति इक्कीसवें हैं।\n\nअब शिव-पार्वती। ये दंपति हैं। यहाँ शिव मन के अभिमानी देवता हैं और पार्वती वाक् देवता। मन जैसा सोचता है वैसी ही वाणी होती है, इसलिए उनका दांपत्य अन्योन्य है। शब्द की मूल शक्ति वायु और आकाश हैं। आकाश और वायु न हों तो शब्द नहीं होता। हमारी भीतरी वाक्-नाद ही पार्वती है, वह शब्द रूप में बाहर आना ही वाणी है। यह मूल नाद का स्थूल रूप है। मनुष्य के लिए सबसे बड़ी आपत्ति वाणी है। अध्यात्म साधना के लिए वाणी से अधिक आवश्यक है मौन। स्वयं के बोध के बिना (awareness of self), अहंकार तत्व के विरुद्ध वाणी बढ़ने पर, वाणी के शिरच्छेदन के बिना ज्ञान नहीं होता। शिरच्छेदन के बाद फिर वही वाणी आगे नहीं बढ़नी चाहिए। इसके लिए सब कुछ सुनने वाले बड़े कानों वाला, प्राणशक्ति को नियंत्रित करने वाली लंबी नाक के प्रतीक रूप हाथी का सिर लेकर गणपति नामक नए आकार का जन्म हुआ। गणपति को देखते ही हमें याद आना चाहिए कि बोलने से अधिक मनन करो, अच्छी तरह सुनो (be a good listener), यही विचार है।\n\nअब उत्तर दिशा में सिर करने का क्या अर्थ है? सामान्यतः हम सभी जानते हैं कि उत्तर में सिर करके नहीं सोना चाहिए। दक्षिण की ओर मुख करके पूजा में नहीं बैठना चाहिए। मंदिर में उल्टी परिक्रमा नहीं करनी चाहिए इत्यादि। परन्तु यह सब क्यों? इसके पीछे का सिद्धांत क्या है? इस पृथ्वी पर उत्तरी ध्रुव की शक्ति उत्तर से पूर्व की ओर बहती है, और दक्षिणी ध्रुव की शक्ति दक्षिण से पश्चिम की ओर बहती है। हमारी गति भी इस शक्तिपात के अनुरूप होनी चाहिए। हम दक्षिण की ओर मुख करें तो दक्षिणी ध्रुव के शक्तिपात के सामने खुद को उजागर करते हैं, और उत्तर की ओर मुख करें तो उत्तरी ध्रुव के शक्तिपात के सामने। उत्तर में सिर करके सोना यानी उठते समय दक्षिण की ओर मुख होना। इसलिए दक्षिण मुख और उत्तर सिर दोनों एक ही हैं। इन दो शक्तिपातों में एक बड़ा अंतर है — उत्तर का शक्तिपात ऊर्ध्वमुखी है और दक्षिण का शक्तिपात संसार के भँवर में फँसाने वाला है। इस कारण उत्तर में सिर करके सोने या दक्षिण की ओर मुख करके पूजा में बैठने से हमारा शिरच्छेदन होता है। हमें फिर इस संसार के भँवर में घूमना पड़ता है।\n\nअब पेट पर साँप का लपेटना। साँप कुंडलिनी शक्ति का प्रतीक है। यह चक्राकार होकर सिर नीचे किए सोए साँप के रूप में हमारे मल-मूत्र द्वार के मध्य में रहता है। कुंडलिनी जाग्रत होना यानी यह साँप फन उठाकर खड़ा होना। कुंडलिनी जाग्रत होने पर शक्ति मूलाधार, मणिपुर और स्वाधिष्ठान शक्ति केंद्रों में ऊर्ध्वमुखी होकर संचरण करती है। हमारी नाभि के ऊपर का शक्ति केंद्र ज्ञान का द्वार है, गणपति इन तीन शक्ति केंद्रों को नियंत्रित कर हमें ज्ञान का द्वार खोलने वाले शक्ति देवता हैं। इतनी बात इस छोटी सी कथा में है। यह फूल से फल तक जाने का तरीका है। केवल ऊपरी अर्थ में रुकने से कोई हानि नहीं है, उससे परे कुछ नहीं है ऐसा मान लेना ही अनर्थ है।\n\nहमें अपने सिर में जो है वह वेद में नहीं ढूँढना चाहिए, बल्कि वेद में जो है उसे अपने सिर में भरना चाहिए। वेद को ऊपरी दृष्टि से देखने पर हम केवल जन्म-कर्म, जन्म-मृत्यु के इसी भँवर में रहते हैं, अमरत्व का मार्ग कभी नहीं दिखता। ऊपरी दृष्टि से वेद देखने वाले सुबह से शाम तक भोग-ऐश्वर्य-कर्मकांड में खड़े रहकर आत्मसाक्षात्कार भूल जाते हैं। यह बड़ा दुर्भाग्य है।\n\nअब हमें एक प्रश्न सताता है — प्राचीन अध्यात्म ग्रंथ पहेली के रूप में क्यों लिखे गए? कक्षा के अनुसार पाठ्यपुस्तक होती है वैसे इन ग्रंथों को चरण-दर-चरण समझ में आने वाले तरीके से क्यों नहीं लिखा गया? इत्यादि। यहाँ हमें जो मुख्य बात जाननी है वह यह है कि इन ग्रंथों को समझने के लिए योग्यता चाहिए। यहाँ पुस्तक एक ही है, परन्तु एक ही पुस्तक में अनेक स्तर की शिक्षा छिपी है। ये वेद ग्रंथ कभी अयोग्य को नहीं मिलते। वे केवल स्वयं को जानने वाले, जानकर उसका सदुपयोग कर सकने वाले के सामने ही खुलते हैं। योग्य व्यक्ति इस ग्रंथ की गहराई में जितना उतरता है उतना ही अधिक विषय जानता है। एक ग्रंथ को जानने के लिए अनेक जन्मों की साधना चाहिए।",
  "2.45": "त्रैगुण्यविषया वेदा निस्त्रैगुण्यो भवार्जुन ।\n\nनिर्द्वन्द्वो नित्यसत्त्वस्थो निर्योगक्षेम आत्मवान् -- वेद ऊपरी दृष्टि से त्रिगुणों के संबंध का ही निरूपण करते हैं। [भीतर से त्रिगुणों के संबंध के विष को दूर करते हैं।] हे अर्जुन, तुम त्रिगुणों के बंधन से मुक्त होकर खड़े रहो... द्वंद्वों का टकराव मिटाकर सदा भगवान में मन लगाओ। योग-क्षेम का भार उन्हें सौंपकर वही स्वामी हैं ऐसा मानकर चलो।\n\nअब तक हमने देखा कि वेद का अनुसंधान कैसे करना चाहिए, उसके ऊपरी अर्थ से गहराई में कैसे उतरना चाहिए, यह कृष्ण ने अर्जुन को बताया। और अधिक स्पष्टता से, वह कैसा दिखता है और उसे कैसे देखना चाहिए यह इस श्लोक में कृष्ण स्पष्ट रूप से बताते हैं। यह एक तरह से पूरे अध्यात्म अनुसंधान की मुख्य बात है। यहाँ कृष्ण बताते हैं कि इसका अनुसंधान कैसे करना चाहिए, तथा अपने मन को कैसे तैयार करना चाहिए।\n\nहमें ऊपरी दृष्टि से वेद सत्व-रज-तमोगुण (त्रैगुण्य) से संबंधित सांसारिक विषय, तथा केवल सांसारिक अर्थ ही कहते हुए दिखता है — जैसे लाल चश्मा पहनने वाले को सारा संसार लाल दिखता है। उदाहरण के लिए: संतान वृद्धि, गोशाला भरी हुई गायों से, हाथ भरा धन, घर भरे बच्चे, राजसूय, अश्वमेध, पुरुषमेध इत्यादि। ये वेद में ऊपरी दृष्टि से दिखने वाली बातें हैं। ये सब बिल्कुल सांसारिक विषय हैं। इस कारण वेद हमें अध्यात्म की गहराई में नहीं ले जाता ऐसा लगता है। परन्तु वेद को समझने के लिए पहले सांसारिक प्रभाव को पार करना चाहिए। सांसारिक प्रभाव लाल चश्मे जैसा है। उसके प्रभाव में वेद देखने पर हमें केवल सांसारिक विषय ही दिखता है। इसलिए हमें त्रैगुण्यवर्जित होना चाहिए। इन तीन गुणों के प्रभाव को पार कर अपना सच्चा स्वभाव क्या है यह पहचानने पर शुद्ध चिंतन संभव होता है। त्रिगुण की बाड़ पार किए बिना सत्य ज्ञात नहीं होता। त्रिगुण के प्रभाव से पूर्णतः बाहर खड़ा होना असंभव है। परन्तु यह जानकारी हो और उसकी सावधानी हो तो हम साधना कर सकते हैं। हम कितने भी अपवित्र हों, मुँह में भगवान का नाम स्मरण, हमारे भीतर भगवान हैं यह सावधानी हमें शुद्ध करती है।\n\nध्यान करते समय हमारा मन बाहरी संसार की ओर न भटके यह देखना चाहिए। आत्मज्ञान के बिना होम-हवन करना व्यर्थ है। हमें आश्रयभूत आत्मतत्व को भगवान के बोध से निःस्वार्थ भाव से साधना चाहिए। कभी छल-कपट रहित धर्म का आचरण करना चाहिए। हमारे मन को शुद्ध भाव-चिंतन के लिए तैयार करना चाहिए। अपने स्वार्थ की ओर न देखते हुए, त्रिगुणों को पार करके खड़े होने पर ही हमें वेद का सच्चा संदेश समझ में आता है। इस स्थिति में वेद पढ़ने पर वह केवल लौकिक विषय नहीं है यह समझ में आता है। हमारे द्वारा किए जाने वाले हर कर्म को, पूजा-अर्चना को, निःस्वार्थ भाव से भगवान की आराधना मानकर करना चाहिए। हमें क्या चाहिए यह हमें पता नहीं है; हमें जो आवश्यक है वह भगवान देते ही हैं; ऐसा मानकर अपनी भविष्य की चिंता भगवान को सौंपकर आगे बढ़ने पर ज्ञान सिद्ध होता है।\n\nजो नहीं है उसे पाना योग है, जो पाया है उसे बनाए रखना क्षेम है। लौकिक योग-क्षेम में ही हमारा पूरा जीवन बीत जाता है। इसे छोड़कर भगवान ने हमें जो दिया है उसमें संतुष्ट रहना सीखना चाहिए। 'निर्योगक्षेम' की स्थिति में ही सत्य का साक्षात्कार होता है। हमारे योग-क्षेम का दायित्व उस भगवान का है। सबके भीतर अंतर्यामी रूप में रहने वाला भगवान सदा हमारी रक्षा करता है यह भरोसा रखकर भगवान के चिंतन में लगना चाहिए। यह अध्यात्म साधना के लिए आवश्यक मानसिक तैयारी है। ऐसी मनःस्थिति में कोई भी ग्रंथ पढ़ें तो वह भगवान की स्तुति बन जाती है। इस मनःस्थिति तक पहुँचे बिना वेदांत हमारी समझ में नहीं आता।\n\nअध्यात्म मार्ग पर चलने वाले व्यक्ति की साधना क्या होनी चाहिए, अंतरंग का अनुष्ठान कैसा होना चाहिए, यह स्पष्ट करने वाले कृष्ण के वचन से हमें एक प्रश्न उठ सकता है। कृष्ण कर्म और ज्ञान में से ज्ञान को महत्व देकर आगे बढ़ना चाहिए, हमारी किसी भी क्रिया का अनुसंधान ज्ञान की ओर सहायक होना चाहिए, ऐसा कहते हैं। 'ज्ञान साधना को इतना महत्व क्यों? कर्मयोग से स्वर्ग तो पाया जा सकता है?' यह प्रश्न है। इस प्रश्न का उत्तर कृष्ण यहाँ देते हैं। पहले वेद को ज्ञानकांड, कर्मकांड और उपासनाकांड — तीन भागों में बाँटने की परंपरा थी। परन्तु कृष्ण कहते हैं कि वेद का एक ही मुख है। वेद में कहे गए कर्म, उपासना — सबके पीछे ज्ञान छिपा है। सब कुछ ज्ञान के लिए ही है। इसलिए संपूर्ण वेद ही ज्ञानकांड है, यह अगले श्लोक में कृष्ण जोर देकर कहते हैं।",
  "2.46": "यावानर्थ उदपाने सर्वतः सम्प्लुतोदके ।\n\nतावान्सर्वेषु वेदेषु ब्राह्मणस्य विजानतः -- कुएँ से जो भी उपयोग है वह सब भरकर बहते हुए पानी के स्रोत में समाहित है। सभी वेदों में जो फल है वह ब्रह्म को जानने वाले विज्ञानी के फल में समाहित है। [प्रकृति पानी की तरह सब जगह भरकर बहने वाली, प्रलय में भी भरे हुए घड़े के समान, किसी और की देखभाल के बिना, काल आदि का नियमन करने वाले भगवान से जितना मिलता है, वह सभी वेदों को जानने वाले बड़े ज्ञानी को ही सुलभ है।]\n\nयह श्लोक पहेली जैसा है। सीधे देखने पर अर्थ समझ में न आने वाला श्लोक है यह। इस श्लोक को समझने के लिए इसमें डूबना पड़ता है। तब गहराई के मोती-रत्न हमें मिलते हैं। हम अपने अहंकार को पूर्ण रूप से त्यागकर शरणागति से (Self Surrender) देखें तो यह स्वयं को खोल देता है। इस श्लोक को थोड़ा खोलकर ऐसे कहा जा सकता है:\n\n'यावान् अर्थ उदपाने, यावान् अर्थ सर्वतः संप्लुतोदके, तावान् सर्वेषु वेदेषु, तावान् ब्राह्मणस्य विजानतः' — एक कुआँ खोदकर उससे मिलने वाले पानी से जो लाभ है, उन सब लाभों के साथ और भी अनेक लाभ भरकर बहते हुए पानी का स्रोत दे सकता है। बिना ज्ञान के कर्मकांड करने वाले की स्थिति घर में कठिनाई से कुआँ खोदकर उससे पानी खींचने जैसी है। भगवान का साक्षात्कार करने वाले की स्थिति भरकर बहते हुए पानी के स्रोत के किनारे खड़े होने जैसी है। अपरोक्ष ज्ञानी सब कुछ में भगवान को देखता है। ब्रह्मज्ञानी सदा निर्मल भरकर बहते पानी के स्रोत के पास खड़े व्यक्ति के समान है। पूरे वेद को पढ़कर केवल कर्म में बैठे रहने वाला पसीना बहाकर कुएँ से पानी खींचने वाले के समान है।\n\nइस श्लोक में 'ब्राह्मण' शब्द आया है। इसे 'जाति' मानें तो इस श्लोक का सच्चा संदेश समझ में नहीं आता। वेद ग्रंथों में कहीं भी जाति का उल्लेख नहीं है। ब्राह्मण का अर्थ है 'ब्रह्म जानाति इति'; अर्थात ब्रह्म तत्व को समझने वाला। 'ब्रह्म' का अर्थ है सबसे बड़ा। सबसे बड़ा है वेद और वेद से जाने जाने वाले भगवान। इसलिए वेद को जानने वाला, वेदवेद्य भगवान का साक्षात्कार करने वाला ब्राह्मण है।\n\nब्रह्म को अपरोक्ष रूप से जानने वाले ज्ञानी को भरकर बहते पानी का फल मिलता है, कर्मकांडी को कुएँ का फल। शास्त्र से विशिष्ट बोध पाने वाला विज्ञानी ही भगवान को देख सकता है। यहाँ विज्ञानी का अर्थ है किसी भी वस्तु के बारे में तलस्पर्शी ज्ञान रखने वाला।\n\nइस श्लोक में एक और बात छिपी है। 'सर्वतः संप्लुतोदक' का अर्थ है पानी से भरी स्थिति। यहाँ पानी का अर्थ है प्रलयजल। प्रकृति सूक्ष्म परमाणु के समुद्र रूप में रहने वाला काल-प्रलयकाल है। ऐसे प्रलय समुद्र में सोने वाले को 'उदपान' कहते हैं। उत्-अप-अन — अर्थात सबसे उत्कृष्ट, सदा सचेत (उत्); सबका पालन करने वाला, तथा अपने से बड़ा कोई पालक न होने वाला सर्वोत्तम (अप); सबको नियंत्रित करने वाला सर्वचेष्टक (अन)। इस तत्व के माध्यम से जो भी उपयोग पाया जा सकता है, वह उपयोग समस्त वेद में, वेद के हर मंत्र में, मंत्र के हर वाक्य में, वाक्य के हर पद में, पद के हर अक्षर में भगवान को देखने वाला ब्रह्मज्ञानी पाता है।\n\nवेद को केवल ऊपरी दृष्टि से पढ़ने से कोई लाभ नहीं है। वेद के समग्र मंत्र में, मंत्र के हर अक्षर में भगवान को देखकर भगवन्मय होने पर, भगवान की समस्त कृपा का पात्र बनकर, समग्र लाभ पाया जा सकता है।\n\n'फल की कामना से कर्मकांड नहीं, समग्र वेद को भगवान के चिंतन के लिए समर्पित करो' ऐसा कहने वाले कृष्ण के वचन से हमें थोड़ा भ्रम हो सकता है। क्योंकि वेद में हर जगह फल बताया गया है। ऐसा क्यों है यह प्रश्न हमारे मन में उठता है। पहले बताया गया है कि अध्यात्म की पाठ्यपुस्तक साधना के हर स्तर पर — छोटे से बड़े तक सबके लिए एक ही है। अभी शुरुआती स्तर पर रहने वालों से कुछ भी न चाहते हुए निर्लिप्त होकर अनुसरण करो ऐसा कहें तो उन्हें वेदांत में रुचि ही न हो। इसलिए, बच्चों को गुड़ देकर दवा पिलाने की तरह वेदों में फल बताया गया है। यह वेदाभ्यास के शुरुआती स्तर पर उपयोगी है।\n\nकर्म करते समय हमारी मनःस्थिति कैसी होनी चाहिए यह अगले श्लोक में कृष्ण विस्तार से बताते हैं।",
  "2.47": "कर्मण्येवाधिकारस्ते मा फलेषु कदाचन ।\n\nमा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि -- कर्म में ही तुम्हारा अधिकार है, फलों में कभी नहीं। फल को ही मानकर कर्म मत करो (कर्म को फल देने की शक्ति स्वयं में है ऐसा मत मानो)। वैसे ही अकर्मण्यता तुम्हें न लगे।\n\nइस श्लोक को गलत समझने वाले ही अधिक हैं। कर्म करना चाहिए परन्तु फल की इच्छा नहीं करनी चाहिए इसका क्या अर्थ है? यह मनुष्य को निष्क्रिय बना देता है, इत्यादि तर्क इस श्लोक पर अनेक लोगों ने प्रस्तुत किए हैं। परन्तु उनमें से किसी ने भी श्लोक का सच्चा अर्थ जानने का प्रयत्न नहीं किया। यहाँ कहीं भी फल की इच्छा मत करो ऐसा नहीं कहा गया है। इसके बदले फल में अधिकार मत जताओ ऐसा कृष्ण कहते हैं।\n\nकर्म तुम्हारे हाथ में है, परन्तु कर्मफल भगवान के हाथ में है। तुम स्वयं को कर्मफल का कारण मत मानो। कर्मफल का कारण भगवान है यह सावधानी तुम्हें रहे, ऐसा कृष्ण कहते हैं। यहाँ कृष्ण ने इच्छा का निषेध नहीं किया, परन्तु 'ऐसा ही होना चाहिए, नहीं तो मैं यह कर्म नहीं करूँगा' यह विचार सही नहीं है ऐसा कहा है। इच्छा करने का अधिकार हमें है, परन्तु फल देने वाला भगवान है यह बोध चाहिए। कई बार हम बिना जाने गलत इच्छा करते हैं। तब भगवान वह नहीं दे सकते, क्योंकि सही क्या है गलत क्या है इसका बोध हमें नहीं है। यह सावधानी हो तो हमें फल न मिलने पर दुःख नहीं होता। हम जो कर्म करते हैं उसे निष्ठा से भगवद्अर्पण के रूप में करके, उससे जो भी फल आया उसे वैसे ही स्वीकार करने की मनोवृत्ति विकसित करें तो दुःख नहीं रहता।\n\nकृष्ण कहते हैं कि किसी भी समय निष्क्रिय होकर मत बैठो, सदा कर्तव्यशील रहो। 'ऐसा ही होना चाहिए', 'ऐसा ही फल आना चाहिए' यह विचार छोड़कर कर्तव्य निभाने पर कोई दुःख नहीं है। इसे छोड़कर फल में अधिकार जताने पर वह फल न मिलने पर होने वाला आघात, व्याकुलता भयानक है। हार और जीत को समान देखने वाली मनःस्थिति हमें ऊँचाई तक ले जाती है। पहले बताया गया है कि हम हार में जितना सीखते हैं उतना जीत में नहीं सीख सकते। भगवान हमें फल देते समय हमारी भलाई को ध्यान में रखकर देते हैं, न कि हम जैसा सोचते हैं वैसे। जो आया उसे वैसे ही स्वीकार करते हुए, कभी निष्क्रिय न होते हुए, फल में अधिकार न जताते हुए आगे बढ़ना चाहिए, यह कृष्ण का कर्मसिद्धांत है। यहाँ अर्जुन का यह सोचना गलत नहीं है कि वह धर्म की रक्षा के लिए, धर्म की विजय के लिए युद्ध करता है। इस स्तर पर हार-जीत के बारे में न सोचते हुए, उसे पूर्ण रूप से भगवान को अर्पित करके, अपने हिस्से आए कर्तव्य को निष्ठा से अपनी शक्ति से बढ़कर निभाना उसका धर्म है। ऐसा करने पर युद्ध के हर चरण में आने वाला परिणाम उसे विचलित नहीं कर सकता। जो भी परिणाम आए उसे भगवान का प्रसाद मानकर स्वीकार करते हुए आगे बढ़ना चाहिए, बस इतना ही।",
  "2.48": "योगस्थः कुरु कर्माणि सङ्गं त्यक्त्वा धनञ्जय ।\n\nसिद्ध्यसिद्ध्योः समो भूत्वा समत्वं योगः उच्यते -- हे धनंजय, 'योग' में स्थित होकर कर्म करो — फल के संबंध को त्यागकर, काम सफल हो या असफल — समभाव से रहो। ऐसे समभाव को ही 'योग' कहते हैं।\n\nकोई भी कर्म करें, वह यूँ ही नहीं करना चाहिए। उसके पीछे एक योग होना चाहिए। भगवान फल देने वाले हैं, मुझसे कर्म करवाने वाले भी वही हैं। क्या फल, कितना फल, कब फल — यह सब उन्हीं का है। मिले तो खुशी, न मिले तो खुशी। यह भौतिक संतुलन है। ऐसे संतुलन में कर्तव्य दृष्टि से कर्म करना चाहिए। हमारे जीवन के हर कर्म में यह अनुसंधान हो तो वह भगवान की पूजा बन जाता है। यही कर्मयोग है।\n\nसिद्धि-असिद्धि को समभाव से देखना मन का योग है। यह एक मानसिक स्थिति है। ऐसे योग भाव से कर्म करने पर फल मिलने पर अहंकार नहीं होता, न मिलने पर दुःख नहीं होता। इस प्रकार सिद्धि-असिद्धि के समत्व से किया गया हर कर्तव्य भगवान की पूजा बन जाता है। इस अनुसंधान के बिना किया गया महायज्ञ भी पूजा नहीं बन सकता। भगवान ने मुझसे यह काम करवाया, यह भगवान की पूजा के रूप में अर्पित हो, ऐसा अनुसंधान होने पर ही कर्म-योग बनता है। हमारा मन भगवान में संयोग पाना ही योग है। इस अनुसंधान के सहायक और अनुसंधानपूर्वक किया गया हर कर्म कर्मयोग है।",
  "2.49": "दूरेण ह्यवरं कर्म बुद्धियोगाद्धनञ्जय ।\n\nबुद्धौ शरणमन्विच्छ कृपणाः फलहेतवः -- हे धनंजय, बोध के मार्ग से कर्म का मार्ग बहुत नीचा है। इसलिए बोध में स्थिर रहो। [बोध होने पर भी हरि की शरण लो।] फल को ही मानकर खड़े रहने वाले दया के पात्र हैं।\n\nसंसार में कुछ कर्मयोगी हैं, कुछ ज्ञानयोगी। कर्मयोगियों के पास ज्ञान नहीं है, तथा ज्ञान आने के बाद कर्म की आवश्यकता नहीं है, ऐसा कुछ लोगों का चिंतन है। कुछ कर्म को श्रेष्ठ कहते हैं, कुछ ज्ञान को श्रेष्ठ कहते हैं। कुछ लोग कर्म और ज्ञान को 'दो पहियों' की तरह समान मानने का तर्क देते हैं। इससे अनेक द्वंद्व पैदा होते हैं। परन्तु कृष्ण यहाँ स्पष्ट कहते हैं: ज्ञान के सामने कर्म बहुत दूर है। कर्म करते समय ज्ञान अत्यंत महत्वपूर्ण है। ज्ञान के लिए ही कर्म है, वह ज्ञान के समान नहीं है। इसलिए ज्ञान की शरण लेकर ज्ञान का सहायक कर्म करना चाहिए। ज्ञान के बिना, फल की आकांक्षा से कर्म करने वालों की स्थिति शोचनीय है। ये कर्म का रहस्य जाने बिना कर्म करते हुए तड़पते रहते हैं।\n\nज्ञान के मार्ग में ऊँचाई पर पहुँचने के लिए भी कर्म करना चाहिए। इससे भगवान का साक्षात्कार होता है। इस स्थिति में अहंकार न रखते हुए, भगवान ही मेरे रक्षक हैं और वही मेरा आश्रय है यह जानकर उनकी शरण लेनी चाहिए। मैंने स्वयं को भगवान को अर्पित कर दिया है, वे मेरी रक्षा करते ही करते हैं यह विश्वास ही शरणागति है।\n\nहमें कोई भी समस्या आने पर भगवान से प्रार्थना करनी चाहिए, अन्य किसी से नहीं। 'हे भगवान, मुझे इस समस्या में क्यों फँसाया? इसका समाधान दिखाओ, पिता' ऐसा मन से पूछने पर वे निश्चित रूप से हमें संकट से बचाते हैं। परन्तु यहाँ भी फल का अधिकार न जताते हुए, केवल भगवान पर विश्वास रखकर, हमारी सभी समस्याओं के बीच भी निश्चिंत होकर जीना सीखना चाहिए।\n\nअगले श्लोक को देखने से पहले यहाँ आए 'धनंजय' नाम विशेषण का अर्थ जानें। इस संबोधन के दो अर्थ हैं — एक लौकिक और एक आध्यात्मिक। लौकिक रूप से देखें तो अर्जुन ने कई जगह युद्ध करके देश की सीमा बढ़ाई, राजकोष की संपत्ति बढ़ाई — इसलिए वह धनंजय है। आध्यात्मिक रूप से देखें तो इस नाम का विशेष अर्थ है। भगवान की आराधना, अध्यात्म का बोध ही सच्चा धन है। भगवान का बोध, ज्ञान सबसे बड़ी संपत्ति है। अर्जुन उस काल के अपरोक्ष ज्ञानी थे। वे स्वयं इंद्र थे। वे ज्ञान की संपत्ति की पराकाष्ठा थे। 'ऐसे ज्ञानी तुम भगवान की शरण जाकर, बुद्धिपूर्वक कर्म करो' इस अर्थ में कृष्ण यह संबोधन करते हैं।",
  "2.50": "बुद्धियुक्तो जहातीह उभे सुकृतदुष्कृते ।\n\nतस्माद्योगाय युज्यस्व योगः कर्मसु कौशलम् -- भगवान को जानने वाला अनावश्यक पुण्य-पाप दोनों को यहीं छोड़ देता है। इसलिए बोध के 'योग' में लग जाओ। 'योग' यही है — जानकर करने की कुशलता।\n\nसमझदारी से कर्म करने पर मनुष्य अपने सारे पाप तथा अनावश्यक पुण्य को छोड़कर भगवान को प्राप्त करता है। यहाँ अनावश्यक पुण्य का अर्थ है: उदाहरण के लिए एक महात्मा अपने ज्ञान-कर्म से मोक्ष पाता है। इस मार्ग पर रहते हुए वह अन्य पुण्य भी अर्जित करता है। यदि उसने चक्रवर्ती बनकर शोभायमान होने का पुण्य पाया हो तो वह उसके लिए अनावश्यक पुण्य है, क्योंकि मोक्ष के सामने इस पुण्य की आवश्यकता उसे नहीं है। वह इस पुण्य को यहीं छोड़ देता है। इसे यहाँ अनावश्यक पुण्य कहा गया है। जो लोग इस प्रकार भगवत्-प्रज्ञा में जीते हैं, उनके द्वारा किया गया कर्म उनके पाप-पुण्य के बंधन का कारण नहीं बनता। इसलिए ज्ञानयोग में स्थित होकर उस बोध से कर्म करना बुद्धिमानी है।",
  "2.51": "कर्मजं बुद्धियुक्ता हि फलं त्यक्त्वा मनीषिणः ।\n\nजन्मबन्धविनिर्मुक्ताः पदं गच्छन्त्यनामयम् -- जानने वाले भगवान का बोध पाकर, कर्मफल का दायित्व उन्हें सौंपकर, जन्म-मृत्यु के बंधन से मुक्त होकर, क्लेशरहित पद को पाते हैं।\n\nसच्चे मनीषी अपने मन को स्वयं नियंत्रित कर सकने वाले जितेंद्रिय होते हैं। आत्मसंयम युक्त ज्ञान के मार्ग पर चलकर वह बोध पाने वाले। बुद्धिमान ज्ञानी कर्म से मिलने वाले फल के मोह को छोड़कर उसे भगवान को अर्पित करते हैं। इस प्रकार जो कर्मफल को भगवान को अर्पण की बुद्धि से त्यागकर निष्कपट भाव से कर्म करते हैं, वे कर्म करते हुए भी कर्मबंधन में नहीं फँसते, सभी बंधन तोड़कर दोषरहित मोक्ष पाते हैं। इसलिए कर्तव्य कर्म को भगवान की आराधना मानकर करके मोक्ष पाना चाहिए। इसे छोड़कर 'मैं ज्ञानी हूँ, मुझे कुछ नहीं करना' यह रवैया सही नहीं है।",
  "2.52": "यदा ते मोहकलिलं बुद्धिर्व्यतितरिष्यति ।\n\nतदा गन्तासि निर्वेदं श्रोतव्यस्य श्रुतस्य च -- जब तुम्हारी बुद्धि अज्ञान की गंदगी को पार कर जाएगी, तब आगे सुनने वाले और पहले सुने हुए उपदेश का पूरा फल पाओगे।\n\nकब हमारा पढ़ा-सुना सार्थक होता है? हमारी बुद्धि कितना भी सुनने पर भी बार-बार भ्रम में ही रहे तो कितना भी सुनने से कोई उपयोग नहीं है। पढ़ने-सुनने से हमारे मन की गंदगी धुल जानी चाहिए और मन निर्मल होना चाहिए।",
  "2.53": "श्रुतिविप्रतिपन्ना ते यदा स्थास्यति निश्चला ।\n\nसमाधावचला बुद्धिस्तदा योगमवाप्स्यसि -- पहले श्रुतियों के अनुकूल न रही, [फिर श्रुतियों से मेल खा गई] तुम्हारी बुद्धि जिस दिन सच्चे बोध से दृढ़ होकर समाधि में स्थिर होकर खड़ी रहेगी, उस दिन तुम लक्ष्य तक पहुँचोगे।\n\nयहाँ 'विप्रतिपन्ना' का अर्थ है 'मतभेद'। पहले श्रुतियों से (सुनने से) भ्रम होता है। फिर वहाँ से वेद की ओर जाने पर वेद में कही बात के विरुद्ध मन सोचता है। परन्तु एक बार मन निर्मल होने पर श्रुति में कहे गए त्रिगुणातीत तत्व में मन दृढ़ता से बैठ जाता है। पहले त्रैगुण्य विष जैसा था, फिर त्रैगुण्य के विष का निवारण होने लगता है (यापयति)। एक बार मन निर्मल होने पर वह वेद के साथ श्रुतिगूढ़ (tune) हो जाता है। इससे वेद में कही बात और हमारे विचारों में कोई अंतर नहीं दिखता। मन वैदिक वाङ्मय में स्थिर हो जाता है। इस स्थिति में ध्यान (Meditation) करने पर मन सदा भगवान में स्थिर रहता है। इससे भी आगे जाकर निश्चल समाधि स्थिति में, स्वरूप चिंतन में देखने पर भगवान का सच्चा रूप साक्षात्कार होता है। इस स्थिति में मन काम नहीं करता, आत्मा काम करती है। आत्मा की आँख से भगवान का साक्षात्कार होता है — यही साधना का पूर्ण फल है।",
  "2.54": "अर्जुन उवाच —\n\nस्थितप्रज्ञस्य का भाषा समाधिस्थस्य केशव ।\n\nस्थितधीः किं प्रभाषेत किमासीत व्रजेत किम् -- हे ब्रह्म-रुद्र के नियामक, समाधि पर चढ़ सकने वाले [समझ की गलतियाँ सुधार चुके] दृढ़ बोध वाले को कैसे पहचानें? ऐसा स्थितप्रज्ञ क्या बोलता है? कैसे बैठता है? कैसे चलता है?\n\nइस स्तर पर कृष्ण अपना उपदेश रोककर अर्जुन के प्रश्न को सुनते हैं। मनुष्य का बोध दृढ़ होना चाहिए; सत्य के साक्षात्कार से मनुष्य स्थितप्रज्ञ बन सकता है। ऐसे स्थितप्रज्ञ को हम कैसे पहचानें, यह अर्जुन का प्रश्न है। एक स्थितप्रज्ञ को उसके वेश-भूषण से पहचानना असंभव है। बाहरी संसार से न चिपककर अंतरंग संसार में समाधि की स्थिति तक पहुँचे उन्हें कैसे पहचानें? वे बाहरी संसार के साथ कैसे व्यवहार करते हैं? उनका आचरण-वाणी कैसी होती है? यह अर्जुन का प्रश्न है।\n\nयहाँ अर्जुन कृष्ण को 'केशव' कहकर संबोधित करता है। इस संबोधन से ही समझ में आता है कि अर्जुन स्वयं एक महाज्ञानी है। केशव का अर्थ है कह+ईश — कह अर्थात ब्रह्मशक्ति, ईश अर्थात शिवशक्ति। ब्रह्मशक्ति और शिवशक्ति के भीतर की परशक्ति ही केशव है। सूर्य की किरणों में रहकर पूरे जगत को शक्ति प्रदान करने वाले भगवान केशव हैं। 'जगत को प्रकाश देने वाले तुमसे मैं यह विषय सुनकर जानने को उत्सुक हूँ' — इस अर्थ में यह संबोधन है।\n\nमनुष्य के दुःख का मूल कारण उसकी क्षुद्र इच्छाएँ हैं। अपनी इच्छा पूरी न होने पर दुःख-क्रोध इत्यादि शुरू हो जाता है। इससे वह अपने जीवन को नरक बना लेता है। ऐसी स्थिति में उसे अपने भीतर की उस अपूर्व शक्ति का बोध नहीं होता। स्थितप्रज्ञ इस जंजाल में न फँसते हुए, अपने अंतरंग में उस महान आनंद को सदा चखते हुए प्रसन्न रहता है। वह इच्छाओं का शिकार नहीं होता। 'चाहिए' यह इच्छा उसे नहीं सताती। उसका मन सदा प्रसन्न रहता है। जीवन में कैसी भी समस्या आए वह कभी तनाव (Tension or Stress) का शिकार नहीं होता। उसका मन दृढ़ रहता है और इससे वह सफलता पा सकता है।\n\nयहाँ कृष्ण अर्जुन को 'पार्थ' कहकर संबोधित करते हैं। पार्थ अर्थात पार-तीर-गमन करने वाला, अर्थात सत्य के, साधना के सागर को पार करने वाला। 'साधना के सागर को पार करने वाले तुम्हें यह स्पष्ट रूप से जानना चाहिए' इस अर्थ में यह संबोधन है।\n\nआगे आने वाले तीन श्लोकों में कृष्ण इच्छाओं को छोड़ने का अर्थ क्या है और कैसे, यह बताते हैं।",
  "2.55": "प्रजहाति यदा कामान्सर्वान्पार्थ मनोगतान् ।\n\nआत्मन्येवात्मना तुष्टः स्थितप्रज्ञस्तदोच्यते -- हे पार्थ, मन में घर बनाई सभी इच्छाओं को छोड़ने पर, परमात्मा में ही स्थिर होकर, परमात्मा की कृपा से तृप्त होकर प्रसन्न रहने पर स्थितप्रज्ञ कहलाता है।\n\nकृष्ण सीधे स्थितप्रज्ञ के आचरण-वाणी के बारे में न बताते हुए, वह कैसा होता है यह पहले बताते हैं। सच्चे स्थितप्रज्ञ को मूल रूप से कोई इच्छा नहीं सताती (यहाँ इच्छा का अर्थ है मनुष्य को गलत रास्ते पर ले जाने वाली बुरी इच्छाएँ)। वह ऐसी सभी क्षुद्र इच्छाओं को छोड़कर अपने भीतर के ज्ञानानंदमय भगवान को देखते हुए सदा प्रसन्न रहता है।",
  "2.56": "दुःखेष्वनुद्विग्नमनाः सुखेषु विगतस्पृहः ।\n\nवीतरागभयक्रोधः स्थितधीर्मुनिरुच्यते -- संकट आने पर मन में हलचल नहीं। सुख की बातों में लालसा नहीं। किसी में भी राग नहीं, भय नहीं, क्रोध नहीं। ऐसा चिंतनशील स्थितप्रज्ञ कहलाता है।\n\nजीवन में सुख-दुःख दिन-रात जैसे हैं। यह निरंतर है और किसी को नहीं छोड़ता। कभी सुख हम बिना चाहे आता है। उसी तरह कभी दुःख माला की तरह पीछे लग जाता है। पैसे से दुःख को रोका नहीं जा सकता, सुख को खरीदा नहीं जा सकता। सामान्यतः दुःख आने पर हम उद्विग्न हो जाते हैं। इससे मन विचलित होता है, उससे शरीर का स्वास्थ्य बिगड़ता है। जो अनिवार्य है उसके बारे में रोते हुए बैठे रहने से कोई लाभ नहीं। रोते हुए बैठने से आया दुःख नहीं जाता, आने वाले दुःख को रोका नहीं जा सकता। दुःख 'सुख की तैयारी' है; सुख 'दुःख की तैयारी' है। ये जीवन के अनिवार्य द्वंद्व हैं। इसका अर्थ यह नहीं कि सुख आने पर प्रसन्न नहीं होना चाहिए, बल्कि उस सुख में डूब नहीं जाना चाहिए। मन को तटस्थता का अभ्यास कराना चाहिए। जीवन युद्ध में सुख-दुःख आपस में गुँथे हुए हैं यह सत्य जानकर जीवन बिताना चाहिए।\n\nदुःख आने पर मन को दृढ़ करके जीना चाहिए ऐसा कहना आसान है। परन्तु उसे जीवन में अपनाना उतना ही कठिन है। इसका उदाहरण है महाभारत युद्ध में अभिमन्यु के मरने पर आँसू बहाने वाला अर्जुन। स्वयं भगवान से उपदेश पाकर, भगवान की सारथी में युद्ध में उतरा स्थितप्रज्ञ अर्जुन, अपने पुत्र अभिमन्यु के मरने पर दुःखी होता है। हमें दुःख को स्वीकार करने का अभ्यास करना चाहिए। नहीं तो जीवन असह्य हो जाता है।\n\nकिसी भी वस्तु के बारे में तीन बातें मन में नहीं होनी चाहिए। वे हैं राग-भय-क्रोध। दुःख की पूर्व स्थिति भय है; भय की उत्तर स्थिति दुःख है! अधिक चाहना — राग, चाही वस्तु न मिलने पर — निराशा। वह वस्तु हमसे कमज़ोर को मिले तो उन पर क्रोध; हमसे बलवान को मिले तो उनसे भय! ये सब मन का हिचकोला है। व्यास ने कहा है — 'इस जगत में अब तक न होने वाला कुछ भी नहीं हुआ, और आगे भी नहीं होगा'। जो होना है वह होकर ही रहता है, उसके बारे में चिंता करने से कोई लाभ नहीं। ऐसी चिंतनशीलता को अपनाने वाला स्थितप्रज्ञ कहलाता है।\n\nयहाँ मुनि शब्द का प्रयोग हुआ है। मुनि का अर्थ है काम-क्रोध को जीतने वाला। हमें मन को हर परिस्थिति में एकरूप तटस्थ रखने का प्रयास करना चाहिए। जो भी आए आने दो, भगवान की कृपा बनी रहे कहकर जीवन में सुख-दुःख को समदृष्टि से देखने वाला मुनि है। 'तुम भी ऐसे मुनि बनो' यही यहाँ संदेश है।",
  "2.57": "यः सर्वत्रानभिस्नेहस्तत्तत्प्राप्य शुभाशुभम् ।\n\nनाभिनन्दति न द्वेष्टि तस्य प्रज्ञा प्रतिष्ठिता -- जब-जब भला-बुरा घटित होता है, कहीं भी अत्यधिक चिपकता नहीं है। भले के प्रति प्रशंसा नहीं है। बुरे के प्रति क्रोध नहीं है। ऐसे व्यक्ति का बोध दृढ़ रहता है।\n\nयहाँ कृष्ण कहते हैं — 'दुःख आने पर विचलित मत हो, सुख आने पर फूल मत जाओ, निर्लिप्तता का अभ्यास करो। किसी भी चीज़ पर अत्यधिक आसक्ति (Over attachment) मत रखो। मन का संतुलन साधो।' दुःख किसी को नहीं छोड़ता। देवांश से जन्मे पांडवों ने जो कष्ट सहा उसे देखने पर यह स्पष्ट है। ज्ञानी हो या अज्ञानी, सबको कष्ट आता है। हमें कष्ट को देखने की मनःस्थिति बदलनी है, बस। 'मुझे चाहिए-नहीं चाहिए से परे खड़ा हूँ, यह चाहिए ही, यह नहीं चाहिए' यह चुनने का अधिकार मुझे नहीं है, यह सत्य जानकर जीने पर जीवन सुगम होता है। ऐसा व्यक्ति ऊँचाई तक उठता है।\n\nज्ञानियों में ऐसी मनःस्थिति होती है। हम सामान्य मनुष्यों के लिए इंद्रिय-निग्रह बहुत कठिन है। परन्तु असंभव नहीं है। निरंतर साधना से इसे साधा जा सकता है। किस प्रकार साधक इंद्रिय-निग्रह करके साधना करे यह दृष्टांत सहित कृष्ण अगले श्लोक में बताते हैं।",
  "2.58": "यदा संहरते चायं कूर्मोऽङ्गानीव सर्वशः ।\n\nइन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता -- जैसे कछुआ अपने अंगों को पूरी तरह खोल में खींच लेता है, वैसे ही इंद्रियों को इंद्रिय-विषयों से पीछे खींचने वालों का बोध दृढ़ रहता है।\n\nहमारी इंद्रियाँ हमें भटका देती हैं। जो नहीं चाहिए वही चाहिए यह इच्छा पैदा करती हैं। यहाँ कृष्ण कहते हैं: जैसे कछुआ अपने चार पैर और सिर को अपने खोल में पूरी तरह खींचकर सुरक्षित रहता है, वैसे ही हमें अपनी पंचेंद्रियों को दृढ़ मन के किले में खींचकर अंतर्मुख करना चाहिए। यहाँ अंतर्मुख करने का अर्थ है देखने की दृष्टि बदलना। सब कुछ को अंतरंग दृष्टि से विश्लेषण करके उसमें अच्छाई पहचानकर ग्रहण करना। उसे बनाने वाले भगवान की महिमा का अनुसंधान करना।\n\nहम भगवान द्वारा बनाए इस संसार को देखते हैं। देखते हुए उसके पीछे रहने वाली उस विश्वशक्ति की महिमा सोचें तो वह अंतर्मुख अंतर्दृष्टि बन जाती है। सब कुछ के भीतर भगवान हैं यह सजगता, हर अभिव्यक्ति में भगवान की एक-एक विभूति है यह समझ होने पर, कुछ भी हमें रास्ते से भटका नहीं सकता। यह ज्ञानी की संसार को देखने की दृष्टि है। हम संसार को बदल नहीं सकते। संसार को अपनी इच्छानुसार नियंत्रित नहीं कर सकते यह सत्य जानकर, संसार जैसा है उसके अनुरूप जीने की मनोवृत्ति विकसित करने पर कोई समस्या नहीं है। इस प्रकार अपनी इंद्रियों को अंतर्मुख करने वाले का बोध दृढ़ रहता है।",
  "2.59": "विषया विनिवर्तन्ते निराहारस्य देहिनः ।\n\nरसवर्जं रसोऽप्यस्य परं दृष्ट्वा निवर्तते -- आहार त्यागने वाले जीव को विषय-भोग की शक्ति ही कम होती है — जीभ की चाहत और भोग की इच्छा को छोड़कर। ऐसी चाहत-इच्छा भी भगवान को देखने पर समाप्त हो जाती है।\n\nहमने देखा कि स्थितप्रज्ञ बनने के लिए इंद्रियों को अंतर्मुख करना चाहिए। परन्तु यह इतना आसान विषय नहीं है। साधना शरीर में रहने वाला साधक, इंद्रियों को बाहरी विषयों से संपर्क न होने दे (एकांत का अभ्यास) तो देखने-सुनने की सभी इच्छाएँ चली जा सकती हैं। परन्तु स्वाद (जीभ की चपलता) और शृंगार (यौन इच्छा) को दूर करना बहुत कठिन है। इस कारण ब्रह्मचर्य पालन करना हो तो एक बार शृंगार भोग का अनुभव करके, दांपत्य क्या है यह जानकर, फिर ब्रह्मचर्य में कदम रखने पर साधना आसान होती है। नियमित आहार, उपवास अध्यात्म के लिए सहायक हैं। अति आहार, तामस और राजस आहार (उदाहरण: तुअर दाल, प्याज़, लहसुन, सहजन, अधिक मसालेदार पदार्थ, मांसाहार इत्यादि) अध्यात्म साधना के बिल्कुल विरुद्ध हैं। (इस कारण जब भी अतिथि आएँ उन्हें ज़बरदस्ती भोजन नहीं देना चाहिए; बनाया खाना बचने पर खराब होगा सोचकर खाने से भोजन भी बिगड़ता है और शरीर भी बिगड़ता है!) कुल मिलाकर अध्यात्म साधना में एकांत और आहार नियंत्रण साधना के सहायक हैं। इससे हमारी जीभ और भोग की चपलता पूर्ण रूप से न भी रुके, तो भी वे भगवान में पूर्ण शरण होने पर समाप्त हो जाती हैं।",
  "2.60": "यततो ह्यपि कौन्तेय पुरुषस्य विपश्चितः ।\n\nइन्द्रियाणि प्रमाथीनि हरन्ति प्रसभं मनः -- साधक चाहे कितना भी जान ले, कितना भी प्रयत्न करे, इंद्रियाँ बलपूर्वक मन को हिलाकर खींच लेती हैं।\n\nहम कितना भी पढ़-सुनकर जान लें, साधना का यह मार्ग इतना आसान नहीं है। प्रयत्न के हठ के बिना यह असंभव है। अध्यात्म के मार्ग पर चलने के लिए मन दृढ़ होना चाहिए। परन्तु यहाँ एक समस्या है। वह यह कि मन दृढ़ होने पर इंद्रियाँ ढीली हो जाती हैं। राग-द्वेष नहीं करना चाहिए, काम-क्रोध के अधीन नहीं होना चाहिए, इच्छा पर लगाम होनी चाहिए — ऐसा दृढ़ मन में निश्चय करके बैठने पर इंद्रियाँ मन को भ्रमित कर देती हैं। शास्त्र पढ़कर परोक्ष रूप से सत्य को देखने वाले को भी यह समस्या नहीं छोड़ती। बलपूर्वक इंद्रियाँ मन को भटका देती हैं। इससे पहले जो माना था उसे मानना चाहिए या छोड़ना चाहिए यह संशय पैदा होता है। यह हर साधक जीव के अनुभव में आने वाली बात है। यह समस्या गंभीर दिखने पर भी कृष्ण अगले श्लोक में इसका सरल समाधान बताते हैं।",
  "2.61": "तानि सर्वाणि संयम्य युक्त आसीत मत्परः ।\n\nवशे हि यस्येन्द्रियाणि तस्य प्रज्ञा प्रतिष्ठिता -- उन सबको रोककर, मुझे ही परतत्व मानकर, मुझमें ही मन लगाकर बैठना चाहिए। इस प्रकार इंद्रियों को जीतने वाले का बोध दृढ़ रहता है।\n\nइंद्रियों से मन का विचलित होना, या मन से इंद्रिय को अनावश्यक कार्य में लगाना — यह सबको सताने वाली समस्या है। इस समस्या से बाहर आने के लिए हमें इंद्रिय रूपी घोड़ों को वश में करके, मन रूपी लगाम में उन्हें बाँधकर, वह ढीली न हो इस प्रकार पकड़े रखना चाहिए। इस कार्य को सफलतापूर्वक करने के लिए पहले हमें भगवान की शरण लेनी चाहिए। 'यह दायित्व मुझे सौंपो' ऐसा कृष्ण कहते हैं। कैसा भरोसा? 'मेरी इंद्रियाँ रास्ता न भटकें, इसलिए मेरे भीतर रहकर प्रेरित करो भगवान; तुम्हारे चिंतन की शक्ति निरंतर मेरे मन में बनी रहे' ऐसा भगवान से प्रार्थना करनी चाहिए। भगवान की शरणागति पाए बिना सब कुछ स्वयं के प्रयत्न से करूँगा कहना असंभव है। प्रयत्न करना चाहिए, प्रयत्न में जय मिले इसके लिए भगवान से माँगकर, उनकी शरण में जाने पर, एक न एक दिन अनुभूति की कृपा होती है। तब पूर्ण इंद्रिय-निग्रह संभव होता है। यह साधना अनेक जन्मों की है। दस दिन साधना करके निराश होकर श्रद्धाहीन न होते हुए, निरंतर साधना करने पर सफलता हमारी होती है। जिसकी इंद्रियाँ उसके वश में आ गईं, उसका बोध दृढ़ होता है। वह जीवन में, साधना के मार्ग में जीतता है।",
  "2.62": "हमारे पतन का कारण हमारा मन कैसे बनता है, यह कृष्ण अगले दो श्लोकों में बताते हैं। मनुष्य का मन कैसे काम करता है इसका एक अद्भुत मानसिक चित्रण यहाँ है।\n\nध्यायतो विषयान्पुंसः सङ्गस्तेषूपजायते ।\n\nसङ्गात्सञ्जायते कामः कामात्क्रोधोऽभिजायते -- विषयों का ही चिंतन करने वाले मनुष्य में उनका लगाव बढ़ता है। लगाव से इच्छा पैदा होती है। इच्छा में बाधा आने पर क्रोध उत्पन्न होता है।",
  "2.63": "क्रोधाद्भवति सम्मोहः सम्मोहात्स्मृतिविभ्रमः ।\n\nस्मृतिभ्रंशाद्बुद्धिनाशो बुद्धिनाशात्प्रणश्यति -- क्रोध से न करने योग्य को करने की इच्छा होती है (गलत समझ)। ऐसी इच्छाओं से विधि-निषेध का विस्मरण होता है। विस्मरण से नासमझी, नासमझी से सर्वनाश!\n\nकिसी वस्तु के निरंतर संपर्क से उस पर मोह बढ़ता है। पहले परिचय, परिचय से स्नेह, फिर उस स्नेह को अपनाना (attachment)। फिर वे मेरे बनने चाहिए यह इच्छा। हमने जो चाहा वह पूरा न होने पर क्रोध। इस क्रोध का मूल प्रेम है! क्रोध का मूल कारण इच्छा है। हमें क्रोध न आए इसके लिए पहले इच्छा को त्यागना चाहिए। इच्छा कम होने पर क्रोध कम होता है। चिपकने या अपनाने से इच्छाएँ-आकांक्षाएँ बढ़ती हैं। वह पूरी न होने पर क्रोध। क्रोध से सम्मोह, अर्थात असंगत विचार सिर में आकर न करने योग्य को करने की इच्छा। इससे उचित-अनुचित का विश्लेषण करने की शक्ति चली जाकर, गलत को ही सही मानकर समर्थन करने के स्तर तक हम उतरते हैं। परिणाम: बदला लेना ही है यह हठ। इससे पूर्ण नासमझी और अंत में आत्मा का पतन — विनाश — सर्वनाश!\n\nबुद्धि नष्ट होने पर मन मरे हुए के समान। इससे जीव नरक के रास्ते पर जाने लगता है। यह पतन का रास्ता है। हमें ऊँचाई पर उठना है तो परमात्मा का महत्व जानकर उनकी शरण लेनी चाहिए। अच्छे रास्ते पर मन चिंतन करने पर आत्मा ऊँचाई पर उठ सकती है। इसके लिए पहले हमें अपनाने (attachment) को कम करना चाहिए। इसका अर्थ यह नहीं कि किसी से प्रेम न करें, स्नेह न बढ़ाएँ। प्रेम रहे, स्नेह रहे, परन्तु मोह न हो। जो आया वह आए यह दृढ़ निश्चय रहे। ऐसा ही होना चाहिए, वैसा ही होना चाहिए यह अति-मोह दुःख का कारण है। सबके साथ रहकर, सबसे प्रेम करना — परन्तु अपनाए बिना (attachment) रहना — यही साधना और प्रसन्नता का मूल मंत्र है।\n\nमन सदा प्रसन्न रहना चाहिए। प्रसन्नता न रहने पर मानसिक और शारीरिक रूप से हम स्वास्थ्य खो देते हैं। किसी भी प्रसंग में सिर न बिगाड़ते हुए सहज रहना प्रसन्नता है। इसे पाना कैसे है यह चित्रण अगला श्लोक है।",
  "2.64": "रागद्वेषवियुक्तैस्तु विषयानिन्द्रियैश्चरन् ।\n\nआत्मवश्यैर्विधेयात्मा प्रसादमधिगच्छति -- राग-द्वेष से मुक्त होकर, अपने वश में रही इंद्रियों से विषयों का अनुभव करते हुए भी, संयमित व्यक्ति का मन निर्मल होता है।\n\nइंद्रिय-निग्रह या न अपनाना यानी सभी विषय-भोगों को त्यागकर सांसारिक व्यवहार से दूर होकर आँखें मूँदकर बैठना नहीं है। इंद्रिय से विषय ग्रहण करो, वह निरंतर है। परन्तु उससे प्रभावित होकर उसका दास मत बनो, ऐसा कृष्ण कहते हैं। विषयों को इंद्रियों से अनुभव करो, परन्तु विषयों से राग-द्वेष की आदत मत जोड़ो। जो आया वैसे ही अनुभव करो। ऐसी मनोवृत्ति विकसित करने पर इंद्रिय कोई भी विषय ग्रहण करे, कोई खतरा नहीं। तटस्थ मन से कोई भी विषय सुनने-देखने से कोई खतरा नहीं है। यहाँ तटस्थ मन का उदाहरण है — कभी-कभी हम अपने मित्रों से रास्ते में मिलते हैं। हम वहाँ बैठकर बातचीत करते हैं। परन्तु फिर कोई आकर पूछे तुम्हारा मित्र किस रंग का कपड़ा पहना था, तो हमें पता नहीं होता। हमने देखा, परन्तु ध्यान नहीं दिया, क्योंकि उसकी आवश्यकता नहीं थी। इसी तरह मन को तटस्थ रखकर कोई भी विषय ग्रहण करने पर खतरा नहीं है। इससे इंद्रियाँ अधीन रहती हैं, मन विनम्र रहता है। भीतर से निर्लिप्तता विकसित करने पर सबके साथ रहते हुए एकांतता पाई जा सकती है। सबके साथ मिलकर भी अलग रहा जा सकता है। यह अंतरंग संसार में अलग रहने की स्थिति है। इस तरह जीना सीखने पर मन निर्मल होता है। सदा प्रसन्नता उमड़ती रहती है। साधना सुगम होती है।",
  "2.65": "प्रसादे सर्वदुःखानां हानिरस्योपजायते ।\n\nप्रसन्नचेतसो ह्याशु बुद्धिः पर्यवतिष्ठते -- मन निर्मल होने पर साधक के सभी दुःख समाप्त हो जाते हैं, क्योंकि जिसका मन निर्मल हो गया है उसकी बुद्धि शीघ्र ही भगवान में स्थिर हो जाती है।\n\nमन गंदा हो तो सब कुछ गंदा। मन निर्मल हो तो सब कुछ निर्मल। सारी समस्या मन के गंदे होने से है। हमें अपने मन की स्वच्छता पर ध्यान न हो तो बाकी सारा कार्य व्यर्थ है। मन स्वच्छ हो तो शुद्ध — यही प्रसन्न स्थिति है। मन निर्मल होने पर सारा दुःख अपने आप ओझल हो जाता है। यह दुःखातीत आनंद की स्थिति है।\n\nमन निर्मल होना यानी वह भगवान को जानने में सहायक होता है। गंदे मन से भगवान का चिंतन संभव नहीं। भगवान को जानने के बाद दुःख नहीं रहता। बुद्धि दृढ़ होकर भगवान के अपरोक्ष ज्ञान में स्थिर हो जाती है। इस स्थिति में, विचार जिस भी दिशा में जाए, वह भगवान में ही जाकर ठहरता है। जो भी सुनें, जो भी देखें, उसके पीछे रहने वाली संसार की मूल शक्ति का चिंतन मन में आ जाता है। तब किसी छोटी बात के लिए दुःखी होने का प्रश्न ही नहीं रहता। निर्मल मन भगवन्मय हो जाता है। एक बार भगवान मन में भर जाएँ तो सब कुछ आनंदमय। उसके बाद दुःख नाम की चीज़ नहीं रहती। यह आनंद असीम है।",
  "2.66": "नास्ति बुद्धिरयुक्तस्य न चायुक्तस्य भावना ।\n\nन चाभावयतः शान्तिरशान्तस्य कुतः सुखम् -- मन को न साधने वाले की निर्मल बुद्धि नहीं होती। मन न साधने वाले का ध्यान भी नहीं होता। ध्यान न होने पर मुक्ति नहीं [भगवान में मन स्थिर नहीं होता]। मुक्त न होने वाले [भगवान में मन न लगाने वाले] को कहाँ का सुख?\n\nसुख चाहिए तो शांति चाहिए। मन प्रसन्न न होकर विक्षिप्त हो तो वह भगवान तक नहीं पहुँचता। जिसका मन भगवान में संयोग नहीं पाता उसे अपरोक्ष ज्ञान नहीं होता। ऐसे व्यक्ति का मन निर्मल नहीं होता। ऐसे लोग एकाग्रता से चिंतन नहीं कर सकते। एकाग्र चिंतन के बिना यथार्थ ज्ञान नहीं। ऐसे लोगों के लिए ध्यान असंभव है। यहाँ ध्यान का अर्थ है एकाग्रता से किसी वस्तु का चिंतन। किसी भी वस्तु के बारे में निश्चित बोध पाने के लिए एकाग्रता चाहिए। इसे ही यहाँ 'भावना' कहा गया है। मन एकाग्र हो तो ही गहरा चिंतन संभव है। किसी को भी गहराई से न सोचने पर उसके बारे में, उसकी व्यापकता के बारे में बोध नहीं होता। इस तरह गहराई में उतरकर चिंतन न करने वाले को शांति नहीं। यहाँ शांति के दो अर्थ हैं। ऊपरी दृष्टि से शांति यानी आनंदमय स्थिति। शास्त्रकारों के अनुसार जीव के लिए पूर्ण आनंद की स्थिति यानी मोक्ष। इसलिए जो ध्यान से भगवान को नहीं पाता उसे मोक्ष नहीं। मोक्ष के मार्ग पर न चलने वाले को सुख नहीं। फिर शांति का अर्थ है आनंद की पराकाष्ठा। मन भगवान में स्थिर होने पर हमें शांति मिलती है।\n\nइस तरह इंद्रियों को संयमित करके, मन को एकाग्र करके, उसमें गहराई से चिंतन करके, सत्य को पाना चाहिए। हम बाहरी संसार को छोड़कर भीतरी संसार में गहराई से न डूबें तो सत्य का साक्षात्कार नहीं होता। सत्य के साक्षात्कार के बिना सुख नहीं।",
  "2.67": "इन्द्रियाणां हि चरतां यन्मनोऽनुविधीयते ।\n\nतदस्य हरति प्रज्ञां वायुर्नावमिवाम्भसि -- विषयों की ओर बहने वाली इंद्रियों के पीछे चलने के लिए ही मन बना है, है न? इसलिए वह साधक के बोध को भटका देता है — जैसे समुद्र में तूफान जहाज़ को रास्ते से भटका देता है।\n\nइतनी गहरी बात होने पर भी मन अंतरंग की गहराई में क्यों नहीं उतरता? यह स्वाभाविक है, ऐसा कृष्ण कहते हैं। क्योंकि मन का एक स्वभाव है। हमने उसे जिसका अभ्यास कराया, वही उसे पसंद आता है। नए को वह अस्वीकार करता है, तथा परिचित को ही वह पसंद करता है। मन के लिए भीतरी संसार अपरिचित है। इसलिए वह भीतरी संसार की ओर नहीं बहता। मन से दृढ़ता से कहें तो वह अंतर्मुख हो जाता है, परन्तु वह प्रयत्न हम नहीं करते! इस खतरे को कृष्ण इस श्लोक में बताते हैं।\n\nबचपन से हमने मन को जो अभ्यास कराया वह उसी के पीछे जाता है। उदाहरण के लिए बचपन से शाकाहारी रहे व्यक्ति को मांस देखने पर घिन आती है। परन्तु वही मांस बेचने वाला मांस के बीच रहकर उसे पकाकर खाए तो भी उसे घिन नहीं आती। यह सब मन को दी गई हमारी ट्रेनिंग है। मन निरंतर जो देखता है उसी की आदत बना लेता है। इस तरह मन भगवान द्वारा बनाया गया है। इंद्रियाँ नित्य जो देखती हैं उसे पसंद करने वाला स्वभाव भगवान ने मन को दिया है। मन के इस स्वभाव को न जानना खतरनाक है। यह हमारे बोध को चुरा लेता है। इसे एक अच्छे दृष्टांत से कृष्ण बताते हैं:\n\nहम पाल वाली नाव में यात्रा करने वाले नाविक जैसे हैं। हमारा मन उस नाव में बँधा कपड़ा है। यदि हमें इस कपड़े को मोड़कर अपनी इच्छानुसार नाव को नियंत्रित करने की कला न आए, तो हवा जिधर बहे उधर ही हम जाएँगे, न कि जहाँ पहुँचना है वहाँ। यह दृष्टांत बहुत उचित है। यदि हम अपने मन को नियंत्रित करने की कला न सीखें तो जीवन छिन्न-भिन्न हो जाता है। तूफान में फँसे सूखे पत्ते जैसा हो जाता है — यह चेतावनी कृष्ण यहाँ देते हैं।",
  "2.68": "तस्माद्यस्य महाबाहो निगृहीतानि सर्वशः ।\n\nइन्द्रियाणीन्द्रियार्थेभ्यस्तस्य प्रज्ञा प्रतिष्ठिता -- इसलिए हे महावीर, जिसकी इंद्रियाँ सभी प्रकार से इंद्रिय-विषयों से मुक्त होकर वश में हैं, उसका बोध दृढ़ रहता है।\n\nकृष्ण कहते हैं, मन सदा बाहरी इंद्रियों ने जिसका अभ्यास किया है उसी के पीछे जाता है। इंद्रियों को नियंत्रित किए बिना मन को नियंत्रित करना कठिन है। इसलिए पहले हमें इंद्रियों को प्रशिक्षित करना चाहिए। इसके लिए छोटे बच्चों को उत्तम संस्कार सिखाना अत्यंत महत्वपूर्ण है। बचपन से चले आ रहे अभ्यास को तोड़ना असंभव है। इस कारण पहले स्कूल में तथा घर में अनेक संस्कार डालकर बच्चों को प्रशिक्षित किया जाता था। परन्तु आज न स्कूल में, न घर में ऐसा मार्गदर्शन बच्चों को मिल पाता, आज की युवा पीढ़ी तूफान में फँसी नाव जैसी हो गई है। इंद्रिय-निग्रह के लिए सहायक संस्कार बचपन से मिले तो इंद्रियाँ मन को भटकाने की स्थिति नहीं आती। इससे मन दृढ़ होता है। एकाग्रता संभव होती है। एकाग्रता आने पर बोध दृढ़ होता है।\n\nमन को कैसे नियंत्रित करें, नियंत्रित मन कैसा व्यवहार करता है, ऐसी मनःस्थिति वाले कैसे ज्ञानी बन सकते हैं — इसका एक विस्तृत मनोविश्लेषण कृष्ण ने किया। अर्जुन के मूल प्रश्न का उत्तर कृष्ण अगले श्लोक में देते हैं। एक स्थितप्रज्ञ कैसा होता है, उसका आचरण-वाणी कैसी होती है इस प्रश्न का महत्वपूर्ण उत्तर कृष्ण यहाँ देते हैं।",
  "2.69": "या निशा सर्वभूतानां तस्यां जागर्ति संयमी ।\n\nयस्यां जाग्रति भूतानि सा निशा पश्यतो मुनेः -- जो सब प्राणियों के लिए अंधेरी गुत्थी है, वहाँ इंद्रियों को जीतने वाला योगी जागृत रहता है। जहाँ सब प्राणी जागते हैं, वह ज्ञानी चिंतक के लिए घोर रात्रि है।\n\nसामान्य मनुष्य के लिए जो दिन है, वह सत्य के साक्षात्कार वाले के लिए रात्रि है। संसार के सभी प्राणियों के लिए जो रात्रि है वह साधक के लिए दिन है। अर्थात सच्चा साधक हमारी रात्रि में जागृत रहता है, और सांसारिक व्यवहार रूपी हमारा दिन उसके लिए रात्रि है। सांसारिक संसार में उसकी कोई प्रवृत्ति नहीं रहती। वह हमें एक भोला-भाला, बच्चे जैसा दिख सकता है। उसके ज्ञान के बारे में न जानने वाले को वह पागल जैसा लगे तो आश्चर्य नहीं! क्योंकि वह सांसारिक संसार के साथ रहते हुए भी उसमें घुले बिना अपने अंतरंग के आनंद को सदा चख रहा होता है। एक ज्ञानी भगवान को देखने पर उसे बाकी सब अंधकार लगता है। अद्भुत बात देखने के विस्मय में एकचित्त होकर वही देखता रहता है। भगवान को देखने के लिए हमें सदा शास्त्र का श्रवण करना चाहिए। केवल श्रवण पर्याप्त नहीं, श्रवण के बाद मनन-निदिध्यासन अत्यंत महत्वपूर्ण है। इसे ही 'आत्मा वा अरे द्रष्टव्यः श्रोतव्यः मन्तव्यः निदिध्यासितव्यः च' कहा गया है। मनन करने वाला 'मुनि'; वही 'पश्य' अर्थात भगवान को देख सकने वाला या देख चुका।\n\nआज के समाज में सत्य का साक्षात्कार पाए व्यक्ति को पहचानना बहुत कठिन है। सिद्ध पुरुष सभी सत्य को देखने वाले नहीं हैं! चमत्कार करने वालों को भगवान को देखने वाला नहीं कहा जा सकता। क्योंकि सच्चा साधक सामान्यतः चमत्कार नहीं करता। बहुत अनिवार्य होने पर ही वह संसार की भलाई के लिए चमत्कार कर सकता है। निरंतर सत्य की खोज करके सिद्धि पाने पर ही स्थितप्रज्ञ बना जा सकता है।",
  "2.70": "आपूर्यमाणमचलप्रतिष्ठं समुद्रमापः प्रविशन्ति यद्वत् ।\n\nतद्वत्कामा यं प्रविशन्ति सर्वे स शान्तिमाप्नोति न कामकामी -- भरने पर भी न छलकते हुए स्थिर समुद्र में जैसे सभी नदियाँ आकर मिलती हैं, वैसे ही जिसमें सभी विषय भरकर भी न छलकाएँ ऐसे आकर मिलें, वह मुक्ति पाता है, न कि बुरी इच्छाओं के पीछे भागने वाला।\n\nभगवान को देखने वाला, सत्य का साक्षात्कार पाया हुआ व्यक्ति, भगवान को देखने के सही रास्ते पर चलने वाला कैसा होता है इस पर कृष्ण यहाँ और विवरण देते हैं: उसका मन सदा आनंदित रहता है। वह भगवान में स्थिर रहता है। वह छोटी धाराओं जैसा नहीं, समुद्र जैसा होता है। समुद्र में सभी नदियाँ आकर मिलें तो भी वह उफनता नहीं। समुद्र बारिश आने पर उफनकर बहता नहीं, गर्मी आने पर सूखता नहीं। वैसे ही साधक। संसार के सभी भोग उसमें प्रवेश करें तो भी, वह विचलित हुए बिना सुख-दुःख से परे खड़ा रहता है। उसका मन सदा प्रसन्न रहता है। वह भगवान में निष्ठा रखकर मोक्ष पाता है। परन्तु इच्छाओं के पीछे भागने वाला उनसे बाहर न आकर कभी सच्चा सुख नहीं पा सकता।",
  "2.71": "विहाय कामान्यः सर्वान्पुमांश्चरति निःस्पृहः ।\n\nनिर्ममो निरहङ्कारः स शान्तिमधिगच्छति -- जो सभी विषयों में मन खोए बिना, बुरी इच्छा का शिकार हुए बिना, मैं-मेरा यह अहंकार त्यागकर अनुभव करता है, वह मुक्ति पाता है।\n\nजो भोग की इच्छा छोड़कर जो आया उसे प्रसन्नता से अनुभव करता है, वह सच्चा साधक कहलाता है। सीमित आहार, नींद और मैथुन का अभ्यास करके, निर्भय होकर पूर्ण भगवान के रक्षा कवच के ज्ञान में रहकर, इच्छा-आकांक्षाओं का शिकार हुए बिना, किसी भी उतार-चढ़ाव से विचलित हुए बिना जीता है। वह सच्चा 'मनुष्य' कहलाता है। ऐसे व्यक्ति को मैं-मेरा यह अहम् कभी नहीं होता तथा वह मुक्ति पाता है।",
  "2.72": "एषा ब्राह्मी स्थितिः पार्थ नैनां प्राप्य विमुह्यति ।\n\nस्थित्वास्यामन्तकालेऽपि ब्रह्मनिर्वाणमृच्छति -- हे पार्थ, यह ब्रह्मज्ञानी की पहचान है। इसे पाकर फिर मोह नहीं होता। अंत काल में भी इस स्थिति में रहने वाला शरीर से भी न मरने वाले परतत्व को प्राप्त करता है।\n\nभगवान में स्थिर होने वाले का लक्षण ब्राह्मी स्थिति है। अब तक जो कहा गया वह एक ब्रह्मज्ञानी का लक्षण है। ब्रह्म में स्थित ब्रह्मप्रज्ञा जागृत व्यक्ति का लक्षण। ऐसे ब्रह्मज्ञानी को उसकी बाहरी क्रिया से या वेश-भूषण से नहीं पहचाना जा सकता। उसकी मानसिक स्थिति ही उसका स्थान बताती है।\n\nअपनी मृत्यु के अंतिम क्षण में भी भगवान की प्रज्ञा जागृत रहे तो वह सीधे पुनर्जन्म रहित मोक्ष पाता है।\n\nइस प्रकार दूसरा अध्याय समाप्त हुआ।\n\nअध्याय तीन\n\nदूसरे अध्याय में भगवान का बोध, उस बोध को पाने का उपाय कृष्ण ने बताया। इस उपदेश में एक ओर ज्ञान सबसे श्रेष्ठ है, ज्ञान के सामने कर्म कुछ भी नहीं है ऐसा कृष्ण कहते हैं। दूसरी ओर अर्जुन से तामसिक युद्ध करने को कहते हैं! ज्ञान ही सबसे श्रेष्ठ है तो यह तामसिक राग-द्वेष वाला युद्ध क्यों चाहिए? तीसरा अध्याय अर्जुन के इसी प्रश्न से शुरू होता है।\n\nअर्जुन उवाच —\n\nज्यायसी चेत्कर्मणस्ते मता बुद्धिर्जनार्दन ।\n\nतत्किं कर्मणि घोरे मां नियोजयसि केशव -- हे जनार्दन, यदि कर्म से बुद्धि श्रेष्ठ है यह तुम्हारा मत है, तो फिर मुझे इस घोर मारने वाले कार्य में क्यों लगा रहे हो, हे केशव?\n\nकृष्ण के ज्ञान और कर्म के बारे में दिए गए विवरण से अर्जुन भ्रमित हो जाता है। उसे कौन सा मार्ग उचित है यह प्रश्न सताता है। कृष्ण कभी ज्ञान मार्ग पर चलो, वह श्रेष्ठ है कहते हैं; कभी युद्ध करो कहते हैं! खुद क्यों श्रेष्ठ ज्ञान मार्ग पर न चले, युद्ध ही क्यों करना चाहिए यह भ्रम अर्जुन का है। इस भ्रम में अर्जुन कृष्ण से पूछता है: 'हे जनार्दन, कर्म से ज्ञान मार्ग श्रेष्ठ है यह तुम्हारा मत है तो, मुझसे कर्म करो क्यों कह रहे हो? युद्ध घोर राग-द्वेष से भरा तामसिक कार्य है। वह अध्यात्म साधना के बिल्कुल विरुद्ध कर्म है। ऐसे में मुझे ही इस कार्य में क्यों लगा रहे हो केशव?' ऐसा।\n\nइस श्लोक में अर्जुन श्रीकृष्ण को 'जनार्दन' और 'केशव' इन दो विशेष नामों से संबोधित करते हुए हम देखते हैं। यहाँ प्रश्न करते अर्जुन का भाव छिपा है। जन-अर्दन अर्थात लोगों का नाश करने वाला! यहाँ जन का अर्थ है दुर्जन। जनार्दन अर्थात दुर्जन नाशक। 'दुष्ट निग्रह के लिए अवतरित तुम, मुझसे यह कार्य करवा रहे हो। परन्तु यहाँ सब इकट्ठे हुए दुर्जन नहीं हैं। ऐसे में उन्हें मारने का कर्म श्रेष्ठ कैसे होगा? लोगों को मुक्त कर मोक्ष देने वाले तुम, मुझसे गुरु-बड़ों को मारने का यह घोर कर्म क्यों करवा रहे हो?' यही अर्जुन का प्रश्न है। श्लोक के अंत में 'केशव' नाम विशेषण अर्जुन की शरणागति को दर्शाता है। क+ईश+व — केशव; यहाँ 'क' अर्थात सृष्टि का कारण चतुर्मुख ब्रह्मा; ईश अर्थात संहार का कारण शंकर। केशव अर्थात सृष्टि-संहार का कारण ब्रह्मशक्ति और शिवशक्ति से युक्त परशक्ति। 'सृष्टि-स्थिति-संहार-मोक्ष के कारण तुम मुझे इस भ्रम से बचाओ' ऐसा अर्जुन श्रीकृष्ण की शरण में जाकर याचना करता है।\n\nव्यामिश्रेणेव वाक्येन बुद्धिं मोहयसीव मे ।\n\nतदेकं वद निश्चित्य येन श्रेयोऽहमाप्नुयाम् -- दोहरी बात से मेरी निर्णय-शक्ति को भ्रमित कर रहे हो जैसा लगता है। इसलिए, एक बात निश्चित करके कहो: किससे मैं भलाई पाऊँगा?\n\nयहाँ 'व्यामिश्रेण' का अर्थ है विरोधाभास। 'इस प्रकार दोहरी बात से मुझे क्या सही, क्या गलत यह निर्णय नहीं आ रहा, और उसे जानने की शक्ति मुझमें नहीं है। तुम्हारा अभिप्राय मैं समझ नहीं पा रहा। किस रास्ते चलने पर मैं भलाई पाऊँगा? मेरा जीवन सार्थक होने वाला निश्चित रास्ता बताओ' ऐसा कृष्ण से अर्जुन पूछता है।",
  "3.1": "अध्याय तीन\n\nदूसरे अध्याय में भगवान का बोध, उस बोध को पाने का उपाय कृष्ण ने बताया। इस उपदेश में एक ओर ज्ञान सबसे श्रेष्ठ है, ज्ञान के सामने कर्म कुछ भी नहीं है ऐसा कृष्ण कहते हैं। दूसरी ओर अर्जुन से तामसिक युद्ध करने को कहते हैं! ज्ञान ही सबसे श्रेष्ठ है तो यह तामसिक राग-द्वेष वाला युद्ध क्यों चाहिए? तीसरा अध्याय अर्जुन के इसी प्रश्न से शुरू होता है।\n\nअर्जुन उवाच —\n\nज्यायसी चेत्कर्मणस्ते मता बुद्धिर्जनार्दन ।\n\nतत्किं कर्मणि घोरे मां नियोजयसि केशव -- हे जनार्दन, यदि कर्म से बुद्धि श्रेष्ठ है यह तुम्हारा मत है, तो फिर मुझे इस घोर मारने वाले कार्य में क्यों लगा रहे हो, हे केशव?\n\nकृष्ण के ज्ञान और कर्म के बारे में दिए गए विवरण से अर्जुन भ्रमित हो जाता है। उसे कौन सा मार्ग उचित है यह प्रश्न सताता है। कृष्ण कभी ज्ञान मार्ग पर चलो, वह श्रेष्ठ है कहते हैं; कभी युद्ध करो कहते हैं! खुद क्यों श्रेष्ठ ज्ञान मार्ग पर न चले, युद्ध ही क्यों करना चाहिए यह भ्रम अर्जुन का है। इस भ्रम में अर्जुन कृष्ण से पूछता है: 'हे जनार्दन, कर्म से ज्ञान मार्ग श्रेष्ठ है यह तुम्हारा मत है तो, मुझसे कर्म करो क्यों कह रहे हो? युद्ध घोर राग-द्वेष से भरा तामसिक कार्य है। वह अध्यात्म साधना के बिल्कुल विरुद्ध कर्म है। ऐसे में मुझे ही इस कार्य में क्यों लगा रहे हो केशव?' ऐसा।\n\nइस श्लोक में अर्जुन श्रीकृष्ण को 'जनार्दन' और 'केशव' इन दो विशेष नामों से संबोधित करते हुए हम देखते हैं। यहाँ प्रश्न करते अर्जुन का भाव छिपा है। जन-अर्दन अर्थात लोगों का नाश करने वाला! यहाँ जन का अर्थ है दुर्जन। जनार्दन अर्थात दुर्जन नाशक। 'दुष्ट निग्रह के लिए अवतरित तुम, मुझसे यह कार्य करवा रहे हो। परन्तु यहाँ सब इकट्ठे हुए दुर्जन नहीं हैं। ऐसे में उन्हें मारने का कर्म श्रेष्ठ कैसे होगा? लोगों को मुक्त कर मोक्ष देने वाले तुम, मुझसे गुरु-बड़ों को मारने का यह घोर कर्म क्यों करवा रहे हो?' यही अर्जुन का प्रश्न है। श्लोक के अंत में 'केशव' नाम विशेषण अर्जुन की शरणागति को दर्शाता है। क+ईश+व — केशव; यहाँ 'क' अर्थात सृष्टि का कारण चतुर्मुख ब्रह्मा; ईश अर्थात संहार का कारण शंकर। केशव अर्थात सृष्टि-संहार का कारण ब्रह्मशक्ति और शिवशक्ति से युक्त परशक्ति। 'सृष्टि-स्थिति-संहार-मोक्ष के कारण तुम मुझे इस भ्रम से बचाओ' ऐसा अर्जुन श्रीकृष्ण की शरण में जाकर याचना करता है।",
  "3.2": "व्यामिश्रेणेव वाक्येन बुद्धिं मोहयसीव मे ।\n\nतदेकं वद निश्चित्य येन श्रेयोऽहमाप्नुयाम् -- दोहरी बात से मेरी निर्णय-शक्ति को भ्रमित कर रहे हो जैसा लगता है। इसलिए, एक बात निश्चित करके कहो: किससे मैं भलाई पाऊँगा?\n\nयहाँ 'व्यामिश्रेण' का अर्थ है विरोधाभास। 'इस प्रकार दोहरी बात से मुझे क्या सही, क्या गलत यह निर्णय नहीं आ रहा, और उसे जानने की शक्ति मुझमें नहीं है। तुम्हारा अभिप्राय मैं समझ नहीं पा रहा। किस रास्ते चलने पर मैं भलाई पाऊँगा? मेरा जीवन सार्थक होने वाला निश्चित रास्ता बताओ' ऐसा कृष्ण से अर्जुन पूछता है।",
  "3.3": "भगवानुवाच — भगवान बोले:\n\nलोकेऽस्मिन्द्विविधा निष्ठा पुरा प्रोक्ता मयानघ ।\n\nज्ञानयोगेन साङ्ख्यानां कर्मयोगेन योगिनाम् -- हे अनघ, इस लोक में दो प्रकार की निष्ठा (मुक्ति) मैंने पहले बताई है: ज्ञानमार्गियों के लिए ज्ञानप्रधान साधना से; कर्ममार्गियों के लिए कर्मप्रधान साधना से।\n\nपहले ज्ञानमार्ग और कर्ममार्ग के बारे में बता चुके कृष्ण, यहाँ किस स्तर पर कौन मुख्य है यह विषय बताते हैं। कर्मयोग के बारे में विशेष विवरण यहीं से शुरू होता है।\n\nइस श्लोक में 'निष्ठा' शब्द का प्रयोग हुआ है। यहाँ 'निष्ठा' का अर्थ है जीवन की चाल या अंतिम स्थिति — वही 'मोक्ष'। कृष्ण कहते हैं: \"साधकों में दो प्रकार हैं — सांख्य और योगी।\" यहाँ सांख्य अर्थात ज्ञानमार्ग में साधना करने वाले। योगी अर्थात कर्मसाधना के द्वारा साधना करने वाले।\n\nइस श्लोक को ऊपरी तौर पर देखें तो: \"ज्ञान के साधक ज्ञानमार्ग पर जाएँ, कर्म के द्वारा साधना करने वाले कर्म के मार्ग पर जाएँ\" ऐसा कहा गया प्रतीत होता है। यहाँ अर्जुन कर्म के द्वारा साधना करने वाला है, इसलिए कृष्ण उससे युद्ध करो कहते हैं ऐसा लगता है। परन्तु यह सच्चा अर्थ नहीं है। जैसा तुम जानते हो अर्जुन उस काल के महाज्ञानियों में से एक था। ऐसे में हमें इस श्लोक का ऊपरी अर्थ नहीं लगाना चाहिए। यहाँ गहरे चिंतन की आवश्यकता है।\n\nशास्त्रों में कहा गया है कि ज्ञान से ही मोक्ष को जाना सम्भव है। मोक्ष का दूसरा मार्ग नहीं है। तो मोक्ष साधना के लिए ज्ञान चाहिए ही। कर्म ज्ञान के लिए है। ज्ञान का पूरक न बनने वाला कर्म — कर्म नहीं है। सुबह से शाम तक जप की माला पकड़कर 'शुद्ध-शुद्ध' कहकर बैठे रहने से हम ऊँचाई पर नहीं पहुँचेंगे। चाहे जो कर्म करना हो, उसे जानकर करना चाहिए। किया गया कर्म ज्ञान का पूरक होना चाहिए। इसलिए केवल ज्ञानयोग या केवल कर्मयोग जैसा कुछ नहीं है। कर्म के बिना ज्ञान नहीं, ज्ञान के बिना कर्म नहीं। छांदोग्य उपनिषद में कहा गया है: \"यदेव विद्यया करोति श्रद्धया उपनिषदा, तदेव वीर्यवत्तरं भवति, विज्ञानं यज्ञं तनुते।\" अर्थात \"जो भी करो जानकर करो। ज्ञानपूर्वक किया गया कर्म सफल है, नहीं तो वह व्यर्थ है।\" किए जाने वाले कर्म को किसलिए कर रहे हैं, करने का फल क्या है, कैसे करना है — यह पता होना चाहिए। अज्ञान से किया कर्म व्यर्थ हो जाता है। यहाँ कृष्ण ने कहा है एक कर्मप्रधान मार्ग (जनक आदि जैसा) और दूसरा ज्ञानप्रधान मार्ग (सनक आदि जैसा)।",
  "3.4": "न कर्मणामनारम्भान्नैष्कर्म्यं पुरुषोऽश्नुते ।\n\nन च संन्यसनादेव सिद्धिं समधिगच्छति -- कर्मों में न लगने से साधक कर्मों से मुक्त नहीं होता। कर्मफल त्यागने मात्र से सिद्धि नहीं मिलती।\n\nशास्त्रों में कहा गया है 'कर्म बंधन का रास्ता और ज्ञान मुक्ति का रास्ता है'। परन्तु कृष्ण ने कहा — मोक्ष के लिए ज्ञानप्रद और कर्मप्रद दो मार्ग हैं। यहाँ उसका विवरण देते हैं कृष्ण। मोक्ष निष्कर्म से मिलने वाली चीज़ है; कर्म बंधक है यह मान लें तो, एक शरीर में जीव कुछ भी कर्म न करते हुए रह सकना सम्भव ही नहीं है। देह मिलने के बाद कर्म-क्रिया चलती ही रहती है। कर्म करना छोड़ते ही मोक्ष नहीं मिलता। मूलतः कर्म छोड़ना भी सम्भव नहीं है। ज्ञान का पूरक न बनने वाला यांत्रिक कर्म बंधक है। ज्ञान का पूरक बनने वाला कर्म कभी बंधक नहीं है। कर्म का फल न चाहते ही कोई सिद्धि नहीं मिलती। केवल कर्मत्याग करने से कभी सिद्धि पाना सम्भव नहीं है।",
  "3.5": "न हि कश्चित्क्षणमपि जातु तिष्ठत्यकर्मकृत् ।\n\nकार्यते ह्यवशः कर्म सर्वः प्रकृतिजैर्गुणैः -- कोई भी एक क्षण भी बिना कुछ किए चुपचाप नहीं रह सकता। हर कोई प्रकृति के गुणों से बिना जाने (भगवान के अधीन होकर) कर्म करता है।\n\nकर्मत्याग से सिद्धि नहीं मिलती। इतना ही नहीं, कर्मत्याग करना सम्भव ही नहीं है। हमारा अन्नमय और प्राणमय कोष निरंतर कार्य करते रहते हैं। जीते जी निष्क्रिय रहना असम्भव है। किसी भी काल में एक क्षण भी निष्क्रिय रहना किसी के लिए सम्भव नहीं है। \"कार्यते हि अवशः\" — देह के भीतर रहने वाले जीव से उसके देह के द्वारा, मन के द्वारा, वाणी के द्वारा — काम करवाया जाता है। वह जीव के अपने अधीन नहीं है। वह भगवान के अधीन है। पूरा विश्व ही प्रकृति से सृष्टि हुआ है। उसका मूल द्रव्य सत्व-रजस्-तमस् है। जीव का अपना स्वभाव होता है। उसके अनुसार प्रकृति के इन तीन गुणों का प्रभाव हम पर होता रहता है। इसलिए निष्क्रियता निरर्थक है। हमें जीवन में स्वयं को लगाना चाहिए। कर्तव्यशील बनना चाहिए। उसके साथ मानसिक रूप से सांसारिक जगत से परे सत्य की ओर हमारा मन जाग्रत रहना चाहिए। इस सजगता से सारे कर्तव्य-कर्म करने चाहिए। निष्क्रियता वेदान्त नहीं है — कर्तव्यच्युति अध्यात्म नहीं है। भगवान की चेतना के साथ।",
  "3.6": "कर्मेन्द्रियाणि संयम्य य आस्ते मनसा चरन् ।\n\nइन्द्रियार्थान्विमूढात्मा मिथ्याचारः स उच्यते -- कर्मेन्द्रियों को दबाकर, मन से ही इन्द्रिय-विषयों के सपने देखने वाला मूर्ख दिखावटी आचरण करने वाला कहलाता है।\n\nइस श्लोक में कृष्ण एक महत्वपूर्ण बात कहते हैं। आमतौर पर आज के संसार में बाहरी रूप-रंग को अधिक महत्व दिया जाता देखते हैं। मन में सारी इच्छाएँ रखकर, किसी भय से बाहर से सदाचार-सम्पन्न जैसे जीने वाले लोग हैं। कृष्ण इसे कपटी धार्मिकता कहते हैं। हमें पहले अपनी अंतरात्मा को धोखा दिए बिना जीना चाहिए। बाहरी आचरण से पहले भीतर की आचार-शुद्धि महत्वपूर्ण है। यह न हो तो कभी उद्धार नहीं है। कर्मेन्द्रियों को दबाकर, मन से ही इन्द्रिय-विषयों के सपने देखने वाला मूर्ख दिखावटी आचरण करने वाला कहलाता है ऐसा कृष्ण ने कहा है।",
  "3.7": "यस्तु इन्द्रियाणि मनसा नियम्यारभतेऽर्जुन ।\n\nकर्मेन्द्रियैः कर्मयोगमसक्तः स विशिष्यते -- हे अर्जुन, इन्द्रियों को मनोबल से जीतकर, फल का नाता छोड़कर, इन्द्रियों के द्वारा साधना में लगने वाला श्रेष्ठ है।\n\nमन स्वच्छ हो और इन्द्रियों पर मानसिक लगाम मजबूत हो — तब कर्मेन्द्रिय से की गई साधना कर्मयोग बनती है। यह शुद्ध अध्यात्म साधना है। इस स्थिति में इन्द्रियाँ राह नहीं भटकतीं। अपने जीव-स्वरूप के स्वभाव के अनुसार चित्तशुद्धि से किया गया कर्म ही सच्ची अध्यात्म साधना है। इस प्रकार की साधना में लगने वाला श्रेष्ठ कहलाता है। ऐसे लोग भीतर कुछ और बाहर कुछ नहीं होते, मनोबल से इन्द्रियों को जीतकर, फल का नाता छोड़कर, ऊँचाई पर चढ़ते हैं।",
  "3.8": "नियतं कुरु कर्म त्वं कर्म ज्यायो ह्यकर्मणः ।\n\nशरीरयात्रापि च ते न प्रसिध्येदकर्मणः -- अपने हिस्से का कर्म तुम करो। निष्क्रियता से कर्म बेहतर नहीं है क्या? निष्क्रिय होने पर तुम्हारे जीवन-रथ की यात्रा नहीं चलेगी।\n\nकृष्ण कहते हैं: 'तुम अपने जीव-स्वभाव के अनुरूप, ज्ञान के पूरक नियत कर्म करो' ऐसा। यहाँ अर्जुन को देखें तो, उसका जीव-स्वभाव अन्याय के विरुद्ध लड़कर देश की प्रजा की रक्षा करने वाला क्षत्रिय-स्वभाव है। उसे छोड़कर, देश में अन्याय ताण्डव कर रहा हो तब, ज्ञान श्रेष्ठ है कहकर तपस्या करे तो वह सच्चा योग नहीं कहलाता। कृष्ण कहते हैं, \"कभी निष्क्रिय मत बनो, अपना कर्म तुम करो, उससे जो मिले उसे भोगो। परन्तु किया जाने वाला कर्म ज्ञान का पूरक हो। भगवान की सजगता हमेशा बनी रहे\" ऐसा। \"भगवान यह कर्म मेरे हाथों से करवा रहे हैं, यह उन्हीं को अर्पित है\" ऐसी भावना से कर्म करने पर कोई भी कर्म हमारे लिए बंधक नहीं बनता।\n\nअपने हिस्से का कर्म करो, जो मिले उसे खाओ, हरि के चरणों की सुधि न भूले। हरि ही परम देवता है, हरि ही गुरु और आसरा है, हरि ही अकेला जगत का माता-पिता है।\n\nहम जब तक एक देह में हैं तब तक कर्म अनिवार्य है। अपरोक्ष ज्ञान आने पर भी कर्म निरंतर चलता है। इस प्रकार कृष्ण ने कर्म सिद्धांत को इस श्लोक के माध्यम से हमारे सामने खोल दिया है।\n\nयहाँ एक बात हमें सही ढंग से समझनी चाहिए। शास्त्रों के अनुसार कर्म बंधक है। पुनः कर्म करने से हम कर्म-चक्र में फँसते हैं। परन्तु यहाँ कृष्ण कहते हैं — कर्म अनिवार्य है ऐसा। तो फिर मोक्ष का मार्ग कौन सा है? हमारे इस प्रश्न का अगले श्लोक में स्पष्ट उत्तर है।",
  "3.9": "यज्ञार्थात्कर्मणोऽन्यत्र लोकोऽयं कर्मबन्धनः ।\n\nतदर्थं कर्म कौन्तेय मुक्तसङ्गः समाचर -- भगवान की पूजा के रूप वाले ऐसे कर्म से अलग किसी और चाल में ही साधक कर्म के जाल में फँसता है। हे कौन्तेय, फल का नाता छोड़कर, भगवान की पूजा समझकर कर्म करो।\n\nयह लोक कर्म के बंधन में फँसा है। परन्तु सारा कर्म बंधक नहीं है। जानकर किया गया कर्म कभी बंधक नहीं बनता। हमें किया जाने वाला कर्म भगवान की चेतना से करना चाहिए। हम सूत्र की गुड़ियों जैसे हैं। भगवान सूत्रधार है। इस सजगता से हम कर्म करें तो हमारा हर एक कर्म भी यज्ञ बन जाता है। उदाहरण के लिए हम साँस लेते हैं। बाहर से ऑक्सीजन खींचकर कार्बन डाइऑक्साइड बाहर निकालते हैं। हमारे भीतर के उस विशेष यंत्र की कल्पना भी हमें नहीं होती। हमें बिना जाने यह क्रिया चलती रहती है। हमारे छोड़े श्वास को पेड़-पौधे लेकर हमें चाहिए वह ऑक्सीजन देते हैं। यह सब उसी भगवान की व्यवस्था है। इसी कारण भारतीय लोग सबसे ज्यादा ऑक्सीजन देने वाले अश्वत्थ वृक्ष की पूजा करते हैं। उस वृक्ष में भगवान की विशेष विभूति छिपी है। इस प्रकार हम अपने हर एक कार्य में भगवान की महिमा को जानें तो, हमारे द्वारा किया कर्म — कर्मयोग बन जाता है। और वह कभी बंधक नहीं बनता।\n\nयहाँ प्रयुक्त 'यज्ञ' शब्द का अर्थ 'यज-देव-पूजा' अर्थात देवता की पूजा है। भगवान को भी यज्ञ कहा जाता है। इसलिए केवल अग्नि के मुख में की जाने वाली पूजा ही यज्ञ नहीं है। हमारे हर एक कर्म को भगवत्-चेतना से करने पर वह यज्ञ बनता है। यहाँ हमें छोड़ना है कर्म नहीं, बल्कि हमें कर्म के बारे में अपने भाव को बदलना है, बस इतना ही। कर्म का अर्थ है 'कर-म' अर्थात भगवान के राज्य की प्रजा बने हम उनको देने वाला 'कर' या कर ही कर्म है। भगवान कभी पैसे का कर नहीं लेते। उनका कर हमें अपने आप को समाज-कार्य में लगाकर चुकाना है। यह भाव आने पर कर्म बंधक न बनकर मोक्ष का मार्ग बनता है।\n\nयहाँ कृष्ण अर्जुन को 'कौन्तेय' कहकर संबोधित करते हैं। इस तरह यहाँ संबोधित करने का विशेष कारण है। कुंती इतने बड़े घराने में जन्म लेकर पली-बढ़ी होते हुए भी, वह कभी भोग की इच्छा की शिकार नहीं हुई। अपनी जवानी जंगल में बिताने वाली वह, अपने बच्चे हिम्मत हारने पर हिम्मत भरने वाली धीर महिला थी। उसने सहा दुख कम नहीं था। परन्तु उसने कृष्ण से कहा \"मुझे दुख ही दो, क्योंकि तब हमें सदा तुम्हारे साथ रहने का सौभाग्य मिलता है\" ऐसा! कर्तव्यनिष्ठा को जगत को दिखाने वाली धीर महिला वह। ऐसी महान महिला के पुत्र तुम्हें कर्मयोग के बारे में पता ही है, ऐसे स्वर में कृष्ण अर्जुन को 'कौन्तेय' कहकर संबोधित करते हैं।\n\nइस प्रकार ज्ञान और कर्म को कैसे मेल बिठाकर जीना चाहिए यह बताने वाले कृष्ण, आगे यह स्पष्ट समझ आए इसलिए एक कथा के रूप में विवरण देते हैं। वह विवरण आगे के श्लोकों में देखें।",
  "3.10": "सह यज्ञाः प्रजाः सृष्ट्वा पुरा उवाच प्रजापतिः ।\n\nअनेन प्रसविष्यध्वमेष वोऽस्त्विष्टकामधुक् -- पहले प्रजापति ने भगवान की पूजा के रूप वाले कर्म के साथ मनुष्यों को जन्म देकर ऐसा कहा: इससे वृद्धि पाओ, यह तुम्हारी इच्छा को पूरा करे।\n\nपहले चतुर्मुख ने चिंतनशील मनुष्यों की सृष्टि करके, उनके लिए उन्हें करने योग्य यज्ञ की सृष्टि की। और कहा \"इस पूजा-विधि से जो चाहिए वह पाओ। यह तुम्हारी चाही हुई अभीष्ट को देने वाली कामधेनु है\" ऐसा। पहले कहा गया जैसे 'यज्ञ' अर्थात 'भगवान की उपासना करने की विधि'; 'दान' और 'संगतीकरण' भी यज्ञ है। दान का विशेष अर्थ है। अपने पास जितना चाहिए उतना होकर, अपने को न चाहिए वह दूसरे को देना दान नहीं है। अपने पास दो वक़्त का भोजन हो, और दूसरे के पास एक वक़्त का भोजन भी न हो तब, उसे अपने पास का भोजन देकर बाँटकर खाना सच्चा दान है। दूसरे के दुख में पिघलना सच्चा दान है। और संगतीकरण अर्थात ज्ञानार्जन के लिए एक जगह इकट्ठा होना। प्रवचन एक संगतीकरण है।",
  "3.11": "देवान्भावयतानेन ते देवा भावयन्तु वः ।\n\nपरस्परं भावयन्तः श्रेयः परमवाप्स्यथ -- इससे देवताओं की मदद करो। वे देवता तुम्हारी मदद करें। एक-दूसरे की मदद करते हुए बड़ा हित पाओ।\n\nइस प्रकार यज्ञ की सृष्टि करने वाले चतुर्मुख ने कहा था: \"यज्ञों के द्वारा तुम देवताओं की मदद करो और वे तुम्हारी इच्छा पूरी करें\" ऐसा। \"इस प्रकार एक-दूसरे की मदद करते हुए बड़ा हित पाओ\" ऐसा कहा था। हमें जो चाहिए वह हम स्वयं ही बना लेते हैं यह हमारा भ्रम है। हमें बोकर उगाना है तो प्रकृति में वातावरण की विपरीतता नहीं होनी चाहिए। नहीं तो हमें कुछ भी उगाना सम्भव नहीं है। हर एक क्रिया के पीछे अनेक देवताशक्तियाँ काम कर रही होती हैं। हमारे हर एक अंग के लिए एक अभिमानी देवता है। वह शक्ति काम न करे तो हम कुछ भी नहीं कर सकते। इस प्रकार हमें जीवन देकर, देखने वाली आँख, सुनने वाला कान देकर, अच्छा देखने, अच्छा सुनने वाली बुद्धि देकर, यह सारा काम एक देवताओं का समूह निरंतर चलाए ऐसी भगवान की व्यवस्था है। ऐसे में हमें ऐसी देवताशक्तियों के प्रति कृतज्ञता दिखानी चाहिए। इस तरह एक-दूसरे की मदद करने पर ही हम हित पा सकते हैं।\n\nसामान्यतः अग्नि के मुख में की जाने वाली पूजा को यज्ञ कहना प्रचलित है। भगवान की पूजा में अग्नि सबसे महत्वपूर्ण प्रतीक है। क्योंकि अग्नि सबसे शुद्ध है। अग्नि में जो भी डाला जाए वह शुद्ध हो जाता है। अग्नि भगवान का प्रतीक है। भगवान का कोई आकार नहीं है, वे प्रकाश-पुंज और पवित्र हैं। यही गुण हम अग्नि में देख सकते हैं। और भगवान को कुछ भी अर्पित करना हो तो वह अग्नि के मुख से ही सम्भव है। यज्ञ में हम आग की नहीं, अग्नि के माध्यम से अग्निनारायण की पूजा करते हैं — यही यज्ञ है। यह समझ के बिना यज्ञ करें तो धुआँ खाकर मरना पड़े! हमारी पूजा अग्निनारायण से सूर्यनारायण तक पहुँचकर, वापस नरनारायण तक पहुँचती है। इसीलिए भगवान के लिए किया जाने वाला यज्ञ हमेशा दिन के समय ही होता है।",
  "3.12": "इष्टान्भोगान्हि वो देवा दास्यन्ते यज्ञभाविताः ।\n\nतैर्दत्तानप्रदायैभ्यो यो भुङ्क्ते स्तेन एव सः -- ऐसे यज्ञ से बल पाए देवता तुम्हारी चाही हुई इच्छाएँ पूरी करेंगे। उन्होंने दिया हुआ उन्हें दिए बिना खाने वाला चोर ही है।\n\nहमें जो चाहिए वह यह प्रकृति देती है। ऐसे में उसका उपयोग करने वाले हमें कृतज्ञता चाहिए। उसे छोड़कर 'यह मेरा है' कहकर अधिकार का अहंकार दिखाएँ तो उद्धार नहीं है। प्रकृति ने दिया हुआ बिना कृतज्ञता दिखाए लेकर 'यह मेरा है' कहने वाला चोर ही सही!",
  "3.13": "यज्ञशिष्टाशिनः सन्तो मुच्यन्ते सर्वकिल्बिषैः ।\n\nभुञ्जते ते त्वघं पापा ये पचन्त्यात्मकारणात् -- देवताओं को अर्पित कर बचा हुआ खाने वाले सज्जन सभी पापों से मुक्त हो जाते हैं। अपने लिए ही अन्न पकाने वाले अपना पाप ही खाते हैं।\n\nजो पाया हुआ भगवान को अर्पित कर उसे भगवान का प्रसाद मानकर स्वीकार करते हैं, वे जीवन की सभी गंदगियों से मुक्त होकर स्वच्छ जीवन जीते हैं। जिसके घर में अपने लिए ही अन्न पकता है, वह अन्न नहीं पाप खाता है। यह भोजन हमें देने वाला वह भगवान है। उसके प्रति हमें पहले कृतज्ञता दिखानी चाहिए। उसे छोड़कर 'यह मेरी कमाई है, मैं इसे दूसरे को क्यों बाँटूँ' यह भावना बढ़ाएँ तो हम अपना पाप का बोझ बढ़ाते हैं। सृष्टि के उद्देश्य के अनुसार न चलें तो हमने कमाया हुआ भी हमें नहीं मिलता।",
  "3.14": "अन्नाद्भवन्ति भूतानि पर्जन्यादन्नसम्भवः ।\n\nयज्ञाद्भवति पर्जन्यो यज्ञः कर्मसमुद्भवः -- जीवों का जन्म अन्न से; अन्न की उपज सूर्य से (बादल से)। सौरशक्ति की वृद्धि (बादल का जन्म) यज्ञ से; यज्ञ का निर्वहण कर्म से।",
  "3.15": "कर्म ब्रह्मोद्भवं विद्धि ब्रह्माक्षरसमुद्भवम् ।\n\nतस्मात्सर्वगतं ब्रह्म नित्यं यज्ञे प्रतिष्ठितम् -- कर्म की उत्पत्ति भगवान से; भगवान की अभिव्यक्ति वेदाक्षर से। इसलिए सर्वत्र रहने वाला भगवान सदा यज्ञ में स्थित है।",
  "3.16": "एवं प्रवर्तितं चक्रं नानुवर्तयतीह यः ।\n\nअघायुरिन्द्रियारामो मोघं पार्थ स जीवति -- इस तरह जगत के पहिए को आगे न बढ़ाने वाला पाप के जीवन में जीता हुआ इन्द्रिय-सुख में ही खोया रहता है। हे पार्थ, उसका जीवन व्यर्थ है।\n\nजीव-जाति का जन्म अन्न से। अन्न के बिना जीवन नहीं है। यह अन्न मिलता है फसल से। फसल का मूल सौरशक्ति और वर्षा है। वर्षा आती है यज्ञ से, हमारे किए ईमानदार जीवन से, भगवत्-अर्पण बुद्धि से। यज्ञ का निर्वहण कर्म से, हमारी क्रियाशीलता से। कर्म अर्थात कर्तव्य-कर्म, ईमानदार क्रिया। ऐसा कर्म चलता है भगवान से। यह भगवान (ब्रह्म) रहता है वेद (अक्षर) में। वेद रहता है जीव-जातियों में (मनुष्य में)। इसलिए यह एक चक्र है। मानव-अन्न-वर्षा-यज्ञ-भगवान-वेद-मानव। यहाँ वेद अर्थात वेद-मंत्र रटना नहीं है। वैदिक वाङ्मय की सजगता-चेतना। इस चक्र में हम अपना कर्म नहीं छोड़ सकते। कर्म को सदा यज्ञ के रूप में, भगवत्-अर्पण के रूप में करना चाहिए। भगवान की सजगता, वैदिक वाङ्मय की चेतना सब बराबर हों तो वर्षा, वर्षा से फसल, फसल से जीवन। इस चक्र को जो आगे नहीं बढ़ाता वह विश्व-चक्र की चाल को तोड़ने वाला है, समाज की स्वाभाविक चाल में रुकावट डालने वाला है। ऐसा व्यक्ति केवल इन्द्रिय-सुख भोग में खोकर अपना जीवन व्यर्थ कर लेता है।",
  "3.17": "यस्त्वात्मरतिरेव स्यादात्मतृप्तश्च मानवः ।\n\nआत्मन्येव च सन्तुष्टस्तस्य कार्यं न विद्यते -- परमात्मा को देखकर (परमात्मा की कृपा से) सुख पाने वाला, परमात्मा के दर्शन (कृपा) से कृतकृत्य हुआ, कुछ और न चाहते हुए परमात्मा में ही आनंदित रहने वाला समाधिमग्न (तृप्त मुक्त) व्यक्ति ही — उसे कुछ भी करना शेष नहीं रहता।\n\nभगवान को अंतरात्मा में देखकर पाया आनंद 'आत्मरति' है। यह स्थिति समाधि-स्थिति में पहुँची जा सकती है। सच्ची समाधि-स्थिति में हमारी इन्द्रियाँ और मन काम नहीं करते। ज्ञानस्वरूप 'जीवस्वरूप' सीधे भगवान को देखने की स्थिति 'समाधिस्थिति' है। इस स्थिति में भगवान से सीधा संपर्क सम्भव है। ऐसी स्थिति में रहने वाले को किसी भी कर्म का लेप नहीं है। भगवान को देखने के बाद उसे यह लौकिक संसार तृप्त होकर नहीं चाहिए लगता है। केवल भगवान के साक्षात्कार के आनंद-सागर में वह डूबा रहता है। इस स्थिति में उसे कोई कर्तव्य-कर्म नहीं, वह विधि-निषेधों से परे रहता है।",
  "3.18": "नैव तस्य कृतेनार्थो नाकृतेनेह कश्चन ।\n\nन चास्य सर्वभूतेषु कश्चिदर्थव्यपाश्रयः -- ऐसे व्यक्ति को कुछ भी करने से कोई अधिक लाभ नहीं, न करने से कोई हानि नहीं। समस्त जीवों में उसे किसी फल की अपेक्षा नहीं है।\n\nसमाधि-स्थिति में उसे भूख, प्यास नहीं है। उसे बाहरी संसार का बोध ही नहीं रहता। ऐसी स्थिति में रहते हुए किसी और साधना से उद्धार, या कर्तव्य-कर्म न करने का दोष नहीं होता। पंचभूतों, पंचकोशों का सहारा भी उसे नहीं चाहिए। समस्त जनसमूह, परिवार जैसी ममता इस स्थिति में नहीं होती। उसे बाहरी संसार की चिंता नहीं है। इस प्रकार समाधि-स्थिति से भगवान को देखने वाला कर्तव्य-कर्म से परे रहता है।",
  "3.19": "तस्मादसक्तः सततं कार्यं कर्म समाचर ।\n\nअसक्तो ह्याचरन्कर्म परमाप्नोति पूरुषः -- इसलिए फल का नाता छोड़कर सदा कर्तव्य-कर्म करते रहो। नाता छोड़कर कर्तव्य में लगने से ही साधक भगवान तक पहुँच सकता है।\n\nइन सभी कारणों से हमें अपना कर्तव्य-कर्म करना चाहिए। \"सब कुछ करो, परन्तु कुछ भी न चिपकाते हुए करो। जो करना है उसे फल की चिंता किए बिना (अधिकार जताए बिना) करो। ऐसे कर्म करने पर वह तुम्हें भगवान की ओर ले जाएगा। वह कभी तुम्हें फिर कर्म-बंधन में नहीं धकेलेगा। इस तरह करने से ही भगवान तक पहुँचना सम्भव है, कर्म-त्याग से नहीं\" ऐसा कृष्ण कहते हैं।\n\nयहाँ \"पूरुषः\" शब्द का प्रयोग हुआ है। पुर में (पूर्ण शरीर में) रहने वाला पुरुष। पुर का पूर्ण उपयोग करने वाला साधक — पूरुषः। साधना-शरीर में रहकर साधना में लगा जीव पूरुषः है।\n\nइस प्रकार कर्म सिद्धांत बताने वाले कृष्ण, उसके अनुरूप उदाहरण अगले श्लोक में देते हैं।",
  "3.20": "कर्मणैव हि संसिद्धिमास्थिता जनकादयः ।\n\nलोकसङ्ग्रहमेवापि सम्पश्यन्कर्तुमर्हसि -- कर्म से ही सिद्धि पाकर जनक आदि ने लक्ष्य पाया। जनता को सुधारने की जिम्मेदारी जानते हुए भी तुम्हें कर्म करना चाहिए।\n\nपहले के अनेक राजर्षियों ने इसी मार्ग पर चलकर मोक्ष पाया है। उनमें से किसी ने भी सब कुछ त्यागकर जंगल नहीं गए। इसका उत्तम उदाहरण जनक महाराज हैं। यह सारे राज्य के वैभव के साथ राज्य करने वाले व्यक्ति थे। परन्तु उतना बड़ा ज्ञानी उस काल में कोई नहीं था। ऐसे महान राजर्षि वे थे। शुकाचार्य वैराग्य की सही समझ के लिए जनक के पास आए थे! यही सच्चे साधक का जीवन है। जनक सभी अधिकार के भोग के बीच रहकर विरक्त होकर जिए। इसीलिए कृष्ण यहाँ जनक का नाम लेते हैं। कृष्ण कहते हैं: \"जनक जैसे राजर्षि कर्मयोग से ही ज्ञान पाकर, कर्म करते हुए ऊँचाई पर चढ़े, कर्म त्याग से नहीं\" ऐसा। इस तरह समाज के मार्गदर्शक बने तुम समाज के लिए युद्ध करो ऐसा कृष्ण कह रहे हैं।\n\nकर्तव्य-कर्म के बारे में विस्तार से बताने वाले कृष्ण, अब गलत रास्ते पर मुखिया चले तो समाज पर होने वाले परिणाम के बारे में स्वयं को ही उदाहरण बनाकर अगले श्लोकों में बताते हैं।",
  "3.21": "यद्यदाचरति श्रेष्ठस्तत्तदेवेतरो जनः ।\n\nस यत्प्रमाणं कुरुते लोकस्तदनुवर्तते -- मुखिया जो-जो करता है वैसे ही बाकी लोग वही रास्ता पकड़ते हैं। वह जिसे आधार बनाकर इस्तेमाल करता है जनता उसे ही अपनाती है।\n\nसमाज में बड़ा माना जाने वाला (श्रेष्ठ, उम्र में, आचरण में, ज्ञान में समाज को मार्गदर्शन कर सकने वाला, ऊँचाई पर रहने वाला व्यक्ति) जिस रास्ते चलता है, बाकी लोग भी उसी राह चलते हैं। यहाँ अर्जुन समाज का मुखिया है। वह जो करेगा वही समाज अनुसरण करेगा। क्योंकि सामान्य लोगों को शास्त्र आदि पता नहीं होता। वे केवल आदर्श व्यक्ति माने जाने वालों का अनुसरण करते हैं। नेता जिसे प्रमाण मानकर करता है वही सामान्य लोग अनुसरण करते हैं।\n\nइस श्लोक में कृष्ण द्वारा दिए संदेश को हम अपने रोजमर्रा के जीवन में देखते हैं। किसी संस्था चलाने वाले मुखिया का बर्ताव, आचरण सही राह पर न हो तो, वह संस्था अधोगति देखती है। दुष्ट शक्तियाँ उठ खड़ी होती हैं। क्योंकि मुखिया माना जाने वाला जो अनुसरण करता है वही प्रमाण मानकर उसके नीचे के लोग बिना जाने अनुसरण करने लगते हैं। इसी कारण एक मुखिया कितना भी सजग रहे कम है। किसी देश को चलाने वाला मुखिया भ्रष्टाचारी हो तो पूरा देश भ्रष्टाचार की राह पकड़ने की संभावना है। सामान्यतः मनुष्य अच्छे का अनुसरण करने से ज्यादा और तेजी से बुरे का अनुसरण करते हैं। उदाहरण के लिए एक अच्छा अध्यापक धूम्रपान की आदत वाला हो तो, उसके विद्यार्थी उसके ज्ञान से ज्यादा उसकी बुरी आदत को प्रमाण मानकर बुरी राह पकड़ने की सम्भावना ज्यादा है। यह बड़ों के गलत राह पकड़ने पर समाज पर होने वाला दुष्परिणाम है। यह बहुत खतरनाक है — यह सजगता हमें होनी चाहिए।",
  "3.22": "न मे पार्थास्ति कर्तव्यं त्रिषु लोकेषु किञ्चन ।\n\nनानवाप्तमवाप्तव्यं वर्त एव च कर्मणि -- पार्थ, तीनों लोकों में मुझे कुछ भी करना नहीं है। पाना न हो और पाना हो ऐसा भी कुछ नहीं है। फिर भी मैं कर्म में लगा हूँ।",
  "3.23": "यदि ह्यहं न वर्तेय जातु कर्मण्यतन्द्रितः ।\n\nमम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः -- हे पार्थ, मैं कभी भी सजगता से कर्म में न लगूँ तो, मनुष्य हर तरह से मेरी राह पकड़ लेंगे।",
  "3.24": "उत्सीदेयुरिमे लोका न कुर्यां कर्म चेदहम् ।\n\nसङ्करस्य च कर्ता स्यामुपहन्यामिमाः प्रजाः -- मैं कर्म न करूँ तो ये सब लोग राह भटककर बरबाद हो जाएँगे। धर्म की मिलावट का कारण बनकर इन सब लोगों को मैं ही अपने हाथों गिरा दूँगा।\n\nइन ऊपर के तीन श्लोकों में कृष्ण स्वयं को उदाहरण बनाकर पहले कही बात बताते हैं। अर्जुन के सारथी बनकर खड़े कृष्ण कहते हैं — \"मुझे कुछ करना है या न करने से कोई तकलीफ हो ऐसा कुछ नहीं है, परन्तु मैं कर्तव्य-कर्म में स्थित हूँ\" ऐसा। तीनों लोकों में सृष्टि-स्थिति-संहार को अपना नित्य-कर्म बनाकर करने वाले भगवान, सब कुछ अपने प्रिय भक्तों के लिए, जीव-जाति के लिए करते हैं, न कि किसी और लाभ के लिए।\n\nअगर कृष्ण स्वयं को नित्य-कर्म में न लगाते तो सब उन्हें प्रमाण मानकर उनकी राह पकड़ लेते। इसी कारण भगवान अवतार लेते समय एक सामान्य मनुष्य जैसे दिखकर, अपने नित्य-कर्म, कर्तव्य-कर्म निभाते हैं। कृष्णावतार में देखें तो कृष्ण संध्या-वंदन आदि मूल कर्म बिना चूके करते थे। यह उनके लिए नहीं, उनका अनुसरण करने वाले लोगों को मार्गदर्शन देने के लिए है।\n\nकृष्ण कहते हैं \"मैं कर्म न करूँ तो पूरा लोक कर्म की सजगता खोकर राह भटक जाएगा, स्वच्छंदता आकर निश्चित व्यवस्था चली जाएगी\" ऐसा। जिसे जो धर्म है वह करना ही चाहिए। यह एक व्यवस्था है। नहीं तो सब अपनी मर्जी से करने लगेंगे। \"इससे अव्यवस्था फैलेगी और उसकी जिम्मेदारी हम बनेंगे\" ऐसा कृष्ण कहते हैं।",
  "3.25": "सक्ताः कर्मण्यविद्वांसो यथा कुर्वन्ति भारत ।\n\nकुर्याद्विद्वांस्तथासक्तश्चिकीर्षुर्लोकसङ्ग्रहम् -- हे भारत, न जानने वाले जैसे फल के नाते के लिए कर्म करते हैं, वैसे ही जानने वाला भी कर्म करता रहे — फल का नाता छोड़कर, समाज को सुधारने के लिए।\n\nसमझ न रखने वाले फल की चाह से कर्म करते हैं। परन्तु जानने वाला, ज्ञानी, किसी भी फल का अधिकार जताए बिना, निष्काम कर्म करता रहे। \"मैं अपनी आँखों के सामने बढ़ती पीढ़ी के लिए मार्गदर्शक बनकर भगवान की सेवा कर रहा हूँ, मुझे इससे भगवान जो भी दें खुशी है\" ऐसे संकल्प से कर्म करना चाहिए। यही सच्चा कर्मयोग है।",
  "3.26": "न बुद्धिभेदं जनयेदज्ञानां कर्मसङ्गिनाम् ।\n\nजोषयेत्सर्वकर्माणि विद्वान्युक्तः समाचरन् -- समझ न रखने वाले फल के नाते के लिए ही कर्म करने वाले लोगों के विश्वास को हिलाना नहीं चाहिए। उपाय जानने वाला समझदार खुद सारे कर्म करते हुए उन्हें प्रोत्साहित करे।\n\nसमाज में अनेक तरह के लोग होते हैं। सभी को समझ नहीं होती। वे अपने विश्वास के अनुसार चलते रहते हैं। जानने वाले को वह अंधविश्वास जैसा लग सकता है। परन्तु कभी भी एकदम जाकर ऐसे लोगों का मजाक नहीं उड़ाना चाहिए। कोई एक पत्थर को एक नाम देकर भगवान मानकर पूज रहा हो सकता है। उसका अपार विश्वास, शरणागति उसकी रक्षा करती रहती है। यह देखकर मजाक उड़ाना मूर्खता है। वे ऐसे विश्वास की नींव पर जीवन में भरोसे से जीते रहते हैं। उनके पास एक सनातन चेतना होती है। सर्वगत, सर्वशब्दवाच्य और सर्वशक्तिमान भगवान उसे पत्थर के माध्यम से भी रक्षा दे सकते हैं न? इसलिए कभी भी ऐसे लोगों को देखकर हँसना नहीं चाहिए। उसे छोड़कर उसे धीरे-धीरे ज्ञान की सीमा में लाने का प्रयत्न करना चाहिए। सब कुछ सामाजिक चिंता से करना चाहिए, परन्तु निर्लिप्त रहकर सारे कर्म करते हुए अज्ञानियों में ज्ञान भरना चाहिए।",
  "3.27": "प्रकृतेः क्रियमाणानि गुणैः कर्माणि सर्वशः ।\n\nअहङ्कारविमूढात्मा कर्ताहमिति मन्यते -- प्रकृति के अंग-अंग बने इन्द्रिय आदि से (भगवान के अधीन, जीवन-स्वभाव सहज गुणों से) सभी तरह के कर्म चलते रहते हैं। अहंकार में खोया हुआ 'मैंने ही किया' ऐसा मानता है।\n\nयह श्लोक अनेक तरह से खुलता है। यहाँ कृष्ण मुख्य रूप से 'मैंने ही किया' ऐसा अहंकार करना कितना गलत और क्यों है यह बताते हैं। कृष्ण कहते हैं \"कोई भी कुछ भी 'मैंने ही किया' ऐसा मान ले तो यह उसकी नादानी है\" ऐसा। सृष्टि की एक अजीब बात यह है कि कोई कुछ भी नहीं करता — परन्तु सब कुछ सबके हाथों से हो रहा होता है! यह देह (पिंडांड) प्रकृति की रचना है। प्रकृति में उसकी पोषक अंगभूत इन्द्रियाँ हैं। प्रकृति अर्थात यह देह, उसके गुण अर्थात इन्द्रियाँ। शब्द-स्पर्श-रस-रूप-गंध; कान-त्वचा-जीभ-आँख-नाक; उसके अनुरूप आकाश (शब्द), हवा (स्पर्श), पानी (रस), अग्नि (रूप), और मिट्टी (गंध) ये प्रकृति के गुण हैं। ऐसे में हम किसी एक चीज़ को 'मैंने किया' कहना अर्थहीन है। उदाहरण के लिए 'आँख से देखा'; यह आँख हमें किसने दी? जन्मांध को आँख देना तुम्हारे लिए सम्भव है क्या? अर्थात आँख प्रकृति की देन है। भगवान ने हमें आँख दी, आँख के सामने देखने की वस्तु रखी, देखने को प्रेरित किया — हमने देखा! अगर हमारा स्वर अच्छा हो तो हम उसके लिए अहंकार करते हैं। परन्तु यह स्वर हमें किसने दिया? इस बारे में हम कभी नहीं सोचते। एक कार्य होने के लिए पूरे विश्व के अनेक घटक मिलकर काम करना चाहिए। प्रकृति जड़ है, उसकी इच्छा नहीं है। 'हम करते हैं' अर्थात इच्छा करके करना। हमें इच्छा है; हर एक जीव का अपना जीव-स्वभाव है। हम जो भी कार्य करते हैं वह हमारे जीव-स्वभाव के अनुरूप होता है। यह इच्छापूर्वक क्रिया है। हमें इच्छा है परन्तु इच्छा-स्वतंत्रता नहीं है।\n\nइच्छा-स्वतंत्रता केवल भगवान में है। उसके अनुसार सारा कार्य होता है। इसलिए हमारे स्वभाव को नियंत्रित करने वाला पूरे जगत का मूल कर्ता भगवान है। उसकी इच्छा के अनुसार संसार का व्यापार चलता है। यह विश्व की व्यवस्था है। पूरे विश्व के कर्म-चक्र में हम एक घटक मात्र हैं। इसलिए 'मैंने ही किया' ऐसा अहंकार करने में कोई अर्थ नहीं है। सच्चा कर्ता भगवान है।",
  "3.28": "तत्त्ववित्तु महाबाहो गुणकर्मविभागयोः ।\n\nगुणा गुणेषु वर्तन्त इति मत्वा न सज्जते -- हे महावीर, इन्द्रिय आदि (जीव-स्वभाव के गुणों) और क्रियाओं के भेद की सच्चाई जानने वाला, इन्द्रियाँ इन्द्रिय-विषयों में ही चलती हैं यह जानकर उनसे चिपकता नहीं है।\n\nतत्व जानने वाला या यथार्थ जानने वाला तत्ववादी — गुण-कर्म, इन्द्रिय और उसमें की क्रिया-भेद को जानना चाहिए। मूल रूप से इन्द्रियों में सात्विक, राजस और तामस इन तीन गुणों से कर्म चलता रहता है। यह हमारे पहले चिपकाए हुए का प्रभाव हो सकता है। इससे होने वाले कर्म को हमें तटस्थ होकर देखते रहना चाहिए। यह विषय मनोविज्ञान से संबंधित है। हम खुद करने वाली क्रिया को हम खुद तटस्थ होकर विश्लेषण करना! मुझ पर त्रिगुण का कौन सा गुण प्रभाव डाल रहा है यह स्वयं विश्लेषण (Self Analysis) करके, गुण-कर्म विभाग तत्व जान लेने पर, त्रिगुण के प्रभाव का बोध होता है। तब हमें उसमें कोई स्वामित्व नहीं है यह सच्चाई पता चलती है। इन्द्रियाँ — उस पर प्रकृति का त्रिगुण — उस पर जीव-स्वभाव — उस पर भगवान का ज्ञानानंद — यह सब कर्म बनकर इन्द्रिय के माध्यम से प्रकट होता रहता है। जड़ में केवल क्रिया (Action), जीव में इच्छा और क्रिया (Intentional Action) तथा भगवान में स्वतंत्र इच्छा-क्रिया (Independent Intentional Action) — यह कर्म-भेद है। इस तरह गुण-भेद और कर्म-भेद जानने वाला 'तत्त्ववित्' है। यह तत्व समझ में आए तो \"मैंने किया\" यह अहंकार कभी हमें परेशान नहीं करता।\n\nइस श्लोक में कृष्ण अर्जुन को 'महाबाहो' कहकर संबोधित करते हैं। ऊपरी तौर पर महाबाहु अर्थात वीर, योद्धा। बलिष्ठ भुजाओं वाले तुम कायर न बनकर लड़ो यह यहाँ दिखने वाला भाव है। परन्तु उससे आगे और भी अर्थ है। \"महत् वहतीति महाबाहु\" अर्थात बड़ी चीज़ को धारण करने वाला। जगत के मूलभूत सत्य को हृदय में धारण करने वाला यह अर्थ है।",
  "3.29": "प्रकृतेर्गुणसम्मूढाः सज्जन्ते गुणकर्मसु ।\n\nतानकृत्स्नविदो मन्दान्कृत्स्नविन्न विचालयेत् -- प्रकृति के अंग-अंग बने इन्द्रिय आदि में खोए हुए लोग इन्द्रिय आदि की क्रिया में ही चिपकते हैं। पूरा सत्य न जानने वाले ऐसे लोगों को पूरा जानने वाला भ्रमित न करे।\n\nप्रकृति के गुण-रूप इन्द्रिय-सुख में डूबे हुए; मूल प्रकृति के त्रिगुण के मोह में फँसकर, सत्य न जानते हुए, मोह में रहने वाले; खुद भगवान के गुण के अधीन हैं यह सजगता न रखने वाले — इन्हें कृष्ण 'प्रकृतेर्गुणसम्मूढाः' कहते हैं। ऐसे लोग भगवान के गुण-कर्म को अपना मानकर भ्रम में, 'मैं ही सब कुछ, मुझसे ही सब कुछ' कहकर जीते रहते हैं। ऐसे लोगों में सच्चाई या पूर्णता जानने की योग्यता नहीं होती। ऐसे लोगों को 'पूर्ण जानने वाले' भ्रमित करने नहीं जाना चाहिए। उनमें सच्चाई जानने की योग्यता हो तो वे उस स्थिति से आगे आ जाएँगे। न होने वाली योग्यता कोई नहीं भर सकता; होने वाली योग्यता कोई नहीं छीन सकता।",
  "3.30": "मयि सर्वाणि कर्माणि संन्यस्याध्यात्मचेतसा ।\n\nनिराशीर्निर्ममो भूत्वा युध्यस्व विगतज्वरः -- सारे कर्म मुझे अर्पित कर, मुझमें ही मन लगाकर, इच्छा छोड़कर, ममकार छोड़कर, बेचैनी छोड़कर लड़ो।\n\nकृष्ण कहते हैं \"तुम जो भी सारे कर्म करते हो वह मुझे अर्पित करके करो\" ऐसा। यहाँ 'संन्यस्य' शब्द का प्रयोग हुआ है। मैंने जो कुछ किया वह सब मैंने ही नहीं किया। जो भी क्रिया मुझसे हुई वह मेरे हाथों भगवान ने करवाई है। जो मेरे माध्यम से हुआ वह भगवान की पूजा है ऐसा समर्पण-भाव संन्यास है। \"नाहं कर्ता हरि कर्ता; हरि कर्ता हि केवलम्\" — \"मेरे मुँह से जो भी निकले वह तुम्हारी स्तुति हो। मेरे मन के माध्यम से जो भी चले वह तुम्हारा स्मरण हो। सब कुछ तुम्हारी पूजा हो ऐसा चिंतन बढ़ाओ — युद्ध करते समय भी\" ऐसा कृष्ण कहते हैं।\n\nयहाँ युद्ध सामूहिक रूप से तय हुआ है। लगभग तेरह वर्ष पहले धर्मराज ने राजसूय यज्ञ किया तब वहाँ शिशुपाल का सिर कटा था। तब धर्मराज से व्यास ने कहा था \"यह आगे लगभग तेरह वर्ष बाद होने वाले महायुद्ध का पूर्वसंकेत है\" ऐसा। अर्थात यह युद्ध विधि-लिखित है। यहाँ अर्जुन केवल एक उपकरण (Instrument) है। इसलिए \"भगवान में मन लगाकर इच्छा-ममकार छोड़कर निश्चिंत होकर लड़ो\" ऐसा कृष्ण अर्जुन से कहते हैं।\n\nहमारा जीवन ही एक संघर्ष है। इस संघर्ष में हमें अपना कार्य ईमानदारी से करना चाहिए। जो होना है वह होकर ही रहता है। उसे रोकना हमारे बस में नहीं है। भगवान ने मुझे सौंपा काम उन्होंने ही मेरे हाथों करवाया, यह उन्हें ही अर्पित हो, उनकी पूजा हो। जो फल मिला वह भगवान का प्रसाद है। यह संकल्प रखकर कार्य करने पर जो भी हो उसकी जिम्मेदारी भगवान उठाते हैं। इससे बड़ी पूजा कोई नहीं है। यह गीता के माध्यम से कृष्ण ने हमें दिया जीवन-संदेश है। इसके फलश्रुति जैसे अगले दो श्लोक हैं।",
  "3.31": "ये मे मतमिदं नित्यमनुतिष्ठन्ति मानवाः ।\n\nश्रद्धावन्तोऽनसूयन्तो मुच्यन्ते तेऽपि कर्मभिः -- जो मनुष्य जलन न रखते हुए मेरे इस सिद्धांत को मानकर चलते हैं वे कर्मों से मुक्त हो जाते हैं।\n\nये त्वेतदभ्यसूयन्तो नानुतिष्ठन्ति मे मतम् ।\n\nसर्वज्ञानविमूढांस्तान्विद्धि नष्टानचेतसः -- जो जलन से मेरे सिद्धांत को आचरण में नहीं लाते वे सारे ज्ञान से वंचित हैं। विनाश की ओर बढ़ते नादान — ऐसा जानो।\n\n\"सब कुछ भगवान मेरे हाथों करवा रहे हैं, मैं जो भी करता हूँ वह उनकी पूजा है, मुझे किस फल से भलाई है यह मुझसे ज्यादा भगवान को अच्छी तरह पता है। इसलिए फल में अधिकार चाहे बिना मिले हुए को भगवान का प्रसाद मानकर स्वीकार कर जीना\" — यह हमारे जीवन के नित्य-अनुष्ठान का ढंग बनना चाहिए। जीवन के हर क्षण में यह अनुसंधान रखने वाले मानव (Human being, ज्ञानी, मनुष्यत्व रखने वाले) अश्रद्धा (राजस) और असूया (तामस) छोड़कर निष्काम-कर्म करें तो उनका ज्ञान बढ़ता है। इससे वे कर्म-बंधन उतारकर मोक्ष जाने के योग्य होते हैं। नित्य-अनुष्ठान में यह अनुसंधान हो तो हमारा कर्म ही हमें कर्म-बंधन से छुड़ाने की सीढ़ी बनता है और कर्म-बंधन से पार करता है।\n\nजो जलन से मेरे सिद्धांत को आचरण में नहीं लाते वे सारी समझ से वंचित हैं। ऊपर बताए अनुष्ठान को न जानते हुए, जलन-असहनशीलता से, \"अपने काम के लिए मैं अकेला जिम्मेदार, मैं जो करता हूँ अपने स्वार्थ के लिए, उसका फल मैं पाऊँगा, मेरे हाथ में मेरा अस्तित्व है, कोई भगवान उसके लिए जिम्मेदार नहीं\" ऐसा राय रखकर अहंकार से जीने वालों के लिए कभी समझ का दरवाज़ा नहीं खुलता। वह संसार में विमूढ (श्रेष्ठ मूर्ख) कहलाता है। उसे 'खुद को कुछ नहीं पता' यह बात भी पता नहीं होती! ऐसे लोगों को सत्य के बारे में सोचने की योग्यता नहीं होती। वे विनाश की ओर चलने वाले नादान हैं। वे अंधेरे से अंधेरे की ओर जाते हुए पतन तक पहुँचकर अपना अस्तित्व खो देते हैं।\n\nकृष्ण के इस ऊपर के संदेश को सुनकर हमें एक प्रश्न आता है। जगत का यह मूलभूत सत्य सब क्यों नहीं अपनाते? इसका बहुत रोचक उत्तर कृष्ण अगले दो श्लोकों में देते हैं।",
  "3.32": "सदृशं चेष्टते स्वस्याः प्रकृतेर्ज्ञानवानपि ।\n\nप्रकृतिं यान्ति भूतानि निग्रहः किं करिष्यति -- कितना भी जानने वाला हो अपने संस्कार (स्वभाव) के अनुसार ही चलता है। सारे जीव संस्कार (स्वभाव) की कठपुतलियाँ हैं। दबाने से क्या होगा?\n\nकोई कितना भी उपदेश दे पूरे जगत में सब एक ही रास्ता अपनाना कभी सम्भव नहीं है। इसका कारण हमारी चाल, हमारा संस्कार, और हमारा जीव-स्वभाव है। हम अपने पूर्व संस्कार को देखें तो — सात्विक, राजस, तामस अनेक अनुभव जन्म-जन्मांतरों से हमारी सुप्त चेतना में रहते हैं। अनेक जन्मों से बहकर आए इस जीव में अनेक जन्मों के अनुभव का संस्कार है। एक ही जन्म देखें तो भी, बड़े होते समय के वातावरण की छाप, यह प्रभाव, सदा हम पर रहता है। इसके अलावा हर व्यक्ति का अपना जीव-स्वभाव होता है। वह सदा उसके अनुसार ही चलता है। मिर्च का पौधा जैसे मीठा फल नहीं दे सकता वैसे ही किसी व्यक्ति का जीव-स्वभाव बदलना असम्भव है। स्वभाव और प्रभाव का मिश्रण यही जीवन है।\n\nइस ऊपर के विश्लेषण को देखते हुए स्वाभाविक रूप से हमें एक प्रश्न आता है। \"जीव-स्वभाव के अनुसार जीव की चाल; स्वभाव के अनुसार क्रिया; स्वभाव के अनुसार सब कुछ होता है। तो फिर प्रयत्न क्यों करना चाहिए?\" ऐसा। क्योंकि सदा प्रयत्न करते रहने से संस्कार या प्रभाव से बाहर आना सम्भव है। सहज स्वभाव में स्थिर होने तक प्रभाव से पार पाने का निरंतर प्रयत्न आवश्यक है। निरंतर अध्यात्म-साधना हमारे सहज स्वभाव को प्रकट करने में सहायता करती है।",
  "3.33": "इन्द्रियस्येन्द्रियस्यार्थे रागद्वेषौ व्यवस्थितौ ।\n\nतयोर्न वशमागच्छेत्तौ ह्यस्य परिपन्थिनौ -- हर एक इन्द्रिय और उसके विषय में राग-द्वेष बसे हुए हैं। उनके वश में नहीं होना चाहिए; वे ही साधक की राह के शत्रु हैं।",
  "3.34": "इन्द्रियस्येन्द्रियस्यार्थे रागद्वेषौ व्यवस्थितौ ।\n\nतयोर्न वशमागच्छेत्तौ ह्यस्य परिपन्थिनौ -- एक-एक इन्द्रिय के विषय में भी लगाव-दुश्मनी भरी है। उनके शिकार नहीं होना चाहिए। वे ही साधक के दुश्मन हैं।\n\nहमारी इन्द्रियों में दो चीज़ें हमारे शत्रु बनकर काम करती हैं। वे हैं राग (पसंद करना, Attachment) और चाहिए कहने वाली इच्छा (काम, Desire)। पसंद करना — राग, उससे काम। पसंद न आना — द्वेष, उससे क्रोध। एक वस्तु चाही, वह नहीं मिली तब गुस्सा। वह दूसरे को मिली तब द्वेष। मिली परन्तु वह हमारी सोच जैसी नहीं तब क्रोध। मूल रूप से रहने वाला बड़ा दोष इच्छा है। जिसे ज्यादा-ज्यादा चाहते हैं उससे ज्यादा-ज्यादा दुख में पड़ते हैं। इच्छा को सीमित किए बिना ऊपर आना सम्भव नहीं है। हमारी हर एक इन्द्रिय में राग-द्वेष; काम-क्रोध भरा रहता है। परन्तु हमें कभी भी इन चाहिए-न चाहिए, राग-द्वेष के वश नहीं होना चाहिए। 'मेरा' कहने वाला अति अनुराग (Possessiveness) हमें पतन की ओर ले जाता है। मुझे चाहिए, वह दूसरे को न मिले यह हर इन्द्रिय में भरा है। यह हमारी प्रवृत्ति के पीछे रहने वाला अहंकार (Ego) है। कृष्ण कहते हैं: \"कभी इन चाहिए-न चाहिए का दास मत बनो, वे तुम्हारी साधना की राह की दीवार हैं। वे तुम्हारे सच्चे शत्रु हैं\" ऐसा।\n\nहमें इन शत्रुओं का शिकार हुए बिना, अपनी इन्द्रियों का खुद विश्लेषण करना चाहिए। मेरी इन्द्रिय क्या चाह रही है, क्यों चाह रही है, उसके पीछे का स्वार्थ-द्वेष क्या है, यह मुझे राह भटकाने वाली इच्छा है या ऊपर लाने वाली इच्छा? ऐसा सोचकर हमें अपनी इच्छाओं का शुद्धीकरण करना चाहिए। वेद में कहा गया है 'आटे को छलनी से अलग करने जैसे' हमें अपने मन रूपी छलनी से अपनी इच्छाओं का शुद्धीकरण करना चाहिए।\n\nयहाँ कृष्ण अर्जुन से कहते हैं: युद्ध करते समय भी राग-द्वेष मन में मत रखो, केवल न्याय-अन्याय के संघर्ष जैसी निर्लिप्तता से लड़ो! अर्थात दुर्योधन मरे तब खुशी नहीं; अपना बेटा अभिमन्यु मरे तब दुख नहीं — यह युद्ध-पूर्व की सलाह है।",
  "3.35": "श्रेयान्स्वधर्मो विगुणः परधर्मात्स्वनुष्ठितात् ।\n\nस्वधर्मे निधनं श्रेयः परधर्मो भयावहः -- अपने स्वभाव से पराया धर्म अच्छी तरह आचरण करने से भी, अधूरा ही सही अपना सहज धर्म आचरण करना बेहतर है। स्वभाव-सहज धर्म में मृत्यु भी बेहतर है। पराया धर्म उससे भी भयंकर है।\n\nपहले कहा गया जैसे हर एक जीव का अपना स्वभाव होता है और उसे बदला नहीं जा सकता। जीव-स्वभाव के अनुसार हमारा धर्म, वह स्वधर्म है। यह स्वाभाविक क्रिया है। हमारा सहज स्वभाव जो भी हो वह करना चाहिए, दूसरा नहीं। इसीलिए माता-पिता अपनी रुचि बच्चों पर न थोपकर, बच्चों के सच्चे स्वभाव को पहचानकर उसके अनुसार उनका भविष्य बनाना चाहिए। नहीं तो उनका भविष्य बिगाड़ना ही हुआ। हर एक को अपने जीव-स्वभाव के अनुसार काम करना चाहिए, न कि किसी और के धर्म का अनुसरण करके। यहाँ कृष्ण कहते हैं \"तुम्हारे स्वधर्म के आचरण में कमी हो तब भी, वह पराए धर्म के आचरण से श्रेष्ठ है\" ऐसा। पराए धर्म को कितना भी पूर्णता से आचरण करें उससे भलाई नहीं है, वह अप्रिय या भयंकर है।\n\nयहाँ युद्ध करना अर्जुन का स्वभाव-धर्म है। उसे छोड़कर वह तपस्या करने जंगल जाना उसके स्वधर्म के विरुद्ध है। इसलिए स्वधर्म का पालन करो, राग-द्वेष छोड़कर लड़ो ऐसा कृष्ण कह रहे हैं।",
  "3.36": "अर्जुन उवाच — अर्जुन ने पूछा:\n\nअथ केन प्रयुक्तोऽयं पापं चरति पूरुषः ।\n\nअनिच्छन्नपि वार्ष्णेय बलादिव नियोजितः -- हे वार्ष्णेय, मनुष्य पाप करता है। खुद न चाहते हुए भी कोई जबरदस्ती करवा रहा हो जैसे! यह किसकी प्रेरणा है?\n\nकृष्ण का उपदेश सुनने के बाद अर्जुन हम सबको आने वाला एक बहुत महत्वपूर्ण प्रश्न पूछता है। \"पाप-पुण्य की समझ रखते हुए, न करने योग्य काम है यह जानते हुए भी, मनुष्य कभी-कभी गलती करता है — यह क्यों? हमें सही-गलत की समझ रहते हुए भी हम गलती क्यों करते हैं?",
  "3.37": "भगवानुवाच — भगवान बोले:\n\nकामः एष क्रोध एष रजोगुणसमुद्भवः ।\n\nमहाशनो महापाप्मा विद्ध्येनमिह वैरिणम् -- पाप को प्रेरित करने वाली शक्ति काम है (काम की अभिमानी कालनेमि)। इसी का रूपांतर गुस्सा है। रजोगुण से इसका जन्म है। यह जितना खाए उतना ही न भरने वाला पेटू है। महापातकों का घर है। इसे इस साधना-पथ में दुश्मन मानो।\n\nसब कुछ का मूल कारण हमारे अंदर की इच्छा है। कोई एक इच्छा हमें सता रही होती है, उस इच्छा को गलत करके पूरा किया जा सकता है ऐसी प्रेरणा हममें रहती है। यह करवाने वाला काम का अभिमानी दुष्ट शक्ति 'कालनेमि' है। हमारे अंदर कालनेमि आकर बैठे तो हमें बिना जाने हम गलती करते हैं। मूल रूप से देखें तो मनुष्य के गलती करने के दो कारण हैं। एक इच्छाएँ और इच्छा पूरी न होने पर गुस्सा। गुस्से के आवेग में मनुष्य कितनी गलती करता है यह कहना भी मुश्किल है।\n\nगलती करके अंत में पछताते हैं। इस क्रोध का मूल काम है। काम के बिना क्रोध नहीं। सारे क्रोध के पीछे अर्थहीन काम होता है।\n\nमनुष्य में रहने वाला रजोगुण राग-द्वेष बढ़ाता है। उसे कितना भी भोजन दें पेट नहीं भरता! इसका अच्छा उदाहरण: एक व्यक्ति काम के लिए भटकता रहता है, तब उसे पेट भरने के लिए एक काम मिल जाए तो काफी है ऐसी राय होती है। एक बार काम मिल जाए तो, उसकी इच्छा ज्यादा तनख्वाह पाने की ओर बहती है। ज्यादा मिलने पर और लालच, इस तरह यह बढ़ता जाता है। कभी भी संतोष नहीं होता।\n\nइस तरह हम गलती करने का अभ्यास कर लें तो वह 'महाशन' बन जाता है। उसे कितना भी भोज दें फिर चाहिए कहता है। यहाँ तक कि वह हमसे न करने योग्य काम भी करवाता है। कुरान में इसी को इस तरह कहा गया है \"Drive them out from where they drove you out\"। राग-द्वेष हमारे व्यक्तित्व को लूटकर खुद राज कर रहे हैं न, उन्हें बाहर निकालो, तुम अपने आप बनकर जियो।",
  "3.38": "धूमेनाव्रियते वह्निर्यथादर्शो मलेन च ।\n\nयथोल्बेनावृतो गर्भस्तथा तेनेदमावृतम् -- जैसे धुएँ से आग ढकी जाती है (भगवान), जैसे मैल से शीशा ढका जाता है (मन), जैसे गर्भ-कोश से भ्रूण ढका जाता है (जीव), वैसे काम से यह सब ढका हुआ है।\n\nधुआँ आग को ढकता है वैसे काम सज्जनों को ढकता है। मैल शीशे को बिगाड़ता है वैसे मध्यमों को। गर्भ-कोश भ्रूण को ढकता है वैसे दुर्जनों को।\n\nराग-द्वेष कैसे हमारी आँखों पर पट्टी बाँधते हैं इसका एक सुंदर वर्णन कृष्ण यहाँ देते हैं। सब कुछ को प्रकाशित करने वाली आग, वह खुद भी जलती है और सब कुछ प्रकाशित करती है। इस आग में धुआँ भर जाए तो वह दिखती नहीं और जलती भी नहीं। भगवान आग जैसे हैं। हमारा रजोगुण धुएँ जैसा है। हमारे और भगवान के बीच रजोगुण का पर्दा आग को लपेटे धुएँ जैसा है। यह सात्विक मनुष्य के लिए कृष्ण का दिया दृष्टांत है। राजस के लिए कृष्ण का दिया दृष्टांत काली स्याही लगा शीशा है। मन रूपी शीशे को रजोगुण रूपी मैल लगने जैसा कृष्ण कहते हैं। तामस के लिए कृष्ण का दृष्टांत गर्भ-थैली में रहने वाला भ्रूण है। सब कुछ अंधेरा है, आँख खोलने पर भी नहीं दिखता।\n\nइस तरह आग को धुएँ जैसे — भगवान को यह रजोगुण आवरण; शीशे को लगी स्याही जैसे — अंतःकरण को यह रजोगुण आवरण। अंतःकरण काम न करे तब भगवान नहीं दिखते, तब जीव के लिए 'भ्रूण जैसे' सब अंधेरा। सब कुछ होते हुए भी कुछ उपयोग न होकर व्यर्थ हो जाता है।",
  "3.39": "आवृतं ज्ञानमेतेन ज्ञानिनो नित्यवैरिणा ।\n\nकामरूपेण कौन्तेय दुष्पूरेणानलेन च -- हे कौन्तेय, आग जैसे निगलते हुए भी तृप्ति न होने वाला, अंतहीन यह काम साधक का चिरशत्रु है। यह जानने वालों की समझ को भी ढककर धुँधला बना देता है।\n\nयह रजोगुण का पर्दा — ज्ञान आए हुए को उसका ज्ञान उपयोग में न आने जैसे, ज्ञान न होने वाले को ज्ञान न आने जैसे — रोक बनकर खड़ा रहता है। राग-द्वेष हमारे कड़वे दुश्मन हैं। यह इतना भयंकर है कि इसे 'इच्छा की आग' कह सकते हैं। उसे कितना भी परोसें वह काफी नहीं कहता। कुंती जैसी महान माता के पुत्र तुम इस काम (इच्छा), हे कौन्तेय कहने वाले, ज्ञान-विरोधी शत्रु को जानो ऐसा कृष्ण कहते हैं।\n\nयहाँ हमें पता चला कि हमारा सच्चा दुश्मन हमारी काम या इच्छा, या राग-द्वेष है। तो फिर इस दुश्मन का ठिकाना कौन सा है? इसे कृष्ण अगले श्लोक में बताते हैं।",
  "3.40": "इन्द्रियाणि मनो बुद्धिरस्याधिष्ठानमुच्यते ।\n\nएतैर्विमोहयत्येष ज्ञानमावृत्य देहिनम् -- इन्द्रियाँ, मन, बुद्धि यह काम के ठिकाने हैं। इनके माध्यम से यह समझ को ढककर साधक को घबरा देता है।\n\nहमारी इच्छाओं की माला पहले आकर बैठती है हमारी इन्द्रिय में। आँख को देखना, कान को सुनना, नाक को सूंघना, शरीर को छूना — इस तरह एक-एक इच्छा एक-एक रूप में एक-एक इन्द्रिय में आकर बैठती है। वहाँ हम उसे न रोकें तो, वह हमारे मन पर कब्ज़ा करती है। वहाँ भी हम ढील दें तो वह आगे हमारी बुद्धि पर कब्ज़ा कर लेती है। इस तरह आँगन (इन्द्रिय) के इस दुश्मन को बरामदे (मन) में बुलाकर, फिर हमारे बीच के कमरे (बुद्धि) में बिठा देना जैसा है। एक बार यह दुश्मन हमारी बुद्धि पर कब्ज़ा कर ले तो आगे उसे हटाना बहुत मुश्किल है। इस स्थिति में इच्छा एक सिद्धांत बनकर हमारे अंदर बैठकर हम पर ही राज करना शुरू करती है। इससे कामना हमारा जीवन-धर्म बन जाता है। उदाहरण के लिए एक बात हमारे कान पर पड़ती है। हम उस विषय से हमें क्या उपयोग है उस पर ध्यान क्यों देना चाहिए ऐसा नहीं सोचते। उसे छोड़कर सुनी बात को देखने की चाह रखते हैं। देखने के बाद छूना (खाना, सूंघना आदि) चाहिए ऐसी इच्छा! इस तरह हम अपनी सारी इन्द्रियों में इस कामना नाम के दुश्मन को प्रोत्साहन देते हैं। तब वह धीरे-धीरे हमारे मन पर कब्ज़ा करती है। मन लगातार उस विषय के बारे में सोचने लगता है। मन 'वह मेरा होना चाहिए, मेरा ही होना चाहिए' ऐसा सोच रहा है तो इसका मतलब है यह दुश्मन मन पर कब्ज़ा कर चुका है। यहाँ से आगे बुद्धि — 'उसे छोड़कर मैं नहीं रह सकता, जो भी हो मुझे वह पाना ही है' ऐसे विचार। यह कामना हमारी बुद्धि पर कब्ज़ा करने का संकेत है। यह पूरे विनाश का पूर्वसंकेत है। इस तरह ज्ञान को भ्रमित करने वाली इन तीन जगहों में बैठकर ज्ञान के लिए पर्दा बनकर खड़ा रहता है यह हमारा दुश्मन।\n\nयहाँ 'देहिनम्' शब्द का प्रयोग हुआ है। हमारा शरीर ज्ञान के माध्यम से हमें ऊँचाई तक ले जाने का साधन है। परन्तु कामना नाम के दुश्मन का साथ करने पर वह हमें पतन की ओर धकेलने का साधन बन जाता है। यही इस शब्द के पीछे का भावार्थ है।\n\nइस तरह हमारा दुश्मन कौन है, वह कहाँ रहता है और वह हम पर कैसे कब्ज़ा करता है यह बताने वाले कृष्ण, आगे इस दुश्मन को जीतने का तरीका बताते हैं।",
  "3.41": "तस्मात्त्वमिन्द्रियाण्यादौ नियम्य भरतर्षभ ।\n\nपाप्मानं प्रजहि ह्येनं ज्ञानविज्ञाननाशनम् -- इसलिए, हे भरतवंश के वीर, पहले इन्द्रियों को काबू में करके, समझ और गहरी सोच-शक्ति को बरबाद कर सकने वाले इस पापी को खदेड़ दो।\n\nऐसे बड़े दुश्मन को हमें पहले चरण में ही नियंत्रित करना चाहिए। इस शत्रु के पहले प्रवेश-द्वार, इन्द्रिय में ही उसका नियंत्रण करना चाहिए। हमारे ज्ञान (श्रवण) को, विज्ञान-मनन (निदिध्यासन) को बरबाद कर, हमारी सोचने की शक्ति को नष्ट कर सकने वाले इस महापापी को खदेड़ दो ऐसा कृष्ण कहते हैं। परन्तु कैसे? इसमें कौन मदद करेगा? आगे सुनो!",
  "3.42": "इन्द्रियाणि पराण्याहुरिन्द्रियेभ्यः परं मनः ।\n\nमनसस्तु परा बुद्धिर्यो बुद्धेः परतस्तु सः -- इन्द्रियाँ (शरीर से) बड़े ठिकाने हैं (इन्द्रिय के अभिमानी इन्द्र आदि बड़े देवता हैं)। इन्द्रियों से मन बड़ा ठिकाना है (इन्द्रिय के अभिमानी देवताओं से मन के अभिमानी रुद्र बड़े देवता हैं)। मन से बुद्धि बड़ा ठिकाना है (मन के अभिमानी से बुद्धि की अभिमानी सरस्वती बड़ी देवी हैं)। बुद्धि से भी परे है वह परतत्व (बुद्धि की अभिमानी से भी बुद्धि-अगोचर भगवान बड़े तत्व हैं)।\n\nजैसे दुष्ट शक्तियाँ हैं वैसे ही हमारी भलाई चाहने वाली देवता-शक्तियाँ भी हमारी रक्षा के लिए खड़ी रहती हैं। हर एक इन्द्रिय का एक अभिमानी देवता है। हमारी इन्द्रिय का अभिमानी देवता इन्द्र है। मन का अभिमानी शिव-पार्वती हैं, बुद्धि की अभिमानी सरस्वती हैं। बुद्धि से परे है आत्मा — वही भगवान का स्थान है।\n\nएवं बुद्धेः परं बुद्ध्वा संस्तभ्यात्मानमात्मना ।\n\nजहि शत्रुं महाबाहो कामरूपं दुरासदम् -- हे महावीर, इस तरह बुद्धि से भी परे उस परतत्व को जानकर, विवेक से मन को थामकर, सामान्य लोगों के लिए न झुकने वाले काम नाम के दुश्मन को खदेड़ दो।\n\nहमें अपनी इन्द्रिय, मन, बुद्धि को नियंत्रित करने वाली देवता-शक्ति की शरण में जाना चाहिए। तब उन देवता-शक्तियों की मदद से हम ज्ञान पाकर भगवान को देख सकते हैं। हमारी हर एक इन्द्रिय का एक अभिमानी देवता है — आँख के लिए सूर्य, कान के लिए चंद्र, मुँह के लिए अग्नि, जीभ के लिए वरुण, नाक के लिए अश्विनी देवता, हाथ के लिए इन्द्र (यह सर्व-इन्द्रिय के स्वामी भी हैं), पैर के लिए इन्द्र-पुत्र उपेन्द्र, मल-मूत्र त्याग के अंग और संतान से संबंधित अंग के देवता यम और दक्ष हैं। इस तरह हर एक देवता हमें हमारे दुश्मन से पार पाने में मदद करते हैं। इस तरह देवताओं की प्रार्थना कर उनकी मदद पाकर दुष्ट शक्ति से दूर हटकर सबसे बड़े उस परतत्व तक पहुँचना चाहिए।\n\nइस तरह इन्द्रिय-मन-बुद्धि से परे उस परतत्व को जानकर, मन रूपी चंचल घोड़े को बुद्धि रूपी लगाम से बाँधकर, वह लगाम भगवान के हाथों सौंपकर, सारे देवताओं की मदद से कालनेमि नाम के राक्षस को चरण-दर-चरण जीतकर, भगवान तक पहुँचो ऐसा कृष्ण कहते हैं। यहाँ दी गई बात हमें बुरी इच्छा पैदा होने पर याद आ जाए तो कालनेमि नाम के राक्षस को हमारे अंदर घुसने से रोका जा सकता है। क्योंकि सारी इच्छाएँ बुरी नहीं होतीं। भगवान तक पहुँचना चाहिए ऐसी इच्छा चाहिए। इसलिए हमारी बुद्धि भगवान के हाथों सौंपकर, बुरी कामनाओं के विरुद्ध देवताओं की मदद से लड़कर मोक्ष पाया जा सकता है। यहाँ एक सजगता आवश्यक है, एक ही बार इस दुष्ट शक्ति के विरुद्ध लड़कर जीत हासिल करूँगा ऐसा सोचना असम्भव है। इसे चरण-दर-चरण पाना चाहिए। साधना की विभिन्न सीढ़ियों पर विभिन्न देवता हमारी मदद करते हैं।\n\nइस प्रकार तीसरा अध्याय समाप्त हुआ।",
  "3.43": "[बन्नंजे गोविंदाचार्य के भाष्य में तीसरा अध्याय ४२ श्लोकों के साथ समाप्त होता है। ३.४३ इस श्लोक का विवरण पिछले श्लोक में ही समाहित है। अध्याय का उपसंहार बस इतना ही है: काम-रूपी शत्रु को जीतो।]",
  "4.1": "भगवानुवाच — भगवान बोले:\n\nइमं विवस्वते योगं प्रोक्तवानहमव्ययम् ।\n\nविवस्वान्मनवे प्राह मनुरिक्ष्वाकवेऽब्रवीत् -- यह अविनाशी साधना-मार्ग मैंने सूर्य को बताया था। सूर्य ने मनु को बताया। मनु ने इक्ष्वाकु को बताया।\n\nएवं परम्पराप्राप्तमिमं राजर्षयो विदुः ।\nस कालेनेह महता योगो नष्टः परन्तप ॥२॥",
  "4.2": "एवं परम्परा प्राप्तमिमं राजर्षयो विदुः ।\n\nस कालेनेह महता योगो नष्टः परन्तप -- इस तरह एक से दूसरे को मिलते हुए आए इसे ज्ञानी राजाओं ने जाना था। हे शत्रुओं को काटने वाले, बहुत समय बाद वह ज्ञान का रास्ता इस धरती पर लुप्त हो गया।",
  "4.3": "स एवायं मया तेऽद्य योगः प्रोक्तः पुरातनः ।\n\nभक्तोऽसि मे सखा चेति रहस्यं ह्येतदुत्तमम् -- वही पुराना ज्ञान का रास्ता मैंने अब तुम्हें बताया — तुम मेरे भक्त और मित्र हो इसलिए। यह अत्यंत श्रेष्ठ रहस्य है।\n\nइन ऊपर के तीन श्लोकों में सृष्टि के आरंभ से यह ज्ञान-परम्परा कैसे बढ़ते आई इसका चित्रण कृष्ण ने दिया है। वास्तव में ज्ञान का मूल वेद हैं। वेद के सार को संग्रह कर, समस्त वेदार्थ का संग्रह करने वाला एक ग्रंथ रचा गया। उसे पंचरात्र कहा गया। पंचरात्र वैदिक वाङ्मय के ज्ञानयोग और कर्मयोग का सम्मिलित रूप वाला ग्रंथ है। उस पंचरात्र का सार-संग्रह ही भगवद्गीता है। सृष्टि के आरंभ में, स्वायंभुव मन्वंतर में भगवान ने पंचरात्र चतुर्मुख को उपदेश किया। इस तरह संसार की सृष्टि होते ही पंचरात्र का ज्ञान चतुर्मुख और देवताओं को मिला। सूर्य ने वैवस्वत मन्वंतर में इसे मनु को, मनु ने इक्ष्वाकु को बताया। यही कृष्ण यहाँ अर्जुन को समझा रहे हैं।\n\nसबसे पहले देवताओं ने भगवान से यह ज्ञान पाया। इन देवताओं में सूर्य भी एक है। सूर्य पृथ्वी और देवताओं को जोड़ने वाला देवता है। इससे वैवस्वत मन्वंतर के अभिमानी मनु को यह ज्ञान मिला। मनु ने इसे अपने पुत्र इक्ष्वाकु को बताया। यह पृथ्वी पर चक्रवर्ती बनकर जिए महान राजर्षि थे। इस तरह यह ज्ञान देवताओं से पृथ्वी तक बहकर आया।\n\nज्ञान अनादि-नित्य है। यह अविनाशी विद्या है। हर सृष्टि के आरंभ में यह विद्या भगवान द्वारा कही जाती है। फिर देवताओं को, देवताओं से राजर्षियों को, फिर ऋषियों को — इस तरह ज्ञान-परम्परा बढ़ती है। आज इस तरह बहकर आई विद्या लुप्त हो रही है; लोग भूल रहे हैं। महान ज्ञानी अर्जुन भी इस ज्ञान को भूल गया है। पहले कहा गया जैसे अर्जुन उस काल का महान ज्ञानी था। फिर भी उसे यह याद नहीं आ रहा। यहाँ कृष्ण अर्जुन को \"परंतप\" कहकर संबोधित करते हैं। परंतप अर्थात सदा भगवान को ज्ञान की दृष्टि से देख सकने वाला। \"तुम अपरोक्ष-ज्ञानी हो; तुम्हीं में यह ज्ञान-परम्परा है; फिर भी तुम्हें संशय हुआ; यह अनादि-नित्य ज्ञान-परम्परा तुम्हीं में लुप्त हो रही है, तो बाकी का क्या हाल?\" यह ध्वनि इस \"परंतप\" संबोधन में है।\n\nज्ञान नष्ट नहीं हुआ है, परन्तु मोह के पर्दे ने उसे रोक दिया है। इसलिए अब मैं तुम्हें फिर से वह ज्ञान बता रहा हूँ, ऐसा कृष्ण कहते हैं। अर्जुन के कृष्ण के प्रति असीम आदर, भक्ति और आत्मीयता को पहचानकर, कृष्ण अनादि-नित्य, अपूर्व इस ज्ञान को अर्जुन को याद दिलाते हैं। अर्जुन की भक्ति नवविध भक्तियों (श्रवण, कीर्तन, स्मरण, पादसेवन, अर्चन, वंदन, दास्य, सख्य और आत्मनिवेदन) में से सख्य है। उसने भगवान को मित्र के रूप में पूजा। इसीलिए कृष्ण यहाँ कहते हैं: \"तुम मेरे भक्त और मित्र हो। इसीलिए यह अमूल्य ज्ञान तुम्हें बता रहा हूँ\" ऐसा।\n\nयहाँ \"रहस्य ज्ञान तुम्हें बता रहा हूँ\" ऐसा कृष्ण ने कहा है। ज्ञान को रहस्य रखने के दो कारण हैं। एक उसका दुरुपयोग और दूसरा उसका निरुपयोग। जो ज्ञान पाकर अपनी पीढ़ी को नहीं दे पाएंगे उन्हें ज्ञान देना व्यर्थ है। इससे ज्ञान-परम्परा आगे नहीं बहती। और दुरुपयोग — ज्ञान हमारे अंतरात्मा के उद्धार के लिए और दूसरे के उद्धार का रास्ता दिखाने के लिए है, व्यापार करने के लिए नहीं। ज्ञान से समाज को धोखा दिया जा सकता है। समझ न रखने वालों को अपनी समझ से ठग सकते हैं। इन सब कारणों से ज्ञान रहस्य का विषय है। पहले योग-सिद्धि से लुप्त होने वाली विद्या ज्ञानियों को पता थी। ऐसी अमूल्य विद्या का दुरुपयोग बहुत आसान है। इसलिए इसे रहस्य रखा गया। पशुओं की भाषा समझने वाली विद्या भी हमारे पास थी। इसे भी रहस्य रखा गया। इस तरह जब भी ज्ञान के दुरुपयोग की संभावना हो तब उसे रहस्य रखना चाहिए। ऐसे रहस्य विषय को मैं \"तुम्हें चुनकर बता रहा हूँ\" ऐसा कृष्ण ने कहा है।",
  "4.4": "अर्जुन उवाच — अर्जुन ने पूछा:\n\nअपरं भवतो जन्म परं जन्म विवस्वतः ।\n\nकथमेतद्विजानीयां त्वमादौ प्रोक्तवानिति -- तुम्हारा जन्म हाल का है। सूर्य पहले जन्मा था। तुम ही पहले बताने वाले हो ऐसा कहो तो इसे कैसे समझूँ?\n\nज्ञान-परम्परा बताते हुए कृष्ण ने कहा \"मैंने पहले सूर्य को (देवताओं को) बताया\" ऐसा। यहाँ अर्जुन कृष्ण से इस बारे में प्रश्न करता है। उम्र में कृष्ण अर्जुन से लगभग छह महीने बड़े हैं। ऐसे में करोड़ों वर्ष पहले सूर्य को बताया कहते हो तो इसे कैसे समझूँ, यह अर्जुन का प्रश्न है।\n\nयहाँ अर्जुन को स्वयं भगवान से इस प्रश्न का उत्तर पाने की इच्छा है। इसीलिए यह प्रश्न रखा है। इतना ही नहीं, सभी मनुष्यों के प्रतिनिधि बनकर खड़े महाज्ञानी अर्जुन, हम सबकी ओर से यह प्रश्न पूछता है।",
  "4.5": "भगवानुवाच — भगवान बोले।\n\nबहूनि मे व्यतीतानि जन्मानि तव चार्जुन ।\n\nतान्यहं वेद सर्वाणि न त्वं वेत्थ परन्तप -- हे अर्जुन, मेरे कई जन्म हो चुके। तुम्हारे भी। हे शत्रुओं को काटने वाले, वे सब मुझे पता हैं — परन्तु तुम्हें पता नहीं।\n\nजन्म अर्थात जनन या जन्म लेना। जो नहीं है वह जन्म नहीं लेता। जड़ के जन्म लेने की बात नहीं कहते। सूक्ष्म शरीर से स्थूल शरीर में प्रकट होना जन्म है। मरना अर्थात सूक्ष्म शरीर का स्थूल शरीर छोड़ना। यहाँ कृष्ण कहते हैं: \"मेरे और तुम्हारे कई जन्म हो चुके। मुझे यह पता है परन्तु शत्रुओं को काटने वाले तुम्हें यह बात पता नहीं\" ऐसा।",
  "4.6": "अजोऽपि सन्नव्ययात्मा भूतानामीश्वरोऽपि सन् ।\n\nप्रकृतिं स्वामधिष्ठाय सम्भवाम्यात्ममायया -- मुझे जन्म नहीं है। मेरे शरीर को भी मृत्यु नहीं है। मैं सभी जीवों के स्वामियों का भी स्वामी हूँ। फिर भी अपने अधीन प्रकृतिमय शरीर में प्रवेश कर ज्ञान-स्वरूप से ही (अपने सहज स्वभाव के अनुसार अपनी इच्छा से ही) प्रकट होता हूँ।\n\nसमस्त जीव-जाति के स्वामी भगवान कई बार पृथ्वी पर अवतरित होते हैं। उन्हें जन्म नहीं कहते। फिर भी जन्म लेकर आते हैं। वे अव्यय हैं; वे नश्वर देह लेकर जन्म नहीं लेते। इसलिए देह के माध्यम से जन्म-मृत्यु भगवान को नहीं है। यहाँ आए 'आत्ममायया' शब्द के कई अर्थ हैं। जीव को ढकने वाला मोह का पर्दा आत्ममाया है; भगवान की महिमा आत्ममाया है; भगवान की अपनी इच्छा और ज्ञान आत्ममाया है। भगवान का पृथ्वी पर अवतरित होना उनके ज्ञान की महिमा से है, किसी माया के अधीन होकर नहीं। भगवान अपने भक्तों की चाह पूरी करने के लिए, इच्छापूर्वक स्वयं बनाई प्रकृति को माध्यम बनाकर अवतरित होते हैं। यही उनकी महिमा है। मोह के पर्दे में जीने वाले हमें यह एक साधारण जन्म जैसा दिखता है, क्योंकि हम उनका ज्ञानानंदमय शरीर देख नहीं सकते।",
  "4.7": "यदा यदा हि धर्मस्य ग्लानिर्भवति भारत ।\n\nअभ्युत्थानमधर्मस्य तदात्मानं सृजाम्यहम् -- हे भारत, जब-जब धर्म क्षीण होता है और अधर्म सिर उठाता है, तब मैं स्वयं को उत्पन्न करता हूँ।\n\nपूरे संसार में जब कभी धर्म मलिन होकर अधर्म के सामने हार मानकर सिर झुकाकर खड़ा होने का प्रसंग आता है, तब मैं धरती पर उतर आता हूँ, ऐसा कृष्ण कहते हैं। यहाँ धर्म का हारना अर्थात यह किसी एक घर या एक देश से जुड़ा विषय नहीं है। पूरे विश्व में ही धर्म को जगह न मिलने की स्थिति आने पर भगवान का अवतार होता है। दुष्ट शक्तियाँ पृथ्वी पर पकड़ बनाकर सत्व-गुण को सिर न उठाने दें तब भगवान स्वयं को पृथ्वी पर उत्पन्न करते हैं। \"तदात्मानं सृजाम्यहम्\" में दो ध्वनियाँ हैं — \"मैं अपने आत्मीयों को भेजता हूँ\" और \"मैं स्वयं अवतरित होता हूँ\"। धर्म के हारने के लक्षण क्षेत्रीय रूप से दिखने पर भगवान अपने आत्मीयों (देवताओं) को पृथ्वी पर भेजते हैं। वे आचार्य-पुरुष बनकर आकर समाज को सुधारते हैं। ऐसी व्यवस्था भी टूटकर तामसिक शक्तियाँ विजृंभित हों तब अंत में भगवान स्वयं अवतार लेते हैं। कृष्ण के अवतार के समय की स्थिति देखने पर उस काल में धर्म की क्या दशा थी यह स्पष्ट होता है — जरासंध ने संसार भर के लगभग 22,800 राजकुमारों को बंदी बना रखा था।",
  "4.8": "परित्राणाय साधूनां विनाशाय च दुष्कृताम् ।\n\nधर्मसंस्थापनार्थाय सम्भवामि युगे युगे -- सज्जनों की रक्षा के लिए, दुष्टों के नाश के लिए, धर्म की स्थापना के लिए मैं युग-युग में उत्पन्न होता हूँ।\n\nजो समाज को बुराई करके उससे लाभ पाकर इतराते हैं, उनके पूर्ण नाश के लिए, सज्जनों और संसार की समग्र रक्षा के लिए, धर्म का बीज बोने भगवान पृथ्वी पर अवतरित होते हैं। यहाँ \"युगे-युगे\" का अर्थ है \"युग-युग में\"। इसका मतलब यह नहीं कि भगवान हर युग में अवतरित होते हैं। वे तभी अवतरित होते हैं जब ऊपर बताई स्थिति आए। किसी एक युग में कई अवतार हो सकते हैं; किसी युग में अवतार बिल्कुल न भी हो। परन्तु भगवान की अभिव्यक्ति वाले अनेक महापुरुष युग-युग में आते-जाते रहते हैं। उनके माध्यम से भगवान की धर्म-रक्षा युग-युग में निरंतर चलती है।",
  "4.9": "जन्म कर्म च मे दिव्यमेवं यो वेत्ति तत्त्वतः ।\n\nत्यक्त्वा देहं पुनर्जन्म नैति मामेति सोऽर्जुन -- हे अर्जुन, इस तरह मेरे दिव्य जन्म और कर्म को जो यथार्थ रूप से जानता है, वह देह त्यागकर फिर जन्म नहीं लेता — वह मुझे प्राप्त होता है।\n\nइस तरह भगवान के ज्ञानानंदमय, दिव्य, लीलामय अवतार की समझ यथावत (तत्त्वतः) आ जाए तो वह हमें मोक्ष का मार्ग दिखा सकती है। यह पुनर्जन्म-रहित मोक्ष पाने के लिए जरूरी एक अमूल्य ज्ञान है।",
  "4.10": "वीतरागभयक्रोधा मन्मया मामुपाश्रिताः ।\n\nबहवो ज्ञानतपसा पूता मद्भावमागताः -- राग-भय-क्रोध छोड़ने वाले, हर जगह मुझे ही देखने वाले (मेरी महिमा जानने वाले), मेरी शरण में आए बहुत से लोग — ज्ञान की तपस्या से शुद्ध होकर मुझसे मिल चुके हैं।\n\nतीसरे अध्याय के अंत में (श्लोक 39) कृष्ण ने कहा जैसे राग-द्वेष आदि हमारे परम शत्रु हैं। हमें जीवन की सभी समस्याओं के कारण बने लगाव (इच्छा, राग), डर (भय), और गुस्सा (क्रोध) छोड़कर, जो है उसमें खुश रहना और जो मिले उसे खुशी से स्वीकार करने की मनोवृत्ति बढ़ाकर, मन्मय बनना चाहिए। 'मन्मय' अर्थात जीवन की सभी राहों में भगवान को भरना और सांसारिक चेतना को कम करना। एक बार हम भगवान के चिंतन में लगें तो यह राग-द्वेष तुच्छ लगने लगते हैं।",
  "4.11": "ये यथा मां प्रपद्यन्ते तांस्तथैव भजाम्यहम् ।\n\nमम वर्त्मानुवर्तन्ते मनुष्याः पार्थ सर्वशः -- जो जिस तरह मुझे भजते हैं, उन्हें मैं उसी तरह अनुगृहीत करता हूँ। हे पार्थ, मनुष्य चाहे जिस राह चलें, अंत में मुझ तक ही पहुँचते हैं।\n\nभगवान की उपासना का सही रास्ता कौन सा है? हर कोई एक-एक तरह से उपासना करता है। इससे भ्रम, उत्तेजना होती है। जो जिस तरह उपासना करता है भगवान उसी तरह अनुगृहीत करते हैं। हम जिस भी रूप से उपासना करें वह विश्वरूप भगवान तक पहुँचती है। इसीलिए हम अपनी पूजा तुलसी, अश्वत्थ वृक्ष, गाय आदि रूपों में करते हैं जिनमें भगवान की विशेष विभूति है। परन्तु यहाँ एक सजगता आवश्यक है — तुलसी के पौधे को ही भगवान मानकर पूजा न करते हुए, तुलसी में भगवान की विशेष विभूति छिपी है ऐसा जानकर पूजा करना महत्वपूर्ण है।",
  "4.12": "काङ्क्षन्तः कर्मणां सिद्धिं यजन्त इह देवताः ।\n\nक्षिप्रं हि मानुषे लोके सिद्धिर्भवति कर्मजा -- कर्मों के फल की चाह रखने वाले यहाँ देवताओं की पूजा करते हैं। इस पृथ्वी पर कर्म से फल-सिद्धि जल्दी मिल ही जाती है न?\n\nहममें से कुछ लोग देवताओं और भगवान के बीच का अंतर न जानते हुए, देवताओं को ही भगवान मानकर पूजते हैं। यह देवताओं के बारे में हमारी एक गलत धारणा है। भगवान अनेक नहीं, वे एक ही हैं; परन्तु भगवान के अधीन देवता अनेक हैं। तुरंत फल पाने की चाह से भगवान को भूलकर देवताओं के समूह की पूजा करने की परम्परा हमने बढ़ा ली है। ऐसा करने से फल मिल सकता है — परन्तु वह अल्पकालीन है। सांसारिक सुख की चाह से विभिन्न देवताओं को विभिन्न फल के लिए पूजना हमें शाश्वत मोक्ष के मार्ग तक नहीं ले जा सकता।",
  "4.13": "चातुर्वर्ण्यं मया सृष्टं गुणकर्मविभागशः ।\n\nतस्य कर्तारमपि मां विद्ध्यकर्तारमव्ययम् -- गुण और कर्म के बँटवारे से मैंने चार वर्णों का समूह बनाया है। इसे करने वाला होते हुए भी मुझ अपरिवर्तनीय को अकर्ता जानो।\n\nकृष्ण कहते हैं: \"मैंने गुण-कर्म-विभाग से चार वर्ण बनाए\" ऐसा। जैसा हमें पता है चार वर्ण — ब्राह्मण, क्षत्रिय, वैश्य और शूद्र। भगवान की इस बात को गलत समझने वाले ही ज्यादा हैं। मूल रूप से देखें तो कृष्ण यहाँ जाति के बारे में नहीं, बल्कि चार वर्णों के बारे में कह रहे हैं। वर्ण और जाति को मिलाकर भी इस्तेमाल करते हैं। संस्कृत में एक शब्द के कई अर्थ होते हैं। जाति शब्द के दो अर्थ हैं। एक है जन्म से मिला गुण-स्वभाव (जीव-स्वभाव — जन्म के समय ही पाया, मूल त्रिगुण से संबंधित) वह वर्ण है; दूसरा है जिस घर में जन्मा वह जाति (ब्राह्मण के घर जन्मा लड़का ब्राह्मण लड़का, क्षत्रिय के घर जन्मा लड़का क्षत्रिय लड़का)। यह सूक्ष्मता न समझें तो यहाँ हमें भ्रम होता है। इसलिए इस श्लोक में वर्ण अर्थात मूल जन्म का वर्ण — वर्ण अर्थात रंग भी। एक मनुष्य का रंग अर्थात क्या? \"उसका रंग खुल गया\" ऐसा हम सामान्यतः कहते हैं। किसी का रंग खुलना अर्थात उसका असली व्यक्तित्व सामने आना। हमारे स्वभाव का भी एक रंग है — सात्विक-सफेद; राजस-लाल; तामस-काला। इस तरह रंग स्वभाव का प्रतिनिधित्व करता है।\n\nपुरुष-सूक्त में इन चार वर्णों को उनके-उनके कर्म के अनुसार शरीर के चार अंग बताकर वर्णन किया गया है: \"ब्राह्मणोऽस्य मुखमासीत्, बाहू राजन्यः कृतः, ऊरू तदस्य यद्वैश्यः, पद्भ्यां शूद्रोऽजायत।\" शरीर के पंचांगों में से एक और पूजा में श्रेष्ठ माने जाने वाले पैर की तुलना शूद्र से की गई। यह शरीर की नींव है। जाति जन्म से है परन्तु वर्ण गुण-कर्म से बाँटे गए हैं। ब्राह्मण के घर जन्मा लड़का ब्राह्मण जाति का लड़का है। परन्तु वह स्वभाव से क्षत्रिय भी हो सकता है; एक ही घर में चार वर्णों के बच्चे जन्म ले सकते हैं। जीव-स्वभाव और कर्म के अनुसार भगवान जीव को जन्म के समय ही एक वर्ण देते हैं।",
  "4.14": "न मां कर्माणि लिम्पन्ति न मे कर्मफले स्पृहा ।\n\nइति मां योऽभिजानाति कर्मभिर्न स बध्यते -- कर्म मुझे नहीं चिपकते। मुझे कर्मफल की चाह नहीं है। ऐसा जो मुझे जानता है वह कर्मों में नहीं बंधता।\n\nअपने-अपने स्वभाव के अनुसार, अपने-अपने कर्म के अनुसार (गुण-कर्म-विभागशः) संसार रूपी बगीचा बनाकर, चार वर्णों के मोक्ष-योग्य मानवों की सृष्टि इस पृथ्वी पर की। \"इससे मुझे कोई कर्म नहीं चिपकता\" ऐसा कृष्ण कहते हैं। कर्म चिपकना 'यह मेरा है', 'मैंने किया' ऐसा अभिमान रहने पर ही होता है। भगवान को कर्म का लगाव या नाता नहीं है।",
  "4.15": "एवं ज्ञात्वा कृतं कर्म पूर्वैरपि मुमुक्षुभिः ।\n\nकुरु कर्मैव तस्मात्त्वं पूर्वैः पूर्वतरं कृतम् -- मुक्ति चाहने वाले पहले के लोगों ने भी इस तरह \"जानकर\" कर्म किया। इसलिए पहले से चले आए, बड़ों द्वारा किए गए कर्म को ही तुम करो।\n\nकर्म के बंधन से छूटने के लिए 'निष्क्रियता' सरल उपाय है ऐसा कोई सोच सकता है। कृष्ण निष्क्रियता का प्रबल विरोध करते हैं। 'सौ वर्ष जियो परन्तु कर्तव्य-कर्म करते हुए जियो। निष्क्रिय होकर मत जियो' — यह कृष्ण का सिद्धांत है।",
  "4.16": "किं कर्म किमकर्मेति कवयोऽप्यत्र मोहिताः ।\n\nतत्ते कर्म प्रवक्ष्यामि यज्ज्ञात्वा मोक्ष्यसेऽशुभात् -- क्या कर्म है, क्या अकर्म है — इसमें जानकार भी उलझ जाते हैं। वह कर्म तुम्हें बताऊँगा, जिसे जानकर तुम बुराई से पार हो जाओगे।",
  "4.17": "कर्मणो ह्यपि बोद्धव्यं बोद्धव्यं च विकर्मणः ।\n\nअकर्मणश्च बोद्धव्यं गहना कर्मणो गतिः -- कर्म के बारे में भी जानना चाहिए। विरुद्ध कर्म के बारे में भी जानना चाहिए, कर्म-त्याग के बारे में भी जानना चाहिए। कर्म की चाल गूढ़ है।\n\nक्या कर्म है, क्या अकर्म है यह ज्ञानियों के लिए भी उलझन का विषय है। हम जो करते हैं वह जानकर करना चाहिए। हमारा कर्म ज्ञानपूर्वक होना चाहिए। इसलिए कर्म क्या है यह पहले तुम्हें बताता हूँ। इससे तुम बुराई से पार हो जाओगे, ऐसा कृष्ण कहते हैं।\n\nकर्म के बारे में जानना इतना आसान नहीं है। परन्तु यह जानना ही चाहिए। कर्म की चाल अत्यंत रहस्यमय है। क्या कर्म है क्या अकर्म है यह जानना बहुत कठिन है। बड़े-बड़े ज्ञानियों को भी यह पता नहीं चलता।",
  "4.18": "कर्मण्यकर्म यः पश्येदकर्मणि च कर्म यः ।\n\nस बुद्धिमान्मनुष्येषु स युक्तः कृत्स्नकर्मकृत् -- जो कर्म में अकर्म देखे, अकर्म में कर्म देखे, वह मनुष्यों में बुद्धिमान है। वही युक्त है; वही सारे कर्म का, उसके फल का प्राप्तकर्ता है।\n\nकर्म क्या है इस बारे में बहुत रोचक विचार कृष्ण यहाँ बताते हैं। पहले कहा गया जैसे संस्कृत रहस्यार्थ वाली भाषा है। इसीलिए भगवद्गीता पढ़ते ही, अध्यात्म का अनुभव न हो तो कुछ भी समझ नहीं आता। अध्यात्म के अनुभव के स्तर में हम जितनी गहराई उतरते हैं उतनी गहराई तक गीता खुलती है। इसका उदाहरण यही श्लोक है। ऊपरी तौर पर पहेली जैसा, विरोधाभास वाला पागलपन भरा कथन जैसा दिखता है यह श्लोक! यहाँ ऐसा कहा गया है: \"जहाँ कर्म है वहाँ कर्म नहीं है, जहाँ कर्म नहीं है वहाँ कर्म है। यह जिसे पता है वह बुद्धिमान है\" या \"जो कर्म है वह कर्म नहीं है, जो कर्म नहीं है वह कर्म है; यह जानने वाला बुद्धिमान है\" — यहाँ छिपे गूढ़ अर्थ को समझने के लिए अध्ययन के साथ अध्यात्म का अनुभव चाहिए।\n\n'जहाँ कर्म है वहाँ कर्म नहीं है'। हम अपने में कर्म है ऐसा मानते हैं। 'मुझमें कर्म की स्वतंत्रता है — मुझे किसी की परवाह नहीं' ऐसा भाव हमारा है। परन्तु हममें रहने वाला कर्म भगवान के अधीन है। इस सृष्टि-चक्र में हम कुछ भी न करें तब भी क्रिया निरंतर चलती रहती है। तुम कुछ भी कर रहे हो तो तुम्हारे कारण से क्रिया नहीं हुई। मुझमें क्रिया है यह भ्रम छोड़ दो। प्रकृति निरंतर अपना कर्तव्य करती रहती है।\n\nइसे समझने के लिए एक सांसारिक दृष्टांत देखें। एक हाथी (यह विश्व-चक्र) है, उसके सिर पर एक छोटी चींटी (सामान्य मानव)। हाथी पूरब से पश्चिम जा रहा है। चींटी निरंतर सिर से पूंछ तक अर्थात पश्चिम से पूरब जा रही है। परन्तु हाथी पर रहने वाली यह चींटी चाहे जिस दिशा चले, वह हाथी जहाँ पहुँचेगा वहीं पहुँचेगी। यहाँ चींटी की चाल व्यर्थ है — इससे कोई उपयोग नहीं। अगर यह चींटी सोचे कि मेरे कारण हाथी वहाँ से यहाँ आ पहुँचा तो? कितना हास्यास्पद है न! वैसे ही, हमारी गति के पीछे एक महान चालक-शक्ति है।",
  "4.19": "यस्य सर्वे समारम्भाः कामसङ्कल्पवर्जिताः ।\n\nज्ञानाग्निदग्धकर्माणं तमाहुः पण्डितं बुधाः -- करने की चाह, पाने की चाह छोड़कर सभी कर्मों में लगने वाला, ज्ञान की आग से कर्मों को जला चुका — जानकार लोग ऐसे व्यक्ति को पंडित कहते हैं।\n\nहमारे जीवन के जुड़ाव के पीछे एक कामना, संकल्प रहता है। मुझे सुख मिलना चाहिए, अपने घर वालों को सुखी रखना चाहिए ऐसी कामना। इसके लिए हम कोई न कोई तरीका अपनाते हैं। यह हर क्रिया के पीछे मनुष्य को सताने वाली समस्या है। अपनी इच्छा पूरी करने के लिए हम खुद को लगाते हैं। जिसके जुड़ाव में इच्छाओं का स्पर्श नहीं है वह पंडित है। पंडित की पांडित्य उसकी बात में नहीं, उसके आचरण में देखना चाहिए।",
  "4.20": "त्यक्त्वा कर्मफलासङ्गं नित्यतृप्तो निराश्रयः ।\n\nकर्मण्यभिप्रवृत्तोऽपि नैव किञ्चित्करोति सः -- कर्मफल में मोह छोड़कर, नित्य तृप्त, आश्रयरहित — कर्म में लगा होते हुए भी वह कुछ नहीं करता।\n\nकुछ को यह चाहिए, वह चाहिए ऐसी इच्छा नहीं होती। परन्तु मिलने पर खुशी होती है। कर्मफल में अधिक स्नेह अच्छा नहीं है। भगवान की प्रेरणा से जो मिला उसका सही उपयोग कैसे करें यह सोचो; इतराओ मत। मिलना चाहिए ऐसी अपेक्षा मत रखो, बिना अपेक्षा के मिलने पर उछलो मत। फल के प्रति अधिक ममता अच्छी नहीं है। यही एक तरीका है जिससे मनुष्य सुख-चैन से जी सकता है।",
  "4.21": "निराशीर्यतचित्तात्मा त्यक्तसर्वपरिग्रहः ।\n\nशारीरं केवलं कर्म कुर्वन्नाप्नोति किल्बिषम् -- मन-चित्त को काबू में रखने पर चाह दूर हो जाती है। मैं-मेरा का भाव मिट जाता है। शरीर पोषण के लिए ही कर्म करें तो भी दोष नहीं लगता।\n\nनित्य-तृप्त रहना चाहिए ऐसी इच्छा है परन्तु उसे कैसे अपनाएँ? इस प्रश्न का उत्तर कृष्ण यहाँ देते हैं। सांसारिक इच्छा हो तो असंतोष अवश्यंभावी है। न होने वाली चीज़ की चाह से कभी सुख नहीं मिलता। संतोष के लिए पहले चाहिए-न चाहिए की सूची कम करनी चाहिए। पहले 'यतचित्त बनो' फिर 'निराशी बनो' (desireless) ऐसा कृष्ण कहते हैं।",
  "4.22": "यदृच्छालाभसन्तुष्टो द्वन्द्वातीतो विमत्सरः ।\n\nसमः सिद्धावसिद्धौ च कृत्वापि न निबध्यते -- अपने आप मिली चीज़ में संतुष्ट रहने वाला, जीवन की दुविधा से ऊपर उठा हुआ, दूसरों की तरक्की से जलन न रखने वाला, सफलता-असफलता को एक ही नज़र से देखने वाला — कर्म करते हुए भी उसके बंधन में नहीं फँसता।\n\nहमारा मन हमारे काबू में आने पर दिखने वाले मुख्य लक्षण के बारे में यहाँ विवरण है। संतोष पाने वाले को कुछ भी मिले तो उसी में खुश रहता है। मिला हुआ कम है ऐसा या कुछ और मिले ऐसा उसका मन नहीं चाहता। क्योंकि हमें जो भी मिलता है वह भगवान की इच्छा से मिलता है।",
  "4.23": "गतसङ्गस्य मुक्तस्य ज्ञानावस्थितचेतसः ।\n\nयज्ञायाचरतः कर्म समग्रं प्रविलीयते -- फल का नाता छोड़कर, देह-अभिमान छोड़कर, भगवान के बोध में ही मन लगाकर, पूजा समझकर करने वाले का सारा कर्म लय हो जाता है।\n\nइस श्लोक में ऊपर कही सारी बात को उपसंहार के रूप में भगवान हमारे सामने रखते हैं। फल के बारे में अत्यधिक इच्छा मत रखो; अत्यधिक अपेक्षा मत रखो; कर्तव्यनिष्ठा हो; देह-अभिमान, परिवार का अभिमान छोड़कर निर्लिप्त होकर जीना सीखो; मन को ज्ञान-स्वरूप भगवान (चेतस्) में स्थिर करो। ऐसे जीने पर हमारा किया सारा कर्म यज्ञ बनकर यज्ञ नाम वाले भगवान तक पहुँचता है और ज्ञान की आग में कर्म की गंदगी जल जाती है।",
  "4.24": "ब्रह्मार्पणं ब्रह्म हविर्ब्रह्माग्नौ ब्रह्मणा हुतम् ।\n\nब्रह्मैव तेन गन्तव्यं ब्रह्मकर्मसमाधिना -- अर्पण भी भगवान (भगवान में अर्पण)। अर्पित की जाने वाली हवि भी भगवान (भगवान रूपी हवि)। आग के रूप वाले भगवान में (भगवान के अधीन आग में) भगवान से ही हवन हुआ। मन की एकाग्रता के साथ कर्म की व्यग्रता भी भगवान ही है (भगवान के अधीन)।\n\nअभिमान त्यागकर ज्ञान की स्थिति में कर्म करें तो कैसा होता है इसका उत्तर है \"ब्रह्मार्पणं ब्रह्महविः\"। यहाँ अर्पण को इस तरह समझा जा सकता है। हम एक हवि को अग्नि में भगवान को अर्पित करते हैं — यह अर्पण है। एक भूखे को अन्न देते हैं — यह अर्पण है। एक योग्य वर को कन्यादान करते हैं — यह अर्पण है। किसी की धन-समस्या में मदद करते हैं — यह अर्पण है। यहाँ देने वाला भी वह भगवान, लेने वाले के अंदर रहकर स्वीकार करने वाला भी वही है। सब कुछ भगवान की इच्छा से चलता है।",
  "4.25": "दैवमेवापरे यज्ञं योगिनः पर्युपासते ।\n\nब्रह्माग्नावपरे यज्ञं यज्ञेनैवोपजुह्वति -- कुछ साधक भगवान की उपासना रूपी मानस यज्ञ का आचरण करते हैं (भगवान को ही यज्ञ-रूप मानकर पूजते हैं)। कुछ आग के रूप वाले भगवान में हवन करके बाह्य यज्ञ से यज्ञ-नाम वाले भगवान को पूजते हैं।\n\nभगवान की उपासना के मार्ग पर चलने वाले कुछ योगी (साधक) दैव को ही यज्ञ मानकर उपासना करते हैं। अर्थात निरंतर अंतरात्मा में भगवान की उपासना ही उनका यज्ञ है। इसके लिए किसी बाहरी सामग्री की जरूरत नहीं। यह ध्यान-रूप यज्ञ है।",
  "4.26": "श्रोत्रादीनीन्द्रियाण्यन्ये संयमाग्निषु जुह्वति ।\n\nशब्दादीन्विषयानन्य इन्द्रियाग्निषु जुह्वति -- कुछ कान आदि इन्द्रियों को संयम की आग में हवन करते हैं। कुछ शब्द आदि विषयों को इन्द्रियों की आग में हवन करते हैं।\n\nएक साधक में होना चाहिए ऐसी विशेष साधना भी एक यज्ञ है। इन्द्रिय रूपी हवि को 'निग्रह' नाम की आग में आहुति देना एक यज्ञ है। बुरा नहीं सुनना, बुरा नहीं बोलना, बुरा नहीं देखना ऐसे दृढ़ निश्चय से, इन्द्रिय-संयम से इन्द्रिय-चंचलता का हवन करो।",
  "4.27": "सर्वाणीन्द्रियकर्माणि प्राणकर्माणि चापरे ।\n\nआत्मसंयमयोगाग्नौ जुह्वति ज्ञानदीपिते -- कुछ सारी इन्द्रिय-क्रियाओं और प्राणवायु की क्रियाओं को ज्ञान से जगमगाई आत्म-निग्रह की साधना रूपी आग में हवन करते हैं।\n\nहमारे शरीर में ज्ञानेन्द्रिय और कर्मेन्द्रिय से निरंतर क्रिया चलती रहती है। इसके अलावा प्राण-शक्ति से होने वाली अनेक क्रियाएँ हैं (जैसे साँस लेना, बल, संतान-शक्ति, खुशी या दुख में आँसू आदि)। मनोनिग्रह नाम की आग में इस ज्ञानेन्द्रिय, कर्मेन्द्रिय और प्राण-शक्ति से होने वाली क्रिया का हवन (नियंत्रण) करना एक यज्ञ है।",
  "4.28": "द्रव्ययज्ञास्तपोयज्ञा योगयज्ञास्तथापरे ।\n\nस्वाध्यायज्ञानयज्ञाश्च यतयः संशितव्रताः -- कुछ संपत्ति का हवन करने वाले हैं। कुछ तपस्या को ही भगवान में हवन करने वाले हैं। कर्म-साधना ही कुछ का यज्ञ है। तीखी निष्ठा से प्रयत्नशील कुछ लोगों के लिए वेद-अध्ययन, भगवान का बोध ही यज्ञ है।\n\nद्रव्य-यज्ञ: कुछ लोग संपत्ति के माध्यम से भगवान की आराधना करते हैं। यह अग्नि के मुख से हो सकता है, धन-दान, अन्न-दान, कन्या-दान आदि दानों के माध्यम से हो सकता है। योग्य व्यक्ति को, योग्य समय में, योग्य चीज़, उनमें बसे भगवान प्रसन्न हों ऐसी भावना से देना द्रव्य-यज्ञ है।\n\nतप-यज्ञ: इसके दो पहलू हैं — बाहरी और भीतरी। एक निरंतर ध्यान, इसे बाहरी सामग्री की जरूरत नहीं। दूसरा भगवान के चिंतन के लिए जरूरी आत्म-संयम — इसे तपस्या कहते हैं। उदाहरण के लिए ब्रह्मचर्य-पालन, व्रत-अनुष्ठान आदि।\n\nयोग-यज्ञ: अर्थात विविध प्रकार के कर्मयोग को भगवान की प्रसन्नता के लिए अनुष्ठान करना। यह बाहरी कर्मों के माध्यम से भगवान की आराधना है। उदाहरण के लिए: भगवान की 108 परिक्रमा, अर्चना आदि।\n\nस्वाध्याय-ज्ञान-यज्ञ: यह भगवान को सबसे प्रिय यज्ञ है। यहाँ स्वाध्याय के कई अर्थ हैं। अपने से संबंधित, अपने पढ़ने योग्य को पढ़ना। अपनी शाखा का वेद-अध्ययन; सब जगह स्वतंत्र सर्वोत्तम भगवान के गुण को अध्ययन के माध्यम से सभी ग्रंथों में पाना स्वाध्याय है।",
  "4.29": "अपाने जुह्वति प्राणं प्राणेऽपानं तथापरे ।\n\nप्राणापानगती रुद्ध्वा प्राणायामपरायणाः -- फिर कुछ प्राणायाम के साधक हैं। प्राण-अपान की चाल को रोककर अपान में प्राण का हवन करते हैं। प्राण में अपान का।\n\nयोग में विशिष्ट साधना प्राणायाम है। कुछ के लिए प्राणायाम ही जीवन में एक साधना है। प्राण-अपान को भगवान में यज्ञ रूप से अर्पित कर, प्राणायाम से भगवान की उपासना — अपान में प्राण का हवन करना। यह कुम्भक से संबंधित है। शरीर के भीतर से साँस बाहर छोड़ना 'रेचक'; ऑक्सीजनयुक्त शुद्ध हवा भीतर लेना 'पूरक'। हमारे हृदय-कलश में प्राण-शक्ति को थामे रखना — 'कुम्भक'। यह बहुत प्रभावी है।\n\nइससे एकाग्रता, स्वास्थ्य, आयु बढ़ती है। सामान्यतः एक मनुष्य की आयु उसकी साँस पर निर्भर होती है। स्वाभाविक साँस अर्थात चार सेकंड में एक साँस (रेचक और पूरक)। एक मनुष्य सौ वर्ष जिए तो उसकी आयु '77 करोड़, 76 लाख साँस' होती है। अगर चार सेकंड के बजाय 8 सेकंड में एक बार साँस लें तो वह 200 वर्ष जी सकता है। इसे पहले कुछ साधक प्राणायाम से साध लेते थे। आज भी हिमालय में सैकड़ों वर्ष की उम्र वाले स्वस्थ साधक हैं — ऐसा परमहंस योगानंद और स्वामी राम ने अपनी किताब में अपने खुद के अनुभव से कहा है। प्राणायाम से प्राण-शक्ति बढ़ती है। इससे दूसरे की बीमारी भी ठीक की जा सकती है। इसे स्पर्श या स्पर्श-चिकित्सा (healing touch) कहते हैं।",
  "4.30": "अपरे नियताहाराः प्राणान्प्राणेषु जुह्वति ।\n\nसर्वेऽप्येते यज्ञविदो यज्ञक्षपितकल्मषाः -- कुछ आहार को सीमित कर इन्द्रिय-वृत्तियों को इन्द्रियों में हवन करते हैं। ये सभी यज्ञ की विधि जानने वाले हैं; यज्ञ से अपनी गंदगी धो चुके हैं।\n\nकुछ लोग आहार-नियंत्रण कर, इन्द्रिय-चंचलता कम करके साधना करते हैं। आहार-नियंत्रण अर्थात ज्यादा भोजन न करना, नमक-खट्टा-तीखा कम खाना आदि। इससे इन्द्रियों का खिंचाव कम होता है। इसका असर सीधे मन पर पड़ता है। इस तरह आहार-नियंत्रण के माध्यम से साधना एक यज्ञ है। इसीलिए हमारे यहाँ कई त्योहारों में, एकादशी को उपवास की प्रथा सामाजिक रूप से चली आई है।",
  "4.31": "यज्ञशिष्टामृतभुजो यान्ति ब्रह्म सनातनम् ।\n\nनायं लोकोऽस्त्ययज्ञस्य कुतोऽन्यः कुरुसत्तम -- यज्ञ में अर्पित कर बचे अमृत को खाने वाले (यज्ञ-फल का अमृत) शाश्वत भगवान को पाते हैं। हे कुरुश्रेष्ठ, यज्ञ न करने वाले के लिए यह लोक भी नहीं है। उस लोक की तो बात ही क्या?\n\nयज्ञ में भगवान को अर्पित कर बचे को 'अमृत' कहते हैं। वह हमें मृत्यु के पार ले जाता है। जीवन के हर कदम में इस तरह जीते रहें तो धीरे-धीरे कभी न बदलने वाले, शाश्वत और सनातन भगवान से जा मिलते हैं।\n\nयहाँ 'सनातन' में एक और ध्वनि है। केवल उपवास प्राणायाम करने से मोक्ष नहीं मिलता। सनातन (नातन-नादन) अर्थात शब्द। ब्रह्म सनातन अर्थात सर्व-शब्द-वाच्य, वेद-वेद्य भगवान। ऐसे भगवान को शास्त्र के माध्यम से जानकर करने वाले यज्ञ से ही मोक्ष संभव है। नहीं तो कोई उपयोग नहीं।",
  "4.32": "एवं बहुविधा यज्ञा वितता ब्रह्मणो मुखे ।\n\nकर्मजान्विद्धि तान्सर्वानेवं ज्ञात्वा विमोक्ष्यसे -- इस तरह कई तरह के यज्ञ भगवान के मुख में फैले हुए हैं। वे सब कर्म से ही होने वाले हैं ऐसा जानो। ऐसा जानने पर तुम मुक्त हो जाओगे।\n\nयज्ञ के कई पहलू हैं। जीवन के किसी भी कदम को भगवान के बोध से करें तो, जीवन की चाल भगवान की ओर बढ़ने वाली चाल बने तो, वह यज्ञ बन जाता है। जिस भी तरह यज्ञ करें वह भगवान के मुख में ही आकर मिलता है। सारे यज्ञों के नियामक वह भगवान ही हैं, विविधता केवल हमारे अनुसंधान और क्रिया में है।",
  "4.33": "श्रेयान्द्रव्यमयाद्यज्ञाज्ज्ञानयज्ञः परन्तप ।\n\nसर्वं कर्माखिलं पार्थ ज्ञाने परिसमाप्यते -- हे परंतप, संपत्ति का हवन करने वाले बाहरी यज्ञ से ज्ञान-यज्ञ बेहतर है। हे पार्थ, संपूर्ण सारा कर्म ज्ञान में पूरा हो जाता है।\n\nवास्तव में पूर्ण रूप से केवल बाहरी यज्ञ और केवल भीतरी यज्ञ जैसा कुछ नहीं है। हमारे किए बाहरी यज्ञ के पीछे बोध है। भीतरी यज्ञ के साथ आचरण भी है। इन दोनों में भीतरी यज्ञ को ज्यादा महत्व है। क्योंकि हम मानसिक रूप से ध्यान करने से बाहरी क्रिया के बिना मन में विशेष शक्ति निर्माण होती है। परन्तु बोध के बिना कर्म करें तो वह व्यर्थ है! इसीलिए कर्म के पीछे का बोध बहुत महत्वपूर्ण है। इसलिए हमें ज्ञानपूर्वक कर्म करना चाहिए।",
  "4.34": "तद्विद्धि प्रणिपातेन परिप्रश्नेन सेवया ।\n\nउपदेक्ष्यन्ति ते ज्ञानं ज्ञानिनस्तत्त्वदर्शिनः -- ज्ञान पाना हो तो \"तुम्हें ज्ञानियों के पीछे लगना चाहिए; सत्य का साक्षात्कार कर चुके तत्त्वदर्शियों से ज्ञान पाओ\" ऐसा कृष्ण कहते हैं। ज्ञान केवल किताब पढ़ने से नहीं आता। वह हमें साक्षात्कार होना चाहिए। \"Truth is an intuitional flash, it is not Intellectual\" — सत्य हमें स्फुरित होना चाहिए।\n\nसामान्यतः सत्य का साक्षात्कार कर चुके ज्ञानी योग्य न होने वालों को ज्ञान कभी नहीं सिखाते। इसीलिए कृष्ण कहते हैं: \"तत्त्वदर्शियों को देखो तो छोड़ना मत, उनके पीछे लगो, उन्हें प्रसन्न करो, उनके सामने खुद को योग्य साबित करो। अपनी अनन्य चाह उन्हें समझाओ, उनकी शरण जाओ\" ऐसा।",
  "4.35": "तद्विद्धि प्रणिपातेन परिप्रश्नेन सेवया ।\n\nउपदेक्ष्यन्ति ते ज्ञानं ज्ञानिनस्तत्त्वदर्शिनः ॥\n\nयज्ज्ञात्वा न पुनर्मोहमेवं यास्यसि पाण्डव ।\n\nयेन भूतान्यशेषेण द्रक्ष्यस्यात्मन्यथो मयि -- हे पांडव, जिसे जानकर तुम फिर इस तरह मोहग्रस्त नहीं होगे; जिस मोह के मिटने से सारे जीवों को अंतर्यामी (हर जगह रहने वाले) मुझमें देख सकोगे, ऐसे ज्ञान को सच्चे देखने वाले तुम्हें बताएँगे। चरणों में गिरकर, बार-बार पूछकर, सेवा करके उसे जानो।\n\nज्ञान पाना हो तो \"तुम्हें ज्ञानियों के पीछे लगना चाहिए; सत्य का साक्षात्कार कर चुके तत्त्वदर्शियों से ज्ञान पाओ\" ऐसा कृष्ण कहते हैं। ज्ञान केवल किताब पढ़ने से नहीं आता। वह हमें साक्षात्कार होना चाहिए। \"Truth is an intuitional flash, it is not Intellectual\"। सत्य हमें स्फुरित होना चाहिए। सारे वेद-मंत्र ऋषियों को अंतरात्मा में स्फुरित हुए थे — जैसे न्यूटन को गुरुत्वाकर्षण शक्ति का विचार सूझा था। इसीलिए हमें पहले सत्य की शरण जाना चाहिए; सत्य देखने वाले तत्त्वज्ञानियों के पीछे लगना चाहिए।\n\nएक बार सत्य का बोध आए तो उससे मोह का पाश छूट जाता है। वह फिर आने की संभावना नहीं रहती। इस स्थिति में समस्त जीव-जगत आत्मा (भगवान) में आश्रित है, सब कुछ की नियामक शक्ति भगवान है ऐसी चेतना जाग जाती है। इससे सारी उलझन मिट जाती है। स्वार्थ, दुख, ईर्ष्या, सब कुछ चला जाकर स्थितप्रज्ञता उभरती है।",
  "4.36": "अपि चेदसि पापेभ्यः सर्वेभ्यः पापकृत्तमः ।\n\nसर्वं ज्ञानप्लवेनैव वृजिनं सन्तरिष्यसि -- तुम सभी पापियों में सबसे बड़े पापी हो तो भी, सारे पापों को ज्ञान की नाव से पार कर सकते हो।\n\n\"तुम अपने काल के सबसे बड़े पापी हो तो भी, एक बार तुम्हें भगवान का बोध हो जाए तो तुम जीत गए जैसा है\" ऐसा कृष्ण कहते हैं। क्योंकि समझ आने के बाद ज्ञान के मार्ग पर चलें तो पहले का कोई पाप नहीं रुकता। ज्ञान पाप के सागर में नाव जैसा है। वह हमें किनारे पहुँचा सकता है। पाप के सागर को पार करने का एक ही साधन है — ज्ञान। ऐसा बड़ा भरोसा कृष्ण ने दिया है।",
  "4.37": "यथैधांसि समिद्धोऽग्निर्भस्मसात्कुरुतेऽर्जुन ।\n\nज्ञानाग्निः सर्वकर्माणि भस्मसात्कुरुते तथा -- अर्जुन, जलती आग जैसे ईंधन को जलाकर राख कर देती है वैसे ही ज्ञान की आग सारे कर्मों को जलाकर राख कर देती है।\n\nज्ञान सदा जलने वाली आग है। उससे ज्यादा शक्तिशाली आग और कोई नहीं है। जैसे जलती आग लकड़ी को जला देती है वैसे ही ज्ञान की आग सारे पाप-कर्म को जला देती है। भागवत में कहा गया है जैसे अध्यात्मिक रूप से आग सत्व-गुण का प्रतीक है। क्योंकि वह प्रकाश देने वाली और सदा ऊपर की ओर बढ़ने वाली शक्ति है। उसी तरह लकड़ी सदा नीचे खींचने वाले तमोगुण का प्रतीक है।",
  "4.38": "नहि ज्ञानेन सदृशं पवित्रमिह विद्यते ।\n\nतत्स्वयं योगसंसिद्धः कालेनात्मनि विन्दति -- समझ के बराबर पवित्र वस्तु यहाँ और कोई नहीं है। साधना से पके व्यक्ति को सही समय पर वह खुद अपने में मिल जाती है।\n\nज्ञान महापवित्र है। उसके बराबर कोई और वस्तु इस संसार में नहीं है। क्योंकि ज्ञान अर्थात भगवान। इसीलिए \"ज्ञान का मार्ग पकड़ो, समय पकने पर तुम सिद्धि पा ही लोगे\" यह कृष्ण का भरोसा है। कभी-कभी साधना के रास्ते में सिद्धि पाने के लिए कुछ जन्म भी लग सकते हैं। परन्तु भगवान के भरोसे पर विश्वास कर आत्मविश्वास से आगे बढ़ने वाला सिद्धि पाता है।",
  "4.39": "श्रद्धावाँल्लभते ज्ञानं तत्परः संयतेन्द्रियः ।\n\nज्ञानं लब्ध्वा परां शान्तिमचिरेणाधिगच्छति -- इन्द्रियों को काबू में रखकर, श्रद्धा से मुझे ही परम देवता मानने वाला ज्ञान पाकर जल्दी ही खुशी के स्रोत मुक्ति को पाता है।\n\nहममें बोध जगे इसके लिए केवल अध्ययन काफी नहीं है। कोई बात हमें समझ में आने के लिए पहले हमें श्रद्धा चाहिए। यहाँ समर्पण-भावना अत्यंत महत्वपूर्ण है। मैंने जो जाना वही बड़ा है, उससे बड़ा कुछ नहीं ऐसा अहंकार पहले छोड़ना चाहिए।",
  "4.40": "अज्ञश्चाश्रद्दधानश्च संशयात्मा विनश्यति ।\n\nनायं लोकोऽस्ति न परो न सुखं संशयात्मनः -- अज्ञानी, विश्वास खो चुका, दुविधा वाला विनाश की ओर बढ़ता है। दुविधा वाले के लिए न यह लोक है, न परलोक है, न चैन है।\n\nज्ञान न रखने वाले, श्रद्धा न रखने वाले अज्ञानी निरंतर संशय में ही जीते हैं। ज्ञान और श्रद्धा न होने पर वहाँ संशय बढ़ने लगता है। वह संशय मन पर कब्ज़ा कर फिर चित्त तक पहुँचता है। बुद्धि तक पहुँचे संशय का कोई इलाज नहीं। वह हमें पतन की ओर ले जाता है।",
  "4.41": "योगसंन्यस्तकर्माणं ज्ञानसञ्छिन्नसंशयम् ।\n\nआत्मवन्तं न कर्माणि निबध्नन्ति धनञ्जय -- हे धनंजय, साधना से कर्मफल का नाता छोड़ चुके, बोध से शंकाएँ मिटा चुके भगवद्भक्त को कर्म नहीं बाँधते।\n\nजीवन में कर्म करो, कर्म करते हुए कर्म-संन्यास करो ऐसा कृष्ण कहते हैं। यहाँ कर्म-संन्यास अर्थात कर्म-त्याग नहीं है। 'यह कर्म भगवान का है' ऐसा मानकर भगवान में कर्म अर्पित करना — कर्म-संन्यास है (इस बारे में अगले अध्याय में ज्यादा विवरण मिलेगा)।",
  "4.42": "तस्मादज्ञानसम्भूतं हृत्स्थं ज्ञानासिनात्मनः ।\n\nछित्त्वैनं संशयं योगमातिष्ठोत्तिष्ठ भारत -- इसलिए, हे भारत, अज्ञान से जन्मा, मन में बैठा तुम्हारा यह संदेह ज्ञान की तलवार से काटकर योग के मार्ग पर चलो; उठ खड़े हो।\n\n\"इसलिए उठ खड़े हो, भरत चक्रवर्ती जैसे महापुरुष जिस वंश में जन्मे उस वंश के तुम, ज्ञान-स्वरूप भगवान की भक्ति में लगे ज्ञानी (भारत); तुम्हारे मन में बैठे संदेह को भगवान नाम की ज्ञान-तलवार से काट दो। अन्याय के विरुद्ध लड़ाई भगवान की पूजा है ऐसी दीक्षा लेकर, सत्य और ईमानदारी का जीवन जीने के लिए पुण्य की साधना में लग जाओ\" ऐसा कृष्ण कहते हैं।\n\nइस प्रकार चौथा अध्याय समाप्त हुआ।",
  "5.1": "अर्जुन उवाच — अर्जुन ने पूछा:\n\nसंन्यासं कर्मणां कृष्ण पुनर्योगं च शंससि ।\n\nयच्छ्रेय एतयोरेकं तन्मे ब्रूहि सुनिश्चितम् -- कृष्ण, कभी तुम कर्म-संन्यास की प्रशंसा करते हो; कभी कर्मयोग की। इन दोनों में जो बेहतर है वह मुझे निश्चित रूप से बताओ।\n\nअर्जुन पूछता है: \"हे कृष्ण, तुम कभी लड़ो कहते हो, कभी कर्म-संन्यास करो कहते हो। अगर कर्म-संन्यास का मतलब कर्म-त्याग है तो यह एक-दूसरे के विरुद्ध है। इसमें जो बेहतर है वह निश्चित रूप से बताओ\" ऐसा। युद्ध करते समय द्वंद्व तो रहता ही है। द्वंद्व-त्याग से युद्ध कैसे करें? कर्म-संन्यास और कर्मयोग दोनों साथ कैसे संभव हैं? युद्ध है तो राग-द्वेष रहेगा ही। इस कारण कृष्ण की बात हमें निश्चित रूप से समझ नहीं आती। इसीलिए अर्जुन कृष्ण से विवरण पूछ रहा है।",
  "5.2": "भगवानुवाच — भगवान बोले\n\nसंन्यासः कर्मयोगश्च निःश्रेयसकरावुभौ ।\n\nतयोस्तु कर्मसंन्यासात्कर्मयोगो विशिष्यते -- कर्म-संन्यास और कर्मयोग दोनों ही भलाई के रास्ते हैं। उनमें कर्म-संन्यास से कर्मयोग बेहतर है।",
  "5.3": "ज्ञेयः स नित्यसंन्यासी यो न द्वेष्टि न काङ्क्षति ।\n\nनिर्द्वंद्वो हि महाबाहो सुखं बंधात्प्रमुच्यते -- जो न द्वेष करता है, न चाहता है, उसे सच्चा संन्यासी जानो। हे महावीर, ऐसे द्वंद्वों को जीतने वाला आसानी से कर्म-बंधन से मुक्त हो जाता है।\n\nयहाँ अर्जुन के प्रश्न का कृष्ण का उत्तर पहेली के रूप में है। यहाँ कहा गया संन्यास संन्यास-आश्रम नहीं है। जो राग-द्वेष को पार कर खड़ा होता है वह संन्यासी है। स-अहं-न्यास-संन्यास। 'स' अर्थात संपूर्ण, उचित, दोषरहित और गुणपूर्ण भगवान। उनमें अपने अहं (राग-द्वेष-अहंकार) को रखना संन्यास है। कृष्ण कहते हैं: \"कर्मयोग कर्म-संन्यास से बेहतर है\" ऐसा। क्योंकि यहाँ अर्जुन 'मुझे कौरवों से द्वेष नहीं है, हमें ही जीतना चाहिए ऐसी इच्छा नहीं है, मुझे किसी फल की चाह नहीं है' ऐसा कहकर युद्ध न करते हुए निर्लिप्त-निष्क्रिय बैठे तो वह कर्म-संन्यास बन जाएगा। परन्तु ऐसे चुपचाप बैठने से कर्तव्य-कर्म (कर्मयोग) करना नहीं होता। इससे अधर्म की जीत होती है। इसलिए कर्म-संन्यास और कर्मयोग साथ-साथ होने चाहिए। कर्मयोग के बिना कर्म-संन्यास कभी भलाई नहीं लाता — यही कृष्ण का उत्तर है।\n\nसंन्यास सार्थक बनने के लिए काम-क्रोध के त्याग के साथ क्रिया होनी चाहिए। लड़ना चाहिए — परन्तु राग-द्वेष से नहीं। क्रिया के बिना राग-द्वेष त्याग का कोई अर्थ नहीं। इसलिए द्वंद्वातीत होकर कर्म करना चाहिए — यही कृष्ण का संदेश है।\n\nहमारा जीवन ही एक संघर्ष है। यहाँ अपने कर्तव्य-कर्म से दूर हटकर, राग-द्वेष, काम-क्रोध छोड़कर, निष्क्रिय होकर 'मैंने कर्म-संन्यास साध लिया' ऐसा मान लें तो हमारा जीवन व्यर्थ है। इससे कभी भलाई नहीं, मोक्ष नहीं। राग-द्वेष त्याग के साथ ही, जीवन नाम के इस संग्राम में अपने कर्तव्य-कर्म के माध्यम से संघर्ष करना ही सच्चा जीवन-धर्म है। इस तरह द्वंद्वातीत जीवन जीने वाला कर्म की कैद से पार हो जाता है।\n\nयहाँ कृष्ण अर्जुन को महाबाहु कहकर संबोधित करते हैं। पहले कहा गया जैसे महाबाहु का ऊपरी अर्थ है महावीर। यहाँ इस विशेषण का विशेष अर्थ है। 'महाबा' अर्थात राग-द्वेष और कामनाओं के भँवर में रहने वाला। ऐसे महत्तर राग-द्वेष का त्याग करने वाला महाबाहु है। \"तुझमें कर्म-संन्यास है, उसके साथ कर्मयोग करने की योग्यता रखने वाला महावीर तू है\" ऐसी ध्वनि इस संबोधन में है।",
  "5.4": "सांख्ययोगौ पृथग्बालाः प्रवदन्ति न पण्डिताः ।\n\nएकमप्यास्थितः सम्यगुभयोर्विंदते फलम् -- ज्ञान और कर्म का रास्ता अलग-अलग है (एक संन्यासियों के लिए और दूसरा गृहस्थों के लिए) ऐसा कहने वाले नादान हैं; जानकार नहीं। जो कोई भी एक रास्ते पर सही तरीके से चले वह दोनों का फल पाता है।\n\nपहले कर्म-संन्यास और कर्मयोग के बारे में बताते हुए कृष्ण यहाँ सांख्य (ज्ञान — Spiritual Wisdom) और योग (अनुष्ठान — Spiritual Practice) के बारे में बताते हैं। शास्त्र में सांख्य (सम्यक् ख्याति) का अर्थ गणित नहीं; वह शुद्ध आत्म-तत्व-विज्ञान है — भगवान का ज्ञान। जिसके नियंत्रण में यह पूरा संसार चल रहा है उसका बोध। इसे न जानने वालों को कृष्ण नादान कहते हैं, और उनकी बात का कोई मूल आधार नहीं ऐसा कहते हैं। इतना कहकर कृष्ण कहते हैं \"एकमप्यास्थितः सम्यगुभयोर्विंदते फलम्\" ऐसा। अर्थात \"किसी भी एक को तुम अच्छी तरह आचरण में लाओ, दोनों का फल पाओगे\" ऐसा अर्थ। यहाँ फिर हमें भ्रम हो सकता है। इसका मतलब केवल ज्ञान या केवल कर्म का आचरण करना नहीं है। हम कर्म को अच्छी तरह करें अर्थात जानकर ज्ञानपूर्वक करें। उसी तरह ज्ञान अच्छा होना अर्थात जाने हुए को आचरण में लाना। इसलिए एक 'ज्ञानप्रधान' दूसरा 'कर्मप्रधान' हो सकता है। परन्तु एक दूसरे का पूरक है। जो इसे जानते हैं वे पंडित हैं और वे सच्चा फल पाते हैं।",
  "5.5": "यत्सांख्यैः प्राप्यते स्थानं तद्योगैरपि गम्यते ।\n\nएकं सांख्यं च योगं च यः पश्यति स पश्यति -- ज्ञानयोगी जो स्थान पाते हैं वहाँ कर्मयोगी भी पहुँचते हैं। ज्ञान और कर्म के रास्तों की मंज़िल एक ही है यह जानने वाला ही सच में जानने वाला है।\n\nज्ञानियों को अपने लिए ही नहीं, संसार को मार्गदर्शन देने के लिए भी कर्म करना पड़ता है। क्योंकि समाज उनका अनुसरण करता है। यह उन पर एक सामाजिक जिम्मेदारी है। इसलिए ज्ञान और कर्म एक-दूसरे के पूरक हैं। ज्ञान-प्रद और कर्म-प्रद, इन दोनों रास्तों की मंज़िल एक ही है। ज्ञान-प्रधान होकर कर्म करने वाले ऋषि, देवता, और कर्म-प्रधान होकर ज्ञान से कर्म करने वाले — दोनों जिस मंज़िल पर पहुँचते हैं वह एक ही है, वह है वह भगवान। यहाँ कर्म-संन्यास अलग और कर्मयोग अलग कहना अर्थहीन है। ये दोनों एक-दूसरे के पूरक हैं। जो यह सत्य जानते हैं वे 'जानने वाले' हैं।",
  "5.6": "संन्यासस्तु महाबाहो दुःखमाप्तुमयोगतः ।\n\nयोगयुक्तो मुनिर्ब्रह्म न चिरेणाधिगच्छति -- हे महावीर, कर्मयोग के बिना केवल संन्यास दुख ही लाता है (भगवान की पूजा समझकर कर्म करने के बदले कर्म को ही छोड़ना नरक का रास्ता है)। कर्म करते हुए द्वंद्व को जीतने वाला भगवान को पाने में देर नहीं करता।\n\nकर्मयोग के बिना केवल द्वंद्व-त्याग (संन्यास) व्यर्थ है। शास्त्र पढ़कर 'मुझे ज्ञान मिल गया, मैं द्वंद्वातीत हूँ, मुझे किसी कर्म की जरूरत नहीं' ऐसा मानकर निष्क्रिय बन जाएँ तो यह हमें अधोगति की ओर धकेलता है। परन्तु द्वंद्वातीत होकर काम-क्रोध जीतकर ज्ञानपूर्वक कर्म करें तो उससे मोक्ष निश्चित है।",
  "5.7": "योगयुक्तो विशुद्धात्मा विजितात्मा जितेंद्रियः ।\n\nसर्वभूतात्मभूतात्मा कुर्वन्नपि न लिप्यते -- कर्मयोग में लगा हुआ, शुद्ध मन वाला, मन को जीत चुका, इन्द्रियों को जीत चुका, सभी जीवों की रक्षा करने वाले भगवान को अपना स्वामी मानने वाला (भगवान में ही मन लगाने वाला) — करते हुए भी नहीं चिपकता।\n\nकर्मयोग में लगे व्यक्ति को अपने मन को काबू में कर शुद्ध मन से शुद्ध कर्म करना चाहिए। मन को जीतने के लिए भगवान की कृपा चाहिए। मन को जीतने वाला इन्द्रियों को जीतता है — इससे आत्म-शुद्धि होती है। तब सभी जीवों का आत्मा बना भगवान ही मेरा आत्मा है यह बोध होता है। सर्वव्यापी, सर्व-नियामक भगवान मेरे भीतर भी है, वही विश्व-नियामक बनकर विश्व में भरा है — इस अनुसंधान से, सभी जीवों में अंतर्यामी भगवान में मन को स्थिर कर कर्म करने पर, हमें कर्म नहीं चिपकता।\n\nकर्म-संन्यास और कर्मयोग दोनों को मिलाकर जीवन में कर्म-अनुष्ठान करना चाहिए यह बताने वाले कृष्ण, हमारे रोजमर्रा के जीवन में इस तरह का कर्म-अनुष्ठान क्या है इसका विवरण अगले श्लोक में देते हैं।",
  "5.8": "[इस श्लोक का पदच्छेद, अर्थ और विवरण अगले श्लोक (५.९) के साथ एक साथ दिया गया है, जैसा ग्रंथ की रचना में है।]\n\nप्रलपन्विसृजन्गृह्णन्नुन्मिषन्निमिषन्नपि ।\n\nइंद्रियाणींद्रियार्थेषु वर्तंत इति धारयन् ॥",
  "5.9": "नैव किंचित्करोमीति युक्तो मन्येत तत्त्ववित् ।\n\nपश्यञ्श्रृण्वन्स्पृशञ्जिघ्रन्नश्नन्गच्छन्स्वपञ्श्वसन् ।\n\nप्रलपन्विसृजन्गृह्णन्नुन्मिषन्निमिषन्नपि ।\n\nइंद्रियाणींद्रियार्थेषु वर्तंत इति धारयन् -- सत्य जान चुका साधक खुद कुछ नहीं कर रहा ऐसा मानना चाहिए — देखते हुए, सुनते हुए, छूते हुए, सूँघते हुए, खाते हुए, घूमते हुए, सोते हुए, साँस लेते हुए, बोलते हुए, त्यागते हुए, लेते हुए, पलक खोलते हुए, पलक बंद करते हुए भी — 'इन्द्रियाँ अपने काम में लगी हैं' ऐसा मानते हुए।\n\nहमारे जीवन में देवता-पूजा ही अकेला अनुष्ठान नहीं है। हमारा हर एक कदम एक कर्मयोग बनना चाहिए। किसी खास समय पर ही देवता-पूजा करना नहीं है। हमारा पूरा जीवन ही एक यज्ञ बनना चाहिए। यज्ञ को कन्नड़ में 'बेळुवे' कहते हैं। हमारा जीना (बाळुवे) ही एक बेळुवे बनना चाहिए।\n\nकर्म-अनुष्ठान करने वाले को \"मैं अपने आप कुछ नहीं कर रहा, मेरी इच्छापूर्वक क्रिया है, परन्तु यहाँ मुझे स्वतंत्रता नहीं है\" यह सत्य पता होना चाहिए। हम जो करना चाहते हैं वह हमसे हो नहीं पाता, जो चाहते हैं वह मिलता नहीं, फल में हमारी स्वतंत्रता नहीं है। यह हर एक के अनुभव में आने वाली बात है। परन्तु क्रिया हमारे माध्यम से ही होती रहती है।\n\n'मुझे यही मिलना चाहिए, यह नहीं मिलना चाहिए ऐसी इच्छा से, या मैं कर रहा हूँ ऐसे अहंकार से नहीं; मेरे भीतर रहने वाला भगवान यह करवा रहा है' ऐसा तत्वज्ञानी जानता है। इसलिए किसी भी चीज़ में \"मैं, मेरा\" ऐसा अहंकार उसे नहीं रहता। सब कुछ भगवान की इच्छा के अनुसार चलता है, हम स्वतंत्र कर्ता नहीं हैं यह सच्चाई जानकर वह अपनी क्रिया करता है।\n\nउदाहरण के लिए — हम एक फूल की सुंदरता आँख से चखते हैं; उसकी खुशबू नाक से सूँघकर आनंद लेते हैं; उस फूल को छूकर-पहनकर खुश होते हैं। इस फूल को बनाने वाला, उसे सुंदरता देने वाला वह भगवान है। उस फूल को देखने वाली आँख हमें देने वाला वही है (जन्मांध को यह योग नहीं है)। यह अनुसंधान हो तो देखने-छूने-सूँघने की क्रिया में 'मेरा' ऐसा अहंकार नहीं रहता।",
  "5.10": "ब्रह्मण्याधाय कर्माणि सङ्गं त्यक्त्वा करोति यः ।\n\nलिप्यते न स पापेन पद्मपत्रमिवांभसा -- जो कर्मों को भगवान में सौंपकर, नाता छोड़कर करता है वह पाप से नहीं चिपकता — जैसे कमल का पत्ता पानी से नहीं चिपकता।\n\nहम पूजा के अंत में \"श्री कृष्णार्पण मस्तु\" कहते हैं। इसका अर्थ है \"उस भगवान को अर्पित\"। अर्पित करने का मतलब है \"यह कर्म भगवान ने अपनी पूजा के रूप में मेरे माध्यम से मेरे उद्धार के लिए खुद करवाया\" ऐसा संकल्प। इस तरह हम कर्म करें तो कोई भी कर्म का लेप हमें नहीं चिपकता। \"मैं, मेरा, मुझसे\" ऐसा अहंकार निकल जाता है। यह एक आनंदमय आश्चर्य है। कमल का पत्ता पानी में रहते हुए भी पानी को अपने से नहीं चिपकाता, वैसे ही, कर्म के साथ रहकर, कर्म करके, कर्म को न चिपकाना इसी अनुसंधान से ही संभव है।",
  "5.11": "कायेन मनसा बुद्ध्या केवलैरिंद्रियैरपि ।\n\nयोगिनः कर्म कुर्वंति सङ्गं त्यक्त्वात्मशुद्धये -- योगी शरीर से, मन से, बुद्धि से और केवल इन्द्रियों से भी कर्म करते हैं। नाता छोड़कर, आत्म-शुद्धि के लिए।\n\nद्वंद्वातीत, फल की चाह न रखने वाले, 'मुझमें भगवान अपनी पूजा मेरे माध्यम से मेरे उद्धार के लिए करवा रहे हैं' ऐसा जानकर कर्तव्य-दृष्टि से कर्म करते हैं। उनमें अहंकार-ममकार नहीं होता; इससे मन शुद्ध होता है। शुद्ध मन ही शुद्ध विषय ग्रहण कर सकता है।",
  "5.12": "युक्तः कर्मफलं त्यक्त्वा शांतिमाप्नोति नैष्ठिकीम् ।\n\nअयुक्तः कामकारेण फले सक्तो निबध्यते -- योग जानने वाला कर्मफल का नाता छोड़कर निश्चल शांति पाता है। योगी न होने वाला फल में आँख गड़ाकर, चाह रखते हुए उसका बंदी बन जाता है।\n\nकर्मयोग में लगा हुआ, भगवद्-चेतना में कर्म करने वाला, ज्ञानानंद की चोटी मोक्ष पाता है। किसी फल की चाह से कर्म करें तो कोई फल नहीं मिलता ऐसा नहीं है। परन्तु वह फल हमारे लिए कितना उपयोगी है यह बोध हमें नहीं रहता और वह पूरा फल नहीं होता। फल की चाह के बिना कर्म करें तो हमें जो चाहिए वह सब मिल जाता है।\n\nकर्मयोग के बिना 'मैं अपने लिए काम कर रहा हूँ, यह मेरी संपत्ति है, कमाया हुआ अपने सुख के लिए खर्च करूँगा, कोई भगवान हमारी मदद नहीं करता' आदि स्वार्थ-केंद्रित भावना से कर्म करें तो कर्म हमारे लिए बंधन बन जाता है। एक गूँगा जानवर भी ऐसे नहीं जीता। उदाहरण के लिए कौआ: उसे कोई खाने की चीज़ दिखे तो अपने सारे साथियों को बुलाकर बाँटकर खाता है। बाघ-सिंह जैसे क्रूर जानवर भी एक बार पेट भरने के बाद कभी स्वार्थ से काम नहीं करते। परन्तु मानव होकर हम स्वार्थ से जीते हैं। जितना पाएँ उतनी और चाह! ऐसे जीने वाला संसार-चक्र में फँसकर अधोगति पाता है।",
  "5.13": "सर्वकर्माणि मनसा संन्यस्यास्ते सुखं वशी ।\n\nनवद्वारे पुरे देही नैव कुर्वन्न कारयन् -- मन को काबू में रखने वाला, मानसिक रूप से सारे कर्मों का नाता छोड़कर, नौ द्वार वाले इस शहर (शरीर) में सुख से रहता है — कुछ भी न करता, न करवाता।\n\n'कर्म को मानसिक रूप से छोड़ो' ऐसा कृष्ण कहते हैं। यह बहुत महत्वपूर्ण बात है। यहाँ 'कर्म छोड़ो' कृष्ण नहीं कह रहे, केवल मन में छोड़ो कह रहे हैं। अर्थात कर्मों के बारे में मन में रहने वाला फल का नाता; मानसिक स्वतंत्रता का भ्रम — इसे छोड़ना। 'मेरे लिए', 'मेरे वास्ते' ऐसे विचार को मानसिक रूप से छोड़ना। जीव को किसी भी समय, किसी भी कर्तृत्व में स्वतंत्रता नहीं है। यह मध्वाचार्य ने अपने सभी ग्रंथों में बार-बार कहा है। इसे मानसिक रूप से अपनाना ही सच्चा कर्म-संन्यास है।\n\nभगवान इस नौ द्वार वाले शहर (पूर्णता पाया मानव शरीर) में हमें बिठाकर हमसे कर्म करवा रहे हैं। 'मुझे इस शहर में रखकर, मेरे साथ मेरे आत्मीय मित्र बनकर खड़े होकर, मेरे उद्धार के लिए वह भगवान कर्म करवा रहे हैं' यह सजगता कर्मयोग है।\n\nयहाँ कृष्ण कहते हैं \"कुछ भी न करते, न करवाते\"। सामान्यतः हम एक काम करें तो 'यह मैंने किया', 'मैंने कहा इसलिए वह काम हुआ' ऐसा हर जगह कहते फिरते हैं। वैसे चार लोग कहें ऐसा चाहते हैं। परन्तु ज्ञानी ऐसा नहीं कहते। 'कुछ भगवान ने मेरे हाथों करवाया', 'मेरे भीतर रहकर उस भगवान ने करवाया', 'भगवान ने उन्हें प्रेरणा दी' इस तरह बोलते हैं। इसका कारण है ज्ञानी कभी 'मैं स्वतंत्र कर्ता' ऐसी चेतना नहीं पालते। यही ज्ञानी और अज्ञानी के कर्म-अनुसंधान में अंतर है।",
  "5.14": "न कर्तृत्वं न कर्माणि लोकस्य सृजति प्रभुः ।\n\nन कर्मफलसंयोगं स्वभावस्तु प्रवर्तते -- प्रभु लोक का कर्तृत्व, कर्म, और कर्मफल-संयोग नहीं रचते। स्वभाव ही प्रवृत्त होता है।\n\nजीव जड़ से भिन्न, इच्छापूर्वक क्रिया करने वाला है, फिर भी उसमें कर्तृत्व नहीं है। संसार में तीन तरह का कर्तृत्व है — केवल क्रिया (जड़ में भी, जैसे थन से दूध बहना), बुद्धिपूर्वक अस्वतंत्र क्रिया (जीव में), स्वतंत्र इच्छापूर्वक क्रिया (केवल भगवान में)। जीव को दत्त-स्वतंत्रता भी नहीं है; वह भगवान के अधीन है, इसलिए कर्ता नहीं।\n\nपालने के बच्चे का उदाहरण — बुद्धि और इच्छा है, स्वतंत्रता नहीं; माँ के मुँह में डाला वही खाता है। फल में भी वैसे ही — माता-पिता नमस्कार करवाते हैं, फल बच्चे को ही मिलता है। वैसे ही जीव में बैठा अदृश्य भगवान 'जीवन' क्रिया को नियंत्रित करता है; कर्म भगवान करवाए तो भी फल जीव का ही है, भगवान का नहीं।\n\n'भगवान बुरा काम क्यों करवाते हैं' इस प्रश्न का उत्तर — उपाध्याय के उदाहरण से: उपाध्याय सबको समान पढ़ाता है, परन्तु विद्यार्थी-भेद से ग्रहण-भेद होता है — वहाँ उपाध्याय कारण नहीं, विद्यार्थी का स्वभाव ही कारण है। 'स्वभावस्तु प्रवर्तते' यह अपूर्व वचन है। जीव अनादि-नित्य है, उसका स्वभाव भी अनादि-नित्य है; उसी के अनुसार जीव चलता है।\n\nआम का बीज जैसे आम का ही फल देता है कटहल का नहीं, वैसे जीव देह-वृक्ष का बीज स्वस्वभावानुगुण ही अभिव्यक्त होता है। सत्व-रज-तम मिश्रित स्वभाव जीव का अनादि-नित्य है; जिसमें जो गुण प्रधान हो वह उसी वर्ग में जाता है। स्वतंत्र भगवान सृष्टि-बगीचा बनाकर जीव-बीज को माली की तरह बोते-उगाते हैं; उससे देह-वृक्ष बढ़ता है, स्वभावानुगुण कड़वा, खट्टा या मीठा फल अभिव्यक्त होता है। मिर्च के पौधे को माली कभी कड़वा पानी नहीं डालता, फिर भी वह स्वभाव से तीखा फल देता है।\n\nकभी हम अपने विचार के विरुद्ध काम करते हैं, क्योंकि मन-बुद्धि की विचार-शृंखला अलग, क्रिया अलग है। दुर्योधन ने भी कहा था 'जानता हूँ जो कर रहा हूँ गलत है' फिर भी वह अपने स्वभाव के अनुसार चला। इसलिए समझ अलग, क्रिया अलग — यही 'स्वभावस्तु प्रवर्तते' कृष्ण-वचन है। जिसका जो स्वभाव है वह वैसा ही रहे, दूसरे जैसा नहीं। यह श्लोक हमारे सारे संशयों का उत्तर है। बुद्धि तक पहुँचा संशय 'स्थिर-संशय' कठिन होता है। शास्त्रीय बोध हर कदम पर आवश्यक है — मैं क्या हूँ, स्वभाव क्या है, उसका नियामक कौन, फलदाता कौन — यह समझ आने पर अहंकार का अवकाश नहीं रहता।\n\nभगवान की शिक्षा द्वेष से नहीं, अपार करुणा से है — जैसे माँ की शिशु-शिक्षा। दुख-ताप से जीव पकता है; कष्ट के बिना जीव नहीं बढ़ता। पतन के पीछे उद्धार का बीज, दुख के पीछे सुख का बीज रहता है। यह शास्त्रीय अंतःप्रज्ञा अध्यात्म-मार्ग में निरंतर धारण करनी चाहिए।",
  "5.15": "नादत्ते कस्यचित्पापं न चैव सुकृतं विभुः ।\n\nअज्ञानेनावृतं ज्ञानं तेन मुह्यंति जंतवः -- विभु किसी का पाप या पुण्य ग्रहण नहीं करता। अज्ञान से ढका ज्ञान — इसी से प्राणी मोहित होते हैं।\n\n'विभुः' जीव-पक्ष में विशिष्टता, विविधता दर्शाता है — जीव जड़ से विशिष्ट है, एक ही जन्म में कई विविधताएँ अनुभव करता है (श्रीमंत या दरिद्र, विद्वान या मूढ़)। 'दूसरे के पाप से मैं दुखी हुआ' यह भ्रम है — वास्तव में अपना ही किया कर्मफल भोगा जाता है, दूसरे का नहीं। वामाचार आदि तब तक ही असर नहीं करते जब तक अपना सुकृत-फल रक्षा करता है। भक्त की ओर से पुरोहित का किया कर्म भक्त को ही मिलता है; अन्यथा अपना किया फल स्वयं ही भोगते हैं।\n\nदूसरे अर्थ में 'विभुः' सर्वसमर्थ, सर्वगत भगवान है; उसे कर्म का लेप नहीं, जीव-भेद के अनुसार वृद्धि देता है, पक्षपाती नहीं है। यह कर्म-सिद्धांत बहुत लोगों को पता नहीं, इसलिए भगवान के बारे में उलझन होती है।",
  "5.16": "ज्ञानेन तु तदज्ञानं येषां नाशितमात्मनः ।\n\nतेषामादित्यवज्ज्ञानं प्रकाशयति तत्परम् -- जिनका आत्म-अज्ञान ज्ञान से नष्ट हो गया, उनका वह ज्ञान सूर्य की तरह परमतत्व को प्रकाशित करता है।\n\nअपनी उलझन सुलझाने का एक ही रास्ता है — ज्ञान-मार्ग की साधना से सत्य जानना। जीव-स्वरूप में ज्ञान है, परन्तु अज्ञान के धुँधलके से ढका है। 'ज्ञान आग जैसा है, भीतर की ज्ञान-चिंगारी को निरंतर अंतर्मनन से प्रज्वलित करो, तब यह अज्ञान का पर्दा जल जाएगा' ऐसा कृष्ण-उपदेश। यह ज्ञानाग्नि सूर्य-प्रकाश से भी बड़ी है; यह अपरोक्ष ज्ञान भगवत्-साक्षात्कार कराता है।",
  "5.17": "तद्बुद्धयस्तदात्मानस्तन्निष्ठास्तत्परायणाः ।\n\nगच्छंत्यपुनरावृत्तिं ज्ञाननिर्धूतकल्मषाः -- जिनकी बुद्धि उसी में, आत्मा उसी में, निष्ठा उसी में, शरण उसी में — वे ज्ञान से पाप धोकर फिर न लौटने वाले स्थान को जाते हैं।\n\nभगवान में बुद्धि स्थापित करो (तद्बुद्धयः); आत्मा-मन उन्हें अर्पित करो (तदात्मानः); उनमें निष्ठा (भक्ति) अनिवार्य है (तन्निष्ठाः); उन्हें ही सबसे बड़ा आसरा मानने से (तत्परायणाः) संसार ही सर्वस्व है यह भ्रम मिट जाता है। ऐसे जीकर आत्मा की गंदगी धोकर ज्ञान-प्रकाश से भगवत्-साक्षात्कार पाकर, फिर न लौटने वाला मोक्ष पाता है।",
  "5.18": "विद्याविनयसंपन्ने ब्राह्मणे गवि हस्तिनि ।\n\nशुनि चैव श्वपाके च पंडिताः समदर्शिनः -- विद्या-विनय से संपन्न ब्राह्मण में, गाय में, हाथी में, कुत्ते में, और श्वपाक (कुत्ते का मांस खाने वाला) में भी पंडित समान दृष्टि रखते हैं।\n\nयह गूढ़ अर्थ वाला श्लोक है। मनुष्यों में विद्या-विनय-संपन्न सबसे श्रेष्ठ है, फिर ब्राह्मण-वर्ण, सबसे नीचे श्वपाक। पशुओं में गाय श्रेष्ठ, हाथी मध्यम, कुत्ता सबसे नीचे। सत्वगुण-पूर्ण गाय, तमोगुण-प्रधान कुत्ता। पंडित हर जगह भगवान की विशेष अभिव्यक्ति देखते हैं — सर्वांतर्यामी भगवान सबमें है, अभिव्यक्ति भिन्न है। हर जीव अपने विशेष गुण-धर्म से अभिव्यक्त होता है — जैसे टच-मी-नॉट पौधे (Touch-me-not) में औषधीय गुण, मधुमक्खी में शहद बनाने की शक्ति। इस तरह सब जगह भगवान की महिमा का अनुसंधान अपरोक्ष ज्ञान के लिए जरूरी समदर्शन है।",
  "5.19": "इहैव तैर्जितः सर्गो येषां साम्ये स्थितं मनः ।\n\nनिर्दोषं हि समं ब्रह्म तस्माद्ब्रह्मणि ते स्थिताः -- जिनका मन समता में स्थिर है उन्होंने यहीं यह सृष्टि जीत ली है। दोषरहित, समान ब्रह्म है, इसलिए वे ब्रह्म में स्थित हैं।\n\nसर्वगुण-पूर्ण भगवान सब जगह समान रूप से भरे हैं यह अनुसंधान मन में स्थिर हो तो जन्म-मृत्यु के पार मोक्ष का द्वार खुल जाता है। जिस भी वस्तु में भगवान हैं वहाँ दोष नहीं, वे सब जगह निर्दोष हैं। जिस भी आधार में हों वहाँ निर्लिप्त होकर भरे रहते हैं। यह जानने वालों का मन भगवान में स्थिर रहता है, इसलिए वे फिर बंधन नहीं पाकर शाश्वत मोक्ष पाते हैं।",
  "5.20": "न प्रहृष्येत्प्रियं प्राप्य नोद्विजेत्प्राप्य चाप्रियम् ।\n\nस्थिरबुद्धिरसंमूढो ब्रह्मविद्ब्रह्मणि स्थितः -- प्रिय पाकर खुश न हो, अप्रिय पाकर घबराए नहीं। स्थिर बुद्धि, मोहरहित, ब्रह्म को जानने वाला, ब्रह्म में स्थित।\n\nहमारा जीवन सुख-दुख का चक्र है। किसी को केवल सुख या केवल दुख नहीं होता। प्रिय-अप्रिय दोनों में समान दृष्टि रहनी चाहिए। जो अनिवार्य है उसे स्वाभाविक रूप से स्वीकार करना चाहिए; नहीं तो मन उलझ जाता है। सुख में अति-हर्ष न हो, दुख में अति-विषाद न हो — यही जीवन का सफल सूत्र है। आध्यात्मिक दृष्टि से प्रिय-अप्रिय वास्तव में अच्छे-बुरे नहीं होते। कठोपनिषद में कहा गया — 'प्रेयो मंदो योगक्षेमाद्वृणीते' (1.2.2) — जो प्रिय को चुनता है वह मंद है। भगवान भला जानते हैं यह जानकर सुख-दुख में मन न लगाकर भगवान में ही मन लगाना चाहिए।",
  "5.21": "बाह्यस्पर्शेष्वसक्तात्मा विंदत्यात्मनि यत्सुखम् ।\n\nस ब्रह्मयोगयुक्तात्मा सुखमक्षयमश्नुते -- बाहरी भोगों में नाता न रखने वाला भीतर [जब भी भगवान को याद करे] जैसा सुख पाता है, वही सुख भगवान में सदा मन लगाने वाला साधक निरंतर चखता रहता है।\n\nसंसार में सुख के पाँच साधन हैं — रूप, रस, गंध, स्पर्श, शब्द। इनके माध्यम से अनुभव करना गलत नहीं है। चाहिए चीज़ पाने में आनंद है, परन्तु उससे ज्यादा आनंद उसे छोड़ने में है। यह जानना जीवन का एक महत्वपूर्ण सूत्र जानना है।",
  "5.22": "ये हि संस्पर्शजा भोगा दुःखयोनय एव ते ।\n\nआद्यंतवंतः कौंतेय न तेषु रमते बुधः -- विषय के नाते से आने वाले सुख दुख की जन्मभूमि हैं। हे कौन्तेय, वे आदि-अंत वाले हैं; जानकार उनमें रमते नहीं।\n\nबाहरी विषय-स्पर्श से मिलने वाले सुख-भोग के अनुभव (संस्पर्श) से हमें कितना सुख मिल सकता है? एक गुंजा भर सुख के लिए हम कुम्हड़े भर दुख भोगने को तैयार रहते हैं। आज के सारे सांसारिक अपराधों का यही कारण है।",
  "5.23": "शक्नोतीहैव यः सोढुं प्राक्शरीरविमोक्षणात् ।\n\nकामक्रोधोद्भवं वेगं स युक्तः स सुखी नरः -- जो इस शरीर के छूटने से पहले ही, यहीं, इच्छा-क्रोध से उठने वाले वेग को सह सकता है, वही सच्चा योगी है; वही सच्चा सुखी है।\n\nहम अपने सांसारिक सुख-स्पर्श के मोह को जीत सकते हैं यह देह रहते हुए ही। विषयों का स्पर्श देह को है और विषयों को जीतना भी इसी देह के रहते संभव है। भगवान ने हमें सही-गलत सोचने की बुद्धि-शक्ति दी है। इस विचार-शक्ति का उपयोग कर शरीर गिरने से पहले ही इन्द्रिय-निग्रह का अभ्यास करना चाहिए।",
  "5.24": "योऽंतःसुखोऽंतरारामस्तथांतर्ज्योतिरेव यः ।\n\nस योगी ब्रह्मनिर्वाणं ब्रह्मभूतोऽधिगच्छति -- इच्छा मिट चुकी, भीतर का सुख देख चुका, भगवान को देखकर भीतर ही भीतर खुश हुआ, भगवान की रोशनी को ही भीतर भरने वाला, भगवान में ही टिका ऐसा साधक, अविनाशी शरीर धारण करने वाले भगवान से ही मिलता है।\n\nमनुष्य को सुख नहीं, अंतःसुख चाहिए ऐसी चाह रखनी चाहिए। इस श्लोक में 'सुख' और 'आराम' दो शब्द इस्तेमाल हुए हैं। इन दोनों शब्दों में सूक्ष्म अंतर है। हमारी इच्छाएँ पूरी होने या चाही चीज़ मिलने पर होता है 'आराम'; इच्छाओं का न होना ही सुख है।",
  "5.25": "लभंते ब्रह्मनिर्वाणमृषयः क्षीणकल्मषाः ।\n\nछिन्नद्वैधा यतात्मानः सर्वभूतहिते रताः -- सारी गंदगी मिटा चुके, दुविधा खत्म कर चुके, मन को साध चुके [बुद्धि को तपाया हुआ], सब जीवों की भलाई चाहने वाले जानकार नित्य-स्वरूप भगवान को ही पाते हैं।\n\nखुद के भीतर उठने वाले संदेह, द्वंद्व को पार कर खड़े होने वाले ही सच्चे साधक हैं। ये सदा अपने मन को अंतरात्मा में स्थिर रखते हैं। इनकी चाही सुख 'अंतरात्मा का सुख' है। बाहरी सुख का पीछा न करते हुए, सब जीवों की भलाई चाहने वाले ये सदा नित्य-स्वरूप भगवान में ही टिककर उन्हीं से मिलते हैं।",
  "5.26": "कामक्रोधवियुक्तानां यतीनां यतचेतसाम् ।\n\nअभितो ब्रह्मनिर्वाणं वर्तते विदितात्मनाम् -- प्रयत्नशील होकर इच्छा-क्रोध छोड़ चुकों के लिए, मन जीत चुकों के लिए, भगवान को जानने वालों के लिए हर जगह नित्य-स्वरूप भगवान भरे रहते हैं।\n\nकाम-क्रोध पूरी तरह छोड़कर, पूरी तरह इन्द्रिय-निग्रह साध चुकों को हर जगह सब जीव-जंतुओं में भगवान दिखते हैं। किसी भी सांसारिक क्लेश का दर्द इन्हें नहीं होता। इनके मन में सर्वांतर्यामी, नित्य-स्वरूप भगवान टिके रहते हैं।\n\nबाहरी सुख से अंतरात्मा के सहज सुख की ओर मुड़ने का संदेश देने वाले कृष्ण, उसके पूरक ध्यान के बारे में संक्षेप में अगले श्लोक में बताते हैं।",
  "5.27": "स्पर्शान्कृत्वा बहिर्बाह्यांश्चक्षुश्चैवांतरे भ्रुवोः ।\n\nप्राणापानौ समौ कृत्वा नासाभ्यंतरचारिणौ ॥२७॥\n\nयतेंद्रियमनोवृत्तिर्मुनिर्मोक्षपरायणः ।\n\nविगतेच्छाभयक्रोधो यः सदा मुक्त एव सः ॥२८॥\n\n[इन दोनों श्लोकों (5.27 और 5.28) का पदच्छेद, अर्थ और विवरण अगले श्लोक (5.28) में एक साथ दिया गया है।]",
  "5.28": "स्पर्शान्कृत्वा बहिर्बाह्यांश्चक्षुश्चैवांतरे भ्रुवोः ।\n\nप्राणापानौ समौ कृत्वा नासाभ्यंतरचारिणौ ।\n\nयतेंद्रियमनोवृत्तिर्मुनिर्मोक्षपरायणः ।\n\nविगतेच्छाभयक्रोधो यः सदा मुक्त एव सः -- बाहरी विषयों का नाता बाहर छोड़कर, नज़र को दोनों भौंहों के बीच टिकाकर, नथुनों के भीतर चलने वाले प्राण-अपान को समान करके, इन्द्रियों और मन के खेल को काबू में रखने वाला, मुक्ति के लिए तड़पने वाला, इच्छा-भय-क्रोध छोड़ चुका — ऐसा साधक सदा मुक्त ही है।\n\nहमें अपना मन नियंत्रित करना हो तो पहले अपनी इन्द्रियों को बाहरी संसार में घूमने से रोकना चाहिए। \"स्पर्शान्कृत्वा बहिः बाह्यान्\" — बाहरी इन्द्रियों को नियंत्रित किए बिना मन को नियंत्रित करना संभव नहीं। इसके लिए बाहरी संसार के रूप-रस-स्पर्श-शब्द-गंध नाम के सुख के भ्रम को बाहर ही छोड़ना चाहिए।\n\nध्यान के लिए जरूरी एक और महत्वपूर्ण बात है अन्नमय-कोश (शरीर) को स्थिर करना। शरीर हिले तो मन हिलता है — तब एकाग्रता संभव नहीं। इसके लिए हमें सीधा (erect and straight body), जितना संभव हो उतने आसन (Posture) में अपने शरीर को स्थिर करना चाहिए। कृष्ण कहते हैं: \"चक्षुः च एव अंतरे भ्रुवोः\" ऐसा। अर्थात अपनी नज़र को दोनों भौंहों के बीच टिकाना। यह कठिन हो तो नाक की नोक भी चुन सकते हैं ऐसा शास्त्रकार कहते हैं। दोनों भौंहों के बीच आज्ञा-चक्र है, वहाँ नज़र टिकाने से यह शक्ति-केंद्र जाग्रत होता है। इससे अन्नमय-कोश स्थिर होता है।\n\nअन्नमय-कोश के बाद प्राणमय-कोश। \"प्राण अपानौ समौ कृत्वा नास अभ्यंतर चारिणौ\" — हमारे भीतर निरंतर हवा की चाल चलती रहती है; इस चाल को स्थिर करना कुम्भक कहलाता है। इसके दो प्रकार हैं — अंतः-कुम्भक और बाह्य-कुम्भक [इस तरह का प्राणायाम गुरु से सीखकर करना चाहिए, नहीं तो खतरा है]। इस तरह कुम्भक से प्राणमय-कोश स्थिर होता है। अगला कदम मनोमय और विज्ञानमय-कोश। हमारा मन चंचल है, वह एक जगह नहीं टिकता, उसे स्थिर करना चाहिए। \"इस राह पर मैं चलकर साध कर सिद्धि पाकर ही रहूँगा\" ऐसा हठ पकड़कर मन को उसके लिए तैयार करना चाहिए। इससे चित्त भगवान की ओर एकाग्र होता है। यह स्थिति पंचभौतिक रूप से हम पहुँच सकने वाली सबसे बड़ी स्थिति है। यहाँ का आनंद असीमित है। इस स्थिति के सुख का अनुभव करें तो आगे बाहरी संसार के सुख के पीछे हमारा मन कभी नहीं दौड़ता। मन भगवान में टिक जाता है। इससे हमारी इच्छा-भय-क्रोध सब मिट जाते हैं। \"ऐसा साधक सदा मुक्त ही है\" ऐसा कृष्ण कहते हैं।\n\nअन्नमय-कोश, प्राणमय-कोश, मनोमय-कोश और विज्ञानमय-कोश नाम के चार-प्रकार के अंतःकरण को पकाकर हम कैसे अपने भीतर के भगवान का दर्शन पा सकते हैं यह बताने वाले कृष्ण, अगले श्लोक में हमने कभी न देखे उस भगवान को किस तरह देखना चाहिए यह बताते हैं।",
  "5.29": "भोक्तारं यज्ञतपसां सर्वलोकमहेश्वरम् ।\n\nसुहृदं सर्वभूतानां ज्ञात्वा मां शांतिमृच्छति -- होम-व्रतों को खाने वाला, सभी लोकों के स्वामियों का भी बड़ा स्वामी, सभी जीवों का मित्र — ऐसा मुझे जानने वाला सुख की जड़ मुक्ति पाता है।\n\nवह भगवान सभी यज्ञों के भोक्ता हैं। (यहाँ यज्ञ का मतलब सिर्फ अग्नि-मुख में किया जाने वाला यज्ञ नहीं, पहले बताए गए सभी तरह के यज्ञ हैं।) हम यज्ञ में देवताओं के नाम पर अर्पित करने वाली हवि भी उस देवता के भीतर अंतर्यामी बने भगवान को अर्पित है ऐसी भावना से अर्पित करनी चाहिए। भगवान को अर्पित किए बिना अर्पित की गई कोई भी हवि देवता स्वीकार नहीं करते। हमारे हर एक कदम में भगवान का अनुसंधान होना चाहिए। वे सर्वसमर्थ, सभी क्रियाओं के नियामक हैं, सब कुछ उन्हीं को है यह अनुसंधान ध्यान में बहुत महत्वपूर्ण है।\n\nकुछ लोगों के लिए भगवान माने डर! यहाँ कृष्ण कहते हैं: 'सुहृदं सर्व भूतानाम्' ऐसा। भगवान से कभी डरना नहीं चाहिए। उनसे बड़ा आत्मीय मित्र कोई नहीं है। हमें सदा प्रेम करने वाली, निरंतर हमारे भीतर-बाहर भरकर सदा रक्षा करने वाली शक्ति भगवान है। हर एक को उसकी योग्यता के अनुसार बढ़ाने वाले, गलती करने पर केवल सुधारने के लिए सज़ा देकर राह दिखाने वाले, सदा करुणा से ऊपर उठाने वाले 'सुहृत्' वह भगवान हैं। ऐसा दयालु और कोई नहीं यह ज्ञान ध्यान में बहुत महत्वपूर्ण है। इसे जानकर अनुसरण करने वाला ज्ञानानंद की पराकाष्ठा मोक्ष पाता है ऐसा कृष्ण कहते हैं।\n\nइस प्रकार पाँचवाँ अध्याय समाप्त हुआ।",
  "6.1": "अध्याय छह\n\nपिछले अध्याय में मुख्यतः भगवान की उपासना की साधना का वर्णन करने वाले कृष्ण अब छठे अध्याय में ध्यानयोग और ध्यानसमाधि का मूल से वर्णन करते हैं।\n\nभगवानुवाच — भगवान ने कहा:\n\nअनाश्रितः कर्मफलं कार्यं कर्म करोति यः ।\n\nसः संन्यासी च योगी च न निरग्निः न चाक्रियः -- कर्म के फल का आश्रय लिए बिना कर्तव्य को करते रहने वाला ही सच्चा संन्यासी और सच्चा योगी है। जो अग्नि में हवन नहीं करता वह संन्यासी नहीं, और जिसने कर्म ही छोड़ दिया वह भी संन्यासी नहीं।\n\nसामान्यतः हम कर्मयोगियों को अलग और संन्यासियों को अलग, दो समूह मानते हैं। यहाँ कृष्ण संन्यासी कौन, कर्मयोगी कौन है, इस लौकिक कल्पना से भिन्न विवरण हमारे सामने रखते हैं। कृष्ण कहते हैं: \"अनाश्रितः कर्मफलम्।\" हम सामान्यतः कर्मत्याग करने वालों को संन्यासी और कर्म करने वालों को गृहस्थ मानते हैं। पर कृष्ण कहते हैं हर एक को कर्मयोगी बनना चाहिए और हर एक को संन्यासी भी बनना चाहिए। एक को छोड़कर दूसरा नहीं हो सकता। संन्यासी का अर्थ है हमने जो कुछ किया वह सब भगवान को अर्पित करना, न कि कुछ भी न करना। समस्त (सं) कर्म को भगवान को अर्पित करना ही 'सं-न्यास' है। यहाँ बहुत महत्वपूर्ण बात यह है कि कर्म के फल की इच्छा को सम्पूर्ण भगवान के हृदय में स्थापित करना। संन्यास का अर्थ अपने परिवार को छोड़कर वन जाना नहीं है। कर्मयोग तो करना ही होगा। \"कार्यं कर्म करोति यः\" -- जिस-जिस को जो-जो कार्य है उसे वह-वह करना ही होगा। इसी कारण संन्यास और कर्मयोग दोनों साथ-साथ रहते हैं। सच्चा संन्यासी कर्मयोगी होता है, और सच्चा कर्मयोगी संन्यासी होता है। इसके अलावा, जैसा हम समझते हैं, केवल अग्नि का त्याग करने वाले या कर्म का त्याग करने वाले संन्यासी या योगी नहीं होते।\n\nसंन्यासी कभी भी निष्क्रिय नहीं होता। हर एक का अपना कर्म होता है। ब्रह्मचारी अध्ययन, गुरुकुलवास, गुरुसेवा आदि कार्य करता है, तो गृहस्थ अतिथिसत्कार, संसारपालन आदि कार्य करता है। इस प्रकार सबके पास कर्म है।\n\nयं संन्यासमिति प्राहुर्योगं तं विद्धि पाण्डव ।\n\nनह्यसंन्यस्तसंकल्पो योगी भवति कश्चन ॥२॥",
  "6.2": "यं संन्यासम् इति प्राहुः योगं तं विद्धि पाण्डव । न हि असंन्यस्त संकल्पः योगी भवति कश्चन -- जिसे संन्यास कहते हैं उसे ही योग जान, हे पाण्डव। इच्छाओं का 'संन्यास' न करने वाला कोई भी मर्म को समझने वाला कर्मयोगी नहीं बन सकता।\n\nसंन्यास भी एक योग है। कर्मफलत्याग भी कर्म करने वाले कर्मयोगी के योग का एक पहलू है। सब कुछ भगवान को अर्पित करके, फल की कामना के बिना, भगवत्पूजा की दृष्टि से किया गया कर्म सात्त्विकों की साधना है। संन्यास का अर्थ है काम-संकल्प को भगवान में अर्पित करना। काम अर्थात \"करना चाहिए\" ऐसी इच्छा, संकल्प अर्थात \"करूँगा\" ऐसा निश्चय। काम-संकल्प से रहित होना ही संन्यास है। यहाँ कृष्ण जो बता रहे हैं वह आश्रम (संन्यासाश्रम) से सम्बन्धित विषय नहीं है, यह साधना से सम्बन्धित विषय है। साधना के मार्ग में योगियों को संन्यासी बनना चाहिए और संन्यासियों को योगी बनना चाहिए, यही कृष्ण का संदेश है।\n\nहम जब साधना करते हैं तब कर्म भी होना चाहिए, फलन्यास भी होना चाहिए। ऐसे में क्या सबके लिए करने योग्य किसी कर्म को माना गया है? साधक का सामाजिक कर्तव्य क्या है? समाज के साथ साधक कैसे व्यवहार करे? कर्म का अंत कब? साधना और कर्म में क्या तालमेल है, वह साधना के लिए कैसे सहायक है? इन सब प्रश्नों का उत्तर कृष्ण अगले श्लोक में देते हैं।\n\nआरुरुक्षोर्मुनेर्योगं कर्म कारणमुच्यते ।\n\nयोगारूढस्य तस्यैव शमः कारणमुच्यते ॥३॥",
  "6.3": "आरुरुक्षोः मुनेः योगम् कर्म कारणम् उच्यते । योग आरूढस्य तस्य एव शमः कारणम् उच्यते -- साधना की सीढ़ी चढ़ने वाले के लिए लक्ष्य तक पहुँचने का कारण कर्मयोग [अनेक प्रकार की जनसेवा] कहा जाता है। जब वही लक्ष्य तक पहुँच जाता है तब भगवत्समाधि [जनसेवा से विराम और भगवान में ध्याननिष्ठा] सुख की वृद्धि का कारण कही जाती है।\n\nइस श्लोक के दो आयाम हैं। एक, साधक अपने नित्यकर्म को कहाँ तक करे और कहाँ से छोड़ सकता है यह एक आयाम है, तो दूसरा, सामाजिक रूप से साधक का कर्तव्य क्या है यह इस श्लोक में बताया गया है।\n\nअभी सिद्धि न पाने वाला, साधना के मार्ग पर चल रहा साधक उस अवस्था में सभी विहित कर्म करता रहे, कुछ भी न छोड़े। सिद्ध हो जाने पर वह समाधि अवस्था में भगवान को भीतर से देख सकता है। उस अवस्था में उसके लिए शेष कर्मों से अधिक भीतर भगवान को देखने वाला कर्म महत्वपूर्ण हो जाता है। अपरोक्ष ज्ञान पाया हुआ व्यक्ति सदा समाधि अवस्था में नहीं रह सकता; उसे बाहरी दुनिया में आना ही होता है। तब उसका मुख्य कर्म शास्त्रश्रवण, मंत्रजप, प्रवचन आदि होता है। इसलिए विहित कर्मों की विधि-निषेध की बद्धता अपरोक्ष ज्ञान तक ही है। उदाहरण के लिए एक अपरोक्ष ज्ञानी ध्यान में बैठा है। वह अपने भीतर भगवान को देख रहा है और उस आनंद में डूबा है। वह सुबह का समय, सूर्योदय का समय है। स्नान करके संध्यावंदन करने के समय यह ध्यान में बैठा है, ऐसा सोचकर हमें उसे जगाना गलत है। वह संध्यावंदन न करे तो भी कोई कर्म का लेप नहीं होता, क्योंकि संध्यावंदन भगवान के दर्शन के लिए ही किया जाता है, और वह पहले से ही भगवान का दर्शन पा रहा है। इस प्रकार अपरोक्ष ज्ञानी के लिए कर्म की बद्धता नहीं है। समाधि अवस्था से बाहर आने पर उसका कर्तव्य भगवान का गुणगान, प्रवचन, अध्ययन, जप आदि होता है।\n\nइस श्लोक के एक अन्य आयाम को मध्वाचार्य ने अपने गीतातात्पर्य में बहुत सुंदर ढंग से समझाया है। यह मुख्यतः साधक का सामाजिक आचरण कैसा होना चाहिए यह बताता है। कर्म शब्द को आचार्य ने एक अद्भुत अर्थ दिया है। कर्म अर्थात करम। कर अर्थात कंदाय (Duty)। जिसे कंदाय जानकर हमें करना चाहिए वह \"कर-म\" है। हम भगवान के राज्य की प्रजा हैं; इसीलिए उन्हें हम जो कर देते हैं वह कर-कर्म है। किसी इच्छा से मंदिर में हम जो भेंट चढ़ाते हैं वह असली कंदाय नहीं है, उसे भगवान चाहते भी नहीं। भगवान हमसे जो कर्म चाहते हैं वह है कष्ट में पड़े लोगों की सेवा। एक साधक के अपरोक्ष साधक बनने तक यह उसकी साधना में एक मुख्य साधना है। सभी जीवों पर करुणा, सेवा की भावना बहुत महत्वपूर्ण है। योगशास्त्र में भी यही कहा गया है। मैत्री, करुणा, मुदिता और उपेक्षा नामक चार भावनाएँ एक साधक में होनी चाहिए। मैत्री का अर्थ है सज्जनों का साथ, जहाँ अच्छाई है वहाँ स्नेह। दुःख देखने पर करुणा और सहायता -- करुणा। दूसरे के उद्धार को देखकर प्रसन्न होना -- मुदिता। दुष्टों से दूर रहना -- उपेक्षा। बुरे लोगों से झगड़ा न करते हुए उनके साथ से बिना किसी द्वेष के दूर रहना उपेक्षा है। इस प्रकार साधक के जीवन में यह एक बड़ा सामाजिक कर्तव्य है। जो सिद्ध हो गया है (योगारूढ) वह सदा अंतर्मुखी रहता है; उसके लिए यह सामाजिक बद्धता नहीं है (उसके लिए यह संभव भी नहीं होता)। उसके आनंद की वृद्धि का कारण है शम -- अर्थात सदा भगवान में ही मन लगाए रखना। उससे भिन्न कोई अन्य कर्म उसके लिए नहीं है।\n\nइस प्रकार लोकसेवा एक साधक का अभिन्न अंग बनना चाहिए यह कृष्ण ने इस श्लोक में स्पष्ट रूप से कहा। योगारूढ़ को कोई सामाजिक बद्धता नहीं है, वह भीतर भगवान को देखता रहता है, ऐसा कृष्ण के कहने पर हमारे मन में एक प्रश्न उठ सकता है -- ऐसे अपरोक्ष ज्ञानियों को पहचानें कैसे? अगला श्लोक हमारे इस प्रश्न का उत्तर है।\n\nयदा हि नेन्द्रियार्थेषु न कर्मस्वनुषज्जते ।\n\nसर्वसंकल्पसंन्यासी योगारूढस्तदोच्यते ॥४॥",
  "6.4": "यदा हि न इन्द्रिय अर्थेषु न कर्मसु अनुषज्जते । सर्व संकल्प संन्यासी योगारूढः तदा उच्यते -- सभी कर्म का भार भगवान को अर्पित करके, इन्द्रिय विषयों में और कर्मों में हर प्रकार का लगाव खो देने पर साधना के लक्ष्य को पा चुका माना जाता है।\n\nअपरोक्ष ज्ञानी का लक्षण बताते हुए कृष्ण कहते हैं: \"यदा हि न इन्द्रिय अर्थेषु न कर्मसु अनुषज्जते\" अर्थात अपरोक्ष ज्ञानी इन्द्रियों को खींचने वाली चीज़ों में (शब्द, रूप, रस, गंध, स्पर्श, या किसी भी विषय में) आसक्त नहीं रहता। वह क्रिया करता है पर उससे स्वयं को चिपकाता नहीं है। साधना के मार्ग पर चल रहा साधक कठिनाई से इन्द्रिय निग्रह करता है, अपरोक्ष ज्ञानियों के लिए यह सहज धर्म हो जाता है। ऋग्वेद में कहा गया है -- \"जगत का नियामक नरसिंह है। उसकी इच्छा ही मेरी इच्छा हो। उसके हृदय में जो इच्छा है वही मेरी भावना हो। उसके विरुद्ध कोई संकल्प मुझे न आए।\" इसी तरह अपरोक्ष ज्ञानी चाहता है। वह इन्द्रिय के माध्यम से कुछ भी अनुभव करना नहीं चाहता, न ही तड़पता है। इन्द्रिय के माध्यम से आए अनुभव से प्रभावित होकर उससे चिपकता भी नहीं। वह सब कुछ तटस्थ भाव से देखता रहता है। जैसे हम समुद्र के किनारे बैठकर समुद्र को देखें तो वहाँ अनेक प्रकार की लहरें होती हैं; हम उन लहरों को देखकर आनंदित होते रहते हैं। वहाँ आने वाली लहरों का नियंत्रण हमारे हाथ में नहीं है। जो लहर जैसे आई वैसे ही तटस्थ भाव से आस्वाद लेने में आनंद है। जीवन-सागर में कष्ट, सुख, दुःख, हर्ष सब लहरों की तरह आते-जाते रहते हैं। उनका नियंत्रण हमारे हाथ में नहीं है। समुद्र की लहर को देखकर प्रसन्न होने की तरह इस जीवन की लहर को सहजता से देखकर प्रसन्न होते हुए जीना ही अपरोक्ष ज्ञानी का लक्षण है।\n\nइस अध्याय में कृष्ण आगे ध्यान की सम्पूर्ण प्रक्रिया का वर्णन करते हैं। इसके लिए हमारे मन को कैसे तैयार करना चाहिए, हमें योगारूढ़ बनने के लिए क्या करना चाहिए इसका प्रस्ताव अगला श्लोक है।\n\nउद्धरेदात्मनात्मानं नात्मानमवसादयेत् ।\n\nआत्मैव ह्यात्मनो बन्धुरात्मैव रिपुरात्मनः ॥५॥",
  "6.5": "उद्धरेत् आत्मना आत्मानम् न आत्मानम् अवसादयेत् । आत्मा एव हि आत्मनः बन्धुः आत्मा एव रिपुः आत्मनः -- अपने बल से [भगवान की कृपा से] जीव को ऊपर उठाना चाहिए; जीव को उलझन में नहीं डालना चाहिए। भगवान ही जीव के मित्र हैं; भगवान ही जीव के शत्रु हैं।\n\nपहले बताए अनुसार आत्मा शब्द के अनेक अर्थ हैं -- शरीर, मन, जीव, परमात्मा। इस श्लोक में आए आत्मा शब्द को इन सभी अर्थों से जोड़कर देखने पर अनेक बातें स्पष्ट होती हैं। \"उद्धरेत् आत्मना आत्मानम् न आत्मानम् अवसादयेत्\" का अर्थ है -- हमारे पतन का कारण भी मन है, हमारे उद्धार का कारण भी मन है। इसलिए मन से जीव के उद्धार का मार्ग खोज, ऐसा कृष्ण कहते हैं। कभी मन को नीचे मत भेज। जीव के पतन का कारण बने ऐसा मन को स्वच्छंद मत छोड़, उसे ऊपर ले जा। मन नीचे जाए तो वह हमें पाताल में धकेल देता है। उस मन को ऊँचाई पर भेज; ऊँचाई पर गया मन तुझे ऊँचाई पर ले जाएगा। मन से अपने जीव स्वरूप का उद्धार कर ले। जीव के लिए मन ही बंधु है, मन ही शत्रु है। इसलिए साधना करनी है तो मन को बंधु बनाकर बदल ले। मन तेरे विरुद्ध शत्रु बनकर खड़ा हो जाए तो तेरे जीवनकाल में कभी उद्धार नहीं होगा। इसीलिए पहले बुद्धिबल से मन को प्रशिक्षित करके उसे जीतना चाहिए, यह कृष्ण का संदेश है। मन को जीत लेने पर सब कुछ शांत हो जाता है, कोई भ्रम नहीं रहता। यह ध्यान के लिए आवश्यक पूर्व स्थिति है।\n\nकृष्ण के इस संदेश को सुनकर हमारे सामने एक प्रश्न आता है। पहले कृष्ण ने ही कहा था कि कुछ भी हमारे हाथ में नहीं है; भगवान की कृपा के बिना हम अपने मन को स्वतंत्र रूप से कभी नियंत्रित नहीं कर सकते। तो फिर हम अपने मन को कैसे नियंत्रित करें? हमारे इस प्रश्न का उत्तर इसी श्लोक में है। आत्मा का अर्थ परमात्मा -- इस सूक्ष्म अर्थ में इस श्लोक को देखने पर हमारे प्रश्न का उत्तर मिलता है। \"उद्धरेत् आत्मना आत्मानम्\" का अर्थ है -- आत्मा से ही (भगवान से ही) आत्मा को (जीव को) उबारना चाहिए। सामान्यतः मन हमारी बात नहीं सुनता। \"मुझसे यह नहीं हो सकता\" ऐसा कहता है मन। पर हमें भगवान ने बुद्धि दी है, हमें उसका उपयोग करना चाहिए। बुद्धि का उपयोग करके उस भगवान से \"मुझे अच्छा मन दे, मुझे उद्धार के मार्ग पर चला, साधना करने वाली सद्बुद्धि दे\" ऐसी उस भगवान से निरंतर प्रार्थना कर। वे हमारे सबसे आत्मीय हितचिंतक बंधु हैं। वे अकेले ही किसी स्वार्थ के बिना, शाश्वत, निष्कपट, निरंतर बंधु हैं। वे निश्चित ही हमारी प्रार्थना स्वीकार कर हमारे मन में आकर बैठ जाते हैं।\n\nभगवान को हम जैसे देखते हैं वैसे ही वे प्रकट होते हैं। देवताओं ने उन्हें ज्ञानी के रूप में देखा -- वे उनके लिए ज्ञानी बनकर प्रकट हुए और उनका उद्धार किया। राक्षसों ने उन्हें मारने वाला और शत्रु समझकर उनसे द्वेष किया -- वे उनके लिए शत्रु बनकर प्रकट हुए। इसीलिए कृष्ण कहते हैं: \"आत्मा एव रिपुः आत्मनः।\" अर्थात हम जब अहंकार से भटक जाते हैं तब वे हमें अपने शत्रु जैसे प्रतीत होते हैं। इस पर अगला श्लोक और अधिक प्रकाश डालता है।\n\nबन्धुरात्मात्मनस्तस्य येनात्मैवात्मना जितः ।\n\nअनात्मनस्तु शत्रुत्वे वर्तेतात्मैव शत्रुवत् ॥६॥",
  "6.6": "बन्धुः आत्मा आत्मनः तस्य येन आत्मा एव आत्मना जितः । अनात्मनः तु शत्रुत्वे वर्तेत आत्मा एव शत्रुवत् -- जो जीव विवेक से भगवान को [भक्ति से] जीत सके, जिस जीव से भगवान वश में हो गए हों, ऐसे जीव के लिए भगवान मित्र हैं। जो भगवान को नहीं जीत सका उसके लिए भगवान ही शत्रु की तरह प्रतिद्वंद्वी हैं।\n\nजिन्होंने भगवान को जीत लिया है, जो भगवान के प्रेम के पात्र बन गए हैं, उनके लिए वे बंधु हैं। भगवान के प्रेम के पात्र बनने के लिए उनकी कृपा चाहिए। उनकी कृपा से उन्हें रिझाकर उनके प्रेम के पात्र बने लोगों के लिए वे बंधु हैं। जो भगवान की ओर पीठ करके आगे बढ़े, वे सदा भगवान से दूर जाते रहते हैं। उन्हें पीठ दिखाकर उनसे द्वेष करने वालों के लिए वे शत्रु जैसे दिखते हैं। इसी कारण निरंतर भगवान से प्रार्थना कर -- \"बंधु बनकर मेरे भीतर आकर बस, मुझे अच्छे मार्ग पर चला, मुझे अपनी ओर मोड़कर आगे ले चल।\" ऐसी प्रार्थना और शरणागति हमारे मन को उनमें स्थिर होने देती है। यह ध्यान की पहली सीढ़ी है। इस प्रकार मन को वश में करने के लिए भगवान की कृपा पाने का प्रयत्न करने पर क्या होता है, यह हम आगे के श्लोकों में देखेंगे।\n\nजितात्मनः प्रशान्तस्य परमात्मा समाहितः ।\n\nशीतोष्णसुखदुःखेषु तथा मानापमानयोः ॥७॥",
  "6.7": "जितात्मनः प्रशांतस्य परमात्मा समाहितः ।\n\nशीतोष्णसुखदुःखेषु तथा मानापमानयोः ॥७॥\n\n[इन दोनों श्लोकों (6.7, 6.8) का पदच्छेद, अर्थ और विवरण अगले श्लोक (6.8) में एक साथ दिया गया है।]",
  "6.8": "जितात्मनः प्रशांतस्य परमात्मा समाहितः ।\n\nशीतोष्णसुखदुःखेषु तथा मानापमानयोः ।\n\nज्ञानविज्ञानतृप्तात्मा कूटस्थो विजितेंद्रियः ।\n\nयुक्त इत्युच्यते योगी समलोष्टाश्मकांचनः -- भक्ति से खुद को जीत चुके, शांत हुए व्यक्ति के हृदय में भगवान आकर बस जाते हैं। ऐसा व्यक्ति सर्दी-गर्मी, सुख-दुख और मान-अपमान जैसे द्वंद्वों में निर्विकार रहता है; भगवान के बोध और दर्शन से भरा हुआ, इन्द्रियों को काबू में रखने वाला होता है। उसके लिए मिट्टी, पत्थर, सोना सब बराबर हैं। ऐसा योग-साधक लक्ष्य तक पहुँच चुका माना जाता है।\n\nभक्ति से भगवान की कृपा मिलने पर पहले मन उन्हीं में टिक जाता है। मन किसी भी प्रसंग में उद्वेलित नहीं होता। \"परमात्मा समाहितः\" — भगवान उसके हृदय में आकर बस जाते हैं। हम चाहें तब उनका अंतर्दर्शन संभव है। इस तरह भगवान को देखने वालों के अपरोक्ष ज्ञान का क्या परिणाम होता है यह यहाँ कृष्ण फिर से बताते हैं।\n\nमुख्य रूप से अपरोक्ष ज्ञानियों को इन्द्रिय-चंचलता कभी नहीं सताती। अपमान से वे कभी नहीं झुकते। मान-अपमान उनके लिए बड़ी बात नहीं रहती। यह स्थिति पाया व्यक्ति सिद्ध कहलाता है। वह इतना निर्विकार हो जाता है कि सब कुछ समान देखने लगता है। धन-सोना सब उसे अनावश्यक लगता है और वह उससे दूर रहता है। (रामकृष्ण परमहंस की आत्मकथा पढ़ने पर एक अपरोक्ष ज्ञानी की मनःस्थिति हमें समझ आती है।)\n\nअगले श्लोक में कृष्ण ध्यान से पहले एक योगी की मनःस्थिति कैसी होनी चाहिए यह बहुत महत्वपूर्ण बात बताते हैं।",
  "6.9": "सुहृन्मित्रार्युदासीनमध्यस्थद्वेष्यबंधुषु ।\n\nसाधुष्वपि च पापेषु समबुद्धिर्विशिष्यते -- शुभचिंतक, मित्र, शत्रु, उदासीन, मध्यस्थ, न सहने वाले, रिश्तेदार, साधु और पापी — इन सबमें समान बुद्धि रखने वाला श्रेष्ठ है।\n\nमन संतुलित हुए बिना ध्यान संभव नहीं। किसी-किसी के बारे में कुछ-कुछ विचार मन में उठने लगें तो ध्यान असंभव है। संसार में कई तरह के लोग होते हैं। उदाहरण के लिए सुहृद — अच्छे हृदय वाले, बिना बदले की चाह किए सबकी मदद करने वाले। फिर मित्र — अपने आत्मीय की सदा मदद करने वाला, गलती होने पर सुधारने वाला। शत्रु — मारने वाली बुरी शत्रुता रखने वाले, इनसे द्वेष का कोई कारण नहीं चाहिए। उदासीन — जो न भले के लिए न बुरे के लिए हों। मध्यस्थ — भला करने पर भला, बुरा करने पर बुरा करने वाले। द्वेष्य — जिसे देखना सहन न हो। अंत में रिश्तेदार। इस तरह मानव-जाति में अच्छे और बुरे दोनों भरे रहते हैं।\n\nध्यान में भगवान का दर्शन पाना हो तो पहले हमें अपने अंतर में इन सभी तरह के लोगों के प्रति समान बुद्धि विकसित करनी चाहिए।",
  "6.10": "योगी युंजीत सततमात्मानं रहसि स्थितः ।\n\nएकाकी यतचित्तात्मा निराशीरपरिग्रहः -- योग-साधक अकेला एकांत में बैठकर, तन-मन को साधकर, बिना इच्छा के, बिना किसी चीज़ के लिए हाथ फैलाए, निरंतर अपने आपको समाधि के लिए तैयार करता रहे।\n\nध्यान-मार्ग में साधना करने वाले को मन को निरंतर ध्यान-योग में लगाने और एकाग्र करने का प्रयत्न करना चाहिए। भीड़-भाड़ में ध्यान का अभ्यास असंभव है। इसीलिए पुराने लोग ध्यान के लिए सुबह के अरुणोदय काल को सुरक्षित रखते थे।\n\nसूर्योदय से छियानवे मिनट पहले ध्यान के लिए बैठें तो उस समय पूरी प्रकृति शांत रहती है। यह समय मन को एकाग्रता की ओर ले जाने के लिए बहुत सहायक होता है। इसे 'ब्रह्ममुहूर्त' कहते हैं। इस मुहूर्त के देवता चतुर्मुख ब्रह्मा हैं। यही हमारे चित्त के भी देवता हैं। इसलिए यह समय जप, स्मरण और ध्यान के लिए सबसे श्रेष्ठ समय है। ध्यान एक बहुत अंतरंग क्रिया है। यहाँ केवल भगवान और साधक जीव ही होने चाहिए। तीसरा साथी आए तो परेशानी होती है।",
  "6.11": "शुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मनः ।\n\nनात्युच्छ्रितं नातिनीचं चेलाजिनकुशोत्तरम् ॥११॥\n\n[इन दोनों श्लोकों (6.11, 6.12) का पदच्छेद, अर्थ और विवरण अगले श्लोक (6.12) में एक साथ दिया गया है।]",
  "6.12": "शुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मनः ।\n\nनात्युच्छ्रितं नातिनीचं चेलाजिनकुशोत्तरम् ।\n\nतत्रैकाग्रं मनः कृत्वा यतचित्तेंद्रियक्रियः ।\n\nउपविश्यासने युंज्याद्योगमात्मविशुद्धये -- स्वच्छ स्थान में, न बहुत ऊँचा न बहुत नीचा, कुश-मृगचर्म-वस्त्र बिछाकर एक स्थिर आसन तैयार कर, वहाँ बैठकर, मन को एकाग्र कर, इन्द्रियों और मन की चंचलता को रोककर, आत्म-शुद्धि के लिए समाधि साधनी चाहिए।\n\nध्यान के लिए बैठने की जगह स्वच्छ होनी चाहिए। घर में सात्विक कंपन (Vibration) वाली जगह ध्यान के लिए चुननी चाहिए। पहले घर में जहाँ ज्यादा सात्विक कंपन होता वहाँ देवघर बनाते थे। दुर्भाग्य से आज हम घर बनाते समय जहाँ जगह बचती है उसे देवघर बना देते हैं। घर में जिस भाग में बैठने पर मन प्रसन्न होकर भगवान के ध्यान के लिए अनुकूल लगे, वहाँ सात्विक कंपन ज्यादा है यह हम आसानी से पहचान सकते हैं। इसी को यहाँ \"शुचि देश\" कहा गया है।",
  "6.13": "समं कायशिरोग्रीवं धारयन्नचलं स्थिरः ।\n\nसंप्रेक्ष्य नासिकाग्रं स्वं दिशश्चानवलोकयन् ॥१३॥\n\n[इन दोनों श्लोकों (6.13, 6.14) का पदच्छेद, अर्थ और विवरण अगले श्लोक (6.14) में एक साथ दिया गया है।]",
  "6.14": "समं कायशिरोग्रीवं धारयन्नचलं स्थिरः ।\n\nसंप्रेक्ष्य नासिकाग्रं स्वं दिशश्चानवलोकयन् ।\n\nप्रशांतात्मा विगतभीर्ब्रह्मचारिव्रते स्थितः ।\n\nमनः संयम्य मच्चित्तो युक्त आसीत मत्परः -- शरीर, सिर और गर्दन को सीधा, बिना हिले, स्थिर रखते हुए, इधर-उधर न देखते हुए, अपनी नाक की नोक पर नज़र टिकाकर, शांत आत्मा वाला, निर्भय, ब्रह्मचर्य-व्रत में स्थित, मन को संयमित कर, मुझमें ही चित्त लगाकर, मुझे ही परम मानकर, निरंतर मेरा स्मरण करते हुए समाधि साधनी चाहिए।\n\nध्यान के लिए बैठते समय कमर से ऊपर हमारा शरीर सीधी रेखा में होना चाहिए। पीठ नहीं झुकनी चाहिए, गर्दन-सिर नहीं झुकने चाहिए। शरीर को स्थिर करना चाहिए। इस तरह बैठे बिना मन की स्थिरता असंभव है। शरीर के भीतर एक और महत्वपूर्ण अंग है आँख। शरीर स्थिर करने के बाद आँख को स्थिर करना चाहिए। नाक की नोक पर दृष्टि टिकाकर किसी भी दिशा की कोई आकृति न दिखे इस तरह सीधे एक ही जगह दृष्टि स्थिर करनी चाहिए।\n\nइस तरह ध्यान की स्थिति पाने पर मन शांत हो जाता है। इससे सारा भय निकल जाता है। ध्यान के लिए अत्यंत महत्वपूर्ण एक और बात है ब्रह्मचर्य का पालन।\n\nध्यान का परिणाम क्या है? हमें ध्यान क्यों करना चाहिए? उत्तर अगले श्लोक में!",
  "6.15": "युंजन्नेवं सदात्मानं योगी नियतमानसः ।\n\nशांतिं निर्वाणपरमां मत्संस्थामधिगच्छति -- इस तरह भगवान का निरंतर ध्यान करते हुए, मन को काबू में रखने वाला साधक देह छोड़ने के बाद मुझमें ही टिकने वाले सुख का अनुभव करता है।\n\nइस अध्याय में अब तक कृष्ण ने जो बताया वह मन से किया जाने वाला ध्यान है। बाहरी इन्द्रियों को रोककर, चित्त और मन को नियंत्रित कर किया जाने वाला ध्यान। इससे आगे है 'तुरीयावस्था'। हमारे मन को पूरी तरह स्थिर कर, आत्म-स्वरूप जीव सीधे भगवान को देखने की स्थिति तुरीयावस्था है। इस श्लोक में कृष्ण तुरीयावस्था का संकेत देते हैं।\n\nध्यान में हम सीधे भगवान को नहीं, बल्कि भगवान के प्रतीक को देखते हैं। क्योंकि मन सीधे ज्ञानानंद-स्वरूप भगवान को ग्रहण नहीं कर सकता। भगवान का सीधा दर्शन पाना हो तो ध्यान से आगे तुरीयावस्था में जाना चाहिए। जीव-स्वरूप की आँख से भगवान को देखना चाहिए।\n\nएक जीव अपनी साधना की राह में पा सकने वाला सबसे बड़ा आनंद है — भगवान का साक्षात्कार। इससे बड़ा बोध, आनंद का दर्शन और कोई नहीं। इस तरह भगवान का साक्षात्कार करने वाला फिर कभी इस संसार-बंधन में नहीं फँसता। वह भगवान में ही टिककर मोक्ष पाता है।",
  "6.16": "नात्यश्नतस्तु योगोऽस्ति न चैकांतमनश्नतः ।\n\nन चातिस्वप्नशीलस्य जाग्रतो नैव चार्जुन -- हे अर्जुन, बहुत खाने वाले को ध्यान-योग संभव नहीं। बिल्कुल न खाने वाले को भी नहीं। बहुत सोने वाले को भी नहीं। नींद न आने वाले को भी नहीं।\n\nबहुत खाने वाले को ध्यान संभव नहीं। पेट में ज्यादा भोजन जाने पर मन सुस्त हो जाता है। इसीलिए मनन-शील व्यक्ति को पेटू नहीं होना चाहिए। ज्यादा भोजन करना अच्छा नहीं है। उसी तरह हमेशा ठीक से न खाएँ तो शरीर को पोषण न मिलकर शरीर कमज़ोर हो जाता है। भगवान का साक्षात्कार इसी शरीर के माध्यम से होता है। इसलिए हमें नियमित भोजन नियमित समय पर करने की आदत डालनी चाहिए।\n\nभोजन के साथ हमारी नींद की आदत भी नियमित होनी चाहिए। ज्यादा नींद कभी अच्छी नहीं। उसी तरह नींद न आए तो निश्चित रूप से ध्यान संभव नहीं। नियमित भोजन-नींद हमारे स्वास्थ्य के लिए भी सहायक है और ध्यान के लिए बहुत आवश्यक है।",
  "6.17": "युक्ताहारविहारस्य युक्तचेष्टस्य कर्मसु ।\n\nयुक्तस्वप्नावबोधस्य योगो भवति दुःखहा -- उचित भोजन-विहार वाले, कर्मों में उचित प्रयत्न करने वाले, उचित नींद-जागरण वाले को ध्यान-योग से दुख दूर हो जाता है।\n\nयोग-अभ्यास करते समय हमारा जीवनक्रम अनुशासित होना चाहिए। नियमित और उचित भोजन बहुत महत्वपूर्ण है। ध्यान के लिए मन को तैयार करने वाला सात्विक भोजन ध्यान के लिए सहायक है। कुछ भोजन हमारे मन पर बुरा असर डालते हैं — उदाहरण के लिए प्याज़ और लहसुन। इनमें औषधीय गुण होते हुए भी यह हमारे मन पर असर डालने वाला भोजन है।\n\nहमारे मन को जितना चाहिए उतना विश्राम देना बहुत महत्वपूर्ण है। परन्तु यह विश्राम आलस्य न बने। \"युक्तचेष्टस्य कर्मसु\" — हमें जो काम करना है उसे व्यवस्थित रूप से खुद करना चाहिए। करने योग्य काम में आलस्य नहीं होना चाहिए।\n\nशास्त्रीय, शुद्ध, व्यवस्थित भोजन, उचित समय पर उचित नींद-जागरण, व्यवस्थित परिश्रम और विश्राम — इस तरह रहने पर \"योगो भवति दुःखहा\" — दुख-रहित आनंदमय जीवन संभव है।",
  "6.18": "यदा विनियतं चित्तमात्मन्येवावतिष्ठते ।\n\nनिःस्पृहः सर्वकामेभ्यो युक्त इत्युच्यते तदा -- जब अच्छी तरह वश में किया चित्त आत्मा में ही टिक जाए, सारी कामनाओं की चाह मिट जाए, तब 'ध्यान-योगी' कहलाता है।\n\nयोग-अभ्यास से योगी की अवचेतना नियंत्रित होती है। सामान्यतः हमारे चित्त में रहने वाली पुरानी बुरी यादें सदा हमें सताती रहती हैं। किसी से बैर, किसी से प्यार — इन सबको हटाकर योगी अपने अंतरंग सिंहासन पर केवल भगवान को बिठा सकता है। ऐसा करने पर सदा अंतरंग में भगवान का दर्शन होता है। उस भगवान को देखने के बाद और कुछ नहीं चाहिए लगता। क्योंकि भगवान हमारी चाही चीज़ों में सबसे श्रेष्ठ है।",
  "6.19": "यथा दीपो निवातस्थो नेंगते सोपमा स्मृता ।\n\nयोगिनो यतचित्तस्य युंजतो योगमात्मनः -- हवा न चलने वाली जगह में दीपक जैसे नहीं हिलता, वैसे ही अपने भीतर को साधने वाले योगी के मन में भगवान संबंधी योग (आत्म-योग) अचल रहता है।",
  "6.20": "यत्रोपरमते चित्तं निरुद्धं योगसेवया ।\n\nयत्र चैवात्मनात्मानं पश्यन्नात्मनि तुष्यति ॥२०॥\n\n[इन चारों श्लोकों (6.20, 6.21, 6.22, 6.23) का पदच्छेद, अर्थ और विवरण अगले श्लोक (6.23) में एक साथ दिया गया है।]",
  "6.21": "सुखमात्यंतिकं यत्तद्बुद्धिग्राह्यमतींद्रियम् ।\n\nवेत्ति यत्र न चैवायं स्थितश्चलति तत्त्वतः ॥२१॥\n\n[इस श्लोक (6.21) का पदच्छेद, अर्थ और विवरण 6.20, 6.22, 6.23 श्लोकों के साथ अगले श्लोक (6.23) में एक साथ दिया गया है।]",
  "6.22": "यं लब्ध्वा चापरं लाभं मन्यते नाधिकं ततः ।\n\nयस्मिन्स्थितो न दुःखेन गुरुणापि विचाल्यते ॥२२॥\n\n[इस श्लोक (6.22) का पदच्छेद, अर्थ और विवरण 6.20, 6.21, 6.23 श्लोकों के साथ अगले श्लोक (6.23) में एक साथ दिया गया है।]",
  "6.23": "यत्रोपरमते चित्तं निरुद्धं योगसेवया ।\n\nयत्र चैवात्मनात्मानं पश्यन्नात्मनि तुष्यति ॥२०॥\n\nसुखमात्यंतिकं यत्तद्बुद्धिग्राह्यमतींद्रियम् ।\n\nवेत्ति यत्र न चैवायं स्थितश्चलति तत्त्वतः ॥२१॥\n\nयं लब्ध्वा चापरं लाभं मन्यते नाधिकं ततः ।\n\nयस्मिन्स्थितो न दुःखेन गुरुणापि विचाल्यते ॥२२॥\n\nतं विद्याद्दुःखसंयोगवियोगं योगसंज्ञितम् ।\n\nस निश्चयेन योक्तव्यो योगोऽनिर्विण्णचेतसा ॥२३॥ -- ध्यान की साधना से बँधा चित्त इस स्थिति में बाहरी विषयों की ओर नहीं बहता। यहाँ अपने भीतर ही (भगवान की कृपा से) भगवान को देखते हुए संतुष्ट होता है। यहाँ इन्द्रियों से न मिलने वाले, भीतर खिलने वाले असाधारण आनंद का अनुभव करता है। इस स्थिति में टिका व्यक्ति कभी भगवान से नहीं हटता। इसे पाने के बाद कोई और उपलब्धि इससे बड़ी नहीं लगती। यहाँ टिका व्यक्ति कैसे भी बड़े दुख से भी विचलित नहीं होता। इसे ही सारे दुखों से मुक्ति देने वाला योग जानना चाहिए। विषयों से ऊबकर पीठ मोड़ने वाले को यह योग अवश्य साधना चाहिए।\n\nबाहरी संसार से संपर्क खोकर मन भगवान में टिक जाए तब क्या होता है — कृष्ण कहते हैं: \"उपरमते चित्तम्\" अर्थात उस श्रेष्ठ आनंद में ही मन टिक जाता है। उस आनंद के स्रोत से अलग नहीं होना चाहिए ऐसा भाव आ जाता है।\n\nहमें आत्म-साक्षात्कार होने पर कभी न हुआ अपूर्व आनंद होता है। यह सबसे श्रेष्ठ आनंद का अनुभव है। भक्त की भगवान के प्रति भक्ति और भक्त पर भगवान का वात्सल्य — इन दोनों का मेल होने पर 'निर्भयता' आती है।",
  "6.24": "संकल्पप्रभवान्कामांस्त्यक्त्वा सर्वानशेषतः ।\n\nमनसैवेंद्रियग्रामं विनियम्य समंततः ॥२४॥\n\n[इन दोनों श्लोकों (6.24, 6.25) का पदच्छेद, अर्थ और विवरण अगले श्लोक (6.25) में एक साथ दिया गया है।]",
  "6.25": "संकल्पप्रभवान्कामांस्त्यक्त्वा सर्वानशेषतः ।\n\nमनसैवेंद्रियग्रामं विनियम्य समंततः ।\n\nशनैः शनैरुपरमेद्बुद्ध्या धृतिगृहीतया ।\n\nआत्मसंस्थं मनः कृत्वा न किंचिदपि चिंतयेत् -- मन में उठने वाली सारी इच्छाओं को पूरी तरह छोड़ देना चाहिए; इन्द्रियों के समूह को हर तरफ से मन-बल से ही काबू में रखना चाहिए; न डिगने वाली विवेक-बुद्धि से धीरे-धीरे मन को विषयों से हटाना चाहिए; भगवान में रखना चाहिए। रखकर फिर कुछ और नहीं सोचना चाहिए।\n\nमन को भगवान में स्थिर करने की विधि कृष्ण यहाँ फिर बताते हैं। हमारी सारी समस्याओं की जड़ हमारे संकल्प हैं। संकल्प अर्थात मन में क्या-क्या करना है इसका निर्णय। हम कोई भी काम करने से पहले उसे मानसिक रूप से करते हैं। आज यहाँ जाना है, ऐसे व्यक्ति से मिलना है, वहाँ ऐसा पाना है — इस तरह की समय-सारणी हमारे मन में गड़ी रहती है।\n\nचाहना मन का सहज गुण है, बिना चाहे जीना नहीं है। इसके लिए जो मिले वह मिले ऐसा चाहना सीखकर अपने बाकी संकल्प-विकल्प को छोड़ना चाहिए। यही सफलता का सूत्र है। हमारा संकल्प केवल एक ही होना चाहिए — \"भगवान का संकल्प जैसा है वैसा ही\"। द्वादश स्तोत्र में मध्वाचार्य कहते हैं जैसे: अपने हिस्से का नियत कर्म करो, जो मिले उसे खाओ, हरि के चरणों की सुधि न भूले। \"मेरा\" ऐसा अलग संकल्प न हो। वेद में कहा गया है जैसे — \"भगवान की चाह ही मेरी चाह हो, उनकी इच्छा ही मेरी इच्छा हो, इससे मेरी चाह भगवान की चाह से सुर मिलाए\"।",
  "6.26": "यतो यतो निश्चरति मनश्चंचलमस्थिरम् ।\n\nततस्ततो नियम्यैतदात्मन्येव वशं नयेत् -- चंचल, अस्थिर मन जहाँ-जहाँ भटके, वहाँ-वहाँ से इसे रोककर आत्मा में ही वश में लाना चाहिए।\n\nहमारा मन बहुत चंचल है। इसी कारण वह इधर-उधर बहता रहता है। जहाँ-जहाँ वह फिसलता है वहाँ-वहाँ भगवान नाम का बाँध लगाकर उसे भगवान में टिकाना चाहिए। इसके लिए निरंतर प्रयत्न ज़रूरी है।",
  "6.27": "प्रशांतमनसं ह्येनं योगिनं सुखमुत्तमम् ।\n\nउपैति शांतरजसं ब्रह्मभूतमकल्मषम् -- विषयों की ओर न बहने वाले, शांत मन वाले, रजोगुण की गर्मी बुझा चुके, भगवान में ही टिके ऐसे योगी को सबसे बड़ा सुख आ मिलता है।\n\nएक बार हमारा मन भगवान में टिक जाए तो उलझन का घर बना मन शांत हो जाता है। इसे साध चुका व्यक्ति किसी भी स्थिति में उद्वेलित नहीं होता। जीवन में हमें अनुभव करने योग्य सच्चा श्रेष्ठ सुख क्या है यह इस स्थिति में पता चलता है।",
  "6.28": "युंजन्नेवं सदात्मानं योगी विगतकल्मषः ।\n\nसुखेन ब्रह्मसंस्पर्शमत्यंतं सुखमश्नुते -- इस तरह सारी गंदगी मिटाकर सदा भगवान का ध्यान करने वाला साधक आराम से भगवद्-अनुभव के परम सुख को चखता है।\n\nभगवद्-अनुभूति होने पर होने वाला अंतरात्मा का आनंद दूसरे ढंग से कृष्ण यहाँ बताते हैं। भगवान का ध्यान करने के लिए मन को स्वच्छ कर एक बार भगवान को देखा जा सकता है। परन्तु भगवद्-अनुभव से नीचे उतरते ही तामसिक आवेश हमारा मन बिगाड़ सकता है। इसलिए सदा भगवद्-अनुभूति में ही टिकना चाहिए।",
  "6.29": "सर्वभूतस्थमात्मानं सर्वभूतानि चात्मनि ।\n\nईक्षते योगयुक्तात्मा सर्वत्र समदर्शनः -- ध्यान-योग के लिए मन तैयार किए साधक सभी जीवों में भगवान को देखता है और सभी जीवों को भगवान में देखता है। हर जगह रहने वाला भगवान एक-रूप है ऐसा देखता है।\n\nहम भगवान को ब्रह्म कहते हैं, परमात्मा कहते हैं। इसका क्या मतलब है? सभी काल में सभी जगह भरा हुआ विशाल ब्रह्म है। हर जगह व्याप्त, सभी गुणों से पूर्ण, काल-देश-गुण-शक्ति से अनंत परमात्मा है। यहाँ कृष्ण कहते हैं: \"सर्वभूतस्थमात्मानम्\" — अर्थात सभी जीव-जातियों के भीतर अंतर्यामी बनकर बिंब-रूप भगवान है। इतना ही नहीं \"सर्व भूतानि च आत्मनि\" अर्थात सभी जीव भगवान में हैं।",
  "6.30": "यो मां पश्यति सर्वत्र सर्वं च मयि पश्यति ।\n\nतस्याहं न प्रणश्यामि स च मे न प्रणश्यति -- जो मुझे हर जगह देखता है और सब कुछ मुझमें देखता है, उसके लिए मैं कभी खोता नहीं; वह भी मुझसे कभी नहीं खोता।\n\nआगे कृष्ण कहते हैं: \"जो इस तरह मुझे सबमें और सबको मुझमें देखता है उसके लिए मैं कभी नहीं मिटता। सदा उसके योग-क्षेम की ज़िम्मेदारी मेरी है। उसी तरह 'मैं उसके योग-क्षेम की देखभाल करता हूँ' यह सजगता सदा उसमें रहती है\" ऐसा।",
  "6.31": "सर्वभूतस्थितं यो मां भजत्येकत्वमास्थितः ।\n\nसर्वथा वर्तमानोऽपि स योगी मयि वर्तते -- सभी जीवों में स्थित मुझे एक-रूप मानकर पूजने वाला साधक चाहे जैसी स्थिति में रहे, वह मुझमें ही रहता है।\n\nकृष्ण कहते हैं: \"सर्वगत भगवान हर जगह एक-रूप हैं ऐसा अनुसंधान और निरंतर भक्ति रखने वाला साधक, वह चाहे कैसे भी हो, मुझसे मिलना निश्चित है\" ऐसा।",
  "6.32": "आत्मौपम्येन सर्वत्र समं पश्यति योऽर्जुन ।\n\nसुखं वा यदि वा दुःखं स योगी परमो मतः -- हे अर्जुन, जो अपनी तरह ही हर जगह सबको समान देखता है — चाहे सुख हो या दुख — वह सबसे बड़ा साधक माना जाता है।\n\nयोगियों में श्रेष्ठ वह अपनी तरह ही दूसरे को जानता है। हमें जो दुख देता है वह दूसरे को भी दुख देता है यह सच्चाई वह जानता है। सबको सुख-दुख हैं, अपनी तरह वे भी दुख नहीं चाहते इस सजगता से साधक व्यवहार करता है।",
  "6.33": "अर्जुन उवाच —\n\nयोऽयं योगस्त्वया प्रोक्तः साम्येन मधुसूदन ।\n\nएतस्याहं न पश्यामि चंचलत्वात्स्थितिं स्थिराम् -- हे मधुसूदन, तुमने समता वाला ध्यान-योग बताया। मुझे लगता है: मन चंचल होने के कारण इसमें दृढ़ता से टिकना संभव नहीं।",
  "6.34": "चंचलं हि मनः कृष्ण प्रमाथि बलवद्दृढम् ।\n\nतस्याहं निग्रहं मन्ये वायोरिव सुदुष्करम् -- कृष्ण, क्या मन चंचल नहीं है? हमें हरा देने जितना मज़बूत, बलशाली है। इसे काबू करना हवा को मुट्ठी में बाँधने जैसा मुझे लगता है।\n\nमन बहुत चंचल है, वह विषय से विषय की ओर उछलता रहता है। मेरा मन सदा मुझे झुका रहा है परन्तु मैं उसे नहीं झुका पा रहा। अर्जुन का यह प्रश्न हर पाठक के मन में भी आधा-आधा आया होगा। \"यह सब हम जैसों के लिए नहीं\" या \"यह हमसे संभव नहीं\" यह सामान्यतः हमारे मन में आने वाला पहला विचार है।",
  "6.35": "भगवानुवाच —\n\nअसंशयं महाबाहो मनो दुर्निग्रहं चलम् ।\n\nअभ्यासेन तु कौंतेय वैराग्येण च गृह्यते -- हे महावीर, बेशक मन चंचल और काबू में न आने वाला है। परन्तु हे कौन्तेय, बार-बार अभ्यास करने से और वैराग्य से इसे साधा जा सकता है।\n\nकृष्ण कहते हैं: \"तुम जो कहते हो उसमें कोई संदेह नहीं। मन को रोकना आसान काम नहीं, परन्तु अभ्यास और वैराग्य से इसे धीरे-धीरे साधा जा सकता है\" ऐसा। बिना प्रयत्न के कुछ भी साधना संभव नहीं। हर चीज़ के लिए प्रयत्न चाहिए। हम अपने मन के कहे अनुसार नाचने के आदी हो गए हैं। इसे छोड़कर हमारे कहे अनुसार मन सुने ऐसा प्रयत्न हमने कभी नहीं किया।\n\nइसका एक अच्छा उदाहरण है ग्रीस के दार्शनिक सुकरात की \"तीन छलनी\" वाली प्रसिद्ध कहानी। सुकरात का एक परिचित एक बार आकर उन्हें एक मित्र के बारे में कुछ सुनी-सुनाई बात बताने लगा। सुकरात ने उससे पहले तीन प्रश्न पूछे — क्या यह बात सच है, क्या यह अच्छी बात है, और क्या यह मेरे किसी काम की है? तीनों ही सवालों का जवाब \"नहीं\" निकला। तब सुकरात ने कहा कि जो बात न सच है, न अच्छी, न उपयोगी — उसे बताने का कोई मतलब नहीं, और उसकी बात सुनने से मना कर दिया।\n\nदोस्तो, यहाँ हमें यह सीखना है कि मन को व्यर्थ बातों में लगाने से पहले विषय को तीन बार छानना सीखें। अनावश्यक विचार में वैराग्य रखें और मन को एकाग्र करने की साधना का अभ्यास कराएँ। इस राह पर चलने वालों के लिए ध्यान-योग कभी असंभव नहीं है।",
  "6.36": "असंयतात्मना योगो दुष्प्राप इति मे मतिः ।\n\nवश्यात्मना तु यतता शक्योऽवाप्तुमुपायतः -- मन को न साधने वाले के लिए योग पाना कठिन है यह मेरा मत है। मन को काबू में रखने वाले, प्रयत्नशील व्यक्ति के लिए उपायपूर्वक इसे पाना संभव है।\n\nजो अपने आलस्य से, बुरी सांसारिक चाह से इस तरह प्रयत्न नहीं करता उसे समाधि कभी नहीं मिलती। वैराग्य और अभ्यास नाम के उपाय से मन को झुकाकर हमें चाहिए वैसा काम उससे करवाना चाहिए। ऐसा करने पर समाधि साधी जा सकती है ऐसा भरोसा कृष्ण यहाँ देते हैं।",
  "6.37": "अर्जुन उवाच —\n\nअयतिः श्रद्धयोपेतो योगाच्चलितमानसः ।\n\nअप्राप्य योगसंसिद्धिं कां गतिं कृष्ण गच्छति -- कृष्ण, श्रद्धा तो है परन्तु प्रयत्न पूरा न हुआ, ध्यान-योग से मन डिग गया। योग-सिद्धि न पाने वाले ऐसे व्यक्ति का क्या हाल होता है?\n\nयोग की साधना में साधना की, ध्यान करने का भी प्रयत्न किया, एक हद तक श्रद्धा से एकाग्रता का प्रयत्न किया, किसी कारण से पूरा लक्ष्य नहीं पाया — ऐसे व्यक्ति का क्या हाल होता है? ऐसे लोगों को सिद्धि नहीं मिलती क्या?",
  "6.38": "कच्चिन्नोभयविभ्रष्टश्छिन्नाभ्रमिव नश्यति ।\n\nअप्रतिष्ठो महाबाहो विमूढो ब्रह्मणः पथि -- हे महावीर, जगह न पाकर, भगवान की राह में लक्ष्य चूककर, वह इधर का न उधर का होकर टूटे बादल के टुकड़े जैसे मिट जाता है क्या?",
  "6.39": "एतन्मे संशयं कृष्ण छेत्तुमर्हस्यशेषतः ।\n\nत्वदन्यः संशयस्यास्य छेत्ता न ह्युपपद्यते -- कृष्ण, मेरे इस संदेह को पूरी तरह मिटाने में तुम ही समर्थ हो। तुम्हें छोड़कर इस संदेह को मिटाने वाला कोई और नहीं है।\n\nअर्जुन की विनम्र स्वीकृति — भगवान अकेला ही उत्तर देने में समर्थ है। प्रश्न के अंत में भक्त की शरणागति — यह एक उचित समापन है।",
  "6.40": "भगवानुवाच —\n\nपार्थ नैवेह नामुत्र विनाशस्तस्य विद्यते ।\n\nन हि कल्याणकृत्कश्चिद्दुर्गतिं तात गच्छति -- हे पार्थ, उसकी साधना व्यर्थ नहीं है, न यहाँ, न परलोक में। बेटा, भला करने वाला कभी बुरी गति को नहीं पहुँचता।\n\nअर्जुन के प्रश्न का कृष्ण का उत्तर बड़ा भरोसा है। कृष्ण कहते हैं: \"साधना की राह पर चलने वाले इस लोक में या परलोक में कुछ नहीं खोते। मेरे प्रिय मित्र, अच्छा करने वाले को कभी बुरा नहीं मिलता। यह प्रकृति का नियम है\" ऐसा।",
  "6.41": "प्राप्य पुण्यकृतां लोकानुषित्वा शाश्वतीः समाः ।\n\nशुचीनां श्रीमतां गेहे योगभ्रष्टोऽभिजायते -- ऐसा योग से भटका व्यक्ति पुण्यवानों के लोक पाकर वहाँ लंबे समय तक रहकर, फिर स्वच्छ और धनी लोगों के घर में जन्म लेता है।\n\nयोग का अभ्यास कर, भगवान के ध्यान का प्रयत्न कर, कुछ सीढ़ियाँ चढ़कर किसी कारण से, मन भटकने से या आयु समाप्त होने से, वहीं रुक गए व्यक्ति की साधना कभी व्यर्थ नहीं जाती।",
  "6.42": "अथवा योगिनामेव कुले भवति धीमताम् ।\n\nएतद्धि दुर्लभतरं लोके जन्म यदीदृशम् -- या फिर बुद्धिमान योगियों के घराने में जन्म लेता है। संसार में इस तरह का जन्म बहुत दुर्लभ है।\n\nआगे कृष्ण कहते हैं: नहीं तो योग-सिद्धों के घर में वह जन्म लेता है। इससे गर्भ से ही उसे योग की दीक्षा मिल जाती है। पिछले जन्म में साधना की जो सीढ़ी उसने चढ़ी थी उस सीढ़ी तक वह आसानी से पहुँचकर वहाँ से आगे की साधना करने का मौका उसे मिलता है।",
  "6.43": "तत्र तं बुद्धिसंयोगं लभते पौर्वदेहिकम् ।\n\nयतते च ततो भूयः संसिद्धौ कुरुनंदन -- हे कुरुनंदन, वहाँ पिछले जन्म का वह बुद्धि-संबंध फिर पाता है, और फिर सिद्धि के लिए प्रयत्न करता है।\n\nपिछले जन्म में उसने जो साधना की थी वह सब अवचेतन में छिपी रहती है, और उसके अनुकूल वातावरण मिलते ही वह जाग जाती है। इस जन्म की वृद्धि पिछले जन्म की वृद्धि का उत्तरार्ध बनती है।",
  "6.44": "पूर्वाभ्यासेन तेनैव ह्रियते ह्यवशोऽपि सः ।\n\nजिज्ञासुरपि योगस्य शब्दब्रह्मातिवर्तते -- पिछले अभ्यास के बल से बिना जाने भी उसका मन उसी ओर बहता है। ध्यान-योग को जानने की चाह रखने वाला भी वेद-शब्द से परे परब्रह्म तक पहुँच जाता है।\n\nवेदज्ञों के घर जन्म न लेने पर भी पिछले जन्म की साधना के फल से बिना जाने हमारा मन साधना की ओर बहता है। प्रह्लाद और पिंगला की कथा इसका अच्छा उदाहरण है।",
  "6.45": "प्रयत्नाद्यतमानस्तु योगी संशुद्धकिल्बिषः ।\n\nअनेकजन्मसंसिद्धस्ततो याति परां गतिम् -- प्रयत्न से जुटा साधक मन की गंदगी मिटाकर, कई जन्मों की साधना से सिद्धि पाकर, बड़े ठिकाने भगवान तक पहुँचता है।\n\nपहले कहा गया जैसे हमारी साधना कई जन्मों की है। पहले हममें इच्छा जगी, उससे वह इच्छा पूरी होने का वातावरण अगले जन्म में भगवान ने दिया, वहाँ प्रयत्न कर भीतर की गंदगी धुली, साधना से स्वच्छ ज्ञान आया।",
  "6.46": "तपस्विभ्योऽधिको योगी ज्ञानिभ्योऽपि मतोऽधिकः ।\n\nकर्मिभ्यश्चाधिको योगी तस्माद्योगी भवार्जुन -- ध्यान-योग का साधक तपस्वियों से बड़ा है; केवल शास्त्र जानने वालों से भी बड़ा माना जाता है। कर्म-योगियों से भी बड़ा है। इसलिए हे अर्जुन, तुम ध्यान-योगी बनो।\n\nजो अंतरात्मा में एकाग्र होकर भगवान का ध्यान कर सकता है, वह तपस्या करने वाले से बड़ा है ऐसा कृष्ण कहते हैं। यहाँ तपस्या अर्थात हम करने वाला व्रताचरण। देह-दंडन, एकादशी उपवास, ब्रह्मचर्य-पालन आदि। सैकड़ों बाहरी व्रताचरण, होम-हवन करने वालों से भी अंतरात्मा में ध्यान करने वाला भगवान को ज्यादा प्रिय है। वह ज्ञानियों से भी बड़ा है ऐसा कृष्ण कहते हैं। अर्थात ध्यान के बारे में, शास्त्र के बारे में केवल जानने वालों से ध्यान करने वाला बड़ा है। आज अध्यात्म की बात करने वाले मिल जाते हैं, परन्तु सच्चे ध्यान-योगी मिलना बहुत दुर्लभ है। जैसा अमेरिकी लेखक थोरो ने अपनी किताब वॉलडेन में कहा था — आजकल दर्शनशास्त्र के प्रोफेसर तो मिलते हैं, परन्तु दार्शनिक नहीं मिलते।\n\nहममें से कुछ लोग कर्मठ हैं। यज्ञ-याग करने वाले, अग्नि के मुख से भगवान की आराधना करने वाले। यह कर्म अंतरात्मा में भगवान को देखने के लिए है। इसी तरह मूर्ति-पूजा। हमारी पूजा केवल भगवान की मूर्ति तक सीमित न होकर वह अंतरात्मा में भगवान को देखने में मदद करने वाला प्रतीक है यह ज्ञान हमें होना चाहिए। मानस-पूजा के बिना बाहरी पूजा, पूजा ही नहीं है। इसलिए केवल कर्मठ बनकर बाहरी पूजा करने वाले से मानस-पूजा करने वाला ध्यान-योगी बड़ा है। \"इसलिए तुम जीवन में ध्यान-योगी बनो, अंतरात्मा के ध्यान में लग जाओ। उस ध्यान में लगने के बाद तुम्हारे बाहरी कर्म तुम्हें नहीं चिपकेंगे। तब युद्ध भी भगवत्-पूजा बन जाएगा\" यह अर्जुन को कृष्ण का संदेश है।",
  "6.47": "योगिनामपि सर्वेषां मद्गतेनांतरात्मना ।\n\nश्रद्धावान्भजते यो मां स मे युक्ततमो मतः -- मुझमें ही अंतरात्मा रखकर श्रद्धा से मुझे भजने वाला बाकी सभी ध्यान-योगियों से बड़ा योगी है ऐसा मेरा मत है।\n\nध्यान करते समय हम मन को किसी पर भी एकाग्र कर ध्यान कर सकते हैं। कुछ लोग कई छोटे देवताओं, भूत-प्रेतों की उपासना करने वाले होते हैं। परन्तु कृष्ण कहते हैं: \"जो भगवान में ही मन रखकर ध्यान करते हैं वे सबसे बड़े योगी हैं\" ऐसा। भगवान को छोड़कर कुछ और ध्यान करें तो कोई उपयोग नहीं। हमारे ज्योतिषी सामान्यतः 'ऐसे ग्रह-दोष के लिए ऐसे देवता की उपासना करो' कहते हैं। इसका मतलब है उस प्रतीक में भगवान को देखो। किसी भी देवता की उपासना करते समय उस प्रतीक में भगवान की उपासना न करें तो वह सच्चा योग नहीं बनता। ध्यान में केवल भगवान को देखने की चाह और हर प्रतीक में उन्हें ही देखना श्रेष्ठ योग है। इस तरह जीने पर हमारा जीवन ही एक योग बन जाता है।\n\nइस प्रकार छठा अध्याय समाप्त हुआ।\n\nयहाँ भगवद्गीता का पहला षट्क (पहले छह अध्याय) समाप्त हुआ। इस षट्क में भगवान की उपासना का ज्ञान और सांख्य कृष्ण ने बताया। ज्ञानपूर्वक भगवद्-उपासना करने की विधि गीता का पहला षट्क बताता है। आगे भगवान की उपासना का विषय और भगवान की महिमा के विवरण आते हैं।",
    "7.1": `अध्याय सात

पिछले अध्याय में ध्यानयोग का वर्णन करने के बाद अब कृष्ण ज्ञान-विज्ञान का, अर्थात् भगवान के स्वरूप-ज्ञान के साथ-साथ वे किस वस्तु में किस विशेष रूप में स्थित हैं इसके विस्तृत ज्ञान का, वर्णन करते हैं।

भगवानुवाच — भगवान ने कहा:

मयि आसक्तमनाः पार्थ योगं युञ्जन् मदाश्रयः ।

असंशयं समग्रं मां यथा ज्ञास्यसि तच्छृणु -- पार्थ, मुझमें मन को आसक्त करके, मुझ पर ही प्रेम करते हुए, मेरी ही शरण लेकर, योग-साधना में लगे रहकर, निःसंदेह मुझे सम्पूर्ण रूप से कैसे जान सकते हो, वह सुनो।

हमारे इस मन को, जो मतवाले हाथी या बैल के समान है, साधना के मार्ग पर वश में करके परिपक्व बनाने के बाद, भगवान में कभी न डिगने वाली दृढ़ और गहरी भक्ति से, अहंकार छोड़कर, सम्पूर्ण शरणागति से (हर समय हम भगवान के अधीन हैं इस जागरूकता से), भगवान को अपने आप को पूरी तरह अर्पित करके, ध्यानयोग में लगे रहने के बाद, "ज्ञान की पूर्ण क्षमता तक भगवान को कैसे जाना जा सकता है" वह सुनो, ऐसा कृष्ण कहते हैं।`,
  "7.2": `ज्ञानं ते अहं सविज्ञानम् इदं वक्ष्यामि अशेषतः ।

यज्ज्ञात्वा न इह भूयः अन्यज्ज्ञातव्यम् अवशिष्यते -- जानने योग्य मेरी महिमा को उसके विस्तार के साथ मैं तुम्हें पूरी तरह कहूँगा। इसे जान लेने पर फिर इस विषय में और कुछ जानना शेष नहीं रहता।

जिसे जान लेने पर सब कुछ जान लिया जाता है, वही मैं तुम्हें बताऊँगा, ऐसा कृष्ण कहते हैं। उपनिषद में एक वचन है "यस्मिन् विज्ञाते सर्वमिदं विज्ञातं भवति" (शाण्डिल्य-२.२; मुण्डक १.१.३) अर्थात् जिसे जान लेने पर सब कुछ जान लिया जाता है, उसे पहले जानना चाहिए। हम यदि भगवान को जान लें तो इस संसार को जान लिया, ऐसा ही समझो। इसे छोड़कर संसार को जानकर भगवान को जानना चाहें तो यह असम्भव है। यहाँ कृष्ण कहते हैं: "जिस बात को जान लेने पर फिर कोई और बात जानना शेष नहीं रहता, वह विज्ञान मैं तुम्हें दूँगा।" ज्ञान जब विज्ञान बनता है तभी वह सम्पूर्ण होता है। विज्ञान अर्थात् वि+ज्ञान। यहाँ 'वि' उपसर्ग है, 'वि' का अर्थ है विलक्षण, विशिष्ट, विशेष आदि। किसी विषय को तलस्पर्शी रूप से जानना विज्ञान है। यहाँ कृष्ण विज्ञान के बारे में कह रहे हैं। "भगवान हैं, वे सर्वसमर्थ हैं, सर्वान्तर्यामी हैं" यह ज्ञान है; वे कहाँ कैसे हैं, किस वस्तु में किस रूप में विभूति हैं यह विस्तार से जानना विज्ञान है।`,
  "7.3": `मनुष्याणाम् सहस्रेषु कश्चित् यतति सिद्धये ।

यतताम् अपि सिद्धानाम् कश्चित् माम् वेत्ति तत्त्वतः -- हजारों मनुष्यों में कोई एक सिद्धि के लिए प्रयत्न करता है। प्रयत्न करने वालों में, प्रयत्न करके लक्ष्य तक पहुँचने वालों में, कोई एक मुझे सही ढंग से जान पाता है।

भगवान को तलस्पर्शी रूप से जानना किसके लिए सम्भव है? कृष्ण कहते हैं: "हजारों मनुष्यों में से कुछ सिद्धि के लिए प्रयत्न करते हैं। इस तरह योग में लगकर उसमें लक्ष्य तक पहुँचने वाले अनेकों में से 'किसी एक ने मुझे सचमुच समझा है' ऐसा कहना भी कठिन है।" अपरोक्ष ज्ञान में ऊँचाई पर पहुँचे सिद्ध पुरुषों में भी भगवान को तत्त्वतः जानने वाले बहुत विरल होते हैं।`,
  "7.4": `भूमिः आपः अनलः वायुः खम् मनः बुद्धिः एव च।

अहङ्कारः इति इयम् मे भिन्ना प्रकृति अष्ट धा-- मिट्टी, पानी, आग, हवा, आकाश, मन, बुद्धि [सुप्त-प्रज्ञा से युक्त], और अहंकार -- इस तरह मेरे अधीन यह जड़ प्रकृति आठ प्रकार की है।

यह श्लोक भगवान की संसार-सृष्टि के विराट रूप को समष्टि रूप में बताता है। जैसा हमें ज्ञात है, सृष्टि से पहले यह सम्पूर्ण जगत सूक्ष्म रूप में उस भगवान के उदर में स्थित था, फिर भगवान ने इस सृष्टि का निर्माण किया। इस तरह पहले निर्माण हुआ यह जड़ प्रकृति। यहाँ पंचभूत (मिट्टी, पानी, आग, हवा, आकाश) के साथ मन, बुद्धि और अहंकार -- ये मिलाकर आठ प्रकार। यह पूरा स्थूल संसार मिट्टी पानी आग हवा आकाश का ही विकार है। इसलिए इस संसार में रहने वाले समस्त जड़ पदार्थों का मूल द्रव्य पंचभूत हैं।

यहाँ हमारे सामने एक प्रश्न आ सकता है -- पंचभूतों की सृष्टि में आकाश की सृष्टि का अर्थ क्या है? मूलतः आकाश की सृष्टि वास्तविक नहीं बल्कि सापेक्ष है। अंतरिक्ष (Space) पहले से ही था। उसमें भगवान अपने रूप को प्रकट करते हैं, यही आकाश-सृष्टि है। रंगहीन अंतरिक्ष में "आँख से न दिखने वाले नीले रंग का (Ultraviolet) आकाश निर्मित हुआ (इसे तेरहवीं शताब्दी में मध्वाचार्य ने उल्लेख किया है)। वहाँ कम्पन होकर उससे हवा उत्पन्न हुई। हवा के कम्पन से आग और आग से पानी की सृष्टि हुई। यह पानी दृढ़ होकर धीरे-धीरे मिट्टी में विकसित हुआ। इस तरह इन पंचभूतों से अनंत वस्तुओं का निर्माण हुआ।

पहले पंचभूतों से अन्नमयकोश की सृष्टि; फिर आग, हवा, आकाश से प्राणमयकोश की सृष्टि; इस प्राणमयकोश के भीतर मन और बुद्धि से बने मनोमयकोश की सृष्टि; फिर हमारी स्मरण-शक्ति के अहंकार-तत्त्व (awareness of self, चित्त, चेतन) से बने विज्ञानमयकोश की सृष्टि हुई। यहाँ मन की सृष्टि होने का अर्थ है मन के अभिमानी देवता की सृष्टि होना; भूमि की सृष्टि होने का अर्थ है इस जड़ भूमि के साथ भूमि के अभिमानी देवता की सृष्टि होना। उसी तरह वायु की सृष्टि होने पर वहाँ वायु के साथ उनचास देवताओं की सृष्टि हुई, ऐसा अर्थ है। जैसा हमें ज्ञात है, भूमि को घेरने वाली वायु की परतें उनचास हैं। भूमि से अलग-अलग दूरी पर हवा के अलग-अलग दबाव के अनुसार यह विभाजन है, जिसे अपने-अपने अभिमानी देवता नियमित रूप से चलाते हैं। (भारद्वाज संहिता में इस बारे में और विमान-तकनीक के बारे में सम्पूर्ण विवरण मिल सकता है)। इस तरह भगवान के अधीन आठ रूप की अक्षर-प्रकृति बनी। इस आठ प्रकार के संसार में अष्टाक्षर द्वारा प्रतिपादित होकर भगवान भरे हुए हैं।

नाद-सृष्टि की पहली सृष्टि ओंकार है। ओंकार में आठ अक्षर हैं। नाभि से निकलकर उच्चारण के अंत तक कुल आठ अक्षर हैं -- अकार, उकार, मकार, नाद, बिंदु, कला, शांत, अतिशांत। इस तरह आठ अक्षरों से प्रतिपादित होकर विश्व, तैजस, प्राज्ञ, तुरीय, आत्म, अंतरात्म, परमात्म और ज्ञानात्म नामक आठ रूपों में भगवान इस अष्टविध प्रकृति में भरे। इस तरह पूरा संसार आठ प्रकार में विकसित हुआ।

[अध्यात्म में हर संख्या के पीछे एक वेदांत है। सृष्टि-प्रक्रिया में आठ के महत्व को हमने यहाँ देखा। बन्नंजे जी की "अंकेयल्लि अध्यात्म" (संख्याओं में अध्यात्म) नामक छोटी कृति इस पर और प्रकाश डालती है।]`,
  "7.5": `अपरा इयम् इतः तु अन्याम् प्रकृतिम् विद्धि मे पराम् ।

जीवभूताम् महाबाहो यया इदम् धार्यते जगत्-- इन दो प्रकृतियों में यह निचले स्तर की है। मेरे अधीन दूसरी प्रकृति इससे बढ़कर है। वही चेतन प्रकृति है, श्रीतत्त्व है, जो सभी जीवों को सदा-सर्वदा आसरा देती है। हे महावीर, उसी ने इस जगत को धारण किया हुआ है।

अचेतन सृष्टि के लिए एक निमित्त कारण और एक उपादान कारण होता है। जड़ प्रकृति संसार के लिए उपादान कारण है और उसके माध्यम से भगवान समस्त सृष्टि के निमित्त कारण हैं। चेतन में दो प्रकार हैं -- चर और अचर। अचर चेतन (जैसे पेड़-पौधे) की सृष्टि के लिए ऊपर कहे अनुसार एक निमित्त कारण और एक उपादान कारण पर्याप्त है। परंतु चेतन में चर चेतन (अंडज और जरायुज) की सृष्टि के लिए एक निमित्त कारण पर्याप्त नहीं है। यहाँ दो निमित्त कारण चाहिए -- एक पिता, एक माता। दो चेतन से एक चेतन की सृष्टि होती है। इसकी शुरुआत मूल सृष्टि में ही हो गई थी। इस तरह दो चेतन और एक जड़ मिलकर यह समस्त सृष्टि बनी है। पहले कहे अनुसार वस्तुतः प्रलय-काल में पूरा संसार भगवान के उदर में ही था। इसलिए वे ही पिता, वे ही माता। फिर भी इस संसार में जीव-जगत की सृष्टि के लिए आगे जैसे पिता-माता नामक दो चेतन चाहिए, वह व्यवस्था भगवान ने सृष्टि के आरंभ में ही कर दी। संसार में जिस तरह जीव-सृष्टि की प्रक्रिया आगे बढ़ती है, उसी तरह आरंभ से ही वह व्यवस्था करने वाले भगवान हैं। यह उसी की निरंतरता है, यह सृष्टि।

इस श्लोक में कृष्ण कहते हैं "मैंने पहले जो प्रकृति बताई वह 'जड़ प्रकृति' है; परंतु उससे भिन्न और श्रेष्ठ एक और प्रकृति है" ऐसा। वही पूरे संसार को मातृ-स्थान देने वाली चित् प्रकृति है। वेद में कहा गया है कि जड़ प्रकृति 'अक्षर' है, उससे भिन्न चेतन-प्रकृति 'परमाक्षर' है। भगवान 'परतः-परमाक्षर' हैं। इस तरह भगवान और संसार के बीच माध्यम के रूप में श्रीतत्त्व (श्रीलक्ष्मी) है। इस कारण लक्ष्मी को लोकमाता कहते हैं। इस जगत की सृष्टि करते समय जड़ प्रकृति को उपादान कारण के रूप में प्रयोग किया, तो उस जड़ शरीर (पिंडांड) में जीव की सृष्टि के लिए जीवभूता चेतन-शक्ति से युक्त चित् प्रकृति को कारण के रूप में प्रयोग किया भगवान ने। इस तरह जगत के पहले जीव चतुर्मुख की सृष्टि श्रीतत्त्व से हुई। इस तरह जगत के मूल में ही प्रकृति और पुरुष नामक दो प्रकार का चेतन हम देखते हैं। जीव-स्वरूप में भी नर और मादा नामक दो भेद हैं, यह सृष्टि के आरंभ से ही ज्ञात होता है। पुरुष और प्रकृति नामक भगवान के दो मुख से यह सृष्टि हुई। जड़ में लिंग-भेद नहीं है, फिर भी हम कुछ जड़ वस्तुओं को मादा और कुछ को नर के रूप में पहचानते हैं। यह उस वस्तु के अभिमानी देवता के लिंग के अनुसार पहचाना गया है। उदाहरण के लिए नदी -- नदी के अभिमानी देवताओं में अधिकतर स्त्रीलिंग हैं; उसी तरह भूमि की अभिमानी देवता भी स्त्री हैं। इस कारण नदी को और भूमि को हम माता के रूप में देखते हैं।

इस तरह जगत की मूल बात भगवान (पुरुष) और उनके अधीन जड़ प्रकृति और चित् प्रकृति हैं। ये सदा नित्य हैं -- कभी नाश न होने वाले। आकार (विकृति) का नाश होता है, परंतु मूल द्रव्य का उत्पत्ति-नाश जगत में नहीं है। इसलिए ये क्षर-रहित (अ-क्षर) हैं। इन तीनों से 'क्षर' रूपी संसार की सृष्टि होती है।`,
  "7.6": `एतत् योनीनि भूतानि सर्वाणि इति उपधारय ।

अहम् कृत्स्नस्य जगतः प्रभवः प्रलयः तथा-- इन दोनों प्रकृतियों से ही सारे जीव बने हैं, ऐसा जानो। मैं ही जगत के सारे जन्म-मरणों का कारण हूँ।

जड़ प्रकृति और चित् प्रकृति ही पूरे संसार के समस्त जीव-जगत के मूल कारण हैं। भगवान जीव-जगत के पीछे पिता के रूप में, लक्ष्मीदेवी माता के रूप में खड़े होकर इस संसार की सृष्टि करते हैं। माता के गर्भ में बढ़ने वाले भ्रूण की तरह जड़ प्रकृति विकार को प्राप्त हुई। इस तरह चित् प्रकृति ने जड़ प्रकृति को रूप दिया, रूप देकर धारण किया, वही संसार बना।

भगवान की शक्ति के आधान से, प्रेरणा से, जड़ और चित् प्रकृति के माध्यम से इस संसार के जन्म के लिए भगवान जैसे कारण हैं, वैसे ही पूरे संसार का प्रलय भी भगवान ही हैं। कृष्ण कहते हैं "समस्त जगत की उत्पत्ति का मूल कारण मैं हूँ, जगत के संहार का कारण भी मैं हूँ" ऐसा। इस संसार के जन्म से पहले जो थे, जन्म का कारण, संहार का कारण, संहार के बाद रहने वाले वे भगवान हैं।

हममें से कुछ लोग पूछते हैं -- जड़ प्रकृति की नियामक शक्ति चेतन प्रकृति है, चेतन प्रकृति को प्रेरित कर सृष्टि-संहार में लगाने वाला 'पुरुष' नामक भगवान है। तो इस भगवान को नियंत्रित करने वाला कौन है? इसका उत्तर कृष्ण अगले श्लोक में देते हैं।`,
  "7.7": `मत्तः परतरम् न अन्यत् किंचित् अस्ति धनंजय ।

मयि सर्वम् इदम् प्रोतम् सूत्रे मणिगणाः इव -- धनंजय, मुझसे बढ़कर कुछ भी नहीं है। सब कुछ मुझमें ही गुँथा हुआ है -- जैसे धागे में मणियों की माला।

कृष्ण कहते हैं: "मुझसे परे, मुझसे बड़ा, मुझसे भिन्न कोई दूसरी वस्तु नहीं है" ऐसा। चित् प्रकृति, जड़ प्रकृति, इनसे देह धारण करने वाला जीव-जगत, रहने वाला ब्रह्मांड, यह पिंडांड -- सब कुछ भगवान में धागे में मणियों की तरह गुँथा हुआ है। पूरे विश्व को, जीव-जगत को गूँथने वाला सूत्र वही भगवान है।`,
  "7.8": `रसः अहम् अप्सु कौंतेय प्रभा अस्मि शशि सूर्ययोः ।

प्रणवः सर्ववेदेषु शब्दः खे पौरुषम् नृषु -- कौंतेय, पानी में रस होना मुझसे है [पानी में रहकर रस का स्वाद चखाने से 'रस' नामक]। चंद्र-सूर्य में प्रकाश होना मुझसे है [चंद्र-सूर्य में रहकर प्रकाशित करने से 'प्रभा' नामक]। सारे वेदों में 'ओंकार' सार होना मुझसे है [सारे वेदों में रहकर मैं ही स्तुति करने से 'प्रणव' नामक]। आकाश में ध्वनि उठना मुझसे है [आकाश में ध्वनि उत्पन्न करने से 'शब्द' नामक]। पुरुषों में वीर्य मुझसे है [पुरुषों में रहकर वीर्य देने से 'पौरुष' नामक]।

भगवान ने इस संसार की सृष्टि की, फिर संसार में प्रवेश किया, ऐसा शास्त्र कहते हैं। यहाँ हमें थोड़ा भ्रम होता है -- "भगवान सर्वव्याप्त हैं, वे प्रवेश करते हैं इसका अर्थ क्या?" यह हमारा प्रश्न है। यह समझने के लिए सर्वव्याप्त भगवान के अनंत रूप होने की बात भी हमें ज्ञात होनी चाहिए। वे व्याप्त एक रूप में सर्वत्र हैं, और एक-एक वस्तु में विशेष शक्ति देने वाले, विशेष शक्ति प्रकट करने वाले एक विभूति-रूप में वहाँ प्रवेश करते हैं। इस तरह एक वस्तु में ही भगवान के अनेक रूप हो सकते हैं। एक वस्तु को वह शक्ति-विशेष देने वाले भगवान के रूप को उनका विभूति-रूप कहते हैं -- यह उनकी लीला है। भगवान विभूति-रूप में एक वस्तु में प्रवेश कर उस वस्तु में एक शक्ति-विशेष प्रकट करते हैं -- यही विभूति-विज्ञान है।

इस श्लोक के आरंभ में कृष्ण पंचभूतों में बहुत महत्वपूर्ण पानी में अपनी विभूति का वर्णन करते हैं। हमारी उपासना में भगवान को पानी में उपासना करना बहुत विशेष है। हर अनुष्ठान (स्नान, अर्घ्य, तर्पण आदि) के लिए भी पानी चाहिए। "अर्घ्यं समर्पयामि। गंधाक्षतं समर्पयामि। पुष्पं समर्पयामि। नैवेद्यं समर्पयामि। ताम्बूलं समर्पयामि।" ऐसे समर्पण करना एक तरह से पानी ही समर्पित करना है! इस तरह जब कुछ न हो तो सबके प्रतिनिधि के रूप में हम पानी अर्पित करते हैं, क्योंकि भगवान की सृष्टि के विस्तार के लिए पानी मूल द्रव्य है। इसे भक्ति से अर्पित करें तो सब कुछ अर्पित करने के समान है।

यहाँ कृष्ण कहते हैं "रसः अहम् अप्सु कौंतेय" ऐसा। अर्थात् "रस नामक होकर पानी में मैं रस हूँ" ऐसा। संस्कृत में रस का अर्थ सारभूत, बहना आदि अनेक अर्थ हैं। बहने की शक्ति पानी का विशिष्ट गुण है। बहने की शक्ति के रूप में 'हरि' पानी में बैठे होने से पानी को वह शक्ति मिली। उपासना में यह ज्ञान बहुत महत्वपूर्ण है। शास्त्रीय रूप से गुह्य भाषा में पानी को 'विष्णुः' कहते हैं। "विशंति अत्र इति विष्णुः" -- अर्थात् जिसके भीतर जाकर बाहर आना संभव है वह विष्णुः।

भगवान पानी में रस (स्वाद) बनकर बैठे। हमें स्वाद का अनुभव देकर, वे पानी में रस बनकर न बैठे होते तो हमें जीभ होते हुए भी कोई उपयोग न होता। हर वस्तु में जो सारभूत ऐसी असाधारण शक्ति है, वह उस भगवान की विभूति है। वे रसः हैं -- 'र' का अर्थ आनंद, 'स' का अर्थ ज्ञान -- इसलिए रसः नामक भगवान ज्ञानानंद-पूर्ण हैं।

पानी के बाद कृष्ण सूर्य और चंद्रमा का उदाहरण लेते हैं। कृष्ण कहते हैं "प्रभा अस्मि शशि सूर्ययोः" ऐसा। अर्थात् "सूर्य-चंद्र में प्रभा नामक होकर प्रकाशित करने वाला मैं हूँ।" हमें प्राण-शक्ति सूर्य और चंद्रमा से प्रवाहित होती है। मनुष्य के जीवन के लिए विशेष रूप से सौर-शक्ति कारण है, फिर भी सारी वनस्पतियों का चंद्रमा से विशेष संबंध है। इस कारण वनस्पति-विशेषज्ञ यह अध्ययन करके कि किस पेड़ में किस तरह की शक्ति चाँदनी से उत्पन्न होती है, चंद्रमा की गति के अनुसार वनस्पतियों को काटते थे। पहले के समय में घर बनाने में प्रयोग होने वाली लकड़ी को चंद्रमा की गति के अनुसार अध्ययन कर काटा जाता था। इसे जाने बिना पेड़ काटा जाए तो वह लकड़ी टिकाऊ नहीं होती। भगवान चंद्र-सूर्य से निरंतर शक्ति प्रवाहित करते रहने से यह जीव-लोक जीवित है। सूर्य-चंद्र की शक्ति-पात न होती तो हमारा जीवन ही नहीं होता। इसीलिए भगवान को 'केशव' कहते हैं। सूर्य-चंद्र की किरणों में रहकर, उस प्रकाश के माध्यम से, धूप और चाँदनी के माध्यम से हमें जीवन देने वाले केशव हैं। चंद्रमा के प्रकाश में, सूर्य के प्रकाश में वह प्रकाशित करने वाली शक्ति देकर, उस प्रकाश में प्रकाश बनकर 'प्रभा' शब्द-वाच्य भगवान बैठे हैं। 'प्र' का अर्थ अत्यंत श्रेष्ठ, 'भा' का अर्थ ज्ञानानंदमय। भगवान ज्ञानानंदमय प्रकाश बनकर सूर्य-चंद्र में रहकर जीव-जगत को निरंतर प्राण-शक्ति प्रवाहित करते रहते हैं।

कृष्ण आगे कहते हैं: "सारे वेदों में, वेद शब्द-वाच्य होकर मैं भरा हूँ" ऐसा। 'वेद' का अर्थ है 'जागरूकता देने वाला।' सबको जागरूकता देने वाले भगवान हैं। स्वयं पूर्ण होकर सबको ज्ञान देने वाले, सर्व-शब्द-वाच्य होकर सारे वेदों में भगवान बसे हुए हैं। वेद का अर्थ जानने वाले का जीवन सदा मंगलमय होता है। ऐसे वेद का सार 'ओंकार' है -- वही प्रणवः है।

यहाँ हमें एक बात समझनी चाहिए। ओंकार को सारे वेदों का सार कहते हैं, यह कैसे? वेद अनेक हैं। ऋग्वेद में 24 शाखा, यजुर्वेद में 101 शाखा, सामवेद में 1000 शाखा, अथर्ववेद में 12 शाखा -- इस तरह कुल 1137 संहिताएँ हैं, साथ में उनके ब्राह्मण, आरण्यक, उपनिषद। इस तरह वेद का अर्थ है विपुल वैदिक वाङ्मय। इतने वेद होते हुए भी मूलतः वेद में मुख्य रूप से तीन विभाग हैं -- पद्य-रूप (ऋग्वेद), गद्य-रूप (यजुर्वेद) और गान-रूप (सामवेद)। इन तीन वेदों के तीन अक्षर लेकर बना है ओंकार। "ओंकार को सारत्व देकर, सारभूत होकर 'प्रणवः' शब्द-वाच्य होकर मैं ओंकार में स्थित हूँ" ऐसा कहते हैं कृष्ण। यह बहुत विचार-गर्भित बात है। प्राचीनों ने तीन वेदों को निचोड़कर उसके सार तीन वर्गों का एक सूक्त बनाया -- वही पुरुषसूक्त है। इस कारण वेद-सूक्तों में पुरुषसूक्त सबसे श्रेष्ठ सूक्त है। इस सूक्त को फिर निचोड़कर तीन पादों की गायत्री मंत्र (तत्सवितुर्वरेण्यं भर्गो देवस्य धीमहि धियो योनः प्रचोदयात्) बनी। "तत् सवितुर् वरेण्यम्" ऋग्वेद से संबंधित है, "भर्गो देवस्य धीमहि" यजुर्वेद से संबंधित है, "धियो यो नः प्रचोदयात्" सामवेद से संबंधित है। इस तरह तीन वेदों का सार गायत्री के तीन पादों वाले एक मंत्र में है। इसलिए गायत्री मंत्र को 'वेदमाता' कहते हैं। इस गायत्री से रस निकालने पर तीन पादों से तीन पदों वाली व्याहृति "भूः भुवः स्वः" बनती है। इन तीन पदों का सार तीन अक्षर (अ, उ, म) का ओंकार है।

ओंकार में 'अ'कार ऋग्वेद से, 'उ'कार यजुर्वेद से और 'म'कार सामवेद से संबंधित है। ऋग्वेद "अग्निमीळे पुरोहितं यज्ञस्य देवमृत्विजम्।" ऐसा 'अ' कार से शुरू होता है और "...समानी व आकूतिः समाना हृदयानि वः। समानमस्तु वो मनो यथा वः सुसहासति॥" ऐसा 'इ'कार में समाप्त होता है। वहाँ से आगे यजुर्वेद "इषे त्वोर्जे त्वा.." ऐसा 'इ'कार से शुरू होकर "...समुद्रो बंधुः" ऐसा 'उ'कार में समाप्त होता है। इस तरह ओंकार का 'अ'कार और 'उ'कार ऋग्वेद और यजुर्वेद को पूर्ण रूप से सूचित करने वाला संक्षेपण (abbreviation) रूप है। यहाँ से आगे सामवेद। सामवेद "अग्न आ याहि......" ऐसा 'अ'कार से आरंभ होकर "बृहस्पतिर्दधातु" ऐसा 'उ'कार में समाप्त होता है। इसलिए यहाँ 'म'कार नहीं आया। परंतु जैसा हमें ज्ञात है, सामवेद नाद-रूप में है। ओंकार में भी 'म' नाद-रूप में बाहर निकलने वाला अक्षर है -- वह संगीत है। इस तरह ओंकार वेद का संक्षेपण-रूप बीजाक्षर है। यह हमारे लिए वेद पहचानने का मार्गदर्शक है। इसलिए भगवान की स्तुति करने वाले मंत्रों में यह सबसे श्रेष्ठ है। इससे बड़ा स्तुति करने वाला शब्द इस संसार में नहीं है।

किसी मंत्र के अंत में कहे जाने वाले ओंकार को व्याकरण की परिभाषा में 'प्रणवः' कहते हैं। आदि से अंत तक समस्त नाम का प्रतिपाद्य 'भगवान' है यह दिखाने के लिए ओंकार का आदि-अंत में उच्चारण करते हैं। इस कारण मंत्र के आदि में और अंत में प्रयोग होने वाले ओंकार को कभी अलग से नहीं कहना चाहिए। उदाहरण के लिए विष्णुसहस्रनाम के अंत में "सर्वप्रहरणायुधः ओं नमः इति" ऐसा न कहकर "सर्वप्रहरणायुधोऽं नमः इति" ऐसा कहना चाहिए। आयुधः में जो विसर्ग (ः) है उसे हटाकर वहाँ 'ओं' जोड़कर उसे मिलाकर कहना चाहिए।

"वेद के सारभूत 'प्रणवः' मैं हूँ" ऐसा कहते हैं कृष्ण। प्रणवः का विस्तार होने पर व्याहृति, व्याहृति का विस्तार होकर गायत्री, गायत्री का विस्तार होकर पुरुषसूक्त, फिर तीन वेद, वहाँ से समस्त वेद। इस तरह प्रणव में, व्याहृति में, पुरुषसूक्त में, समस्त वेदों में भगवान बसे हुए हैं।

वेद के शब्दों से ही उत्पन्न हुए संसार के सारे शब्दों में, सारी लौकिक ध्वनि में भरे हुए भगवान ने आकाश में अनंत शब्दों को, अनंत ध्वनियों को उत्पन्न किया। हमें शब्द से अनंत अनुभव देकर, उस शब्द को ग्रहण करने और ग्रहण कर पुनः उच्चारण करने की विशेष शक्ति दी। ज्ञान के माध्यम से इस शब्द नामक भगवान को जानने की विशेष शक्ति मनुष्य को भगवान की विशेष देन है। जीव-लोक को नाना प्रकार का पौरुष देने वाले भगवान 'पुरुष' शब्द-वाच्य होकर मनुष्यों के बहु-विध पौरुष में भरे।

[अगले श्लोक पर जाने से पहले पिछले श्लोक में हमने संक्षेप में देखे 'ओंकार' के बारे में एक बार और अधिक विवरण देखें। पहले कहे अनुसार समस्त वेद में हम जो उपासना करते हैं भगवान के सारे गुणों को ओंकार बताता है। ओं(तौ) कहने का एक अखंड अर्थ है। ओंकार 'अव' या 'ऊयि' नामक दो धातुओं से बना है। "अवति इति ओं" -- यहाँ 'अवति' शब्द के अनेक अर्थ-विशेष हैं। 'अव व्याप्तौ' धातु; अवति का अर्थ है सब जगह भरा हुआ। इसलिए ओं का अर्थ है सर्वगत। 'अव' का अर्थ है ज्ञान। 'अवति' का अर्थ है सब कुछ जानने वाला; इसलिए ओं का अर्थ है सर्वज्ञ। 'अव सामर्थ्ये' यह एक और धातु है; इसलिए अवति का अर्थ है सर्वसमर्थ (omnipotent)। इस तरह भगवान सर्वसमर्थ, सर्वगत, सर्वज्ञ नामक तीन प्रमुख पक्षों को ओंकार बताता है। यह भगवान को पहचानने के तीन मूलभूत गुण हैं। जीव 'अणु' है तो भगवान सर्वगत हैं; जीव अल्पज्ञ है तो भगवान सर्वज्ञ हैं; जीव अल्प-सामर्थ्य वाला है तो भगवान सर्वसमर्थ हैं। इस तरह अपने से भिन्न वह शक्ति कितनी भिन्न है, यह ओंकार बताता है।

'अव प्रवेशे' नामक धातु -- यहाँ अवति का अर्थ है 'प्रवेश करता है।' भगवान सर्वगत हैं, इसलिए वे सबके भीतर भी (omnipresent) बाहर भी हैं। इसे नारायण-सूक्त में "अंतर् बहिश्च तत् सर्वं व्याप्य नारायण स्थितः" ऐसा कहा है। 'अव वधे' नामक एक और धातु है। अवति का अर्थ है रक्षा करने वाला यह एक अर्थ, संहार करने वाला यह दूसरा अर्थ। इसलिए ओं का अर्थ है सर्व-रक्षक, सर्व-संहारक शक्ति। "भगवान हममें रहने वाले अज्ञान का, हममें रहने वाले दुःख का, हममें रहने वाले दोष का संहार करने वाले हैं -- सर्व-दोष-नाशक।" यह हमें ओंकार में 'संहारक-शक्ति' भगवान की उपासना करते समय ज्ञात होनी चाहिए। समष्टि रूप से 'अव' धातु से उत्पन्न ओं -- भगवान सर्व-संहारक, सर्व-दोष-निवारक, सर्वांतर्यामी, सर्वांतर्नियामक, सर्वज्ञ, सर्वसमर्थ, इस तरह हमें उपासना करने योग्य भगवान के मुख्य गुणों को बताता है। इसका विवरण ही समस्त वेद में आता है।

दूसरी धातु 'ऊयते इति ओं'। जगत जिसमें ओत है वह ओं है। अर्थात् पूरा जगत जिसमें आश्रित है वह 'ओंकार' वाच्य भगवान है। सारे गुण जिसमें ओत (गुँथे हुए) हैं वह ओं है। अर्थात् भगवान सर्वाधार-सर्वगुणपूर्ण हैं।

ओंकार को समष्टि रूप से देखने के बाद उसे अलग-अलग अक्षर में विभाजित कर उसमें रहने वाले तीन अक्षर (अ, उ, म) क्या कहते हैं यह देखें। प्रणव शब्द का एक-एक अक्षर ओंकार के एक-एक अक्षर की व्याख्या के रूप में है। ओंकार का पहला अक्षर 'अ'। 'अ' का अर्थ है अधिक, सबसे अधिक भगवान 'अ'। इसे प्रणव का 'प्र' अक्षर बताता है। 'प्र' का अर्थ है प्रकृष्ट -- सबसे प्रकृष्ट अनंत शक्ति भगवान 'अ'। ओंकार का दूसरा अक्षर 'उ'। 'उ' का अर्थ है उत्तम, ज्ञानानंद से भरा उन्नत। इसे प्रणव का 'ण' अक्षर बताता है। ज्ञानानंद की आत्म-शक्ति। भगवान सर्व-समर्थ हैं -- इसलिए ज्ञानानंद-स्वरूप भगवान 'उ'। ओंकार का तीसरा अक्षर 'म'। 'म' का अर्थ है ज्ञान-स्वरूप। इसे प्रणव का 'व' अक्षर बताता है। 'व' का अर्थ है ज्ञान -- वह सर्वज्ञ अर्थ देता है। इस तरह ओंकार के एक पक्ष को 'प्रणवः' बताता है।

उपनिषद में कहा गया है "नेति नेति आत्मा अग्रह्यः न हि गृह्यते" -- अर्थात् भगवान को पूरी तरह जानना असंभव है, यह जानना ही सबसे पहले हमें भगवान के बारे में जानना चाहिए। इसे ओंकार बताता है। यहाँ 'अ' का अर्थ है नहीं या न हो। भगवान नहीं, भगवान न हों! अर्थात् भगवान को पूरी तरह जानना संभव नहीं, क्योंकि हम जिस वस्तु को जानते हैं उसमें जो है वह उनमें नहीं है। हमें त्रिगुणात्मक संसार का ही परिचय है, परंतु भगवान त्रिगुणातीत हैं। त्रिगुणात्मक हमारा मन त्रिगुणातीत को ग्रहण नहीं कर सकता। भगवान में कोई दोष नहीं है। वे सर्व-गुण-पूर्ण हैं। भगवान हमारी समझ से परे हैं।

भगवान 'उ' हैं। हमारा मन जिस ऊँचाई तक चढ़ सकता है उससे भी उन्नत वस्तु। हमारा मन उस ऊँचाई तक चढ़ने में असमर्थ है। फिर भी वे 'म' हैं -- अर्थात् उन्हें जाना जा सकता है! अर्थात् भगवान समुद्र के समान हैं। हम पूरा समुद्र लाकर अपने घर के बर्तन में नहीं भर सकते। परंतु अपने बर्तन में जितना भर सकते हैं उतना पानी भरकर ला सकते हैं। उसी तरह भगवान को हम पूरी तरह ग्रहण नहीं कर सकते, परंतु अपनी-अपनी सामर्थ्य के अनुसार उन्हें जान सकते हैं। ओंकार "भगवान को पूरी तरह जानना असंभव है, परंतु अपनी-अपनी योग्यता के अनुसार भगवान को जानने का प्रयत्न करो" यह वेद का संदेश हमें बताता है। भगवान का किस तरह अनुसंधान करना चाहिए यह ओंकार बताता है। भगवान 'अ' अर्थात् वे अतीत हैं -- जो सृष्टि से पहले था वह 'अ'। हमारे उत्पन्न होने के बाद रहने वाले भगवान 'उ'; सब कुछ नष्ट होने के बाद रहने वाले भगवान 'म'। तीनों काल में एकरूप रहने वाले भगवान ओं।

भगवान 'अ' अर्थात् भूः (भूमि); वे 'उ' -- भूमि के ऊपर रहने वाला अंतरिक्ष (भुवः); वे 'म' अर्थात् ज्ञान-प्रद स्वर्ग (स्वः)। तीनों लोक को नियमित करने वाली शक्ति भगवान ओं।

हमारी तीन अवस्थाओं -- 'अ'-जागृति, 'उ'-स्वप्न, 'म'-निद्रा को नियंत्रित करने वाली अनंत शक्ति भगवान ओं।

इस तरह समस्त वैदिक वाङ्मय भगवान में जिस गुण की उपासना करनी चाहिए यह बताता है; सर्वनाम-वाच्य भगवान में सर्वनाम जिस गुण को बताते हैं -- उन सबको इकट्ठा कर निचोड़कर सारयुक्त रूप से कहने वाला बीजाक्षर ओंकार है। यह भगवान की स्तुति में ही सबसे श्रेष्ठ स्तुति है। भगवान के अलावा किसी और को 'ओं' कहना असंभव है। [इस कारण सामान्यतः 'ओं' को कोई भी अपना नाम बनाकर उपयोग नहीं करता, नहीं करना चाहिए।]

ओंकार के पीछे रहने वाले सारे अर्थ-अनुसंधान के साथ जप करें तो यह अत्यंत प्रभावी होता है। सामान्यतः संन्यासी ओंकार जप करते हैं। गृहस्थ का निरंतर ओंकार जप करना उतना उचित नहीं है -- अधिकतम दस बार कर सकते हैं। संसार-जीवन बिताने वाली स्त्रियों का ओंकार जप न करना अच्छा है, क्योंकि ओंकार को पूरी तरह लगाकर, अर्थ-अनुसंधान से जप करने से वह मन पर बहुत बड़ा प्रभाव डालता है। यह एक तरह का ध्यान जैसा है। इससे मन मग्न होकर, सांसारिक जीवन में वैराग्य आने का खतरा है। परंतु संन्यासी को इस तरह की कोई समस्या नहीं है। वे अपना शरीर सह सके उतनी (12,000) बार ओंकार जप कर सकते हैं।]`,
  "7.9": `पुण्यः गंधः पृथिव्याम् च तेजः च अस्मि विभावसौ ।

जीवनम् सर्व भूतेषु तपः च अस्मि तपस्विषु -- मिट्टी में सुगंध मुझसे है [पवित्र होकर मिट्टी में रहकर गंध का अहसास देने से 'पुण्य' और 'गंध' नामक]। आग में जलाने की शक्ति भी मुझसे है [आग में रहकर जलाने वाला होने से 'तेजस्' नामक]। सारे जीवों में जीवन मुझसे है [सारे जीवों में रहकर जीवित करने से 'जीवन' नामक]। तपस्वियों में तपःशक्ति मुझसे है [तपस्वियों में रहकर तप की शक्ति देने से 'तपस्' नामक]।

कृष्ण कहते हैं: "पुण्यो गंधः पृथिव्यां -- ज़मीन में सुगंध मुझसे है" ऐसा। जो गंध हमारी नाक को आह्लाद देती है वह 'पुण्यगंध' है। यहाँ पुण्य का अर्थ है पवित्र या सुंदर। इस भूमि में, भूमि पर पैदा होने वाली हर वस्तु को सुगंध देने वाले 'पुण्य' नामक भगवान हैं। वे अपने विशेष रूप में 'गंध' नामक होकर उस वस्तु में समाए होने से वस्तु को एक विशेष गुण मिलता है। इस भूमि में उगने वाली लताएँ, वनस्पतियाँ, अनंत प्रकार के फूल, फल -- सब में वह विविधता-सुगंध उस भगवान से है। भूमि की अभिमानी देवता (पृथ्वी-देवता) में रहकर, पृथ्वी में गंध शब्द-वाच्य होकर गंध में बसे हुए हैं भगवान। ज़मीन सबका आसरा है, भगवान ज़मीन में स्थित होने से ज़मीन में उभरने वाली हर वस्तु भी एक-एक विशिष्ट सुगंध लेकर आती है। इस तरह भगवान ने अपनी सृष्टि में सौंदर्य-भरी विशिष्ट गंध का संसार ही हमारी नाक के सामने खोल दिया।

हिमालय की "फूलों की घाटी" (Valley of Flowers) में अनंत प्रकार के फूलों का संसार है। एक फूल की खुशबू दूसरे से अलग है। सारे पौधे एक ही मिट्टी से उगते हैं फिर भी भगवान ने एक-एक पौधे में एक-एक विशिष्ट गुण (exclusive quality) भरा। कुछ फूलों में हम पहचान सकें ऐसी सुगंध नहीं होती। सामान्यतः ऐसे फूल भगवान को अर्पित नहीं करते। इसका कारण है भगवान की पूजा की हर क्रिया आनंदमय होनी चाहिए, यह अनुसंधान। पूजा करते समय उस फूल की आह्लादकारी खुशबू नाक से टकराने पर हमें 'पुण्य' या 'गंध' नामक भगवान का बोध होना चाहिए।

पानी, सूर्य, चंद्र, आकाश और भूमि के बारे में बताने के बाद भगवान आगे बढ़कर भूमि में भगवान की आराधना का मुख्य प्रतिष्ठान अग्नि (विभावसु) में अपने विभूति-विज्ञान का वर्णन करते हैं। विभावसु भूमि में अग्नि की अभिमानी देवता हैं। ये अष्ट-वसुओं में [द्रोण, प्राण, ध्रुव, अर्क, अग्नि (विभावसु), दोष, वस्तु, द्युवसु] पाँचवें हैं। इनके अनेक नाम हैं -- वैश्वानर, वह्नि, जातवेद, हुताशन, पावक, अनल, दहन आदि। हमारे लिए भूमि में अग्नि भगवान का एक बहुत महत्वपूर्ण प्रतीक है। वेद भी शुरू होता है "अग्निमीळे पुरोहितं यज्ञस्य देवमृत्विजम्" ऐसा अग्नि के नाम से। ज़मीन में भगवान की पूजा के लिए अग्नि से बेहतर प्रतीक और कोई नहीं है। अग्नि प्रकाश का रूप है, अग्नि पवित्र है। दिया हुआ स्वीकार करने वाला भगवान का एकमात्र प्रतीक अग्नि है। यहाँ कृष्ण कहते हैं "तेजश्चास्मि विभावसौ" ऐसा। अर्थात् "इस अग्नि-देवता में दाहक, पाचक, प्रकाशक शक्ति बनकर, तेजस् बनकर मैं हूँ" ऐसा। बाहर के संसार में जलने वाली आग में भगवान हैं तो हमारी जीभ में बैठे अग्नि नामक भगवान (अग्नि-नारायण) हमें वाणी नामक प्रकाश देकर हमारे भीतर वाङ्मय के रूप में एक बड़ी रोशनी हैं। उसी तरह वैश्वानर बनकर हमारी पाचन-क्रिया को नियंत्रित करने वाले भी वे ही हैं। [इस बारे में अधिक विवरण आगे दसवें अध्याय में मिल सकता है।]

आगे कृष्ण कहते हैं: "वायु में भरकर हर जीव-जगत की साँस बनकर, जीव को साँस की शक्ति देकर मैं खड़ा हूँ" ऐसा। जीवन देने वाली अभिमानी देवता 'प्राण-देवता' हैं। हम दूसरी इंद्रियों का काम न करें तो भी जी सकते हैं। परंतु प्राण-शक्ति (साँस) काम न करे तो जीना संभव नहीं। नींद में हमारे बाकी तत्त्वाभिमानी देवता सो सकते हैं। परंतु प्राण-देवता सो जाएँ तो हम फिर जाग नहीं सकते! भगवान दिन-रात जीवन-प्रद प्राण में 'प्राण' बनकर खड़े होकर हमें जिलाते हैं।

पंचभूतों के बारे में बताने के बाद कृष्ण आगे मानस संसार के बारे में बताते हैं। मनोमय संसार में रहने वाले तपस्वी हैं (तप-सोच)। मन के गहरे चिंतन को तपस्या कहते हैं। इसकी अभिमानी देवता शिव हैं। हम जो बोलते हैं -- हमारे मन में जो विचार उभरते हैं वही। हमारे मन को ऐसी अद्भुत सोचने की शक्ति देकर, मनोमय-कोश में स्थित होकर हमें आनंद का अनुभव देने वाले वे भगवान हैं। इस तरह पंचभूतों में; अन्नमय-कोश से लेकर आनंदमय-कोश तक कैसे भगवान विभूति-रूप में खड़े हैं यह अद्भुत अध्यात्म-विज्ञान (divine science) इन दो श्लोकों (8 और 9) में कृष्ण ने बताया।

कृष्ण पिंडांड-ब्रह्मांड में खड़े होकर कैसे विभूति बनकर अलग-अलग वस्तु में विशिष्ट शक्ति भरते हैं, इस बात की संक्षिप्त उपासना हमने देखी। इस विभूति का विस्तार अगले अध्याय में फिर आता है। यहाँ कृष्ण ने इसे संक्षेप में कर समष्टि रूप से विभूति का अनुसंधान कैसा होना चाहिए यह बताया है।`,
  "7.10": `बीजम् माम् सर्वभूतानाम् विद्धि पार्थ सनातनम् ।

बुद्धिः बुद्धिमताम् अस्मि तेजः तेजस्विनाम् अहम्-- हे पार्थ, सारे जीवों का अविनाशी बीज [स्वभाव की अभिव्यक्ति का कारण होने से 'बीज' नामक] मैं हूँ, ऐसा जानो। जानने वालों की समझ मुझसे है [जानने वालों में रहकर समझ देने से 'बुद्धि' नामक]। पराक्रमियों की न हारने वाली शक्ति मुझसे है [पराक्रमियों में रहकर न हारने वाली शक्ति देने से 'तेजस्' नामक]।

कृष्ण कहते हैं: "बीजं मां सर्वभूतानां" ऐसा। अर्थात् "सारे जीवों का बीज मैं हूँ" ऐसा। बीज कहने पर हमें सामान्यतः याद आता है पेड़-पौधे का बीज। इस बीज को बोने पर वह पेड़ बनकर बढ़ता है। अर्थात् पेड़ के लिए बीज उपादान कारण है। क्या वैसे ही भगवान भी इस जगत के लिए उपादान कारण हैं? यह हमारे सामने आने वाला पहला प्रश्न है। इसे जानने के लिए पहले हमें 'बीज' शब्द के आध्यात्मिक अर्थ-विशेष (etymological meaning) को जानना चाहिए। बीज 'अंज' धातु से आया हुआ है। यहाँ 'वि' विसर्ग है। जो व्यंजन (व्यंजनात्) है वह अभिव्यंजन है। अर्थात् जिससे अभिव्यक्त हुआ वह बीज है। जो (मूल-वस्तु) था पर दिखता नहीं था, उसे दिखने योग्य आकार देने वाले वे भगवान हैं। अर्थात् सूक्ष्म रूप में भरे हुए इस अव्यक्त संसार को व्यक्त रूप देने वाले। इसलिए पूरे संसार में रहने वाले जीव-जगत को अभिव्यक्ति देने वाले जो हैं वे सर्व-भूतों के बीज हैं। इस जगत के पिता और माता दोनों हुए वे भगवान बीज हैं। प्रलय-काल में आँख से न दिखने वाले (अव्यक्त), सूक्ष्म रूप में रहे इस संसार को -- व्यक्त रूप देने वाले 'सर्व-भूतानां बीज' हैं।

जगत के समस्त जीव-जगत को अर्थात् चतुर्मुख-प्राण-गरुड़-शेष-रुद्र-इंद्र-काम-सारे देवता, मनुष्य, वनस्पतियाँ आदि। इस तरह समस्त जीव-कोटि को देह देकर, आकार देकर, अभिव्यक्ति देकर, पूरे जीव-जगत के पीछे पिता बनकर खड़े रहने वाले वे भगवान हैं। इस संसार में जो-जो जीव-जगत है, उस जीव-जगत में रहने वाले विशेष गुण-धर्म (exclusive quality) के पीछे कारण-पुरुष बनकर, व्यक्तित्व-विकास के (अभिव्यक्ति के) मूल कारण बनकर वे भगवान खड़े हैं। हमारे पास बीज की एक और कल्पना है -- वह पेड़ बनकर बढ़ने पर अपना आकार खो देता है। परंतु भगवान 'सनातन' हैं। यहाँ कृष्ण कहते हैं "मैं मैं ही रहकर संसार को आकार देता हूँ" ऐसा। अर्थात् भगवान कभी नहीं बदलते -- परंतु संसार बदलता है। भगवान संसार को अलग-अलग आकार की अभिव्यक्ति देते हैं। नई शक्ति देते हैं। इससे वह बदलता, नया रूप पाता रहता है। इसका कारण-पुरुष भगवान ही हर समय एकरूप में रहते हैं। इस तरह भगवान समस्त भूतों (जड़, चेतन, मुक्त) के बीज हैं और वे सनातन हैं।

कृष्ण कहते हैं "बुद्धिर्बुद्धिमतामस्मि तेजस्तेजस्विनामहम्" ऐसा। अर्थात् "बुद्धिमानों की बुद्धिमत्ता जो कुछ है वह मेरी देन है; वैसे ही तेजस्वियों के लिए तेजस्वी मैं हूँ।" ज्ञान-प्रद जीवों में भगवान ने ज्ञान-शक्ति को अभिव्यक्त किया। इससे वे ज्ञान-योगी बने और संसार में ज्ञान की परंपरा बढ़ाकर मुक्ति पाई। उसी तरह कर्म-प्रधान कर्म-योगियों के लिए तेजस् बनकर खड़े होकर आगे बढ़ाने वाले भगवान, उन्हें 'तेजस् बनकर' मुक्ति देने वाले हैं। बुद्धिः और तेजः भगवान के नाम हैं। ज्ञान के अपार और अनंत सागर भगवान 'बुद्धिः' हैं। देह-बल, आत्म-बल सब कुछ पूर्ण मात्रा में रखने वाले सर्व-समर्थ भगवान 'तेजः' हैं।`,
  "7.11": "बलम् बलवताम् च अहम् काम-राग-विवर्जितम् |\nधर्म-अविरुद्धः भूतेषु कामः अस्मि भरत-ऋषभ -- मैं बलवानों का काम-राग-रहित बल हूँ; और, हे भरतश्रेष्ठ, प्राणियों में जो धर्म के विरुद्ध नहीं ऐसी कामना, वह भी मैं ही हूँ।\n\nकृष्ण यहाँ चेतन में रहने वाले बल की बात करते हैं। मुण्डकोपनिषद् कहती है: \"नायम् आत्मा बलहीनेन लभ्यः\" -- कमज़ोर व्यक्ति भगवान को नहीं पा सकता। यहाँ जो बल कहा गया है वह शारीरिक बल नहीं, बल्कि भगवान की कृपा का बल, आत्मबल है। शास्त्राध्ययन से मनोबल बढ़ सकता है, परन्तु आत्मबल के बिना भगवान का दर्शन असम्भव है। स्वरूप-योग्यता का बल, साधना का बल, भक्ति का बल, शास्त्राध्ययन का बल, गुरु-अनुग्रह का बल -- यह सब भगवान ही देते हैं। साधारणतः बल के पीछे एक दोष छिपा रहता है -- बल आने पर बुरी कामना जन्म लेती है। परन्तु भगवान काम-राग-रहित बल-स्वरूप हैं। कृष्ण यहाँ कामना को त्यागने के लिए नहीं कह रहे -- \"भगवान को जानना है\", \"भक्तिपूर्वक शास्त्र पढ़ना है\" जैसी कामनाएँ आवश्यक हैं। जो कामना धारक-शक्ति बनकर खड़ी रहती है, वहाँ भगवान काम-विवर्जित होकर स्वयं खड़े हैं। यहाँ कृष्ण अर्जुन को 'भरतर्षभ' कहकर सम्बोधित करते हैं।",
  "7.12": "ये च एव सात्त्विकाः भावाः राजसाः तामसाः च ये |\nमत्तः एव इति तान् विद्धि न तु अहम् तेषु ते मयि -- जो भाव सात्त्विक, राजस अथवा तामस हैं, उन सबको मुझसे ही उत्पन्न जानो; परन्तु मैं उनके अधीन नहीं, वे मेरे अधीन हैं।\n\nसंसार अन्तरंग और बहिरंग दोनों रूपों में त्रिगुण से युक्त है। मिट्टी तमोगुण की, जल रजोगुण की और अग्नि सत्त्वगुण की प्रतीक है। सृष्टि के आरम्भ से ही ये तीनों गुण मिश्रित रूप में विद्यमान हैं, कहीं भी शुद्ध सत्त्व नहीं मिलता। इस त्रिगुणमय जगत् का निर्णय कर पाना मनुष्य के लिए अत्यन्त कठिन है, कि कौन-सा अच्छा है और कौन-सा बुरा। परन्तु कृष्ण कहते हैं -- \"त्रिगुण-रहित होकर भी यह तीनों गुण देने वाला मैं ही हूँ!\" प्रत्येक जीव को उसके स्वभाव के अनुसार आवश्यक गुण-प्रवृत्ति भगवान ही देते हैं; भगवान की प्रेरणा के बिना किसी की भी कोई क्रिया नहीं होती। भगवान त्रिगुणातीत हैं, वे त्रिगुण के नियन्त्रण में नहीं आते।",
  "7.13": "त्रिभिः गुण-मयैः भावैः एभिः सर्वम् इदम् जगत् |\nमोहितम् न अभिजानाति माम् एभ्यः परम् अव्ययम् -- इन तीनों गुणमय भावों से मोहित यह सम्पूर्ण जगत्, इनसे परे, अविनाशी मुझे नहीं जान पाता।\n\nसम्पूर्ण जगत् त्रिगुणों से मोहित है, और ये तीनों गुण सर्वत्र व्याप्त हैं, इसलिए हमारे लिए त्रिगुणातीत विचार असम्भव है। भगवान को जानने के लिए हमें इस त्रिगुण के चक्र से बाहर आना होगा। परन्तु बाहर आने का मार्ग क्या है? उत्तर अगले श्लोक में है।",
  "7.14": "दैवी हि एषा गुणमयी मम माया दुरत्यया |\nमाम् एव ये प्रपद्यन्ते मायाम् एताम् तरन्ति ते -- यह मेरी गुणमयी दैवी माया अत्यन्त दुस्तर है; जो केवल मुझ में शरण लेते हैं, वे ही इस माया को पार करते हैं।\n\nइस त्रिगुणमय माया की स्वामिनी स्वयं श्री लक्ष्मी भी तीन रूपों में हैं -- श्री, भू, दुर्गा। यह गुणमयी माता माया बनकर जगत् में व्याप्त है, और यह माया भी भगवान के अधीन है। इस माया के पर्दे को स्वयं हटाना हमारे लिए असम्भव है; इसलिए भगवान तक पहुँचने का एकमात्र मार्ग है भगवान में पूर्ण शरणागति। नौ प्रकार की भक्तियों में यह सर्वश्रेष्ठ है, इसे आत्मनिवेदन कहते हैं।",
  "7.15": "न माम् दुष्कृतिनः मूढाः प्रपद्यन्ते नर-अधमाः |\nमायया अपहृत-ज्ञानाः आसुरम् भावम् आश्रिताः -- दुष्कर्मी, मूढ़, नराधम, माया द्वारा जिनका ज्ञान हर लिया गया है, आसुरी भाव का आश्रय लिए हुए लोग, मेरी शरण नहीं लेते।\n\nदुष्कृतियों में दो प्रकार हैं -- प्रारब्ध-कर्म अथवा परिवेश के प्रभाव से पाप-मार्ग पर चलने वाले (जैसे कर्ण, अजामिळ), और स्वभाव से ही पापी (जैसे दुर्योधन, शकुनि)। स्वभाव से दुष्ट व्यक्ति कभी भगवान को स्वीकार नहीं करते, चाहे कितनी भी सद्बुद्धि दी जाए। परिवेश के प्रभाव से गिरे हुए सज्जनों के लिए सृष्टि में पुनः सही मार्ग पर लौटने की व्यवस्था है -- अजामिळ की कथा इसका उत्तम उदाहरण है, जो अपने पुत्र 'नारायण' को पुकारते हुए, यम-दूतों के स्थान पर विष्णु-दूतों को देखकर सुधर गया और अन्ततः मोक्ष पाया। करुणामय भगवान हमें दण्ड देने के बजाय क्षमा करके उद्धार करते हैं। यह व्यवस्था कभी नहीं बदलती कि पापियों को पाप का फल और पुण्यवानों को पुण्य का फल मिलता है। हरिकथामृतसार में दास लोगों ने सात्त्विक, राजस, तामस भक्तों का सुन्दर वर्णन किया है। कलियुग में माया का प्रभाव अधिक होता है, परन्तु यदि इसे पार कर मन भगवान की ओर मुड़ जाए तो वह सर्वोत्कृष्ट है।",
  "7.16": "चतुर्-विधाः भजन्ते माम् जनाः सुकृतिनः अर्जुन |\nआर्तः जिज्ञासुः अर्थ-अर्थी ज्ञानी च भरत-ऋषभ -- हे अर्जुन, चार प्रकार के पुण्यवान जन मेरी भक्ति करते हैं -- आर्त, जिज्ञासु, अर्थार्थी और ज्ञानी, हे भरतश्रेष्ठ।\n\nभगवान की ओर जाने का मार्ग एक सीधी रेखा के समान है। जो लोग भगवान की ओर पीठ करके चलते हैं, वे स्वभाव से दुष्कृती हैं; जो भगवान की ओर मुख करके चलते हैं, वे सुकृती भक्त हैं। इनमें चार प्रकार हैं। कष्ट में पड़ा व्यक्ति भगवान से राहत माँगता है -- यह आर्त-भक्ति है, जिसका उत्तम उदाहरण द्रौपदी और गजेन्द्र हैं, परन्तु इसमें एक समस्या है कि सुख आने पर हम भगवान को भूल जाते हैं। जिज्ञासु ज्ञान के लिए, अर्थार्थी ऐश्वर्य के लिए भगवान की उपासना करते हैं। चौथा और श्रेष्ठतम है ज्ञानी, जो बिना किसी कामना के, भगवान की महिमा जानकर स्वाभाविक रूप से उन्हें प्रेम करता है। एकभक्ति का अर्थ यह नहीं कि सब देवताओं और गुरुजनों की उपेक्षा कर केवल भगवान की पूजा करें -- ऐसा करना भगवान का अपमान होगा। सम्पूर्ण देव-परिवार सहित भगवान की उपासना ही सच्ची एकभक्ति है।",
  "7.17": "तेषाम् ज्ञानी नित्य-युक्तः एक-भक्तिः विशिष्यते |\nप्रियः हि ज्ञानिनः अत्यर्थम् अहम् सः च मम प्रियः -- इन चारों में ज्ञानी, नित्य-युक्त, एकभक्ति-सम्पन्न, सर्वश्रेष्ठ है; क्योंकि ज्ञानी को मैं अत्यन्त प्रिय हूँ, और वह भी मुझे अत्यन्त प्रिय है।\n\nचार प्रकार के भक्तों में ज्ञानी सबसे श्रेष्ठ है। वह बिना किसी फलाकांक्षा के, जानते हुए भगवान को स्वाभाविक रूप से प्रेम करता है। जैसा हमने पूर्व अध्यायों में देखा, हम जैसा करते हैं वैसा ही पाते हैं -- हम भगवान को जैसे देखते हैं, भगवान भी हमें वैसे ही देखते हैं। इसलिए ज्ञानपूर्वक, निष्काम, एकभक्तिमय ज्ञानी भगवान के अत्यन्त निकट रहता है।",
  "7.18": "उदाराः सर्वे एव एते ज्ञानी तु आत्मा एव मे मतम् |\nआस्थितः सः हि युक्त-आत्मा माम् एव अनुत्तमाम् गतिम् -- ये सभी उदार हैं ही, परन्तु ज्ञानी तो मेरा अपना आत्मा ही है, ऐसा मेरा मत है, क्योंकि वह युक्तात्मा होकर मुझमें ही सर्वोत्तम गति के रूप में स्थित है।\n\nकृष्ण कहते हैं कि भक्ति-मार्ग पर चलने वाले ये सभी उत्तम हैं, परन्तु ज्ञानी ही मेरे अत्यन्त निकट और आत्मीय है, क्योंकि ज्ञान-रहित भक्ति पूर्ण भक्ति नहीं होती। ज्ञानपूर्वक भक्ति करने वाला सीधे भगवान तक पहुँच जाता है। ज्ञानी स्वयं आर्त, जिज्ञासु अथवा अर्थार्थी भी हो सकता है (जैसे अर्जुन)। प्रह्लाद के जीवन की एक घटना इस बात को स्पष्ट करती है -- महान् ज्ञानी होते हुए भी प्रह्लाद नरसिंह-रूपी भगवान से अपने पिता हिरण्याक्ष के लिए क्षमा-याचना करते हैं, जिसमें कोई स्वार्थ दिखाई नहीं देता।",
  "7.19": "बहूनाम् जन्मनाम् अन्ते ज्ञानवान् माम् प्रपद्यते |\nवासुदेवः सर्वम् इति सः महात्मा सु-दुर्लभः -- अनेक जन्मों के अन्त में ज्ञानवान् व्यक्ति \"वासुदेव ही सब कुछ है\" यह जानकर मेरी शरण लेता है; ऐसा महात्मा अत्यन्त दुर्लभ है।\n\nजीवन में ज्ञानी बनना कोई सरल कार्य नहीं है। अनेक जन्मों की साधना, जिज्ञासा और अध्ययन से ज्ञान आता है, और ऐसा ज्ञानी स्वाभाविक रूप से भगवान की शरण लेता है। एक जन्म में की गई आध्यात्मिक साधना कभी नष्ट नहीं होती; हम जन्म लेते समय ही पूर्वजन्म की साधना का ज्ञान लेकर आते हैं। वासुदेव नाम का विशेष अर्थ है -- भगवान वासु हैं, अर्थात् स्वयं को छिपाने वाले; जब हम ज्ञान प्राप्त कर अपने जीव-स्वरूप को देख लेते हैं, तब वही छिपा हुआ भगवान देव के रूप में प्रकट होता है -- वासुदेव।",
  "7.20": "कामैः तैः तैः हृत-ज्ञानाः प्रपद्यन्ते अन्य-देवताः |\nतम् तम् नियमम् आस्थाय प्रकृत्या नियताः स्वया -- जिनका ज्ञान इस-उस कामना से हर लिया गया है, वे अपने-अपने स्वभाव के अनुरूप नियमों का पालन करते हुए अन्य देवताओं की शरण लेते हैं।\n\nमनुष्य के आध्यात्मिक मार्ग से भटकने का मूल कारण उसकी पागल कामनाएँ हैं। कामना के पीछे भागने पर मनुष्य अपनी एकभक्ति से दूर हो जाता है और जहाँ जिस देवता से इच्छा-पूर्ति सम्भव लगती है, वहाँ पूजा करने लगता है। एकभक्ति की उपासना से ऐसी क्षुद्र कामनाएँ कभी पूर्ण नहीं होतीं, क्योंकि भगवान भक्तों के धन को परखकर ही उनका उद्धार करते हैं। हर जीव की अपनी प्रकृति (स्वभाव तथा वंशानुगत संस्कार) होती है, जिसे कोई भी बदल नहीं सकता; इसीलिए संसार में समान स्वभाव नहीं मिलता, और सत्य को ग्रहण करने के लिए भी जीव को योग्यता चाहिए।",
  "7.21": "यः यः याम् याम् तनुम् भक्तः श्रद्धया अर्चितुम् इच्छति |\nतस्य तस्य अचलाम् श्रद्धाम् ताम् एव विदधामि अहम् -- जो-जो भक्त जिस-जिस रूप की श्रद्धापूर्वक अर्चना करना चाहता है, उस-उस की श्रद्धा को मैं ही अचल बना देता हूँ।\n\nमनुष्य श्रद्धा का स्वरूप है। जिस पर श्रद्धा जगती है, वही उसमें दृढ़ होती जाती है। भगवान और उनके देव-परिवार को मनुष्यों की तरह परस्पर द्वेष रखने वाला समूह समझना घोर मूर्खता है। भगवान एक ही शक्ति हैं, सदा अपने देव-परिवार सहित प्रकट होते हैं। इस एकशक्ति के भान के साथ किसी भी देवता की पूजा महापूजा बन जाती है; परन्तु उस भान को छोड़कर किसी एक देवता को ही सर्वस्व मानकर श्रद्धा दृढ़ करना पत्थर की मूर्ति को ही भगवान मान लेने जैसा है।",
  "7.22": "सः तया श्रद्धया युक्तः तस्य आराधनम् ईहते |\nलभते च ततः कामान् मया एव विहितान् हि तान् -- वह उस श्रद्धा से युक्त होकर उस देवता की आराधना करता है, और उससे वे कामनाएँ प्राप्त करता है जो वास्तव में मेरे द्वारा ही विहित हैं।\n\nजो लोग एकभक्ति का पालन न करते हुए किसी एक देवता को अचल रूप से पूजते हैं, वे भी फल पाते हैं। कृष्ण कहते हैं -- \"तुम जिसकी भी उपासना करो, अन्ततः फल देने वाला मैं ही हूँ।\" शास्त्रों में कहा गया है \"सर्व-देव-नमस्कारः केशवं प्रति गच्छति\"। अन्तर केवल इतना है -- जानकर की गई पूजा शाश्वत पूर्ण फल देती है, अनजाने में की गई फलाकांक्षा-युक्त पूजा क्षुद्र और भौतिक फल देती है।",
  "7.23": "अन्तवत् तु फलम् तेषाम् तत् भवति अल्प-चेतसाम् |\nदेवान् देव-यजः यान्ति मत्-भक्ताः यान्ति माम् अपि -- उन अल्पबुद्धि लोगों का वह फल नाशवान् होता है; देवताओं को पूजने वाले देवताओं को प्राप्त होते हैं, मेरे भक्त मुझे ही प्राप्त होते हैं।\n\nकोई देवता हमें अनन्त काल तक अपने लोक में नहीं रखता; कर्म की अवधि समाप्त होते ही पुनः इस मृत्युलोक में लौटना पड़ता है। इसलिए भगवान की जानकारी के बिना केवल देवता-उपासना शाश्वत मोक्ष नहीं दे सकती। भगवान में मन लगाकर एकभक्ति से भजन करने पर ही \"तद्धाम परमं मम\" -- वह शाश्वत मोक्ष प्राप्त होता है जहाँ से लौटना नहीं पड़ता। भगवान स्तुति नहीं, सत्य-ज्ञान चाहते हैं; सत्य को जानने वालों का ही वे उद्धार करते हैं।",
  "7.24": "अव्यक्तम् व्यक्तिम् आपन्नम् मन्यन्ते माम् अबुद्धयः |\nपरम् भावम् अजानन्तः मम अव्ययम् अनुत्तमम् -- मेरे परम, अविनाशी, अनुपम भाव को न जानने वाले अबुद्ध लोग मुझ अव्यक्त को व्यक्त हुआ मानते हैं।\n\nभगवान के विषय में सही समझ प्राप्त करना कठिन है, परन्तु गलत धारणा बना लेना सरल है। भगवान का पाञ्चभौतिक, नाशवान् शरीर कभी नहीं होता -- वे सदा अव्यक्त हैं। ऐसे अव्यक्त भगवान अपनी इच्छा से अवतार-रूप में प्रकट होते हैं। जो लोग भगवान के स्वरूप को न जानकर उन्हें भी अपने जैसा नाशवान् शरीरधारी मान लेते हैं, वे बुद्धिशून्य ही कहलाते हैं।",
  "7.25": "न अहम् प्रकाशः सर्वस्य योग-माया-समावृतः |\nमूढः अयम् न अभिजानाति लोकः माम् अजम् अव्ययम् -- योगमाया से आवृत मैं सबके लिए प्रकट नहीं हूँ; यह मूढ़ संसार मुझ अजन्मे, अविनाशी को नहीं पहचानता।\n\nभगवान सबके सामने प्रकट नहीं होते। मनुष्य की बुद्धि की एक सीमा है, परन्तु भगवान उस सीमा में नहीं आते, इसलिए उनके अनन्त ज्ञान, अनन्त शक्ति, अनन्त रूप को हमारी बुद्धि ग्रहण नहीं कर सकती। अज्ञान नामक माया के पर्दे के कारण भगवान हमें दिखाई नहीं देते; समय पकने पर, अपनी इच्छा से, वे उतने प्रकट होते हैं जितना जीव की क्षमता होती है।",
  "7.26": "वेद अहम् समतीतानि वर्तमानानि च अर्जुन |\nभविष्याणि च भूतानि माम् तु वेद न कश्चन -- हे अर्जुन, मैं भूत, वर्तमान और भविष्य के सभी प्राणियों को जानता हूँ; परन्तु मुझे कोई नहीं जानता।\n\nभूत शब्द के अनेक अर्थ हैं -- पञ्चभूत, उनसे बना ब्रह्माण्ड, और उससे बने सम्पूर्ण जीव-जगत्। भूत, वर्तमान और भविष्य के अनन्त ब्रह्माण्डों और जीव-जातियों को जानने वाला वह एक भगवान ही अनन्तकोटि-ब्रह्माण्ड-नायक है। भगवान को पूर्ण रूप से जानना असम्भव है; वे स्वतन्त्र, पूर्ण और नित्यसत्य हैं, जबकि जीव अपूर्ण, अस्वतन्त्र है।",
  "7.27": "इच्छा-द्वेष-समुत्थेन द्वन्द्व-मोहेन भारत |\nसर्व-भूतानि सम्मोहम् सर्गे यान्ति परन्तप -- हे भारत, हे परन्तप, इच्छा-द्वेष से उत्पन्न द्वन्द्व-मोह के कारण सभी प्राणी जन्म से ही सम्मोह को प्राप्त होते हैं।\n\nजन्म के साथ ही हम इच्छा और द्वेष लेकर जन्म लेते हैं, और शरीर बढ़ने के साथ यह भी बढ़ता जाता है। जो-दुःख को सुख समझकर उसके पीछे भागते हैं, वे अन्ततः दुःख पाकर पछताते हैं। \"जो मैं जानता हूँ वही सही है\" यह हठ मनुष्य को अज्ञान से मोह की ओर, और मोह से सम्मोह की ओर ले जाता है। महाभारत में कहा गया है -- \"सर्वो हि मन्यते लोक आत्मानं बुद्धिमत्तरम्।\"",
  "7.28": "येषाम् तु अन्तगतम् पापम् जनानाम् पुण्य-कर्मणाम् |\nते द्वन्द्व-मोह-निर्मुक्ताः भजन्ते माम् दृढ-व्रताः -- जिन पुण्यवान् लोगों का पाप समाप्त हो चुका है, वे द्वन्द्व-मोह से मुक्त होकर दृढ़ व्रत से मेरी भक्ति करते हैं।\n\nद्वन्द्व-मोह के दो मूल कारण हैं -- जीव का अपना स्वभाव, और प्रारब्ध-कर्म। जिनका स्वभाव ही ऐसा है उनके लिए कोई उपाय नहीं, परन्तु जो सात्त्विक जीव किसी कारणवश बुरे मार्ग पर चला जाता है, उसके लिए ज्ञान का मार्ग खुला रहता है। पश्चात्ताप से बढ़कर कोई प्रायश्चित नहीं है। अपनी भूल का बोध होते ही उत्पन्न पश्चात्ताप ही भगवान की ओर गहरी भक्ति को जन्म देता है।",
  "7.29": "जरा-मरण-मोक्षाय माम् आश्रित्य यतन्ति ये |\nते ब्रह्म तत् विदुः कृत्स्नम् अध्यात्मम् कर्म च अखिलम् -- जो जरा-मरण से मुक्ति के लिए मेरी शरण लेकर प्रयत्न करते हैं, वे उस ब्रह्मतत्त्व को, सम्पूर्ण अध्यात्म को और सम्पूर्ण कर्म को भी जानते हैं।\n\nबलि चक्रवर्ती के त्रिपाद-दान की कथा उपासना के तीन क्रमों को दर्शाती है -- पहला, भगवान की छोटी मूर्ति की पूजा; दूसरा, भगवान को सम्पूर्ण जगत् में व्याप्त शक्ति के रूप में जानना; तीसरा और सबसे महत्त्वपूर्ण, भगवान को अपने भीतर भी अन्तर्यामी रूप में जानकर अपने आप को उन्हें अर्पित कर देना। यही ब्रह्म-कर्म-अध्यात्म का ज्ञान है।",
  "7.30": "स-अधिभूत-अधिदैवम् माम् स-अधियज्ञम् च ये विदुः |\nप्रयाण-काले अपि च माम् ते विदुः युक्त-चेतसः -- जो मुझे अधिभूत और अधिदैव के साथ, तथा अधियज्ञ के साथ जानते हैं, और जो अन्त-काल में भी युक्त-चित्त होकर मुझे स्मरण करते हैं, वे मुझे वास्तव में जानते हैं।\n\nभगवान की जानकारी के लिए पहले अधिभूत (भौतिक जगत्) का ज्ञान चाहिए, फिर अधिदैव (प्रत्येक इन्द्रिय के पीछे स्थित अभिमानी देवता) का, फिर अधियज्ञ अर्थात् सब देवताओं के नियन्ता भगवान का। इस प्रकार अधिभूत, अध्यात्म, अधिदैव, अधियज्ञ, ब्रह्म-साक्षात्कार और कर्म-रहस्य -- ये छह बातें जीवन के अन्तिम क्षण में भी दृढ़ रहनी चाहिए, क्योंकि मृत्यु के समय जो मन में दृढ़ रहता है, वही अगले जन्म को निर्धारित करता है।\n\nइति सप्तमोऽध्यायः।",
  "8.1": "अध्याय आठ\n\nअर्जुन उवाच — अर्जुन ने कहा:\n\nकिं तद् ब्रह्म किम् अध्यात्मं किं कर्म पुरुषोत्तम ।\nअधिभूतं च किं प्रोक्तम् अधिदैवं किम् उच्यते -- हे पुरुषोत्तम, वह 'ब्रह्म' क्या है? 'अध्यात्म' क्या है? 'कर्म' क्या है? 'अधिभूत' किसे कहते हैं? 'अधिदैव' किसे कहते हैं?\n\nअर्जुन कृष्ण से पूछते हैं: \"वह ब्रह्मतत्त्व क्या है? अध्यात्म क्या है? और कर्म क्या है?\" यहाँ व्यास ने अर्जुन के इस प्रश्न के पीछे की भावना को \"पुरुषोत्तम\" इस विशेषण में समेट कर हमारे सामने रखा है। पुरुषोत्तम का अर्थ है -- जो क्षर (जीव) से परे खड़ा है और अक्षर (श्रीतत्त्व) से भी बड़ा है। \"क्षर-अक्षर से परे खड़े आप ही पुरुषोत्तम हैं, आपसे बड़ा कोई तत्त्व नहीं है, अतः जैसा मैं समझता हूँ, आप ही ब्रह्म हैं। इसकी व्याख्या आपसे ही सुनना चाहता हूँ\" -- यही भाव अर्जुन ने \"पुरुषोत्तम\" विशेषण के द्वारा व्यक्त किया है। अर्जुन आगे पूछते हैं: \"अधिभूत किसे कहते हैं? अधिदैव किसे कहते हैं?\"",
  "8.2": "अधियज्ञः कथं कोऽत्र देहेऽस्मिन् मधुसूदन ।\nप्रयाणकाले च कथं ज्ञेयोऽसि नियतात्मभिः -- हे मधुसूदन, इस देह में 'अधियज्ञ' कौन है, और कैसे? और मृत्यु के समय संयमी पुरुषों द्वारा आप कैसे जाने जाते हैं?\n\nआगे अर्जुन पूछते हैं: \"अधियज्ञ कौन है?\" हमारे शरीर में अधियज्ञ कौन है, और किस रूप में? \"अधियज्ञ\" शब्द का अर्थ-क्षेत्र क्या है? -- यही अर्जुन का प्रश्न है। यहाँ भी व्यास ने अर्जुन के प्रश्न के पीछे की भावना को \"मधुसूदन\" इस विशेषण से व्यक्त किया है। \"मधुसूदन\" नाम के मुख्यतः दो अर्थ हैं। \"मधु\" का अर्थ है आनन्द। \"सूद\" का अर्थ है सत्कर्म करने वाला -- सात्त्विक पुरुष। इस प्रकार मधुसूदन का अर्थ है -- जो सात्त्विक पुरुषों के भीतर रहकर उन्हें आनन्द देता है। \"सूद\" का एक और अर्थ है -- नाश करना। इस प्रकार मधुसूदन दुष्टों के आनन्द का नाश करने वाला भी है। \"आप ही हमारे भीतर बैठकर सुख देने वाले हैं, और आप ही दुःख देने वाले भी हैं। हमारे भीतर बैठकर आप ही प्रत्येक यज्ञ को नियंत्रित करते हैं। अतः मेरी समझ में आप ही अधियज्ञ हैं -- यह मुझे समझाइए\" -- यही भाव व्यास ने इस विशेषण द्वारा व्यक्त किया है। अर्जुन पूछते हैं: \"जीवन की अंतिम और सबसे बड़ी यात्रा के समय, शरीर से जीव के निकलने की प्रक्रिया और विधि मुझे समझाइए।\"\n\nइस श्लोक में प्रयुक्त दो विशेषणों -- पुरुषोत्तम और मधुसूदन -- के अर्थ देखने से यह स्पष्ट होता है कि अर्जुन इन छह विषयों (शब्दों) का सही अर्थ पहले से ही जानते थे। फिर भी भगवान से विस्तृत व्याख्या सुनने की इच्छा से वे कृष्ण से यह प्रश्न पूछते हैं। सामान्यतः जो पहले से जानते हैं, वे भी दूसरों को ज्ञात कराने के उद्देश्य से ऐसे प्रश्न पूछते हैं। यहाँ अर्जुन यह प्रश्न कृष्ण से अपनी समझ की पुष्टि के लिए और भगवान की व्याख्या समस्त मानवजाति तक पहुँचाने के लिए दोनों उद्देश्यों से पूछते हैं।\n\nहमें आश्चर्य हो सकता है: \"युद्धभूमि में खड़े अर्जुन ऐसे प्रश्न क्यों पूछ रहे हैं? यहाँ इसकी क्या आवश्यकता है?\" सामान्यतः युद्धभूमि में खड़े व्यक्तियों को मृत्यु से बढ़कर कोई चिंता नहीं होती। मृत्यु प्रत्येक क्षण उनकी प्रतीक्षा करती है। वे मृत्यु और मृत्यु के परे की स्थिति के प्रति सदैव सजग रहते हैं। सैनिकों के लिए मृत्यु के परे क्या है, यह अत्यंत महत्त्वपूर्ण होता है। कृष्ण-अर्जुन संवाद में अब तक कृष्ण ने कहीं भी अर्जुन को विजय का आश्वासन नहीं दिया है -- केवल यही कहा है कि धर्म के लिए युद्ध करना अर्जुन का कर्तव्य है। अतः युद्धभूमि में खड़े अर्जुन के लिए मृत्यु और उसके परे का प्रश्न अत्यंत महत्त्वपूर्ण है। अर्जुन के इस प्रश्न का उत्तर ही इस आठवें अध्याय के शेष भाग में दिया गया है।",
  "8.3": "श्रीभगवानुवाच — भगवान ने कहा:\n\nअक्षरं ब्रह्म परमं स्वभावोऽध्यात्ममुच्यते ।\nभूतभावोद्भवकरो विसर्गः कर्मसंज्ञितः -- सर्वश्रेष्ठ अक्षर तत्त्व ही 'ब्रह्म' है। जीव का स्वरूप [और जीव से संबंधित समस्त पिण्डाण्ड -- भगवान का अपना अंतर्भाव] 'अध्यात्म' कहलाता है। चेतन-अचेतन की उत्पत्ति का कारण भगवान का बहुविध सृष्टि-व्यापार 'कर्म' कहलाता है।\n\nकृष्ण कहते हैं -- \"ब्रह्म\" का अर्थ है \"परमं ब्रह्म -- परमम् अक्षरम्।\" भगवान सबसे महान हैं -- वे सर्वश्रेष्ठ अक्षर तत्त्व हैं; ऐसे भगवान को जानना ही \"ब्रह्म\" शब्द का तात्पर्य है। विष्णुसहस्रनाम में भगवान का वर्णन इस प्रकार है:\n\nपरमं यो महत्तेजः परमं यो महत्तपः ।\nपरमं यो महद्ब्रह्म परमं यः परायणम् ॥\n\nभगवान वह स्वरूप हैं जो प्रत्येक प्रकाश को प्रकाश देते हैं; वे प्रत्येक चिंतन का अंतिम लक्ष्य हैं; वे समस्त ज्ञान की परिणति हैं। यहाँ भगवान को \"परम महाब्रह्म\" कहा गया है। \"ब्रह्म\" का अर्थ है जीव; \"परब्रह्म\" का अर्थ है मुक्त जीव; \"परमब्रह्म\" का अर्थ है श्रीतत्त्व -- नित्यमुक्त श्री लक्ष्मी। \"परम महाब्रह्म\" का अर्थ है नारायण। भगवान परायणों से भी परे हैं -- यहाँ \"परायण\" का अर्थ है वे तत्त्वाभिमानी देवता जो हमारा आधार हैं। भगवान समस्त देवताओं के स्वामी हैं। यही \"ब्रह्म\" शब्द का, जानने योग्य छह विषयों में से एक, तात्पर्य है।\n\nआगे कृष्ण कहते हैं: \"स्वभावोऽध्यात्ममुच्यते।\" यहाँ स्वभाव का अर्थ है अपना निजी स्वरूप -- जीव के अस्तित्व की रीति, जीव का अपना स्वभाव। भगवान को जानने से पहले हमें अपने जीव-स्वभाव को जानना आवश्यक है। मैं क्या हूँ? मुझमें अच्छा (plus point) क्या है? मुझमें बुरा (minus point) क्या है? -- हमें निरंतर स्वयं को इस प्रकार जानने का प्रयास करना चाहिए [किंतु हम प्रायः दूसरों का ही मूल्यांकन करने में समय व्यतीत करते हैं!]। हमें यह भी ज्ञात नहीं कि इस शरीर की आँख, हाथ, पैर आदि अंगों के अतिरिक्त \"मैं\" नामक कोई वस्तु भी है। हमें पहले जीव के अस्तित्व को जानना चाहिए, तत्पश्चात् उसके स्वभाव को। [सामान्यतः हमें अपने जीव-स्वभाव का ज्ञान नहीं होता; हम प्रभाव के अधीन जीते हैं।] जीव अत्यंत सूक्ष्म तत्त्व है। वह हृदय-कमल के मध्य में अनाहत-चक्र नामक शक्तिकेंद्र में निवास करता है। यह जीव कमरे में जलाए गए एक छोटे दीपक के समान है -- जैसे दीपक सम्पूर्ण कमरे को प्रकाशित करता है, वैसे ही अत्यंत सूक्ष्म होते हुए भी जीव सम्पूर्ण शरीर को अपने प्रकाश से व्याप्त करता है। ऐसा है जीव और उसका स्वभाव -- यही \"अध्यात्म\" है।\n\nकृष्ण आगे कहते हैं: \"यह जगत् भूत और भाव है -- अर्थात् चेतन और अचेतन की सृष्टि।\" हम इस जगत् में विद्यमान हैं। ऐसा जगत् कैसे बना? कब बना? इसके पीछे मूल द्रव्य क्या है? इसका निमित्त और उपादान कारण कौन है? जीव शरीर के माध्यम से जन्म क्यों लेता है? जब हम इन सबका क्रमबद्ध चिंतन करते हैं, तो एक सत्य स्पष्ट होता है -- यही कर्म का सिद्धांत है। इस अनंत जीवसमूह और इस अचेतन जगत् की सृष्टि करने वाली मूल शक्ति वे भगवान ही हैं; उन्हीं की क्रिया सच्ची क्रिया है। इस जगत् की बहुविध सृष्टि का मूल समझना ही सच्चे कर्म को समझना है। हम सब भगवान द्वारा बनाई गई कठपुतलियाँ मात्र हैं -- वे ही सूत्रधार हैं। हमारा कर्म उसी सूत्रधार के नियम से बँधा है। सम्पूर्ण जगत् का चक्र भगवान के अधीन घूमता है; भगवान की क्रिया महाक्रिया है। हमारी क्रिया एक बड़े घूमते चक्र पर चलती चींटी के समान है -- चींटी चाहे जिस दिशा में चले, उसकी गति वास्तव में चक्र की ही गति है, चींटी की नहीं; चींटी के कारण चक्र नहीं घूमता। इसी प्रकार जगत् की गति हमारे कर्म से निर्धारित नहीं होती -- यह अपने ही क्रम में निरंतर चलती रहती है। अतः \"मैंने यह किया\", \"मेरे कारण यह हुआ\" -- इस अहंकार का कोई अर्थ नहीं है। इस प्रकार चेतन-अचेतन जगत् की उत्पत्ति का कारण जो विशिष्ट सृजनात्मक क्रिया है, वही सच्चा \"कर्म\" है।\n\nएक दूसरे आयाम से देखें तो यह श्लोक भिन्न रूप से खुलता है। यहाँ जीव का कोई प्रवेश ही नहीं है -- तीनों विषय स्वयं भगवान के विषय में हैं। \"ब्रह्म\" का अर्थ है \"भगवान\"; \"स्वभाव\" का अर्थ है भगवान का अपना स्वतंत्र स्वभाव। अतः भगवान के गुणों और स्वभाव का चिंतन ही \"अध्यात्म\" है। हममें से कुछ लोग पूछते हैं: \"भगवान का यह स्वभाव क्यों है? किसी को सुख, किसी को दुःख; किसी को दरिद्रता, किसी को धन; किसी को नरक, किसी को स्वर्ग -- यह भेदभाव क्यों?\" यह एक बालसुलभ प्रश्न है। इसी प्रकार के तर्क से नास्तिकता जन्म लेती है। जीव अनादि और नित्य है; भगवान उसे उत्पन्न नहीं करते। भगवान का स्वभाव प्रत्येक जीव को उसके अपने स्वरूप में निहित गुण और योग्यता के अनुसार सृजित करना है। अतः यहाँ भेदभाव का प्रश्न उठता ही नहीं। भगवान की सृष्टि में स्वतंत्रता; उनकी निष्पक्षता; किसी भी प्रभाव से अप्रभावित रहना; त्रिगुणातीत होना -- यही भगवान का मूल स्वभाव है। इसका ज्ञान ही \"अध्यात्म\" है। जब हम भगवान के स्वभाव को जानते हैं, तो उनकी सृष्टि क्या है यह भी समझ में आता है -- यही कर्म है। भगवान की क्रिया में हमारी भाँति ज्ञान-इच्छा-कर्म की तीन अवस्थाएँ नहीं हैं; उनका संकल्प ही क्रिया है। यह जानना ही \"कर्म की समझ\" है। इस प्रकार भगवान के अपने स्वरूप, उनके स्वभाव और उनकी क्रिया की समझ ही ब्रह्म, अध्यात्म और कर्म है।",
  "8.4": "अधिभूतं क्षरो भावः पुरुषश्चाधिदैवतम् ।\nअधियज्ञोऽहमेवात्र देहे देहभृतां वर -- नाशवान् स्थिति [जन्म-मृत्यु की, देहधारियों के समूह से बना यह जगत्] 'अधिभूत' है। शरीर के भीतर से नियमन करने वाली तत्त्वाभिमानी देवताएँ ['पुरुष' नामक श्रीतत्त्व, जगत् की सर्वोच्च प्रेरणाशक्ति] 'अधिदैव' हैं। हे देहधारियों में श्रेष्ठ, इस देह में मैं स्वयं 'अधियज्ञ' हूँ।\n\nजैसा पिछले श्लोक में देखा, अध्यात्म शरीर में बंदी जीव है। इस जीव के भोग के लिए रचा गया पंचभूतात्मक जगत् का प्रत्येक विषय अधिभूत के अंतर्गत आता है। पंचभूतों का मूल द्रव्य, और पंचभूतों से निर्मित जगत्, अधिभूत है -- जड़ प्रकृति से लेकर स्थूल ब्रह्मांड तक त्रिगुणमय सब कुछ \"अधिभूत\" है।\n\nकृष्ण कहते हैं: \"पुरुषश्चाधिदैवतम्।\" शरीर के भीतर विभिन्न इंद्रियों का नियमन करने वाली देवताएँ हैं, जो देह में निवास करने वाले जीव की सहायता करती हैं -- यही अधिदैवत का विज्ञान है। यह एक पक्ष है। दूसरे दृष्टिकोण से देखें तो यहाँ कृष्ण \"पुरुष\" को संबोधित कर रहे हैं। हमारे शरीर में चार \"पुरुष\" हैं -- शरीरपुरुष, छन्दःपुरुष, वेदपुरुष और संवत्सरपुरुष। इस शरीर के खड़े होने और चलने के लिए शरीरपुरुष रूपी शिव-शक्ति आवश्यक है। मन के विचार को स्पन्दन, परा, पश्यन्ती, मध्यमा और वैखरी रूपों में वाणी-शक्ति के रूप में प्रकट करने के लिए छन्दःपुरुष शेष कारण हैं। मनोमय कोश में निवास करने वाले वेदपुरुष गरुड़ हमें वेदान्त-चिंतन और मानसिक मनन की शक्ति प्रदान करते हैं, वैदिक वाणी की दुर्लभ शक्ति देते हैं। जीव की योग्यता और सम्पूर्ण जीव-स्वरूप का नियमन करने वाले चतुर्मुख ब्रह्मा जीव की इंद्रियों के अधिष्ठाता देवता हैं -- वे संवत्सरपुरुष हैं [\"संवत्सर\" का अर्थ है वह पितामह जो अपनी संतानों का भली-भाँति पालन करता है]। ब्रह्मा और वायु जीव को उठाकर साधना-मार्ग पर स्थापित करते हैं। इस प्रकार भगवान के पश्चात् शरीर में प्रमुख अधिष्ठाता देवता ये पाँच हैं, और उनके द्वारा शासित सम्पूर्ण जगत् अधिभूत है।\n\nकृष्ण आगे कहते हैं: \"मैं प्रत्येक शरीर में एक विशेष रूप में निवास करता हूँ -- भगवान का यह रूप 'अधियज्ञ' रूप है।\" यज्ञ का अधिष्ठाता, नियामक, भोक्ता, कर्ता, प्रेरक और फलदाता वे भगवान ही अधियज्ञ हैं। हमारे जीवन की प्रत्येक क्रिया, जिसे भगवान की पूजा जानकर किया जाए, यज्ञ है। \"यज देवपूजायाम्\" -- हमारे जीवन की प्रत्येक क्रिया भगवान की पूजा है। हमारे शरीर में निवास करते हुए समस्त तत्त्वाभिमानी देवताओं के माध्यम से क्रिया कराने वाले भगवान \"अधियज्ञ\" हैं।\n\nदूसरे आयाम से देखें [जैसा पिछले श्लोक में भगवान, उनके स्वभाव और उनकी क्रिया के विश्लेषण में देखा], अधिभूत का अर्थ है ब्रह्मा और समस्त देवता। चेतन-अचेतन जगत्, जीव, शरीर, ब्रह्मा और ब्रह्मांड -- यह सब अधिभूत है। ब्रह्मा और समस्त देवताओं की माता, \"शक्ति\" श्रीतत्त्व, जो भगवान के पश्चात् सबसे श्रेष्ठ हैं, वे अधिदैव हैं। सर्वत्र व्याप्त होकर प्रत्येक जीव में अंतर्यामी नियंता के रूप में स्थित भगवान अधियज्ञ हैं।",
  "8.5": "अन्तकाले च मामेव स्मरन् मुक्त्वा कलेवरम् ।\nयः प्रयाति स मद्भावं याति नास्त्यत्र संशयः -- अंतिम क्षण में मुझे ही स्मरण करते हुए, देह त्यागकर जो प्रस्थान करता है, वह निःसंदेह मेरे ही भाव को प्राप्त होता है [मुझमें ही निवास पाता है]।\n\nअर्जुन के अंतिम प्रश्न का उत्तर देते हुए कृष्ण कहते हैं: \"मृत्यु के क्षण में भी मुझे ही स्मरण करते हुए जो देह त्यागकर जाता है, वह मेरी ही भाँति ज्ञानानंदस्वरूप होकर मुझमें आकर निवास करता है। वह पुनः इस अज्ञान और दुःखमय संसार के भँवर में कभी नहीं फँसता। इस विषय में कभी संदेह मत करो।\" यहाँ \"अंतकाले\" का अर्थ \"बुढ़ापे में\" नहीं है, अपितु देह से जीव के निकलने का अंतिम क्षण है। देह त्यागते हुए भगवान का स्मरण करते हुए बाहर जाने वाली चेतना को अपार प्रकाश दिखाई देता है, और वह चेतना मोक्ष को प्राप्त होती है। [जीव के शरीर त्यागने और देह से बाहर आने के पश्चात् जीव की यात्रा के विषय में, मरकर जीवित हुए अनेक लोगों के अनुभवों को संकलित कर रेमंड मूडी द्वारा लिखित 'Life After Life' नामक पुस्तक इस विषय पर प्रकाश डालती है।]",
  "8.6": "यं यं वापि स्मरन्भावं त्यजत्यन्ते कलेवरम् ।\nतं तमेवैति कौन्तेय सदा तद्भावभावितः -- हे कौन्तेय, अंत में देह त्यागते समय जिस-जिस भाव का स्मरण करता है, उसी भाव को वह प्राप्त होता है, क्योंकि वह सदैव उसी भाव से भावित रहता है।\n\nकृष्ण ने क्यों कहा कि जीवन के अंतिम क्षण में भगवान को स्मरण करने वाले \"मुझसे मिल जाते हैं\"? इसका उत्तर यह श्लोक देता है। यहाँ कृष्ण मृत्यु के क्षण का एक अद्भुत मनोविज्ञान हमारे सामने प्रकट करते हैं। मृत्यु के समय भगवान का ध्यान करने का एक विशेष उद्देश्य है, कृष्ण कहते हैं। देह त्यागते समय हम जिसका स्मरण करते हैं, वही अगले जन्म में हमें प्राप्त होता है -- अतः यदि हम उस समय भगवान को स्मरण करें, तो हम भगवान से मिल जाते हैं। मृत्यु के अंतिम क्षण में उठने वाला विचार ही अगले जन्म का निर्णायक होता है; अतः अगले जन्म में जो होना है, वही उस क्षण मन में उभर आता है! जिनका भगवान तक पहुँचने का कोई योग (संबंध) नहीं होता, उनके मन में उस समय भगवान कभी नहीं आते। शास्त्रों में इसके अनेक दृष्टांत मिलते हैं। ऋषभदेव के पुत्र भरत की कथा -- जिनके नाम से यह भूमि \"भारत\" कहलाई -- इस बात को स्पष्ट करती है। (यह भरत दुष्यंत के पुत्र नहीं हैं; दुष्यंत के पुत्र भरत \"भरतवंश\" के आदिपुरुष हैं।) अत्यंत धर्मात्मा भरत ने पुत्र के वयस्क होने पर सम्पूर्ण राज्यभार उसे सौंपकर वानप्रस्थ लिया और वन में ऋषियों के साथ, सदैव भगवान की भक्ति में लीन रहते हुए, निवास किया। एक दिन उन्हें वन में एक मृगशावक मिला जिसकी माता मर चुकी थी। भरत उसे घर ले आए और उसका पालन करने लगे, तब से वे उस मृग की देखभाल में ही पूर्णतः लीन रहने लगे। इससे उनकी साधना क्षीण होती गई। मृगशावक के बड़ा होने से पहले ही उनकी मृत्यु का समय आ गया -- और उस समय भरत को भगवान का स्मरण नहीं, अपितु उस मृगशावक की चिंता सताने लगी! इसी कारण अगले जन्म में उनका जन्म मृग के रूप में हुआ। अपरोक्ष-ज्ञान प्राप्त व्यक्ति को भी प्रारब्ध नहीं छोड़ता, इसका यह सर्वोत्तम उदाहरण है। यह कथा कृष्ण द्वारा यहाँ कहे गए मर्म का सजीव दृष्टांत है।\n\nहम चाहे जीवन-भर साधना करते रहें, फिर भी मृत्यु के क्षण भगवान का स्मरण न आए, ऐसा हो सकता है। इसीलिए जीवन-भर की -- अथवा अनेक जन्मों की -- साधना आवश्यक है। कृष्ण कहते हैं \"सदा तद्भावभावितः।\" यहाँ भाव का अर्थ है तल्लीनता। भगवान का सतत चिंतन करते हुए, मन को सदैव उन्हीं में लीन रखना चाहिए। अंतिम क्षण में भगवान का स्मरण आने के लिए, मन को निरंतर भगवान पर स्थिर रखने का संस्कार आवश्यक है। इसके बिना, यदि यह सोचकर जीवन व्यर्थ किया जाए कि \"मृत्यु के समय तो भगवान को याद कर ही लूँगा,\" तो उस क्षण भगवान का स्मरण बिल्कुल नहीं आएगा!\n\nभीष्माचार्य ने अपने अंतिम दिनों में भगवान का जितना भी चिंतन किया हो, उन्होंने वास्तव में जो देखा वह अपने ही बाणों से घायल, रक्तरंजित कृष्ण थे! उन्हें आनंदस्वरूप भगवान का सच्चा दर्शन नहीं हुआ। यहाँ हमें यह समझना है कि हमें कभी भी किसी बुरी वस्तु में मन को गहराई से नहीं लगाना चाहिए -- यदि हम ऐसा करें, तो अंतिम क्षण में वही हमें दिखाई देगा! जीवन-भर हमें कभी बुरे विचारों में नहीं रहना चाहिए, न ही किसी को दुष्ट समझकर द्वेष करना चाहिए। किसी से द्वेष करना अत्यंत बुरी बात है -- यह हमारे सम्पूर्ण जीवन को नष्ट कर देता है। दुष्टों से दूर रहें, किंतु उनसे द्वेष न करें। किसी से द्वेष करने और उसकी निंदा में गहरे उतरने से दूसरे व्यक्ति का कुछ भी अहित नहीं होता -- बल्कि हम स्वयं अपना जीवन नष्ट कर लेते हैं। जिससे हम द्वेष करते हैं, वह हमारे मन में गहराई से बैठ जाता है और हमें नीचे खींचता है; अंतिम समय में वही सिर उठाकर सामने आता है! अतः हमें इस विषय में सावधान रहना चाहिए। हम किसी की भी आलोचना करने योग्य नहीं हैं, क्योंकि हम किसी के हृदय में झाँक नहीं सकते -- हम केवल बाहरी दिखावे के आधार पर बोलते हैं, यह देखने की शक्ति हमारे पास नहीं कि भीतर \"कौन क्या है\"। अतः कृष्ण कहते हैं: दूसरों के विषय में सोचना छोड़ो, और सदैव भगवान का ही चिंतन करो -- हमें केवल एक ही वस्तु का चिंतन करना चाहिए, और वह है भगवान।",
  "8.7": "तस्मात्सर्वेषु कालेषु मामनुस्मर युध्य च ।\nमय्यर्पितमनोबुद्धिर्मामेवैष्यस्यसंशयः -- अतः सभी समय में मेरा स्मरण करो और युद्ध करो। मुझमें मन और बुद्धि अर्पित करने पर तुम निःसंदेह मुझे ही प्राप्त होगे।\n\nईश्वर-स्मरण के लिए कोई निश्चित समय नहीं है। कृष्ण कहते हैं: \"सभी समय में मेरा स्मरण करो।\" कोई भी कर्म करते समय यह जागरूकता रहे कि भगवान ही उस कर्म को करा रहे हैं। युद्ध करते समय भी यह भाव कि \"मेरे भीतर बैठे भगवान ही यह कर्म करा रहे हैं -- यह उन्हीं की इच्छा है,\" युद्ध को भी ईश्वर-पूजा में परिवर्तित कर देता है! भगवान की जागरूकता और उनके प्रति समर्पण हमारी अनजाने में हुई भूलों को भी पाप से दूषित नहीं होने देते। भगवान के स्मरण के लिए समय की कोई सीमा नहीं है -- जब भी भगवान का स्मरण उठे, वही पवित्र क्षण है। उन्हें मन में धारण करना ही पवित्रता है। अतः बिना अहंकार के, पूजा-अर्पण के रूप में, उनका स्मरण करते हुए ही अपना कर्तव्य करना चाहिए।\n\nकिसी कर्म में विद्यमान भावना ही उसे धर्म या अधर्म बनाती है। धर्मव्याध का उदाहरण लें -- वे मांस बेचकर जीवन-यापन करते थे, फिर भी परम धर्मात्मा के रूप में जीए, क्योंकि उनका अंतःकरण (अनुसंधान) शुद्ध था। उनका दृढ़ विश्वास था: \"भगवान ने मुझे इस कार्य में लगाया है; इस जन्म में मांस बेचकर जीविका चलाना ही मेरा कर्तव्य है, और मुझे इसे ईमानदारी से करते हुए अपना जीवन चलाना है।\" वे केवल अपने और अपने परिवार के भरण-पोषण के लिए ही व्यापार करते थे। इस प्रकार ईमानदारी से जीते हुए, वे ऋषियों से भी ऊँचे स्थान तक पहुँचे। अतः भावना की शुद्धता ही सर्वोच्च है। इसलिए हमें अपना मन और बुद्धि भगवान में स्थिर करना चाहिए -- \"तब तुम निःसंदेह मुझे ही प्राप्त होगे,\" कृष्ण कहते हैं।",
  "8.8": "अभ्यासयोगयुक्तेन चेतसा नान्यगामिना ।\nपरमं पुरुषं दिव्यं याति पार्थानुचिन्तयन् -- हे पार्थ, अभ्यासयोग से स्थिर किए गए चित्त से, अन्यत्र न जाते हुए, निरंतर चिंतन करते हुए, वह उस परम दिव्य पुरुष को प्राप्त होता है।\n\nपार्थ, जिनकी सृष्टि केवल लीला है, वह परम पुरुष अभ्यास के अनुशासन से, अन्यत्र कुछ भी न चाहने वाले अंतःकरण से, भक्तिपूर्वक स्मरण करने वाले को प्राप्त होते हैं।\n\nअपने मन को निरंतर भगवान में स्थिर रखने के लिए \"निरंतर मनन\" ही सबसे महत्त्वपूर्ण साधन है। सामान्यतः हमारा मन उन वस्तुओं की ओर भटकता है जिन्हें हम चाहते भी नहीं; हमें इसे केवल भगवान का चिंतन करने का प्रशिक्षण देना होगा, ताकि अन्य कुछ भी उसे विचलित न कर सके। हमारा मन, बुद्धि और चित्त वैसे ही कार्य करते हैं जैसा हम उन्हें प्रशिक्षित करते हैं; हमें उन्हें भगवान के चिंतन के अभ्यास में प्रशिक्षित करना होगा। अभ्यास ही वह एकमात्र साधन है जिससे मन की चंचल प्रकृति वश में होती है। ऐसा होने पर मन भगवान में स्थिर हो जाता है -- और भगवान में स्थिर मन अंतिम क्षण में भी भगवान को ही देखता है। यह केवल चिंतन (cintana) नहीं, अपितु अनुचिंतन है -- श्रुति में वर्णित भगवान का सच्चा, यथार्थ ध्यान। मिथ्या का चिंतन करके भगवान तक नहीं पहुँचा जा सकता।\n\nकृष्ण कहते हैं कि एकाग्र मन से हृदय-कमल के मध्य में निवास करने वाले भगवान, उस दिव्य परम पुरुष का ध्यान करना चाहिए। यहाँ कृष्ण का संदेश है: ध्यान में यह पहचानो कि महानतम में महान, भगवान, तुम्हारे हृदय में नित्य और सार्थक रूप से निवास करते हैं। भगवान सर्वव्यापी, सर्वसमर्थ, समस्त गुणों से परिपूर्ण, अनादि और नित्य हैं -- ऐसे भगवान हमारे हृदय-कमल में निवास करते हैं और दिव्य (divya) हैं।\n\nयहाँ प्रयुक्त \"दिव्य\" शब्द के अनेक अर्थ हैं। मूलतः \"दिव्य\" या \"देव\" शब्द \"दिव्\" धातु से बने हैं। प्राचीन धातुपाठ में इस धातु के सात अर्थ हैं: (1) द्युति (प्रकाश) (2) विजिगीषा (विजय की इच्छा) (3) कान्ति (आभा/इच्छा) (4) स्तुति (प्रशंसा) (5) व्यवहार (लेन-देन) (6) क्रीड़ा (खेल) (7) गतिः (गति/ज्ञान)। हाल में तीन और अर्थ -- मोद, मद, स्वप्न -- जोड़े गए हैं, यद्यपि ये प्राचीन धातुपाठ में नहीं मिलते। ऊपर दिए गए सात अर्थों को संक्षेप में देखें:\n\n1) द्युति: प्रकाश का स्वभाव। सूर्य, चंद्र और प्रत्येक प्रकाश-स्रोत को प्रकाश देने वाले भगवान हमारे भीतर ज्ञान के प्रकाश से भर देते हैं।\n\n2) विजिगीषा: भगवान सबसे ऊपर स्थित हैं, और स्वयं विजय-स्वरूप हैं।\n\n3) कान्ति: केवल इच्छामात्र से सृष्टि करने वाले -- जिन्होंने हमें हमारी अपनी इच्छाशक्ति दी और प्रत्येक की योग्यता के अनुसार उसे पूर्ण करते हैं।\n\n4) स्तुति: सबके द्वारा स्तुत; जिनकी स्तुति सब करते हैं, वे भगवान ही प्रत्येक शब्द से सूचित होते हैं।\n\n5) व्यवहार: जगत् का समस्त व्यवहार संचालित करने वाले।\n\n6) क्रीड़ा: सृष्टि-स्थिति-संहार भगवान के लिए क्रीड़ा मात्र है; जन्म-मृत्यु, प्रत्येक लेन-देन उनकी लीला है।\n\n7) गतिः: गति और ज्ञान देने वाले -- जो सर्वत्र गए हैं, जो सब कुछ जानते हैं, जो सबके भीतर अंतर्यामी बिम्ब के रूप में निवास करते हैं -- वे ही दिव्य या \"देव\" हैं।\n\nइस प्रकार \"दिव्य\" शब्द में अनेक अर्थ पाए जाते हैं। जब हम \"हे ईश्वर\" कहते हैं, तो यदि हम उपर्युक्त अर्थों को एक बार भी स्मरण कर लें, तो जो आनंद प्राप्त होता है वह असीम है -- भगवान के नाम में यही शक्ति है। हम भगवान के साथ रहते हुए भी मानसिक रूप से उनसे दूर रहते हैं। भगवान के निरंतर अनुचिंतन से हम उनका साक्षात्कार प्राप्त कर सकते हैं।\n\nइस अध्याय के शेष भाग में कृष्ण यह स्पष्ट करते हैं कि भगवान को अनुचिंतन में रखने का क्या अर्थ है। आगे के श्लोकों में यह बताया गया है कि ध्यान करते समय साधक को भगवान का कौन-सा रूप धारण करना चाहिए।",
  "8.9": "कविं पुराणमनुशासितारमणोरणीयांसमनुस्मरेद्यः ।\nसर्वस्य धातारमचिन्त्यरूपमादित्यवर्णं तमसः परस्तात् -- जो सर्वज्ञ, सनातन, सबके नियंता, अणु से भी सूक्ष्म, सबके धारण-पोषक, अचिन्त्य रूप वाले, सूर्य के समान तेजोमय, अंधकार से परे भगवान का स्मरण करता है, वह उन्हें ही प्राप्त होता है।\n\nहमारे भीतर निवास करने वाले भगवान का ध्यान करते समय, कृष्ण यहाँ बिंदु-दर-बिंदु वे विषय बताते हैं जो ध्यान में धारण करने चाहिए। कृष्ण कहते हैं: \"भगवान की उपासना 'कवि' के रूप में करो।\" यहाँ कवि का अर्थ है सर्वज्ञ, सर्वज्ञाता। हमें सबसे पहले ज्ञान चाहिए; ज्ञान के बिना आनंद नहीं -- अतः हमें पहले भगवान के प्रति जागरूकता चाहिए। दूसरे, कृष्ण कहते हैं, भगवान की उपासना \"पुराणम्\" रूप में करो। पुराण का अर्थ है वह जो सबसे पहले विद्यमान था और सदा एक-सा बना रहता है -- जो हमारे शरीर (पुर) में बैठकर प्रत्येक क्षण हमारा नियमन करता है; यही ध्यान में धारण करने योग्य अर्थ है।\n\nतीसरे, भगवान \"अनुशासितारम्\" हैं -- जो सबका नियमन और शासन करते हैं। मेरा अपना अस्तित्व, और जगत् की प्रत्येक वस्तु का अस्तित्व, उनके नियंत्रण के अधीन है; भगवान प्रत्येक जीव के अपने स्वभाव की योग्यता के अनुसार शासन करते हैं -- यह जानकर उनका चिंतन करना चाहिए। सम्पूर्ण ब्रह्मांड को भरने वाले वही भगवान, जीव के भीतर अणु से भी सूक्ष्म रूप में विद्यमान हैं। \"सबको धारण करने वाले भगवान हमारे भीतर बैठकर हमें धारण करते हैं; वे सम्पूर्ण ब्रह्मांड को धारण और पोषित करने वाली शक्ति हैं; वे सबको उनकी इच्छा के अनुसार प्रदान करते हैं\" -- इस समझ के साथ उनका ध्यान करना चाहिए।\n\nहमें यह जानना चाहिए कि भगवान हमारी कल्पना की पहुँच से परे हैं -- उनका स्वरूप ऐसा है जिसे न हमारी वाणी और न हमारा मन ग्रहण कर सकता है। यदि ध्यान में जीव अपने स्वभाव की दृष्टि से भगवान को देखे, तो वे उगते हुए सूर्य के समान प्रतीत होते हैं। उनका वर्ण प्रकृति से जन्मा रंग नहीं है; वह त्रिगुणातीत, दिव्य, अविनाशी वर्ण है। जो इस प्रकार भगवान को जानकर निरंतर उनका चिंतन करता है, वह देह त्यागते समय, केवल उन्हीं का स्मरण करते हुए, स्वयं भगवान को प्राप्त होता है।",
  "8.10": "प्रयाणकाले मनसाचलेन भक्त्या युक्तो योगबलेन चैव ।\nभ्रुवोर्मध्ये प्राणमावेश्य सम्यक्स तं परं पुरुषमुपैति दिव्यम् -- मृत्यु के समय अचल मन से, भक्ति और योगबल से युक्त होकर, प्राण को भली-भाँति भौंहों के मध्य में स्थापित करके, वह उस परम दिव्य पुरुष को प्राप्त होता है।\n\nभगवान तक पहुँचने का एक अन्य मार्ग है -- हठयोग। यह मार्ग कठिन है; यह यम-नियम, प्राणायाम और प्रत्याहार के माध्यम से भगवान तक पहुँचने की विधि है। इस श्लोक में कृष्ण बताते हैं कि इस मार्ग के साधकों को मृत्यु के समय क्या करना चाहिए। आसन और प्राणायाम से स्थिर शरीर और स्थिर प्राणमय कोश प्राप्त कर, प्रत्याहार से अपने भीतर भरे दोषों को दूर करके और किसी भी बुरे विचार को प्रवेश न करने देकर, एकाग्रता प्राप्त की जाती है -- यह अत्यंत लंबी और कठिन साधना है। ऐसे साधकों को हृदय-कमल के मध्य में अनाहत-चक्र में जीवनशक्ति के साथ निवास करने वाले जीव को विशुद्धि-चक्र से होते हुए भ्रूमध्य (दोनों भौंहों के मध्य आज्ञाचक्र) तक ऊपर लाना होता है। यह प्रक्रिया अत्यंत कठिन है, और इसमें दृढ़ भक्ति सर्वथा आवश्यक है। यदि इस प्रकार जीव भ्रूमध्य से मस्तक के ब्रह्मरंध्र के मार्ग से निकलता है, तो वह सीधे भगवान के पास जाता है।\n\nचूँकि यह हठयोग अत्यंत कठिन साधना है, प्राचीन काल के लोगों ने इसका एक सरल, सहायक अभ्यास दैनिक जीवन में समाहित किया -- ऊर्ध्वपुण्ड्र इसका उत्तम उदाहरण है। यह जीव की ऊर्ध्वगति से संबंधित है, और शरीर के भीतर शक्तिकेंद्रों को पूर्णतः जाग्रत करने की एक सरल विधि है। [किंतु आज हमें यह भी ज्ञात नहीं कि हम यह चिह्न क्यों धारण करते हैं।]\n\nउचित मार्गदर्शन के बिना हठयोग का अभ्यास खतरनाक है। भागवत के द्वितीय स्कंध में एक पूरा अध्याय उन चरणों का विस्तृत वर्णन करता है जिनसे जीव को ऊपर ले जाया जाता है। इस प्रकार भगवान तक या तो योग की दृढ़ता से पहुँचा जा सकता है, या -- जैसे बालक माता से हठ करता है -- भक्त भक्ति के हठ मात्र से भी उन तक पहुँच सकता है।\n\nजीव को भ्रूमध्य में स्थिर करने की यह विधि समझाकर, कृष्ण आगे तीन श्लोकों में यह और विस्तार से बताते हैं कि इसके बाद जीव मस्तक के शक्तिकेंद्र के द्वार से किस प्रकार निकलता है।",
  "8.11": "यदक्षरं वेदविदो वदन्ति विशन्ति यद्यतयो वीतरागाः ।\nयदिच्छन्तो ब्रह्मचर्यं चरन्ति तत्ते पदं संग्रहेण प्रवक्ष्ये -- वेद के ज्ञाता जिसे 'अक्षर' कहते हैं, आसक्तिरहित यति जिसमें प्रवेश करते हैं, जिसकी इच्छा करते हुए साधक ब्रह्मचर्य का पालन करते हैं -- वह पद मैं तुम्हें संक्षेप में बताऊँगा।\n\nकृष्ण कहते हैं: \"योग-साधना से भ्रूमध्य में स्थिर किए गए जीव को वहाँ से ध्यान में सहस्रार की ओर आगे ले जाना होता है।\" इस प्रक्रिया के दौरान ध्यान में धारण करने योग्य रूप के बारे में कृष्ण कहते हैं: \"वेद के ज्ञाता इसे अविनाशी 'अक्षर' कहते हैं [ओंकार शब्द से व्यक्त होने वाला सर्वशब्दवाच्य]।\" जिन्होंने महान प्रयास से भगवान को प्राप्त किया है, जिन्होंने सांसारिक आसक्ति को पार कर लिया है, वे जाकर उन भगवान से जुड़ जाते हैं। \"वे,\" कृष्ण कहते हैं, \"ऐसे भगवान को जानने की इच्छा से अपने जीवन में ब्रह्मचर्य धारण करते हैं।\" [यहाँ \"ब्रह्मचर्य\" का अर्थ शब्दकोश में दिया गया शारीरिक संयम नहीं है, अपितु \"ब्रह्मणि चरणम्\" -- मन का भगवान में स्थिर निवास।] \"उन तक पहुँचने की इच्छा से वे उस महान तत्त्व का इस प्रकार चिंतन करते हैं। मैं अब तुम्हें संक्षेप में मोक्ष-प्राप्ति की यह प्रक्रिया बताता हूँ,\" कृष्ण कहते हैं, और आगे के श्लोकों में वे अर्जुन को यह प्रक्रिया समझाते हैं।",
  "8.12": "सर्वद्वाराणि संयम्य मनो हृदि निरुध्य च ।\nमूर्ध्न्याधायात्मनः प्राणमास्थितो योगधारणाम् ॥१२॥\n\n[इन दोनों श्लोकों (८.१२ और ८.१३) का पदच्छेद, अर्थ और व्याख्या एक साथ अगले श्लोक (८.१३) में दी गई है।]",
  "8.13": "ओमित्येकाक्षरं ब्रह्म व्याहरन्मामनुस्मरन् ।\nयः प्रयाति त्यजन्देहं स याति परमां गतिम् -- शरीर के समस्त द्वारों को रोककर, मन को हृदय में स्थिर करके, अपने प्राण को मस्तक पर स्थापित करके, योग-धारणा में स्थित होकर -- ब्रह्मवाचक एक अक्षर 'ॐ' का उच्चारण करते हुए, मेरा स्मरण करते हुए -- जो इस प्रकार देह त्यागकर प्रस्थान करता है, वह परम गति को प्राप्त होता है।\n\nसमस्त नाड़ी-द्वारों को रोककर, मन को केवल भगवान में दृढ़तापूर्वक स्थिर करके, अपने प्राण को मस्तक पर स्थापित करके, योग-साधना में स्थित होकर, एक अक्षर \"ॐ\" से व्यक्त होने वाले उस परम तत्त्व की स्तुति करते हुए, मेरा स्मरण करते हुए -- जो इस प्रकार देह त्यागकर ऊपर उठता है, वह उस स्थान को प्राप्त होता है जहाँ से पुनरागमन नहीं होता।\n\nजीव को सहस्रार की ओर ले जाते समय शरीर के अन्य समस्त द्वारों को योगबल से बंद करना होता है, और बंद सहस्रार के द्वार को खोलकर उसी से बाहर जाना होता है। ऐसा करते समय मन को उस सर्वसंहारक भगवान में स्थिर करना चाहिए। अपनी योग-साधना का पूर्ण उपयोग करते हुए, श्वास को रोककर, मन को भगवान में रखते हुए ध्यान करना चाहिए।\n\n\"ओंकार से प्रतिपाद्य मुझे ओंकार के द्वारा स्मरण करते हुए सहस्रार के द्वार से बाहर आकर, देह त्यागकर ऊपर उठने वाला, फिर कभी न लौटने वाले उस स्थान -- मोक्ष (भगवान) -- को प्राप्त होता है।\"\n\nयह साधना केवल हठयोगियों के लिए संभव है, और यह अत्यंत कठिन साधना है। सभी लोग इस प्रकार योगाभ्यास करके सिद्धि प्राप्त नहीं कर सकते। इसीलिए अगले श्लोक में कृष्ण सरल मार्ग की व्याख्या करते हैं।",
  "8.14": "अनन्यचेताः सततं यो मां स्मरति नित्यशः ।\nतस्याहं सुलभः पार्थ नित्ययुक्तस्य योगिनः -- हे पार्थ, जो अनन्य चित्त से निरंतर, नित्य ही, मेरा स्मरण करता है, उस नित्ययुक्त योगी के लिए मैं सहज सुलभ हूँ।\n\n\"जो साधक मेरी उपासना करते हुए निरंतर और नित्य भगवान का ही चिंतन करता है, अन्य कुछ भी स्मरण नहीं करता, उसे मैं सहज ही प्राप्त हो जाता हूँ,\" कृष्ण कहते हैं। जो साधना में सदैव लगा रहता है और उसकी पराकाष्ठा तक पहुँच जाता है, वह बिना किसी अतिरिक्त प्रयास के भगवान को प्राप्त कर लेता है।",
  "8.15": "माम् उपेत्य पुनः जन दुःख आलयम अश्वत्थम |\n\nन अप्पुवंति मह आत्मानः संसिद्धिम परमं गतः - ऐसा व्यक्ति जिसने वरिष्ठ सिद्धि प्राप्त कर ली हो।\nजीवों द्वारा मुझे प्राप्त करने के बाद, इस चार दिवसीय संसार, दुगुदास के निवास, में फिर से जन्म लेना\nनहीं आता\n\nजो जीव सिद्धि प्राप्त करके भगवान से जुड़ जाता है, वह सदैव दुःखी एवं दुःखी रहता है\nइस अनित्य संसार में पुनर्जन्म नहीं होता। “जो लोग आते हैं और मुझसे जुड़ते हैं वे पवित्र आत्माएं हैं।\nसंसार में जीवन की प्राप्ति में सबसे बड़ी सिद्धि ईश्वर प्राप्ति है। यह\nजो लोग इसे प्राप्त कर लेते हैं उन्हें दोबारा पारिवारिक बंधनों में फंसने की जरूरत नहीं होती है,'' कृष्णा कहते हैं।",
  "8.16": "वह ब्रह्मभुवनाथ लोकः पुनः अवर्तिनः अर्जुनः।\nमम उपेत्य तु कौन्तेय रे जन्म न विद्यते - अर्जुन, ब्रह्म लोक तक सर्वथा।\nउसे संसार से भी वापस आना होगा। कौन्तेय, मेरा प्राप्त हो जाने पर ही पुनर्जन्म नहीं होता।\n\nब्रह्मा के लोक से लेकर अन्य सभी लोकों में एक दिन विनाश होगा। चतुर्गुणी ब्राह्मण\nआयु 31,104,000,0000000 (इकतीस हजार एक सौ चार हजार करोड़) वर्ष। ये है\nप्रभु के लिए एक दिन के समान! ईश्वर कालातीत है. तो कृष्ण कहते हैं “जब तुम मुझे पाओगे\nकेवल पुनर्जन्म नहीं होता.",
  "8.17": "सहस्र युग पर्यन्तं अहः यत् ब्राह्मणः विदुः।\n\nरथं युग सहस्रांतं ते अहः रत्र विदः जनः - हजारों युगों तक।\nभगवान हजारों युगों से दिन और अंधकार के रूप में जाने जाते हैं, वह दिन हैं-\nअंधेरे लोग.\n\nयद्यपि भगवान कालातीत हैं, उनकी रचना का समय उनके दृष्टिकोण के लिए भगवान का है\nहगलेंदु और प्रलय काल को भगवान की रात के रूप में भी जाना जाता है। एक हजार\nयुगचक्र संस्करण के लिए एक ब्राह्मण दिवस... युगचक्र का अर्थ है चतुर्युग - कलियुग 4,32,000\nवर्ष; द्वापर युग 8,64,000 वर्ष का है; त्रेता युग 12,96,000 वर्ष का है; कृत युग\n17,28,000 वर्ष; एक युगचक्र मिलाकर 43,20,000 वर्ष का होता है। ऐसे एक हजार\nयुग चक्र ब्रह्म का एक दिन है। अर्थात 432 करोड़ वर्ष। तो ब्रह्मा का एक दिन अर्थात\n864 करोड़ वर्ष. चतुर्मुख ब्रह्मा या सत्यलोक की आयु 100 वर्ष है। वह है\n864 करोड़ x 360 x 100 = 311,040,000,000,000 (इकतीस हजार एक सौ चार हजार)\nकरोड़) प्रति वर्ष। यह ईश्वर का रचना काल (दिन) है। फिर महाप्रलय. इस भीषण बाढ़ के दौरान\n31,104 हजार करोड़ वर्ष (रात)। यह ईश्वर की सृष्टि और विनाश की गणना है।\n\nजल प्रलय तीन प्रकार की होती है. 1. मन्वंतर का जलप्रलय; 2. बाढ़ 3. महाप्रलय [ये तीन\nबाढ़ के अलावा कई छोटी बाढ़ें भी आती हैं। पृथ्वी का कुछ भाग उन बाढ़ों में से एक है\nभाग नष्ट हो सकता है]। मन्वन्तर की जलप्रलय में पृथ्वी पूर्णतया नष्ट नहीं होती--किन्तु\nसभ्यता नष्ट हो जायेगी. दीनप्रलय चतुर्मुखी ब्रह्मा की रात्रि है। यानि प्रत्येक को 432 करोड़\nसाल में एक बार जल प्रलय. इस जलप्रलय में पृथ्वी पूरी तरह नष्ट हो जायेगी। महाप्रलय के अनुसार\nसाल में एक बार 31,104 हजार करोड़ और इस बाढ़ में सत्य लोक से सब कुछ\nयहाँ तक कि संसार भी सूक्ष्म परमाणु रूप में भगवान में लीन हैं।",
  "8.18": "अव्यक्तत् व्यक्तयः सर्वः प्रभावन्ति अहः अगमे |\nयह कैसा अव्यक्त संकेत है, जैसे रात में जल प्रलय - वह सब अदृश्य भगवान से देखा जाता है।\nवे दिन के दौरान बनते हैं, और अंधेरा होने पर उसी अदृश्य भगवान में गायब हो जाते हैं।\n\nमहाप्रलय के समय अव्यक्त भगवान से प्रकट हुआ यह संसार परमाणु रूप में था\nपुनः निर्माण के समय पुनः सूक्ष्म रूप से स्थूल रूप में जुड़ जाता है\nप्रकट होते हैं.",
  "8.19": "भूत ग्रामः सः एव अयं भूत्वाभूत्वा प्रलीयते |\nरात्रि अगामे पार्थ प्रभावति अहा अगामे हो सकता है - पार्थ, पंचभूतों का एक ही समूह\nजब रेत फिर से जन्म लेती है, तो वह भगवान के अधिकार में विलीन हो जाती है; दिन के दौरान पैदा हुआ.\n\nसृष्टि का सार कभी नहीं बदलता। वही पंचभूत सृजन और विनाश में लौट आते हैं\nएक पहिये में घूमना. अनंत जीव, जो मोक्ष के योग्य नहीं हैं, वे भी इस चक्र में घूमते हैं। लेकिन\nजो जीवन भगवान का है वह इस चक्र से परे है।",
  "8.20": "परः तस्मात् तु भवः अन्यः अव्यक्तः अव्यक्त सनातनः।\nयः सः सर्वेषु भूतेषु नष्टत्सु न विन्यशति - इस दृश्य जगत से भिन्न,\nसर्वदा विद्यमान तत्त्व अव्यक्त है। यह तब भी मौजूद रहता है जब सभी राक्षस ख़त्म हो जाते हैं।\n\nजो भगवान सबसे परे है, वह विचित्र और महान है। वह शाश्वत है. हर समय\nसमस्त नैतिक जगत् के नष्ट हो जाने पर भी निर्विकार, सर्ववैदिक प्रतिपाद्य होना\n\nभगवान ही एकमात्र सिद्धांत है जो नष्ट हुए बिना सब कुछ समाहित कर लेता है।",
  "8.21": "अव्यक्तः अक्षरः इति उक्तः तम अहुः परमं गतिम् |\n\nयं प्राप्य न निवर्तन्ते तत् धाम परमं मम - यह अव्यक्त तत्त्व ही 'अक्षर' है।\nभगवान कहते हैं. उसे अंतिम कहा जाता है। जो लोग उसे प्राप्त करते हैं वे कभी वापस नहीं लौटेंगे।\nवह मेरा सबसे पुराना रूप है.\n\nयह अव्यक्त दर्शन ही वह सर्वोच्च स्थान है जहाँ सभी को जाकर सम्मिलित होना चाहिए। वह 'अक्षर' शब्द का मुख्य अर्थ है।\nसर्वव्यापी, सर्वव्यापी, जो चाहे दे,\nसर्वशक्तिमान, इंद्रियों का अनुभवकर्ता, सर्वशक्तिमान-भगवान. फिर से उससे जुड़ें\nपरिवार में दोबारा जन्म लेने की जरूरत नहीं है. कृष्ण कहते हैं, ''वह मेरा पुराना रूप है.''\n\nपुरुषः सः पार्थ भक्त्या अग्यस्त्रानया |\nयस्यान्थास्थानि भूतानि येन सर्वमिदं ततम् ॥202॥\n\nपुरुषः सा; परः पार्थ भक्त्या तु अनन्या य |\n\nयस्य अंतस्थानि भूतानि येन सर्वं इदं ततम् - पार्थ, वह परम व्यक्तित्व।\nकेवल समर्पित भक्ति के लिए पर्याप्त है. उसके अंदर बिजली की दुनिया है. वह यह सब स्वीकार करता है\nखड़ा है\n\nभगवान सर्व शब्दवाच्य जो इस ब्रह्मांड में और पिंडदान नामक पुरा में सब कुछ नियंत्रित करते हैं।\nऐसे भगवान को लुभाने का एकमात्र तरीका भक्ति है। भक्ति के बिना क्या है?\n\nउसे कर्म से भी नहीं जोड़ा जा सकता। केवल ईश्वर प्राप्ति और मोक्ष के लिए\nसाधना अद्वितीय एकपत्नीत्व है। बाढ़ के समय, सृष्टि के समय उसके शरीर की सभी चीज़ों की रक्षा करें\nजो कार्य करना है उसे दिन के अनंत समय में अन्तर्यामी होकर करो\nउस प्रभु से सदैव प्रेम करो जो भरता है और रक्षा करता है।\n\nअत: अंत में शरीर त्याग करते समय भगवान का ध्यान कैसे करें\nकृष्ण, जिन्होंने छवि हमारे सामने रखी है, शरीर छोड़ने के बाद भगवान की ओर यात्रा करते हैं\nइस अध्याय के अगले भाग में मार्ग बताया जायेगा।",
  "8.22": "पुरुषः स परः पार्थ भक्त्या लभ्यस्त्वनन्यया ।\nयस्यान्तःस्थानि भूतानि येन सर्वमिदं ततम् ॥\n\n'हे पार्थ, वह परम पुरुष — जिसमें सब भूत अन्तःस्थ हैं, जिससे यह सब व्याप्त है — अनन्य भक्ति से प्राप्त होता है।'\n\n'अनन्यया भक्त्या' — अनन्य भक्ति — यही एकमात्र मार्ग। 'यस्यान्तःस्थानि भूतानि' — जिसमें सब भूत स्थित। 'येन सर्वमिदं ततम्' — जिससे सब व्याप्त। यह ध्यान-योग अध्याय का परम निष्कर्ष।",
  "8.23": "यत्र काले तु अनावर्तिम वर्धम् च एव योगिनः |\n\nप्रयतः यान्ति तम कालम् वक्ष्यामि भरत ख़ुशभा - भरत श्रेष्ठ, किस काल के देवता\nजो लोग रास्ते पर चलते हैं वे वापस नहीं आते और किस तरह से वापस आते हैं\nआइए मैं आपको समय की देवी के बारे में बताता हूं।\n\n''जो मनुष्य काल के अधीन होकर शरीर का त्याग करता है, उसके जीवन पर कौन से देवता शासन करते हैं।''\nआगे बढ़ाया जाएगा; जो लोग किस रास्ते पर जाते हैं वे फिर से धरती पर जन्म लेते हैं\nऔर जो भी सीधे मोक्ष प्राप्त करता है, वह मैं तुम्हें बताऊंगा, ”कृष्ण कहते हैं।\nइधर कुछ लोग समय शब्द को गलत भी समझते हैं। इस श्लोक में कृष्ण समय के बारे में बताते हैं\nवह समय नहीं है. \"काल\" देवताओं का शरीर है जो बलिदान किये गये शरीर के जीवन पर शासन करते हैं।",
  "8.24": "अग्निः ज्योतिः अहः शुक्लः षट् मसाः उत्तरा अयनम्,।\n\nतत्र प्रयतः गच्छन्ति ब्रह्म ब्रह्मविदः जनः -अग्नि और ज्वाला [म्बिब्बरु वाहनिया]\nबच्चे]. [दोपहर की देवी के साथ] दिन की देवी, [पूर्णिमा की देवी के साथ] शुक्लपक्ष की देवी,\nउत्तरायण के छह महीनों के देवता, [देव संक्रांति के साथ] उत्तरायण के देवता- ई\nजो लोग मार्ग पर चलते हैं, जो प्रभु को जानते हैं, वे प्रभु से जुड़ जाते हैं; वापस नहीं आएगा.\n\nवैश्वानर (प्रा.)\nअग्नि और ज्योति, अग्नि के पुत्र)। ये देवता जीवन का स्वागत करते हैं और उसे आगे भेजते हैं।\nआगे के जीवन का स्वागत प्रकाश और दोपहर की देवियों द्वारा किया जाता है। यह सच्चा प्रकाश है\nअनुभव के साथ जीव आगे बढ़ता है और शुक्लपक्ष तथा पूर्णिमा के देवता तक पहुँच जाता है। वह\nफिर संक्रांति के देवता, उत्तरायण के साथ-साथ उत्तरायण के छह महीने के देवता\nजीवन को ईश्वर के पास भेजता है। इस प्रकार जो कोई इस मार्ग पर चलेगा वह कभी नहीं चलेगा\nवापस नहीं आता - शाश्वत सत्य प्रभु से मिल जाता है।",
  "8.25": "धूमः रतिः तदा कृष्णः षट मसा दक्षिणायनम् |\n\nतत्र चंद्रमासम ज्योतिः योगी प्राप्य निवारते - धुएं की देवी, अंधेरे की देवी,\nकृष्णपक्ष के देवता, दक्षिणायन के छह महीनों के देवता, और दक्षिणायन के देवता - इस प्रकार\nजो साधक मर गया है वह चांदनी की दुनिया से जुड़ जाता है और वापस आ जाता है।\n\nमोक्ष के अयोग्य शरीर से बाहर आने पर जो देवता उसका स्वागत करते हैं, वे धूम्र और देवता हैं\nअँधेरे की देवी. उसके बाद कृष्णपक्ष के देवता; फिर दक्षिणायन और 'दक्षिणायन छह\nमहीनों के देवता सोमलोक में जीवन प्रदान करते हैं। जीव यहाँ अपना पुण्य खो देगा\nखुशी को तब तक महसूस करें, जब तक कि आप बादलों में वापस शामिल न हो जाएं, बारिश के माध्यम से धरती पर न पहुंच जाएं\nपुरुष के शरीर के माध्यम से स्त्री के गर्भ में प्रवेश करता है और पुनः पृथ्वी पर जन्म लेता है।",
  "8.26": "शुक्ल कृष्ण गति हि एत जगतः शाश्वते मते।\n\nएकया याति अनावर्तिम अन्यया अवतारथे रे - ये दुनिया के सफेद और काले रास्ते हैं।\nविज्ञान का निष्कर्ष यह है कि अनुगला है। एक से वापस नहीं आना है. दूसरे से\nफिर से लौटता है.\n\nइस प्रकार एक प्रकाश का श्वेत मार्ग है जो मोक्ष की ओर जाता है और दूसरा संसार की ओर वापस जाता है\nअँधेरे का काला रास्ता. ये दोनों मार्ग अनंत और अनंत में सभी जीवनों के लिए समान हैं\nसिस्टम जैसा होना चाहिए. जो प्रकाश के मार्ग पर जाता है, वह लौटकर नहीं आता; जो अन्धकार के मार्ग पर जाता है, वह लौटकर नहीं आता\nवापस आऊंगा",
  "8.27": "न एते सृति पार्थ जनन योगी मुह्यति कश्चन |\nतस्मात् सर्वेषु कालेषु योगयुक्तः भव अर्जुन-पार्थ, इन मार्गों का अनुष्ठान क्या है?\nयहां तक ​​कि पेशेवर भी भटकते नहीं हैं. इसलिए, हे अर्जुन, हर समय बुद्धिमानी से चलना।\n\nइन दोनों तरीकों की उचित समझ होने के बाद आपको किस रास्ते पर चलना चाहिए\nजानकर अपने-अपने प्रशंसक देवताओं के साथ आगे बढ़ना चाहिए। संबंधित प्रशंसक देवता\nवे अलग-अलग स्तर पर आते हैं और जीवन को आगे ले जाते हैं। इस वजह से ख़त्म\nसमय की स्मृति में पथ और प्रशंसक देवताओं का चिंतन आवश्यक है। यह जानकर\nयदि इसका पालन और कार्यान्वयन किया जाए तो किसी भी अभ्यासकर्ता के लिए कोई भ्रम नहीं रहेगा। तो कृष्ण\nवह अर्जुन से कहते हैं - 'हमेशा इस योजना का पालन करें।'",
  "8.28": "वेदेषु यज्ञेषु तपसु च एव दनेषु यत् पुण्यफलं प्रदिष्टम्।\n\nअयेति तत् सर्वं इदं विदित्वा योगी परम स्थान उपैति च आद्यम्-वेद\nयदि तुम पढ़ते हो, यज्ञ करते हो, तप करते हो, दान देते हो, तो क्या पुण्य है?\nएक अभ्यासी जो इसे जानता है वह कही गई सभी बातों से परे है; सबसे पहले वरिष्ठ साइट\n\nकार्यभार संभाला\n\nअंत में, कृष्ण कहते हैं - सबसे बड़ा ज्ञान यह समय का अंत है\nवह जागरूकता. सभी शास्त्रों में यज्ञ-दान-तप के माध्यम से पुण्य ने जो कहा है, उसका यही अंत है\nसमय की मृत्यु के रहस्य की जागरूकता इन सभी पुण्य फलों से परे है। तो सबसे बड़ा\nउपलब्धि एक अंतिम समय का विचार है। इसी कारण मृत्यु के लिए जीवन से अधिक विचार की आवश्यकता होती है।\n\nमृत्यु शुभ नहीं है. यह हमारा भ्रम है कि मृत्यु एक दुखद अनुभव है। शरीर के अंदर होते हुए भी शारीरिक\nशरीर के सारे कष्ट जीवन से जुड़े हुए हैं। मृत्यु का अर्थ है इस स्थूल शरीर से मुक्ति।\nतो सूक्ष्म शरीर में जीवन पिंजरे से बाहर आता है और आकाश में स्वतंत्र रूप से उड़ता है\n\nपक्षी की तरह इसी कारण से मृत्यु का भय पीछे छूट जाता है और अंतिम समय में शुभता का उदय होता है\nदेवता अनुसन्धान हमारे जीवन में निरंतर बना रहना चाहिए।\n\nइति अष्ट मोध्याय\nआठवां अध्याय समाप्त हो गया\n\nक्या यह सच है?\n\nअध्याय नौ\n\nज्ञान का अर्थ है ईश्वर के प्रति जागरूकता । हमारा मन ईश्वर की ओर जाता है जो सब कुछ जानता है\nज्ञान प्रवाहित होता है. ईश्वर को सर्वोच्च, सर्वज्ञ, सर्वज्ञ आदि जानना ही ज्ञान है। वह\nफिर उसके विवरण के प्रति जागरूकता ही विज्ञान (विशिष्ट ज्ञान) है। ज्ञान ईश्वर का गुण है.\nभगवान ज्ञानी, आनंदमय, सुंदर, दयालु आदि हैं\nसंपूर्णता को विस्तार से समझना एक विज्ञान है । हम हैं\nईश्वर को पूर्णतः नहीं जाना जा सकता। लेकिन प्रत्येक जीवन अद्वितीय है\nजागरूकता का एक स्तर है. हर किसी को एक जैसी बात नहीं पता चलती. उनके स्तर के अनुसार\nईश्वर को जानना विज्ञान है । इस प्रकार प्रभु\nयदि ज्ञान से परम को जानना है तो वह परम तत्त्व ही उसका विस्तार है\nउनकी योग्यता के अनुसार उन्हें विभिन्न कोणों से देखना ही विज्ञान है। इस प्रकार\nइस तथ्य के करीब पहुंचकर कि ईश्वर अस्तित्वहीन होने के बजाय अजीब है\nसाकार हो जायेगा.\n\nसातवें अध्याय में कृष्ण ने अर्जुन से कहा- ''मेरी महानता का जाना जाना उसका बीज नहीं है।\nमैं तुम्हें पूरी बात बताऊंगा. ये जानना इस मामले में फिर अलग है\nकुछ भी जानना बाकी नहीं है” (ए-7, श्लो-2)। इस अध्याय में फिर से यहाँ\nज्ञान विज्ञान के बारे में बताते हैं! . ऐसा क्यों कृष्ण भूल गए कि उन्होंने पहले क्या कहा था?\nसमझा रहे हैं?! नहीं, उसके कुछ कारण हैं। वह एक बार कही गई बात को क्यों दोहरा रहे हैं?\n\"एक अलग आयाम में बोलना\"। तो यहाँ जो कहा गया है वह पहले कही गई बात की व्याख्या है\nऔर रचनात्मकता. वहां संक्षेप में बताया गया है, यहां दूसरे तरीके से कुछ नए अर्थ दिए गए हैं\nकृष्ण बताते हैं. यदि हम ईश्वर का मूल चिंतन एक बार अपने मन में कर लें\nनहीं जा रहा! अगर आप इसके बारे में सोचते रहेंगे तो यह कहीं न कहीं चला जाएगा! जब पूछा गया,\nजब आप इसे पढ़ते हैं तो आपको लगता है कि आप सब कुछ जानते हैं। लेकिन कुछ देर बाद आपको याद भी नहीं रहता!\nइसके लिए आपको संस्करण बनाते समय एक अलग आयाम में सोचना होगा। इस अध्याय में कृष्ण\nपहले बताए गए ज्ञान को समझने का हमारा तरीका अलग-अलग पहलुओं से अलग-अलग है\nआयाम में समझाता है.\n\nयुद्ध के मैदान में एक सैनिक के रूप में खड़े व्यक्ति की मानसिक स्थिति आध्यात्मिक चिंतन के लिए बहुत अनुकूल होती है\nकरीब होगा. इस वजह से, कृष्ण ने युद्ध के मैदान में आध्यात्मिकता को उजागर किया। अर्जुन बहुत है\nएक महान ऋषि. सदैव भगवद चिंतन करना ही देवता है। उसके अलावा\nयुद्ध के मैदान में रुकना, मानसिक रूप से उसे जन्म और मृत्यु की इस लीला से परे ले जाना,\n\nमानसिक रूप से तैयार हो जाओ - कृष्ण वेदांत कहते हैं। ऐसे क्षण में भगवान के पास\nअगर बता दिया जाए तो जल्द ही दिल भर जाएगा. यहां तक कि हम अपने दैनिक जीवन में भी वही हैं-\nग़लत, धर्मों का टकराव जारी रहेगा. ऐसे युद्ध की स्थिति में हमारे लिए\nअध्यात्म को समझना.\nभगवान का वचन",
  "9.1": "भगवान उवाच- भगवान ने कहा:\n\nइदं तु ते गुह्यतमं प्रवक्ष्यामि अनुसूयवे।\n\nज्ञानं विज्ञान सहितं यत् ज्ञात्वा मोक्षसे अशुभत् - यह भी बहुत है\nछुपाने के लिए कुछ. बिना चिल्लाए कह रहा है कि वह सराहना कर रहा है: जानें और जानें। यह\nजानकर मैं जाल से छूट जाऊँगा।\n\nकृष्ण कहते हैं: “मैं तुम्हें भगवद के सिद्धांत के बारे में फिर से बताऊंगा; सबसे गुप्त पूजा\nमैं आपके सामने तथ्य उजागर कर रहा हूं.' यह हर किसी के लिए खुला नहीं है.\nजो लोग भगवान की पूजा करने की अनोखी इच्छा रखते हैं, उनके लिए मेरे पास भगवान के अलावा कुछ भी नहीं है।\nयह उन लोगों के सामने कहा जाना चाहिए जिनका मन ना कहने का है और जो भगवान के लिए तरसते हैं\nवाणी सबसे गुप्त रहस्य करने वाली बात। \"मैं तुम्हें यह बता रहा हूँ\"\nकृष्ण कहते हैं. इधर अर्जुन इस विषय को जानने के लिए जिज्ञासु एवं योग्य हैं, अतः कृष्ण\nवह उसे यह महत्वपूर्ण बात बताता है। केवल वे ही जिनके पास योग्यता है और सुनने की इच्छा है\nयही शिक्षा दी जानी चाहिए. यह हर किसी को नहीं दिया जाता.\n\nयहाँ कृष्ण ने \"अनसूयावे\" शब्द का प्रयोग किया है। एक आदमी जो वेदांत पढ़ता है और\nजो गुण वेदांत का अध्ययन करने के बाद भी मौजूद रहने चाहिए (ए63) - \"अहंकार\" ।\nवेदांत का अध्ययन करने से कोई लाभ नहीं है। वेदांत का अध्ययन करने से पहले अहंकार नहीं करना चाहिए।\nयदि आप जानते हैं कि \"मैं भगवान के सामने कुछ भी नहीं हूं\", तो कोई घमंड नहीं होगा। वेदांत पढ़ें “मैं हूं\nयदि 'महान ज्ञान' का अहंकार आ जाए तो यह ईश्वर को पढ़ने और खो देने जैसा है। लेकिन आज हम हैं\nहम किसी न किसी अहंकार के अधीन हैं। ज्ञान का अभिमान, शक्ति का अभिमान, धन का अभिमान\nअहंकार, सुंदरता का अहंकार, यौवन का अहंकार, ऐसी बहुत सी चीजें हैं हम\nभूतिया. हम वेदांत को जानने के योग्य तभी हैं जब हम इससे छुटकारा पा लेंगे\n\nप्राप्त किया जायेगा. जब तक हम अहंकार से भरे हैं, वेदांत हमारे लिए है\nउपयोगी नहीं.\n\nज्ञान का अभिमान सभी अभिमानों में सबसे खतरनाक है। हालाँकि, अन्य अहंकारों का अंत होता है\nज्ञान के अहंकार का कोई अंत नहीं है. ''यदि 'मैं विद्वान हूं' का अभिमान मन में आ जाए तो वह महान है\nमनहूस! \"ईर्ष्या\" अहंकार की संतान है। यह ईर्ष्या वह आग है जो हमें जला देती है। उसके लिए\nकन्नड़ में इसे 'हॉट्टेकिचू' कहा जाता है। यह हमारे व्यक्तित्व को नष्ट कर देता है। उन लोगों के लिए\nवेदांत बेकार है. “तुम्हें ईर्ष्या नहीं है, इसीलिए तुम्हारे पास यह रहस्य है\nकृष्ण कहते हैं.\n\nयुद्ध के मैदान में खड़े व्यक्ति के लिए ईर्ष्या रहित होना बहुत बड़ी बात है। नफरत-ईर्ष्या\nयुद्ध के मैदान में अहंकार हमेशा प्रचुर मात्रा में होता है। जो इस पर विजय प्राप्त कर लेता है वह सबसे महान है।\nयहाँ कृष्ण कहते हैं: “यह जानकर, आपका मन भगवान के प्रति शुद्ध है\nआप जो चाहते हैं वह संभव है।” जब ज्ञान आता है तो हमारे अंदर का मैल धुल जाता है और मन दूर हो जाता है\nशुद्ध हो जाता है. हमारा सबसे बड़ा धन आनंदमय स्वच्छ मन है। ऐसे मन में\nभगवान प्रकट होते हैं. अहंकार-ईर्ष्या से रहित मन \"वासुदेव\" इत्यादि है\nमन द्वारा देखे गए भगवान \"वासुदेव हैं। शुद्ध मन से ज्ञान, ज्ञान से आनंद।\"\nआनंद की इस अवस्था से, पंचभौतिक शरीर और संसार से मुक्ति और\nमोक्ष\n\nहमारे पास तीन वर्ण हैं जो पंचभूति हैं। इन तीन बाड़ों के भीतर आत्मज्ञान\nवहाँ स्वयं है. लिंगशरीर, सूक्ष्म शरीर और स्थूल शरीर आत्मा को ढके हुए हैं\nबाड़े. हम इन तीनों ने अपनी कमीजें उतार दीं और अशुभ से मुक्त हो गए,\nयहां कृष्ण 'मोक्ष्यसे$शुभत्' भगवान के समक्ष रूपात्मक वास्तविक अवस्था में खड़े हैं।\n[हम मंदिर में भगवान के सामने अपनी शर्ट उतारते हैं- \"भगवान्।\"\nसामने रखे सभी बाड़ों को भगवान के सामने हटाकर सुखाया जाएगा\nका मुख्य अर्थ है. हमने भगवान के सामने जो भी मुखौटे लगाए हैं वे सभी उनके हैं\nऔर खुलना चाहिए. तब वह अपने आप को हमारे सामने खोल देता है।] इस प्रकार पंचभौतिका\nभगवान ने अर्जुन को शरीर से मुक्ति और मोक्ष का ज्ञान दिया\nआइए देखें कि निम्नलिखित श्लोक में क्या कहा गया है।",
  "9.2": "राजविद्या राजगुह्यं पवित्रं इदं उत्तमम् |\n\nप्रत्यक्ष अवगमं धर्मं सु सुखं कर्तुम् अव्यम् - यह अनुभूति का राजा है। रहस्यों का\nएक रहस्य बाकी सब असली है. आँख में आँख डालकर देखने का तरीका. धारक के बारे में सब कुछ. जश्न मनाने के लिए\nआराम न बुझने वाला.\n\nकृष्ण, उस आध्यात्मिक विज्ञान के बारे में बात करते हुए जिसका उन्हें आगे प्रचार करना था, कहते हैं: “यह\nसभी विषयों में प्रमुख शिक्षा; सबसे गुप्त और सबसे पवित्र विज्ञान के रूप में\"। 'जीवित'\nशब्दवाच्य (इंद्रियों का नियंत्रक) भगवान को प्रकट करता है; दुनिया के\nयह एक विज्ञान है जो सीधे भगवान, धारण करने वाली शक्ति से संबंधित है, और साक्षात भगवद का विषय है। यह\nविद्या को जानकर भगवान को प्रसन्न करना बहुत आसान है। क्योंकि प्रभु सबसे बड़ा है\nज्ञान प्रिय है. ईश्वर के ज्ञान के मार्ग के समान कोई मार्ग आसान नहीं है। \"यह\nकृष्ण कहते हैं कि मार्ग कभी व्यर्थ नहीं जाता, इसलिए ज्ञान का मार्ग कभी व्यर्थ नहीं जाता।",
  "9.3": "अश्रद्धानः पुरुषः धर्मस्य अस्य परन्तपः।\nअप्राप्य मम निवर्तन्ते मृत्यु संसार वार्मानि -- परंतप, जो इस कदम में विश्वास नहीं करते थे।\nबहुत से लोग मुझ तक पहुंचे बिना मौत के भंवर में फिसल जाएंगे।\n\nकृष्ण, जिन्होंने पहले ईर्ष्या के बारे में बात की थी, यहाँ एक और बहुत महत्वपूर्ण गुण के बारे में बात करते हैं - वही\n'परिश्रम'. जो मेहनती नहीं, उनसे कुछ भी कहना व्यर्थ है। हमारे लिए किस पर\nयदि भक्ति नहीं है तो हमारा मन उसे स्वीकार नहीं करेगा। एक बात हम समझते हैं\nयदि हम यह करना चाहते हैं तो हमें इसके प्रति प्रयत्नशील रहना होगा। \"ऐसी कुछ बातें हो सकती हैं जो मैं नहीं जानता,\nक्योंकि ऐसी बहुत सी चीज़ें हैं जो मैं नहीं जानता\" - जानना ईमानदारी की पहली बात है\nसीढ़ी । हमें अपनी अज्ञानता के प्रति सचेत रहना चाहिए। तब मुझे पता नहीं था\nजानने का परिश्रम आता है। पहले हमें अज्ञात के बारे में जानना चाहिए; उसके बाद\nहमें इस संभावना के बारे में जागरूकता की आवश्यकता है कि जो कुछ हम नहीं जानते वह सत्य हो सकता है;\nइसे जानने के लिए परिश्रम की आवश्यकता होती है। इसे जानने से यह तथ्य ज्ञात हो जाता है कि कोई अज्ञात वस्तु है।\n\nज्ञान के पथ पर चलने वाले साधक को बुनियादी आस्था की आवश्यकता होती है। अविश्वासी के सामने क्या है?\nयह कहने से कोई फायदा नहीं है. कृष्ण यहाँ यही कहते हैं: “उन लोगों के लिए जिनके पास कोई भक्ति नहीं है\nकोई सच्चाई नहीं है. जो लोग संसार के पालनकर्ता, भगवान में विश्वास नहीं करते हैं, वे वे हैं जो भगवान में विश्वास नहीं करते हैं\nनहीं है. “वे आत्मा को नष्ट करने वाली तमसा या संसार के भंवर में शामिल हो जाते हैं\nकृष्ण कहते हैं.\n\nइस श्लोक में परंतप विशेषण का प्रयोग किया गया है। इसका सतही अर्थ शत्रु है\nएक ज्वलंत बहादुर बनने के लिए. हमारे जीवन के युद्ध में हमारे शत्रु हैं अज्ञान, जुनून,\nकाम, क्रोध आदि ऐसे शत्रुओं के प्रति प्रत्येक साधक समर्पित रहता है\nवह धधकती हुई आग बन जानी चाहिए, वह जलती हुई आग बन जानी चाहिए।",
  "9.4": "मया ततम् इदं सर्वं जगत् अव्यक्त मूर्तिना |\nमत स्थानि सर्वभूतानि न च अहं तेषु अवस्थितः - यह सारा संसार मुझ मैदोरा से है।\nपूर्ण है यहां जो कुछ भी है वह सब मुझमें निवास करता है। मैं उनके पक्ष में नहीं हूं.\n\nकृष्ण कहते हैं: \"मैं वह अन्तर्यामी व्यक्ति हूँ जो पूरे विश्व में व्याप्त है।\" यहाँ प्रयोग किया जाता है\nअव्यक्तमूर्ति शब्द में अव्यक्त और मूर्ति विपरीत शब्द हैं। अव्यक्त\nइसका मतलब है कि जो दिखता है और जिसका कोई रूप नहीं है। मूर्ति का अर्थ है आकार और स्वरूप। भगवान आकाश की भाँति सर्वत्र विद्यमान हैं\nव्यापक, अव्यक्त, लेकिन वह सर्वव्यापी मूर्ति है। एक के बाद एक\nवह अनंत रूपों वाला भगवान जो एक रूप और दूसरे पदार्थ से परिपूर्ण है। कृष्ण कहते हैं:\n\"मैं हर चीज़ का आधार हूं, यह पूरी दुनिया मुझ पर निर्भर है। लेकिन मैं हूं।\"\nस्वतंत्र होकर मैं सर्वत्र परिपूर्ण हूँ।” वह है।",
  "9.5": "न च मत स्थानि भूतानि पश्य मेय योगं ईश्वरम् |\n\nभूतभृत न च भूतस्थः मम आत्मा भूतभावनः - मेरे पास सब कुछ है; मेरे पास कोई नहीं है\nगोंद मेरी शेष महिमा को देखो। मेरे रूप ने इन्हें आकार दिया है. समय की सलाह दी जाती है.\nहालाँकि इनमें नहीं.\n\nहमें इस बात पर ध्यान देना होगा कि कृष्ण पिछले श्लोक में और इस श्लोक में क्या कह रहे हैं। जाहिरा तौर पर\nये विरोधाभासी बयान लगते हैं. ऐसा कृष्ण कहते हैं\n\"मेरी शक्ति को जानो, मैं सभी चीजों में हूं - लेकिन कुछ भी नहीं। सभी चीजें मुझमें हैं\nलेकिन मेरे पास कोई नहीं है. यह ईश्वर की अकल्पनीय शक्ति के प्रति एक दृष्टिकोण है। भागवत में\nजैसा कि कहा जाता है “जगत में जिसे हम विपरीत कहते हैं वह शुभ है।\nयदि यह धर्म है तो यह ईश्वर में लागू होता है'। यहाँ यह विपरीत धर्म कहकर\nभगवान जो बता रहे हैं.. उसका मतलब है. - मेरे पास सबकुछ है। लेकिन। जो\nमामाकारवु । इसका मतलब यह है कि यह भगवान की अनासक्ति को दर्शाता है। वह\nकुछ भी नहीं चिपकता. वह किसी चीज़ का सहारा नहीं लेता और किसी चीज़ पर दोषारोपण नहीं करता\nउसके पास यह नहीं है. कृष्ण कहते हैं: \"यह मेरी दिव्य शक्ति है\"। यह ईश्वर की सर्वशक्तिमत्ता है।\n\nकृष्ण एक बार फिर इस बात को संक्षेप में समझाते हैं (0गा60) \"भूतभृत नच भूतस्थः\"।\nयहां 'नाचा' शब्द का प्रयोग दो शब्दों के बीच में दहलीज पर रखे दीपक की तरह किया गया है। इसका मतलब है\nइस प्रकार: “मैं सभी जीवित प्राणियों से भूतभृत-आवेशित हूं और नचभूतभृत-शून्य से आवृत हूं;\nमैं भूतस्थ हूं-सभी जीव मुझमें हैं और मैं नचभूतस्थ हूं-मैं किसी भी चीज में नहीं हूं।”\n\nकृष्ण कहते हैं: \"मम आत्म भूतभावनः\"। अर्थात् इस संसार की उत्पत्ति-स्थिति-विनाश।\nनियम-ज्ञान-अज्ञान-बंध-मोक्ष सभी भगवान से हैं। वह ज्ञानानन्द स्वरूप हैं। प्रभु\nउसका शरीर अलग नहीं है; उनके गुण भी अलग नहीं हैं. वे सभी बरकरार हैं. यह\nपंचभौतिक और त्रिगुण्य के दायरे में हम कल्पना नहीं कर सकते।\n\nकृष्ण एक दृष्टांत के माध्यम से आगे बताते हैं कि भगवान कैसे सर्वव्यापी हैं\nवह श्लोक में बताते हैं.",
  "9.6": "यथा आकाशस्थितः नित्यं वायुः सर्वत्र गह महान्।\nतथा सर्वाणि भूतानि मत स्थानि इति उपाधारय - नित्य विद्यमान वायु\nसंसार के सभी अस्तित्व अगासा की तरह मुझमें हैं। कल्पना कीजिए.\n\nहवा हर जगह है. यह अंदर और बाहर दोनों है. हम हवा को नहीं देख सकते. हवा इस आकाश में है\nपूर्ण है इस प्रकार भगवान हमारे अंदर और बाहर पूर्ण रूप से विद्यमान हैं। लेकिन कुछ नहीं\nउसके पास यह नहीं है. इस संसार का सारा अस्तित्व प्रभु में है।",
  "9.7": "सर्वभूतानि कौन्तेय प्रकृतं यान्ति मामिकम् |\nकल्पक्षये पुनस्तानि कल्पादौ विसृजाम्यहम् 17\n\nसर्वभूतानि कौन्तेय प्रकृतं यान्ति मामिकम् |\nकल्पक्षये रे तनि कल्प अदौ विसृजामि अहम् - सृष्टि के अंत में सभी चीजें मेरी हैं।\nयह मूल प्रकृति का है. मैं उन्हें सृष्टि के आरंभ से ही निर्मित करता हूँ।\n\nसृष्टि के 31,104 अरब वर्षों के बाद, महाप्रलय। यह चतुर्विध ब्राह्मणों में से एक सौ है\nवर्ष इसे कल्पक्षय कहा जाता है। इस महाप्रलय में सत्यलोक से सब कुछ अपना है\nवे स्थूल रूप को खो देते हैं और सूक्ष्म रूप में भगवान की अधीन प्रकृति में शामिल हो जाते हैं।\nसभी जीव भी अपना स्थूल रूप खोकर भगवान के गर्भ में प्रविष्ट हो गये\nपुनः जुड़ जाता है. 31,104 हजार करोड़. वर्ष प्रलयकाल है। फिर वापस इस रचना पर\nबनाया जाएगा. अर्थात यह सूक्ष्म रूप से स्थूल रूप में लौट आता है।",
  "9.8": "प्रकतुरं स्वं अवस्ताभ्य विसृजामि अवरापुणः।\nभूत ग्रामं इमाम कृत्स्नं अवशं प्रकृतिः वषत् - प्रकृति द्वारा निर्धारित।\nपरतंत्र [मेरे मन में] इस भंवर ब्रह्मांड में मैं अपनी प्रकृति का बार-बार उपयोग कर रहा हूं\nमैं निर्माण करूंगा\n\nप्रलय के समय में, निर्जीव और जीव सूक्ष्म जगत में भगवान के होते हैं\nवह वशीभूत प्रकृति का उपयोग करके पुनः सृजन करता है। सृष्टि और विनाश का यह चक्र ईश्वर का है\nनिरंतर. ऐसे अनन्त ब्रह्माण्ड अतीत में बनाये गये थे और अब भी अनन्त हैं\n\nयह समय के साथ चलता रहता है. इस कारण से, भगवान अनंत ब्रह्मांड के स्वामी हैं\n(इसकी चर्चा हमने सातवें अध्याय में विस्तार से की है)।\n\nक्या कर्म उस ईश्वर से जुड़ा नहीं है जो निरंतर निर्माण और विनाश कर रहा है? निम्नलिखित श्लोक में\nआइए देखें:",
  "9.9": "न च मम तनि कर्माणि निबद्धदन्ति धनंजय।\n\nउदासीनवत् असीनं असक्तं तेषु। कर्मसु - धनंजय, मैं करता हूं\nमैं वैसा ही रहूँगा जो ऐसा नहीं करता। मैं उन कर्मों से बंधा नहीं हूं. तो वे कर्म मुझे बांधते हैं\nनहीं डाल सकते\n\nभगवान निर्लिप्त हैं, वे कर्म अपने लिए नहीं करते। कदापि नहीं प्रभु जो स्वतंत्र है\nकिसी भी कर्म को बांधा नहीं जा सकता\nक्या आपको नहीं लगता? \"मैं अपने लिए कुछ नहीं करता और कर्म मुझसे जुड़ा नहीं है।\"\nकृष्ण स्पष्ट कहते हैं.\n\nइस श्लोक में धनंजय विशेषण का प्रयोग हुआ है। अगर आप इस नाम को व्यावसायिक तौर पर देखें\n'उन शत्रु राजाओं को परास्त करो जो प्रजा का धन, संपत्ति लूटते हैं\nधनंजय जो इस पर काबू पाते हैं और लोगों के लिए इसका अच्छा उपयोग करते हैं।' [अपने लिए दूसरे का\nछापा मारकर पैसा कमाने वाला व्यक्ति \"डाकू\" तो माना जाता है, लेकिन धनंजय नहीं।\nमहाभारत में एकलव्य इसी दूसरे समूह से थे। तो उसकी उंगली\nकाट दिया गया और कृष्ण ने स्वयं उसे मार डाला।] आध्यात्मिक का अर्थ है वास्तविक धन\nभगवान। धनंजय को ऐसे भगवान का ज्ञान प्राप्त है। हम सभी अर्जुन की तरह भगवान के हैं\nमोक्ष तभी प्राप्त हो सकता है जब व्यक्ति ज्ञान से समृद्ध हो जाए।",
  "9.10": "मया प्रध्यवनेन प्रकृतिः सुयते स चर आचारम्।\n\nहेतुना अनेना कौन्तेय जगत विपरिवर्तथे-मेरे द्वारा जो सजीव-निर्जीव वस्तुओं का साक्षी बनकर खड़ा था।\nविलीन प्रकृति उड़ती है। कौन्तेय, इसीलिए तो दुनिया बदलती रहती है.\n\nसंसार को बनाने और उसे आकार देने के लिए आवश्यक कच्चा माल प्रकृति है\nप्रकृति लक्ष्मी प्रकृति की सर्वोच्च आत्मा है। संपूर्ण सृष्टि का स्वामी प्रभु,\nक्रिया के पीछे की शक्ति के रूप में, वह जड़ और चेतन प्रकृति के माध्यम से इस सृष्टि का निर्माण करता है।\nसंसार की प्रत्येक वस्तु ईश्वर की एक अनोखी ऊर्जा से ओत-प्रोत है।",
  "9.11": "अवजानन्ति मम मुदः मानुषिम तनुम अश्रितम् |\n\nपरमं भवम् अजन्न्तः मम भूतमहेश्वरम् - मनुष्य के रूप में प्रकट हुए और युद्ध किया।\nवे मेरे साथ एक इंसान की तरह व्यवहार करते हैं और मेरी उपेक्षा करते हैं - उन सभी में से सबसे महान जो कभी भी और हर जगह मौजूद हैं\nमेरे अज्ञानी मूर्ख.\n\nइस श्लोक में भगवान अपने स्वभाव के बारे में कुछ ऐसा बताते हैं जो कोई नहीं बता सकता।\nभगवान के पास पंचभौतिक शरीर नहीं है. भगवान अवतार रूप में हमारे ही समान शरीरधारी हैं\nवह बस ऐसा दिखता है जैसे उसके पास यह है। वहां दिखाई देने वाले शरीर को देखना: भगवान का शरीर हमारे जैसा ही है\nजो लोग इसे अनित्य, एक दिन गिरने वाले शरीर के रूप में जानते हैं - वे स्वभाव से तमस हैं\nकृष्ण कहते हैं कि जो लोग तमस के प्रभाव में आ गए हैं वे बच्चे हैं जिन्हें भगवान की महानता का एहसास नहीं है।\n\nयहां भूतमहेश्वर विशेषण का प्रयोग किया गया है। भगवान की महिमा बताना विशेष है\nशब्द शब्द को सामूहिक रूप से देखें: भूत का अर्थ है सभी जीवित प्राणी। उन्हें शुभकामनाएँ\nब्रह्मा देवता (भूतेश)। इन देवताओं में सबसे महान श्रीलक्ष्मीभूतमहेश हैं)। जैसे कि\nजो भगवान लक्ष्मी के वर हैं, वे \"भूत महेश्वर\" हैं। . वही शब्द बनाएं. यदि आप देखें\nभूत महान- ईश्वर: ब्रह्मा सभी राक्षसों पर महान हैं और उन सभी को नियंत्रित करते हैं।\n, सर्वोच्च-सर्वशक्तिमान भगवान। दूसरा मार्ग है भूत-महत-ईश्वर। यहाँ एक भूत है\nअर्थ: जन्म या मृत्यु के बिना अनंत काल, उत्कर्ष के कगार पर। महत् का अर्थ है: समय में,\nएक ऐसा सिद्धांत जो स्वभाव और गुणवत्ता से उत्तम है। ईश्वर का अर्थ है: सर्वशक्तिमान भगवान। इस प्रकार यह\nयह विशेषण भगवान के गुणों को अनेक रूपों में व्यक्त करता है।",
  "9.12": "मोघ असः मोघकर्मणः मोघज्ञानः विचेतसः।\n\nरक्षासेम् आसुरीं च एव प्रकृतिम् मोहिनीम् श्रीतः - उनकी इच्छा पूरी नहीं होती। कर्म\nनतीजा रोशनी फीकी पड़ जाती है. वे भिन्न हैं; धोखेबाज, राक्षस-असुर\nजो तमस प्रकृति के अधीन हैं।\n\nकृष्ण यहां सोच रहे हैं कि \"भगवान ज्ञानानंद स्वरूप हैं, उनके पास पांच भौतिक शरीर नहीं हैं\"।\nवह जोर देकर कहता है. “यह सोचना पाप है कि भगवान के पास हमारे जैसे पाँच भौतिक शरीर हैं\nरास्ता\" कृष्ण कहते हैं. क्योंकि जो लोग ऐसा सोचते हैं वे सात्विक नहीं हैं। वे कभी नहीं हैं\nभगवद्भक्त नहीं है। ऐसा सोचने वालों की आध्यात्मिक प्राप्ति की सारी इच्छाएँ समाप्त हो जाती हैं\nदेवता उन लोगों से कभी प्रेम नहीं करते जो कहते हैं कि ईश्वर नश्वर है। वे हैं\nबलिदान व्यर्थ हैं. सामान्य तौर पर, आध्यात्मिक उपलब्धि में एक बाहरी व्यक्ति के रूप में उनकी स्थिति क्या है?\nइच्छा पूरी नहीं होती.\n\nजो लोग सात्विक विचार नहीं रखते या तमस से प्रभावित होते हैं वे भगवान से इसी प्रकार की भूल करते हैं\nसोचने से काम चलेगा उनके पास सोचने की शक्ति नहीं है। चाहे उसने कोई भी विज्ञान पढ़ा हो\nकोई फायदा नहीं. उनका मन आध्यात्मिकता को नहीं समझता। “ये राक्षस हैं या\nकृष्ण कहते हैं, ''असुर हैं। राक्षस स्वभाव से तामसिक होते हैं; असुर होते हैं\nराजस - जो कामुक भोग में मर्दाना दिखते हैं। उसके प्रभाव से\nजो लोग अपनी विचारशीलता खो चुके हैं वे भी ऐसा ही सोचते हैं। यह उनके लिए हमेशा स्वाभाविक है\nविचार नहीं आता. उसे हमेशा हत्या की चिंता सताती रहती है.",
  "9.13": "महा आत्मनः तु मम पार्थ दैवीम प्रकटुरं अश्रितः |\n\nभजन्ति अनन्य मनसः ज्ञात्वा भूत आदिम अव्यम् - हे पार्थ, सात्विक स्वभाव के अग्रज\nमनुष्य यह जानकर कि मैं समस्त नाशवान ब्रह्माण्डों का अविनाशी कारण हूँ, उसी प्रकार मैं ही हूँ\nपूजा करता है\n\nपिछले श्लोक में आसुरी और आसुरी प्रकृति का वर्णन करने वाले कृष्ण यहाँ दिव्य हैं\nचरित्र का वर्णन करता है. दैवीय प्रकृति वाले सदैव ज्ञान, प्रकाश और सत्य के मार्ग पर चलते हैं\nजो लोग यात्रा करते हैं वे भगवान को जानने के लिए भाग्यशाली हैं। भगवान ने उन्हें \"महात्मा\" कहा।\nवह कहता है। भगवान को उससे बड़ा प्रेम है. कृष्ण कहते हैं, “उन्होंने मुझे अद्वितीय बनाया\nवह मन से जप करता है।” हम भगवान से प्यार करते हैं और भगवान हमसे प्यार करते हैं\nप्रेम करना ही सच्चा भजन है। जो लोग स्वभाव से दिव्य हैं वे भगवान को छोड़कर नाशवान हैं।\nवे इस सत्य को जानते हैं कि एकमात्र ईश्वर ही शाश्वत सत्य है। भगवान और दुनिया में उनका\nकेवल ज्ञान ही अपरिहार्य है। बाकी सब कुछ (पैसा, संपत्ति, सोना, शक्ति, आदि) बेकार है। नाशवान\nधन भगवान और उनका ज्ञान है. महात्मा वे हैं जो ईश्वर के बारे में इस प्रकार सोचते हैं।\n\nइस श्लोक में विशेषण 'पार्थ' है। कृष्ण ने अर्जुन से कहा, \"प्रथिया के पुत्र\"।\nसम्बोधन का अर्थ सतही होता है। शास्त्रीय दृष्टि से व्युत्पत्ति \nइस विशेषण के पीछे एक अलग आध्यात्मिक अर्थ है। “प्रथा-विस्तारे' धातु.कौन सा\nजो व्याप्त है, जो हर जगह व्याप्त है वह \"प्रथा\" है। यह भगवान की सर्वव्यापकता है\nयह उन लोगों को इंगित करता है जो इस सत्य को समझते हैं कि ईश्वर सर्वव्यापी है और उन्हें हर जगह देखते हैं\n'पार्थस'. दूसरे अर्थ में वेदार्थभूत भगवान अपने गुणों का सदैव पान करते हैं\nऐसा करने वाले 'पार्थ' हैं. हम सबको वेदार्थ पीकर पार्थ बनना चाहिए। हर जगह\nइस संबोधन के पीछे भाव यह है कि हम अपने भीतर सर्वव्यापी शक्ति को देखें\nसंदेश\n\nदैवी प्रकृति वाले किस प्रकार भगवान की पूजा करते हैं?\nकृष्ण अगले श्लोक में बताते हैं.",
  "9.14": "सततं कीर्तयन्तः मम यतन्तः च थं प्रातःः।\n\nनमस्यान्तः च मम भक्त्या नित्य युक्तः उपासते - मुझे हर दिन अपने अंदर ले चलो।\nनिरंतर मेरी प्रशंसा करते रहो और मेरे लिए संघर्ष करते रहो\nझुकना.\n\nकृष्ण कहते हैं, \"जो लोग स्वभाव से दिव्य हैं वे निरंतर मेरा जप करते हैं।\" उनमें से प्रत्येक\nक्रियाशीलता में भी भगवद् चेतना गहरी है। दूसरे अर्थ में, एक यंत्र धारण करना,\nहमेशा तार बजाना और भगवान की स्तुति करना (महर्षि नारद की तरह)।\nजो लोग खुश हैं वे स्वभाव से दिव्य हैं। वे अपने लक्ष्यों को प्राप्त करने के लिए दृढ़ निश्चयी हैं\nवह दीक्षा से, अनूठे प्रेम से पूजा करता है। दूसरे प्रकार के भक्त हैं कृष्ण\nवह अगले श्लोक में बताते हैं.",
  "9.15": "ज्ञानयज्ञेन च अपि अन्ये यजन्तः मम उपासते |\n\nएकत्वेन पृथक त्वेन बहुधा विश्वतः मुखम्- जागरूकता के मनसा यज्ञ द्वारा सर्वत्र कुछ।\nवे मुझ परिपूर्ण भगवान की पूजा करते हैं और उसका उपभोग करते हैं - भगवान जो हर जगह मौजूद है\nजैसा कि [एकीकृत], जैसा कि सभी से अलग [चतुर्भुज], जैसा कि विभिन्न रंगों का\n[कई मायनों में];, इस प्रकार कई मायनों में।\n\nअन्य लोग प्रभु चेतना की दुनिया में डूबे हुए हैं। उनके बाहर ध्यान में\nसंसार का कोई भान नहीं रहता। ध्यान में वे ईश्वर को कई आयामों में देखते हैं\nपूजा उनकी पूजा ध्यान से पहले एक यज्ञ है। बाह्य रूप से उन्हें महात्मा कहा जाता था\nइसे पहचानना बहुत मुश्किल है. कृष्ण कहते हैं: “ये मुझे एक बनाते हैं, अलग करते हैं, अनेक बनाते हैं\nवे देखेंगे. यहां एकत्वेण का अर्थ है इस बात की पूजा करना कि भगवान एक है।\nप्रत्येक देश, प्रत्येक जाति, प्रत्येक वोट के लिए एक भगवान नहीं। भगवान सबके लिए\nएक के रूप में पूजा करना एकत्ववेण है। पृथक्तवेण का अर्थ है सबसे विचित्र\nईश्वर को अनेक प्रकार से देखना। वह अनेक रंगों से भगवान का ध्यान करता है\nइस प्रकार देखा जाता है कि विश्वतोमुख भगवान एक हैं, चतुर्मूर्ति हैं, अनेक हैं\nमूर्तियों की तरह अनेक रंगों से पूजी जाती हैं।\n\nभगवान के पास कैसे जाएं और कैसे न जाएं, इसका ज्ञान कृष्ण ने दिया।\nइसके बाद भगवान की विभूति को अलग करें। अन्य प्रतीकों तक कैसे पहुंचें\nवह बताते हैं कि संपूर्ण ब्रह्मांड भगवान और परमाणु कणों की उपस्थिति से भरा हुआ है\nइसकी अनोखी पूजा का विवरण कृष्ण ने इस अध्याय के अगले भाग में बताया है। चलो\nआइए प्रभु से अद्वितीय ज्ञान सुनकर कृतज्ञ हों।",
  "9.16": "अहं क्रतुः अहं यज्ञः स्वधा अहं अहं वहहम्तम्।\n\nमंत्र अहं अहं एव अज्यम अहं अग्निः अहं हुतम - मुझसे यग। [मेरी कार्रवाई मेरी है\nमैं रूप के कारण \"क्रतु\" हूं। मेरे द्वारा यज्ञ की क्रिया |\nमेरे द्वारा [क्योंकि मैं स्वयं \"स्वधा\" द्वारा समर्थित हूं। मुझसे मनुष्यों का भोजन मिलता है\n'चिकित्सा' क्योंकि प्रोप. मंत्र मेरी ओर से [सलाहुदा द्वारा ज्ञात \"मंत्र। घी मेरी ओर से\n[\"अज्य\" क्योंकि वह सबसे बड़ा है। मेरे द्वारा आग. [स्वयं गतिहीन ब्रह्माण्ड को गति देकर\n“अग्नि. मुझ से होमदा हवमी (जैसा कि भक्त मुझे \"हुता\" कहते हैं)।\n\nशास्त्रकारों ने भगवान की आराधना के लिए तीन प्रतीक बताए हैं। वेद में वे तीन\nप्रतीकात्मक पूजा वह है जो हम हर जगह पाते हैं। वे आग प्रतिरोधी और वायु प्रतिरोधी हैं\nऔर आदिम. अग्निप्रतीक में भूस्त्र में भगवान की पूजा करें। अंतरिक्ष परत में आदित्य\nवायु के प्रतीक रूप में भगवान की मुख और अंतःकरण में पूजा। धरती पर\nमनुष्य आमतौर पर ज्ञान के मार्ग की तुलना में कर्म के मार्ग से अधिक जुड़ा होता है। ऐसे में\nज्ञान से अधिक जोर कर्म पर है। कुछ लोग सुबह से शाम तक पूजा करते हैं। लेकिन खुद\nउन्हें क्रियान्वयन की जानकारी नहीं है. ज्ञान अर्जन उसके लिए गौण है )।\nयह मानवीय कमजोरी है. हम ज्ञान पर उतना जोर नहीं देते जितना अपनी विनम्रता पर! अज्ञात\nबाहरी कार्यान्वयन पर निर्भर रहने के बजाय पाठ प्रवचन से थोड़ा सा ज्ञान\nकमाई एक महान पूजा है जिसकी भगवान सराहना करते हैं।\n\nजो कर्म प्रधान हैं उनके लिए ईश्वर का कार्यान्वयन क्या होना चाहिए। यहां कृष्णा ने कहा\nसमझाया. कृष्ण कहते हैं: \"अहम् क्रतुः अहम् यज्ञ\"। प्रभु का\n“क्रतु” अग्नि की उपासना के लिए की जाने वाली प्रक्रिया है। यहाँ बलिदान से\nभगवान को प्रसाद चढ़ाते समय, हम यह कहकर प्रसाद चढ़ाते हैं: आज्ञा ये स्वाहा-अग्ना य इदम्ना।\nमामा प्रजापता स्वाहा प्रजापतय इदम् की माता हैं; इन्द्राय स्वाहा-इन्द्राय इदम् न\nमम सूर्याय स्वाहा - सूर्याय इदम् की माता; वयव इदम् के वयवे स्वाहा-मम;\nवरुणाय स्वाहा-वरुणाय इदं न मम, आदि। इस प्रकार भगवान को विभिन्न प्रतीकों में\nयज्ञ एक यज्ञ है. यहाँ कृष्ण कहते हैं \"मैं तुम्हारे कार्यों का नियंत्रक हूँ\"।\nहम जिस भी प्रतीक की पूजा करते हैं, वह उस देवता का अन्तर्यामी होता है\n\nप्रभु को. उदाहरण के लिए गणहोमा, चंडिकाहोमा, नवग्रहोमा आदि। हम यहाँ हैं\nऐसा कहा जाता है कि चाहे किसी भी देवता की बलि दी जाए, उस बलि का श्रेय भगवान को जाता है\nहमारे पास एक दृष्टिकोण होना चाहिए. यद्यपि भगवान ऊर्जा के कई रूपों में प्रकट होते हैं, फिर भी वे सर्वव्यापी हैं\nभगवान ही नियंता हैं. [ज्योतिषी हम पर आने वाली विपत्तियों को टालने के लिए भगवान के समान हैं\nऐसा कहा जाता है कि संबंधित शक्ति प्रतिका की पूजा की जाती है, लेकिन कई भगवानों की नहीं]। देवता का\nकेवल जब भीतर के भगवान से प्रेम किया जाता है, तो यह उस देवता और भगवान के साथ मिलन होता है।\nइसलिए, एक समय में एक दिन, एक ही देवता का प्रिय बनने के लिए कर्म नहीं करना चाहिए।\nहमारी पूजा सर्वव्यापी भगवान को समर्पित होनी चाहिए।\n\nहमारे शरीर के भीतर परोपकारी देवता हैं। सभी देवता बृहस्पति स्थित हैं। वे हैं\nभगवान का परिवार. वहाँ वह प्रभु है जो उन पर शासन करता है। ये कट्टर\nदेवताओं. ईश्वर अपनी कृपा से हमें सही रास्ते पर ले जाएं।'\nयज्ञ भगवान अन्तर्यामय की पूजा है।\n\nयदि हम नित्य पीठ में जो पूजा करते हैं वह भक्त देवताओं के लिए एक यज्ञ है,\nश्राद्ध- पितृसत्तात्मक देवताओं के लिए किया जाने वाला बलिदान। हममें से कई लोगों को ग़लतफ़हमी है. श्रद्धा\nजैसे 'जीवन पर शरीर का बलिदान होता है'। लेकिन ये सही नहीं है. श्रद्धा स्थूल शरीर को त्यागकर सूक्ष्म होती है\nयह शरीर में जीवन को नियंत्रित करने वाले 'पिता देवताओं' के साथ ऐसा करने जैसा है। विशेषकर दस\nसार्वभौमिक देवता (क्रतु, दक्ष, वसु, सत्य, काम, काल, धुरी, लोचन, पुरुरवा आर्द्रव); उनमें से\nपुरुरवा और आर्द्रावरदा पितृसत्ता के शासन के तहत बनाये जाने वाले खाते हैं। अन्य देवताओं का\nगण दस (सौ पितरों में प्रमुख): यम, सोम, काव्यवाह (ये तीन)।\nपितृपति), सोमसद, अग्निशत्त, बहिरशद, सोमप, हविर्भुज, अज्यप,\nशुभकामनाएँ. यह जीवन की भूख को संतुष्ट करने के लिए नहीं है जिसे हम प्रत्यारोपित करते हैं। हमारे बुजुर्गों को स्वर्ग या\nनरक में जाना उनके कर्मों के कारण है न कि हमारे समर्पण के कारण। श्रद्धा\nऐसा करने का उद्देश्य यह है कि कुलपतियों के अधिकार में जीवन कुछ आकस्मिक है\n प्रभाव के कारण बाधाओं का सामना कर सकता है। उस समय यह\nकर्मानुष्ठान जो समाप्त करता है वह उस सूक्ष्म शरीर में मौजूद नहीं है। उसके लिए ऐसा\nपितृ देवता जो उन्हें बाधाओं से बचाते हैं और आगे बढ़ने के लिए मदद मांगते हैं\nपूजा ही श्राद्ध है. कुल मिलाकर यह बुजुर्गों की मृत्यु के दिन की याद, उनके प्रति आभार और पितृ देवताओं का स्मरण है\nपूजा.\n\nकृष्ण कहते हैं: \"स्वधा अहम्\"। जैसा कि मंत्रों में कहा गया है, \"स्वाहा' तत्त्वभिमानी\nदेवताओं के लिए ''स्वधा'' पिता देवताओं के लिए है। श्राद्ध मेरे द्वारा पितृसत्तात्मक देवताओं के कारण होता है\nकृष्ण कहते हैं.\n\nपरोपकारी देवताओं और कुलपतियों के बाद मनुष्य। मनुष्य का मुख्य भोजन\n'चिकित्सा'. जो पौधा फल देता है और मर जाता है उसे संस्कृत में \"ओषधि\" कहा जाता है। उस पौधे का जन्म ही उसका है\nमृत्यु मनुष्य जो भी अनाज खाता है वह सभी औषधियाँ हैं। औषधि ऐसी औषधियों का समुदाय है। कृष्ण\nवह कहते हैं \"अहम् मदहोतम\"। हम जो दावासा अनाज खाते हैं वह भी वैश्वाना के रूप में धन्य है\nभीतर बैठे प्रभु को। जो औषधि देता है, उससे रोग दूर करता है, भूख मिटाता है\nभगवान रक्षक है.\n\nहम अलग-अलग मंत्रों से आहुति देते हैं। जैसा कि पहले मंत्र पता बताया गया है।\nयदि जो कुछ भी दिया गया है वह भगवान का है, तो अलग संबोधन क्यों? कृष्ण ने कहा: “अन्य\nमेरे लिए एक अलग पते पर! भगवान एक हैं लेकिन उनके रूप अनेक हैं। हम क्या हैं\nभले ही यह मंत्र द्वारा भेजा गया हो - यह पढ़े गए सभी मंत्रों से संबंधित है, शब्दशः।\nभगवान। भले ही अलग-अलग देवी प्रतीकों में अलग-अलग ऊर्जा रूपों की पूजा की जाती है\nप्रत्येक नाम स्वयं भगवान को भी संदर्भित करता है। भगवान हर चीज़ का सार है. इसके लिये\nनारियल इसका एक अच्छा उदाहरण है। जलती हुई आग की तरह, सिस्थ के साथ नारियल;\nभूसी के भीतर का अखरोट अग्नि की मध्यस्थ देवी अग्नि के समान है; खोल के अंदर नारियल की आग\nदेवता के भीतर भगवान की तरह. हमारे यहाँ हर चीज़ को नारियल या आग कहते हैं\nअसली नारियल के अंदर जैसा सार होता है, वैसी ही असली आग होती है\nअन्तर्यामी भगवान हैं. इस श्लोक में कृष्ण इसी को \"अहम् अग्निः\" कहते हैं।\n\nकृष्ण एक उदाहरण के रूप में उस महत्वपूर्ण चीज़ को लेते हैं जिसे हम बलिदान के रूप में अर्पित करते हैं\nवह कहते हैं \"अहम् एव आज्यम्\"। अज्य का अर्थ है घी। आज्ञा में देवताओं को प्रसन्न करने के लिए अद्वितीय\nशक्ति है. कृष्ण मैं होमद हवि (अहम् हुतम्) हूं जो कहता है कि मैं आज्ञा में अद्वितीय शक्ति हूं।\nवह कहता है।\n\nहविस्सु का अर्थ है भगवान को अर्पित किया जाने वाला होम द्रव्य। उस इच्छा में एक विशेष शक्ति होती है\nप्रभु से. हमारा समर्पण कभी व्यर्थ नहीं जाता. अग्नि को अर्पित इच्छा अग्नि से बाहर है\nसमाज को सूर्य की किरणों से वातावरण में चमकते सातों रंगों से मुखातिब होना\nफल देता है. हविर्हरिः भगवान हैं जो हविर्भागा को स्वीकार करते हैं। “सर्व देव नमस्कारः\nकेशवं प्रतिगच्छति”। प्रभु सभी शब्दों से पढ़े जाते हैं। तो कैसा शोर\nभले ही वह उसका है. इस प्रकार इच्छा को स्वीकार करना और भक्तों के पापों का निवारण करना\nभगवान हविर्हरिः।\n\nइस श्लोक को दूसरे आयाम से देखें तो यहां आने वाला हर शब्द ईश्वर का है\nआप बहुलता देखेंगे.\n\nक्रतुः: क्रथु शब्द का मुख्य अर्थ भगवान है। 'क्रतु' - का अर्थ है क्रिया, ज्ञान आदि।\nक्रिया स्वरूपा, ज्ञान स्वरूपा भगवन्त क्रतुः। हमारे पास विश्वास है, इच्छा शक्ति है, क्रिया शक्ति है इत्यादि\nसुविधा देना, हमारे पीछे खड़े रहना, क्रियाएं करना, ज्ञान देना भी कर्म है\nप्रभु क्रतुः जो हमें जाल से बचाते हैं। यज्ञ: यज्ञ का अर्थ है सब कुछ\nजो सर्वज्ञ भगवान को जानता है, वह सभी कार्यों द्वारा पूजा किया जाना चाहिए\nयज्ञ का मध्यस्थ। स्वधाः का अर्थ है आत्म-संयमी सर्व-नियंत्रक। दवाइयाँ:\nभगवान \"औषधः\" का अर्थ उन लोगों के लिए सहारा-मुक्ति है जो संसार तप में गिरते और लड़खड़ाते (औषरू) हैं।\nमंत्रः भगवान 'मंत्रः' उन लोगों की रक्षा करते हैं जो जानबूझकर उनके पास आते हैं।\n[मंत्र हमारी रक्षा तभी करता है जब हम उसे जानते और जपते हैं। अन्यथा यह निष्फल ही है\nप्राप्त किया जा सकता है लेकिन वास्तविक महान फल नहीं]। संभवतः इसलिए ईश्वर सबसे महान चीज़ है\nवह “अज्यः” अग्निः है; वह भगवान जो अचल वस्तु “अग्निः” हुतः को गति देता है; सभी भक्तों द्वारा।\nआहुताना के रूप में, भगवान \"हुतः\" हैं।",
  "9.17": "पिता अहम् अस्य जगतः माता धाता पितामहः |\n\nवेद्यं पवित्रं ओंकारः ऋक् सम यजुः एव च- मैं इस संसार का पिता, माता, पालनकर्ता हूं।\nऔर दादा. जानने से \"माँ\"। पालन-पोषण से \"धात्रु\"।\nपिता से बड़े होने के कारण उन्हें ही पूरी दुनिया को जानना चाहिए। वह जो दुनिया के लिए पवित्र है.\nजो ओंकार, ऋग्वेद-सामवेद-यजुर्वेद का पाठ किया जाता है। [ॐ'. वह है\n'ओमकारा' कहा जा रहा है. श्रद्धा के कारण \"खाक\"। समता के कारण ''सम''।\nयज्ञों द्वारा पूजित होना, “यजुस्\n\nयहां कृष्ण जीवन के रिश्तों के संबंध में भगवान की पूजा का वर्णन करते हैं। कृष्ण\n\nवह कहते हैं \"पिता अहम् अस्य जगतः माता धाता पितामहः\"। इसका मतलब है \"मैं पिता हूँ,\n\nमैं माता हूं, मैं पालनकर्ता और पिता हूं।'' जैसा कि हम जानते हैं कि कोई भी पिता बन सकता है या बन सकता है\n\nमां बन सकती हैं. लेकिन माँ और पिता दोनों अकेले रहना संभव नहीं है। यह प्रभु में है\n\nही संभव है. ईश्वर सबका पिता और सबकी माता है। पिता के भीतर \"पिता\" के रूप में,\n\nवह प्रभु माँ के भीतर 'माँ' के रूप में भरी हुई शक्ति है। हम इसकी प्रशंसा इस प्रकार करते हैं:\nत्वमेव माताच पिता त्वमेव, त्वमेव बन्धुष सखा त्वमेव\n\nत्वमेव विद्या द्रविणं त्वमेव, त्वमेव सर्वं मम देवा देवा\nगायति का मूलतः यही कार्यान्वयन है। \"तत्सवितुर्वरेण्यं भर्गः\" में भगवान ही विश्व है\nइसका अर्थ है पिता जिसने सृजन किया। सविता. इसका अर्थ है संसार को धारण करने वाला।\nप्रभु ने प्रलय के समय संसार को अपने पेट में धारण किया और सृष्टि के समय उसे धारण किया। बहुत समय तक\nपरामर्शदाता एक \"माँ\" है - इसलिए भगवान भी एक माँ है, न केवल वह, बल्कि हर माँ के भीतर\nउस माँ के मातृत्व को, उस प्रभु को जगाओ जो माँ के भीतर मातृत्व से भरा हुआ है, सब\nवह पिता ही है जो पिताओं में, यहां तक ​​कि उनके भीतर भी पितृत्व जगाता है। पिता शब्द की परिभाषा\n\"पिता\" केवल एक पारंपरिक अर्थ है। श्रुति कहती है:\n\nयोनः पिता जनितयो विधाता धामनि वेद भुवनानि विश्वा|\n\nयो देवानां नामधा एक एव तम् सम्प्रशना म्बुवना यन्तन्य ||\nयहां पिता और जनक का अलग-अलग उल्लेख किया गया है। वह हमारा पिता है, वह हमारा जन्मदाता है।\nअर्थ: वह सृष्टिकर्ता है, वह रक्षक है।\nसंसार में पुरुष स्त्री नहीं हैं, स्त्री पुरुष नहीं हैं। लेकिन ईश्वर तो सबका अवतार है. तो प्रभु\nउभयलिंग - वह स्त्रैण है। परन्तु उसमें न स्त्री का दोष है, न पुरुष का\nकोई त्रुटि नहीं है. अतः वह भी लिंगविहीन है\nनामों में पाया जा सकता है]।\nभगवान 'धाता' हैं। वह अनन्त काल से इस संसार का पालनकर्ता एवं पालक है।\nचार मुख वाला ब्राह्मण भगवान है जो पिता का वचन है।\nयहां कृष्ण ने सिर्फ अहम रिश्ते का जिक्र किया है. इसका मतलब यह है कि सभी रिश्तों में\nयह अन्तर्यामी भगवान ही हैं जो इंद्रियों को जागृत करते हैं। हर रिश्ते के पीछे\nभगवान से रिश्ता है. लेकिन हमें वह विचार नहीं है. प्रत्येक जीवन का प्रारब्ध\nकर्म संबंध. प्रेम, द्वेष, शत्रुता सब ईश्वर के कार्यक्रम हैं।\nजब हम यह जान लेते हैं तो हमारा जीवन आसान हो जाता है। जब कोई हमसे नफरत करता है तो सिकुड़ने की जरूरत नहीं,\nजब कोई हमसे प्यार करता है तो बढ़ने की कोई जरूरत नहीं है। सब कुछ हमारा जीवन स्वभाव है और\nयहां प्रारब्धकर्म के अनुसार भगवान की लीला का स्मरण करना बहुत जरूरी है। इसके लिए एक अच्छा है\nदृष्टांत भागवत में वृत्र और इंद्र के बीच युद्ध की कहानी: इंद्र को मारने के लिए निकले\nजैसे 'वृत्र' के पिता त्वष्ठा ने एक स्वर गलत वाला मंत्र बोला - वृत्र से।\nइंद्र द्वारा मारे जाने के बजाय, इंद्र ने ही वृत्र को मार डाला। वृत्र और इन्द्र के युद्ध में |\nइंद्र ऋषि वृत्र को मारने से हिचकिचाते हैं। तब वृत्र कहता है: “शर्म।”\nमत गिरो इंद्र, मुझे मार डालो। क्योंकि इस नाटक में भगवान तुम्हें मार देते हैं\nऔर उसने मुझे मरने के लिए भी एक भूमिका दी। हमें बस इस पर अमल करना है।” इस कदर\n\nयदि हमारे पास ईचा है, तो जब हमें दूसरों द्वारा डांटा जाएगा या नफरत की जाएगी तो हम दुखी नहीं होंगे। सब कुछ भगवान का है\nजब इसे सिस्टम के रूप में जाना जाता है तो सब कुछ एक समान दिखता है। नफरत और प्यार स्वाभाविक रूप से चले जाते हैं।\nरिश्ते टूटने पर सिकुड़न नहीं होती और जुड़ने पर विस्तार नहीं होता। यह बहुत ऊंचा दर्जा है.\nकृष्ण यहां जो कह रहे हैं उसका पूरा सार यह है: सभी रिश्तों के पीछे भगवान हैं। सबमें से\nवह अंदर से 'सभी' से भरा हुआ है। उनमें से प्रत्येक रूप में, अपने-अपने कार्य हैं\nक्या यह वह विज्ञान है जिसके प्रति हमें संपर्क करना चाहिए।\n\nकर्म और संबंधों की व्याख्या करने के बाद कृष्ण अब ज्ञान के बारे में बताते हैं। कृष्ण कहते हैं “वेद्यम्\nपवित्रमोणकर ऋक् सम यजुरेव च”। इस नाममात्र संसार के सभी नामों में से\nमूल 'ओम्' है। कृष्ण कहते हैं: \"मैं ओमकारा हूं\"। संसार में सभी ध्वनियाँ जन्म लेती हैं\nओमकारा द्वारा. अतः भगवान सर्वज्ञ हैं। संस्कृत के सभी शब्द ऐसे ही हैं\nओमकारा से निकलने वाली ध्वनियाँ। आइए संक्षेप में देखें कि कैसे:\n\nवैदिकवाजकय के मूल ओंकार में आठ अक्षर हैं: अकार, उकार, मकार, नाद,\nबिंदु, कला, शांत, अति शांत। इसका अर्थ है नारायण अष्ट क्षार: \"ओम नमो\nनारायणायः... ओमकारा के आठ प्राथमिक रंगों में से अक्षरा मलिका की आठ श्रेणियां\nद्वारा गठित:\n\n1. स्वर: एईईईईईईईईईईईईईईईईईईईईईईईईईईईईईईई\n\n2. क-.वर्ग: कखगघज\n\n3. चा-वर्गा: चाचाजारुए\n\n4. ता-वर्ग: ताराथराधना\n\n5. ता-वर्ग: तथाधाधना\n\n6. पा-वर्ग: पापभाभामा\n\n7. प्रारंभिक अक्षर:\n\n8. अंतिम छह अक्षर: शशशहालक्ष\n\n'अ' से 'क्ष' तक कुल इक्यावन अक्षर (अ से क्ष इसलिए अ-क्ष-र)। संपूर्ण\nसंसार के सभी शब्द इन्हीं अक्षरों के संयोजन हैं। सभी ध्वनियाँ ओमकार की हैं\nओंकार वाच्य भगवन्त सर्वशब्द वाच्य जन्म के कारण। तो सभी ध्वनियों का मूल\nपवित्र का अर्थ है ईश्वर. दोषयुक्त बातें भी केवल प्रभु की ही होती हैं\nवे केवल पवित्र अर्थ ही कहते हैं। उदाहरण के लिए दुःखद. यह तब होता है जब भगवान कहते हैं \"दुःख।\"\nइसका मतलब मालिक है.\n\nइक्यावन अक्षरों (मैट्रिक्स) से पढ़े जाने वाले भगवान के रूप भी इक्यावन हैं:\n\n1. अजा, 2. आनंद, 3. इंद्र, 3. ईशा, 4. उग्र, 5. ऊर्जा, 7. खुटंबर, 8. खगहा, 9. एल श, 10.\nलिजी, 11. एकात्म, 12. इरा, 13. ओज़ोभृत, 14. औरसा, 15. अंत, 16. अर्धगर्भ, 17.\nकपिला, 18. खपति, 19. गरुड़ासन, 20. ताप, 21. जसारा 22. चार्वंगा, 23. छंद,\n24. जनार्दन, 25. रुओतितारी, 26, इमू, 27. टंकी, 28. थाकला, 29. दारका, 30. धारी, 31.\nनतमा, 32. तारा, 33. थाभा, 34. दंडी, 35. धान्वी, 36. लचीलापन, 37. प्रो, 38, फली, 39. बलिदान, 40.\nभग, 41. मनु, 42. यज्ञ, 43. राम, 44. लक्ष्मीपति, 45. वर, 46. शांतसंवित्, 47. षडलूण,\n48. शरतमा, 49. हंस, 50. लालुका, 51. नृसिंह[नृहर्याक्ष]।\n\nओंकार मूल मूराक्षर का अ-उ-मा पद्य-गद्य-गण। यह वेद और वेदा के तीन रूप हैं\nप्रतिपद्य भगवान् कहते हैं। ऋग्वेद के लिए अकार, यजुर्वेद के लिए उकार और मकार\nसामवेद से संबंधित. खगरेदा \"अग्निमि\"ले पुरोहितं यज्ञस्य देवम्-खत्विजम्\" |\nहोता”राम रत्न धतमन् |…” “ए’ कारा से शुरू होता है.और “…बराबर”\nवो मनो यथा वः सुसहसति॥” जो 'ई' में ख़त्म होता है. वहां से आगे बढ़ें\nयजुर्वेद \"इशे त्वोरजे त्वा ..\" \"ए'कारा \"......समुद्रो बंधु\" से शुरू होता है\n\"उ'कारा में समाप्त होता है। इस प्रकार ओमकारा ऋग्वेद में \"अकारा और \"उकारा\" होता है\nसंपूर्ण यजुर्वेद को इंगित करने वाला संक्षिप्त रूप। यहां से आगे\nसामवेद सामवेद “अग्ना आ याही ह्हहल्ला*। 'अ'कारा से शुरू करते हैं\n1411 बृह्मास्पतिरद्दधातु” का अंत “उकार” में होता है। तो 'एम' कार यहां नहीं आई। लेकिन\nजैसा कि हम जानते हैं सामवेद नाद रूप में है। ओंकार में भी \"म\" नाद का ही रूप है\nएक उभरता हुआ अक्षर- वह है संगीत। इस प्रकार ओंकार वेद का संक्षिप्त रूप है। ये हमारे लिए है\nवेदों की पहचान के लिए एक मार्गदर्शिका। तो मंत्रों में भगवान ओंकार की स्तुति की जाती है\nयह अत्यंत प्राकृष्ण है। इस संसार में इससे बड़ी कोई प्रशंसा नहीं है। इस वजह से\nओमकारा उनका विशेष नाम है जिससे हम भगवान को बुलाते हैं।\n\nव्याहृति जब ओंकार खो जाता है, व्याहृति व्यापक रूप से गायत्री है, गायत्री अत्यधिक अंधी है।\nसूक्त, फिर तीन वेद, फिर सभी वेद। इस प्रकार प्रणव में, व्याहृति में, पुरुष में\nसूक्त में सभी वेदों में भगवान का वास बताया गया है। ओमकारा के बारे में और भी बहुत सी जानकारी\nइसका विशेष विवेचन अध्याय सात श्लोक-08) में किया जा चुका है।\n\nवेदों के शब्दों से जन्मे, दुनिया की सभी ध्वनियों और सभी सांसारिक स्वरों से भरे हुए\nभगवान ने आकाश में अनंत नाद और अनंत स्वर उत्पन्न किये। शोर से लेकर हम तक\nउस ध्वनि को समझने और समझने तथा दोहराने की विशेष शक्ति, अनंत अनुभव कराती है\nदयालु. मनुष्य में इस शब्द नमक भगवान को ज्ञान के माध्यम से जानने की विशेष शक्ति होती है\nभगवान का विशेष उपहार.\n\nभगवान 'ऋक्': खाक वह है जिससे हम भगवान की पूजा करते हैं। हम हैं\nमंत्रों के माध्यम से पूजा की जाती है. जिसकी पूजा की जाती है उसे 'ऋक्' कहते हैं\nप्रभु. जिनकी आराधना सभी मंत्रों द्वारा की जाती है।-प्रशंसनीय भगवान 'ऋक्'\n\nभगवान \"समः': वह जो अपने सभी रूपों में सभी को ज्ञानानंदादि गुणों से समान करता है\n\"समहा\" वह भगवान है जो उनके गुणों के बराबर और बराबर जीवन देता है।\n\nभगवान “यजस: जो सभी यज्ञों द्वारा पूजे जाते हैं, जो वेदों में मौजूद हैं।\nसर्वज्ञ भगवान \"यजुस्\",",
  "9.18": "गतिः भर्ता प्रभुः साक्षी निवासः शरणं सुह्रुत।\n\nप्रभावः प्रलयः स्थानम् धनं बीजम् अव्यम् - जो मुक्ति के लिए जाना जाए। सब\nवह जो उत्तरदायित्व वहन करता हो। हर चीज़ का स्वामी. जो सब कुछ प्रत्यक्ष देख सके। सबका घर. निःशुल्क भी समर्थन.\nअनिमित्ता एक रिश्तेदार है. सृष्टि-राज्य-प्रलय का कारण। वह जो दुनिया को बाढ़ में ले जाता है। फिर से दुनिया का\nवह जो अभिव्यक्ति का कारण बनता हो। अमर।\n\nरिश्तों के बारे में पहले बात करने के बाद, कृष्ण यहां विभिन्न प्रकार के लगावों का उल्लेख करते हैं। अलग\nइस प्रकार समाज में एक दूसरे से सहायता मिलती है। संकट के समय राजा की ओर से सुरक्षा\nआश्रय, दुखियों को सांत्वना देना, मित्रता आदि आसक्ति ये सब भगवान के हैं\nधर्म को कृष्ण कहा जाता है।\nजब किसी के पास घर नहीं होता, रहने का कोई मौका नहीं होता, \"मैं हूं\" ही सुरक्षा है\nऐसा करने वालों को 'गति' कहा जाता है। वास्तव में गति का अर्थ अंतिम गति है। सिर्फ परिवार में ही नहीं\nभगवान गतिः, जो मोक्ष में भी आश्रय हैं, वे अच्छे हैं, और जब हम गलत करते हैं, तो वे बुरे होते हैं\nभी। सारी जिम्मेदारी उठाना, दुनिया में हर कोई जो करता है, उसमें उसकी भलाई है\nप्रभु ही वह है जो बुराई को देख सकता है। वह हमारे सभी अंतरतम रहस्यों को जानता है।\nवह सर्वव्यापक तथा सर्वद्रष्टा सच्चा साक्षी है।\nकृष्ण कहते हैं \"अहम् निवासः\"। जैसा कि ईशावास्योपनिषद कहता है:\nईशावास्यं इदं सर्वं यत् किंच जगत्यं जगत् |\nतेन त्यक्षेण भुंजीतः मा गृधः कस्य स्विद् धनम्]\n\nहम प्रभु के घर में रहते हैं। इसमें एक घर बनाओ जिसे ये दुनिया कहते हैं\nईश्वर वह परमधाम है जिसने हमें आश्रय दिया है और हमारे रहने की व्यवस्था की है। वह सबके लिए है\nसहारा ऐसा भगवान एक प्रिय मित्र (सुहृत) है जो संकट के समय में हमें सुरक्षा (शरण) देता है।\nदोस्त दो तरह के होते हैं. सखा और सुह्रुत. 'सखा' का अर्थ है साथी। सदैव आपके साथ हैं।\nसुह्रुत का अर्थ है वह जो हमारे हृदय की बात सुनता है और हमारा हितैषी है चाहे वह दूर हो या निकट।\nप्रभु वह हैं जो हमारे हृदय में निवास करते हैं और सदैव हमारे हृदय के द्वार पर रहते हैं\nउत्तरदायी दयालुता.\n\nपरिशिष्ट में कहने के बाद, कृष्ण मानव शक्ति को पीछे छोड़ते हुए, देवताओं की शक्ति की व्याख्या करते हैं।\nवह कहते हैं \"प्रभावः प्रलयः स्थानं धनं बीजमव्यम्\"। हममें से बहुत कम लोग जानते हैं\nसृष्टिकर्ता-ब्रह्मा, राज्य-विष्णु और संहारक-शिव के रूप में। यहाँ कृष्ण स्पष्ट रूप से कहते हैं: “मैं हूँ\nप्रभावः-प्रलयःस्थानम्\"। संसार की रचना का मूल कारण भगवान हैं। सृष्टि के अंत में यह\nसंसार के नष्ट होने और सृष्टि से लेकर विनाश तक ब्रह्माण्ड की स्थिति के लिए, यह मूल रूप से ईश्वर था\nकारण\n\nवह भगवान ही हैं जो प्रलय के समय सभी प्राणियों को नाजुक स्थिति में अपने पेट में धारण करते हैं।\nवह सूक्ष्म चीज़ जो फिर से अंकुरित और खिलती है और ऐसे बीज बोती है जो कभी नष्ट नहीं होते\nअव्यय-भगवान्।\n\nइस प्रकार संसार की सारी क्रियाएँ, लौकिक, लौकिक, अलौकिक, रिश्ते-नाते, लगाव।\nसब कुछ समझाने के बाद कृष्ण समय-समय पर ऐसी बातें और भी समझाते हैं।",
  "9.19": "तपामि अहम् अहम् वर्षम् निगृह्णामि उत्सृजामि च ।\n\nअमृतम् च एव मृत्युः च सत् असत् च अहम् अर्जुन-मैं तपाता हूँ, मैं वर्षा को रोकता हूँ और उसे बरसाता हूँ। मैं अमृत और मृत्यु भी हूँ, और हे अर्जुन! मैं सत् (व्यक्त) और असत् (अव्यक्त) भी हूँ।\n\nसूर्य में उपस्थित होकर पृथ्वी पर सौर ऊर्जा का संचार करने वाले और जीवन देने वाले भगवान ही हैं। समय-समय पर वर्षा कराने वाले और अकाल में वर्षा को रोकने वाले भी वही हैं। वर्षा का समय पर न आना या असमय आना भी भगवान के नियंत्रण में ही है। दिखने वाली सृष्टि के पीछे की कारण शक्ति भगवान ही हैं।\n\nभगवान हमारे जीवन में प्राण फूँकने वाले अमृत हैं। जब जीवन समाप्त होता है, तो श्वास रोककर अपने पास बुलाने वाले भी वही हैं। संक्षेप में कृष्ण कहते हैं - 'दिखने वाले (सत्) और न दिखने वाले (असत्) समस्त संसार का संचालन करने वाली शक्ति मैं ही हूँ।' यह कृष्ण द्वारा भगवान की उपासना के लिए दिया गया एक समग्र चित्रण है।\n\nआगे, कृष्ण दो मुख्य प्रकार के भक्तों (अपने भक्तों में, संतों) का वर्णन करते हैं। वे त्रैविद्या और भागवत हैं।",
  "9.20": "त्रैविद्या मां सोमपाः पूतपापा यज्ञैरिष्ट्वा स्वर्गतिं प्रार्थयन्ते ।\nते पुण्यमासाद्य सुरेन्द्रलोकमश्नन्ति दिव्यान् दिवि देवभोगान् ॥\n\nत्रैविद्याः माम् सोमपाः पूतपापाः यज्ञैः इष्ट्वा स्वर्गतिम् प्रार्थयन्ते | ते पुण्यम् आसाद्य सुरेन्द्रलोकम् अश्नन्ति दिव्यान् दिवि देवभोगान् - तीनों वेदों में बताए गए सकाम कर्मों के अनुगामी, सोमपाय (यज्ञ का सोमरस पीने वाले) और निष्पाप होकर, यज्ञों द्वारा मेरी आराधना करके स्वर्ग की प्रार्थना करते हैं। वे पुण्य के फलस्वरूप देवराज इन्द्र के लोक को प्राप्त करके वहाँ दिव्य देवताओं के भोग भोगते हैं।\n\nत्रैविद्या अर्थात् वेदत्रय के ज्ञाता! इन्होंने भगवान के साथ केवल भोग का सम्बन्ध जोड़ा है। वे स्वर्ग की कामना और लौकिक सुखों को सामने रखकर भगवान की भक्ति करते हैं। उनके लिए वेदों में कहा गया कर्मकाण्ड ही मुख्य है। वे ज्योतिष्टोम जैसे यज्ञों को केवल स्वर्ग की इच्छा से करते हैं, भगवान के लिए नहीं। इस प्रकार सकाम भक्ति करने के फलस्वरूप वे इन्द्रलोक (स्वर्ग) पहुँचते हैं और वहाँ देवताओं के दिव्य भोगों का आनन्द लेते हैं।",
  "9.21": "ते तम भुक्त्वा स्वर्ग लोकं विशालं क्षीणे पुण्ये मर्त्य लोकं विशन्ति।\nएवं तीन धर्मं अनुप्रपन्नः गता अगतम् काम कामः लभन्ते - वह व्यापक है\n\nसग्गीगारा की भूमि खोजने के बाद, पुण्य समाप्त होने पर वे पृथ्वी पर लौट आते हैं। इस प्रकार वैदिक कर्मों की दुहाई\nहोक्कू इच्छाओं की पीठ पर इधर-उधर भटकता रहता है।\n\nस्वर्ग की इच्छा से पवित्र कर्म करने वाले त्रैविडियन स्वर्ग में शामिल होते हैं और वहां सभी प्रकार के सुखों का आनंद लेते हैं\nजैसे ही वे अपने अच्छे कर्मों का फल भोगते हैं, वे फिर से पृथ्वी पर जन्म लेते हैं। इस वजह से\nवह सबसे बड़ी मुक्ति और प्रभु की ओर से है। वंचित रह जायेंगे. वह हमेशा\nवे इच्छाओं के चक्र में फंस जाते हैं। उनसे एक बहुत ही अलग कदम है प्रतिभागियों का:",
  "9.22": "अनन्यः चिन्तयन्तः माँ ये जनः पर्युपासते।\n\nतेषाम् नित्य अभियुक्तानां योग क्षेमम् वहामि अहम् - बाकी सब कुछ और मुझे छोड़ दो\nविसर्जन के साथ पूजा करने वाले लोग सर्वत्र मेरी सेवा में समर्पित हैं।' उनका योग-\nमैं अपने स्वास्थ्य के लिए जिम्मेदार हूं।\n\nभागवत कुछ भी नहीं चाहते। यदि उनमें ईश्वर का विचार शेष रह जाए\nऔर कोई विचार नहीं है. वह विशिष्ट रूप से केवल भगवान की इच्छा रखता है। किसी वस्तु की इच्छा करना\nबांध गिरने पर वे पूजा नहीं करते। वह ईश्वर के अतिरिक्त कोई देवता नहीं है\nवे बलि चढ़ाकर पूजा नहीं करते। वह सभी देवताओं में से हैं\nसिर्फ भगवान ही नजर आते हैं. यह एकपत्नीत्व है; ईश्वर से जुड़ना, मोक्ष\nजिस मार्ग का अनुसरण किया जाना चाहिए।\n\nजब हम पूजा करते हैं तो संकल्प लेते हैं। यहाँ हमारी सांसारिक इच्छाएँ कभी नहीं होतीं\nइसे भगवान के सामने मत रखो. केवल ज्ञान, भक्ति, मोक्ष - यही हमारा संकल्प होना चाहिए। अनित्यता\nजब हम मनोकामना लेकर पूजा करते हैं तो हम महान फल खो देते हैं। हम लोगो को\nवह प्रभु हमसे बेहतर जानता है कि हमें क्या चाहिए और क्या नहीं\nहमें नहीं छोड़ेंगे. पूजा भगवान के प्रति एक अनोखी भक्ति ही है\nजब हम पौधे लगाते हैं तो भगवान हमसे प्यार करते हैं। कृष्ण कहते हैं. “तेषाम् नित्यभियुक्तानाम्।”\nयोगक्षेमन् वहाम्यहम्'' - मैं ऐसे भक्तों के कल्याण के लिए जिम्मेदार हूं।\nआपको आशा की क्या आवश्यकता है?\n\nयदि हम गहराई से विश्वास करते हैं कि \"भगवान हमें बचाएंगे और हमें बचाएंगे\", तो वह ऐसा करेंगे\nवह अपनी रक्षा स्वयं करता है। हमें ईश्वर में अपने विश्वास से कभी भी डिगना नहीं चाहिए।\n\nयह दृढ़ होना चाहिए. लक्ष्य केवल प्रभु से जुड़ना होना चाहिए। भगवान ने जो दिया है\nइसे एक महान उपहार के रूप में स्वीकार करें और पूरी तरह से उसके प्रति समर्पण कर दें। ऐसी स्थिति में हमारे लिए\nकभी दुःखी नहीं. जीवन आनंदमय है. जिंदगी में चाहे कुछ भी हो जाए\nयह यह जानते हुए कि यह प्रभु की इच्छा के अनुसार किया गया है, इसे खुशी से स्वीकार करने का दृष्टिकोण है\nहमारे बनो. यह मोक्ष का द्वार है।",
  "9.23": "ये अपि अन्य देवता भक्तः यजन्ते श्रद्धया अन्विताः।\nते अपि माम् एव कौन्तेय यजन्ति अविधि पूर्वकं - कौन्तेय, जो अन्य देवताओं का है।\nयहां तक ​​कि जो भक्त के रूप में सच्चे दिल से उसकी पूजा करते हैं, वे भी मेरे द्वारा धोखा खा जाते हैं\n\nपूजा",
  "9.24": "अहं हि सर्वयज्ञानं भोक्ता च प्रभुः एव च।\n\nन तू मम अभिजानन्ति तत्त्वेन अत: च्यवन्ति ते - मैं सभी पूजाएँ करने वाला नहीं हूँ।\nक्रेता और कंडक्टर. दरअसल वे मुझे ठीक से नहीं जानते. तो प्रवर्तन\nगिर जायेगा\n\nजैसा कि पहले चर्चा की गई है, कुछ लोग अपनी इच्छाओं की पूर्ति के लिए देवताओं से प्रार्थना करते हैं\nमुख्य रूप से पूजा की जाती है (भगवान के अलावा)। सवाल यह है कि जब आप ऐसा करते हैं तो क्या होता है\nहम उठ सकते हैं. इससे पहले कृष्ण ने कहा था कि 'मैं ही वह हूं जो हर चीज में मौजूद हूं।' किसको\nभले ही इसकी मुख्य रूप से पूजा की जाती है, यह भगवान के कारण है। यहां समस्या है पूजा\nजिनको वो जागरूकता नहीं है. यह एक गलत दृष्टिकोण है. भक्ति अनजाने में की गई\nयह पूर्ण भक्ति नहीं हो सकती. दूसरे की जानकारी के बिना की गई पूजा. हम कभी नहीं\nउत्थान नहीं किया जा सकता. कृष्ण कहते हैं, “इस प्रकार की पूजा से पुण्य अर्जित करने के बजाय, योग्यता कर्म है\nऐसा लगता है मानो वह फिसल कर गिर गया हो।\" इसलिए जो भी पूजा करें उसमें परतत्व का ध्यान रखें\nयह तभी सार्थक है जब किया जाए। जिसकी पूजा की जाती है, उस पूजा का फल मिलता है\n\nस्वयं भगवान. क्योंकि भगवान सभी यज्ञों के चरम हैं। यज्ञ के पीछे यही यज्ञपुरुष है\nरहस्य के रूप में, पुरुषसूक्त कहता है \"यज्ञेन यज्ञ मयाजंता देवः\" - यज्ञ से यज्ञ नमक।\nप्रभु की आराधना. बलिदानों के भगवान, बलिदानों के भगवान, बलिदानों के भगवान\nहम आराधना के माध्यम से प्रभु से जुड़ सकते हैं।\n\nफिर भी समाज में हम अनेक प्रकार से देवताओं की पूजा करते हैं\nहम देखेंगे. वे उस देवता की पूजा करने में समर्पित हैं। ऐसे करें पूजा\nकर्ता की गति क्या है? कृष्ण इसका उत्तर अगले श्लोक में देते हैं।",
  "9.25": "यान्ति देवव्रतः देवां पितृ-न यान्ति पितृव्रतः |\n\nभूटानि यन्ति भूतेज्यः यन्ति मत याजिनः अपि मम-देवताओं के भाड़े के लोग।\nस्वर्गदूतों से जुड़ता है. जो लोग पितरों द्वारा नियुक्त किये जाते हैं, वे पितरों में शामिल हो जाते हैं। भूत\nउपासक राक्षसों से जुड़ते हैं। जो मेरी पूजा करते हैं वे मुझसे जुड़ जाते हैं।\n\nकृष्ण कहते हैं, 'तुम जिसकी पूजा करते हो, वह तुम्हें मिलता है।' देवदूत\nजो देवताओं की पूजा करते हैं, जो पितरों की पूजा करते हैं, जो पितरों, भूतों (देवता) की पूजा करते हैं\nगण) की पूजा करने वालों को भी भूत प्राप्त होते हैं। परन्तु जो हर बात में एकचित्त है\nजो लोग भगवान को पाते हैं और ईमानदारी से उनकी पूजा करते हैं - \"वे मुझसे जुड़ेंगे\" -\nकृष्ण यहाँ आशा देते हैं। कोई देवताओं की पूजा कर सकता है और स्वर्ग प्राप्त कर सकता है, लेकिन वापस\nअजन्मे की मुक्ति नहीं. पूजा चाहे कोई भी की जाए, हर कार्य के पीछे ईश्वर का हाथ होता है\nउसे जानना और उसकी पूजा करना ही वास्तविक पूजा है। बिना जागरूकता के कभी भी हमारी पूजा न करें\nमोक्ष की ओर नहीं ले जाता. मानो ब्रह्मा समस्त देवताओं के परिवार के साथ है\nयदि तुम प्रभु की आराधना करोगे तो तुम प्रभु से जुड़ जाओगे। यह एक वैज्ञानिक प्रणाली है.\n\nअगली कविता पर आगे बढ़ने से पहले, हमें यहां एक बात स्पष्ट करनी होगी। हम हैं\nहमारे दैनिक जीवन में गणहोम, नवग्रहहोम, देव पूजा, संकष्टी आदि के रूप में।\nहम पूजा करेंगे. क्या ये ग़लत है? हम गणपति या किसी अन्य प्रतीक में भगवान हैं\nक्या पूजा करने से हमें मोक्ष नहीं मिलता? क्या सही है, क्या ग़लत है? जो है\nत्रिविद्याधर्म, भागवत धर्म कौन सा है?\n\nभागवत धर्म आज हमारे बीच से लुप्त होता जा रहा है। कोई भी प्रतीक अन्तर्यामी प्रभु का है\nपूजा करना गलत नहीं है. लेकिन इसके पीछे हमारी मंशा गलत है. उदाहरण के लिए नवग्रह होम। एक\nयदि हम किसी फल की नहीं, केवल मोक्ष की प्राप्ति की इच्छा रखते हैं, तो देवताओं का पूरा परिवार,\nनवग्रह नारायण प्रीत्यर्थ नवग्रह होम करने में कुछ भी गलत नहीं है। लेकिन वहाँ\nआइए हम \"नवग्रह को नारायण प्रसन्न के रूप में अवतरित करें और इस प्रकार नवग्रह दोष का निवारण करें\"\nजब आप उसका संकल्प कर लेते हैं तो वह त्रिविद्या धर्म बन जाता है। संकल्प करते समय कोई इच्छा नहीं\nकेवल भगवत् प्रीत्यार्थ को जोड़े बिना जो भी काम्य कर्म किया जाता है वह भागवत धर्म है।\nयदि प्रभु प्रसन्न हो तो सब कुछ तैयार है। उसने जो दिया है उसका आनंद लो,\nजो नहीं दिया गया है उसे मत चाहो. अपनी कठिनाइयों को दूर करने के लिए भगवान की पूजा न करें।\nइसके बजाय, जो आता है उसे प्रसाद के रूप में स्वीकार करें और ज्ञान वैराग्य भक्ति-मोक्ष देना जारी रखें\nप्रभु से प्रार्थना करें. आपकी सुरक्षा का भार उस प्रभु का है। इसकी चिंता मत करो.\nआपके जीवन में जो घटित हो रहा है वह कोई दुर्घटना नहीं है। इसके उन्मूलन के लिए यह ईश्वर की इच्छा है\nआप भगवान की पूजा नहीं कर रहे हैं बल्कि भगवान से जुड़ने के लिए भगवान की पूजा कर रहे हैं। यह\nउदाहरण के लिए, जब हम अपने इरादे के पीछे का दृष्टिकोण बदलते हैं, तो यह भागवत है\nएक धर्म बन जाता है. यदि कोई त्रिविद्या अपने गुरु को \"मेरे गुरु\" कहकर प्रणाम करता है, तो भागवत कहती है, \"आ।\"\nवह यह जानकर कि गुरु के अंदर भगवान विराजमान हैं और मुझे शिक्षा दे रहे हैं, नमस्कार करते हैं।\nभागवत अपने सभी कार्यों में भगवान को देखता है। वह अपने सभी कार्यों और कर्मों में मोक्ष है\nभगवान के अलावा किसी और चीज की इच्छा न करें। इनकी आराधना में मोक्ष की कामना की जाती है\nऔर कोई इच्छा नहीं बची. हमारे लिए इस ऊंचाई तक पहुंचना असंभव नहीं है।' यह संभव है\nबस इतना ही करने के लिए प्रयास करना पड़ता है। हम जितना भगवत प्रीत्यार्थ कर्म करेंगे उतना ही\nहम मोक्ष के उतने ही करीब पहुँचते हैं। \"मुझे यह दो\" या \"यह।\"\nकभी भी 'इसे ठीक करो' के लिए न कहें। भगवान जानता है कि तुम्हें क्या चाहिए\nइसे भगवान पर छोड़ दो. बस भगवद प्रेम के लिए, मोक्ष की प्राप्ति के लिए कर्म करो।” “यह बस है\n\"केवल भीमसेना/वायुदेव के लिए\" बिना भागे और बिना किसी फल की तलाश के\nअन्यथा पूरी श्रद्धा से भगवान की आराधना करें। पूजा में मांगने की शक्ति केवल आपके पास है\nमोक्ष और ईश्वर'. इसे पाने के लिए अपनी उपलब्धि समर्पित करें। सात जो जीवन में आते हैं\nपतन, सब कुछ नश्वर है, इसके बारे में सोचे बिना, संसार से छुटकारा पाएं और मृत्युहीन मोक्ष प्राप्त करें\nशामिल होने के लिए प्रदर्शन करें. यह यहां का मूल संदेश है.\n\nभगवान की पूजा धन दौलत के बारे में नहीं है. बस शुद्ध भक्ति. भगवान की भक्ति कितनी है?\nकृष्ण निम्नलिखित श्लोक में सहजता की व्याख्या करते हैं:",
  "9.26": "पात्रं पुष्पं फलं तोयं यः में भक्क्य प्रयच्छति।\n\nतत् अहम् भक्ति उपहृतं अश्नामि प्रयता आत्मानः - जो एक पत्ता है, एक फूल है,\nवह भक्ति से मुझे पानी देता है, मैं उसकी भक्ति का उपहार हूं\nनाल्मे से खरीदूंगा.\n\nसर्वोच्च भगवान की पूजा के लिए जो कुछ भी आवश्यक है वह निरपेक्ष है\nसंलग्न , और \"मन से पूजा करना\"।\nयदि आप तुलसी का पूरा पत्ता या फूल अर्पित करेंगे तो भगवान प्रेमपूर्वक इसे स्वीकार करेंगे।\nयहां कुछ भी नहीं है, न सोने का आसन, न चांदी का कड़ाही, न पंचपात्र। घर पर,\nबगीचे में जो कुछ है उसे अर्पित करो। यदि घर में दूध न हो तो श्रद्धापूर्वक एक गिलास पानी पी लें\nसमर्पित करें लेकिन जब तक इसके पीछे पवित्रता है, कृष्ण कहते हैं \"यो मेई भक्त्या प्रयच्छति\"।\nवह है। ईश्वर जो चाहता है वह है हमारा अंतरतम प्रेम और ईमानदारी\nबाहरी महिमा नहीं. \"तदहं भक्कुपहृतमश्नामि प्रयतात्मनः\" - \"आपने मन को मुझमें डाल दिया।\"\nबस जाओ, श्रद्धापूर्वक जो कुछ दिया जायेगा, मैं स्वीकार कर लूँगा।” कृष्ण.\nरामायण में शबरी की कहानी भगवान के इसी वचन का उदाहरण है।",
  "9.27": "यत् करोशि यत् अश्नासि यत् जुहोशि ददासि यत् |\nयत् तपस्यासि कौन्तेय तत् कुरुष्ठ मत अर्पणम् -- कौन्तेय, तुम क्या करते हो, क्या\nतुम क्या चाहते हो, क्या प्यार करते हो, क्या देते हो, क्या खोते हो, मुझे सौंप दो।\n\nकृष्ण कहते हैं. “तुम्हें मेरे लिए कुछ नहीं करना है लेकिन तुम्हारे लिए क्या\nयदि आप ऐसा करते हैं, तो इसे मुझे पेश करें। हमारे दैनिक जीवन में करने के लिए बहुत सारे काम हैं\nअपरिहार्य कैरियर कार्य हैं। जीवनयापन में खर्चा होगा। हम भगवान के हैं\nइसे पूजा के नाम से जानना चाहिए. इसका अच्छा उदाहरण धर्मव्याधन की कहानी है। मांस बेचो\nउनके जीवन में एक दृढ़ संकल्प था। “मांस बेचना मेरे लिए आनुवंशिक है\n\nएक आदत जो आ गयी है. इसलिए मैं मांस बेचता हूं, ताकि मैं जीवित रह सकूं और अपना गुजारा कर सकूं\nमैं यह पेशा अपनाता हूं जो मेरे माता-पिता का समर्थन करने के लिए मेरे पास आया है।\nइससे मैं उतना ही कमा पाता हूँ जितना मुझे अपने जीवन के लिए चाहिए। लोग हमेशा व्यवसाय में रहते हैं\nवह यह सोचकर मांस बेचता था कि वह शोषण नहीं करेगा\nइसे ज्ञानी धर्मव्याध के नाम से जाना जाने लगा। एक ऐसी घटना घटी जब ख़ुशी मुनीस ने उनसे सबक सीखा।\nइसका मूल कारण यह है कि वह जो कर रहे थे वह ईश्वर की आराधना के रूप में किया।\nइस प्रकार हम जो काम करते हैं उसका कोई महत्व नहीं है, बल्कि वह भगवान की पूजा के रूप में किया जाता है\nदृष्टिकोण महत्वपूर्ण है.\nजो कुछ भी आपका दैनिक कर्तव्य है, उसे भगवान को अर्पित करें। इसे भगवान की पूजा बनाओ.\nभगवान के लिए पकवान भोज्य बनाने की जरूरत नहीं है. आप क्या खा रहे हैं\nप्रभु को समर्पित हो जाओ. जब ऐसा किया जाता है तो भगवान की पूजा अलग नहीं होती और\nयह कठिन नहीं होगा. भगवान के लिए कोई विशेष होम-हवन करने की आवश्यकता नहीं है। आप हैं\nआप जो भी होम करते हैं उसे \"अग्नि परगता नारायण इदं न ममः\" कहा जाता है।\nसमर्पित करें यदि आप किसी भूखे व्यक्ति को देखें तो वह वैश्वान रूपी भगवान को अपने पेट में लिए हुए है\nउस व्यक्ति को बताएं कि वह आया है और उसके भीतर वैश्वान को प्रसन्न करें\nकरो यह प्रभु की महान पूजा है।\nकृष्ण कहते हैं \"यत्तपस्यासि कौन्तेय तत् कुरुष्ठ मदारपनम्\"। यहाँ तपस्या है\n\"सोचना' या वृतानुष्ठान। उदाहरण के लिए \"संकष्टी'- इसे मनाते समय गणपति\nइसे अवतारी प्रभु के प्रति समर्पण के रूप में करें। कोई स्वार्थ नहीं है\nइस प्रकार कोई भी अनुष्ठान भगवान के सर्वोच्च व्यक्तित्व को समर्पित नहीं है\nजब आप यह जान लेते हैं तो यह सच्ची तपस्या बन जाती है। यहाँ अर्जुन से कहा गया है, “तुम्हारा कर्तव्य कर्म है\nइस श्लोक का संदेश यह है कि यह जो युद्ध आया है, इसका भी भगवान को भजन करना चाहिए\nकृष्ण ने दिया है. भागवत धर्म के कार्यान्वयन का परिणाम क्या है, इसका पालन कृष्ण करते हैं\nवह श्लोक में बताते हैं.",
  "9.28": "शुभ अशुभ भयः एवं मोक्षसे कर्म बंधनयेः |\n\nसंन्यास योग युक्त आत्मा विमुक्तः मम उपैश्यसि - इस प्रकार जीने पर, अच्छा-बुरा\nकर्म बंधन से बचो. फल का सुख त्याग कर कर्त्तव्य में लग गये\nकपड़े उतारो और मेरे साथ आओ।\n\nहम कोई भी कर्म 'मुझे ऐसा फल मिलेगा' और 'मुझे' के फल के साथ करते हैं\nजब अहंकार होता है कि 'मैंने यह कर्म किया है' तो वह कर्म हमसे जुड़ जाता है। उसके लिए\nपूर्वकाल में वे कर्मकर्ता बनने का संकल्प करते समय इस प्रकार कहते थे।\nभगवतो बलेण भगवतो वीरेण भगवदः तेजस |\nभगवत कर्मणा कर्मकरिष्यामि भगवतो वासुदेवस्यः ॥|\n\n\"मैं जो कर्म करता हूं वह मेरा कर्म नहीं है, यह मेरे भीतर के भगवान का कर्म है। इसके पीछे।\"\nशक्ति और सामर्थ्य सब भगवान के हैं, कुछ भी मेरा नहीं है।” यही भागवतधर्म का संकल्प है। भगवद\nकोई भी किया हुआ कर्म हमें बांध नहीं पाएगा। वेद व्यास ने ब्रह्मसूत्र में यह\nकहा: “जब प्रभु का ज्ञान अतीत से हमारे भीतर दृढ़ता से स्थापित हो जाता है\nवह ज्ञान की अग्नि सारे पापों को भस्म कर देगी।” अतः ज्ञान सबसे बड़ा है।\nइसे हम कठोपनिषद में यम और नचिकेता के बीच संवाद में देखते हैं। वहाँ\nजब नचिकेता ने यम से ज्ञान का वरदान मांगा तो यम ने उससे कहा, \"तुम्हें कितना धन चाहिए?\"\nसुनो, यदि तुम चाहो तो मैं तुम्हें एक विशाल साम्राज्य का सम्राट बना दूंगा। इस के लिए\nनचिकेता कहते हैं, ''ये सब नरक के साधन हैं, मुझे इनमें से कुछ भी नहीं चाहिए\nहमें प्रभु के बारे में जानना चाहिए।” इस प्रकार, हमारे पाप कर्म पूरी तरह से धुल जाते हैं\nईश्वर का ज्ञान ही मुक्ति का एकमात्र मार्ग है। भगवदर्पण बुद्धि द्वारा कर्म\nक्रियान्वित होने पर शुभ कर्म की शक्ति से मुक्ति संभव है। कृष्ण कहते हैं\nयथा ''संन्यासयोगयुक्तमा विमुक्तो मामापैश्यसि''। संन्यास ने कहा, यहां एक है\nयोग (टिप). भगवान को सब कुछ अर्पित करें और बिना किसी परिणाम के भगवत पूजा करें\nदृष्टि से सत्त्वगुण की प्राप्ति | संन्यास का अर्थ है भगवान में काम-संकल्प\nकाम अर्पण का अर्थ है 'करना चाहना', संकल्प का अर्थ है 'करना'\nकामसंकल्प वर्जिता-संन्यास का निर्णय करना। इस प्रकार भागवत धर्म का पालन करना आसान है\nकोई भी भगवान से जुड़ सकता है - \"निश्चित ही कोई मुझसे जुड़ेगा\" यह कृष्ण का वादा है।",
  "9.29": "समः अहं सर्वभूतेषु नाम वथ्यः अस्ति नाप्रियः।\n\nये भजन्ति तू मम भक्त माई ते तेषु च अपि अहम् - सभी प्राणी मेरे साथ एक हैं। मेरे लिए\nन कोई शत्रु, न कोई मित्र. परन्तु जो भक्ति से मुझे प्रसन्न करता है, वही मेरा अधिकार है;\nमैं उनका हूं.\n\nभगवान की न तो किसी से दुश्मनी है और न ही किसी से दोस्ती। वह प्यार करता है\nव्यक्ति नहीं बल्कि व्यक्ति में ज्ञान और भक्ति है। जो इसके योग्य है वही प्रभु है\nवे भक्ति भाव से पूजा करते हैं. भगवान सच्चे भक्तों के प्रति समर्पण कर देते हैं।",
  "9.30": "अपि चेत सु दुराचारः भजते माम् अनन्य भाक |\n\nसाधु एव सः मन्तव्यः सम्यक व्यवसितः हि सः - जो अन्यत्र स्थिर हुए बिना स्वयं को मेरे प्रति समर्पित कर देता है।\nआचरण कितना भी बुरा क्यों न हो, उसे मूलतः अच्छा ही जानना चाहिए। क्योंकि वह निश्चित है\nअसली वाला.\n\nसच्चे भक्त प्रायः दुष्ट नहीं होते। अकास्मत सात्विक है\nयद्यपि किसी आदिम कर्म के कारण एक जन्म में उसके साथ दुर्व्यवहार हुआ था, फिर भी वह मूलतः है\nवह सर्वश्रेष्ठ होगा. क्योंकि उन्होंने अनेक जन्मों में भगवत्प्राप्ति की है। यह है\nभले ही हम आम लोग इसे नहीं देख सकते, भगवान इसे देखते हैं। वह भगवान की नजर में है\nअच्छा लगता है. इस कारण हमें किसी को भी हल्के में नहीं लेना चाहिए। एक बुरा\nरास्ते में चलने के कई कारण हो सकते हैं. वह सात्विक भी हो सकता है. लेकिन उसका\nप्रारब्ध कर्म ने शायद उसे उस मार्ग पर चलने के लिए प्रेरित किया होगा। जिसे अच्छा लगा\nकृष्ण अगले श्लोक में कहते हैं कि वह हमेशा उस रास्ते पर नहीं चलेंगे।",
  "9.31": "क्षिप्रं भवति धर्म आत्मा शाश्वत शांतिम् निगच्छति।\nकौन्तेय प्रतिजानिः न मे भक्तः प्रणस्यति - वही मार्गदर्शन करता है; अमर\nउसे ख़ुशी मिलती है. कौन्तेय, यह व्रत करो: \"मेरा भक्त कभी नष्ट नहीं होगा\"।\n\nइस प्रकार जो लोग प्रारब्ध कर्म के कारण भटक गए हैं वे स्वयं भी किसी न किसी बिंदु पर हैं\nगलत कार्य का एहसास होने पर वह सही मार्ग अपनाता है और शाश्वत मोक्ष प्राप्त करता है।\nयह निश्चित है. कृष्ण कहते हैं तुम यह शपथ लेते हो। इसका अच्छा उदाहरण अजामिलन है\nकहानी अजामिल मूल रूप से एक महान जीव थी जिसने वह किया जो एलडीए को अपने जीवन में नहीं करना चाहिए था। जैसे कि\n\nजीवन के अंत में भगवान अजामिल को सत्य का मार्ग दिखाते हैं और उसका उद्धार करते हैं। वह है\nजीवन के अंत में उसे मोक्ष की प्राप्ति होती है।\nकृष्ण अर्जुन से क्यों कहते हैं, \"तुम प्रतिज्ञा करो\" का अर्थ है - भगवान ने भक्तों को अपनी प्रतिज्ञा दी है।\nउन्होंने प्रतिज्ञा तोड़ी लेकिन भक्तों की प्रतिज्ञा कभी नहीं तोड़ी। इसका उदाहरण महाभारत है\nयुद्ध की एक घटना:\nमहाभारत युद्ध से पहले कृष्ण ने शस्त्र न उठाने की प्रतिज्ञा की थी\nइस बीच जब अर्जुन भीष्म से युद्ध करने से झिझके तो भीष्म क्रोधित हो गये\nवह रथ का पहिया पकड़ कर आगे आता है मानो उसे ही मार डालेगा! भीष्म ने यह देखा\nवह दोनों हाथ जोड़कर कहता है: \"हे भगवान, मैं आपके हाथ में पहिया ऐसे ही पकड़ता हूं।\"\nमैंने लड़ने की कसम खाई. आपने कहा था कि आप पहिया नहीं पकड़ेंगे। लेकिन अब\nतुम मेरी प्रतिज्ञा पूरी करने के लिये चक्र थाम लो। तुम अपने को भूल गये हो, परन्तु अपने भक्त को\nप्रतिज्ञा नहीं; आपके अलावा हमारे लिए और कौन है?” वह है. इस घटना में भगवान का कैसा भक्त है\nयह समझ में आ गया है.",
  "9.32": "माँ हि पार्थ व्यापा सृत्य ये अपि स्यूः पापयोनयः;ह |\nस्त्रीः वैश्य तथा शूद्र ते अपि यान्ति परम गतिम् - पार्थ, जिसने मेरी शरण ली है\nकिसी पाप के कारण स्त्री, वैश्य, शूद्र के रूप में उपलब्धि से वंचित होने पर भी वह ज्येष्ठ है\n\nवे मुझे परमधाम दिला देते हैं।\n\nइस श्लोक ने कुछ टीकाकारों को भ्रमित कर दिया है। इस श्लोक पर माधवाचार्य की टीका है\nजब तक यह नहीं दिया गया था, अधिकांश ने इसे गलत समझा था। इस श्लोक की सतह पर\nयह जानने का जोखिम अधिक है कि \"महिलाएं, वैश्य और शूद्र पापी हैं\"। यहाँ कृष्ण हैं\nयह महिलाओं के जीवन के बारे में नहीं है. महिलाएं पापी नहीं हैं. किसी पाप से या\nएक श्राप के कारण पैदा हुआ नर मादा \"मादा पपायोनी\" है न कि मादा पपायोनी।\nकृष्ण कहते हैं, ''हिनायोनि शायद किसी पाप से आई है, लेकिन मैं ऐसा ही हूं\nपूजा करने से मनुष्य सभी दोषों से मुक्त हो जाता है।” इसका एक अच्छा उदाहरण\nनरकासुर की बंदी सोलह हजार एक सौ स्त्रियाँ थीं। ये अग्नि के पुत्र हैं।\nउन्होंने अपना कद खो दिया और भगवान की पत्नियाँ बनने की इच्छा से पृथ्वी पर महिलाएँ बन गईं\nजिनका जन्म हुआ और वे नरकासुर के कारागार में फँस गये। कृष्ण ने उनसे विवाह किया और उनका पालन-पोषण किया।\n\nनंदगोप और यशोदा मूल रूप से देवांशसंभूत थे। 'द्रोण' वसु का ही उपनाम है\nनंदगोप एवं 'धरा' नमक वसुपत्नी यशोदे। उनका जन्म पृथ्वी पर एक वैश्य के रूप में हुआ था।\nभगवान अपने अवतार में उनके घर में पले-बढ़े और उनका पालन-पोषण किया।\nमहाचेतना विधुर हैं. वह स्वयं धर्मी है. वेदव्यास का पुत्र होने पर भी वह शापित है\nनतीजा ये हुआ कि उन्हें एक मजदूर का बेटा होने का दावा करके जीना पड़ा.\nवह दुर्योधन, भीष्म और द्रोण के घर जाने के बजाय सीधे विधुर के घर और विधुर के पास से आये।\nसाधारण सी मिठाई खाकर उसे खुश कर दिया। भगवान यहाँ जो चाहते हैं वह कोई दिखावा नहीं है\nबल्कि यह स्पष्ट हो जाता है कि यह प्रेम है। उनके लिए आत्मा महत्वपूर्ण है, मुखौटा नहीं.\nइस प्रकार कृष्ण st बन गए। कहते हैं, “पापपूर्ण कर्म या श्राप से कुछ\nजब जो लोग मेरी शरण लेते हैं, वे जो हेनायोनि के रूप में जन्म लेते हैं, वे अपने पापों से छुटकारा पा जाते हैं और मुझसे जुड़ जाते हैं”\nवह है.",
  "9.33": "किम् पुनः ब्राह्मणः पुण्यः भक्तः राजा क्षयः तथा |\n\nअनित्यम असुखम लोकम इमाम प्राप्य भजस्व मम - पुण्य के फल से ब्राह्मण बनो,\nउन भक्तों का क्या जो ख़ुशी जैसे राजा के रूप में पैदा हुए हैं? चूँकि यह अस्थिर है,\nजब मनुष्य जन्म में आनंद न हो तो मेरी पूजा करो।\n\n\"उन लोगों के लिए जो पुण्य के फल से राजा और ब्रह्म-ज्ञानी के रूप में पैदा हुए हैं और भगवान की पूजा करते हैं।\nविशेष रूप से क्या कहने की आवश्यकता है?” कृष्ण पूछते हैं. इस प्रकार उसने भगवान के सामने आत्मसमर्पण कर दिया और शरण मांगी\nसबकी रक्षा का भार भगवान पर है। इसके लिए कृष्ण हमें यहां बताते हैं:\n\"यह सोचकर संसार में मत फंसो कि यह संसार ही सब कुछ है, क्योंकि यह 'अनित्यम्' है।\nअसुखम् लोकम्”। इसमें कोई ख़ुशी नहीं है. यह स्थायी नहीं है. इसलिए शाश्वत आनंद\nप्राप्त करने के लिए मेरी शरण लो। मेरे साअमने समर्पण करो। तुम्हें बचाना मेरी ज़िम्मेदारी है”।",
  "9.34": "मन्मना भव मद्भक्तो मद्याजी मां नमस्कुरु ।\nमामेवैष्यसि युक्त्त्वैवमात्मानं मत्परायणः ॥\n\nमत् मनाः भव मत् भक्तः मत् याजी माम् नमस्कुरु | माम् एव एष्यसि युक्त्वा एवम् आत्मानम् मत् परायणः - अपना मन मुझमें लगाओ, मेरे भक्त बनो, मेरी पूजा करो और मुझे प्रणाम करो। इस प्रकार अपने मन को मुझमें लगाकर और मेरे परायण होकर तुम मुझे ही प्राप्त होगे।\n\nजैसा कि कहा गया है, \"भजस्व पद्माक्षी, येन सौख्यं लभाम्यहम्\"—मैं तुम्हारी आराधना करता हूँ, तुम मेरी आराधना करो। यहाँ आराधना का अर्थ भक्तिपूर्वक प्रेम करना है।\n\nतुम जो भी पूजा करो, वह भगवान की पूजा हो; अपने हर प्रेम में भगवान को देखो। तुम्हारा हर प्रणाम भगवान के चरणों में हो। इस प्रकार अपने मन को भगवान में स्थिर करके अपने जीवन को भगवन्मय बनाओ - तुम्हारे लिए सबसे बड़ी वस्तु भगवान, जीवन का सारांश भगवान और निरंतर चिंतन का विषय भगवान ही हों। तुम्हारे जीवन की हर क्रिया भगवान की आराधना बने। तब कृष्ण कहते हैं - \"तुम मुझे ही प्राप्त होगे।\" इस प्रकार मोक्ष देने वाली उपासना का वर्णन करते हुए नौवां अध्याय समाप्त होता है।\n\nइति नवमोऽध्यायः\nनौवां अध्याय समाप्त।",
  "10.1": "अध्याय दस\n\nउन्होंने अर्जुन को भगवान के स्वरूप की व्याख्या की, जिसकी हमें पूजा करनी चाहिए, ज्ञान और विज्ञान के रूप में कृष्ण, उनमें ज्ञान की प्यास और पूर्ण भक्ति को पहचानें-विशेष रूप से पूजा में। इस अध्याय में भगवान की महिमा स्पष्ट की गई है।\n\nआमतौर पर मूल्यवान ज्ञान गुरु द्वारा आसानी से प्रकट नहीं किया जाता है। ऐसा कहा जाता है कि इस तरह के मामले को केवल तभी प्रकट किया जाना चाहिए जब शिष्य में पूर्ण निष्ठा और योग्यता हो। इस प्रकार गुरु बिना परीक्षा के शिष्य को मूल्यवान ज्ञान नहीं बताते हैं। इसका एक अच्छा उदाहरण प्रश्नोपनिषद में मिलता है। पिप्पलाद के पास छह लोग आए, जिन्होंने विद्वानों से कहा—\n\nभूया एव तपसा ब्रह्मचर्येण श्रद्धया संवत्सरं संवत्सरुथ;\nयथाकामन् प्रष्णन पैछता; यदि विज्ञास्यमः सर्वं हाओ वाक्ष्याम इति |२|\n\n\"तपस्या और ब्रह्मचर्य के साथ एक वर्ष श्रद्धापूर्वक रहें। उसके बाद, जो भी प्रश्न आपको पसंद हो, पूछें। यदि मैं जानता हूँ, तो मैं उत्तर दूँगा।\" यहाँ शिक्षक और शिष्यों की आपसी परीक्षा स्पष्ट है। लेकिन जब शिक्षक ने अपने योग्य शिष्य की पूर्ण भक्ति को पहचान लिया, तो भले ही वह प्रश्न न पूछे, उनका ज्ञान स्वतः ही उसके लिए प्रवाहित होने लगता है। इस स्तर पर कृष्ण ने अर्जुन में ऐसी पूर्ण भक्ति देखी।\n\nभगवान उवाच - भगवान ने कहा:\n\nभूयः एव महाबाहो श्रृणु मेइ परमं वाचः।\n\nयत् ते अहम प्रियमानया वक्ष्यामि हित कामया - हे महावीर, मेरी बात फिर से सुनो।\nहिरूनी, क्योंकि मैं यह तुमसे कह रहा हूं जो सुनकर प्रसन्न हैं।\n\nगुरु को ज्ञान देने में असंतोष शिष्य की प्रतिभा और गुणवत्ता के कारण होता है। यहाँ कृष्ण हैं, वह कहते हैं: \"मैं तुम्हें और अधिक बताऊंगा।\" क्योंकि यहाँ जो कहा जा रहा है वह \"परमं वाचः\" है, कृष्ण कहते हैं। यहां 'परमं' का मतलब सबसे बड़ी चीज है जिसे हमें जानना जरूरी है। यह सबसे बड़ा ज्ञान है जो पारलौकिकता की जागरूकता देता है। पूरी दुनिया के लिए यह मददगार है। इससे बढ़कर कुछ नहीं है। “आप इस युद्ध भूमि में खड़े होकर यह सुन रहे हैं और खुश हैं, वह खुशी आपके अंदर उमड़ रही है। उसके लिए, दुनिया की भलाई के लिए मैं तुम्हें बताऊंगा, सुनो, ”कृष्ण कहते हैं।",
  "10.2": "नाम विदुः सुरा गणः प्रभावं न मह खुशायः |\n\nअहं अदिह ही देवानां मह खुपीनं च सर्वसः - मेरी गहराई: [मैं ही संसार हूं\nनिर्माण की विधि देवताओं, ऋषियों या किसी अन्य को ज्ञात नहीं है। देवताओं को,\nक्या मैं हर किसी के लिए वरिष्ठ खुशियों का स्रोत नहीं हूँ?\n\nकृष्ण यहां एक बुनियादी बात कह रहे हैं। कृष्ण कहते हैं: “मेरी महिमा\nमहर्षि से लेकर ब्रह्मा तक देवता अज्ञात हैं। यहाँ 'शक्ति' शब्द तीन हैं\nअर्थ में प्रयुक्त। प्रभव का अर्थ है उत्पत्ति या उत्पत्ति; प्रभाव का अर्थ है क्षमता या\nमहानता; प्रभव जगत् की रचना है। “मेरी उत्पत्ति, मेरी महिमा और इस संसार की मेरी उत्पत्ति\nजन्मे-उन महान ऋषियों से जिन्होंने मुझे जाना, ब्रह्मादि जिन्होंने मेरा परोक्ष ज्ञान प्राप्त किया\nयहाँ तक कि देवता भी नहीं जानते,'' कृष्ण कहते हैं।",
  "10.3": "यं मम अजं अनादिं च वेत्ति लोक मह ईश्वरम् |\n\nअसम्मुधा सः मर्त्येषु सर्व पापैः प्रमुच्यते - मैं अजन्मा हूं। सब कुछ चल रहा है\nवह जो सभी चीज़ों से पहले था [अमरता के माध्यम से]। समस्त लोकों के स्वामी.\nजो मनुष्य मनुष्यों में मुझे इस प्रकार जानता है, वही मोहग्रस्त है। वह पापों से बच जाता है।\n\nहममें से कुछ लोगों का एक प्रश्न है. \"यदि प्रभु ने सभी जीवित प्राणियों को बनाया,\nइसे किसने बनाया।” यदि ईश्वर को दूसरे द्वारा बनाया जा रहा है तो हम हैं\nउनको भगवान नहीं कहा जाता था. कृष्ण जानते हैं कि हमारे संदेह क्या हैं।\nइसके लिए उन्होंने इस श्लोक में हमारे प्रश्न का उत्तर दिया है। कृष्ण कहते हैं “यहाँ मम अजम\n\"अनादिम\"। यहाँ \"अज\" का अर्थ अजन्मा है। भगवान जन्म और मृत्यु से परे हैं।\nइसके लिए यदि हम जन्म और मृत्यु से बचना चाहते हैं तो हमें उनकी पूजा करनी चाहिए और उनसे जुड़ना चाहिए।\nभगवान शाश्वत हैं. यहाँ अनादि (अना-दि) का अर्थ है: “वह जो सबसे पहले सृजन और निर्माण की प्रेरणा देता है\nइसे सर्वोच्च शक्ति बनाएं जो इस सृष्टि में सभी व्यवसाय को नियंत्रित करती है।'\n\nभगवान 'लोकमहेश्वरः'। ब्रह्मा सभी देवता हैं-'लोकेश'। उनकी माता लक्ष्मी-\n'लोकेश्वरी'. वह भगवान उसके लिए भी महान हैं - 'लोकमहेश्वर'। उससे भी बड़ा एक और\nकोई सिद्धांत नहीं है. वह जन्म और मृत्यु से परे है।\n\nवह भगवान हैं जिन्होंने महर्षियों, देवताओं, सभी को बनाया। तो वे सब उसके हैं\nमहिमा का अंत नहीं देखा है. ऋग्वेद में एक स्थान पर कहा गया है: न ते विष्णो\nजयामानो न जातो देव महिम्नः परमंतमपा'। यहाँ तक कि अतीत में जन्मे लोग भी,\nयहाँ तक कि इसके बाद जन्मे लोग भी भगवान की महिमा के चरम अंत को नहीं जानते और न ही जान सकते हैं।\nक्योंकि यह अनंत है.\n\nयह सृष्टि कैसे रची, यह कोई नहीं जानते। क्योंकि जलप्रलय के दौरान\nप्रभु के पेट में सब कुछ सो गया है, जिसके बाद सृजन के समय योग सबसे पहले था\nचतुर्मुख भगवान ने बनाया है। तो यह चतुर्मुख के जन्म से पहले ही शुरू हो गया था\nइस सृष्टि का निर्माण किसी ने नहीं देखा है। इसके लिए ऋग्वेद में ''यदि इस सृष्टि का रहस्य जान लिया जाए।''\nएक बुद्धिमान पुत्र को पता होना चाहिए\"। वह भगवान की रचना का पहला जीवन है - 'चतुर्मुख'\nब्रह्मा'. इन सबके कारण हम सामान्य मनुष्य परमेश्वर की पूर्ण महिमा हैं\nयह जानना असंभव है. आचार्य ने यह कहा: “बहु चित्र जगत् बहुदाकारनात्\nअस पराशक्तिरनन्त गुणः परमः”। यह ईश्वर की रचना की दुनिया है\nयह जितना महान है—वह रचनाकार भी उतना ही महान होगा। अतः भगवान अनन्त हैं\nउसे समझना और उसकी पूजा करना ही मोक्ष का एकमात्र मार्ग है। भगवान के बारे में ये सच्चाई\n\"असामुधा\" के नाम से जाना जाता है। वह सदैव बिना किसी भ्रम के सभी से और सभी में प्रेम करता रहता है\nवह प्रभु को देखता है। \"इस सत्य का अभ्यास करने वाला सभी पापों से बच जाता है\"\nयह कृष्ण का वचन है.",
  "10.4": "बुद्धिः ज्ञानं असम्मोः क्षमा सत्यं दमः शमः।\n\nसुखं दुःखं भवः अभवः भयं च अभयं एव च -- बुद्धिमता, जागरूकता,\nबुराई करने की इच्छा न करना, गलत काम करने वालों पर भी क्रोध न करना, साहस, इन्द्रियों पर संयम,\nईश्वर में निष्ठा, सुख-दुःख, जन्म-मृत्यु, भय-क्रोध ये सब मुझसे ही हैं।\nउठना।\n\nयहां कृष्ण एक महत्वपूर्ण बात बताते हैं कि हमें भगवान की पूजा करते समय जागरूक रहना चाहिए।\nवह प्रभु ही है जो हमें बुद्धि, ज्ञान, अविश्वास, क्षमा, सत्यम्, दमः-शमः प्रदान करता है।\nकुछ लोगों को यह भ्रम होता है कि वे बहुत बुद्धिमान हैं। लेकिन वह उस बुद्धि पर दयालु है\nवे परमेश्वर की सच्चाई को नहीं जानते। कृष्ण कहते हैं: “वह जो तुम्हें ज्ञान देता है\nमैं ज्ञान का दाता हूँ. यहां 'ज्ञान' का अर्थ किसी चीज़ के प्रति जागरूकता से है। \"बुद्धि\" का अर्थ है\nक्या करें और क्या न करें का ज्ञान। जब हमारे पास बुद्धि और ज्ञान दोनों हैं\nकेवल यह पूर्ण है. यदि ज्ञान रहेगा और बुद्धि नहीं रहेगी तो वेद हमसे दूर हो जायेंगे। “अचरा हीनम की।”\nपुनन्ति वेदः''-यदि कोई व्यक्ति अनैतिक है, तो सभी वेद उसे त्याग देंगे। पंख\nवेदविद्या उनके पास से वैसे ही उड़ गई जैसे युवा पक्षी अपने घोंसले से उड़ जाते हैं\nयह जानना कि भक्त होना चाहिए, ज्ञान है। लेकिन जो रीति है वही है\nविवेक चेतना-बुद्धि जो अधर्म है। निस्संदेह बुद्धि-ज्ञान के साथ सत्य भी\nजानने की क्षमता 'असम्मोह' है। ये तीन मुख्य चीजें हैं जो हमें जीवन में मदद करती हैं\nखंभे. हमें यह जानना चाहिए और उस प्रभु की आराधना करनी चाहिए।\n\nचौथा गुण है \"क्षमा\"। यह सबसे बड़ा गुण है. यदि कोई हमारी आलोचना करता है - उस आलोचना में\nयदि आत्मसुधार का तत्व है तो सुधार। अन्यथा यह सिर्फ ईर्ष्या है\nआलोचना के मामले में, बिना किसी प्रतिशोध के मामले को वहीं छोड़ देना \"माफी\" है।\n\nपाँचवाँ गुण 'सत्यम्' है। सत्यम का अर्थ है ईमानदारी। आज हम सज्जनता और सज्जनता को भूल जाते हैं\nनकाब में रहना. बेईमानी हमारे जीवन में व्याप्त हो गई है।\nईमानदारी के बिना संस्कृति की कोई भी संपत्ति किसी काम की नहीं है। एक व्यक्ति विपरीत है और\nपलट कर बात करना बेईमानी है. अगर हमें किसी दूसरे व्यक्ति का विचार पसंद नहीं आता\nया तो उन्हें सीधे बताएं या उनसे दूर रहें. हमारे अंदर ईमानदारी\n\nजब तक हम विकसित नहीं हो जाते, कोई भी विज्ञान हमें नहीं बचा सकता।\nहमें प्रभु से प्रार्थना करनी चाहिए कि वह हमें ऐसी ईमानदारी दे।\nछठा है दमाह. इसका संबंध इंद्रियों से है. हमारी इंद्रियाँ वैसी ही हैं जैसी हम कहते हैं\nनहीं पूछता वे हमें अवांछित दिशाओं में खींचते हैं। जो नहीं देखना चाहिए उसे देखकर,\nहम वह खेलते हैं जो नहीं खेलना चाहिए. ऐसा संयम दमः है। इंद्रिय दमन के लिए\nईश्वर के प्रति समर्पण ही एकमात्र रास्ता है।\n\nसातवां गुण है शमः। हमारा मन शांत है शमाः। आज\nहम सब अशांति में जी रहे हैं ! इसका मूल कारण हम स्वयं हैं\nमन को सांसारिक विषयों पर केन्द्रित रखना। सांसारिक विचार, मन को छोड़ दो\nजब भगवान की ओर निर्देशित किया जाता है, तो मन सहज हो जाता है। यदि जीवन में कोई समस्या है, तो \"ईश्वर है, वह है।\"\nजिस व्यक्ति को यह दृढ़ विश्वास है कि वह हार नहीं मानेगा वही इस स्थिति को प्राप्त कर सकता है। सामूहिक रूप से 'हमारी आंतरिक दुनिया\nहमें इस ज्ञान से पूजा करनी चाहिए कि सब कुछ भगवान ही है'- ऐसा यहां कहा गया है\nमूल संदेश.\n\nकृष्ण आगे कहते हैं: “सुख-दुख, जन्म-मृत्यु, भय-क्रोध, ये सभी प्रकार की चीजें।\nरास्ते मेरे कारण बनते हैं। सुख और दुःख द्वैत हैं। जीवन में दोनों\nएक साथ हैं और एक के बाद एक आते हैं. किसी की ख़ुशी दुःखी नहीं होती,\nदु:ख के बिना सुख नहीं है। यह हमारे जीवन में दिन और रात की तरह है। इस तथ्य को जानकर\nदुःख बुरा नहीं है. हमारे जीवन में उतार-चढ़ाव सामान्य बात है। जन्म और मृत्यु\nप्राकृतिक. यदि हमारे पास ज्ञान है तो भय है, यदि भय नहीं है। ये सभी भगवान के अधीन हैं।\n\nइस श्लोक में मनुष्य के मन में जो-जो भावनाएँ उत्पन्न होती हैं, उन सभी भावनाओं का वर्णन किया गया है\nकृष्ण ने हर चीज़ के पीछे भगवद शक्ति के बारे में बताया - परिवर्तन और प्रभाव। अगला\nश्लोक में, कृष्ण सात मानसिक गुणों का वर्णन करते हैं जिन्हें हमें अवश्य प्राप्त करना चाहिए।",
  "10.5": "अहिंसा समता तुप्पिः तपः (ए) दानं यशः अयः।\nभवन्ति भवः भूतानां मथथ एव पृथक विधः - अहिंसा, समता, संतोष, तपस्या,\n(अ)दान, (बुरा) नाम - ये सभी प्रकार की बातें मुझसे उत्पन्न होती हैं।\n\nकृष्ण कहते हैं: \"अहिंसा, समता, संतोष, तपस्या, (अ)दान, नाम, बदनामी\" मुझसे हैं।\nवह है। यहां अहिंसा और समभाव बहुत खास हैं। क्योंकि कभी-कभी हिंसा\nअहिंसा बन जाती है और असमानता समानता बन जाती है। उसके लिए यह विशेष रूप से यहां है\nकृष्ण ने प्रस्ताव रखा.\n\nपहली अहिंसा : दूसरों को नुकसान पहुंचाए बिना रहना ही अहिंसा है। यहाँ अहिंसा का अर्थ है\nहमें न केवल शारीरिक रूप से, बल्कि मन और वाणी से भी अहिंसा प्राप्त करनी चाहिए।\nउदाहरण के लिए: एक को मौखिक रूप से, दूसरे को मानसिक रूप से बदनाम करना\nगाली देना या श्राप देना भी हिंसा है। कभी-कभी हिंसा अहिंसा बन जाती है।\nउदाहरण के लिए: एक नरभक्षी बाघ एक कस्बे में कई लोगों को मार डालता है\nयदि वह शेष रहे तो उसे मार डालना अहिंसा है\nकार्यों में पाया गया]। बड़ी हिंसा को रोकने के लिए छोटी हिंसा-अहिंसा। हम हैं\nहमें अपने शब्दों, कार्यों और विचारों से दूसरों को नुकसान पहुंचाए बिना कार्य करना चाहिए।\nदूसरा गुण है समभाव (समतः): यहां समदृष्टि का अर्थ है सभी को एक रूप में देखना।\nइसका मतलब यह नहीं है कि यह योग्यता की समता है। उदाहरण के लिए: स्कूल में अच्छे से पढ़ाई करें\nएक छात्र जिसने लिखा है और दूसरा छात्र जिसने पढ़ाई नहीं की है, उन्हें समान अंक मिलेंगे\nदेना समानता नहीं है. बिना किसी बैर के, शत्रु, मित्र, देशी, परदेशी\nबिना किसी भेदभाव के योग्यता के अनुसार अंकों का वितरण ही समानता है। कौन जानता है कैसे\nयदि आप उन्हें देखना चाहते हैं तो उन्हें वैसे ही देखें जैसे वे हैं। पिता को पिता, माँ को माँ,\nबृहस्पति के लक्ष्य के रूप में. इस प्रकार जो समान हैं उनका सम्मान करना समानता है।\nतीसरा गुण है संतोष: असंतोष ही मनुष्य के सभी दुखों का मूल कारण है। आज के समाज में हम\nभले ही हमारे पास घर पर हमारी जरूरतों के लिए पर्याप्त सामान है, फिर भी मीडिया में जो विज्ञापन आते हैं\nमूर्खों के रूप में, या पड़ोसियों के प्रतिद्वंदियों के रूप में, हम सतत दुःख में रहते हैं। काम\nअगर काम की इच्छा नहीं है तो वेतन कितना भी हो, दुख रहता है। जो नहीं है उसके बारे में शिकायत मत करो,\nजो था उसमें आनन्दित होना वास्तविक संतुष्टि है।\nचौथा है तप: जिसके तीन प्रकार हैं: काया-वाचा-मनसा तपः। काया का अर्थ है शरीर।\nशरीर के माध्यम से प्रायश्चित करने का तात्पर्य यह नहीं सुनना है कि शरीर क्या कहता है - भोजन या भोजन\nप्रकारान्तर से। जब भोजन नियंत्रित होता है तो मन नियंत्रित होता है। मन\nयदि नियंत्रित किया जाए तो शरीर स्थिर रह सकता है। इसके लिए विभिन्न नियंत्रण उपकरणों का उपयोग किया जाता है\nवृतानुष्ठान। कुल मिलाकर अहंकार बिना ईर्ष्या किये झुक सकेगा। शरीर का\nतपस्या से. अच्छा बोलना, सच्चा-स्वाभाविक रूप से; शास्त्रों का श्रवण-मन\n\nकरो, फिर आत्म-चर्चा के साथ इसका अभ्यास करो और इसे पचाकर दूसरों को इसका उपदेश करो।\nअगली पीढ़ी को देना वाचा-तपः है। सदैव मानसिक रूप से गहराई से सोचना मनसा-तपः है।\nपांचवां है (ए)दाना: दाना शब्द के संस्कृत में दो अर्थ होते हैं। एक दूसरे को \"दे\" रहा है\n\"काट दो'। यदि देने से हमारा पाप कट जाता है, तो वह दान है। हमारा नहीं।\"\nयदि पुण्य काट दिया जाए तो वह अदाना है।\n\nहमारे लिए किसी अनुपयोगी वस्तु को ले जाने के लिए दिया गया दान दान नहीं है। बहुत\nयदि आवश्यक वस्तु दूसरे के पास नहीं है लेकिन हमारे पास है तो जो हमारे पास है उसे उसके साथ साझा करें\nदेने का अभाव ही सच्चा दान है। एक व्यक्ति के पास एक समय के भोजन के लिए समय नहीं है\nयदि हमारे पास संघर्ष करते समय दो वक्त के भोजन के लिए पर्याप्त अनाज है, तो हमारे कल के बारे में\nबिना सोचे समझे उस व्यक्ति को अनाज का एक दाना दान करना ही सच्चा दान है।\n\nदान में आसन-वासना-अन्न किसी को भी दान किया जा सकता है। रहने का स्थान,\nपहनने को कपड़े, भूखों को खाना। इसे देने के लिए फिट या अनफिट होने का कोई बंधन नहीं है.\nलेकिन अन्य वस्तुएं दान करते समय यह देखें कि किसके लिए क्या आवश्यक और योग्य है\nदान करें। प्रचार के लिए दान - अदाना. बिना किसी इच्छा के ईमानदारी से\nकर्तव्य के संदर्भ में, सही देश में, सही समय पर, सही व्यक्ति के प्रति\nदान ही वास्तविक दान है।\n\nअंत में कृष्ण यहां यशः-अयः कहते हैं। ये बहुत अजीब है. एक बुरा\nअच्छा होने से सफलता अर्जित की जा सकती है। जीवन भर अच्छे कर्म करो\nअवांछित अपवाद सुनने से विपत्ति आ सकती है। यही हमारे जीवन का निष्कर्ष है\nइस कदम पर। तो इस बारे में चिंता मत करो. अपवाद होने पर क्या होना चाहिए\nकृष्ण ने हमें अपने जीवन में यह दिखाया है। कृष्ण ने शमंतक मणि की चोरी की\nइसका अच्छा उदाहरण कृष्ण के अपवाद आने पर कृष्ण का व्यवहार है।\n\nइस प्रकार, कृष्ण कहते हैं, \"ये सभी भावनाएँ मेरे कारण अस्तित्व में आती हैं।\" किसको क्या\nयह प्रभु का निर्णय है कि समय पर कौन सा भाव आना चाहिए। हमारी मन:स्थितियों में से एक\nगति भगवान के अधीन है. यह वह बुनियादी बात है जिसे हमें अपनी पूजा में जानना आवश्यक है\nसत्य यह कृष्ण द्वारा दी गई मानसिक पूजा का अद्भुत चित्रण है।",
  "10.6": "महर्षयः सप्त पूर्वे चत्वः मानवः तथा |\n\nमत भवः मनः जाः यशं लोकाय इमः प्रजाः -- प्रथम मन्वन्तर के सात\nमण्डी महर्षि (मरीचि, अत्रि, अंगिरस, पुलस्क्रु, पुलह, क्रतु और वशिष्ठ), पहले चार\nमनु [स्वायंभुव, स्वारोचिष, उत्तम और रैवत], चतुर्मुख के मानस पुत्र।\nवह नन्नी 0डेल हैं।\nजो देवता 'मनु' कहलाते हैं वे सब मेरे ही हैं; मेरी इच्छा से जन्म लो\nजो आया।] संसार के ये सभी लोग उसकी संतानें हैं।\n\nहम जानते हैं कि संपूर्ण ब्रह्मांड ईश्वर द्वारा बनाया गया था। यहाँ हम कृष्ण हैं\nउपासना में जानने योग्य मुख्य बिन्दु बताते हैं। प्रथम मन्वन्तर के पक्षधर\nऔर पहले चार मनुओं का उल्लेख यहाँ कृष्ण ने किया है। हर मन्वंतर के लिए अलग\nविशेषज्ञ हैं. यह पहला मन्वंतर है जो देव भेद में सोलहवीं कक्षा में आता है\nख़ुशीमण्डल में सप्तर्षि बहुत महान हैं। पुराण एवं महाभारत का मोक्षधर्म पर्व\nदेखा जाए तो यहां \"महर्षय: सप्त पूर्वे\" चतुर्मुख, निर्माता के लिए है\nसमझा जाता है कि इसका तात्पर्य सहायक सप्तब्रह्मा से भी है। [यहां सूक्ष्म रूप से भृगु तथा\nकुशल को शामिल किया जाना चाहिए। मनसा के दसवें पुत्र नारद ब्रह्मचारी थे। इसलिए सृजन\nविस्तार में उनका नाम शामिल नहीं... ये सात खुशियां और भृगु-दक्षारांश\nइन्हें प्रजापति कहा जाता है। उनके द्वारा भगवान चतुर्मुख की रचना करें\nसप्तर्षियों की रचना हुई। सृष्टि में सबसे पहले मनुष्य की वंशावली मनु से उत्पन्न हुई\nउन्हीं से मनु वंश का उदय हुआ। इस सब के कारण पहले चार\nमन्वंतर के स्वामी और सुपरर्षि मुख्य रूप से पूजे जाने वाले हैं।\nसंसार के ये सभी लोग उन्हीं की संतानें हैं।\n\n'मनु' का एक और अर्थ है. भगवान का गण भी 'मानुस'\nवे कहते हैं कि तत्त्वभिमानी देवताओं के चार मुख्य प्रकार हैं। ये मनुष्य के चार हैं\nदेवता जो प्रकृति को नियंत्रित करते हैं (ब्राह्मण, क्षात्र, वैश्य, शूद्र)। यह हम में से प्रत्येक में है\nप्रकृति चार हैं. हम वही हैं जो प्रकृति ने हममें बढ़ाया है। उस वर्ग से\nहम कॉल करेंगे. इसके अलावा \"मनु\" जीव के चार वर्ग हैं: देवताओं से सभी देवता\nख़ुशियों की विरासत से ख़ुशियाँ (इंसान), \"इंसान\" पैदा कीं, ये\nमनुष्य विरासत से. उपासना में यह ध्यान रखने योग्य बात है।",
  "10.7": "एतम् विभूतिम योगम् च मम यः वेत्ति तत्वतः |\nसाह अविकाल्डेना. योगेन युज्यते न अत्र संशयः - यह मेरी महानता है\nजो मेरे गौरवशाली रूपों की विविधता] और गहराई को ठीक से जानता है वह शुद्ध है\nध्यान योग में स्थित हो जाता है। इसके बारे में कोई संदेह नहीं है।\n\nयदि हम वास्तव में भगवान की महानता, उनके विभिन्न रूपों, उनकी गहराई को जानते हैं\nनिःसंदेह समर्पण आएगा। ईश्वर का ज्ञान हमें आत्मविश्वास देता है।\nश्रद्धा और भक्ति से भरा हुआ मन भगवान में विश्राम करता है।",
  "10.8": "अहं सर्वस्य प्रभावः मततः सर्वं प्रवर्तते।\nइति मत्वा भजन्ते माम् बुधः भव समन्वितः जो जानता है कि \"मैं सभी चीजों का कारण हूं,\nसब कुछ मेरे साथ हो रहा है,' उसने मुझे भक्तिभाव से भरते हुए कहा।\n\nऋषियों ने कहा, “भगवान हर चीज़ के नियंत्रक हैं, सब कुछ भगवान द्वारा बनाया गया है, सब कुछ\nइस तथ्य को समझते हुए कि यह भगवान द्वारा नियुक्त है, वह भक्तिपूर्वक पूजा करता है। “इस तरह\nजिनके पास भगवान के प्रति अद्वितीय भक्ति और सर्वोच्च ज्ञान है: उनके मन की सभी दुनियाएं मेरी हैं।\nअधीनस्थ, मैं हर चीज का कारण हूं, सब कुछ मुझसे पैदा होता है, सब कुछ मेरे द्वारा नियंत्रित होता है,\nयह जानते हुए कि सब कुछ मेरे अधीन है, वह पूजा करता है,\" कृष्ण कहते हैं।\n\nमच्चि तत् मद्गतप्राण बोधयन्तः शिक्षायम् |\nकथ्यन्तश्च मम नित्यं थुप्यन्ति च रमण्तिचा...।",
  "10.9": "मत् चित्तः मत गता प्राहा बोध्यन्तः संसानम्।\nकथयन्तः च मम नित्यं तुष्यन्ति च रमन्ति च - अनुगला मेरे द्वारा, मेरे लिए बनाया गया है।\nजो जीवित हैं, वे मुझे एक दूसरे से जानते और जानते हैं; खुश होगे।\n\nइस प्रकार सच्चा ज्ञान और भक्ति रखने वालों के मन में सदैव भगवान के विचार भरे रहते हैं। उसका मन\nदिव्य छोड़ देता है. वे हर चीज़ में भगवान देखते हैं। यह हर इवेंट के लिए है\nवे इस ज्ञान में रहते हैं कि ईश्वर उनके पीछे है और सब कुछ उसकी इच्छा के अनुसार होगा। उसका\nमन ईश्वर की ओर उन्मुख हो जाता है। वह हमेशा भगवान के बारे में बात करता रहता है।\nवह हर चीज़ का विश्लेषण इस तरह करता है जैसे \"ईश्वर की रचना कितनी अद्भुत है\"।\nवे अपने जीवन की हर घटना को ईश्वर के उपहार के रूप में स्वीकार करते हैं।\nइनका जीवन आनंदमय रहेगा। उनमें कोई बुरे विचार नहीं होते. उसका मन\nसदैव शुद्ध. उन्होंने सांसारिक व्यापार की बातें छोड़कर ईश्वर का चिंतन किया\nहमेशा बात करने में मजा आता है.",
  "10.10": "तेषाम् सचदा युक्तानां भजताम् प्रीति पूर्वकम्।\nददामि बुद्धियोगं तम् येन माम् उपयन्ति ते - मैं स्वयं धन्य हो गया हूँ।\nमैं ज्ञान का वह मार्ग उन लोगों को प्रदान करता हूं जो प्रेम से इसका सेवन करते हैं। इस वजह से वे मैं हूं\n\nशामिल हो जायेंगे\n\nइस श्लोक में \"सतत्ययुक्तानाम्\" में आने वाले 'यक्ति' शब्द के संस्कृत में कई अर्थ हैं।\nअर्थ हैं. तरकीब यह है कि बिना भटके, बिना फिसले, बहुत योग्य अनुष्ठान करके जीना है,\nयुक्ति वैदिक अध्ययन को समझने की है जो भगवान के दृष्टिकोण का पूरक है। प्रभु में\nमन को स्थिर करने की युक्ति है। यहाँ कृष्ण कहते हैं: “भगवान् किस बुद्धियोग से\nयदि जुड़ना संभव हो तो ऐसा विचार करने वाले मन को श्रद्धापूर्वक विचार करना चाहिए\nमैं तुम्हें बुद्धि, निश्चित ज्ञान दूँगा। प्रेम से भगवान को समर्पित कर दिया\nजब प्रभु की सेवा की जाती है तो प्रभु स्वयं ही प्रभु से जुड़ने का मार्ग दिखाते हैं।\n\nतेषामेवेनुकम्पार्थमहमज्जनजं तमः।\n\nनाशयमात्मभावस्थो ज्ञानदीपेन भास्वत",
  "10.11": "तेषाम् एव अनुकंपार्थम् अहं आज्ञा जम तमः।\n\nनाशयामि आत्म भव स्थ ज्ञान दीपेण भास्वत - मैं उनकी करुणा से बाहर हूं, उनकी\nरास्ते में खड़ा होकर, मैं चमकते हुए ज्ञान के प्रकाश से अज्ञानता के अंधेरे को दूर करता हूं।\n\nईश्वर हमें स्वार्थी कारणों से नहीं बचाता। बल्कि हमसे ऊपर\nदया के कारण. वे उस भक्त पर दया करते हैं जो अनन्य भक्ति से उनकी पूजा करता है\nहमें बचाता है. वह हमें न केवल बुद्धि देता है, बल्कि सदैव हमारी बुद्धि भी देता है\nवह तमस (अज्ञान) का कफन हटाने वाला भी है। ईश्वर की सहायता के बिना हम हैं\nमन-बुद्धि में घुसे अज्ञान के परदे को हम स्वयं दूर नहीं कर सकते। तीन गुना\nइस अंधकार को केवल भगवान ही दूर कर सकते हैं। इससे हम सत्य को सत्य के रूप में ग्रहण करते हैं\nप्रभु हमें भक्ति से भर सकते हैं, हमारे स्वभाव को जागृत कर सकते हैं, दयालु बन सकते हैं\nवह दृष्टि देता है, हर प्रकार से प्रकाश देता है, सत्य का दर्शन कराता है। इसके लिए\nहमें यह कहते हुए उसके प्रति समर्पण करना चाहिए, \"हे प्रभु, मेरे भीतर के अंधकार को दूर करो। भीतर के अंधकार को।\"\nकितना भी रख-रखाव करके पढ़ लो, कोई फायदा नहीं। जब आप धर्मग्रंथ पढ़ते हैं तो सत्य\nईश्वर में समर्पण जानना महत्वपूर्ण है।\n\nइस समय, कृष्ण की सलाह सुनकर अर्जुन स्तब्ध हो गए। वह युद्ध के मैदान में है\nवह भूल जाता है कि वह खड़ा है और उसे केवल कृष्ण ही दिखाई देने लगते हैं। अगला\nचार श्लोकों में अर्जुन का भगवान अर्जुन की अनंत शक्ति के प्रति दृष्टिकोण\nहम इसे अभिव्यक्त होते देखते हैं।",
  "10.12": "अर्जुन उवाच —\nपरं ब्रह्म परं धाम पवित्रं परमं भवान् ।\nपुरुषं शाश्वतं दिव्यमादिदेवमजं विभुम् ॥\n\n'आप परम ब्रह्म, परम धाम, परम पवित्र हैं। आप शाश्वत दिव्य पुरुष, आदिदेव, अज, विभु हैं।'\n\nअर्जुन का यह उद्गार — भगवान् की विभूतियों की लम्बी सूची सुनने के बाद। 'परं ब्रह्म' — परम सत्ता। 'आदिदेव' — देवों के देव। 'अज' — जन्मरहित। 'विभु' — सर्वव्यापी। मध्वमत में 'परं ब्रह्म' = नारायण।",
  "10.13": "अर्जुनः उवाच--अर्जुन ने कहाः\n\nपरमं ब्रह्म परमं धाम पवित्रं परमं भवनं।\nपुरुषं शाश्वतं दिव्यं आदि देवं आजम विभुम् ॥\nअहुः त्वम् खुशायः सर्वे देव खपिः नारदः तथा।\n\nअसितः देवलः व्यासः स्वयं च एव ब्रविशि मेई - आप, धन्य, बड़ों से भी महान सिद्धांत हैं।\n\nवरिष्ठ सहयोग. पवन भी पवन. आप सदाचारी, परम व्यक्तित्व के रूप में,\nअपरिवर्तनशील, लीलामय, सबसे पहले देवता, अजन्मा,\nजो सर्वत्र विविध रूपों से परिपूर्ण है, उसकी प्रशंसा वे सभी करते हैं जो उसे जानते हैं। देवर्षि नारद भी.\nअसित-देवों को भी. व्यास ने कहा. क्या आप स्वयं मुझे बता रहे हैं?\n\nयहाँ अर्जुन कृष्ण को \"परमब्रह्म, परन्धम, परमपवित्र आप\" कहकर संबोधित करते हैं।\nजो सबसे बड़ा है वह ब्रह्म है। ब्रह्म शब्द के और भी कई अर्थ हैं\nउपयोग उसने यहाँ स्पष्टता के लिए 'परमब्रह्म' कहा है। “सबसे महान और\nतू परिपूर्ण है, जो विश्वास करनेवालों को ऊपर उठाता है। मेरे व्यक्तित्व की संपूर्णता को देखने के लिए मैं आपका हूं\nइस सम्बोधन में स्वर है \"अनुग्रह वरदा\"। परम धाम: 'धाम' का अर्थ है आश्रय।\nइस संसार में ऐसी कोई वस्तु नहीं है जो ईश्वर की शरण न लेती हो। “आप संप्रभु हैं, और\nहम सब आपकी प्रजा हैं, आप शरण हैं और हम आश्रित हैं” अर्थात् अर्जुन\nउन्होंने कृष्ण को 'परन्धम' कहा। भक्तिमय देवता किसी न किसी रूप में हमें आश्रय देते हैं\nपरन्तु भगवान परान्धम ऐसे देवताओं के आश्रय हैं। सभी जीवित चीजें\nअनंत यात्रा में आश्रय बनकर बचाने वाले भगवान सर्वाश्रयधाता हैं।\n\nभगवान 'पवित्र' हैं. ऐसे भगवान हम पवित्रता के प्रतीक अग्नि के समक्ष हैं\nहम पूजा करेंगे. अग्नि स्वयं पवित्र है और कभी गंदी नहीं होती। उसके स्पर्श से अग्नि\nआने वाली सामग्री को रोगाणुहीन बनाता है। भगवान हमें और दुनिया को आशीर्वाद दें\nसर्वोच्च शक्ति\n\nअर्जुन यहां वह परब्रह्म है जो उसके सभी शारीरिक संबंधों से परे उसके सामने खड़ा है\nदेख रहा है \"मैं गंदगी से भरा हूं, ईर्ष्या और अधीरता से भरा हूं। आपकी कृपा से, आपके आश्रय से।\"\nमुझे पवित्र होना चाहिए. मुझे उस ऊँचाई तक पहुँचना है और तुमसे अपनी पूर्णता प्राप्त करनी है\nअर्जुन के इस सम्बोधन में ही इच्छा निहित है।\n\nकभी-कभी हम गुस्से में आकर जरूरत से ज्यादा बातें कर बैठते हैं। इधर अर्जुन स्वयं घबराये हुए हैं\nवह सुनिश्चित करता है कि वह बात नहीं कर रहा है। यह एक अभ्यासी के लिए भगवान की पूजा में है\nबहुत महत्वपूर्ण बिंदु. क्योंकि ईश्वर के बारे में हम जो भी कल्पना करते हैं वह मात्र एक भ्रम है\nअहसास नहीं. हमारी कल्पना हमारी मनःस्थिति पर निर्भर करती है। मन में जोश\nजब भी कोई बात होती है तो नए-नए विचार आते हैं। उनमें से सभी सच नहीं हैं. तो\nयह उनकी बुद्धि के स्तर के अनुसार उनकी कल्पना है, लेकिन हमारा ईश्वर जैसा है वैसा ही है\nकोई अनुमान नहीं। इस कारण अर्जुन के यहाँ आने का विचार उसकी बुद्धि का विचार नहीं था\n\nवह सुनिश्चित करता है कि यही मामला है। देवर्षिनारद ने कहा, वह खुश हैं\nउन्हें यहां का भाषण याद है.\n\nअर्जुन कहते हैं, “ये महात्मा आपको पुरुष, सवः, दिव्यः, आदिदेवः अजः, विभुः कहते हैं।\nउन्होंने कहा. यहां प्रयुक्त प्रत्येक शब्द में ईश्वर का अनंत गुण छिपा हुआ है।\nविष्णुसहस्रनाम में हम इन सभी शब्दों को भगवान के नाम के रूप में पाते हैं। चलो, यहाँ\nआइए इन शब्दों के अर्थ पर संक्षेप में चर्चा करें:\n\nपुरुष: यहां पुरुष का मतलब पुरुष नहीं है। जो पुर में रहता है वह 'पुरुष' है। संपूर्ण\nवेदों के सर्वोत्कृष्ट सूक्तों के राजा 'पुरुषसूक्त' भगवान को \"सहस्र शीर्ष पुरुषः\" कहते हैं।\nसृष्टि के निर्माण के समय, जब कुछ भी नहीं था, ईश्वर ने इस सृष्टि की रचना की\nपुरुषः. भगवान पुर-उषा जिन्होंने जलप्रलय के दौरान सब कुछ जला दिया। संसार में अनंत, अनंत\nभगवान पुरा-साहा, जो समय, अनंत क्षमता, अनंत गुणों से भरे हुए हैं। बाढ़ के दौरान कुछ भी नहीं\nभगवान जो वहां नहीं थे, उन्होंने सृष्टि के समय सबसे पहले प्रत्येक को अपनी नाभि से बनाया\n\"महत्व\" बनाया। महत्व संपूर्ण विश्व का आध्यात्मिक जागरण है। अतीत में था\nसमस्त सृष्टि की स्मृति को सूक्ष्म रूप जगत के प्रेमी ब्रह्म-वायु को देना\nनिर्माण फिर देवों, पंचभूतों की रचना। इस प्रकार सकल का निर्माण हुआ\nभगवान ने ब्रह्मांड को भर दिया। प्रत्येक पिंड के भीतर एक रूप में छवि\nइसे प्रपत्र में भरकर उस पिंडदान से जो कर्म करना हो वह करो, जिससे मोक्ष मिलेगा\nभगवान पुरुष. इस प्रकार सृजन से पहले, सृजन के दौरान, निर्मित पदार्थ के भीतर, सृजन का\nप्राप्ति में, प्राप्ति से मुक्ति तक, यह हृतकमल, मध्यस्थ भगवान, सर्वत्र व्याप्त हैं।\nपूर्ण षड्लूनों से परिपूर्ण ज्ञानानंद स्वरूपा। पु-रु-शाह-पुरुष;; यहाँ 'पु' का अर्थ है\nपवित्र वह जो हमें पवित्र करता है। संसार की सभी ध्वनियों में से 'रु' का अर्थ 'रुवंती' है\nजो पढ़ा हुआ हो। 'शह' या 'सह' का अर्थ है सार्वभौमिक सिद्धांत जो सभी चीजों में व्याप्त है।\nइस प्रकार, भगवान का नाम पुरुषः कई तरीकों से भगवान का आह्वान करने के लिए उपयोग किया जाता है\nनाम.\n\nशाश्वत: शाश्वत, अनंत समय में अपरिवर्तनीय\nआनन्दस्वरूपा भगवन्ता सवस्ताः।\n\nदिव्या: दिव्या शब्द के कई अर्थ हैं। मूल रूप से दिव्य या 'भगवान' ये शब्द हैं 'दिवु'\nतत्त्व से व्युत्पन्न. प्राचीन धातु पाठों में इस धातु के सात अर्थ देखे जा सकते हैं;\nवे हैं: 1) ध्युति 2) विजिगीषा 3) कांति 4) स्तुति 5) व्यापार 6) खेल 7) गतिषु।\n\n1) ध्युति: ध्युति का अर्थ है प्रकाश का रूप। सूर्य, जो प्रकाश का स्रोत है, चंद्रमा के लिए प्रकाश है\nप्रभु हमें ज्ञान के प्रकाश से भर देते हैं।\n\n2) विजिगीषा: भगवान सर्वोच्च और विजय स्वरूप हैं।\n\n3) कांति: जो केवल इच्छा से सृजन कर सकता है। जिसने हमें इच्छा दी है और यह उसका है\nयोग्यता के अनुसार पूर्ति.\n\n4) स्तुति: जिसकी सभी प्रशंसा करते हैं; जिसकी हर कोई तारीफ करता है, वही बुलंद आवाज बन जाता है\nप्रभु.\n\n5) व्यवसाय: वह जो संसार के समस्त व्यवसाय का संचालन करता है।\n\n6) खेल: सृजन-स्थिति-संहार यह भगवान के लिए एक खेल है।\n\n7) गतिषु: गति और ज्ञान देने वाले भगवान। जो हर जगह रहा है; सब कुछ जानता है;\nवह जो सबके भीतर बिम्बा के रूप में निवास करता है वह दिव्य या 'देव' है।\n\nआदिदेवः: जिनके लिए इस संसार की उत्पत्ति-स्थिति-संहार ही लीला है, वे आदिदेवः हैं। प्रभु यह\nवह जो तब भी मौजूद रहता है जब दुनिया मौजूद होती है और जब यह मौजूद नहीं होती है। वह सबसे ऊपर है. सब\nवह वही है जो समय में भी संसार के सभी कार्यों का संचालन करता है। इस प्रकार सब कुछ भीतर है, सब कुछ\nभगवान आदिदेव जो कर्मों का आचरण करते हैं।\n\nअजः 'न जायते इति अजः; 'जा' का अर्थ है जन्म; अ-जाह-अजाह का अर्थ है अजन्मा। अजन्मा\nनाभि में उत्पन्न चतुर्मुख को अजा कहा जाता है। ऐसे चतुर्भुज के भीतर अन्तर्निहित, सृष्टि\nवह ईश्वर जो बिना जन्में ही सृष्टि करता है, सब कुछ बनाता और नष्ट करता है। सब लोग\nभगवान के बच्चे, लेकिन उनका जन्म किसी से नहीं हुआ। क्योंकि उसका कोई जन्म और मृत्यु नहीं है।\nअजः का अर्थ सर्वव्यापी भी है। अ-जा-अजाह. यहां 'ए' का मतलब 'नहीं' है।\nया नहीं! यानी वह ऐसी चीज़ नहीं है जिसे हम जानते हों. उसमें कोई दोष नहीं है.\nदूसरे अर्थ में अजः का अर्थ है वह जो किसी से पैदा नहीं हुआ है - बल्कि सभी में पैदा हुआ है!\nक्या आपका मतलब इसके विपरीत है? हाँ, ईश्वर किसी से जन्मी कोई चीज़ नहीं है। लेकिन छवि\nवह हर गर्भ में एक रूप में निवास करता है और एक साथ कई रूपों में जन्म लेता है।\nगर्भवती स्त्री के गर्भ में भगवान एक छवि के रूप में जन्म लेते हैं।\n\nविभु: वैश्य-भवति- का अर्थ है विभिन्न रूपों में मानवरूपी व्यक्ति। पूरी दुनिया में सर्वशक्तिमान\nभगवान विभु से परिपूर्ण.\n\nयहां अर्जुन ने विशेष रूप से देवर्षि नारद, असित-देवल और व्यास के नामों का उल्लेख किया है।\nक्योंकि अर्जुन ने उसे देखा था और भगवान के बारे में बात करते हुए सुना था। नारद\nहम उस महान ज्ञान को जानते हैं। देवभेद में वे चौदहवें हैं\nवे सीढ़ियों पर हैं. जब धर्मराय के दरबार में भगवान की अग्रपूजा आयोजित की गई तो उन्होंने आकर प्रार्थना की\nभगवान का आनंद. स्नायु समुदाय में अज्ञान का नाश करो, ईश्वर का ज्ञान करो\nनारद दाता हैं, अंतर्ज्ञान की देवी जो हमें सत्य से अवगत कराती हैं। आज्ञा का पहिया\n\nजागृत होने पर हमें नारद के दर्शन होते हैं। क्या करें, क्या करें\nजो सहज भाव से उत्तर देते हैं कि ऐसा नहीं करना चाहिए। असित-देवता\nवैदिक काल के आनन्द द्रष्टा के रूप में। उसने धर्मरायण की सभा में आकर उससे कहा\nअर्जुन ने उन्हें उपदेश देते देखा था। अब और नहीं व्यास: वेदों को विभाजित करें, हमारे लिए\nभगवान के अवतार जिन्होंने अठारह पुराण, महाभारत, पंचवेद दिये। “ये सब\nअर्जुन कहते हैं कि आप मुझे वही बता रहे हैं जो महात्मा ने कहा था। इस प्रकार\nअर्जुन यह सुनिश्चित करता है कि वह जो अनुभव कर रहा है वह सिर्फ एक भ्रम नहीं है।",
  "10.14": "सर्वं एतत् खुत्तं मन्ये यत् माम् वदसि केशव |\n\nनहिते भगवान बैचिम विदुः देवः न दानवः - हे केशव, आपने मुझसे क्या कहा?\nमैं जानता हूं वह सब सच है. हे प्रभु, जिस रीति से तू उत्पन्न हुआ, हे देवता भी,\nदानदाताओं को भी जानकारी नहीं है.\n\n“मैं जानता हूँ कि आप जो कह रहे हैं उसमें कोई अतिशयोक्ति नहीं है\nवह कहते हैं, ''न तो देवता और न ही उपकारी प्रकटीकरण को जानते हैं।'' अर्जुन. देवताओं को\nईश्वर के गुणों को मापा नहीं जा सकता... दान देने वाले ईश्वर में दोष हैं\nखोज सफल नहीं रही. क्योंकि भगवान असीम रूप से अच्छा है. उसका कोई भी\nकोई त्रुटि नहीं. उसे पूरी तरह समझ पाना असंभव है. उसे भगवान के बारे में क्या कहना चाहिए?\nजब तक कोई दूसरा इसका वर्णन न कर सके. प्रभु का पूर्ण ज्ञान हो,\nउनका एक भी अवतार या अवतारों में उनकी एक भी लीला पूर्ण नहीं है\nइसे समझना कठिन है. हम यह नहीं समझ सकते कि कृष्ण ने अपने अवतार में कैसा व्यवहार किया।\nहमें यह अजीब लगता है. उन्हें जानना कोई आसान काम नहीं है. उसका एक\nआंदोलन के पीछे एक संदेश है.",
  "10.15": "वक्षुमर्हास्यशेषेण दिव्य हात्मविभूतयः |\n\nयाभिर्विभूतिभिर्लोकनिमनस्त्रं व्याप्य तिथिसि",
  "10.16": "स्वयम् एव आत्मान आत्मानं वेच त्वम् पुरूषोत्तम |\nभूतेश देवदेव जगत पते भूतभावना।\nवक्तुम अर्हसि अश्शेन दिव्यः हि आत्मविभूतयः |\nयाभिः विभूतिभिः लोकं इमान त्वं व्याप्य तिथिसि - हे पुरूषोत्तम, आप स्वयं हैं।\nमैं तुम्हें तुमसे जानता हूं. हे सभी प्राणियों के निर्माता, सभी प्राणियों के भगवान,\nदेवताओं के स्वामी, लोकों के स्वामी, आप किन रूपों से इन सभी लोकों की रचना करते हैं?\nआपके विभिन्न रूपों की भव्यता को छोड़े बिना, जो बहुत अलौकिक हैं\nआपको समझाना चाहिए.\n\nअर्जुन कहते हैं: “तुम्हारे गुणों को देवता भी नहीं माप सकते\nरास्ता तो तुम ही जानते हो. ये आपको खुद ही कहना होगा, किसी और से नहीं\nकह नहीं सकता. क्योंकि तुम मर्दाना हो. यहाँ पुरूषोत्तम एक विशेषण है\nइस्तेमाल किया गया। पुरूषोत्तम का अर्थ है जो क्षर (जीवन) से परे है। थान अक्षरा (रिश्ता)।\nबुजुर्ग \"तुम्हारे अलावा कोई अन्य सिद्धांत नहीं है सिवाय तुम्हारे जो अक्षरों से परे है। इसलिए, यह।\"\nअर्जुन ने भावना व्यक्त की कि इसका स्पष्टीकरण आपसे जानना चाहिए\nपता बताता है.\n\nयहां अर्जुन कृष्ण- भूतभावन, भूतेश, देवदेव तथा। जगत पाटे\nसंबोधित किया। भूतभावना का अर्थ है- पांच आयामी दुनिया, सभी जीवन का निर्माण करना-\nजो जाति की उत्पत्ति-स्थिति-विनाश के लिए उत्तरदायी है। भूतेश का अर्थ है - सबको नियंत्रित करने वाला\nनियमका स्वामी. देवदेव का अर्थ है - सभी देवताओं का भगवान; सूर्योदय के लिए\nमूल ज्योति जो प्रकाश देती है। जगत पति में 'पति' का अर्थ अभिभावक होता है। वह जो उत्पन्न करता है\nप्रभु, मारने वाला भी प्रभु है। वह जन्म और मृत्यु से रहित मोक्ष दाता भी है। वह सब कुछ है\nविश्व के संरक्षक. भगवान द्वारा हमें 'संसारबंध' देना उनके पालन-पोषण और शिक्षा का एक पहलू है\nइतना ही। सामान्य तौर पर, अर्जुन को लगता है कि \"आपके बिना हम नहीं हैं, आप हर चीज के रक्षक हैं\"।\nव्यक्त किया है",
  "10.17": "कथं विद्यां अहं योगिन त्वं सदा परिचिंतयं |\n\nकेशुकेषु च भावेषु चिन्त्यः असि भगवान माया-सर्वसमर्थक, अनुगला आपका कैसे समर्थन करता है?\nक्या मैं परिवेश को जान सकता हूँ? हे भगवान, चीजों में चीजें कैसी हैं?\nक्या मुझे याद रखना चाहिए?\n\nइस संसार की प्रत्येक वस्तु में एक अद्वितीय गुण के पीछे भगवान की विभूति निहित है।\nयहाँ अर्जुन भगवान से प्रार्थना करता है: “आप कहाँ हैं, सर्वशक्तिमान?\nमैं जानता हूं लेकिन मैं खुद नहीं। जब मैं कोई चीज़ देखता हूँ तो मुझे उसके पीछे की भगवद् शक्ति का स्मरण हो आता है\nमुझे आना है। मैं किसी भी वस्तु में आपकी पूजा कर सकता हूं - वह मैं हूं\nजानना चाहिए\"।",
  "10.18": "वस्त्रेण आत्मानः योगं विभूतिम च जनार्दन।\nभूयः कथय त्रिष्ठिः हि सृन्वतः न अस्ति मेइ अमृतम्--हे जनार्दन, अपनी गहराइयों को भी फैलाओ।\nस्वरूपों का माहात्म्य और भी अधिक बताइये। मैं इस सुधा से पर्याप्त मात्रा में नहीं मिल सकता।\n\nअर्जुन ने कृष्ण से पूछा, \"मुझे अपनी विभूति के बारे में और बताओ।\" प्रभु का\nविभूति मुख्यतः चार प्रकार की होती है। (1) साक्षात विभूति: यहां भगवान हमारे लिए अपने अद्वितीय रूप में हैं\nपृथ्वी पर प्रकट होता है. उदाहरण के लिए: भगवान के अवतार. (2) जातीयता\nनिर्माता उदाहरण के लिए: चंद्रमा, सितारों का राजा। यहां चंद्र सितारों की जाति से नहीं बल्कि वह से संबंधित है\nसितारों का राजा. (3) स्वजाति की सृष्ट प्रभा। उदाहरणार्थ: देवताओं में इन्द्र, प्रकाश में सूर्य। (4)\nस्वजाति एकदेशीय सृष्ट प्रभा। उदाहरण के लिए: पांडवों में अर्जुन। इस प्रकार इन चार प्रकार से\nभगवान के विभूति रूप अनंत हैं। हम यहां हर चीज़ की पूजा नहीं कर सकते.\nइसके लिए अर्जुन उपासना उपयोगी है, \"अपनी भावनाओं को विस्तार से कहें\"\nवह कृष्ण से पूछता है।\n\nकृष्ण का संदेश सुनकर अर्जुन आनंद के सागर में तैर रहा है। वह कहता है: “मैं हूं\nमैं अमृत पी रहा हूं, मुझे नहीं लगता कि यहां काफी है. यह स्वास्थ्यप्रद है, कीवी",
  "10.19": "भगवान उवाच- भगवान बोले:\n\nअवस्था ते कथैष्यामि दिव्यः हि आत्मा विभूतयः |\n\nकुरुश्रेष्ठ की संपत्ति मुख्य रूप से मवेशियों और भेड़ों के सामने है, भाले! मेरा अलौकिक\nमुझे कुछ विभूति रूपों का चयन करने दीजिए। मेरी कास्टिंग का कोई अंत नहीं है.\n\nसंस्कृत में 'हंता' शब्द खुशी और विस्मय व्यक्त करने के लिए इस्तेमाल किया जाने वाला शब्द है। कृष्ण\nअर्जुन की रुचि देखकर वह उनकी 'भले' कहकर प्रशंसा करते हैं।\n\nआज वेदांत को कोई सुनना नहीं चाहता. \"हमारे पास समय नहीं है\" स्लिप\nमानसिक रूप से बढ़े हुए हैं, उन्हें 'नो टाइम' पसंद नहीं है\nढकने के लिए इस्तेमाल किया जाने वाला शब्द! अगर हमें यह पसंद है, तो समय होगा! यहां कृष्ण को अर्जुन की चिंता है\nवह सराहना करते हुए कहते हैं, ''मैं आपको वह जरूर बताऊंगा जो आप सुनना चाहते हैं.''\nभगवान की विभूति दिव्य एवं अनंत है। यह पूरा नहीं कहा जा सकता.\nयहां भगवान कृष्ण की विभूति का संक्षिप्त सारांश दिया गया है जिसकी हमें मुख्य रूप से पूजा करनी चाहिए\nकिया और कहा.\n\nयहाँ 'कुरुश्रेष्ठ' विशेषण का प्रयोग हुआ है। स्वयं भगवदुपासना के मार्ग पर\nइसमें शामिल अभ्यासकर्ता कौरव हैं। यह अध्यात्म के लिए आवश्यक न्यूनतम योग्यता है। “आप आध्यात्मिक हैं\nउपलब्धि में उच्च. आप इस उपलब्धि को लेकर चिंतित हैं. बेशक आपको करना चाहिए\nइस सम्बोधन के पीछे \"मैं आपको बताऊँ\" की भावना है।",
  "10.20": "अहं आत्मा गुडाकेश सर्वभूत आशायस्थितः |\n\nअहं अदीह च मध्यम च भूतानाम अन्तः एव च-हे गुडाकेश, सभी गुणों का निवास।\nमैं वह वासी हूं जो सभी प्राणियों के हृदय में निवास करता हूं। मैं ही समस्त प्राणियों का मूल, केंद्र और मूल हूं\nअंत\n\nविभूति का कुल सार यह है: भगवान सबमें व्याप्त हैं। कृष्ण\nकहते हैं: \"मैं हर प्राणी के भीतर आत्मा के रूप में भरा हुआ हूं। मैं सभी जीवित प्राणियों की आत्मा हूं।\"\nवह है। कुछ लोग ग़लत कहते हैं कि इस श्लोक में ''जीवात्मा-परमात्मा एक ही है''।\nलेकिन कृष्ण ने यहां जो कहा वह यह है कि 'मैं जीवित आत्मा की आत्मा से भरा हुआ हूं'\nपरन्तु 'मैं जीवात्मा हूँ' नहीं। यह प्रत्येक जीवित प्राणी में निहित है\nबिम्बारूपी का तात्पर्य भगवान से है। भगवान “सर्वशक्तिमान” हैं\nवह हृतकमाला हृदय की गुफ़ा में अन्तर्यामी बनकर खड़ी है। यह भगवान की बेटी है\nबड़ी विभूति. भगवान अनंत जीव के भीतर अनंत विभूति के रूप में प्रकट होते हैं। यह\nकारण के कारण हम प्रत्येक जीवन में प्रत्येक ऊर्जा विशेषता पाते हैं। सभी जीवित प्राणी-\nजन्म से पहले उनके भीतर एक नियंत्रक के रूप में खड़ा होना, उनकी रचना का कारण बनना, उन्हें\nविपत्ति के समय भी, हर स्थिति में, सबकी रक्षा करें, रक्षा करें\nखड़े होने और बचाव करने की शक्ति.\n\nयहाँ गुडाकेश का प्रयोग विशेषण के रूप में किया गया है। यह भी एक विभूति गमक है. 'गुडका' का अर्थ है\nनींद 'गुडाकेश' का अर्थ है नींद को जीतने वाला। अर्जुन के पास यह विशेष योग्यता थी। उसके लिए\nउन्हें इसी नाम से बुलाया जाता था. \"आप नींद पर विजय पाने की शक्ति से भरे हुए हैं\nइसी सम्बोधन में स्वर है \"मैं हूँ।\" इस अध्याय के अगले भाग में, कृष्ण अपना विशिष्ट स्वरूप हैं\nविभूति बताते हैं.",
  "10.21": "आदित्यं अहं विष्णुः ज्योतिषम् रविः अंशुमान्।\n\nमरीचिः मरुथम अस्मि नक्षत्रनाम अहम् शशि-अदिति के बारह पुत्र [जहाँ भी\nसर्वव्यापक, सर्वव्यापी होने के कारण मैं विष्णुनामक[वामन] हूं। रोशन\nमैं रवि हूँ, शक्तियों में किरणों से चमकने वाला परम प्रकाश।\n\nमैं रावी नाम से हूं।] मारुतों की संतानों में से मरीचि प्रथम, [बाल-जल से भरपूर\nमैं सूजन और खुजली के कारण वेंटिलेशन के 'चमत्कार' में हूं।]\nचंद्रमा, नक्षत्रों का स्वामी [शा के सभी सुखों में से, शि चंद्रमा में ``शशि'' के सबसे शुभ रूप में है।\nमेरे पास उसके सितारे हैं।\n\nउनकी विभूति की बात करें तो सबसे पहले उनकी दैनिक पूजा में कृष्ण का बहुत महत्व है\nस्वरूपा विभूति से कहती है। अदिति (द्वादशादित्य) के बारह पुत्रों में से-\nविवस्वान (सूर्य), अर्यमा, पूषा, त्वष्टा, सविता, भग, धाता, विधाता, वरुण, मित्र, इंद्र,\nऔर वामन के रूप में विष्णु) एक भगवान का सच्चा अवतार हैं। वह वामन रूप में विष्णु हैं। इसलिए\nकृष्ण कहते हैं, \"मैं द्वैतों में विष्णु हूं\"। अब आदित्य का अर्थ है सभी देवता\nइसका मतलब है कि भगवान विष्णु सभी देवताओं में सर्वश्रेष्ठ हैं।\n\nइस अध्याय में आने वाला प्रत्येक नाम भगवान का विभूति नाम है। इसलिए\nप्रत्येक नाम के पीछे कई अर्थ छिपे होते हैं । इस श्लोक में\nपहले आने वाले भगवान का विभूति नाम \"विष्णुः\" है। विष्णु नाम का क्या अर्थ है?\nआइए एक संक्षिप्त नजर डालें: पुराण में, यदि आप भारत में बंदीतक्का के पौराणिक अर्थ को देखते हैं\nत्रिधातु से 'विष्णु शब्द' निष्ठान्न है। यह समझ में आ गया है. (1) दृश्य-क्षेत्र (2)\nविशति-प्रवेशे (3) वेति- प्रजानयति, गति, कांति, कदनेषु, गच्छति। इस तात्विक अर्थ में\nदेखा - विष्णु का अर्थ है सर्वव्यापी (वपु। वह हर चीज और हर चीज से बाहर है\nवह विष्णु है क्योंकि वह प्रवेश से परिपूर्ण है। इसे नारायण सूक्त में \"अन्तर बहिश्च तत\" के रूप में वर्णित किया गया है\n\"सर्वं व्याप्त नारायण स्थितः\"। अब \"वेति-विष्णुः\" नहीं... कौन-कौन\nजो शरण में आता है वह विष्णु-सर्वश्रयधाता भगवान है। 'वेति-प्रजानयति'-जो समग्र है\nवह विष्णु हैं जिन्होंने संसार की रचना की। वेति-गति'- सर्व-रक्षा करने वाला\nभगवान विष्णु 'वेति-कांति (इच्छा) - पूरी दुनिया की रक्षा और उद्धार करने का सच्चा दृढ़ संकल्प\nविष्णु मौजूद हैं. 'वेति-कादनेषु' - जो संपूर्ण जगत का नाश करता है, वह विष्णु है।\n'वेति-गच्छति' - वह जो तीन चरणों में त्रिविक्रम के रूप में तीनों लोकों में व्याप्त है।\nविष्णु. विष्णु का संपूर्ण अर्थ 'ईश्वर' है, जिसे हम विष्णु शब्द से प्राप्त करते हैं\nअनुसरण करने योग्य कुछ अर्थ। इसका उल्लेख महाभारत में एक जगह मिलता है\nनिर्वचन में कहा. यह निर्वचन कृष्ण ने भारत में अर्जुन से कहा था। कुल मिलाकर\n“सभी का आश्रय, सभी की उत्पत्ति-स्थिति-विनाश का कारण, सभी के अंदर और बाहर\nमैं पूर्ण विष्णु हूं, जिसने तीन कदमों में तीनों लोकों को नाप लिया है।”\nकृष्ण द्वारा विभूति का वर्णन |\n\nस्वरूप विभूति बोलने वाले कृष्ण बाद में विष्णु की पूजा के सबसे व्यापक प्रतीक बन गए\n'सूर्य' में उन्होंने अपनी विभूति का वर्णन किया है। हम विष्णु हैं जो गायत्री प्रतिपदा हैं\nहम धूप में पूजा करते हैं. यह सौर ऊर्जा में भगवान की पूजा है। यह प्रभु का है\nविभूति की दूसरी मंजिल. इसके लिए कृष्ण विष्णु के बाद 'रवि' का उल्लेख करते हैं। सूरज\nसबसे बड़ी ज्योति हम देख सकते हैं। सूर्य में नमक के रूप में 'रवि'\nसर्वव्यापी भगवान सौर ऊर्जा के रूप में ब्रह्मांड में व्याप्त हैं।\n\nयहां भगवान का विभूति नाम \"रविः\" है। वह रावी-राव-रवि के नाम से जाने जाते हैं। \"राव''\nइसका मतलब नाडा है. वह जो गायत्री \"रव\" द्वारा सूचित है, रविह की रोशनी को प्रकाश देता है\nप्रभु, गायत्री यथा प्रतिपद्य, सूर्य किरण में 'रवि' नमकः\nआसन्न है.\n\nअगली विभूति जो कृष्ण कहते हैं वह आकाश में वायुमंडल की एक अलग परत को विनियमित करने के बारे में है\nमरीचि मरुतों की संतान हैं। मूलतः मरुतों की संख्या उनचास है। उनमें से दस\nबहुत से हमारे पिंडदान नियम हैं। इन मरुतों का शासक\nग्रिप गैस इन उनचास मरुतों में मरीचि का नाम पुराणों में कहीं नहीं है\nनहीं आये अत: यह कहना कठिन है कि मरीचि इन उनचास मरुतों में से एक है। लेकिन\nइससे स्पष्ट है कि वह प्रभाववायु का पुत्र है। माधवाचार्य द्वारा ऐतरेय उपनिषद पर भाष्य और\nगीता-मरीचि के अर्थ को समन्वित करते हुए अठारहवीं कक्षा में भूत है।\nदेवी इसलिए, वह दिव्य पंखे (गणपति) के समकक्ष हैं। प्रभु\nजैसे मरीचिनामाका भूत वायु के प्रशंसक देवता के भीतर विभूति के रूप में खड़ा है।\n\nयहां भगवान का विभूति नाम 'मारीचि' है। लकड़ी का अर्थ है पानी. मारी का अर्थ है पानी\nपूर्ण बादल हवा में जो इस बीज को वहां ले जाता है जहां इसे भेजा जाना है\nभगवान उपस्थित होकर विभूति के रूप में विराजमान होकर वर्षा कराने की शक्ति प्रदान करते हैं\nमरीची”\n\nसूर्य में और आकाश में वायु में अपनी विभूति का उच्चारण करने वाले कृष्ण आगे के तारों के राजा हैं\nवह चंद्रमा में अपनी विभूति का वर्णन करता है। यह विजति का रचयिता है। सितारों के भगवान\nचंद्रमा सभी तारों की अधिष्ठात्री शक्ति के रूप में चंद्रमा में \"शशि\" शब्द भगवान के लिए बैठा है\nउन्होंने वह शक्ति दी.\n\nयहाँ भगवान का विभूति नाम \"शशिः\" है। जिसके पास शश है वह शशि है। 'श' का अर्थ है आनंद. शशा का मतलब है\nआनंद का आनंद—आनंद। आनंद मूर्ति जैसे आनंदमय भगवान\nचंद्रमा में बैठो. इस कारण चंद्रमा हमें सुख देता है।",
  "10.22": "वेदानां साम वेदः अस्मि देवानां अस्मि वासवः |\n\nइंद्रियाणं मनः च अस्मि भूतानं अस्मि चेतना - वेदों में मैं सामवेद हूं।\n[साम- हर जगह समान है और वेद को \"सामवेद\" कहा जाता है क्योंकि यह ज्ञान का स्वरूप है\nमैं सामवेद में हूं।] मैं देवताओं में इंद्र हूं। [वासा- सभी आधारों में, जो मौजूद है-\nमैं देवेन्द्र में \"वासव'' के रूप में हूं।] मैं इंद्रियों में मन हूं।\nमैं एन्निसी के मन में हूं।] मैं प्राणियों की आत्मा हूं। [चेतस सभी प्राणियों की स्मृति की गांठ है,\nमैं: रिहाई के कारण मैं होश में हूं.]\n\nआकाश में - सूर्य, चंद्रमा, तारे, वायु - कृष्ण, जिन्होंने अपनी विभूति की बात की, यहाँ आकाश की विशेषता है\nवह उपचारात्मक ध्वनि के बारे में बताता है। शब्द का विभूति-वेद। वेद में विष्टवेद-सामवेद।\nहालाँकि सभी वेद अद्वितीय हैं, प्रश्न यह है कि साम का विशेष रूप से उल्लेख क्यों किया गया है\nआप आ सकते हैं. वेदों में कोई भेदभाव नहीं है। परन्तु वैदिक भक्तों में भेदभाव है।\nप्राणदेव सामवेद के भक्त हैं। शास्त्रकार कहते हैं कि सामगान ही सबसे श्रेष्ठ है\nजो मधुर गाता है वह प्राणदेव है। प्राणदेव का गीत 'समागण' भगवान को बहुत प्रिय है\nसामवेद की एक विशेषता \"नाद\" है।\nयह एक प्रयोग है कि इसमें जो भी स्वर भर दिया जाए, वह भगवान का नाम बन जाता है\nऋग्वेद और यजुर्वेद में मंत्रों और शब्दों के माध्यम से सामवेद भगवान\nयदि यह एक भजन है, तो सामवेद भगवान में ध्वनि के साथ ध्वनि का सामंजस्य स्थापित करने में अद्वितीय है।\nगुणधर्म है। नाद के पीछे नाद से ईश्वर का दर्शन होता है\nनादोपासना.. क्योंकि मौजूदा वेद सामवेद है - विशेषकर भगवान साम में\nआसन्न है. अतः 'साम' भगवान का एक अव्यर्थ नाम है। सभी शब्द भगवद के लिए हैं\nयदि ऋग्वेद यह दर्शाता है, तो न केवल ध्वनि बल्कि सभी ध्वनियाँ भगवान की बात करती हैं\nसामवेद यह दर्शाता है।\n\nभगवान 'समः' हैं और वे 'वेदः' हैं। यहां 'समः' का अर्थ सर्वत्र समान है।\n'वेदः' का अर्थ है ज्ञान स्वरूप। भगवान सामवेद को नाद के रूप में भरते हैं और उसे विभूति बनाते हैं\nकिया\n\nवेद के बाद वेदप्रतिपाद्य देवता। देवताओं में मुख्य रूप से तत्त्वभिमानी देवता हैं।\n\"वासव\" (इंद्र) मुख्य देवता हैं जो भगवान के आसन के रूप में इंद्रियों को नियंत्रित करते हैं।\n\nवह देवताओं में सबसे महान हैं। उसकी पाँच ज्ञानेन्द्रियाँ (आँख, कान, नाक,\nजीभ, त्वचा) और अधिकांश पाँच कर्मेन्द्रियाँ (हाथ, पैर, मुँह, गुदा, उपस्थ)।\nविशिष्ट हाथ (हसरया प्रशंसक देवता। अन्य सभी इंद्रियाँ अन्य जानवरों में भी मौजूद हैं। लेकिन\nकुसुरी कार्य, नृत्य, मूर्तिकला आदि भगवान के अद्भुत शिल्प केवल मनुष्यों के लिए हैं।\nमहाभारत में एक कहानी है जो हमारे हाथों की विशिष्टता के बारे में बताती है। एक बेरोजगार व्यक्ति\nतय करें कि विद्वान अपनी बेरोजगारी से तंग आकर आत्महत्या कर रहा है\nखड़े-खड़े एक लोमड़ी उससे कहती है: “हे भगवान, आपके पास काम करने के लिए दो हाथ हैं\nदिया है लेकिन जो खाना हमें मिलता है उसे खाने के लिए हमारे पास कोई हाथ नहीं है। पेट में बैठकर खून चूसते हैं\nमक्खी को भगाने के लिए कोई हाथ नहीं है. फिर भी हम जीते हैं. भले ही आपके पास इतने कीमती हाथ हों\nतुम मरने वाले नहीं हो - तुम बहुत मूर्ख हो। यह सुनकर विद्वान ने कहा.\nलौटकर आएँगे इस कहानी में हाथ का महत्व बताया गया है। काई का प्रशंसक\n\"वासव\" में भगवान निवास करते हैं, जो अन्य सभी भक्त देवताओं को नियंत्रित करते हैं\nऊर्जा से भरपूर. वैसे तो \"वासव\" नाम भगवान इंद्र में विभूति के रूप में भरा हुआ है\nइंद्र को \"वासव\" कहा जाता है।\n\nयहां भगवान का विभूतिनाम \"वसवः\" है। \"वसव' का अर्थ है वसुओं का समुदाय।\nवसुस का अर्थ है \"देवताओं का समुदाय\"। ब्रह्मांड-ब्रह्मांड में, पिंडदान में-\nभगवान वसावाह, तत्त्वभिमानी देवों के नियंत्रक हैं जो पिंडदान को नियंत्रित करते हैं। सब\nयहां तक कि आधारों में भी, भगवान अस्तित्व के रूप में “वासवः” हैं।\n\nबाह्य जगत के बाद कृष्ण हमारे आंतरिक जगत में अपनी विभूति का वर्णन करते हैं।\nमन ही मनुष्य के सभी कार्यों का कारण है। मन के बिना सब कुछ शून्य है. यह इंद्रियों का है\nगतिविधियों के लिए बुनियादी प्रेरणा. एक ऐसा माध्यम जिसके माध्यम से सभी बाहरी पदार्थ आंतरिक आत्मा को छूते हैं\n\"दिमाग\"। जो महसूस किया जाता है वह मन के माध्यम से सार्थक हो जाता है। जब हम धर्मग्रंथ पढ़ते हैं तो यह हमारे लिए एक विषय है\nचमकना मन से है. भगवान के मन के कारण के रूप में हमारे पास \"मनः\" शब्द है\nये शक्ति हमें बैठने से मिली है. मनुते इति मनः। वह जो ज्ञान का अवतार है, सभी\nज्ञाता, सर्वज्ञ, शब्द का स्वामी मानस है।\n\nमन के बाद, मन के माध्यम से जो आता है उसे समझने की शक्ति जागरूकता है ।\nईश्वर हमारे भीतर है, ग्रहण करने वाली शक्ति के रूप में जो मन जो देखता है उसे ग्रहण कर लेता है\nबैठ जाओ इससे संसार को ग्रहण करने की शक्ति जागृत हो गई। संपूर्ण ब्रह्मांड के प्रति उसकी जागरूकता के साथ\nग्रहणशील, सर्वव्यापी आश्चर्य भगवान 'चेतना'। 'चेतस' का अर्थ है हमारा अवचेतन मन। हमारा\nप्रत्येक अनुभव हमारे अवचेतन में संग्रहीत होता है। मन हर चीज़ को समझने की शक्ति है\nकोट्टव 'चेतनः' नमक भगवान। यह भगवान की विभूति है।",
  "10.23": "रुद्रानां संकरः च अस्मि वित्त ईशाः यक्षरक्षासम् |\n\nवसूनं पावकः च अस्मि मेरुः शिखरिनं अहम्-रुद्रस [ग्यारह] प्रमुख रुद्र हैं।\nमैं [शाम-सुख के प्रति करुणा के कारण शंकर में ``शंकर'' हूं।] यक्ष-रक्षासार\nबल का स्वामी कुबेर है (विट्टा-सिरी, ईशा-ओडेय, तथाकथित 'विट्टेशा' कुबेर में है।\nयक्ष-राक्षस के स्वामित्व में] मैं हूं। मैं [आठ] वसुओं में अग्निदेव हूं।\n['पावक' का मतलब पावना से 'पावक' है। मैं अग्नि में हूं।] मैं चेलुकोडी की पहाड़ियों में मेरु हूं।\n[मैं मेरु गिरि में \"मेरु\" के रूप में इरु-दूसरे मकसद के कारण हूं, मा-था।]\n\nमन में अपनी विभूति की बात करने वाले कृष्ण यहां मन के प्रशंसक शिव में हैं\nविभूति बताते हैं. कृष्ण कहते हैं: \"रुद्रों में शंकर सानु हैं\"। रुद्र ग्यारह हैं\nलोग रायवत, ओज, भव, भीम, वामदेव, उग्र, वृषाकपि, अजैकपथ, अहिर्बुद्दी, विरुपाक्ष,\nऔर महादेव, गणप्रधान के भगवान। (इन एकादश रुद्रों के अनेक नाम हैं।\nउन्होंने अलग-अलग स्थानों पर अलग-अलग नामों का उल्लेख किया है)। 'रुद्र' जो हमारे मन को नियंत्रित करता है-\nमहादेव या शिव. उनका नाम 'शंकर' है। रुद्र का अर्थ है रोदयति इति रुद्र-दुःखः\nइसका मतलब है देने वाला. भगवान केवल दुष्टों को ही दुःख देते हैं। दूसरे अर्थ में\nदेखा जाए तो- रुजं द्रवयति इति रुद्र: यानी हमारे अंदर की बीमारी को ठीक करो\nसुख देने वाला। मूलतः यह रोग मानसिक है। यदि हमारा मन मजबूत होगा तो हम बीमार नहीं पड़ेंगे।\nयदि आपमें यह दृढ़ संकल्प है कि यदि कोई बीमारी आती है तो आप उसका मुकाबला कर सकते हैं - उस बीमारी पर ध्यान दें\nइलाज योग्य.\n\n'शंकर' का अर्थ है खुशी, खुशी देने वाला। जीवन में स्वस्थ शरीर का बहुत महत्व है\nमहान् सुख किसी भी अच्छे कर्म को करने के लिए स्वस्थ शरीर की आवश्यकता होती है। 'रुद्र'\nशरीर पुरुष यदि इस शरीर को खड़ा होना और चलना है, तो यह शिव शक्ति के कारण है जो शरीर में शरीर पुरुष है। हमारा\nमन में बैठो और मानसिक अशांति दूर करो, स्वस्थ शरीर दो, सुख दो\nरुद्र दाता हैं। ऋग्वेद शिवस्तुति में शिव की स्तुति \"भिषक्तं त्वा भिषजम्\" कहकर की गई है।\nइसका मतलब है \"आप डॉक्टरों के डॉक्टर हैं\"। इसी कारण शिव को 'वैद्यनाथ' भी कहा जाता है।\nरुद्र को महादेव क्यों कहा जाता है इसके कई कारण हैं। यहां 'देव' का अर्थ है इंद्रिय\nदेवं इन्द्रियम्)। शिव सभी कामुक देवताओं में सबसे महान हैं। देवता\nविवेक से देखा जाए तो - यदि ग्यारह में से दस रुद्र अठारहवीं कक्षा में हों।\n\nपाँचवीं कक्षा में शिव उससे कहीं अधिक ऊँचे हैं। भगवान शिव के संहार कर्म में\nएक बहुत बड़ी शक्ति जो वायु देव की सहयोगी के रूप में सहायक है। भगवान शंकर\nनमक के रूप में शिव में खड़े हैं। हमें भगवान, भगवद की आराधना के मार्ग पर ले जाना\nरुद्र वह है जो मन को बोध के लिए प्रशिक्षित करता है। तो यह भगवान की बहुत बड़ी कृपा है\nविभूति\n\nयहाँ भगवान का विभूतिनाम \"शंकरः\" है। \"शम\" का अर्थ है ख़ुशी, \"कारा\" का अर्थ है दयालु।\nआत्म-आनंद आत्म-आनंद का एक रूप है, जो दुखी संसार की निंदा करता है- जो हमें मुक्ति देता है\nभगवान \"शंकरः\",\n\nकृष्ण ने भगवान शिव के बारे में कहा कि वे हमारे लिए आंतरिक धन के प्रशंसक हैं, फिर बाहरी धन के\nकोडुवा ने कुबेर में अपनी विभूति का वर्णन किया है। हमारा शरीर एक प्रशंसक और बाहरी है\nफैन कुबेर. उनके शासन में यक्ष और राक्षस हैं। यक्ष का अर्थ है तंत्रिका\nजो लोग निर्दयतापूर्वक मांस खाते हैं। राक्षस यक्षरियों से बेहतर हैं। लेकिन ये भी\nक्रूर. हमें उनसे अपनी रक्षा करनी होगी.\n\nयहां भगवान का विभूतिनाम 'वित्तेशा' है। विट्टा का अर्थ है सिरी, ईशा का अर्थ है मालिक। प्रभु\n\"वितेश\" कुबेर में था, जिसने उसे यक्ष-राक्षस का अधिकार दिया और उसे बाहरी बना दिया।\nउसे धन-संपत्ति का स्वामी बना दिया। यह कुबेर में भगवान की विशेष विभूति है।\n\nवेदों में देवतागण पर विचार करें। करते समय आदित्य-वसु-रुद्रगण तीन हैं\nवे एक साथ आते हैं. यह भी तीन सत्रों में भगवान को दिया जाने वाला प्रसाद है\nमंदिर में भगवान के लिए. भगवान के अष्टवास में रहने के लिए प्रातःकाल में अष्टाक्षर\nगायत्री मंत्र से आहुति दी जाती है। मध्याम की एकादश का संबंध रुद्र से है।\nइसके लिए यहाँ एकादश अक्षर 'त्रिष्ठुप' का प्रयोग किया गया है। द्वादशादित्यों का सायंकालीन सत्र\nसे संबंधित इसके लिए वे दोहरे अक्षर \"जगति\" कृष्ण आदित्य और रुद्र का उपयोग करते हैं\nके बारे में कहा. अब यहां वसुओं के बारे में बोलते हुए, वे कहते हैं: \"वसुओं में, 'अग्नि' मैं हूं।\" वसुस\nआठ लोग. द्रोण, प्राण, ध्रुव, अर्क, अग्नि दोष, मध्य और विभावसु। उसके पास और भी बहुत कुछ है\nएक नाम है. पांचवें अग्नि में वैश्वानर, वह्नि, जातवेद, हुताशन, पावक, अनल, दहन है।\nआदि का नाम दिया गया है। यदि अन्य सभी वसु देवता भेद में अठारहवीं कक्षा में हैं तो 'अग्नि'\nवह उनसे ऊँची पंद्रहवीं कक्षा में है। भुस्त्र में भगवान का सबसे बड़ा उपासक\nप्रतीकात्मक अग्नि. भगवान अग्नि, वह शक्ति जो संपूर्ण विश्व को पवित्र करती है, 'पावकः' नमक के रूप में\nकुतु ने उन्हें यह महान पद दिया।\n\nअग्नि में भगवान का तेज है। चमक में प्रकाश की शक्ति है, ऊष्मा की शक्ति है। और\nइसमें दाहक शक्ति भी होती है. इसके अलावा इस तेज में पाचन शक्ति भी होती है। वह पदार्थ जो अग्नि के संपर्क में आता है\n\nपावन बन जाता है. अग्नि में ही वह भगवान है जिसने अग्नि को ऐसी प्रतिभा दी, वह संसार को पवित्र करेगा\nपापी. जो भगवान सबको पवित्र करते हैं, वे देवताओं के भी अवाक (रक्षक) हैं।\n\nमेरु पर्व में पृथ्वी पर धन के निवास कृष्ण से पहले वित्तेश कुबेर के बारे में बताया गया है।\nविभूति बताते हैं. मेरु पर्वत को हेमाद्रिचिन्नादा बेट्टा कहा जाता है)। बस इतना ही\nवसुओं का निवास. कृष्ण कहते हैं: \"पहाड़ियों में मैं मेरु हूं\"। हिमालय में एक पर्वत\nस्वामीराम ने रैंक में धन के बारे में कहा, जिसे केवल मनुष्य ही जानता है, “64176 50\nअपनी पुस्तक में” ने पुस्तक में अपना अनुभव साझा किया। युद्ध में\nजब संपूर्ण धन नष्ट हो जाता है तो धर्मराय पर्वत श्रृंखला में गड़े धन को लाकर उसका त्याग कर देते हैं\nमहाभारत में कहा गया है कि उन्होंने ऐसा किया। यह हिमालय में तपस्या की कुछ प्रथाएँ हैं\nयोगी भी जानते हैं. मेरु ऐसे धन का घर है.\n\nयहां भगवान का विभूतिनाम मेरुः है। मा-मेरु-मेरु. सर्व भाव से सर्व\nभगवान महान माता महालक्ष्मी के प्रेरक भी हैं। ऐसे भगवान के लिए\nकोई अन्य प्रेरणा नहीं है. अतः \"मेरुः\" भगवान का एक उपनाम है।",
  "10.24": "पुरोधसं च चुचम मम विद्धि पार्थ बृहस्पतिम्।\n\nसेनानिं अहं स्कंदः सारसं अस्मि सागरः - हे पार्थ, सबसे महान पुरोहित।\nमैं बृहस्पति हूं.\nमैं स्मंदा हूं.\nमैं जलाशयों में रहने वाली मछली हूं। [सा:सारा से, मैं 'सागर' नामक समुद्र में हूं।]\n\nकहने के बाद हम जिस भगवान की पूजा करते हैं उसका प्रतीक सबसे महत्वपूर्ण है\nयहाँ पुजारियों के बारे में क्या कहा गया है। कृष्ण कहते हैं, \"मेरी उपस्थिति पुजारियों के साथ है\"।\nजैसा कि ऋग्वेद के प्रथम सूक्त में कहा गया है: \"अग्निमि\"ले पुरोहितं यज्ञस्य देवम्-खत्विजम्\" |\nहोता\"राम रत्न धतमन् |\"। यहाँ \"होटा\" ऋग्वेद का पुजारी है, जो पहले यागा था\nवहाँ सोलह पुजारी थे। ऋग्वेद के लिए: 'होता' प्रधान है और\nउनके तीन सहायक (मैत्रवरुण, अच्छवक, ग्रामस्तुथ) हैं। यजुर्वेद के लिए:\nअध्वर्यु प्रधान है और उसके तीन सहायक हैं (मंडिप्रतिप्रस्थुता, नेष्टा, उन्नेता)।\nसामवेद के लिए: उद्गाता प्रधान और उसके लिए तीन मंदीप्रस्थोता, प्रतिहर्ता, सुब्रह्मण्य)\n\nमददगार. इन सबके पर्यवेक्षक के रूप में यज्ञ में कोई कमी नहीं रहनी चाहिए\nपर्यवेक्षक सर्ववेद में पारंगत प्रधान पुजारी होते हैं। उनका नाम 'ब्रह्मा' है।\nउन्हें तीन लोगों (ब्राह्मणइच्छमसी, अग्नि येधरा, पोटा) द्वारा भी सहायता प्रदान की जाती है। इस प्रकार भगवान विशेष हैं\nउपस्थित सोलह पुरोहित यज्ञ करा रहे थे। पुजारियों की स्थिति\nसमाज में बहुत पुराना है. परंतु आज के पुरोहितों को समाज में वही दर्जा प्राप्त है जो पहले था\nकमाई नहीं. पुजारी हमसे पहले जानते हैं कि हमारे लिए क्या अच्छा है और उसी तरह हमारा मार्गदर्शन करते हैं\nजो चलने का मार्गदर्शन करता हो। ऐसे कार्य जो हमारे विकास को पूरक बनाएंगे\nगुरुस्थान में सलाहकार जो हमें विकास में मदद करने का ध्यान रखते हैं। संपूर्ण\nवे समाज के मार्गदर्शक हैं। पौरोहित्य एक बहुत ही ज़िम्मेदारी भरा काम है. एक धार्मिक\nयह पुजारी की जिम्मेदारी है कि जब पाठ्यक्रम में कोई संदेह हो तो वह समुदाय के लिए एक मार्गदर्शक के रूप में कार्य करे\nबहुत बड़ा. यदि मंत्र पढ़ते समय कुछ छूट जाता है या गलत हो जाता है तो इसके लिए पुजारी जिम्मेदार होता है\nकारण पौरोहित्य ऐसा ही एक उत्तरदायित्वपूर्ण कार्य है। तो भगवान का विशेष है\nमौजूदगी तो है. पूरी पृथ्वी के दो महानतम पुजारी। बहुत बड़ा\nशुक्राचार्य, पुरोहित और बृहस्पतिाचार्य, देवताओं के पुरोहित।\nबृहस्पति देव विग्रह में दशम भाव में हैं। वह स्वर्ग लोक में देवी-देवताओं का है\nदेवेन्द्र के सलाहकार। देवताओं को. जो पुजारी हैं उनमें भगवान विशेष हैं\nएक उपस्थिति है. देवताओं के विवेक में इंद्र आठवीं कक्षा में और दसवीं कक्षा में हैं\nबृहस्पतिाचार्य को प्रणाम करें और अपने अंदर मौजूद भगवान के मार्गदर्शन का पालन करें\nनिकटता ही कारण है. इसकी याद दिलाने के लिए यहां कृष्ण देवेन्द्र के अवतार अर्जुन मौजूद हैं\n\"पार्थ\" कहकर सम्बोधित किया जाता है।\n\nदूसरी ओर, वेदों में बृहस्पति जीवन के देवता हैं। भारत की सरस्वती\nपति-बृहस्पति. वह ब्रह्म-वायु है. वे सभी देवताओं के पुजारी हैं। प्रभु\nवह प्राणदेव में गीत (कान्तसिरी) की विशिष्ट विभूति के रूप में निवास करता है।\n\nयहाँ भगवान का विभूति नाम \"बृहस्पति\" है। बृहत् का अर्थ है बड़ा, पति का अर्थ है स्वामी।\nब्रह्मा सभी देवताओं के स्वामी और पुरोहितों के पुरोहित भगवान \"बृहस्पति\" हैं।\nकृष्ण, जो पुजारियों के बारे में बात करते थे जो आध्यात्मिक योद्धा हैं, अब युद्ध और सुरक्षा में जीत दिलाते हैं\nऐसा करने वाले योद्धाओं में अपनी विशेष विभूति बताते हैं। देवता बृहस्पतिाचार्य हैं\nजब मार्गदर्शन में अर्जित धन असुरों द्वारा चुरा लिया जाए, तो उनसे युद्ध करो\nस्कन्द को वापस लाया गया। भगवान स्कंद नमक के रूप में खड़े होकर युद्ध का संचालन करते हैं।\nअंतरतम, जिसने स्कंद को एक सेनापति के रूप में तारकासुर का वध करने की शक्ति दी\nअंतर्यामी तत्त्व-भगवान भीतर विराजमान हैं। सेनानी की बात करें तो यहां सेनानी के रूप में कीर्ति हैं\n\nकर्नाटक के गौरवशाली सपूत *\"करियप्पा\" को कोई भी याद कर सकता है।\nसन्निदान के कारण ही एक सैन्य कमांडर में ऐसी विशेष शक्ति आती है।\n\nभगवान का विभूतिनाम स्कंदः जो यहां आया है। 'स्मंदः' का अर्थ है संपूर्ण जगत का नाश करने वाला\nशक्ति कृष्ण ने कहा, \"चावल का कटोरा पीते हुए और 'स्कंद' कहते हुए, मैं सेनापति की महिमा में हूं\"।\nकृष्ण आगे कहते हैं: \"सरसमास्मि सागरः\"। पृथ्वी पर महान धन\nयदि स्थान मेरु पर्वत है, तो रस से भरा सबसे बड़ा जलाशय महासागर है।\nकृष्ण कहते हैं, ''मैं इसमें विभूति हूं।'' कुआँ चाहे धरती के किसी भी हिस्से में खोदा गया हो\nमीठा पानी लेकिन समुद्र का पानी स्वाभाविक रूप से खारा होता है। हम नहीं जानते कि ऐसा क्यों है. रूसी\nप्रसिद्ध मनोवैज्ञानिक विलिकोवस्की /) ने अपनी पुस्तक \"Worlds in Collision\"\nकहते हैं: \"हम इस भ्रम में हैं कि हमने दुनिया के सभी आश्चर्यों को पार कर लिया है, लेकिन हम कुछ भी नहीं जानते हैं।\"\nवह है। आज हम नहीं जानते कि समुद्र का पानी खारा और कुएं का पानी मीठा क्यों होता है।\nभगवान ने बाकी सभी रस फलों में डाल दिये। लेकिन रसदा-रस लवणरसा नमक ही\nफल में भी नहीं - समुद्र के पानी में। ये समुद्र एक अजूबा है. ज़मीन पर जानवर\nविविधता से अधिक विविधता समुद्र में है। भगवान ने समुद्र और उसमें महासागरों की रचना की\nशब्दों से भरपूर.\n\nप्रभु विभूतिनामे सागरः यहाँ आये हैं। सारा-गरा-सागर. सार होना\nप्रभु तो वह है जो स्वीकार करता है। सबसे बड़ा सार-नमक, भगवान सगरह से भरे हुए हैं।\nसरं गरति ददातिति सागरः। संसार को जीवन का सार देने वाले भगवान सागरः।\n\nमहर्षिणं भृगुरहं गिरामस्मे चकमाक्षरम् |\n\nयज्ञानं जपयज्ञनोशस्मि स्थावरनं हिमालय",
  "10.25": "महा ख़ुशीहं भृगुः अहं गिराम अस्मि एकम अक्षरम।\n\nयज्ञं जपयज्ञः अस्मि स्थावरनं हिमालय; - मैं ऋषियों में भृगु हूं। [बुरे वाले\nजलकर बोले, भृगु, मैं भृगु मुनि हूं।] मैं वाज्मय में एक अक्षर ओंकार हूं।\n[सर्वोपरि, 'एका', विलुप्त होने के कारण मुझे 'अक्षरा' कहा जाता है।] यज्ञों में।\n\n1\n\nजपयज्ञ मैं हूं।\n\n0 0 1\n\nखरीदकर इसे 'यज्ञ' कहें। मैं जपयज्ञ में हूं।] मैं ठोस पहाड़ियों में हिमालय हूं।\n\n[चूंकि 'ह्री' प्रीलक्ष्‍मी का सामक रूप है और महश्री' नामवाचक रूप है।\nमैं हिमगिरी में हूं जिसे 'हिमालय' कहा जाता है।]\n\nइससे पहले हमने देवर्षि बृहस्पति के बारे में देखा था। वह स्वर्गलोक का है।\nयदि हम उनके अलावा अन्य महर्षियों को देखें - उनमें से सबसे प्रतिष्ठित, जिन्होंने भगवान को देखा\nमहान लोग. भृगु महर्षि. विश्वामित्र-वसिष्ठ. भेदभाव कक्षा में सोलहवाँ\nयदि स्थिति में हो तो भृगुमुनि अपने से पंद्रहवीं कक्षा में अग्नि के बराबर हैं।\nवह पृथ्वी पर खुशियों के आविष्कारक थे। जो भागवत में आता है\nजैसा कि कहानी कहती है, एक प्रतिनिधिमंडल के रूप में यह मापने के लिए जाएं कि त्रिमूर्ति में सबसे महान कौन है,\nभृगु एक बहुत महान ऋषि थे जिन्होंने दुनिया को उपदेश दिया कि नारायण सबसे महान हैं।\nनियोग श्रेष्ठ के रूप में भृगु पहले शिव के पास और फिर ब्रह्मा के पास जाते हैं। उनके लिए क्या है\nजब कोई पुरस्कार नहीं मिलता तो भृगु क्रोधित होकर नारायण के पास जाते हैं। विष्णु भी हैं\nजब उस पर ध्यान नहीं दिया जाता तो वह गुस्से में विष्णु की छाती पर लात मार देता है। तब भक्तवत्सल नारायण:\n\"तुमने मुझे बुलाया होता तो मैं आ जाता, इस तरह लात मारने से तुम्हारे पैर में इतना दर्द क्यों हुआ\"\nवह उनके पैर रगड़ने लगता है. तब भृगु और नारायण को अपनी गलती का एहसास हुआ\nसमर्पण। जब हमने यह कहानी देखी, तो क्या हमें नहीं पता था कि इन ऋषियों के लिए भगवान का महत्व क्या था?\nएक प्रश्न उठता है. निश्चय ही वे परमेश्वर का पूरा महत्व जानते थे। यह बस है\nयह कार्रवाई के माध्यम से सामग्री को जन-जन तक पहुंचाने का कार्य है। इसी तरह, “आप\nयह भृगु ही थे जिन्होंने भगवान को श्राप दिया था कि अवतार पृथ्वी पर दस बार गिरेंगे\nश्राप का प्रतिफल देने के लिए भगवान ने पृथ्वी पर दस अवतार लिये। लक्ष्मी\nभार्गवी का जन्म भृगु मुनि की पुत्री के रूप में हुआ था। भृगु में ऐसी अनेक विशेषताएं हैं\nहम देखेंगे. यह सब भृगु में भगवान के विशेष सन्नी दान के कारण है।\n\nयहां भगवान का विभूतिनाम 'भृगुः' है। भर्जनाथ इति भृगुः। बाढ़ के दौरान सब कुछ\nभर्जन भगवान, मुख्य रूप से भृगुहा जो भक्तों के पापों का नाश करते हैं। प्रभु\nवह अपने भक्तों के जीवन में बाधा डालने वाली बुरी आत्माओं का विनाशक है। और दुष्ट\nभगवंत भृगुः शब्द वाच्य, जो अधर्म का नाश कर धर्म की स्थापना करता है। खेतों में\nभृगु को सर्वोच्च स्थान बनाओ, जिनके बीच भृगु भगवान की वाणी है\nआसन्न है.\n\nजब हम ख़ुशियों के बारे में बात करते हैं, तो हमें आश्चर्य होता है कि ख़ुशियाँ भगवान के करीब कैसे हो गईं।\nइसका कारण है- उपासना, मन्त्र-जप सिद्धि। क्षत्रिय विश्वामित्र ने भी वेद मंत्र का जाप किया\nसिद्धि से ब्रह्मर्षि तक। यदि आप खुश रहना चाहते हैं, यदि आप खुशी पाना चाहते हैं, तो ओंकार की पूजा करें\nमनुष्य को प्रभु का एहसास होना चाहिए। दुनिया की सबसे महत्वपूर्ण और महान ध्वनि\nओमकारा. इस ओंकार में अक्षर नमक भगवान का विशेष सन्निदान है। भगवान ओमकारा\nविशेषसं. [कृष्ण ने ओमकार को इतना महत्व क्यों दिया, ओमकार में जो असाधारण है\n\nविशेषता क्या है इसका विशेष अर्थ हम सातवें अध्याय में बता चुके हैं\nहमने देखा है (ए-7, श्लोक-8)]। अविनाशी (अ-क्षर) भगवान अकेले ही सबसे बड़े हैं\nसिद्धांत तो वह अकेला है.\nकृष्ण यहां ओमकार के बाद जपयज्ञ के बारे में बताते हैं। वह कहते हैं \"यज्ञं जपयज्ञः अस्मि\"।\nकृष्ण. सभी यज्ञों में सबसे बड़ा यज्ञ जपयज्ञ है। जैसा कि पहले उल्लेख किया गया है, पूजा आग के सामने की जाती है\nयज्ञ ही नहीं. दान, पूजा (समेकन) जैसे अच्छे कार्यों में एक पक्ष से जुड़ना,\nज्ञान दान करना, भोजन दान करना, जो हमारे पास है उसे उन लोगों के साथ बांटकर जीना जिनके पास नहीं है, ये सभी एक हैं\nयज्ञ ही. सामान्यतः यज्ञ दो प्रकार के होते हैं। एक आंतरिक त्याग और दूसरा बाह्य त्याग।\nइंटीरियर में. भगवान की निरंतर पूजा (देवपूजा); चित्त-मन भगवान के साथ है\nजुड़ना (एकजुट होना) और स्वयं को प्रभु के प्रति समर्पित करना - उत्तम\nमनसा यज्ञ. इसे मन में करने वाला जपयज्ञ सबसे बड़ा होता है। इसका कारण जपयज्ञ में है\nप्रभु की विभूति.\nभगवान का विभूतिनाम 'जप' और 'यज्ञ' है। जग में हर जन्म\nभगवान जो जीवन को संजोते हैं 'जपः। क्योंकि ऐसे प्रभु को सबकी पूजा प्राप्त होती है\nजपयज्ञ में \"यज्ञ\" है।\nजप की बात करें तो, कृष्ण पृथ्वी पर सात्विक कंपन का सबसे बड़ा पौधा है\nकहते हैं पहले घर बनाते समय, जिस स्थान पर सात्विक कंपन सबसे अधिक होता है वह भगवान का कमरा होता है\nएक शहर में एक मंदिर उच्चतम सात्विक कंपन का स्थान होता है\nहिमालय पृथ्वी पर एकमात्र ऐसा स्थान है जहां सबसे अधिक सात्विक कंपन होता है। यहाँ\nचाहे हम कहीं भी बैठें, हमारा मन बहुत आसानी से भगवान के साथ जुड़ जाता है। यह शक्ति हिमालय को\nयह प्रभु की विशेष उपस्थिति से आया। यहां भगवान 'हिमालय' नमक रूप में निवास करते हैं।\nभगवान के इस विभूतिनाम का एक विशेष अर्थ है। ह्रीमा-मंदिर-हिमालय। ह्री अर्थात\nश्रीलक्ष्मी, माँ का अर्थ है देवी। भगवान हिमालय, श्रीदेवी और भूदेवी का मंदिर।\nभगवान की इस विशेष विभूति के कारण हिमालय भी आध्यात्मिक विस्मय से परिपूर्ण है।\nहिमालय में व्यक्ति के मन को बदलने और उसे आध्यात्मिकता की ओर मोड़ने की विशेष शक्ति है।\nवेदव्यास, नर-नारायण, आचार्य माधव का निवास स्थान हिमालय है। अनेक\nयह हिमालय एक रहस्यमय स्थान है जहाँ देवता निवास करते हैं। प्रभु की विभूति ही इस भूमि के लिए आश्चर्य है\nइससे ताकत मिली है.",
  "10.26": "अश्वत्थः सर्व वृक्षानां देवर्षिणां च नारदः |\n\nगंधर्वनं चित्ररतः सिद्धनं कपिलः मुनिः - सभी वृक्षों का पुष्पित वृक्ष।\nमैं हूँ।\nमैं ख़ुशी से संतुष्ट नहीं हूँ. [नारा: नारा की सभी इच्छाओं के दाता के रूप में, उन्हें ``नारद'' कहें\nमैं नारद में हूं।] मैं गंधर्वों का स्वामी चित्ररथ हूं। [छवि:-आचार्य, रथ-तेरी में चलते हुए\n'चित्ररथ'. एनीस. मैं गंधर्व राजा के रथ पर हूं।] योगसिद्धों में [का-सुखरूप के रूप में,\nदलाली करके, और चापलूसी करके] मैं कपिल मुनि हूं।\n\nकृष्ण कहते हैं: \"सभी वृक्षों में मैं अश्वत्थ हूं\"। अश्वत्समरा आज अवलोकन में\nदेखने वाले के लिए कोई उपयोग का पेड़ नहीं. यदि प्रभु ने इस वृक्ष को महत्व न दिया होता\nहमें इस पेड़ के बारे में कुछ नहीं पता था. आओ हम इस वृक्ष का फल खाएँ,\nएक सुगंधित फूल भी नहीं. इस लकड़ी से फर्नीचर नहीं बनाया जा सकता.\nव्यापक रूप से बढ़ता हुआ और आसपास के क्षेत्र पर कब्जा करने वाला यह पेड़ जाहिर तौर पर लोगों के लिए एक जंगल है\nदेने वाला पेड़! लेकिन यहाँ कृष्ण कहते हैं: \"वृक्षों के समुदाय में सबसे महान वृक्ष अश्वत्थ है\"। क्यों\nइस पेड़ का महत्व क्या है, यह जाने बिना ही आज हम इसकी पूजा करते हैं\nकुछ लोग इसे नजरअंदाज कर देते हैं. इस पेड़ को घर से दूर लगाना चाहिए क्योंकि यह सौभाग्य लाता है\nकहीं मन्दिर में पेड़ लगाने वाले भी हैं। आज ज्यादातर लोग इस पेड़ का महत्व नहीं जानते हैं।\nबरगद, अरली और अत्ति इन तीन वृक्षों को प्राचीन लोग बहुत महत्व देते थे। [बेंद्रा का\nउनके बगीचे में उगे इन तीन पौधों को देखिए- “हमारे बगीचे में तीन भगवान हैं\nयहां बनंजय को याद है कि उन्होंने दिल से कहा था कि वह फॉर्म में आए हैं]।\nपूर्वकाल में यज्ञ के समय शमी और अरणी (अरली) समिता को मथकर उससे अग्नि प्रज्वलित की जाती थी।\nतारसी आग पैदा करती थी. अरली समिता का प्रयोग मुख्य रूप से यज्ञ में किया जाता है।\nअश्वत्थामा समित का प्रयोग यज्ञ में, वहां जलने वाली अग्नि का, शायद ही किया जाता हो\nलौ से एक अनोखी ऊर्जा निकलती है. जैसे सूर्य की किरणों में सात रंग होते हैं\nअग्नि में सात रंग हैं। मुंडका उपनिषद में, काली, आग की लौ के सात रंग,\nकराली, मनोजवाचा, सुलोहितायचा, सुधूम्रवर्ण, स्फुलिंगिनी, विश्वरुचि।\nअग्नि के इन सात रंगों को सूर्य की किरणों के सात रंगों के साथ समन्वयित करने को कहा है\nयज्ञ ही वायुमण्डल में अपना प्रभाव लाता है। इस क्रिया के लिए अश्वत्सस्मिता एक महत्वपूर्ण उपकरण है।\n\nआज, कई लोगों के पास अश्वत्थामा में देवता की उपस्थिति है। वे इसके पास आते हैं।\nज्योतिषियों का कहना है कि अश्वत्थ प्रदक्षिणा तब आती है जब संतान न हो। पता नहीं ऐसा क्यों है\nलोग इन सब बातों को अंधविश्वास कहकर बात करते हैं. दुनिया के सभी पेड़ों से भी ज्यादा\n\nऑक्सीजन देने वाला वृक्ष अश्वत्थ है। ऐसी शुद्ध हवा में सांस लेने से पेट के दोष ठीक हो जाते हैं\nआज विज्ञान भी यह स्वीकार कर चुका है कि ऐसी सम्भावना है। पूर्वकाल में खुशियाँ अश्वत्थ वृक्ष की थीं\nवह पैर के पास बैठकर वेदों का अध्ययन करते थे। इस प्रकार भगवान की विशेष विभूति अश्वत्थ वृक्ष में है\nपेड़ को ऐसी कई विशेष शक्तियां दी गई हैं।\n\nयहाँ भगवान का नाम “अश्वत्थः” है। वेदों का उपदेश करने वाले भगवान के विशेष\nघोड़े के रूप में अवतार हयग्रीव है। 'अश्वत्थ' भगवान को संदर्भित करता है जो घोड़े की तरह थे और वेदों का प्रचार करते थे।\nकहा जाता है\n\nकृष्ण आगे कहते हैं \"देवर्षिणं च नारदः\"। नारद के गंधर्वों में से एक। लेकिन\nभगवान की विशेष उपस्थिति से वह बहुत ऊंचाई पर पहुंच गये और देवर्षि बन गये। नारद जी\nबड़ी उपलब्धि से प्राप्त हुआ। पिछले ब्रह्मकल्प में नारद का जन्म एक गरीब परिवार में हुआ था। उसका\nमां खुशी-मुनिगल आश्रम में रहकर काम करती थीं। वह एक छोटा बच्चा था\nख़ुशी का आध्यात्मिक संवाद सुनकर बड़ा हुआ। जब वह पांच साल का था तो उसकी मां एक सांप थी\nवह काटती है और मर जाती है। जैसा कि जानने वाले कहते हैं- \"हमें यह बताने के लिए कि भगवान \"नाथ\" हैं।\nभगवान सबसे पहले हमें 'अनाथ' बनाता है''।\nइसी साल से वह खुशी से प्राप्त ज्ञान से उपलब्धि हासिल करना शुरू कर देता है। लेकिन उस जन्म में उसके लिए\nप्रभु के दर्शन नहीं होंगे. लेकिन उसने भगवान की आवाज 'सुनी'। “मैं इस जीवन में\nदेखने की कोशिश मत करो. अगले कल्प में तुम सदैव मुझे देखोगे।” फिर उसने कहा\nउन्होंने ब्रह्मकल्प में नारद के रूप में जन्म लिया और भगवान की महान कृपा प्राप्त की।\n\nनारद हमारे अंतर्ज्ञान की प्रशंसक देवी। जैसा कि अतीत की कहानियों में देखा गया है\nअगर कुछ अच्छा करना होता तो नारद आकर बताते। उदाहरण के लिए\nयह नारद ही थे जिन्होंने वाल्मिकी को रामायण लिखने के लिए कहा था। यहां हमारा एक प्रश्न है.\nअब नारद क्यों नहीं आ रहे, हमें मार्गदर्शन क्यों नहीं मिल रहा। हम नारद हैं\nबुलाएँगे तो आज भी ज़रूर आएँगे! \"नारद' का अर्थ है हमारी आंतरिक आवाज ।\nयदि हम अपनी आत्मा की पुकार सुनेंगे तो नारद वहीं बोलेंगे। हम अपने भीतर हैं\nयदि हम संदेश सुनने का अभ्यास करें तो हमारा अचेतन मन खुल जाता है। इससे 'इस तरह\nएक संदेश दिखाई देगा। यह अशरीरवाणी या अन्तर्वाणी है। यही तो है\nनारद. भले ही उन्हें देखा न जा सके, फिर भी उन्हें सुना जा सकता है। यह सारी अनोखी शक्ति नारद को है\nयह परमेश्वर की विशेष उपस्थिति से आया है।\n\nयहां भगवान का विभूतिनाम \"नारदः\" है। नारा (नारा-ध्याति) की अज्ञानता को दूर करते हुए, उन्होंने\nभगवान नारद स्नानकर्ता (नारा-ददाति) हैं।\n\nनारद के बाद कृष्ण ने गंधर्वों में अपनी विशेष विभूति बताई। कृष्ण कहते हैं\n\"मैं गंधर्व की छवि हूं।\" उपदेवता गण जो संसार के सेवक के रूप में कार्य करते हैं\nगंधर्व. ये संक्रमण के देवता हैं. इस गण के राजा चित्ररथ हैं। \"राजा साक्षात् देवता है\"\nऐसा कहा जाता है कि भगवान चित्ररथ में विशेष विभूति के रूप में विद्यमान हैं। यहाँ आये\nभगवानं विभूतिनामा 'चित्ररथ:'। विचित्र रथ वाले भगवान चित्र के समान हैं। भगवान का वाहन-\nगरुड़. यह बाकी सभी गाड़ियों से अलग है. ऐसे रथ में भगवान का चलना एक चित्र के समान है।\nकृष्ण कहते हैं \"सिद्धानं कपिलो मुनिः\"। इतिहास में दो कपिलमुनि दिखाई देते हैं।\nदोनों ने सांख्य कहा। लेकिन जो ईश्वर को नहीं मानता. तो यह यहाँ है\nकपिलमुनि-कपिला वासुदेव। सांख्य मूलतः संसार को देने वाले भगवान के अवतार थे।\nस्वायम्भुव मनु की कन्या देवभूति और कर्दम प्रजापति का विवाह\nभगवान का एक अवतार जो प्रकट हुआ। वेदव्यास ने कपिल ने जो कहा था उसे भी हमारे सामने प्रस्तुत किया\nसंसार को नवीनता देने वाले भगवान का अवतार \"कपिलवतार\" है।\n\nयहां भगवान का विभूतिनाम \"कपिला' है। का-पी-ला; वह जो पूरी दुनिया का पालन-पोषण करता है), और\nलयवर्ण (ला), आनंदमूर्ति (का) भगवान कपिला। सदैव पीने वाला आनंद,\nभगवान \"कपिला\" जिन्होंने अद्भुत अंक के माध्यम से संसार का रहस्य उजागर किया।\n\nख़ुशी, ब्रह्मर्षि, देवर्षि, महर्षि आदि ब्रह्म तेजस्सु और वेदाध्ययन करते हैं,\nतपस्या, यज्ञ-सबकुछ के बारे में बात करने के बाद, कृष्ण अगले श्लोक में क्षात्र तेजस के बारे में बात करते हैं।",
  "10.27": "उच्छेश्रवसं अश्वनं विधि मम अमृत उद्भवम्।\n\nइरावतं गजेंद्रहं नाराणं च नाराधिपम्-घोड़े जो समुद्र में उठे\nउच्चेश्रवस्स की महिमा, बड़ों के बीच इरावत की, पुरुषों के स्वामी की (उन्नतकीर्ति)\nजो उच्चेश्रवस में है उसे 'उच्चेहश्रवस' कहा जाता है, इरा-लक्ष्मी को 'इरावत' उसका रक्षक कहा जाता है।\nवह जो इरावत में है, उसे \"नराधिप\" कहा जाता है क्योंकि वह सभी नरों का स्वामी है]\nजान लो कि मैं हूं\n\nअतीत में, घोड़ों और हाथियों का उपयोग राजाओं द्वारा सेना के महत्वपूर्ण भागों के रूप में किया जाता था। कृष्ण हैं\nश्लोक में उन्होंने घोड़ों, हाथियों और राजाओं के बीच अपनी विशेष विभूति का उल्लेख किया है। कृष्ण कहते हैं\n\"समुद्र मंथन में अमृत लेकर पैदा हुआ घोड़ा 'उच्चेश्रवसु' है और बड़ा घोड़ा 'इरावत' है।\n\nजान लो कि मैं हूं।'' ये दो जानवर बहुत ही खास जानवर हैं, घोड़ा और हाथी\nजानवर अपनी भक्ति के लिए जाने जाते हैं। ये उस धनवान के प्रति सदैव धोखेबाज होते हैं जो उन्हें प्रेम से रखता है\nअब तंत्रिकाओं में सबसे महान, \"नराधिप\" नहीं रहा। मानव जाति के लिए एक नेता के रूप में खड़े रहें और पवित्र बनें\nजनता की परवाह करने वाले नेताओं में ईश्वर की विशेष उपस्थिति होती है। पहले राज्यभारत के रूप में कार्यरत थे\nयहां हम धर्मराज, परीक्षित आदि राजाओं को याद कर सकते हैं।\n\nभगवान के विभूतिनाम उच्चेश्रवसु, ऐरावत: और नारदीपः यहां आते हैं। \"श्रवसु\" का अर्थ है\nप्रसिद्धि, ज्ञान, कर्म. सर्वज्ञ, सर्वज्ञ भगवान की यह सृष्टि-अवस्था-\n\"उच्चेश्रवसु\" जो सदैव संहार नामक महान कार्य करता रहता है। ऐरा का अर्थ भूदेवी में होता है\nलक्ष्मी निकट है. ऐसी लक्ष्मी के पति भगवान \"ऐरावतः\" हैं। नारा, सर्वा को\nप्राणियों के स्वामी के रूप में, राजाओं के बीच विद्यमान भगवान \"नाराधिपः\" हैं।",
  "10.28": "आयुधानं अहं वज्रं धेनुं अस्मि कामधुक् |\n\nप्रजानाः च अस्मि कंदर्पः सर्पानाम् अस्मि वासुकिः - मैं हथियारों में हीरा हथियार हूं।\n[मैं वज्रायुध में ``वज्र'' के रूप में हूं क्योंकि मैं अरिवर्जिता हूं।] मैं गायों में कामधेनु हूं।\n[कामधुक को धुक से “कामधुक” कहा जाता है - इच्छा के लिए आह्वान करना। मैं कामधेनु में हूं।]\nकामदेव जो संतान उत्पन्न करते हैं [काम-सुख, दारा-कई प्रकार, पा-उन्ना \"कंदर्पा\" से\nएन्निसी कामदेव में है जिसके पास जन्म ऐंठन की शक्ति है] I. मैं सांपों से नहाया हुआ हूं।\n[वसु-सर्वत्र निवास करो, की-प्रसन्न होकर मैं वासुकि में 'वासुकि' हूं।]\n\nअस्त्र-शस्त्रों में सबसे बड़ा अस्त्र भगवान द्वारा धारण किया गया सुदर्शन है। भगवान के हथियार को छोड़कर\nसबसे बड़ा हथियार हीरा हथियार है. कृष्ण कहते हैं, \"मैं हथियारों में हीरा हथियार हूं\"। यह\nवज्रायुध इंद्र का हथियार है। भगवान ने इसे तीनों लोकों पर नियंत्रण करने की शक्ति दी।\nदधीचि नामक ऋषि ने व्रत्र को मारने के लिए भगवान के आदेशानुसार तपस्या की।\nफल को अभिमंत्रित करके बनाया गया हथियार हीरा हथियार है। बारिश होने पर दिखाई देती है बिजली-\nबिजली को वज्रायुध का प्रतीक कहा जाता है। इस हथियार में भगवान \"वज्र नमक\" के रूप में हैं\nआसन्न है. \"वर्जनात् इति वज्रः'। शत्रुनाश सर्व दोष।\nभगवान वज्र.\n\nअस्त्र के बारे में बताने वाले कृष्ण के सामने ही वशिष्ठ मुनि ने विश्वामित्र के सभी अस्त्र-शस्त्र नष्ट कर दिये।\nवह कामधेनु के बारे में बताते हैं. पशुओं में सबसे महान पशु गाय है। हमारे पूरे जीवन भर\nभगवान की अद्वितीय विभूति गाय जो हमें दूध पिलाती है और हमारा पोषण करती है। इसी कारण जब कृष्ण बालक थे\nगोपूजा का परिचय दिया गया। गाय का मल और मूत्र भी अपशिष्ट नहीं है। कुछ नहीं से\nठीक न होने वाला चर्म रोग गोमय तथा मृत्तिके (लाल मिट्टी) में स्नान करने से वह रोग ठीक हो जाता है\nघर के सामने गोबर रखने से कीड़े नहीं होंगे। गोमाया में\nवहां लक्ष्मी का वास होता है. ऐसा महाभारत की एक कहानी में कहा गया है. इस प्रकार\nगाय के अनेक उपयोग हैं. जैसा कि \"कामधुक\" का नाम है जो भगवान जो चाहता है वह देता है\nविभूति कामधेनु में खड़ी थी।\n\nइस संसार के प्राणियों में नर और मादा के बीच जन्मजात आक्षेप के रूप में कौन खड़ा है-\nकामदेव जो बच्चे पैदा करते हैं। इस कामदेव (कंदर्प) में भगवान की अद्वितीय शक्ति निहित है।\nसृष्टि में संतान उत्पन्न करने की घृणित इच्छा सभी के मन में पैदा करो\nभगवान बैठे हैं. इस कारण ईश्वर की कृपा के बिना कोई भी खेल नहीं सकता\nसत्ता से आगे नहीं आ सकते. इसे जबरदस्ती नहीं छोड़ा जा सकता. नमक के रूप में भगवान कंदर्पहा\nकामदेव से परिपूर्ण. उस इच्छा से मनुष्य को अनेक प्रकार की इच्छाएं देकर\nउन्हें संतुष्ट करके, भगवान 'कंदर्पाह' उन्हें अजीब आनंद की शय्या पर सुला देते हैं।\nकामदेव-मन्मथ के बाद, कृष्ण वासना के प्रतीक सर्प का वर्णन करते हैं। पेट\nरेंगने वाले सरीसृप को साँप कहा जाता है। वासुकी सभी सरीसृपों का राजा है।\nभगवान 'वासुकिह' नमक के रूप में खड़े हुए और वासुकि को यह पद दिया। भगवान के बिना कोई जगह नहीं है.\nसर्वव्यापी भगवान 'वासुकिः'",
  "10.29": "अनंतः च अस्मि नागानं वरुणः यदसं अहम् |\n\nपित्यानं अर्यमा च अस्मि यमः संयमतम् अहम् - शेष नाग मैं हूँ।\n[मैं विलुप्त होने के कारण \"अनंत\" सी शेष में हूं।] वरुण, जल निकायों के स्वामी ([वरहिरिददा,\nना-आनंदस्वरूप को \"वरुण\" कहा जाता है और वरुण में ही जलीय जीव हैं]\nमैं अर्यमा हूं, मैं पितृ देवताओं में से हूं। [आर्य-ज्ञाता और म: ज्ञाता\nअत: मैं 'आर्यमन' हूं, मैं आदित्य आर्यमन में पितृपुरुष हूं।] दण्ड देने वालों में\n\nयम[ का अर्थ है ``यम'', यम में वह पापियों को दंड देता है\nजिम्मेदार] मैं हूं।\n\nसाँपों की प्रजातियों में सिर वाला 'नागर' होता है। बलराम के रूप में, नागर में सबसे महान \"शेष\",\nलक्ष्मण के रूप में, बहुत महान देवता शक्ति शेष जो हमेशा भगवान की शय्या पर रहते हैं। शेष पृथ्वी\n परिसंचरण जो आकर्षण बल है। इस प्रकार यह कहा जाता है कि वह शेष पृथ्वी को धारण कर रहा है। जैसे कि\nप्रभु विश्राम में विशेष रूप से विद्यमान हैं। सिर वाले सभी साँपों के लिए स्रोत शक्ति के रूप में\nअवशेषों का स्वामी, अवशेषों से भरा हुआ, जो कभी नष्ट नहीं होता, \"अनंत:\" है।\n\nकृष्ण कहते हैं, \"जलीय जानवरों में, मैं वरुण हूं,\" पानी के घेरे में बहुत से हैं।\nभगवान ने वरुण को एक विशेष विभूति के रूप में भर दिया जो जलीय जानवरों को जीवन देता है। यहाँ\nआने वाले भगवान का विभूतिनाम वरुण है। इसके व्यापक आनंद स्वरूप के कारण इसे 'वरुण' कहा जाता है\nवरुण में जलचरों का स्वामी 'वरुण' भगवान हैं।\n\nदेवता शक्ति-पितृदेवता जो पृथ्वी से अपने शरीर का त्याग करने वाले जीवों को नियंत्रित करते हैं।\nउनमें से, द्वादशादित्यों में से एक, अर्यमा में भगवान एक विशेष शक्ति बन गए, उनके नेता\nखड़ा है. इसलिए ज्ञाता (आर्य) और ज्ञेय (मा) को 'आर्यमन' कहा जाता है,\nमैं कुलपिता आदित्य आर्यमन में हूं,'' कृष्ण कहते हैं।\n\nयम पापमय जीवन के नियंत्रक हैं। यम के भीतर भगवान की विशेष उपस्थिति है।\nयम पर शासन करने वाले भगवान \"यमः\" हैं। योग शास्त्र में यम शब्द अद्वितीय है\nके अर्थ में प्रयुक्त होता है। यह हमें पांच नियम बताता है जो हमें नहीं करना चाहिए। (1) हिंसा, (2) झूठ बोलना\nबताना, (3) चोरी करना, (4) अत्यधिक वासना और (5) दूसरे के सामने हाथ फैलाना।\nयह भगवान यम ही थे जिन्होंने भगवान की पूजा के मार्ग में पालन किए जाने वाले ये पांच नियम दिए।\nभगवान यम जो पूरी दुनिया को नियंत्रित करते हैं और यमधर्म को भी नियंत्रित करते हैं।",
  "10.30": "प्रह्लादः च अस्मि धैतानां कालः कलायतं अहम् |\n\nमृगनं च मृगेन्द्रः अहं वैनतेय; च पक्षिनम - वह दिति के वंश में सबसे बड़े थे\nप्रह्लाद I (वरिष्ठ आनंद द्वारा प्रह्लाद में मैं \"प्रह्लाद\" के रूप में हूं।) काला मैं लेक्कियों में से हूं।\n[चूँकि मैं हत्यारा हूँ, मैं कालादेवता में हूँ जिसे “काला” कहा जाता है।] मैं जानवरों में शेर हूँ।\n\n[जानवर: भगवान से प्रेम करने वाले भक्तों के लिए, मैं इंद्र के शत्रु के कारण 'मृगेंद्र' नामक सिंह में हूं।)\nमैं पक्षियों में उकाब हूँ। [विनता: मैं आत्मसमर्पण करने वालों के समर्थन के रूप में गरुड़ में \"वैनाथेय\" के रूप में हूं।]\n\nप्रभु की उपस्थिति कुलीन और गरीब दोनों में है। वह जो दिग्गजों को ताकत देता है\nप्रभु. आमतौर पर राक्षस ही होते हैं जो किसी का जीवन बर्बाद कर देते हैं। लेकिन ऐसे\nराजवंश की शुरुआत में पैदा हुआ प्रह्लाद बाकी सभी से अलग था। इसका कारण उसमें विद्यमान प्रभु ही है\nविशेषकर उपस्थित रहना। एक विशाल परिवार में जन्मे, उन्होंने बहुत पहले ही वह स्वभाव खो दिया था\nप्रह्लाद महान है. इस कारण वे दिग्गजों में विशिष्ट विभूति हैं। प्रह्लाद पर\nभगवान की विशेष कृपा है. जब वे गर्भ में थे तभी देवर्षि नारद के माध्यम से उन्हें अध्यात्म प्राप्त हुआ\nमैं निर्देश प्राप्त करने के लिए काफी भाग्यशाली था। उन्होंने ध्रुव की तरह पाँच वर्ष की आयु में भगवान को देखा\nपेशेवरों. भगवान ने प्रह्लाद के माध्यम से संसार को एक बहुत ही महत्वपूर्ण संदेश दिया।\n\"भगवान डरावने नहीं हैं, अगर हम प्रेम से भगवान के पास जाते हैं तो वह भी हमसे उतना ही प्रेम करते हैं।\"\nभगवान की पूजा करता दिखता है. कोई व्यवसाय नहीं, कुछ ऐसा जो हम चाहते हैं\nहमें प्राप्ति के लिए भगवान की पूजा नहीं करनी चाहिए; हमारी पूर्ण भक्ति भगवान के प्रति है\n'इस तरह भगवान की पूजा करने से हम हमेशा खुश रह सकते हैं'\nप्रह्लाद ने जग दिखाया। भगवान के विभूतिनामे प्रह्लादः यहां आते हैं। कभी नहीं\nआनंदमूर्ति भगवंत प्रह्लाद: जो दुःख से परिपूर्ण है।\n\nकृष्ण कहते हैं: \"कालः कलायतम् अहम्\"। इस दुनिया में हमेशा-हमेशा के लिए\nजो भी जन्म और मृत्यु होती है वह पूर्वनिर्धारित है। इसे कोई नहीं बदल सकता. यहाँ\nकाल शब्द के कई अर्थ हैं जैसे गणना, मृत्यु, शिव, दुर्गा, कालाग्नि आदि।\nइन सभी में भगवान की विशेष विभूति छिपी हुई है। “कला” में संज्ञा के रूप में भगवान कलाह\nपूर्ण काला शब्द 'कला' धातु से बना है। सभी गुण, सभी\nकलाह वह है जिसने अपने अंदर काबिलियत को 'तराशा' है। भगवान सभी गुणों से परिपूर्ण हैं\nसिद्धांत जब हम इस सिद्धांत को समझे बिना अहंकारी हो जाते हैं, तो वही सिद्धांत हमारा 'काल पुरुष' होता है।\nवध की ओर ले जाना. कभी-कभी हमारा उद्धार 'जीवन में' होता है और कभी-कभी यह हमारा होता है\n'मृत्यु में'; कभी हमारी 'इज़्ज़त' में, कभी हमारी 'शर्म' में.; कभी-कभी हमारा\nयदि हमारा उद्धार 'ज्ञान' में है, तो कभी-कभी हमारा उद्धार हमारे 'अज्ञान' में भी होता है। लेकिन\nहमारे 'अहंकार' से कभी मुक्ति नहीं होती। जब संसार अहंकारपूर्ण अज्ञान से भर जाता है\nभगवान 'काल पुरुष' के रूप में बड़े होते हैं। काल का दूसरा अर्थ 'समय' भी है।\nप्रत्येक कार्य के पीछे 'काल' ही कारण है। समय भगवान कलह.\n\nप्रबुद्ध अवतारों (व्यास, कपिल, दत्तात्रय, नर-नारायण, आदि) से लेकर अज्ञान तक।\n\n'कलावड़ा' भगवान, शक्तिशाली अवतारों (नरसिम्हा, वराह, राम, परशुराम, आदि) से।\nअहंकार के लिए, 'समय बन गया है'\"।\nकलाह\n\nकृष्ण, जो अपनी विभूति को संहारक शक्ति के रूप में बोलते थे, जानवरों में सबसे भयंकर और सबसे शक्तिशाली थे\nपशु में अपनी विभूति बताते हैं। पृथ्वी पर सबसे शक्तिशाली और सबसे बड़ा जानवर हाथी है। लेकिन\nजंगल का राजा मृगेन्द्र-सिन्हा ऐसे हाथी को भी मार सकता है। जानवरों में सबसे महान\nविभूति के रूप में, जो एक जानवर है, भगवान सिंह पर विराजमान हैं। भगवान का नाम यहाँ आ रहा है\n\"मृगेन्द्रः। सर्वोच्च (मृगा) जो भगवान की प्राप्ति में खड़े लोगों के लिए एक मार्गदर्शक के रूप में खड़ा है।\nभगवान 'मृगेन्द्रः'।\n\nपशुओं के बाद पक्षियों में भी प्रभु की विभूति। पक्षियों में सबसे महान पक्षी 'ईगल' है। पेट\nगरुड़ एक प्रकार का गरूड़ पक्षी है जिसके शरीर पर सफेद भाग होते हैं। भगवान का वाहन गरुड़ विनुत का पुत्र है। इसलिए\nउसे वैनतेय कहा जाता है। उन भक्तों (विनता) के समर्थन के रूप में \"वैनेतेय\" कहें जो उनके प्रति समर्पण करते हैं\nभगवान गरुड़ में विद्यमान हैं। गरुड़ भगवान को अपने कंधों पर ले जा रहे हैं-\nप्रभु की विशेष विभूति.",
  "10.31": "पवनः पावनम् अस्मि रामः अर्तभृतम् अहम्।\n\nरुषनम् मकर; च अस्मि स्रोतसम अस्मि जाह्न्वी - गतिमान वस्तुओं में वायु का शेष रहना\nमैं. [पंजगत्नु. देवताओं की पूजा, वनपसेव्य के कारण इसे 'पावना' भी कहा जाता है\nमैं हवा में हूं।] उन नायकों में से जो हथियारों से लड़ सकते हैं। मैं [खुशी से,\nअमा-अनंत और संसार का आनंद ले रहा हूं] मुझे राम के नाम से जाना जाता है।\nमैं मछलियों के बीच एक व्हेल हूं. [\"मकर\" कहा जाता है क्योंकि वह ज्ञान का दाता है\nमैं मकर में हूं।] मैं नदी में गंगा हूं। [उन लोगों के लिए जो जहत की अभिलाषाओं को त्याग देते हैं, एक रक्षक के रूप में,\nमैं गंगा में 'जाह्नवी' हूं।]\n\nकृष्ण आगे कहते हैं \"पवनः पवतमस्मि\"। 'पवन' शब्द का लोकप्रिय होना\nजिसका अर्थ है 'हवा' या वायुदेव। आकाश में चलने वाली शक्तियों में सबसे बड़ी विभूति \"वायु\" है।\nजीवन को नियंत्रित करने वाले वायु-देवताओं में भगवान पवन विशेष रूप से विद्यमान हैं। पावथे\n\nइति पावनः - का अर्थ है निरंतर गति। भगवान, जो सबके भीतर हैं,\n\nवह प्रत्येक वस्तु में अपने-अपने स्वरूप में स्थित है और निरंतर गति देता है। हमारे शरीर में उसकी गति\nरुकते ही हम 'लाश' बन जाते हैं. उपनिषद में भगवान को वनः कहा गया है। वह पा-वनः है;\nयहां 'पा' का मतलब 'रखरखाव' है। वह शक्ति जो हमें और सभी ब्रह्म देवों को पोषित करती है। वनह\nइसका अर्थ है कुछ ऐसी चीज़ जिसकी सभी द्वारा पूजा की जाए, जिसकी प्रेम से पूजा की जाए, जिसे सभी द्वारा पोषित किया जाए।\nहजारों योनियों में हजारों रूपों में निवास करने वाले, सदैव रहने वाले भगवान पवनः।\n\nउनके स्वरूप विभूति ने कहा, \"राम उन नायकों में से एक हैं जो हथियार पकड़ सकते हैं और लड़ सकते हैं।\"\nसमझाता है. कृष्ण... राम अवतार में वह भगवान के सभी अवतारों से बढ़कर हैं\nकोदण्डपाणि नामक अस्त्र का भरपूर प्रयोग करके शत्रु का दमन किया गया।\n\nराम को वि कहा जाता है। शास्त्र में नाम के कई अर्थ हैं। 'रा-अमह, मतलब\nवह जो असीम आनंदमय है और सभी को आनंद प्रदान करता है। ईश्वर का यह गुण\nरामावतार में यह स्पष्ट दिखता है। रामावतार में भगवान कहीं और नहीं हैं\nवह चोट पहुँचाने के लिए नहीं चला। कैकेयी पर जिसने उन्हें वन में भेज दिया\nसबके क्रोधित होने पर भी रामचन्द्र ने कभी बुरा शब्द नहीं कहा। इसके बजाय\nउन्होंने कहा, \"अगर मैंने तुम्हें ठेस पहुंचाई हो तो मुझे माफ कर दो\" और खुशी-खुशी जंगल की ओर चले गए।\nइस प्रकार, रामावतार एक अद्वितीय अवतार हैं जिन्होंने दूसरों की खुशी के लिए बलिदान दिया। रमी\nअरसा के भगवान सीतापति, इस अवतार में एक पुरुष और एक महिला के बीच वैवाहिक जीवन कैसा होना चाहिए,\nभाई-बहन का प्यार कैसा हो, माता-पिता और बच्चों का रिश्ता कैसा हो\nउन्होंने दिखाया है. यह भगवान अमितानंद की विभूति है जिसने दुनिया को आनंद दिया।\nव्हेल पानी की सबसे शक्तिशाली और सबसे बड़ी मछली है। कृष्ण\nवह कहते हैं \"रुषाणं मकरश्चास्मि\"। यहां मकर का मतलब व्हेल है। स्वामी मकर;\nउन्होंने क्रिया के रूप में एक विशेष विभूति के रूप में व्हेल को वह शक्ति प्रदान की। ज्ञान\nदाता (कारा) भगवान मकरः।\n\nकृष्ण कहते हैं, \"मैं नदियों में गंगा हूं।\" सबसे बड़ी नदी गंगा है। इस नदी का जल तुलनीय औषधि है\nकोई दूसरा नहीं है. गंगा स्नान से हम अपने मन को शुद्ध कर सकते हैं। जो भी वहां हैं\nगंदगी हमारी है. गंगा वह जल है जो संग्रहित करने पर कभी खराब नहीं होता। उन्होंने गंगा को यह महान शक्ति प्रदान की\nभगवान का विभूतिनाम \"'जाह्नवी'\" है। \"जाह्नु\" का अर्थ है छोड़ देना। क्षुद्र शारीरिक इच्छाएँ\nजो भगवान त्याग कर भगवान की राह पर चलते हैं उनकी रक्षा करने वाली भगवान \"जाह्नवी\" हैं।\nस्त्रीलिंग प्रतीकात्मक नाम. स्त्री के रूप में माता के समान उपदेश देने वाले प्रभु की पूजा करो\nजाह्न्वी भगवान का स्त्रीलिंग नाम है।",
  "10.32": "सर्गहं अदि अंतः च मध्यम च एव अहम् अर्जुन |\n\nअध्यात्मविद्या विद्यानं वदः प्रवादतम् अहम्।- हे अर्जुन, प्राणियों के जन्म और मृत्यु के लिए,\nमैं होने का कारण हूं. मैं जागरूकों में आध्यात्मिक जागरूकता हूं। [\"आध्यात्मिक\" जीवन के स्वामी के रूप में\nएन्निसी, मैं आध्यात्मिक विज्ञान में हूं जिसे 'विद्या' कहा जाता है क्योंकि यह ज्ञान है।] चर्चाकर्ताओं की चर्चा में।\nमैं एक तर्क हूं [सैद्धांतिक ज्ञान के लिए संचालित]। [सभी संज्ञाओं से \"वड़ा\" पढ़ें।\nबहस की।]\n\nसंसार की प्रत्येक वस्तु में भगवान की विभूति छिपी हुई है। जाहिरा तौर पर हमारे लिए\nयहाँ तक कि एक बेकार दिखने वाली चीज़ में भी एक अनोखा गुण होता है जो दूसरी चीज़ में नहीं पाया जाता (Exclusive Quality) छिपा हुआ है. तो घास के एक तिनके से लेकर चार मुख वाले ब्राह्मण तक सब कुछ\nप्रभु की विभूति. यहाँ कृष्ण ने केवल उस समूह की विशिष्टता का उल्लेख किया है। जीवन का जन्म होता है\nवह प्रभु वही है जो पहले था, वही है जिसने जीवन के अस्तित्व का कारण बना, वही है जो अंत में संहारक के रूप में खड़ा होता है। इस प्रकार\nकृष्ण कहते हैं, \"मैं जन्म में हूं, अस्तित्व में हूं और मुझमें हूं।\" “यह मामला-ज्ञान\nकृष्ण ने यहां पार्थ को 'अर्जुन' कहा है, ऐसा करने, सात्विक बनने के अर्थ में, आप जानते हैं।\nविशेष रूप से सम्बोधित किया गया।\n\nकृष्ण कहते हैं, \"मैं चेतनाओं के बीच आध्यात्मिक चेतना हूं।\" एक आध्यात्मिकता जो भगवान को छूती है\nईश्वर ज्ञान से परिपूर्ण है। भगवान अधिक-आत्मा (अध्यात्म) जो सभी आत्माओं में विद्यमान हैं।\nआध्यात्मिक ज्ञान प्राप्त करने के लिए हमें दूसरों के साथ बातचीत करनी चाहिए। ये हमारा है\nसमझ बढ़ाने के लिए, ज्ञान की प्यास जगाने के लिए क्लासिक्स\nऐसी चर्चा में, \"वादः\" ईश्वर का वचन है, जिसे सभी नामों से पढ़ा जाता है\nभगवान वदाः।",
  "10.33": "अक्षराणां अकारः अस्मि द्वन्द्वः समासिकास्य च।\nअहं एव अक्षयः कलः धाता अहं विश्वतोमुखः - मैं अक्षरों में प्रथम अक्षर हूं। [\"ए\"\n'अकार' को 'अकार' कहा जाता है, जो अ-कार से पढ़ा जाता है।] समास के समूह में द्वैत।\n\nसमसा मैं हूं. [द्वंद्व को 'द्वैत' कहा जाता है क्योंकि इसके अंदर और बाहर दो रूप होते हैं\nमैं समसा में हूं।] मैं अविनाशी [समय में] भक्षक हूं। हर जगह सब कुछ भरा हुआ है\nमैं एक सलाहकार भी हूं.\n\nकृष्ण, जिन्होंने पहले ओंकार को शब्दों में उच्चारित किया था, यहाँ अपनी विभूति को अक्षरा में उच्चारित करते हुए कहते हैं:\nयथा \"अक्षरणमकारोस्मि\"। 'अ' भगवान के सभी गुणों का लक्षण है\nअक्षर A- का अर्थ है \"नहीं'। भगवान 'नहीं' है। इसका मतलब है कि वह कोई ऐसी चीज़ नहीं है जिसे हम जानते हैं। वह है\nदुनिया से विदेशी. ऐसा भगवान 'नहीं' है. यानी उसमें कोई दोष नहीं है. वह है\nसर्वशक्तिमान इस प्रकार सर्व-अद्वितीय, सर्व-निर्दोष, सर्व-गुण संपन्न भगवान -\nकरावाच्य का अर्थ है \"अकार से भरा हुआ\"।\n\nअक्षरा के बाद, समास के बारे में बोलते हुए, कृष्ण कहते हैं: \"द्वंद्वः समासिकास्य\"। हमारे लिए\nजैसा कि आप जानते हैं, किसी भी शब्द को एक शब्द होने के लिए दो शब्द (या एक शब्द और) होने चाहिए\nएक प्रत्यय होना चाहिए) अन्य सभी समास में एक शब्द, या दोनों शब्द (एकाधिक)।\nअपनी प्रधानता खो सकता है. लेकिन द्वैत समास में दोनों शब्द महत्वपूर्ण हैं।\nद्वंद्व के प्रमुख समास, द्वंद्व समास में भगवान द्वंद्व द्वंद्व से भरे हुए हैं।\nभगवान द्वन्द्वः हमारे अन्दर और बाहर दो रूपों से परिपूर्ण हैं।\n\nभगवान कालपुरुष जो सभी को नष्ट करते हैं, सभी की रक्षा करते हैं और उनका भरण-पोषण करते हैं\n'तत्व'. ऐसे भगवान विश्वतोमुख हैं। वह हर जगह है। उसके बिना कोई जगह नहीं है. वह अदृश्य है\nकोई छाती नहीं.",
  "10.34": "मृत्युः सर्व हरः च अहं उद्भवः च भिवैतम्।\n\nकीर्तिः श्रीः वाक् च नारीनम् स्मृतिः मेधा धृतः क्षमा - मृत्यु के सर्वभक्षी देवता।\n[मरने वाले के रूप में, \"मृत्यु के नाम\" के रूप में, यम का अनुचर मृत्यु के देवता में है।\nउसमें सब कुछ निगलने की शक्ति है] मैं हूं। मैं ही भविष्य का निर्माण करने वाला हूँ।\nमैं स्त्रियों में महिमा की देवी हूं; मैं श्रीदेवी हूं; मैं वाग्देवी हूं. मैं स्मृति की देवी हूं;\nमैं सहनशक्ति की देवी हूं; शानू, धैर्य की देवी; मैं क्षमा देवी हूं.\nएन्निसी कीर्तिदेवी में है; मैं 'श्री' के रूप में श्रीदेवी में आश्रय के रूप में हूं; प्रवक्ता के रूप में \"चलना\"।\nवाग्देवी में हूँ; मैं स्मृति देवी में स्मृति के रूप में 'स्मृति' के रूप में हूं; जागरूकता के स्वरूप के रूप में\n\n'ध्रुति'. एनीस. मैं धृतिदेवी में हूं; गलतियाँ. “क्षमा” एक क्षमाकर्ता के रूप में। एनीस\nमुझे खेद है.]\n\nहाँ, भगवान मृत्यु के देवता भी हैं जो प्रलय के दिन सब कुछ नष्ट कर देते हैं। जलप्रलय के बाद\nसृष्टि का पुनर्निर्माण भी वही करते हैं। अपनी विभूति को स्त्री रूप में बता रहे हैं\nकृष्ण यहां मुख्य रूप से लक्ष्मी, सरस्वती और भारती में अपनी विभूति का वर्णन करते हैं। वैभव,\nभाग्य, सुंदर वाणी, स्मृति, बुद्धि, दृढ़ संकल्प और धैर्य - ये संरक्षक देवता हैं\nमुख्य रूप से लक्ष्मी और सरस्वती। और भारतीय. उनमें भगवान एक स्त्री विभूति के रूप में हैं\nखड़ा है",
  "10.35": "बृहत्सं मा तथा समं म गायत्री छंदसम अहम्।\n\nमसानम मार्गशीर्ष अहं खुतुनम कुसुमाकरः - साम गीतों में सबसे महान।\nमैं सामा का गीत हूं. [सर्वव्यापी होने के नाते, स-सर्वस्तु और, अमा-समझदार।\n\"मैं 'बृहत्साम' सी बृहत्साम 1 में हूं। छंदों में मैं गायत्री हूं। [गया''\nमैं गायकों के त्रय के कारण गायत्री छंद में \"गायति\" के रूप में हूं]।\nमुझे ['हेडिंग'' कहा जाता है क्योंकि यह सड़क के अंत में है। मैं मार्गशिरामाहा में हूं।]\nमैं पत्रों में बसंत हूं. [कु:बुरा, सु-अच्छा, मा-ज्ञान, कर-देता है \"कुसुमाकर\"\nएन्निसी वसंत खुथु में है।]\n\nसामान कई प्रकार के होते हैं. सप्त स्वर का प्रयोग कर गायन केवल सामवेद में है। यह ऋग्वेद है\nयजुर्वेद में नहीं. सभी समास में सप्तस्वर का कोई उपयोग नहीं है। इस तरह सप्पास्वरा के साथ एक समा में\nकृष्ण कहते हैं, \"मैं बृहत्साम का गीत हूं।\" यहाँ भगवान का नाम \"बृहत्समः\" है\nवह भगवान जो हमारे लिए व्यापक, सर्वोत्कृष्ट और समझ से बाहर है, वह \"बृहत्समः\" है।\n\nश्लोक के रूप में एक अनोखा अर्थ, आध्यात्मिक सन्देश से परिपूर्ण-\nतुकबंदी यह अपनी राय को लयबद्ध तरीके से व्यक्त करने का एक तरीका है। मुख्य रूप से छंदशास्त्र में\nछन्द सात हैं। 24 अक्षर गायत्री, 28 अक्षर उष्जिक, 32 अक्षर अनुष्टुप, 36 अक्षर\nबृहती, 40 अक्षर वाली पंक्ति, 44 अक्षर वाली त्रिष्टुप और। 48 अक्षर ब्रह्मांड. इन तुकबंदी में\n'गायत्री' वह छंद है जिसमें भगवान की विशेष विभूति है। यह भगवान का नाम भी है.\n\n'गायताम् त्रायते इति गायत्रीः। जो कोई इस मंत्र से भगवान की स्तुति करता है\nवह उनकी रक्षा करता है. गायत्री छन्द सात छन्दों में प्रथम छन्द है। आठ\nअक्षरा के तीन पैरों वाली गायत्री हर चीज के पंचांग (Foundation) के समान है। अधिकांश ऋग्वेद\nमंत्र गायत्री छन्द में हैं। गायति को सभी वेदों की 'वेदमाता' माना जाता है\nमंत्र \"गायत्री\" छंद में है। इस प्रकार गायत्री अन्य छंदों का जनक है।\nगायत्री एक मंत्र है जिसमें आध्यात्मिकता का मौलिक पहलू है। धूप में\nभगवान की स्तुति करो, सौर मंडल में हमारा जीवन-सिद्धांत, सौर ऊर्जा को हम तक पहुंचाना\nगायत्री करती है. \"सौर ऊर्जा से उत्पन्न सम्पूर्ण ब्रह्माण्ड का नियंता हमारी आत्मा है\nहमारे हृदय कमल में 'धी' शक्ति का योग है जो शक्ति भगवंत को प्रेरित करता है।'\nगायत्री चिंतन का मंत्र है। गायत्री का प्रयोग आमतौर पर वैदिक छंद के रूप में किया जाता है।\nइसका कोई सांसारिक उपयोग नहीं है. गायत्री की यह अद्वितीय स्थिति भगवान की विशेष विभूति से प्राप्त हुई।\n[एक बात जो हमें यहां जाननी चाहिए: ऐतरेय उपनिषद में बृहती चंदासनु महान है।\nऐसा कहा. इसका कारण यह है कि गायत्री को प्रशंसक देवता भेदभाव में देखा जाता है\nसंरक्षक देवता लक्ष्मी, सरस्वती, भारती, गरुड़ और अग्निपत्नी स्वाहा हैं। भारी तुकबंदी\nदेखा जाए तो लक्ष्मी, सरस्वती, भारती, गरूड़ और बृहस्वतिपत्नी तारा पूजक हैं।\nचूँकि अग्निपत्नी स्वाहा, देवता भेदभाव से तारा देवता भेदभाव में उच्च है\nवहां ऐसा कहना जरूरी है. यह जानने से कोई भ्रम नहीं रहता।]\n\nकृष्ण कहते हैं, \"मैं महीनों का मार्गदर्शक, चरणों का वसंत हूं।\" मार्गशिरामास-मास में\nपहला महीना; कार्तिक आखिरी महीना है. इस कारण कार्तिक मास (मार्गशिरा मास) में\nपहले) दिवाली मनाएं. कृतज्ञता के साथ एक वर्ष विदा कर रहा हूँ\nदिवाली का महत्व मार्गशिरा को आगरा-हयाना कहा जाता है। हयाना का मतलब महीना होता है. आगरा यानी\nपहला वाला. इस माह में हम गीता जयंती मनाते हैं। इस कृष्ण से लेकर अर्जुन तक\nजिस माह में इस गीत का उपदेश किया गया उसे मार्गशिरा भी कहा जा सकता है (इस पर और अधिक शोध होगा)\nज़रूरी)। इस माह में विभूति के रूप में विराजमान भगवान का विभूतिनामा 'मार्गशीर्ष' है। साधना\nवह प्रभु, जो उस मार्ग का सिरा है जिस पर हमें चलना है, वह \"मार्ग का मुखिया\" है।\nकृष्ण कहते हैं कि मैं वसंत ऋतु में 'कुसुमाकर' हूं, जब पेड़ उगते हैं। सबसे बुरे के लिए\nजो भगवान कुस्सितव हैं और सज्जनों को अच्छा ज्ञान प्रदान करते हैं, वे \"कुसुमाकरः\" हैं।",
  "10.36": "देउथं छलयथं अस्मि तेजः तेजस्विनं अहम्।\n\nजयः अस्मि व्यवहारः अस्मि सत्त्वं सत्त्ववतं अहम् - मैं धोखेबाजों का जुआरी हूं।\n[मैं एक खिलाड़ी के रूप में जुआ खेल रहा हूं।] मैं नायकों का नायक हूं। [प्रकटीकरण के कारण\nमैं \"तेजस\" या पी बीरा में हूं।] विजय मैं हूं।\nश्रमिक मैं [मैं 'खेती' नामक पेशे में हूं क्योंकि यह ज्ञान है।] बुजुर्ग व्यक्ति\nगरिमा मैं हूँ.\n\nदेउता को कौरवों और पांडवों के बीच युद्ध का कारण माना जाता है। यह भ्रामक है\nसबसे बड़ी कला! भगवान एक 'देवदूत' के रूप में जुआ खेल रहे हैं। यहां भगवान का नाम 'द्युत' है। दिवु\nयानी खेल. जो भगवान सदैव सृष्टि के संहार की क्रीड़ा में लगे रहते हैं, उनका शब्द \"द्युत\" है।\nपराक्रमी की महिमा प्रभु है. भगवान जयः नमक के रूप में विजय में हैं। पूरी दुनिया में\nप्रभु विजय के प्रेरक हैं। जो किसी कार्य में उत्साहपूर्वक लगा रहता है\n\"व्यवसाय\" भगवान का नाम है. शक्ति के शासक के रूप में, वह बलवानों में \"सत्व\" का नाम है।\nबैठा है",
  "10.37": "वृषेतीनां वासुदेवः अस्मि पाण्डवनम् धनञ्जयः।\n\nमुनिनाम अपि अहम व्यासः कवीनम् उषाना कविः - वृष्टिवंश के राजाओं के बीच।\n[वसु-सर्वव्यापक, सबमें व्याप्त, देव-दिव्य स्वरूप होना] वासुदेव के रूप में\nमैंने अवतार लिया है. मैं पांडवों में अर्जुन हूं। (\"धनंजय\" को सिरी का विजेता कहें\nमैं अर्जुन में हूं।] ऋषियों के बीच ([v: सभी से सबसे प्रतिष्ठित, वह-हर जगह, सः इवाना\nपूर्ण होना] व्यास I. मैं वैज्ञानिकों में सबसे पुराना विद्वान शुक्र हूं।\n[इच्छारूपा के रूप में, मुझे ध्यातुगुरु शुक्र में \"उशनस\" कहा जाता है।]\n\nसाक्षात विभूति की बात करते हुए कृष्ण कहते हैं \"वृष्टिनां वासुदेवः अस्मि\"। यहाँ\nभगवान के विभूति नाम \"वासुदेवः। सर्वत्र अदृश्य, अन्तर्यामी का दयालु ज्ञान\nभगवान वासुदेव जो प्रकट होते हैं। कृष्ण कहते हैं कि मैं पांडवों में 'धनंजयः' हूं। ये है\nएकदेश विभूति. अर्जुन पर भगवान का विशेष प्रभार था। उसमें भगवान “धनंजयः।”\nवह नामांकित व्यक्ति के रूप में खड़े थे। धनंजयः का अर्थ है ज्ञान। प्रभु चेतना, उससे\n\nप्राप्त मोक्ष शाश्वत धन है। इसे प्रदान करने वाले भगवान धनंजय ही हैं। ऋषियों में व्यास। ये है\nईश्वर की प्राप्ति. व्यास ने वेदों को 1137 संहिताओं में विभाजित किया\nमुखेना ने हमें दिया है. वेद मुख्यतः चार हैं। काव्य संकलन ऋग्वेद, गद्य संकलन\nयजुर्वेद, गणाक्षर सामवेद, अथर्व मुनि को ब्रह्मा ने उपदेश दिया था और अथर्वण ने लिखा था।\nवेद. मूलतः वेद तीन हैं परन्तु ख़ुशी परम्परा के अनुसार चार वेद हैं\nवेदव्यास ने चार ऋषियों (बैल, वैशम्पायन, सुमन्तु) से यही कहा था\nऔर जैमिनी से कहा)। इन चारों ऋषियों ने वेद को पुनः कई शाखाओं (संहिता) में विभाजित कर दिया।\nहल निकाला। ऋग्वेद में 24 संहिताएँ हैं; यजुर्वेद की मुख्यतः दो शाखाएँ हैं। एक शुक्र\nयजुर्वेद और दूसरा कृष्ण यजुर्वेद। 15 शुक्ल यजुर्वेद में संहिता और कृष्ण\nयजुर्वेद में 86 संहिताएँ, कुल 101 संहिताएँ। सामवेद की 1000 शाखाएँ, एक हजार\nएक प्रकार का गायन! लेकिन आज केवल तीन (जैमिनी, राणायनी और कौतुमन)\nगणपद्धति ही प्रचलित है। अथर्ववेद की कुल 12 शाखाएँ हैं। इस प्रकार वेद 1137\n मुनि व्यास ने संहिताओं में विस्तार किया। मानव स्वभाव की बुद्धि\nभगवान व्यासः, जिन्होंने हमारे सामने विचित्र ज्ञान का सागर खोल दिया है, वे हर जगह मौजूद हैं। बृहस्पति विशाल है\nभगवान शुक्राचार्यों के बीच \"उशना\" के रूप में खड़े थे। इस कारण शुक्र ग्रहों में से एक बन गया।\nस्थित. भगवान \"उषाण\" जो सभी कार्य अपनी इच्छा से करते हैं।",
  "10.38": "दण्डः दमयथम अस्मि नीतिः अस्मि जिगिष्टम्।\n\nमौनं च एव अस्मि गुह्यं ज्ञानं ज्ञानवतं अहम् - झुकने वालों को दंड।\nमैं [क्योंकि मैं दंड देने वाला हूं, मैं दंड नीति में हूं जिसे \"दंड\" कहा जाता है।] उन लोगों का धोखा जो जीतना चाहते हैं।\nमैं [मैं इसे 'नैतिकता' कहने में पाखंडी हूं क्योंकि यह जीत की ओर ले जाती है।] गुप्त रूप से मौन\nमैं [संतों द्वारा 'मौन' के रूप में स्तुति की गई है, मैं मौन रहता हूं।] मैं जानने वालों का ज्ञान हूं। [संज्ञानात्मक\nमुझे \"ज्ञान\" के रूप में जाना जाता है क्योंकि मैं एक मूर्ति हूं।]\n\nकृष्ण कहते हैं, \"मैं बुराई का दमन करने वाला हूं।\" इस दमनकारी शक्ति के रूप में नायकों के बीच\nभगवान बैठे हैं. दण्ड का अर्थ है दण्ड। संस्कृत में दण्ड का अर्थ शिक्षा है। लेकिन\nयहां डंडा का अर्थ दंड देना है (Punishment)। परमेश्वर के राज्य में ग़लतियों के लिए कोई क्षमा नहीं है। हम हैं\nहमें किये गये कर्मों को महसूस करना होगा। गलत काम करने वालों के प्रति कठोर और कठोर\n\nदण्ड देने वाला भगवान \"दण्ड\" है। वह प्रभु जो विजयी शक्ति के रूप में सभी को नियंत्रित करता है\n\"भगवान जो धार्मिकता और मन के रूप में खड़ा है वह 'मौना' है। भगवान जो ज्ञाता का ज्ञाता है वह “ज्ञानः” है।\n\nमूलतः विभूतियों की सीमा यहीं समाप्त हो गई। आगे विभूति का उपसंहार है\nआइए शेष अध्याय में देखें।",
  "10.39": "यत् च अपि सर्व भूतानां बीजं तत् अहम् अर्जुन |\n\nन तत् अस्ति विना यत् सत् माया भूतम् चर आचरम् - अर्जुन, सभी जीवित प्राणियों में\nउसमें जो भी अद्वितीय गुण हैं, वह शक्ति मैंने ही दी है। मुझे छोड़कर\nव्यवहार में कुछ भी स्वतः स्पष्ट नहीं है।\n\n“इस संसार में सभी पदार्थों (जड़-आत्मा) का मूल रूप और ऊर्जा\nमैं दाता हूं, ”कृष्ण कहते हैं। इस प्रकार भगवान सारी सृष्टि के बीज के रूप में खड़े हैं।\nवह वह है जो अदृश्य जीवन को दृश्य शरीर देता है। जीवन मनुष्य की अवस्था में है\nरेथा का चेहरा महिला के शरीर में डाला जाता है, जहां वह जीवन को एक रूप देता है और उसे रोशन करता है\nप्रभु. इस प्रकार इस संसार में आत्मा या नैतिकता हर चीज़ का प्रवर्तक है\nप्रभु. कृष्ण कहते हैं, ''इस संसार में ऐसी कोई वस्तु नहीं है जो मुझसे स्वतंत्र हो।'' यह है\nवैदिक परंपरा में व्याप्त भ्रम पर कृष्ण का सीधा उत्तर। जीव और भगवान एक नहीं हैं.\nजीवन ईश्वर का प्रतिबिम्ब है। सब कुछ है। परन्तु ईश्वर से पृथक किसी का भी स्वतंत्र अस्तित्व नहीं है।",
  "10.40": "न अंतः अस्ति मम दिव्यं विभूतिनं परंतप।\nएषः तु थम्नतः प्रोक्तः विभूतः विस्तारः | माया-हे परंतप, मेरे दिव्य रूपों की\nमहानता का कोई अंत नहीं है. मैंने यहां अपनी कुछ ही महानताओं का नाम दिया है।\n\nकृष्ण कहते हैं: “मेरी विभूति संसार की प्रत्येक वस्तु में है\n\"नहीं।\" ईश्वर के सांसारिक आश्चर्य का कोई अंत नहीं है। इसे बढ़ा-चढ़ाकर नहीं कहा जा सकता. यहाँ\nकृष्ण सबसे महत्वपूर्ण हैं, हम... निरंतर पूजा करते हैं। करने के लिए, दैनिक\nचर्चा में क्या होना चाहिए, इसके बारे में उन्होंने बस इतना ही कहा",
  "10.41": "यत् यत् विभूति मत सत्त्वम् श्रीमत उर्जितम् एव वा |\n\nतत् तत् एव अवगच्छ त्वं मम तेजः अम्स संभवम् - समूह में रहना, सिरी में\nलंबा. जो कुछ भी ऊपर चमकता है वह मेरे महान प्रकाश की चिंगारी से है\nजानो कि यह उत्पन्न हो गया है।\n\nसामान्य तौर पर, यह वह है जो किसी व्यक्ति, वस्तु के बारे में अद्वितीय है, न कि दूसरों के बारे में\nपरमेश्वर की महिमा के प्रकाश की एक चिंगारी। यह भगवान की अनंत प्रतिभा का एक अंश है।",
  "10.42": "या बहुना एतेन किम ज्ञातेन तव अर्जुन।\n\nविषभ्य अहं इदं कृत्स्नम एक अनशेन स्थितः जगत - या, हे अर्जुन, सब कुछ जानकर।\nक्या हुआ? यह सार है: मैं इस पृथ्वी की दुनिया को अपने एकमात्र तत्व से गले लगाता हूं और धारण करता हूं\nसंचालन\n\nप्रत्येक को अलग-अलग जानना असंभव है। ऐसा करने की कोई जरूरत नहीं है.\nभगवान हर चीज़ के भीतर अद्वितीय शक्ति हैं। हर चीज़ में भगवान की विभूति निहित है।\nकृष्ण कहते हैं, \"मैं अपनी शक्ति के एक अंश से संपूर्ण ब्रह्मांड में व्याप्त हूं\"।\nवह है। जैसा कि पुरुष सूक्त कहता है:\n\nपडोस्य विश्व भूटानी| त्रिपादस्यामृतं दिवि|\n\nत्रिपादुर्ध्व उदयितपुरुषः। पादोसयेहभवथु नः।\n\nततो विष्टमव्यक्रमत्.| ससाननशाने अभि |\n\nईश्वर का केवल एक चौथाई भाग ही इस संसार में व्याप्त है। एक स्वादिष्ट तीन-चौथाई\nभग दिव्यलोक (मुक्तलोक) में रहता है। “दुनिया के सभी पदार्थों को अंदर और बाहर भरें\n\nभगवान श्रीकृष्ण के विभूति नामक इस अध्याय में कहा गया है कि मैं ब्रह्मांड का स्वरूप हूं\nयह ख़त्म हो गया है.\n\nइति दशमोऽध्यायः\nदसवाँ अध्याय ख़त्म हो गया\n\nचिंता मत करो\n\nअध्याय ग्यारह\n\nयह अध्याय बताता है कि भगवान की पूजा करते समय उनके बारे में कैसे सोचना चाहिए\nअध्याय यह भगवान का विश्वरूप दर्शन अध्याय है। कृष्ण द्वारा अर्जुन को दिव्यनेत्र की कृपा प्रदान करना |\nवह अपना विश्वरूप दिखाता है। यहाँ उस ब्रह्माण्ड का वर्णन है। यहाँ व्याप्त है,\nसर्वव्यापी, सर्वशक्तिमान भगवान के बारे में कैसे सोचा जाए, इस पर मार्गदर्शन है।\nईश्वर के स्वरूप की तुलना किसी सांसारिक अनुभव से नहीं की जा सकती। बस इतना ही\nएक अलौकिक अनुभव. यह अध्याय उस अद्भुत अनुभव का वर्णन करता है।\n\nहर कोई भगवान के विश्व स्वरूप का ध्यान नहीं कर सकता। लेकिन हर जगह\nध्यान योग में प्रत्येक व्यक्ति पूर्ण रूप से ईश्वर का किंचित दर्शन प्राप्त कर सकता है। कैसे\nजैसे कृष्ण ने अर्जुन को अपना विश्वरूप दिखाया, वैसे ही ध्यान में उन्होंने हमें भी अपना रूप दिखाया\nउसे यह दिखाना चाहिए. यह वह रूप नहीं है जो बाहरी जगत में दिखता है। हम अपनी आंतरिक आँखें खोलते हैं\nव्यक्ति को बैठकर ध्यान करना चाहिए, व्यक्ति को भगवान के प्रति समर्पण करना चाहिए। जिज्ञासावश पुकारने पर भीतर से क्या?\nयदि सहानुभूति आती है, तो यह सांसारिक सहानुभूति से परे है।\n\nइस अध्याय में भगवान के वचन कम हैं। यहां उन लोगों के शब्द हैं जिन्होंने कृष्ण के सार्वभौमिक रूप को देखा। वे हैं\nजो दिख रहा है उसे सुनकर हमें प्रभु के दर्शन का प्रयास करना चाहिए। यह हमारा आंतरिक स्व है\nआध्यात्मिक अनुभूति के पूरक के रूप में हमें ध्यान के मार्ग पर ले जाना अत्यंत आवश्यक है\nअध्याय आओ, व्यास से भगवान के अद्वितीय विश्व स्वरूप का वर्णन सुनो\nआइए आभारी रहें.\n\nअध्याय में प्रवेश करने से पहले हमें एक बात जाननी होगी। हममें से कुछ के लिए\nएक गलतफहमी है. “अर्जुन को भगवान का संदेश समझाने के लिए कृष्ण उनके पास हैं\nविश्वरूप दर्शन तो करना ही था. “भले ही उन्हें स्वयं भगवान कृष्ण ने निर्देश दिया हो\nअर्जुन को यकीन नहीं हो रहा था कि अब हम क्या कर सकते हैं? हमारे लिए विश्वरूप दर्शन कौन है?\nसोचने वाले भी हैं, लेकिन ये हमारी ग़लतफ़हमी है. अर्जुन के लिए\nप्रभु का संदेश दृढ़ विश्वास से भरा था। यह बात इस अध्याय के प्रथम श्लोक में है\nजान लेंगे अर्जुन कहते हैं \"मोहोयम विगतो मम\" - \"आपकी महिमा को जानना ही मेरा सब कुछ है\nसंशय भी बीत गया'. इससे जो समझा जा सकता है वह है अर्जुन का भगवान अर्जुन के प्रति दृष्टिकोण\nजो चाहिए वह केवल देखना और धन्य होना है, प्रमाण के लिए नहीं। आम तौर पर\nमानव स्वभाव है कि कुछ सुनने के बाद उसे देखना स्वाभाविक है\nइच्छा अर्जुन ने भी कृष्ण के समक्ष ऐसी ही इच्छा रखी। अगले चार\nश्लोक में यह विचार स्पष्ट रूप से समझ में आता है।\n\nअर्जुन उवाच |\nमदनुगृहाय परं गुह्यमध्यात्मसंज्ञम्।\nयश त्वयोक्तं वाचस्तेन मोहो$यं विगतो मम ॥1॥",
  "11.1": "अर्जुनः उवाच- अर्जुन ने कहाः\n\nमत् अनुग्रहाय परमं गुह्यं अध्यात्म संज्ञिथम्।\n\nयत् त्वया उक्तं वाचः तेन मोहः अयं विगतः मम -- मुझ पर दया करो,\nआपने अध्यात्म का पुराना रहस्य निभाया। मैं उस शब्द से दुखी था.\n\nअर्जुन कहते हैं: “अपनी कृपा से मुझे आध्यात्मिकता का सबसे गहरा विचार दीजिए\nकहा।\" यहां \"अनुग्रह\" का अर्थ है-उनमें से कम से कम का मार्गदर्शन करना और उन्हें ऊपर उठाना\nबुजुर्ग छुटकारा पाना चाहते हैं। “मैं भटकने ही वाला था",
  "11.2": "भवाप्ययौ हि भूतानां श्रुतौ विस्तरशो मया ।\nत्वत्तः कमलपत्राक्ष माहात्म्यमपि चाव्ययम् ॥\n\nजीवों के भव और अप्यय — उत्पत्ति और विनाश — विस्तारपूर्वक आपसे सुने। हे कमलपत्र-नयन, आपका अव्यय माहात्म्य भी सुना।\n\nअर्जुन पूर्व अध्यायों में सुने ज्ञान का सार संक्षेप करता है। 'कमलपत्राक्ष' — पद्मदल-सदृश नेत्रों वाले — सौन्दर्यसम्पन्न भगवान् का सम्बोधन। अब ज्ञानदर्शन की इच्छा प्रकट होती है।",
  "11.3": "एवमेतद्यथात्त्वमात्मानं परमेश्वर ।\nद्रष्टुमिच्छामि ते रूपमैश्वरं पुरुषोत्तम ॥\n\n'हे परमेश्वर, जैसा आप अपने विषय में कहते हैं वह सत्य है' — अर्जुन श्रद्धावान् है।\n\nकिन्तु — ऐश्वर रूप — जगत् के ईश्वर का परमरूप — देखना चाहता हूँ। पुरुषोत्तम — क्षर-अक्षर से परे — इस संबोधन से भगवान् का सर्वोत्तमत्व स्वीकृत है।",
  "11.4": "मन्यसे यदि तच्छक्यं मया द्रष्टुमिति प्रभो ।\nयोगेश्वर ततो मे त्वं दर्शयात्मानमव्ययम् ॥\n\n'यदि आप मानते हैं कि मैं उसे देख सकता हूँ — तो हे योगेश्वर, अपना अव्यय रूप दिखाइए।'\n\nयोगेश्वर — जिनकी योगशक्तियाँ अधीन हैं। भगवान् स्वयोगमाया से विश्वरूप देते हैं — साधारण नेत्र से दर्शन सम्भव नहीं।",
  "11.5": "भगवान् उवाच —\nपश्य मे पार्थ रूपाणि शतशोऽथ सहस्रशः ।\nनानाविधानि दिव्यानि नानावर्णाकृतीनि च ॥\n\n'देखो पार्थ, मेरे रूप — सैकड़ों, हजारों — नाना प्रकार के, दिव्य, नाना वर्ण-आकार वाले।'\n\nअर्जुन ने एकवचन में माँगा — भगवान् बहुवचन में देते हैं। भगवान् के सभी रूप — मूलरूप, अवतार — सब एक ही तेज में अभिन्न। नानावर्णाकृतीनि — भिन्न रूपों में एक ही तेज।",
  "11.6": "देखो — बारह आदित्य, आठ वसु, एकादश रुद्र, दोनों अश्विनी, मरुद्गण — और हे भारत, देखो बहुत-सी ऐसी अद्भुत वस्तुएँ जो पहले कभी नहीं देखीं।\n\nसमस्त देवता भगवान् के विश्वरूप की विभूतियाँ हैं। भगवान् सर्वदेवान्तर्यामी — सब देव भगवान् के नियमन में हैं। तारतम्यक्रम — बृहस्पत्यादि उत्तम — सभी भगवन्मुख से सृष्ट।",
  "11.7": "मेरे इस शरीर में — एक स्थान में — सचराचर समग्र जगत् देखो। और जो कुछ और देखना चाहो — वह भी यहीं देखो।\n\nविश्वरूपदर्शन का महिमा — समग्र जगत् भगवान् के शरीर में दीखता है। मध्वाचार्य के मत में — उस दर्शन में त्रिलोकों में सभी अर्हत् जीवों ने एकसाथ दर्शन किया।",
  "11.8": "किन्तु इन अपनी इन्हीं आँखों से मुझे देखने में समर्थ नहीं। मैं तुम्हें दिव्य चक्षु देता हूँ — मेरी ऐश्वरी योगशक्ति देखो।\n\nभगवान् स्वरूपभूत हैं — स्वरूपभूत नेत्र से ही दृश्य। बाह्यनेत्र से सूर्य का प्रकाश दीखता है, सूर्य स्वयं नहीं — वैसे ही इन्द्रियों से विभूतियाँ दीखती हैं, भगवान् ज्ञाननेत्र से।",
  "11.9": "संजय उवाच —\nहे राजन्, इस प्रकार कहकर महायोगेश्वर हरि ने पार्थ को परम ऐश्वर रूप दिखाया।\n\nसंजय — व्यास द्वारा प्रदत्त दिव्यदृष्टि से — स्वयं भी विश्वरूप देखता है, इसीलिए प्रत्यक्षदर्शी की तरह वर्णन करता है। 'महायोगेश्वर' — समस्त योगशक्तियों के ईश — यह विशेषता भगवान् की ही है।",
  "11.10": "अनेक मुख-नेत्र-आभरण-उद्यतायुध; दिव्य माल्य-अम्बर धारण किए हुए; दिव्य गन्धानुलेपन युक्त; सर्वाश्चर्यमय, अनन्त, विश्वतोमुख देव।\n\nविश्वरूप का वर्णन — अनन्त, सर्वाश्चर्यमय, विश्वतोमुख। प्रत्येक इन्द्रिय में विशेष देवता निहित हैं — उनका समागम विश्वरूप है। दिव्यमाल्य-अम्बर-गन्ध — मङ्गल के प्रतीक।",
  "11.11": "अनेकवक्त्र-नयनम्, अनेकाद्भुतदर्शनम्, अनेकदिव्याभरणम्, दिव्यानेकोद्यतायुधम् — भगवान् के प्रत्येक अङ्ग में एक-एक देवता का निवास है — यही अन्तर्यामित्व का दर्शन है।",
  "11.12": "यदि आकाश में एकसाथ हजार सूर्य उदय हों — वह प्रकाश उस महात्मा के प्रकाश के समान हो भी सकता है या नहीं।\n\nभगवान् का तेज सहस्र सूर्यों से भी अधिक — क्योंकि सूर्य का तेज भगवत्तेज से ही उत्पन्न है। ध्यानयोगी भगवान् को सहस्रसूर्यतेज के रूप में देखते हैं।",
  "11.13": "उस समय पाण्डव ने देवदेव के शरीर में अनेक प्रकार से विभक्त समग्र जगत् एकत्र देखा।\n\nमध्वाचार्य के मत में — उस विश्वरूपदर्शन के समय त्रिलोकों में सभी अर्हत् जीवों ने एकसाथ दर्शन किया — केवल अर्जुन को नहीं। 'देवदेव' — देवों के भी देव — इससे भगवान् की परमत्व सिद्ध होती है।",
  "11.14": "तब विस्मय में डूबे, रोमाञ्चित धनञ्जय ने देव को शिर से प्रणाम कर, कृताञ्जलि हुए बोले।\n\nविस्मय-हर्ष-भय-भक्ति — सभी एकसाथ। रोमाञ्चित — भक्त के भगवद्दर्शन का स्वाभाविक भाव। धनञ्जय — विश्वरूपदर्शनरूपी धन पाने वाला।",
  "11.15": "अर्जुन उवाच — हे देव, आपके शरीर में सभी देवों को, सभी भूतविशेष-समूहों को देखता हूँ। ब्रह्मा को ईश को — कमलासन पर बैठे — सभी ऋषियों को और दिव्य नागों को।\n\nब्रह्माणम् ईशम् — चतुर्मुख ब्रह्मा शिव की जाँघ पर बैठे हैं — क्योंकि शिव ब्रह्मा की जाँघ पर बैठते हैं, ब्रह्मा उनसे ऊपर। तारतम्यसहित समग्र सृष्टि का दर्शन।",
  "11.16": "अनेक बाहु-उदर-मुख-नेत्र वाले; सर्वत्र अनन्तरूप आपको देखता हूँ। हे विश्वेश्वर, हे विश्वरूप — न अन्त, न मध्य, न आदि देखता हूँ।\n\nविश्वेश्वर विश्वरूप — दोनों नामों से भगवान् की सम्पूर्णता कही। अनन्तरूप — सर्वदिशाव्यापी —",
  "11.17": "किरीटधारी, गदाधर, चक्रधर, तेजोराशि, सर्वत्र दीप्तिमान् — ज्वलदग्नि-सूर्यसम प्रभा वाले, अप्रमेय, दुर्निरीक्ष्य रूप देखता हूँ।\n\nकिरीट-गदा-चक्र — भगवान् के नित्य नाम-रूप। अप्रमेय — जिसका माप नहीं। दुर्निरीक्ष्य — जिसे सहकर देखना कठिन।",
  "11.18": "आप अक्षर परम वेदितव्य हैं। आप इस विश्व के परम आश्रय हैं। आप अव्यय शाश्वतधर्मगोप्ता हैं। आप सनातन पुरुष हैं — ऐसा मेरा मत है।\n\nप्रत्येक पद में भगवान् के सर्वोत्तमत्व को अर्जुन स्वीकार करता है। अव्यय — विकाररहित। शाश्वतधर्मगोप्ता — सनातनधर्म के रक्षक। सनातनः पुरुषः — अनादिकालसिद्ध।",
  "11.19": "आदि-मध्य-अन्तरहित, अनन्तवीर्य, अनन्तबाहु, शशि-सूर्यनेत्र — ज्वलदग्निमुख, स्वतेज से समग्र विश्व को तपाते हुए आपको देखता हूँ।\n\nअनन्तवीर्यम् — असीमित शक्ति। शशिसूर्यनेत्रम् — चन्द्र-सूर्य जिनके नेत्र। दीप्तहुताशवक्त्रम् — प्रज्वलिताग्नि-सदृश मुख। भगवान् के गुण अनन्त — किसी का माप सम्भव नहीं।",
  "11.20": "आकाश-पृथिवी के बीच का यह स्थान — तथा सभी दिशाएँ — आप अकेले से व्याप्त हैं। हे महात्मन्, आपका यह अद्भुत उग्र रूप देखकर तीनों लोक व्यथित हैं।\n\nभगवान् सर्वत्र एक — अनेक नहीं। एक का ही अनन्त व्याप्तन। उग्ररूप देखकर त्रैलोक्य में भय — किन्तु भक्त के लिए आनन्द।",
  "11.21": "ये देवसमूह आपमें प्रवेश कर रहे हैं, कुछ भयभीत होकर कृताञ्जलि से स्तुति कर रहे हैं। महर्षि-सिद्धसमूह 'स्वस्ति' कहकर पुष्कल स्तुतियों से स्तव करते हैं।\n\nभय से और भक्ति से — दोनों प्रकार का भगवद्दर्शन। पापियों के लिए उग्र, भक्तों के लिए आनन्दप्रद — एक ही रूप का द्विविध अनुभव।",
  "11.22": "रुद्र, आदित्य, वसु, साध्य, विश्वेदेव, अश्विनी, मरुत्, उष्मपा (पितर), गन्धर्व, यक्ष, असुर, सिद्धगण — सभी विस्मित होकर देख रहे हैं।\n\nसम्पूर्ण देवतारतम्य — विश्वरूपदर्शन के समय — विस्मय से खड़े हैं। तारतम्यक्रम में बृहस्पत्यादि उत्तम — सभी भगवान् के नियमनाधीन।",
  "11.23": "हे महाबाहो — आपका महान् रूप — अनेक मुख-नेत्र, बाहु-ऊरु-पाद, उदर, अनेक दंष्ट्राओं से भयानक — देखकर लोक व्यथित हैं, मैं भी।\n\nकरालम् — भयावह। अर्जुन स्वयं भी व्यथित। भगवान् के अङ्गाङ्गों में सृष्टिक्रिया — विराट्पुरुष का वर्णन — 'मुखं ब्राह्मणाः' — श्रुति के अनुसार।",
  "11.24": "आकाशस्पर्शी, दीप्त, अनेकवर्ण, व्यात्तानन, दीप्तविशालनेत्र — आपको देखकर मेरी अन्तरात्मा व्यथित है — हे विष्णो, धृति नहीं पाता, शम नहीं।\n\nअन्तरात्मा व्यथित — धृति न विन्दामि — शम नहीं। 'विष्णो' — सर्वव्यापिन् — इस संबोधन में सार्थकता — जो सर्वत्र व्याप्त उसके उग्रदर्शन से सर्वत्र भय।",
  "11.25": "कालानलसम भयावह दंष्ट्राकरालानि मुखानि देखकर — दिशाएँ नहीं जान पाता, शर्म नहीं मिलता। हे देवेश, हे जगन्निवास — प्रसन्न हों।\n\nदेवेश जगन्निवास — कृपा करें — एकमात्र शरण। नरसिंह के दंष्ट्रावली-सदृश विश्वरूप के करालमुख देखकर दिग्भ्रम। भक्त की शरणागति — 'प्रसीद' — एकमात्र।",
  "11.26": "धृतराष्ट्र के सभी पुत्र — सब राजसमूहों के साथ — आपके मुखों में प्रवेश कर रहे हैं।\n\nकाल निरपेक्ष — न कुलभेद, न पक्षभेद। भगवान् कालपुरुष — सभी को समान भाव से स्वीकार करते हैं।",
  "11.27": "भयानक दंष्ट्राकरालानि मुखों में वे त्वरा से प्रवेश कर रहे हैं। कुछ दाँतों के बीच विलग्न — चूर्णित उत्तमाङ्गों सहित दिख रहे हैं।\n\nभीष्म, द्रोण, कर्ण — युद्धमरण का पूर्वदर्शन। अर्जुन भगवान् के मुख में विनाश देखता है। यही 'काल' शब्द का यथार्थार्थ — सर्वसंहार नित्य।",
  "11.28": "जैसे नदियों के बहुत से जलवेग समुद्र की ओर ही बहते हैं — वैसे ही नरलोक के ये वीर आपके ज्वलित मुखों में प्रवेश कर रहे हैं।\n\nपुण्यजीवों की गति — भगवन्मुखप्रवेश — नदी-सागर-संगम की तरह आनन्दमय। सागर में नदी विलीन — मोक्ष में जीव भगवान् में। किन्तु मोक्ष में अभेद नहीं — जीव-भगवान् भेद नित्य (द्वैत-मत)।",
  "11.29": "जैसे पतंगे प्रदीप्त ज्वाला में नाश के लिए वेग से प्रवेश करते हैं — वैसे ही लोग भी नाश के लिए आपके मुखों में प्रवेश कर रहे हैं।\n\nपतंगे भय से नहीं — आकर्षण से अग्नि में जाते हैं। पापी भी भय से नहीं — कर्मफल से भगवन्मुख में जाते हैं। प्रारब्धकर्म के नाश के लिए जीव भगवन्मुख में — यही काल का स्वरूप।",
  "11.30": "ज्वलित मुखों से सब ओर से समग्र लोकों को ग्रसते हुए चाट रहे हैं। आपका उग्र तेज जगत् को तेज से भरकर प्रतप रहा है — हे विष्णो।\n\nविष्णो — सर्वव्यापिन् — आपकी दीप्ति विश्व को जला सकती है। प्रलयकाल — भगवान् सब संहरते हैं — नई सृष्टि के लिए।",
  "11.31": "मुझे बताइए — आप कौन हैं, इस उग्ररूप में? हे देववर, आपको नमस्कार। प्रसन्न हों। आदिपुरुष आपको जानना चाहता हूँ — आपकी प्रवृत्ति नहीं समझ पाता।\n\nभय-भक्ति-आनन्द-मिश्रित अर्जुन का सरल प्रश्न — 'आपका उद्देश्य क्या है?' भगवान् काल हैं — उत्तर देंगे।",
  "11.32": "भगवान् उवाच —\nकाल हूँ मैं — लोकों को क्षय करने वाला, प्रवृद्ध। लोकों को समेटने के लिए यहाँ प्रवृत्त हूँ। आपके बिना भी — इन प्रत्यनीक-स्थित सभी योद्धाओं का होना नहीं होगा।\n\n'काल' — 'कल' धातु — सर्वसंचालक, सर्वसमाहर्ता। भगवान् कालपुरुष — नित्यप्रवृत्त। भगवान् ने निर्धारित किया — अर्जुन निमित्तमात्र।",
  "11.33": "इसलिए उठो — यश प्राप्त करो। शत्रुओं को जीतकर समृद्ध राज्य भोगो। मैंने ही इन्हें पहले से मार दिया है — हे सव्यसाचिन्, निमित्तमात्र बनो।\n\nसव्यसाचिन् — उभय हस्त कुशल धनुर्धर। भगवान् का निर्णय पूर्वसिद्ध — युद्ध भगवत्कार्य — अर्जुन केवल माध्यम।",
  "11.34": "द्रोण, भीष्म, जयद्रथ, कर्ण — तथा अन्य योधवीरों को — मेरे द्वारा हत — आप मारो। विक्षुब्ध न हों — युद्ध करो — रण में शत्रुओं को जीतोगे।\n\nमेरे द्वारा हत — अर्जुन केवल भौतिकसाधन। जिनका मरण निश्चित — उन्हें मारने में पाप नहीं — क्योंकि जीव अविनाशी (BG 2.19)।",
  "11.35": "संजय उवाच — केशव का वचन सुनकर, कृताञ्जलि कँपते किरीटी ने, नमस्कार करके — सगद्गद, भीतभीत, प्रणाम करके — पुनः कृष्ण से बोले।\n\nगद्गद — कण्ठरोध से। भीतभीत — भयभक्तिमिश्रित। किरीटी — मुकुटधारी महावीर — भगवत्समक्ष नतमस्तक।",
  "11.36": "अर्जुन उवाच — हे हृषीकेश, यह उचित है कि आपके कीर्तन से जगत् हर्षित और अनुरक्त होता है। राक्षस भयभीत होकर दिशाओं में भागते हैं — सभी सिद्धसमूह नमस्कार करते हैं।\n\nहृषीकेश — इन्द्रियों के स्वामिन् — इस संबोधन में सार्थकता। मध्वाचार्य के मत में — विश्वरूपदर्शन के समय त्रिलोकों में सभी अर्हत् जीवों ने एकसाथ दर्शन किया — इसीलिए सिद्धसमूह का नमस्कार।",
  "11.37": "हे महात्मन्, वे आपको क्यों न नमें — ब्रह्मा से भी श्रेष्ठ, आदिकर्ता को? हे अनन्त देवेश जगन्निवास — आप अक्षर, सत्-असत्, और उससे भी परे।\n\nआदिकर्त्रे — जिनसे ब्रह्मा भी उत्पन्न, उन्हें। ब्रह्मा से भी श्रेष्ठ — ब्रह्मा की शक्ति भगवत्सामर्थ्य को नहीं जीत सकती। सत्-असत् परम — व्यक्त-अव्यक्त से परे।",
  "11.38": "आप आदिदेव, पुराणपुरुष, इस विश्व के परम आश्रय। वेत्ता और वेद्य दोनों। परम धाम। हे अनन्तरूप, आप से यह विश्व व्याप्त है।\n\nआदिदेव — देवों के देव। पुराणपुरुष — सनातन। वेत्ता वेद्यश्च — ज्ञाता और ज्ञेय दोनों। अर्जुन उत्तरोत्तर भगवद्गुणों का अनुभव करते हुए स्तुति करता है।",
  "11.39": "वायु, यम, अग्नि, वरुण, शशाङ्क, प्रजापति — आप ही हैं। प्रपितामह भी आप। हजार बार नमः, पुनः-पुनः नमः नमः।\n\nवायु = बल-ज्ञानरूप; यम = नियन्ता; अग्नि = गतिप्रद; वरुण = भक्तवरेण्य; शशाङ्क = आनन्दस्वरूप। प्रत्येक नाम में भगवन्नामार्थ। सहस्रकृत्वः — बार-बार, अनगिनत बार।",
  "11.40": "आगे से नमः, पीछे से नमः — हे सर्व, सर्वतः नमः। हे अनन्तवीर्य अमितविक्रम — आप सब में व्याप्त हैं, इसलिए आप ही सब हैं।\n\nसर्वतः नमः — भगवान् सर्वत्र हैं — इसीलिए सर्वदिशाओं से नमस्कार। 'ततः असि सर्वः' — इसीलिए आप ही सब हैं — विश्वरूप का सार।",
  "11.41": "आपके माहात्म्य को न जानते हुए — प्रमाद से या प्रेम से — 'हे कृष्ण हे यादव हे सखे' — ऐसा जो कुछ आग्रहपूर्वक मैंने कहा, और विहार-शय्या-आसन-भोजन में — एकान्त में या सामने — जो अवहेलना की — हे अप्रमेय अच्युत — उन सबके लिए क्षमायाचना करता हूँ।\n\nपिता-पुत्र, सखि-सखि, प्रिय-प्रिया — तीन सम्बन्धों का उल्लेख कर क्षमायाचना। भगवत्सम्बन्ध तीन प्रकार का हो सकता है।",
  "11.42": "हे चर-अचर जगत् के पिता — पूज्य, गुरु, सबसे श्रेष्ठ गुरु। तीनों लोकों में न तुल्य, न अभ्यधिक — हे अप्रतिमप्रभाव।\n\nसभी गुरु ज्ञान देते हैं — भगवान् तो अज्ञान को ही नष्ट करते हैं और स्वयं ज्ञानस्वरूप हैं — इसीलिए गुरुर्गरीयान्।",
  "11.43": "इसलिए प्रणाम करके, काया झुकाकर — ईश, ईड्य आपको प्रसन्न करता हूँ। हे देव — जैसे पिता पुत्र की, सखा सखा की, प्रिय प्रिया की — वैसे ही क्षमा करने योग्य हैं आप।\n\nतीन सम्बन्धों से क्षमायाचना। भगवान् सभी भावों में आश्रय देते हैं — पिता की तरह, मित्र की तरह, प्रेमी की तरह।",
  "11.44": "जो पहले कभी नहीं देखा, उसे देखकर हर्षित हूँ — और भय से मन व्यथित भी है। हे देव, वही रूप दिखाइए। हे देवेश जगन्निवास — प्रसन्न हों।\n\nआनन्द और भय एकसाथ। देव — वही पूर्वपरिचित रूप दिखाइए। जगन्निवास — सर्वत्र निवासी — देवेश — प्रसन्न हों।",
  "11.45": "किरीटधारी, गदाधर, चक्रहस्त — आपको उसी रूप में देखना चाहता हूँ। हे सहस्रबाहो, हे विश्वमूर्ते — चतुर्भुज रूप धारण करें।\n\nसहस्रबाहु रूप देखकर — चतुर्भुज रूप की इच्छा। भक्त का हृदय — उग्र से नहीं — सौम्य भगवद्दर्शन चाहता है।",
  "11.46": "भगवान् उवाच — हे अर्जुन, मेरे प्रसन्न होने से आत्मयोग से यह परम रूप — तेजोमय, विश्वमय, अनन्त, आद्य — जो तुम्हारे अतिरिक्त किसी ने पहले नहीं देखा — दिखाया।\n\nमया प्रसन्नेन — भगवान् के प्रसाद से — न अन्य किसी प्रयत्न से — विश्वरूप मिलता है। अर्जुन एकमात्र — इस दर्शन से कृतार्थ।",
  "11.47": "वेदाध्ययन, यज्ञ, दान, क्रिया, उग्रतप — किसी से भी इस प्रकार का रूप मनुष्यलोक में तुम्हारे अतिरिक्त किसी ने नहीं देखा — हे कुरुप्रवीर।\n\nभगवद्भक्ति ही — न अन्यकोई साधन — इस दर्शन का हेतु। वेद-यज्ञ-दान-तप ये सब अप्रत्यक्ष साधन — प्रत्यक्ष भक्ति ही परमसाधन।",
  "11.48": "मेरे इस भयावह रूप को देखकर व्यथित न हों — विमूढ़भाव न करें। भयरहित, प्रसन्नमनस् होकर — वही मेरा वह रूप पुनः देखें।\n\nभगवान् करुणालु — अर्जुन का भय देखकर सान्त्वना देते हैं। प्रीतमनाः — आनन्दित मन से — पुनः भगवद्दर्शन।",
  "11.49": "संजय उवाच — वासुदेव ने यह कहकर अर्जुन को अपना कृष्णरूप दिखाया। महात्मा ने पुनः सौम्यवपु धारण कर भयभीत को आश्वासन दिया।\n\nमहात्मा वासुदेव — सौम्यरूपधारी — अर्जुन को आश्वस्त करते हैं। वासुदेव — वसुदेवपुत्र — किन्तु अर्थ — सर्वत्र वासुदेव।",
  "11.50": "अर्जुन उवाच — हे जनार्दन, आपका यह सौम्य मानुष रूप देखकर अब चेतन हो गया हूँ, स्वाभाविक स्थिति में आ गया हूँ।\n\nजनार्दन — जन-अर्दन — सब पापों का नाशक। सौम्यरूप देखकर चेतन। प्रकृतिं गतः — स्वाभाविक स्थिति प्राप्त। उग्रदर्शनजनित भय — सौम्यरूप से दूर।",
  "11.51": "भगवान् उवाच — यह रूप जो तुमने देखा — सुदुर्दर्शम् — देवता भी इसके नित्य दर्शन की कामना करते हैं।\n\nन वेदों से, न तप से, न दान से, न यज्ञ से — ऐसा दर्शन सम्भव नहीं — जैसा तुमने मुझे देखा।\n\nअर्जुन ने जो पाया — देवता भी चाहते हैं। भगवद्भक्ति ही एकमात्र — विश्वरूपदर्शन का हेतु — यही विश्वरूपाध्याय का सार।",
  "11.52": "[बन्नञ्जे के अध्याय 11 में कुल 35 श्लोक हैं। यह प्रविष्टि OCR-त्रुटि से उत्पन्न। 11.51 के साथ ही अध्याय 11 का समापन होता है।]",
  "11.53": "भगवान् उवाच —\nसुदुर्दर्शमिदं रूपं दृष्टवानसि यन्मम ।\nदेवा अपि अस्य रूपस्य नित्यं दर्शनकाङ्क्षिणः ॥\nन अहं वेदैः न तपसा न दानेन न च इज्यया ।\nशक्यः एवंविधः द्रष्टुम् दृष्टवान् असि मां यथा ॥\n\n'जो मेरा रूप तुमने देखा — वह सुदुर्दर्शम् है। देवता भी इस रूप को सदा देखने की कामना करते हैं। वेदों से, तपस्या से, दान से, यज्ञ से — ऐसा दर्शन सम्भव नहीं जैसा तुमने देखा।'",
  "11.54": "अनन्या भक्त्या — इस प्रकार — ज्ञातुं, द्रष्टुं, तत्त्वेन प्रवेष्टुं — शक्यः हूँ।\n\nपरंतप — तीन शक्तियाँ — ज्ञान, दर्शन, प्रवेश (मोक्ष) — अनन्यभक्ति से ही। यही विश्वरूपाध्याय का सार।",
  "11.55": "मत्कर्मकृत्, मत्परम, मद्भक्त, सङ्गवर्जित, सर्वभूतेषु निर्वैर — जो ऐसा है वह मुझे प्राप्त होता है।\n\nपाँच लक्षण — (१) भगवत्कार्यरत; (२) भगवान् ही परम; (३) अनन्यभक्ति; (४) अनासक्ति; (५) सर्वभूतों में द्वेषरहित। ये पाँच विश्वरूपयोग का, गीता का निष्कर्ष हैं।",
  "12.1": "अर्जुन उवाच - अर्जुन ने पूछा:\n\nएवं सचदा युक्तः ये भक्तः त्वम् पर्युपासते।\n\nये च अपि अक्षरं अव्यक्तं तेषाम् के योगवित्तमः - इस प्रकार निरंतर प्राप्ति से\nजो लोग आपकी सेवा करते हैं वे अविनाशी निर्वैयक्तिकता (श्रत्व) के भक्त और उपासक हैं। उनमें से कौन\nउनमें से अधिकांश.\n\nइसके मुख पर यह श्लोक भगवान की पूजा का एक विशिष्ट रूप है और नहीं\nनिराकार भगवान की पूजा करना जो रूपों से प्रकट नहीं होता है - दोनों में से क्या उचित है\n\nसुना हुआ लगता है. लेकिन इस श्लोक में अर्जुन जो मूल प्रश्न पूछ रहा है वह अलग है। यह\nमाधवाचार्य ने इसका अनोखा वर्णन किया है।\n\nवे सभी जो ईश्वर के बारे में सोचते हैं, जरूरी नहीं कि वे ईश्वर के भक्त हों...भगवान के बारे में सोचते हों\nकरने के लिए आवश्यक घटक प्रेम है। ज्ञानमय प्रेम ही भक्ति है। पूर्व समय में\nसबके घर में भगवान के कमरे में एक मूर्ति होती थी. जो उनकी पूजा के लिए है\nइष्ट, इष्टदेवता की मूर्ति है। अगर हम इस पहलू का विश्लेषण करें कि मूर्ति ऐसी क्यों है\nज्ञात होता है कि वे इसकी पूजा करते थे। यहां सबसे पहले हम इस पर काम करते हैं कि हमारा दिमाग कैसे काम करता है\nआपको करने का विचार जानने की आवश्यकता है। आँखें जो देखती हैं, उसे मन नहीं समझता।\nउदाहरण के लिए, यदि हम यह जानते हुए कि ईश्वर 'सबसे सुंदर' है, अपनी आँखें बंद करके ध्यान में बैठ जाते हैं\nमन हमें वह सुन्दर चीज़ दिखाता है जो हमने देखी है! इसके लिए\nपूर्व भगवान में हमारे जैसे गुण हैं, लेकिन वह किसी इंसान की तरह नहीं हैं\nउन्होंने अपनी मूर्ति नहीं देखी. इस मूर्ति का स्मरण करें और अपनी आँखें बंद कर लें\nयदि हम ईश्वर के गुणों का ध्यान करेंगे तो हमें केवल वह मूर्ति ही दिखाई देगी, अपनी नहीं\nकोई परिचित नहीं. इससे ध्यान करना आसान हो जाता है। मन एक व्यक्ति है\nव्यक्ति निश्चिंत होकर भगवान को मूर्ति के रूप में देखना शुरू कर देता है। इस कारण प्रभु\nसोच को एक रूप की आवश्यकता होती है।\n\nजैसा कि हम जानते हैं माता श्री लक्ष्मी को श्रीतत्व, अक्षरा, अव्यक्त, प्रकृति, ह्री आदि नामों से जाना जाता है।\nनाम से पुकारा गया. भगवद्गीता में ही इस प्रकार का सम्बोधन अनेक स्थानों पर मिलता है।\nजैसा कि कठोपनिषद में कहा गया है \"महतः परमव्यक्तमव्यक्तत्पुरुषः परः\"। अर्थात् महत्व के बजाय\nभगवान् पुरुष अव्यक्त तत्त्व से श्रेष्ठ हैं। यहाँ स्पष्ट रूप से हमारे लिए है\nज्ञातव्य है कि माता श्री लक्ष्मी अदृश्य, अक्षरा हैं।\n\nआपने शास्त्रों के द्वारा जो अपने गुण बताये हैं, उनका मन में निरन्तर चिन्तन करते रहना\nआपके विशेष रूप की महिमा को जानकर और उसके प्रति भक्ति विकसित करके\nपूजा करना अच्छा है; अथवा श्रीतत्त्व जो कि क्षरातीत (अक्षर) है) की पूजा करना अच्छा है।\nअर्जुन का प्रश्न है कि कौन सा मार्ग सर्वोत्तम है।",
  "12.2": "भगवान उवाच- भगवान ने कहा:\n\nमाई आवेश्य मनः ये माम् नित्य युक्तः उपासते।\n\nश्रद्धया पराया उपेतः ते मेय युक्तः तमः मतः - जिन्होंने मुझमें भर दिया, भर दो\nविश्वास के साथ. खुद को खपा रहा हूं. लगातार उपलब्धियां हासिल करने वाले-सबसे उत्तम\nविचार किया जाएगा.\n\nअर्जुन के प्रश्न का उत्तर देते हुए, कृष्ण कहते हैं: “जो सच्चे मन से मेरी पूजा करता है\nजो लोग ऐसा करते हैं, वे भगवान के सबसे महान साधक हैं। यहां परिश्रम का अर्थ विश्वास है।\nउपलब्धि में परिश्रम का बहुत महत्व है। बिना भक्ति के पूजा करने से कोई लाभ नहीं है। ये है\nमनोविज्ञान इसका एक सांसारिक उदाहरण: रोगी और चिकित्सक। यदि रोगी स्व\nयदि आपको उस डॉक्टर पर भरोसा नहीं है जो जांच करता है और दवा लिखता है, तो आपके द्वारा ली गई दवा उस पर काम नहीं करती है\nनहीं करता अगर गहरी आस्था हो - डॉक्टर जो भी दवा लिखे वह बीमारी है\nयह ठीक हो जाएगा! ये वैज्ञानिक तौर पर भी सिद्ध है. तो बस अपनी आँखें बंद करो-\nबिना आस्था के पूजा व्यर्थ है। दृढ़ निष्ठा के साथ, भगवान को जानकर\nगुणरूप का ध्यान करना सबसे बड़ी भक्ति है। पूरी ईमानदारी से, किसी भी रूप में,\nभगवान की पूजा किसी भी नाम से की जा सकती है। भगवान का अरूप\nऐसा कोई रूप, कोई नाम नहीं जो भगवान का नाम न हो। नाम-रूप जब पूर्ण ध्यान हो\nकोई समस्या नहीं. इस प्रकार भगवान कहते हैं: “जो मेरा रूप और चरित्र विशेष है\nजो सच्चे दिल से पूजा करता है, वह सबसे महान सिद्धियों में से एक है।\n\nये त्वाक्षरमनिर्देश्यमविकथाम् पर्युपासते।\nसर्वत्रगमाचिन्त्यं च कूटस्थमाचलं ध्रुवम् 13\n\nसन्नि यमेन्द्रियग्रामं सर्वत्र समबुद्धयः |\nते प्राप्नुवन्ति मामेव सर्वभूतहिते रतः ॥4॥",
  "12.3": "येतु अक्षरं अनिरदेश्यं अव्यक्तं पर्युपासते।\n\nसर्वत्रगं अचिन्त्यं च कुतस्थं अचलं ध्रुवम् ॥",
  "12.4": "भगवान ने इस दुनिया की रचना की और पंद्रह बाड़ों के इस संसार में जीवन रखा। यह\nपंद्रह बाड़ें हैं:\n\n1. परिश्रम की बाड़: वह बाड़ जिसे हटाया नहीं जा सकता- परिश्रम जो जीवन के स्वभाव से आता है। और नंगा किया जाना है\nएक बाड़-रेखा परिवार, ईमानदारी जो उस वातावरण के प्रभाव से आई जिसमें वह बड़ा हुआ।\n\n2-6. पंचभूतों की बाड़: पृथ्वी-जल (अन्नमय कोष) अग्नि-वायु-आकाश (प्राणमय कोष)।\n7. इंद्रियों की बाड़: पांच ज्ञानेंद्रियां और पांच कर्मंद्रियां।\n\n8. डराने-धमकाने की बाड़: ऐसा दिमाग जो बुरा सोचता है\n\n9. धान की बाड़: भोजन\n\n10. शुक्राणु बाड़: ताकत\n\n11. तप: यह विचार कि यह वैसा ही होना चाहिए (जैसा कि थिरुका के सपने में था)।\n\n12. मंत्र: किसी के सपने को साकार करने का मंत्र।\n\n13. कर्मः : सपने को प्राप्त करने के लिए किया गया कर्म।\n\n14. संसार: स्टिरा-चारा संपत्ति (मैंने बनाई है, संपत्ति जो मेरी है)\n\n15. नमदा बेली : कीर्ति(Reputation)।\n\nइन पंद्रह बाड़ों के अंदर फंसा हुआ सोलहवां “क्षर” जीवन के लिए उपरोक्त है\nलक्ष्मी चित प्रकृति का सत्रहवाँ रूप हैं जिन्हें बेली नामक कमीज पहनाकर इस संसार में भेजा गया है। वह है\nविद्वान पुरुष. अक्षरों से परे भगवान अठारहवें पुरुष हैं। वह है\nमर्दाना गीता में अब तक भगवान ने जिस मुख्य बात पर जोर दिया है वह यही है\n\"जो भक्तिपूर्वक मेरी पूजा करता है वह इस संसारबंध से मुक्त हो जाएगा और मुझसे जुड़ जाएगा।\"\nयहाँ जो प्रश्न हमारे सामने आता है वह यह है - सत्रहवाँ श्रीतत्त्व, भगवान से क्यों छूट गया है\nपूजा नहीं करनी चाहिए? माँ पिता से भी अधिक दयालु होती है। वह माँ जिसने हमें विवाह के बंधन में बाँधा\nक्या पूजा करने से हमारा उद्धार आसान नहीं हो जाता? कौन सा तरीका अधिक उपयुक्त है? -यह है\n\nएक सामान्य प्रश्न जो हर किसी के मन में आता है। स्तुति में कहा गया है कि श्रीतत्त्व की आराधना से मुक्ति संभव है\nऐसा कहा गया है. उदाहरण के लिए, यह तब कहा जाता है जब मंगलारती के दौरान सभी लोग भगवान की पूजा करते हैं और इसका पाठ करते हैं\nनिम्नलिखित श्रीसूक्त पंक्तियाँ:\n\nश्री जात: श्री अनिरयः श्रेयं व्यो जनित्रभ्योद्दधातु |\nश्रीयं वासनाः अमृतत्वमयां भजंति सद्यस्समिधा मिथद्यौं ||\n\nजैसा कि यहां कहा गया है: \"श्रीतत्व की पूजा करने के लिए हमारा जन्म हुआ है। श्रीतत्व।\"\nवह उपासक को धन और साहस प्रदान करती हैं। श्रीतत्त्व उपासना\nजिन्होंने अमरत्व प्राप्त किया। जैसे दम्पति श्रीतत्त्व की पूजा करते हैं\nइच्छा पूरी होगी. वह मुक्तिवादी है”।\nइससे स्पष्ट है कि मोक्ष भी मिल सकता है। भगवान पुरूषोत्तम की पूजा और\nश्रीतत्व या अक्षर उपासना इनमें से कौन सी विधि अधिक उपयुक्त है? यह यहां हम सभी के लिए एक प्रश्न है।\nयह अध्याय हमारे प्रतिनिधि अर्जुन द्वारा भगवान के समक्ष हमारा प्रश्न रखने से संबंधित है\nशुरू होता है. दूसरे शतक के अंतिम अध्याय में केवल बीस श्लोक हैं। अध्याय\nयद्यपि संक्षिप्त, यह अध्याय असाधारण सामग्री वाला अध्याय है। भगवान यहाँ हैं\nयदि हम बताए गए विचारों को अपने जीवन में अपना लें तो हमारा जीवन सार्थक हो जाएगा।\nआइये जानते हैं इस अध्याय में उल्लिखित अद्वितीय गुण-भक्ति संदेश।\n",
  "12.5": "क्लेश अधिक तारः तेषाम् अव्यक्त असक्त चेतसाम् |\nअव्यक्त हि गतिः दुःखं देहवद्लिह अवप्यते - उन लोगों के लिए जो निर्वैयक्तिकता की पूजा की सराहना करते हैं।\nथकान अधिक है. अव्यक्त के माध्यम से मुक्ति का मार्ग अभ्यासी के लिए एक कठिन चक्कर है।\n\nवह शक्ति की पूजा करने वालों को मोक्ष प्रदान करती हैं। लेकिन पूजा अदृश्य की\n\"अधिक तारा क्लेश:\" करने वालों के लिए उपासना बहुत कठिन है। यह सीधा रास्ता छोड़ देती है।\nजैसे चक्कर लगाकर भगवान तक यात्रा करना। अभ्यासकर्ताओं को इसे बड़ी कठिनाई से प्राप्त करना पड़ता है।\n\nनिम्नलिखित श्लोकों में, कृष्ण बताते हैं कि सीधे भगवान की पूजा करना कितना आसान है।\nयह भगवान द्वारा हमें दिखाया गया भक्ति का आसान मार्ग है।",
  "12.6": "परंतु जो मेरे परायण होकर, सब कर्मों को मुझमें समर्पित करके, अनन्य भक्ति-योग से मेरा ध्यान करते हुए मेरी उपासना करते हैं —\n\nयह सगुण भक्ति का स्वरूप है। 'सर्वाणि कर्माणि मयि संन्यस्य' — सब कर्मों को मुझमें समर्पित करके। 'अनन्येनैव योगेन' — अनन्य योग से। 'मां ध्यायन्तः' — मेरा ध्यान करते हुए। यह भक्त की परम स्थिति है।",
  "12.7": "ये तु सर्वाणि कर्माणि मयि संन्यास मत परः |\n\nअनन्येन एव योगेन मां ध्यानतः उपासते ॥\n\nतेषाम् अहं समुद्धर्ता मृत्यु संसार सागरत्।\n\nभवामि नचिरत पार्थ मय्यावेशिताचेतासम् - कुछ हैं: वे सभी मुझमें किए गए हैं।\n\n1\n\nप्रस्ताव देंगे. उन्होंने ही मुझे बनाया है. उनकी उपलब्धि का लक्ष्य कोई और नहीं बल्कि मैं हूं। मेरी बहन 6 साल की है\n\nभिगोकर सेवन किया जाता है। हे पार्थ, जो लोग मुझे प्रिय हैं, मैं उन्हें शीघ्र ही मार डालूँगा\nसमुद्र से मुक्त हुआ.\n\nकृष्ण कहते हैं: “मुझसे जुड़ने का सबसे आसान साधन है- तुम जीने के लिए क्या हो\nयदि आप कार्रवाई कर रहे हैं, तो इसे मुझे पेश करें। यहां कृष्ण जो कह रहे हैं, वह हम हैं\nप्रत्येक कार्य के पीछे जो दृष्टिकोण होना चाहिए, प्रभु ने यह कार्य मुझे दिया है\nबना दिया - यही निष्कर्ष है कि वे अवतरित हैं। जब हम ऐसे हैं, तो हम परमेश्वर के हैं\nपुर्हनुग्रह को सौंपा जा सकता है। यहां हमें सबसे महत्वपूर्ण चीज़ ईश्वर की आवश्यकता है\nअनन्य भक्तिभाव से पूजा करते हैं। हमारी उपलब्धि, भावना में कमी हो सकती है\nदमन चाहे जितना कठिन हो, सार्वभौमिक परोपकार। शायद नहीं, विचार में\nचूक हो सकती है, एकाग्रता की कमी हो सकती है. लेकिन यहाँ कृष्ण का वचन है\n\"मेरे प्रति समर्पण करो, अपना मन मुझ पर केन्द्रित करो - मैं तुम्हें ऊपर उठाऊंगा।\" हमारा\nजब भगवान मन में स्थापित हो जाते हैं, तो भगवान हमें जन्म और मृत्यु के इस सागर से मुक्त कर देते हैं\nबचाव के लिए जिम्मेदार.",
  "12.8": "मयि एव मनः अधातश्री मयि बुद्धिम निवेशाय।\nनिवसिष्यसि मयि एव अतः उर्ध्वं न संशयः - मुझे बताओ। मुझमें प्रकाश रखो.\nपरिणामस्वरूप, मैं अपने आप में स्थापित हो जाऊँगा। इसके बारे में कोई संदेह नहीं है।\n\nकृष्ण कहते हैं: अपने मन को मुझमें स्थिर करो। \"आधना\" का अर्थ है बीज बोना या\nस्पार्किंग मन को भगवान की भक्ति की चिंगारी से प्रज्वलित कर चमकाना चाहिए। भक्तिपूर्ण\nबीज को विकसित होने के लिए पोषित करना चाहिए। निश्चययज्ञ को बुद्धि में सुदृढ़ करना चाहिए। हमेशा ऐसा ही मन रखो\nभगवान में स्थापित होने पर व्यक्ति बिना किसी कष्ट के भगवान से जुड़ सकता है। यह शक्ति है\nईश्वर की आराधना उपासना से कितनी अधिक सरल है, इसकी व्याख्या। प्रभु की आराधना करना\nनियामक प्रतिबंध बहुत कम है. उदाहरण के लिए विष्णुसहस्रनाम पारायण। विष्णुसहस्रनाम\nचिंतन के लिए कोई निश्चित समय सीमा नहीं है। किसी भी समय कोई भी\nविष्णुसहस्रनाम का पाठ कर सकते हैं। विष्णुसहस्रनाम सभी रोगों का इलाज है। भगवान के विचार में\nअनजाने में हुई चूक क्षमा योग्य है।\n\nनारायण की पूजा का अर्थ है लक्ष्मी के साथ नारायण की पूजा। नारायण\nउपासकों को लक्ष्मी और अन्य देवताओं की अलग-अलग पूजा करने की आवश्यकता नहीं है।\nलक्ष्मी और सभी देवताओं को जो सबसे प्रिय है वह भगवान की पूजा है। नारायण\nसभी देवता साधक को उसके साधना पथ में सहायता करें\nहमें ऊँचा उठाता है... जब हम यह जान लेते हैं तो हम अपनी आराधना में सहज हो जाते हैं\nएकता हासिल की जा सकती है. भक्ति को इस तरह से मजबूत किया जा सकता है।",
  "12.9": "अथ चित्तं समाधातुम् शक्नोशि मयि स्थिरम्।\n\nअभियोगसेना तथा मम इच्छा आपटू डेंजया - धनंजय, एक बार मुझमें\nयदि आंतरिक भाग को सख्त करना संभव नहीं है, तो सैंडिंग के अभ्यास का उपयोग करें\nअपनेपन की इच्छा पैदा करें।\n\nमन में प्रभु भक्ति है, बुद्धि में प्रबुद्ध भक्ति का अंकुर है। फिर भी\nजब स्थिर स्मृति न आ रही हो, मन स्थिर न हो तो क्या करें? शास्त्र में\nजैसा कि कहा गया है:\n\nस्मार्टव्यः सदाचं विष्णुः विस्मर्तव्यो न जातुचित् |\nसर्वे विधि निषेधस्स्युह एतयोरेव किंकरः ॥\n\nइसका अर्थ है 'हमें सदैव भगवान को याद रखना चाहिए, भगवान को कभी नहीं भूलना चाहिए।'\nसभी निषेध भी यही कहते हैं। इस अखंड प्रभु में मन नहीं रुकता\nस्मृति संभव नहीं है. कृष्णा बताते हैं कि ऐसी स्थिति में क्या करना चाहिए।\n“प्रार्थना करें कि आप मुझे मन को एकाग्रता में लाने की शक्ति दें।\nकृष्ण का वचन है कि मार्ग में वह जो भी इच्छा करेगा उसे पूरा करने का उत्तरदायित्व मेरा है।\nयदि अभ्यास और इच्छाशक्ति हो तो एकाग्रता अवश्य संभव है। हम बच्चों को कैसे प्रशिक्षित करें?\n\nबीआर\n\nइसका अभ्यास करें. यदि आप सिखाते हैं, तो हमारे मन को प्रसन्न करें और हमें ज्ञान बताएं\nअभ्यास करना चाहिए. जब आप ऐसा करते हैं तो मन एक आदत बन जाता है। पहले हम\nसांसारिक. धन के पीछे भागना बंद करो और भगवान का अनमोल खजाना जीतो\n\nआभारी होना।",
  "12.10": "आदतें अपि असमार्थः असि मत कर्म परमः भवः।\nमत अर्थं अपि कर्माणि कुर्वान सिद्धिं अवप्स्यसि च - यदि ध्यान भी असंभव है, तो मेरा\nपूजा-पाठ के कार्यों में शामिल हों. कर्म को मेरी पूजा समझो...\n\nहासिल किया जा सकता है।\n\nकुछ लोगों के पास कितना भी अभ्यास हो, एकभक्ति संभव नहीं है। आध्यात्मिक पथ की प्राप्ति में\nमन के लिए एक जन्म का अभ्यास पर्याप्त नहीं है। हालाँकि कभी-कभी पूरे जन्म का अभ्यास किया जाता है\nएकाग्रता नहीं आ पाती. दयालु कृष्ण उनसे कहते हैं: “आप जो कर्म करते हैं\nइसे स्वार्थ के लिए मत करो, इसे भगवान की पूजा करने के इरादे से करो।” उसका दैनिक\nप्रत्येक कार्य को भगवान की पूजा के रूप में भक्तिपूर्वक करें, आध्यात्मिक मार्ग में सिद्धि प्राप्त करें\nमिल सकता है\n\nअथैतादप्यशक्तो$च कर्तुम मदयोगमाश्रितः |\n\nसर्वकर्मफलत्यागं ततः कुरु यतात्मवान्",
  "12.11": "अथ एतत् अपि अशक्तः असि कर्तुम् मत योगम् आश्रितः |\n\nसर्वकर्म फल त्यागम् ततः कुरु यत् आत्मवान् - यदि ऐसा नहीं किया जाता तो सभी प्रकार के\nमुझे भी कर्म अर्पण करने का पराक्रम करो। फिर सब कर्मों का मार्ग कड़ा करो\nनिष्फलता का त्याग करें।\n\nयदि ऊपर बताए अनुसार सभी कर्म भगवान को अर्पित करना संभव नहीं है,\nयदि हर चीज़ को भगवान की पूजा के रूप में करना संभव नहीं है, तो किसी की पूजा करें - लेकिन\nअंत में, कृष्ण कहते हैं कि कर्म की इच्छा किए बिना सभी कर्म भगवान को अर्पित कर दो। यहाँ\nकृष्ण ने कर्मफल के त्याग और अर्पण पर जोर दिया।",
  "12.12": "श्रेयः हि ज्ञानं हैभयत् ज्ञानात ध्यानं विशिष्यते |\n\nध्यानथ कर्म फल त्यागः त्यागत शांतिः अनन्तरम् - जागरूकता अचेतन अभ्यास से कहीं अधिक है।\nखोखला ज्ञान जानने से बेहतर है जानना और मनन करना। कर्मफल रहित ध्यान खाली ध्यान से बेहतर है\nअधिशेष ऐसे ध्यान का अगला चरण मुक्ति है।\n\nबिना ज्ञान के ध्यान से ज्ञान बेहतर है। ज्ञान की आध्यात्मिक प्राप्ति में। बुनियादी\nआवश्यकता है (आधारशिला). ज्ञान के बिना ध्यान या कर्म करना व्यर्थ है।\nबिना समझे किया गया परिश्रम अंध परिश्रम बन जाता है। इसी प्रकार श्रद्धा के बिना समझ अहंकार है।\nतो आपको जानना होगा, आपको जानना होगा और विश्वास करना होगा। केवल समझ ही पर्याप्त नहीं है. ज्ञान के बजाय ज्ञान के साथ\nध्यान पर. सबसे उत्तम कर्म का त्याग है। तो पहले जानें, जानें और अभ्यास करें\nलेकिन अपने ध्यान को कर्म-मुक्त ध्यान बनने दो। इस तरह की जीवन शैली से\nगर्भपात संभव है.\n\nकृष्ण ने बताया कि भगवान की पूजा अब तक कैसी होनी चाहिए, फिर तो हम भगवान हैं\nयदि हम प्रशंसा का जीवन जीना चाहते हैं तो हमें अपने जीवन को कैसा आकार देना चाहिए\n\nबताते हैं कि पाठ्यक्रम और क्रियान्वयन कैसा होना चाहिए।",
  "12.13": "जो सब भूतों में द्वेषरहित, मित्र और दयालु है, ममता और अहंकार से रहित, दुख-सुख में सम और क्षमावान है —\n\nयहाँ से गीता में भगवान के 'प्रिय भक्त' के लक्षणों का वर्णन करने वाली श्रृंखला शुरू होती है। 'अद्वेष्टा' — किसी से द्वेष न करना। 'मैत्रः करुणः' — मैत्री और करुणा। 'निर्ममः निरहंकारः' — ममता और अहंकार से रहित होना।",
  "12.14": "अद्वेष्टा सर्वभूतानां मैत्रः करुणाः एव च।\n\nनिर्ममः निरहंकारः समदुःखसुखः क्षमी॥\n\nसन्तुष्टः सदथं योगी यतात्मा ।\n\nमयि अर्पिता मनः बुद्धिः यः मत भक्तः सः मेः प्रियः - जिसके मन में किसी भी जीवित प्राणी के प्रति कोई शत्रुता नहीं है।\nनेहिगा, जो दुःख देखकर पिघल जाता है, जो मैं-मेरा का अभिमान नहीं करता, जो सुख में विस्तार नहीं करता,\nजो कष्ट से नहीं हटता, जो धैर्य नहीं खोता, जो ध्यान में सदैव संतुष्ट रहता है\nजो प्रतिबद्ध है, जो किसी मार्ग पर दृढ़ता से कायम है, जो एक सैद्धांतिक निर्णय द्वारा तय किया गया है, मार्ग-ज्ञान\nमेरे अंदर जो भक्त है - ऐसा मेरा भक्त मुझे प्रिय है।\n\nभगवान जिस मानवीय व्यवहार की प्रशंसा करते हैं, उसका वर्णन करते हुए, कृष्ण पहले कहते हैं: “अद्वेष्टा\nसर्वभूतानाम्”। इसका मतलब है किसी से नफरत नहीं करना. यह भगवद्भक्ति में होना चाहिए\nपहला गुण. नफरत दो तरह की होती है. एक अच्छा (उनका उद्धार देखकर)\nदूसरे से नफरत करना बुरे से नफरत करना है (उनकी बुराई देखकर)। नफरत आएगी\nअधीरता और ईर्ष्या के कारण. दूसरे की समृद्धि देखकर दुःख उठाना ही घृणा है।\nअच्छा या बुरा - अधीर मत होइए। प्यार वहीं करें जहां अच्छाई हो, दोस्ती हो\nबड़े हो जाओ, दुष्टों को दूर छोड़ दो; अच्छाई, अच्छे लोगों से प्यार करो। दूसरे की कठिनाई\nपाया और विलीन हो गया. मैं, मेरा और मुझसे का अभिमान त्याग दो। “ईशावास्यम्\nइदं सर्वम्' - वह भगवान हर चीज का स्वामी है। यह भाव इसलिए है क्योंकि यह उसने दिया है\nजैसा भी हो...कैसे। जिस प्रकार बहुत अधिक अहंकार अच्छा नहीं है, उसी प्रकार अहंकार भी अच्छा नहीं है।\nपुरंदर दास की तरह प्रेम में स्वतंत्र रहें। पुरंदर दास के पास एक है\nएक बेटा था. उन्होंने प्यार से उसकी देखभाल की. एक दिन प्रिय पुत्र मर गया।\nफिर उन्होंने कहा, \"तोते का कोई पिंजरा नहीं होता - जो तोता आपने दिया था, वह आपसे जुड़ गया है।\"\nरहते थे. हम सुख और दुःख देखते हैं। एक संतुलन बनाना होगा. जब ख़ुशी आती है\nउड़ो मत. जब उदासी आती है तो आपको बिना गिरे उससे निपटना होता है। दूसरों के लिए खेद महसूस करना\nजैसा हो सकता है वैसा रहने दें। कोई बदला नहीं. [न्यायाधीश और अधिकारी गलत काम करने वालों को दंडित कर सकते हैं। इतना ही\n\nउसका कर्तव्य है - कोई बदला नहीं है]।\n\nकृष्ण आगे कहते हैं: \"संतुष्टः सदाचम योगी यतात्मा थमनिश्चयः\"।\nमन की एक अवस्था जो किसी भी इंसान को आरामदायक रहने के लिए चाहिए वह है 'दुख के बिना'।\nजीवन में हमारे सभी दुःखों का कारण दुःख ही है। बजाय इसके कि जो नहीं है उससे दुखी हों\nजो आपके पास है उसमें संतुष्ट रहें। आपके पास जो कुछ है उसी में संतुष्ट रहने का अभ्यास करें। हमेशा\nयोगी बनो. योगी के यहाँ अनेक अर्थ हैं। विभिन्न आसनों का अभ्यास करना योग नहीं है।\nयोग मन को एकाग्र करने की एक प्रक्रिया है। हम बंदरों की तरह रेंगते हैं\nमन को रोकना हवा को रोकने के समान है। यह बहुत अजीब है. दिमाग फिसल जाता है\nहम केवल तभी जानते हैं कि क्या हो रहा है जब यह चला जाता है। सबसे पहले ऐसी सोच रखना बंद करें\nरीढ़ की हड्डी को सीधा रखकर स्थिर बैठने का अभ्यास - आसन (यव)\nआसन ठीक है)। फिर प्राणायाम के माध्यम से आंतरिक विचार को जागृत करना\nयोग. योग भगवान को स्वच्छ मन में बैठाना है, जीवन में जीवन का प्रबंधन करना है\nयोग को जो रास्ता मिला है, उसे निष्ठापूर्वक कर रहा है। इस कदर\nहमें अभ्यास द्वारा अपने मन को वश में करना होगा। जो किसी भी चीज़ को बुरी नजर से नहीं देखता\nअभ्यास अपने आध्यात्मिक पथ पर दृढ़ रहें। चाहे कुछ भी हो दृढ़ संकल्प के साथ आगे बढ़ें\nआगे बढ़ें, मन को प्रभु के लिए तरसने दें। मन को प्रभु को जानने दो। “ऐसा कौन है\n\nजो लोग मुझसे (भक्त) प्यार करते हैं वे मेरे लिए प्रिय हैं, ”कृष्ण कहते हैं।\n\nयस्मान्नो यिदविजते लोको लोकनो यिदविजतेचा यः |\nहर्षमर्षभ्योद्वेगैर्मुक्तो यशाचामे प्रियः",
  "12.15": "यस्मात् उद्विजते लोकः लोकतश्च उद्विजथेचय |\n\nहर्ष अमरषा भय उद्वेगैः मुक्तः यः सः च मे प्रियः - जो किसी से आहत न हो।\nजो किसी को दुःख नहीं पहुँचाता, जो क्रोध से बिगाड़ नहीं करता, जो क्रोध नहीं करता, जो अज्ञानी है,\nजो घबराता नहीं, वही मेरा प्रिय है।\n\nदूसरा हमें देखकर घबरा न जाए.. और हम दूसरे को\nघबराओ मत. किसी को भी हमें और दूसरों को देखने के लिए अधीर नहीं होना चाहिए\nदेखिए, हमें अधीर नहीं होना चाहिए. इसे प्राप्त करने के लिए जब हम दुनिया से बिना शर्त प्यार करते हैं\nसंभव है प्रभु हमसे तब प्रेम करते हैं जब हम वही करते हैं जो उन्हें प्रसन्न करता है। भगवान\n\nप्यार करने वालों को पूरी दुनिया प्यार करती है।\n\nहमें भय और चिंता से मुक्त होना चाहिए। जो नहीं करना चाहिए उसे करने में\nआनन्द मनाओ; जब कोई दूसरा वही करता है जो उसे करना चाहिए तो ईर्ष्या करना बुरी बात है।\nसाधक को हर्ष अमर्ष से मुक्त होना चाहिए। कुछ डरावना और गलत मत करो\nजब आप ऐसा न करें तो घबराएं नहीं। यदि हम दूसरों को संदेह की दृष्टि से देखते हैं, तो वे भी हमें संदेह की दृष्टि से देखते हैं\nसंदेह की दृष्टि से देखा जाने लगा। जब हम दूसरों पर भरोसा नहीं करते, तो वे हम पर भरोसा नहीं करते।\nइस तनाव से । तनाव से हमारे शरीर में कई तरह की बीमारियाँ घर कर जाती हैं\nहमें भगवान पर भरोसा करना सीखना चाहिए और निःस्वार्थ और निश्चिंत होकर जीना चाहिए।\n\"एक साधक जो जीवन में सभी से प्यार करता है; एक साधक जो भय और चिंता पर विजय प्राप्त करता है वह मैं हूं\nप्रिय” कृष्ण कहते हैं।",
  "12.16": "अनापेक्षः शुचिः दक्षः उदासीनः गतव्यथाः।\n\nसर्वरामपरित्यागी यः मत भक्तः सः मेई प्रियः - जो कुछ भी नहीं चाहता, संक्षेप में\nजो सतर्क है, जो कुछ भी नहीं पहनता, जो परेशान नहीं है, जो भगवान का उपासक नहीं है।\nवह जो किसी भी कार्य में संलग्न नहीं होता, [भगवान् को सब कुछ मैं-मेरा मानकर अर्पित करता हूँ\nहम्मू भगोड़ा], मेरा ऐसा भक्त मुझे प्रिय है।\n\nइस श्लोक में कृष्ण ने उन छह गुणों के बारे में बताया है जो उनके भक्त में मौजूद होने चाहिए, जो भक्ति के पूरक हैं।\n\n(1)अनापेक्षा: यह चाहना नहीं है कि यह चाहना है। किस क्षणिक सुख से!\nशाश्वत मोक्ष के मार्ग पर चलना, जो आता है उसका अनुसरण किए बिना। आपको क्या मिला?\nइसमें आनंद लेना-यह अवांछनीय है।\n\n(2) शुचिः : स्वच्छ एवं स्वतंत्र होना। यह तह है. मुँह में बुरे शब्द, मन में बुरे\nसोचा, मील में गंदगी है - यह मील में है। सबसे पहले हमें अपने मन की गंदगी को धोना होगा।\nइसका पूरक है बाह्य सफ़ाई। इसके लिए हम शांति पाठ में कहते हैं: “ओम भद्रं कर्णेभिः\nश्रीनुयाम देवः भद्रं पश्येमक्षभिर्यजत्र ह अस। आइए अच्छे पर नजर डालें,\nचलो अच्छी बात करें, अच्छा सोचें। यह एक वास्तविक तह है.\n\nमैडी के बारे में दो और प्रसिद्ध छंद हैं:\n\nअपवित्रः पवित्रोवा सर्ववस्थं गतोपिव |\nयः स्मरेथ पुण्डरीकाक्षम् स बभाभ्यन्तरः शुचिः॥\n\nऔर\nअतिनिलाघनश्यामन् नलिनायतलोचनम् |\nस्मरामि पुण्डरीकाक्षम् तेन सना तो भावम्यहम्।\nउन्होंने कहा कि यहां पुंडरीकाक्ष का स्मरण करना चाहिए. यह भगवान का एक विशेष नाम है.\nपुण्डरीकाक्ष का अर्थ है केन्दवर जैसी आँखों वाला। प्रभु की दृष्टि सदैव बनी रहती है\nकेन्दवारा गुलाब की तरह खिलता और आह भरता है। आमतौर पर जब हम सबसे ज्यादा खुश होते हैं\nहमारी आँखें चौड़ी हो गईं. परन्तु ईश्वर सदैव आनन्द का स्रोत है। प्रभु प्रेम से देखो\nमुझे देखते हुए मैं उनकी आंखों से बहती कृपा की धारा में हूं\nउसकी कृपा की कृपा मुझ पर बह रही है। मैंने कहा कि मैंने इसमें शराब पी है\nदृष्टिकोण साफ़ है. इस प्रकार हमें भगवान की कृपा से अंदर और बाहर से जुड़ना चाहिए।\n(3) दक्ष: हमारे अंदर अपने मन को ईश्वर की ओर निर्देशित करने की क्षमता होनी चाहिए। वह हमारा बाह्य प्रयास है\nक्या हमें भीतर से उसके पास नहीं जाना चाहिए? बाह्य क्रिया ही हमारी आंतरिक उपलब्धि है\nबस इतना ही. हमें प्रभु से कैसे जुड़ना है इसकी समझ और बुद्धि होनी चाहिए।\n(4)उदासीनता : अंतर्मुखी होना। किसी भी बाहरी कार्रवाई पर जोर न दें, उसकी मांग न करें।\nउदाहरण के लिए- आपके परिवार में किसी को किसी चीज़ की इच्छा है\nइसे पूरा करने के लिए वे किसी तरह की पूजा कर रहे हैं। ऐसे में ये फायदेमंद होता है\nयह कहकर इसके विरोध में खड़ा होना कि भगवान की पूजा करना गलत है, ठीक नहीं है। जो कुछ भी है वह ईश्वर का है\nसेवा; प्रार्थना करें कि यह प्रभु से जुड़ जाए। बिना किसी मांग के सबके साथ रहना\nसीखो\n(5) गाथाव्यथा: बिना बोर हुए हमेशा खुश रहना।\n(6) सर्वारंभपरित्यागी: भगवान की सर्वोच्चता के विपरीत किसी भी पहल में संलग्न न होना।\nसभी स्टार्टअप शुरू से करना बंद करें। हर चीज के अंत में कृष्णार्पणमस्तु\nउसे प्रभु में अर्पित करो।\nकृष्ण कहते हैं, 'जो भक्त मुझे इन गुणों से प्रेम करता है, वह मुझे प्रिय है।",
  "12.17": "यः न हृष्यति न वेति न शोचति न कांक्षति |\nशुभ अशुभ परित्यागी भक्तिमान् यः सः मेइ प्रियाः -बंद नहीं होता; नफरत नहीं करें; कराहता नहीं;\nअच्छे-बुरे की परवाह नहीं करना चाहता, ऐसा भक्त ही मेरा प्रिय है।\n\nयहां पहले बताए गए कुछ विचारों की पुनरावृत्ति है। आमतौर पर एक से अधिक चीज़ें\nकिसी बात को स्पष्ट करने और उस पर ज़ोर देने की अतिरेक। यहाँ कृष्ण हैं\nकहते हैं: जब कुछ अच्छा किया जाए तो रुकें नहीं और किसी और की तलाश करें\nनाराज मत होइए. बहुत खुश रहो कि तुम्हें यह मिल गया, इस बात पर दुखी या नफरत मत करो कि तुम्हें यह नहीं मिला। जीवन में ज्ञान\nभक्ति वैराग्य शुभ है. बाकी हर चीज के फायदे और नुकसान का विश्लेषण न करें। इस दुनिया में\nकुछ भी आकस्मिक नहीं है. यहां होने वाली हर घटना कुछ ऐसी होती है जिसके बारे में हम पहले नहीं जानते थे\nवहाँ एक कारण है। इसके लिए मृत्यु यह निर्णय नहीं कर पाती कि वह शुभ है या अशुभ। यह जानकर\n\nकृष्ण कहते हैं कि जीवित भक्त ही मुझे प्रिय है।",
  "12.18": "जो शत्रु और मित्र में सम है, तथा मान और अपमान में सम है, शीत-उष्ण और सुख-दुखों में सम है और आसक्ति से रहित है —\n\nप्रिय भक्त के लक्षणों की श्रृंखला जारी है। 'समः शत्रौ च मित्रे च' — शत्रु और मित्र में कोई भेद न देखना। 'मानापमानयोः' — मान और अपमान में समता। 'सङ्गविवर्जितः' — आसक्ति से रहित होना।",
  "12.19": "समः शत्रुौ च मित्रे च तथा मन अपमानयोः।\n\nशीत, गरम, सुखी, दुःखी, उदास, संगविवर्जितः।\n\nतुल्य निंदा स्तुतिः मौनी सन्तुष्टः येना केनाचित्।\n\nअनिकेतः स्थिर मतिः भक्तिमान् मे प्रियः नरः - जो शत्रु-मित्रों में भेदभाव नहीं करता; सम्मान-\nजो अपमान, सर्दी-गर्मी, सुख-दुख को समान रूप से देखता है; कुछ नहीं के लिए\nगैर-अनुयायी; जो प्रशंसा को तिरस्कार के रूप में देखता है; विचारमग्न; जैसा भी हो\nइस बीच वह संतुष्ट था; एक ओर वह जो भगवान के प्रति सचेत होकर अस्थिर है\nमुझे ऐसा कठोर व्यक्ति-भक्त पसंद है।\n\nआमतौर पर हम हैं. शत्रु या सहयोगी होने की भावना पर जोर दें\nहमें इसकी आदत हो जाएगी. जो हमारी प्रशंसा करते हैं वे हमारे मित्र हैं, जो हमारी निन्दा करते हैं वे हमारे शत्रु हैं।\nयह हमारी मूर्खतापूर्ण चाल है. दोस्ती के पीछे नफरत हो सकती है, नफरत के पीछे दोस्ती हो सकती है।\nहम यहां याद कर सकते हैं कि पुरंदरदास ने \"निंदकार अवश्य होना चाहिए\" गाया था।\nदुर्व्यवहार करने वाले हमारी गलती है. कर्म करने से हमारे जो निंदनीय दोष होते हैं उनका फल मिलता है\nस्तुति करने वाला हमारे अंदर की भलाई का फल है\n\nहिस्सा मिलेगा. अत: सिद्धि के मार्ग में प्रशंसा करने वालों की अपेक्षा निंदक अधिक सहायक होते हैं।\nइस कारण किसी को शत्रु या मित्र समझकर उसकी आलोचना करना घृणा है\nबंधे मत रहो. विकार से दूर रहो. अच्छे चरित्र से प्यार करें. कहाँ\nअच्छाई का साथ है); दुःख देखकर घुलना (करुणा); दूसरे का\nखुशी पाकर खुश हो जाओ (मुदिता); बुराई (उपेक्षा) से दूर रहें। मूलतः\nशत्रु-मित्र विभाजन की कोई आवश्यकता नहीं है। हर किसी में भगवान देखें. सांसारिक शत्रु-मित्र का भाव\nछोड़ दो\n\nसम्मान मिलने पर फूले नहीं। अपमान होने पर सिकुड़ें नहीं. लज्जा को जीतो.\nइससे कोई फर्क नहीं पड़ता कि कोई और क्या कहता है. महत्वपूर्ण यह है कि हमारी आत्मा क्या है।\nजब कोई दूसरा हमारी प्रशंसा करता है तो जो गुण हमारे पास नहीं है वह हमारे पास आकर शामिल नहीं होगा। इसी तरह एक और\nहम बिछड़ कर नीचे नहीं जाते. हमें प्रशंसा को लेकर सावधान रहना चाहिए. उसके कारण\nहमारे भटकने की सम्भावना अधिक है। शर्म के मारे हम गलत रास्ता छोड़कर सही रास्ते पर चल पड़ते हैं\nबढ़ने की संभावना है.\n\nसुख और दुख को समान रूप से देखें। कोई भी वस्तु हमें सुख या दुःख नहीं दे सकती। वह वस्तु\nजो अनुभूति हम देखते हैं वह हमें सुख और दुख देती है। तो सर्दी-गर्मी जैसी खुशी-\nदुःख को समान रूप से देखने का अभ्यास करें।\n\nहम सोचते हैं कि ये सब मनुष्य की वृत्तियाँ हैं॥15॥700. लेकिन यह प्राकृतिक धर्म नहीं है. हम हैं\nचिपकना हमें उन गुणों से भर देता है जो हम नहीं चाहते। इसलिए\nप्रशंसा और उपहास पर तुरंत प्रतिक्रिया न करें। चुप रहो मामले पर ध्यान करो.\nजल्दी मत करो. जितना हो सके उतना कम बात करें। सोचो और बोलो.\nजो आपके पास है उसमें संतुष्ट रहें। स्थिर गतिमान वस्तुओं के पीछे (Movable and immovable)।\nमत जाओ प्रभु ने तुम्हें जो दिया है उसमें खुशी से जियो। भक्ति भाव से\nजब हम ईश्वर के प्रति समर्पण करते हैं तो हम अपनी उपलब्धि के पथ पर इस ऊंचाई तक पहुंच सकते हैं। \"इस कदर\nकृष्ण कहते हैं, गुणों वाला भक्त मेरा प्रिय है।",
  "12.20": "यतुधर्म अमृतं इदं यथा उक्तं पर्युपासते |\n\nश्रद्धाधानः मत परमः भक्तः ते अतिव मे प्रियः - यह भक्ति ही धर्म मोक्ष का साधन है।\nजो लोग यहां बताए अनुसार योग का अभ्यास करते हैं, वे मेरी महानता में विश्वास करते हैं और मुझमें चलते हैं -\nवह मुझे बहुत पसंद है.\n\nहमारी भक्ति कैसी होनी चाहिए, भक्त में क्या गुण होने चाहिए यह इसका अमृत है।\nकृष्ण, जिन्होंने धर्म की व्याख्या की है, यहाँ निष्कर्ष निकालते हैं: “उपासना जैसा कि यहाँ बताया गया है\nमेरे लिए, जो लोग ऐसा करते हैं, जो लोग सद्गुण विकसित करते हैं, जो लोग भक्ति के साथ अभ्यास करते हैं, वे भक्त हैं\nप्रिय।”\nइति द्वादशोऽध्यायः\nबारहवाँ अध्याय समाप्त हो गया\n\nक्या यह सच है?\n\nअध्याय तेरह\n\nयह भगवत गीता के तीसरे अध्याय का पहला अध्याय है। गीता का यह तेरहवाँ अध्याय एक है\nएक असाधारण अध्याय. इन पिछले बारह अध्यायों में जो कुछ कहा गया है, उसे एकत्रित करें\nइस अध्याय में जो कहा गया है वही करो. पिछली दो शताब्दियों में देखी गई चीज़ों से भरपूर\nविश्लेषण यह अध्याय. निर्जीव संसार, प्रकृति से बंधा हुआ, प्रकृति से पलायन\nवांछित जीवन. मोक्ष के लिए ज्ञान की खोज और प्राप्ति - ये सभी बातें\nजैसा कि हमने पिछले अध्यायों में देखा है, उन सभी का एक संग्रह (सर्वत्र)।\nसंक्षेप में) यह अध्याय। यह अध्याय गीता का सबसे बोधगम्य अध्याय है।\n\nयहाँ शुरुआत में एक श्लोक है. इस अध्याय में आगे जो बताया जाएगा वह स्वयं ही स्पष्ट किया जाएगा\nएक श्लोक जिसमें अर्जुन कृष्ण से जानना चाहते हैं। यह श्लोक पढ़ता है:\n\nप्रकृतिं पुरुषं चैव क्षेत्रं क्षेत्रज्ञमेव च |\nएतद् वेदितुमिच्छामि ज्ञानं ज्ञेयं च केशव ॥\n\nअर्थ – “केशव, मैं जानना चाहता हूँ: प्रकृति, पुरुष, क्षेत्र,\nक्षेत्रज्ञ, ज्ञान और ज्ञान”।\n\nदरअसल यह श्लोक भगवत गीता का श्लोक नहीं है. इस श्लोक का कोई भी प्राचीन भाष्यकार नहीं\nभजन नहीं माना जाता. कई लोगों के अनुसार यह प्रक्षिप्त श्लोक है। गाने में\nकुल मिलाकर सात सौ श्लोक हैं। इसीलिए इस गीत को 'सप्तशती' कहा जाता है। [इसके लिए\nवदिराज ने अपनी युक्तिमल्लिका में वेदव्यास का उल्लेख किया है जिन्होंने ब्रह्मसूत्र और भगवद गीता की रचना की थी।\n\"सूत्रसप्तसाथिपते\" कहकर सम्बोधित किया गया है। यह भगवत गीता है जिसमें ऐसे सात सौ श्लोक हैं।\nउपरोक्त श्लोक को जोड़ने पर कुल सात सौ एक श्लोक बनता है। इस श्लोक में आगे\nपिछले अध्याय के अंत में कहीं भी कृष्ण का उल्लेख नहीं किया गया है जो पूछे गए प्रश्न के लिए प्रासंगिक है। यह\nइस वजह से, अर्जुन द्वारा यहां यह प्रश्न पूछने की संभावना नहीं है। अतः यह श्लोक प्रक्षिप्तश्लोक है।\nयह गीता के सात सौ श्लोकों में सम्मिलित नहीं है।\n\nसीधे कृष्ण अर्जुन को क्षेत्र और क्षेत्र का शास्त्रीय अर्थ\nयह अध्याय एक स्पष्टीकरण से शुरू होता है।\n\nभगवान का वचन",
  "13.1": "इदं शरीरं कौन्तेय क्षेत्रमिथ्यभिधीयते |\nएतद् यो वेत्ति तं प्राहुः क्षेत्रज्ञ इति तद्विदः ॥1॥\n\nभगवान उवाच- भगवान ने कहा:\n\nइदं शरीरं कौन्तेय क्षेत्रं इति अभिधीयते।\n\nएतत् यः वेत्ति तम प्राहु क्षेत्रज्ञः इति तत् विदः- यह चरित्र जो भगवान के शरीर के समान है।\nसंसार को “क्षेत्र” कहा जाता है। जो लोग इसे जानते हैं वे “क्षेत्रज्ञ” कहलाते हैं।\n\n'फ़ील्ड' शब्द का कोई विशिष्ट अर्थ नहीं है। इस श्लोक में क्षेत्रम् शब्द का क्या अर्थ है?\nकृष्ण ने इशारा किया है समझने का. क्षेत्र का अर्थ है 'इदं शरीरम्'\nकृष्ण. तो यहाँ क्षेत्र का अर्थ है जीवन का निवास, पिंडदान से लेकर ब्रह्मांड तक\nसब कुछ हाँ है. इस ब्रह्मांड के लिए 'क्षेत्र और शरीर' वुडू अन्वार्थनमा (6/18) है।\nजो क्षेत्र को व्यापक रूप से जानता है वह क्षेत्र विशेषज्ञ है। जैसे कि अगले श्लोक में कौन\nचलो देखते हैं.",
  "13.2": "क्षेत्रज्ञं च अपि माम् विधि सर्व क्षेत्रेषु भारत।\n\nक्षेत्र क्षेत्रज्ञो ज्ञानं यत् तत् ज्ञानं मातं मम - हे भारत, सभी क्षेत्रों में।\nयह जानो कि मैं ही निवास करने वाला “क्षेत्रज्ञ” हूं। वास्तविक 'ज्ञान' क्षेत्र और क्षेत्र विशेषज्ञों का ज्ञान है\nमेरी राय\n\nभगवान वह क्षेत्रज्ञ हैं जो अंदर और बाहर, सभी क्षेत्रों में पूर्ण हैं। जीव ही क्षेत्र है।\nसच्चा ज्ञान संसार के प्रति जागरूकता है; प्रभु चेतना ब्रह्मांड में व्याप्त है। हम इस दुनिया के भीतर हैं\nआप कैसे हैं यह ब्रह्मांड हमसे किस प्रकार बंधा हुआ है? उस विश्वात्मा ने यह संयम हटा दिया है\nहम प्रभु से कैसे जुड़ सकते हैं? यह जागरूकता ही ज्ञान है। जैसा कि हमने पिछले अध्याय में बताया है\nपंद्रह. हम बाड़ों की जेल में हैं। लेकिन यह सज़ा नहीं, शिक्षा है. इस गिरफ्तारी से\nयदि आप बचना चाहते हैं, तो आपको उस क्षेत्रज्ञ को जानना होगा जो मुक्तिदाता है। यह जागरूकता ही वास्तविक ज्ञान है।",
  "13.3": "तत् क्षेत्रं यत् च यद्रिक च यत् विकारी यतः चयत् |\n\nसः च यः यत् प्रभावः च तत् समासेण मे श्र्णु - वह क्षेत्र कौन सा है? यह कैसा है?\nइसकी विकृतियाँ क्या हैं? इसकी प्रेरक शक्ति कौन है? वह कैसा है उसकी ताकत क्या है? यह\nमुझसे ध्यान से पूछो.\n\nसबसे पहले फ़ील्ड क्या है? ब्रह्माण्ड और पिण्डदण्ड कैसे और किससे बना है?\nइसकी प्रकृति क्या है? यह कैसे परिवर्तित होता है? ये बदलाव\nकैसे के बारे में किसके द्वारा? यह सब मेरी ओर से सूत्रबद्ध, संक्षिप्त, मजाकिया तरीके से\nसुनो",
  "13.4": "खपिभिः बहुधा गीतं छन्दोभिः विधाभिः पृथक।\nब्रह्मसूत्रपादैः च एव हेतुमाद्लिः विनिश्चितैः - विभिन्न मंत्रों से सुख।\nइसे विभिन्न प्रकार से गाया गया है। साथ ही युक्ति से निर्णय करते हुए वेदांत सूत्र के शब्द भी।",
  "13.5": "इस विषय को बुद्धिमान पुरुष भी एक-एक करके कहते हैं। यह उनका अनुभव है\nसीमित है. ब्रह्मसूत्र में जो कहा गया है उसे समझना आसान नहीं है। बिलकुल सच\nसुनो, मैं खुद एक फील्ड एक्सपर्ट हूं।\n\nमहाभूतन्याहंकारो बुद्धिरव्यक्तमेव च।\n181",
  "13.6": "महाभूतानि[महं भूतानि] अहंकारःः बुद्धिः अव्यक्तम् एव च।\nइन्द्रियाणि दशा एकं च पंच च इन्द्रिया अधियाः ॥",
  "13.7": "इच्छा वेतः सुखं दुःखं संघतः चेतना धृतिः |\n\nएतत् क्षेत्रं समसेन सविकारं उदाहृतम् -- मिट्टी[पृथिवी], जल[वरुण], अग्नि[अग्नि] 1:\nगल्वा [वायुपुत्र मारीचि], बानू [अवसर की देवी, विघ्न नशा-विनायक-गणपति] -\nमहाभूत। अहंकार [रह्मवायु और शिव], बुद्धि [पार्वती], मूलप्रकृति [श्री,,\nकिवा[चंद्र.0,, त्वचा[वायुपुत्र मरुत], आँख[सूर्य], जीभ(वरुण], नाक[अश्विस],\nमुँह [अग्नि], हाथ [वायु के पुत्र नदी], पैर [इंद्र के पुत्र यज्ञ (जयता) और शंभू],\nपयु[यम], उपस्थ[शिव-गंडासा के बीच लिंग देवता; स्वायम्भुमानु-स्त्रिय के बीच] इस प्रकार दस\nइंद्रियाँ. ग्यारहवां मनसत्व [इंद्र, काम और अनिरुद्ध] और पांच इंद्रियां हैं\nविषय: ध्वनि, स्पर्श, रूप, रस और गंध[प्राण, अपान, व्यान, उदान रुद्र के पुत्र\nऔर बराबर] ये 24 सघन क्षेत्र हैं।\n\nइच्छा [श्री और भारती], घृणा [(द्वापर-शकुनि]), खुशी [मुख्यप्राण-वायु-भीम], उदासी [काली-\nदुर्योधन], समष्टिशरीरा [शरीर में प्रशंसक जीवन; सभी प्रशंसक देवता],\nस्मृति, साहस [सरस्वती और भारती] के हरहु [श्री] सात विशेष कर्म विकार हैं। इस प्रकार\nविकृति के साथ-साथ क्षेत्र को समाहित बताया गया।\n\nइन दो श्लोकों में कृष्ण क्षेत्र और क्षेत्र की विकृति का वर्णन करते हैं। अखण्ड को क्षेत्र कहा जाता है\nकृष्ण ने यहां सूत्र के रूप में समाहित इकाई के अंतर्गत जगत् के अवयवों का वर्णन किया है।\nसबसे पहले। पंचमहाभूत. इन पांचों से यह पिंडदान और ब्रह्मांड\nनिर्माण किया है। इसी कारण ब्रह्माण्ड को 'प्र-पंच' कहा जाता है। यह पंच\nमहाभूत ही जगत् के मूल हैं। पिंडदान में ये पांच महाभूत अन्नमय और हैं\nइसे प्राणमय कहा जाता है। दृश्यमान स्थूल शरीर पदार्थ और जल से बना है। जैसे कि\nस्थूल शरीर के भीतर एक अदृश्य प्राणमयकोश है। शरीर की गर्मी (अग्नि), सांस (वायु) और\nरक्त-वायु को अंदर (आकाश) जाने दें। इसके परे मन और बुद्धि है\nमनोमयकोश, और उससे भी आगे विज्ञानमयकोश-स्मृति। तो पहले दिमाग लगाओ\nअहंकार और मनोदशा. यहाँ अहंकार का अर्थ है \"मेरे अस्तित्व के प्रति जागरूकता ।\nअहंकार तत्व पिंडदान में मन है, जिसका अर्थ ब्रह्मांड में है।\n\nइस व्यक्त जगत की उत्पत्ति अव्यक्त है। सृष्टि की मूल अवस्था-प्रलयसागर। वह है\nअव्यक्त जगत परमाणु रूप में बिखरा हुआ है। ऐसी दुनिया में, चतुर्मुख\nमहत्व पैदा किया. \"मैं हूँ\" उन जीवित प्राणियों के लिए जो प्रलय सागर में अपने अस्तित्व से अनजान थे।\nउसका बोध ही सार्थकता का सृजन है। मन का दायरा आत्मा है. यह हमारी स्मृति की सीमा है.\n\nइस शरीर में पाँच इन्द्रियाँ हैं, पाँच। कर्मेन्द्रियाँ हैं। और ग्यारहवाँ\nकामुक मन है. कान से ध्वनि का बोध, आँख से रूप का बोध, नाक से गंध का बोध\nअवशोषण, जीभ द्वारा रस का अवशोषण, त्वचा द्वारा वायु का अवशोषण। इसी प्रकार बोलने के लिए मुँह, हाथ\nकाम करने के लिए, पैदल चलने के लिए. इन आठों को ग्रह कहा जाता है । फिर पेयु और\nउपस्थ (उत्सर्जक और प्रजननात्मक)। ग्यारहवाँ जो इस सब पर विचार करता है\nकामुक मन. ये सभी क्षेत्र की सामग्रियां हैं. सामूहिक रूप से यही क्षेत्र है. [यहाँ कहा गया है\nप्रत्येक इकाई के साथ उसका संरक्षक देवता भी होता है। इस पर संक्षेप में\nकहा]\n\nयह संसार सदैव परिवर्तनशील है। उसके लिये जगत् को अश्वत्थ भी कहा जाता है। घोड़ा दृढ़ है\nगतिमान एक जानवर. यह कभी स्थिर नहीं रहता. ये दुनिया हमेशा ऐसी ही है\nगति में रहना - इसे ही प्राचीन लोग अश्वत्थ कहते थे। हमारा शरीर भौतिक है\nविकृति मानसिक जगत की सारी उथल-पुथल मानसिक विकार है। विशेषकर\nहमारी इच्छा (इच्छा), (ए)द्वेष, सुख और दुख, हमारी स्मृति (चेतना), (ए)ध्रुति। ये कृष्ण का है\nक्षेत्र के स्वरूप और विकृति का वर्णन | चाहे यह विचार कितना भी विस्तृत क्यों न हो\nहम विश्लेषण कर सकते हैं. कृष्ण ने यहां सब कुछ समझाया है.\n\nयदि हम ज्ञान के मार्ग पर आगे बढ़ना चाहते हैं तो हमें कुछ नैतिकताओं को अपने आचरण में अपनाना चाहिए\nआचार संहिता (codes of conduct) हैं। हमें उनका अनुसरण करना होगा.\nकृष्ण अगले पांच श्लोकों में पालन किए जाने वाले बीस गुणों की व्याख्या करते हैं। यह\nजितना अधिक हम प्रत्येक गुण को अपने जीवन में शामिल करेंगे, हम उतने ही अधिक जानकार होंगे\nहो सकता है रास्ते में हो. सावधान रहें अन्यथा हमें अज्ञानता के मार्ग पर चलना पड़ेगा\nकृष्ण ने भी यहां दिया है.",
  "13.8": "इन्द्रिय अर्थेषु वैराग्यम् अनहंकारः एव च।\n\nजन्म मृत्यु ज़रा व्याधि दुःख दोष अनुदर्शनम् - कामुक मामलों में\nअव्यक्त, अकल्पनीय, जन्म-मृत्यु की दुविधाओं से परिपूर्ण।\nजीवन के दोषों से सावधान रहें,-\n\n(10) इंद्रियार्थेषु वैराग्य: इंद्रियों को बाहरी दुनिया और मन की ओर बहने से रोकता है।\nप्रभु में विश्राम. इसे शमा-धमा कहा जाता है. सांसारिक मामलों के प्रति संवेदना\nइसे बहने से रोकना धर्म है और इसे भगवान की ओर प्रवाहित करना शमा है।\nजब इंद्रियाँ भगवान के प्रति जागरूक होती हैं, तो वे किसी और चीज़ की ओर नहीं बहती हैं। एक सांसारिक ध्वनि, स्पर्श,\nरूप, रस और गंध से घृणा। उदाहरण के लिए, जीभ लचीली होती है। हममें से कुछ लोग घर पर हैं\nअगर ठीक से पकाया भी जाए तो भी ये ठीक नहीं है, ये ठीक नहीं है वगैरह-वगैरह.\nइस तरह की नौटंकी छोड़ो. यहां जो कुछ भी रखा गया है वह बिना किसी चाहत या आवश्यकता के भगवान का है\nइसे प्रसाद के रूप में स्वीकार करना सीखें। ऐसे प्राप्त करें शमा-धमा।\n\n(11) अहंकार : यह सभी गुणों में सबसे बड़ा है। हमारे पास जो भी गुण है वह हमारा है\nअहंकार के आगे व्यर्थ. अहंकार (₹60) हमारे सभी गुणों को नष्ट कर देता है।\nअहंकार के बिना अन्य गुणों का कोई अस्तित्व नहीं है। इसलिए कृष्ण इसे यहां \"एव-चा\" के रूप में जोर देते हैं।\nकहा 'मैं विद्वान हूं, मैं कार्यान्वयनकर्ता हूं, मैं पागल हूं' और इस प्रकार हम पर अहंकार करते हैं\nयह हर मामले में प्रेतवाधित है। इस प्रकार, यदि हम अहंकारी हो जाते हैं, तो हमारा कार्यान्वयन कार्यान्वयन है\nऐसा नहीं होगा जहां अहंकार राज करता है, वहां उपलब्धि व्यर्थ हो जाती है। जहाँ अभिमान है\nकोई ईश्वर नहीं है-अर्थात् हम अहंकार के कारण ईश्वर से विमुख हो जाते हैं। इस वजह से\nयह कहना बंद करें, \"मैंने यह किया, यह मेरे द्वारा किया गया। भगवान ने इसे मेरे हाथों से किया।\"\nउसे कृतज्ञता दिखाओ.\n\n(12) जन्म मृत्यु ज़रा व्याधि दुःख दोष अनुदर्शनम्: जीवन को अंतर्दृष्टि से देखो।\nयह जीवन जन्म और मृत्यु के दो किनारों के बीच बहने वाली एक नदी है। यह\nबाढ़ में रोग, शोक, शोक और शोक की लहरों का सिलसिला। यह हमारा जीवन है\nउद्देश्य क्या है, ईश्वर ने हमें क्यों बनाया, मानव जन्म को कैसे सार्थक बनाया जाये\nउसका पालन करें. भोजन निद्रा भय मिथुन एक समान जीवन नहीं है। जानवर भी ऐसा करते हैं\nअनुभव करो अतः धर्मग्रंथों को पढ़ो और सत्य के अनुरूप सच्चा दर्शन बनाओ।\nकेवल सांसारिक सुख की आशा में जीना बंद करो-सत्य की प्राप्ति के लिए, प्रभु की खोज करो।\nशामिल होने के लिए जियो. सारी सांसारिक सुख-संपदा निसा की है। इसके परे सार है\nप्रभु को जानो और उसकी ओर कदम बढ़ाओ।",
  "13.9": "माई चाणन्याओ भक्तिरव्याभिचारिणी\nविविक्तदेशसेवित्वमराथिर्जनासाधि",
  "13.10": "अध्यात्मज्ञाननित्यत्वं तत्त्वज्ञानार्थदर्शनम् |\nएतज ज्ञानमिति प्रोक्तम्ज्ञानं यदातोह्न्यथा",
  "13.11": "असक्तिः अनाभिष्टंगः पुत्र दारा गृह आदिषु |\n\nनित्यं च समचित्तत्वं इष्ट अनिष्ट उपपत्तिषु ॥\n\nमायचा अनन्ययोगेन भक्तिः अव्यभिचारिणी |\n\nविविक्त देश सवित्वं आरतीः जन म.प्र.\n\nअध्यात्म ज्ञान नित्यत्वम् तत्वज्ञान अर्थ दर्शनम् |\n\nएतत् ज्ञानं इति प्रोक्तं अज्ञानं यत् अत: अन्यथा एक अनासक्ति, बच्चों\nपसंद-नापसंद आने पर मदादी माने आदि से ज्यादा न जुड़ें\nहमेशा के लिए अनसुलझा, कहीं और। बिना हिलाए अपने प्रति अटूट भक्ति, एकांत,\nभीड़ में न मिलें, अप्रत्यक्ष ज्ञान के लिए आध्यात्मिक जागरूकता में निरंतर स्थिति\nशास्त्र का अध्ययन,|[दर्शन को दर्शनीय भगवान की प्राप्ति] यही ज्ञान और ज्ञान है।\nउपकरण. इसके अलावा अज्ञान और अज्ञान का मार्ग है।\n\n(13) असक्ति: \"शक्ति' का अर्थ है चिपकना या चिपटना (glue)। यह\nहमने पहले भी कई बार इस मुद्दे पर चर्चा की है। \"सक्ते\" हमारे सभी दुखों का कारण है\nकिसी भी बात पर अड़े मत रहो. मृत्यु जन्म के समय कुछ नहीं लाती, मृत्यु के समय कुछ नहीं लाती\nनहीं ले जाऊंगा. इसलिए इस सांसारिक शक्ति से दूर रहें। जो आया वह प्रभु का है\nइसे प्रसाद के रूप में स्वीकार करें, जब भगवान की इच्छा हो तो खुश रहें।\n\n(14) अनाभिष्टंगः पुत्र दारा गृह आदिषु : अभिष्टांगः का अर्थ है अत्यधिक श्रृंगार . घर, पत्नी(पति/पत्नी) बच्चे आदि से ज्यादा मोह न रखें\nकृष्ण कहते हैं. यहां परिवार से मोह न रखने का मतलब है सब कुछ छोड़कर जंगल में चले जाना\nनहीं जा रहा. \"मैं इसके बिना नहीं रह सकता\" सब कुछ छोड़ देने के बारे में है। जीवन में\nदेखिये सबूत के तौर पर क्या आता है। जीवन एक खेल है, जिसमें आप हैं\n\nआप दर्शक हैं, नायक हैं। भगवान निर्देशक हैं. यहां मेरे बच्चे मेरी जिंदगी हैं, मेरे पति/पत्नी मेरे हैं\nजिंदगी, मेरी कमाई ही मेरी जिंदगी है, इसके अलावा मेरा कोई अस्तित्व नहीं है।'\nप्यार मत करो - लेकिन शिकायत मत करो, निराशा मत करो। जीवन तब है जब आप इस तरह जीना सीख जाते हैं\nखूबसूरत है अगर हमारे बच्चे हमसे दूर हैं, अगर पत्नी/पति दूर हैं तो हम अपने हैं\nधन (घर, संपत्ति आदि) की हानि से दुःख-निराशा नहीं होती। जब ऐसे जी रहे हो\nजीवन में जो भी त्रासदी आती है, हमें लगता है कि इसमें हमारी ही भूमिका है\nइसे स्वीकार करने में सक्षम हों—आघात में न पड़ें।\n\n(15) नित्यं च समचित्तत्वं इष्ट अनिष्ट उपपत्तिषु : जीवन में मनभावन घटना।\nहो सकता है, कोई अप्रिय घटना घट जाये. जब ऐसी बुराइयां आएं तो ध्यान रखें\nअपना संतुलन खोए बिना हर समय संतुलित रहना सीखें। हम बुरे हैं\nहम जो सोचते हैं वह जरूरी नहीं कि बुरा हो या जो हमें पसंद हो वह जरूरी नहीं कि अच्छा हो।\nइसलिए, जो आता है उसे पसंद या नापसंद के कलंक के बिना \"नहं कर्ता हरिः कर्ता\" के रूप में स्वीकार करना।\nसीखा: हमारे जीवन में घटित होने वाली प्रत्येक घटना ईश्वर द्वारा हमारे प्रशिक्षण के लिए बनाई गई है\nव्यावहारिक (Practical) शिक्षा। भगवान हमें दुःख देते हैं और बुद्धिमान बनाते हैं\nसत्य को पहचानो और जियो.\n\n(16) मयि च अनन्ययोगेन भक्तिः अव्याभिचारिणी: भगवान के प्रति निरंतर शुद्ध भक्ति बनी रहे।\nप्रभु एक है, उसके नाम अनेक हैं। उनके प्रति अनन्य भक्ति रखें. यहां एकता बहुत जरूरी है.\nएक समय में एक दिन एक देवता की पूजा करना, जब एक देवता की पूजा की जाती है, तो दूसरे देवता की पूजा करना\nकई देवताओं की पूजा देवताओं के नाराज होने के डर से की जाती है\nवह व्यभिचार होगा. तो कृष्ण यहाँ कहते हैं \"आपकी भक्ति अद्वितीय और शुद्ध होनी चाहिए\"।\nउन्होंने इस बात पर जोर दिया. क्या आपको यह विश्वास हो सकता है कि ईश्वर सर्वशक्तिमान, सर्वशक्तिमान और जगत का कारण है।\nईश्वर में आस्था के बिना किसी भी धर्मग्रंथ को पढ़ना व्यर्थ है। भगवान पर पूर्ण\nविश्वास से ही ज्ञान प्राप्त किया जा सकता है\n\n(17) विविक्त देश सवित्वम्: जहां उच्चतम संभव सात्विक कंपन है, सात्विक लोग।\nइसके साथ जीने का प्रयास करें. अक्षुण्ण सात्विक स्पंदन का स्थान\nयह एक तीर्थस्थल जैसा दिखता है। ऐसी जगह पर जो अच्छी बातें बोलता है और अच्छी बातें सोचता है\nसज्जनों के साथ रहो. यदि यह संभव न हो तो यथासंभव एकांतवास का अभ्यास करें।\nचार लोगों के साथ गपशप में अपना अनमोल जन्म बर्बाद मत करो।\n(18) अरतिह जन संस्पति: जहां लोग किसी अवांछित कारण से इकट्ठा होते हैं, जैसे\nभीड़ से दूर रहें.\n\n(19) अध्यात्म ज्ञान नित्यत्वम्; आध्यात्मिक जागरूकता में बने रहें. पहला पिंडदान-\nब्रह्माण्ड को जानो, फिर उस असाधारण दिमाग के आश्चर्य को जानो जो इसे जानता है\nजानिए 'I' का क्या मतलब है । यह जानकर, यह आत्मा\nप्रभु को जानो जो नियन्त्रण करता है। यह तत्वमीमांसा है. आपके अध्ययन का उद्देश्य अध्यात्म है\nज्ञान हो.\n\n(20) तत्त्वज्ञान अर्थ दर्शनम्: संसार के मूलभूत सत्य को जानने के लिए आपका अध्ययन\nसमर्पित रहें. उपरोक्त सभी गुणों के कारण वह सभी शास्त्रों से, सभी शास्त्रों के अधीन हो गया\nपरमपिता परमेश्वर की प्राप्ति.\n\nयहां बताए गए गुण ज्ञान और ज्ञान के उपकरण हैं। इसके अलावा कुछ भी अज्ञान है और\nअज्ञान का लक्ष्य.\n\n6\n\nकृष्ण अगले छह श्लोकों में ध्वनि की सीमा से परे ज्ञान के साधनों का वर्णन करते हैं\nवह ईश्वर का वर्णन हमारे सामने रखता है। भगवान कैसा है, उसका स्वरूप कैसा है\nकृष्ण ने दृष्टिकोण के विचार का सुन्दर वर्णन किया है। इन श्लोकों में\nहम ऐसी कई चीज़ें देख सकते हैं जो एक-दूसरे के विपरीत प्रतीत होती हैं।\nउदाहरण के लिए: भगवान निर्गुण हैं लेकिन वे सर्वशक्तिमान हैं; भगवान अचल है लेकिन वह है\nचलता है; ईश्वर निर्विशेष है लेकिन वह साकार है; परन्तु ईश्वर को जानना असंभव है\nउसे जाना जा सकता है; भगवान के पास कोई इंद्रियाँ नहीं हैं लेकिन उनके पास इंद्रियाँ हैं; वह है\nदूर लेकिन पास; इत्यादि। इस प्रकार का वर्णन भगवान से भिन्न है\nइसे कोई और नहीं दे सकता. इन सभी का स्पष्टीकरण निम्नलिखित श्लोक में पाया जा सकता है।",
  "13.12": "ज्ञेयं यत् तत् प्रवक्ष्यामि यत् ज्ञात्वा अमृतं अश्नुते।\n\nअनादि मटचरं ब्रह्म न सत् तत् न असत् उच्यते - जिसे जानकर व्यक्ति मृत्यु पर विजय प्राप्त कर लेता है।\nऐसा \"जनेय\" मैं कहता हूं: अजन्मा, [शरीर से पैदा भी नहीं हुआ] ज्ञान है।\nदृश्यमान पृथ्वी-जल-अग्नि से भिन्न; अदृश्य हवा हवाओं से भिन्न होती है।\n\nयहाँ कृष्ण ज्ञान के माध्यम से सीखे जाने वाले ज्ञान के बारे में बताते हैं और कहते हैं:\n\"जो शब्द व्यक्त नहीं कर सकते, तुम क्या ज्ञान जानते हो।\"\n\nअमरता का स्वाद चखो—जो मैं तुमसे कहता हूं।'' भगवान अनादिमत!\nउसका पाँच अनित्य तत्वों का कोई स्वरूप नहीं है। वह ज्ञानानन्द स्वरूप हैं।\nईश्वर के गुण अनन्त हैं। प्रभु हमारे लिए गुणों से परिपूर्ण हैं\nपरिपूर्णता का दाता. वह सर्व-रक्षक है, उससे बड़ा कोई सिद्धांत नहीं है। जैसे\nहम ईश्वर को पूर्णतः नहीं जान सकते। यह वही है जिसके बारे में हम जानते हैं। फिर भी\nसाथ ही हम अपनी क्षमता के अनुसार उसे सही मायने में जान सकते हैं।",
  "13.13": "सर्वतःपनीपादं तत् सर्वतः अक्षि शिरः मुखम्।\nसर्वतः श्रुतिमत लोकाय सर्वं अवर्त्य तिष्ठति-सर्वत्र इसके अंग; हर जगह\nआंखें-सिर-मुंह; इसे हर जगह सुनें; यह दुनिया के भीतर की हर चीज़ को कवर करता है।\n\nभगवान हर जगह है. उसके सर्वत्र हाथ-पैर हैं; पूरे कान, चेहरे, मुँह पर,\nआँख\nअलग शब्द इल्लाह 'मुंह' को दर्शाता है)। इस कारण हम प्रभु को नहीं जानते\nकुछ नहीं कर सकते. वह सर्वज्ञ, सर्वज्ञ, सर्वशक्तिमान है। यह सब ट्यून करें\nप्रमाणित करता है। भगवान ने ही आदि में वेदों का उच्चारण किया था। वह हर चीज़ के भीतर है\nवह बाहर ढंका हुआ खड़ा है. शाश्वत भगवान के भीतर उनके अनंत रूप हैं। हर एक को\nरूप में संज्ञानात्मक, रचनात्मक इंद्रियाँ भी होती हैं। हमारे सभी अर्थों में\nवह पूरी तरह से खड़ा है.\n\nसर्वेन्द्रियगुहाभासं सर्वेन्द्रियविवर्जितम् |\n\nअसक्तं सर्वभृचेव निर्गुणं गुणभोक्रु च",
  "13.14": "वह समस्त इन्द्रियों के विषयों को प्रकाशित करता है — किन्तु स्वयं भौतिक इन्द्रियों से रहित है। किसी से अनासक्त होकर सबका धारण करता है। त्रिगुणातीत है — फिर भी गुणों का भोक्ता है।\n\nयह भगवान् के क्षेत्रज्ञत्व का विरोधाभासी वर्णन। वे सब इन्द्रियों को चेतना देते हैं — स्वयं के भौतिक इन्द्रिय नहीं। सबका बोझ उठाते हैं — किसी से चिपकते नहीं। त्रिगुणों से परे हैं — फिर भी उनका अनुभव करते हैं। यह 'अचिन्त्य' — कारण-तर्क से परे — भगवान् का स्वभाव है।",
  "13.15": "बहि अन्तः च भूतानां आचारं चरम एव च।\n\nस्कृत्वात् तत् अविज्ञानं सुदृढ़ं च अंतिकाय च तत् - वह प्राणियों के बाहर है; अंदर\nवहाँ है; फिर भी हर जगह घूम रहा हूं. यह एक अणु के बजाय एक अणु है; वह अकेला ही जानकारीपूर्ण है। बस इतना ही\nदूर होकर भी सबके करीब है।\n\nभूत का अर्थ है संपूर्ण ब्रह्मांड, सभी जीवित प्राणी (पिंडंद)। भगवान इस ब्रह्मांड के भीतर हैं\nबाहर तो भरा हुआ है. जैसा कि नारायण उपनिषद में कहा गया है, “अंतरबहिश्च तत्-सर्वम् व्याप्य।\nनारायणः स्थितः”। वह प्रभु जो हममें व्याप्त है और हमारे भीतर और बाहर व्याप्त है-\nनारायण. एक छोटे से जीव से लेकर भीतर और बाहर चतुर्गुण ब्रह्म तक\nईश्वर पूर्ण है. वह हमारे भीतर एक मध्यस्थ के रूप में हमारा मार्गदर्शन कर रहा है\nऔर हमारे बाहर खड़े होकर हमें सम्भाला है। बुद्धिमानों के लिए उनके अंतरतम में एक दर्शन\nप्रभु जो देता है वह अज्ञानियों के लिए खुला है। सर्वव्यापी भगवान अचल है लेकिन वह अनंत है\nरूप सदैव गतिशील रहते हैं। ईश्वर संपूर्ण नैतिक जीवन में पूर्ण रूप से विद्यमान है।\nप्रभु कण-कण में भरे हुए हैं। ईश्वर सर्वज्ञ है परन्तु सर्वज्ञ नहीं। प्रभु का\nहम विस्तार से जान सकते हैं लेकिन पूरी तरह से नहीं। हम हैं\nसमुद्र में एक छोटी मछली की तरह. यह समुद्र की विशालता को कैसे नहीं जान सका?\nइस प्रकार, संसार का कोई भी जीव भगवान को पूर्ण रूप से नहीं जान सकता। क्योंकि यह हमारा है\nमन अकल्पनीय रूप से सूक्ष्म और विशाल है।",
  "13.16": "अविभक्तम् च भूतेषु विभक्तम् एव च ​​स्थितम् |\nभूतभर्त्रु च तत् ज्ञेयं गृहस्थ प्रभावविष्णु च - सभी प्राणियों में एक समान; हालाँकि\nयह किसी अन्य चीज़ की तरह ही विविध है। सभी प्राणी संजोते हैं; भक्षण\nऔर यह जानना चाहिए कि जन्म के समय जो अच्छा होता है वही होता है।\n\nईश्वर इस संसार के प्रत्येक जीवन में एक छवि के रूप में निवास करते हैं। एक के बाद एक\nवह जीवन में अनेक रूपों में विद्यमान है। यहाँ प्रत्येक जीव एक केन्द्रक है। लेकिन भगवान\nकेवल अखण्ड। ईश्वर जो सर्वत्र है वह एक है लेकिन हम अलग-अलग हैं\nबस यही दिखता है. इसका एक अच्छा उदाहरण भगवान के अवतार -परशुराम, वेदव्यास हैं\nऔर भगवान कृष्ण. यहां भगवान ने हमें एक साथ तीन रूपों में दर्शन दिये। हालाँकि वैसा ही\nवह भी हमें तीन के रूप में दिखाई दिये। वह समस्त जीवन के साथ-साथ समस्त जीवन के भीतर भी है\nवह इसे ले गया है. ईश्वर सभी का निर्माता है और एक दिन वह अपनी रचना को नष्ट कर देगा\nवह कर्ता है. विनाश के बाद सृष्टि का पुनर्निर्माण भी वही करते हैं।",
  "13.17": "ज्योतिषं अपि तत् ज्योतिः तमसः परमं उच्यते |\n\nज्ञानं ज्ञानं ज्ञानगम्यं हृदि सर्वस्य विष्ठितम् - यह सभी प्रकाशों में सबसे बड़ा प्रकाश है।\nअँधेरे से परे. यह ज्ञान का एक रूप है. वह स्वयं को जानता है। जानबूझकर\nप्राप्य है. ऐसा लगता है कि यह हर किसी के दिल में बसता है।\n\nकृष्ण ने अब तक जो समझाया है, उसे अपने ध्यान में देखना हमारे लिए कठिन है। इसीलिए कृष्ण\nउन्होंने कविता में भावनात्मक रूप से अपना वर्णन किया है। भगवान अंधकार के बिना प्रकाश है. उस प्रकाश के लिए एक\nकोई अवधि नहीं. यह अनंत है. महाज्योति वह भगवान हैं जो सभी ज्योतियों को प्रकाश देते हैं। भगवान\nजब हम आंखें बंद करके बैठते हैं तो हम ध्यान में अपनी पसंदीदा वस्तु या व्यक्ति को देखना चाहते हैं\nदेखा जा सकता है तो हमें उस व्यक्ति/वस्तु के भीतर ईश्वर को देखने का प्रयास करना चाहिए।\n(क्योंकि भगवान सर्वव्यापी है - वह हर चीज़ के अंदर और बाहर दोनों है)। बाद\n\"भगवान सूर्य में हैं, सौर ऊर्जा उनकी देन है\" का दृष्टिकोण रखना चाहिए। के बाद\nसूर्यमंडल के मध्य में भगवान के चरणों को देखने का प्रयास करना चाहिए। वह पैर का अंगूठा\n\nध्यान में हम देखते हैं कि प्रकाश सिरे से फूटकर हमारे हृदय में प्रवेश कर चमक रहा है\nअनुभव करना चाहिए. यह वह प्रक्रिया है जिसके द्वारा हम ध्यान में कदम दर कदम ईश्वर को देखते हैं। प्रभु यह\nजिसने संसार की सभी ज्योतियों को प्रकाश दिया। हमारे भीतर स्वयं को प्रकाशमान करने की क्षमता होना\nकेवल भगवान के लिए. ईश्वर का प्रकाश अंधकार से परे है। यह ज्ञान स्वरूप प्रकाश है।\nईश्वर ही ईश्वर का पूर्ण ज्ञाता है। हम उसे पर्याप्त शक्ति के साथ जान लेंगे\nप्रयास तो करना ही होगा. भगवान हमारे हृदय में निवास करते हैं। वह सबसे अजीब है\nहमारे हृतकमल के केंद्र में सूक्ष्म से भी सूक्ष्म वास है। हमारे पास ऐसा भगवान है\nइसे केवल भक्ति ज्ञान के माध्यम से ही महसूस किया जा सकता है।",
  "13.18": "इति क्षेत्रं तथा ज्ञानं ज्ञेयं च उक्तं समासतः |\nमत भक्तः एतत् विज्ञानाय मत भावय उपद्यते - इस प्रकार “क्षेत्र”-“ज्ञान” और 'ज्ञेय'\nऐसा लग रहा था जैसे संक्षेप में कहा गया हो. जो मेरा भक्त बनेगा वह मुझमें बना रहेगा।\n\nइस श्लोक में कृष्ण ने अब तक जो कुछ कहा है उसका सारांश देते हुए कहते हैं: “यह क्षेत्र है\nज्ञान के साधनों के बारे में, ज्ञान के इन साधनों के माध्यम से जाने जाने वाले भगवान के बारे में\n(In a nutshell) कहा गया था। सृजन, निर्मित संसार, संसार निर्माण का तरीका,\nसृष्टिकर्ता प्रभु- यदि आप यह जान लें तो फिर कुछ भी जानने को शेष नहीं रहता। पूर्ण\nकृष्ण कहते हैं, ''जो भक्त आस्था और भक्ति के साथ इसे महसूस करता है, वह मुझसे जुड़ जाता है।''\nज्ञान और भक्ति हमें मोक्ष की ओर ले जा सकते हैं।\n\nअगले श्लोक में कृष्ण मौलिक सृष्टि के विचार और उसके दृष्टिकोण की व्याख्या करते हैं। यह\nश्लोक अध्यात्म दुनिया में सृष्टि के बारे में सभी भ्रमों का कृष्ण का उत्तर है। सघन रूप से\nइस श्लोक के माध्यम से कृष्ण ने सब कुछ हमारे सामने प्रस्तुत कर दिया है।",
  "13.19": "प्रकृतिं पुरुषं च एव विद्धि अनादि उभौ अपि |\n\nविकारं च गुणं च एव विद्धि प्रकृति संभवन् - प्रकृति [शारीरिक और मानसिक प्रकृति] और\nजान लें कि पुरुष [जीव और ईश्वर] दोनों अजन्मे हैं। मैक्रोफॉर्म और गुणत्रय\nजानो कि प्रकृति का कार्य है।\n\nभगवान ने किसी भी जीव या प्रकृति की रचना नहीं की है। प्रकृति, आत्मा प्रकृति,\nपरमपुरुष (भगवान), अवन्तरपुरूष (जीवित प्राणी) सभी शाश्वत हैं। संसार का अर्थ है\nप्रकृति की विकृति. एक बच्चे के जन्म का मतलब यह नहीं है कि जीवन का निर्माण हुआ है। जीवन भर के लिए एक\nआकृति निर्माण. जीव एक आकृति बनाता है जहाँ पिता के शरीर का चेहरा माँ के गर्भ से जुड़ता है\nइस तरह मिलता है. भगवान प्रकृति के माध्यम से प्राणियों के लिए एक आकार बनाते हैं।\nसृष्टि के स्रोत पर भी, लक्ष्मीनारायण दुनिया के निर्माण के लिए माता-पिता के रूप में खड़े थे\nउसने चलाया। सृष्टि के आरंभ में जीव-जन्तु देवी लक्ष्मी के गर्भ में थे। लक्ष्मी देवी परमपुरुष\nवह भगवान के गर्भ में थी. सृष्टि के मूल में लक्ष्मी की खोपड़ी से होमी, भगवान हैं\nचतुर्मुख ब्रह्मा की उत्पत्ति नाभि से हुई। इस कारण चतुर्विध ब्रह्म\nकहा जाता है कि उनका जन्म लक्ष्मी के सिर और भगवान की नाभि से हुआ है। कुल मिलाकर\n\"जो प्रकृति जगत् का कारण है, वह नित्य है; उस प्रकृति से निर्मित जीवन भी शाश्वत है।\"\nदैनिक; इस प्रकृति और जीवन का कारण लक्ष्मीनारायण शाश्वत हैं; दुनिया\nइसका अर्थ है प्रकृति की अव्यवस्था\"। यही मुख्य बिंदु है जिसे हमें यहां जानना आवश्यक है।\n\nराशि से पहले सृष्टि के विस्तार के लिए आवश्यक ऊर्जा का निर्माण हुआ। एक ही प्रकृति का सबसे सूक्ष्म\nअसामान्य गुण. इस ऊर्जा कंपन से पूरी दुनिया बुझ गई। आकार दिया हुआ\nमाँ लक्ष्मी; जो आकार है वह जीवित प्राणी है; नारायण आकार के दाता हैं। इस कारण चतुर्मुख\nब्रह्मा से लेकर सभी दिव्य प्राणी लक्ष्मीनारायण की संतान हैं।\n\nउपरोक्त श्लोक में कृष्ण ने पुरुष और प्रकृति के बारे में बताया। [पुरुष का अर्थ है जीवात्मा और\nईश्वर प्रकृति अर्थात् भौतिक प्रकृति और आध्यात्मिक प्रकृति है]। सृजन प्रक्रिया में ये चार भूमिकाएँ\nकृष्ण हमें अगले तीन श्लोकों में स्पष्टीकरण देते हैं। पहले श्लोक में (slo-\n20) कृष्ण जीवात्मा-परमात्मा, जड़प्रकृति-चेतनप्रकृति का संपूर्ण विवरण देते हैं।\nफिर (श्लोक-21) केवल जड़प्रकृति और जीवात्मा का वर्णन देता है, तीसरा\nश्लोक (श्लोक-22) में सृजन की प्रक्रिया में। परमपुरुष और चेतनप्रकृति के चरित्र का\nवह स्पष्टीकरण हमारे सामने रखता है।",
  "13.20": "कर्म का कारण क्रिया है\n\nपुरुषः सुखः दुखानां भोक्पतवे हेतुः उच्यते - शरीर और इंद्रियों के निर्माण में।\nजड़प्रकृति [चेतना प्रकृति का श्री तत्व] कारण है। सुख-दुःख के अनुभव में\nजीर्णपरमाता ते कारण है।\n\nइस श्लोक में कृष्ण ने दो बातें कही हैं. हमारा एक शरीर है. शरीर में प्रसन्नता\nदु:ख भोग का अनुभव करने के लिए पांच इंद्रियां हैं। इस प्रकार शरीर, शरीर में इन्द्रियाँ-\nइंद्रियों के माध्यम से सुख और दुख का आनंद - यही जीवन है। उसने जीवन भर पहले ऐसा किया था\nकर्म के अनुसार कारण का लेखकत्व | अर्थात भगवान हमारे कर्म के अनुसार हैं\nजन्म के समय एक रूप दिया गया। हमारे माता-पिता हमारे शरीर के निर्माण की नींव हैं।\nहमारा शरीर प्रकृति से बना है। जगन्माता ही वह हैं जिन्होंने हमें माँ के गर्भ में यह रूप दिया\nश्रीलक्ष्मी. लक्ष्मी भगवान के लिए एक शरीर बनाती है। इस प्रकार शरीर के अंग और\nजीव इंद्रियों को प्राप्त कर उनसे सुख और दुख का अनुभव करता है। परमपुरुष\nभगवान जीवन को सुख-दुख का अनुभव कराते हैं। इस प्रकार शरीर में आत्मा और\nयदि जड़ प्रकृति शामिल है, तो भगवान स्वयं अवतार के रूप में जीवन के जुनून का अनुभव करते हैं\nवह खड़ा होकर देता है.",
  "13.21": "पुरुषः प्रकृतिस्थः हि भुंक्ते प्रकृतिजां गुणन |\n\nअरुणम गुनासंग अस्य सात असत योनि जन्मसु - प्रकृति, प्रकृति से बंधा हुआ जीवन\nवह सुख-दुःख आदि कर्मों को भोगता है। अच्छे और बुरे समय में जन्म लेना\nजीवन का कारण त्रिगुणों के समान ही है।\n\nप्रकृति निर्मित शरीर में ईश्वर हैं, देवता हैं। लेकिन शरीर में जो है वह सुख और दुःख है\nभोक्ता-जीव। शरीर का निर्माण प्रकृति द्वारा किया गया है। जीवन उसका है\nस्वभाव के अनुसार, पूर्व जन्म के कर्मों के अनुसार उसे इस जन्म में शरीर मिलता है।\n\nजैसा कि पहले उल्लेख किया गया है, जब जीव अपना शरीर छोड़ता है, तो वह गहराई से अवशोषित करता है -\nइसका अगला जन्म उसी के अनुसार तय होगा। अच्छी या बुरी योनि में\nजीवन के उत्पन्न होने के तीन कारण।",
  "13.22": "उपद्रष्टा अनुमन्ता च भर्ता भोक्ता महेश्वरः |\n\nपरमात्मा इति च अपि उक्तः देहे अस्मिन् पुरुषः परः - सब कुछ देखने वाला, सब कुछ देखने वाला।\nइच्छानुसार। सर्व-संचालन, सर्व-वाहक, सर्व-व्यापक-सर्वशक्तिमान\nईश्वर इस शरीर में जीवन के साथ सर्वोच्च व्यक्तित्व है।\n\nजब चित्त प्रकृति भौतिक शरीर से शरीर बनाती है, तो जीव उस शरीर में रहता है और इंद्रियों का आनंद लेता है\nदुःख सहना- सबको चलाने वाले के रूप में, सबके ऊपर और सबके करीब\nसाक्षात् दर्शन देने वाला भगवान पूर्ण व्यक्तित्व है। वह हमारे कर्म को जानता है। किस तरह का\nजो जानता है कि कर्म से क्या होगा। वह अन्दर बैठकर इस शरीर को प्रेरणा देता है\nखड़ा है तो निकल जायेगा तो शरीर गिर जायेगा। वह हमारे भीतर कितना दु:ख का स्पर्श है\nआनंद भोक्ता जो हमेशा बाहर आनंदित रहते हैं।",
  "13.23": "यः एवं वेत्ति पुरुषं प्रकृतिं च गुणैः भी।\nसर्वथा वर्तमान: अपि न सः भूयः अभिजायते - इस प्रकार प्रकृति-पुरुष गुणों से युक्त है।\nचाहे कोई अपना जीवन कैसे भी जिए, उसका दोबारा जन्म कभी नहीं होता।\n\nशाश्वत प्रकृति (जड़ और आत्मा), सभी का कारण भगवान का परम व्यक्तित्व है\nअधीनस्थ जीव जो गुणों सहित इसका एहसास करता है वह ज्ञानी है। इतना बुद्धिमान आदमी बाहर से कैसा होता है\nदिखावे के बावजूद सत्य की अनुभूति से उसे मोक्ष की प्राप्ति होती है। यहाँ बाहरी\nकृष्ण ने इस बात पर जोर दिया कि ज्ञान संस्कारों से अधिक महत्वपूर्ण है। मुखौटे के जीवन से कुछ भी नहीं\nकोई फायदा नहीं. उससे परे सत्य की प्राप्ति है। जब सच्चाई का एहसास होता है\n\nस्वयं ही यह अहसास हो जाता है कि सांसारिक संसार कितना निरर्थक है। ज्ञान से परे\nकोई अन्य पवित्र उपकरण नहीं है. कर्मानुष्ठान में अकास्मात् च्युति ज्ञान के मार्ग पर है\nइसका यात्री पर कोई असर नहीं पड़ता. ज्ञान उसका मार्गदर्शन करता है और उसे रोकता है\nउसे मोक्ष की प्राप्ति होती है.\n\nकृष्ण ने कहा कि प्रकृति और पुरुष को गुणों सहित जानना ही मोक्ष का मार्ग है। यदि ऐसा है\nइसे जानने का तरीका क्या है? कृष्ण इसे अगले दो श्लोकों में समझाते हैं।\nप्रभु से जुड़ने के कई तरीके हैं। हर किसी के लिए सब कुछ नहीं. क्योंकि जैसा कि कोई जानता है\nकिसी और को पता नहीं चलेगा. आइए कृष्ण की इस व्याख्या को सुनें।",
  "13.24": "ध्यानेन अता त् पश्यन्ति केचित् आत्मानं आत्माना |\nअन्ये सांख्येन योगेन कर्मयोगेन च अपारे - कुछ लोग ध्यान के माध्यम से भगवान को पाते हैं।\nवह अपने आप में अलग दिखते हैं. कुछ वैज्ञानिक ज्ञान के माध्यम से. कुछ कर्म योग के माध्यम से.\n\nसिद्धि प्राप्त करने के लिए सबसे पहले हमें साधना की आवश्यकता है। हीनायोनि पूर्ण नहीं है\nयदि आप एक शरीर में पैदा हुए हैं, तो आप कुछ हासिल नहीं कर सकते। सबसे पहले हमें इंसान बनना होगा।\nशरीर में रहने वाले पुरुष बनना चाहिए)। इसके लिए ''मानव जन्म महान है, इसे बर्बाद करो।''\nइसे मत खरीदो, मूर्खो! \"दशहरा के गीत। यदि किसी के पास सिद्धि के लिए आवश्यक साधना शरीर नहीं है\nकुछ भी संभव नहीं है.\n\nकुछ लोग अपनी योग्यता और ईश्वर की कृपा के कारण जन्मजात ज्ञान के साथ पैदा होते हैं।\nउसके पास ज्ञान है. ऐसे लोग अपने जीवन की योग्यता से अपने जीवन स्वरूप के भीतर - बिम्बारूपी होते हैं\nभगवान के दर्शन हो सकते हैं. ऐसे लोग हमेशा बिना किसी अध्ययन के भगवान का अनुसरण करते हैं\nभीतर देखना-प्रभु से जुड़ता है। ब्रह्मा सर्व देवता देवांश हैं\nसम्भूत इस प्रकार अपनी आँखें बंद करके भगवान को देख सकते हैं और उनसे जुड़ सकते हैं।\n\nकुछ लोग पहले शुद्ध आत्मतत्त्व विज्ञान के माध्यम से भगवान को जानते हैं। जीवन,\nईश्वर को जानना ही सांख्ययोग है। ऐसे ज्ञान प्राप्त करें, आत्मज्ञान प्राप्त करें, ध्यान प्राप्त करें\nइसके माध्यम से वे प्रभु को पाते हैं और प्रभु से जुड़ जाते हैं।\n\nकुछ अन्य लोग अपने निरंतर कर्मानुष्ठा द्वारा शारीरिक शुद्धता प्राप्त करते हैं, जो कि भगवान का है\nशिष्य बनें, ज्ञान प्राप्त करें, ध्यान में प्रभु को खोजें और प्रभु से जुड़ें।",
  "13.25": "अन्ये तु एवं अजन्न्तः श्रुत्वा अन्येभ्यः उपासते।\n\nते अपि च अतितरन्ति एव मृत्युं श्रुतिपरायणः - अब भगवान को इस प्रकार नहीं जानना।\nकुछ लोग जानने वालों से सुनकर पूजा करते हैं। जो सुनने पर भरोसा करता है वह सिद्धि लेकर भी चलता है\nबड़े हो जाओ और मृत्यु पर विजय प्राप्त करो।\n\nजनता, जो उपरोक्त किसी भी तरीके से हासिल नहीं कर सकते-दूसरों से सुनते हैं और सीखते हैं\nवह उपलब्धि की पहली सीढ़ी चढ़ सकता है। यह प्राप्ति के पथ पर सबसे निचला है\nसीढ़ी पर भी वह निरंतर सुन रहा है, ध्यानमग्न है, ध्यानमग्न है, अहंकारशून्य है, ज्ञानी है।\nउस ज्ञान को प्राप्त करके, कोई व्यक्ति ध्यान में भगवान को देख सकता है। आम आदमी के लिए यही कृष्ण हैं\nमोक्ष का मार्ग दिखाया। इस प्रकार उन्होंने श्रवण और आराधना से मृत्यु पर विजय प्राप्त कर ली\nप्रभु से जुड़ सकते हैं.",
  "13.26": "यावत संजयते किंचित् सत्वं स्थावर जंगमम् |\nक्षेत्र क्षेत्रज्ञ संयोगत तत् विद्धि भरतर्षभा -- भरतर्षभा, स्थिर-गतिशील प्राणियों में से कौन सा\nजान लें कि यदि जन्म हुआ भी है, तो वह क्षेत्र [श्रीतत्त्व] और क्षेत्र, भगवान के सहयोग से है।\n\nइस संसार में जो कुछ भी जन्मा है, सभी स्थावर-जंगम जड़ जगत् हैं और\nइसके उपासक प्राकृत देवी मिलकर इसे क्षेत्र कहते हैं। ये सब जानता है\nप्रभु जो क्षेत्र विशेषज्ञ हैं। तो क्षेत्र भगवान द्वारा निर्मित संपूर्ण जीवित शरीर है\nविश्व समस्त सृष्टि का निर्माण लक्ष्मी नारायण के सहयोग से हुआ था। वे इस दुनिया के हैं\nपहला जोड़ा. तो सबके माता-पिता नारायण और श्रीलक्ष्मी हैं। “यह जानकर\n\nतुम असली भरतर्षभ बन जाओगे,'' कृष्ण कहते हैं।\nजिसमें पूर्ण भक्ति है वही भरतर्षभ है।",
  "13.27": "",
  "13.28": "समं पस्यां हि सर्वत्र समवस्थितं ईश्वरम् |\n\nन हिनास्ति आत्मान आत्मानं ततः याति परम गतिम् - सर्वशक्तिमान भगवान हर जगह हैं।\nबिना उतार-चढ़ाव के.. वह एकरूप है.. जैसे. जो जानता है वह अपनी समृद्धि के लिए स्वयं है\nरास्ते में मत आओ. आगे उसे परम वचन की प्राप्ति होती है।\n\nहम अपने शरीर में स्थित हैं। लेकिन प्रभु \"समाविष्ट\" हैं। हम जो इस शरीर में हैं, इस शरीर के हैं\nकोई ज्ञान नहीं है. हम कभी नहीं जानते कि हम कहाँ हैं। हम अंदर ही अंदर सुख और दुख का अनुभव कर रहे हैं।\nलेकिन भगवान दुख अज्ञान के स्पर्श से रहित आनंदमूर्ति हैं। वह हमारे बीच के परोपकारी व्यक्ति हैं।'\nवह देवताओं के साथ सामंजस्य में ऊंचा है। दुःख और अज्ञान के स्पर्श के बिना किसी को भी भगवान द्वारा स्पर्श नहीं किया जाता है\nश्रेष्ठता या हीनता की दृष्टि से मत देखो. प्रत्येक का अपना कर्म और जीवन शक्ति है\nवह बराबरी का दिखता है. भगवान हमारे जगदीश्वर हैं जो सभी जड़-भूतों के भीतर स्थित हैं\nवह हमें जीवन की प्रकृति के अनुसार, कर्म के अनुसार संचालित कर रहा है। जब आप इस सत्य को जानते हैं, “आप\nकृष्ण कहते हैं कि आप हिंसा के बिना भी रह सकते हैं। आपकी जागरूकता के बिना, ईश्वर की जागरूकता के बिना\nजीना यातना है. एक बार \"मैं क्या हूँ\" और मेरे भीतर भगवान क्या है\nअगर आप हकीकत जान लें तो कोई हिंसा नहीं होगी. यह जाने बिना जीना अज्ञानता और दुख का जीवन है।\nजीवन में जो कुछ भी घटित होता है - \"मेरे पिछले कर्मों का परिणाम - वह भगवान है।\"\nयदि आप जानते हैं कि आपने यह किया है, तो आप बिना कष्ट के खुशी से रह सकते हैं। हम अपने मन हैं\nदुःख देना वही सुख देना। हम अपनी समझ के कारण दुःखी हैं\nलेकिन किसी और चीज़ से नहीं. उदाहरण के लिए, एक अमीर आदमी किसी कारण से अपने कब्जे में है\nसारी संपत्ति खो देता है. तब उन्होंने कहा, “यह घटना मेरे पूर्व जन्म के कर्म के अनुसार है\nघटित हुआ सब प्रभु की लीला है; वह दाता है, और वह लेने वाला है;\nवह वही है जो आज्ञा का पालन करता है; उन्होंने कहा, ''मुझे इस बारे में चिंता क्यों करनी चाहिए.''\nखुश हो सकते हैं. इसके अलावा, यदि ब्रह्मांड ऐसा व्यवहार करता है जैसे कि वह अपने सिर पर गिर गया है, तो वह हम हैं\nजैसे हमें प्रताड़ित किया गया. हमें हर चीज़ को एक दर्शक के रूप में देखने का अभ्यास करना चाहिए। प्रभु का\nजागरूकता के साथ ऐसा शांतिपूर्ण जीवन हमें सर्वोच्च मोक्ष की ओर ले जा सकता है।\n\nअगले श्लोक में कृष्ण हमें भगवान के विचार का एक और पहलू प्रस्तुत करते हैं।\nअगर हम इस श्लोक को ध्यान से देखें तो हमें सच्चाई का पता चल जाएगा। यह हम सभी में है\nएक भ्रम यह है- \"क्या मैं कर्म करता हूँ या भगवान मुझसे कराते हैं?\"\nयदि ईश्वर ऐसा कर सकता है, तो वह मुझसे कुछ बुरा क्यों करवाता है?” इस सवाल का जवाब कृष्णा ने दिया\nइसका जवाब उन्होंने इस श्लोक में दिया है. यहाँ वापस. कृष्ण ने क्या कहा\nहमें इस श्लोक को ध्यान से देखने की जरूरत है.",
  "13.29": "",
  "13.30": "प्रकृति एव च ​​कर्माणि क्रियमाणानि सर्वषा |\n\nयः पश्यति तथा आत्मानं अकर्तारं सः पश्यति - सभी कर्म स्वभावतः।\nहो रहे हैं [जीवन के कर्म के अनुसार भगवान स्वयं सभी गतिविधियों में हस्तक्षेप करते हैं और नेतृत्व करते हैं]\nवह जो यह जानता है और कुछ भी करने के लिए स्वतंत्र नहीं है [भगवान के लिए एक और कारण\nवह जो जानता है कि कोई पुरुष नहीं है] वह \"वास्तव में ज्ञाता\" है।\n\nकृष्ण कहते हैं, \"जो जानता है कि 'मैं' नहीं कर रहा हूं, वह जानता है\"।\nइसलिए सबसे पहले हमें \"मैं कर रहा हूँ\" अहंकार को छोड़ना होगा। मैं हूं\nऐसा करना केवल एक व्यावहारिक सत्य है, पारलौकिक सत्य नहीं।\nउदाहरण के लिए: \"मैं बोल रहा हूँ\"। मैं यहां बोलने वाला पहला व्यक्ति हूं\nमूर्ख मत बनो. . उसके लिए। मनुष्य का शरीर उचित अंगों से युक्त होना चाहिए।\nबोलने के लिए, मेरा दिमाग चीजों को सही समय और संदेश पर सोचता है\nअग्रेषित किया जाना चाहिए. इसका मतलब है कि मुझे इसके लिए सही मस्तिष्क शक्ति की आवश्यकता है। मैं बोलने का साहस करता हूं\nअब आइए अपने आप से प्रश्न पूछें: मेरे पास एक मानव शरीर है जो बोल सकता है\nकिसने दिया? किसने मुझे विचारशील मस्तिष्क प्रदान किया और डिज़ाइन किया? समय में\nवास्तव में इस मस्तिष्क से संदेश किसने प्रसारित किया? बोलने की अद्भुत कला\nयह मुझे किसने दिया? इन सभी प्रश्नों से हम जो जानते हैं वह है: “मेरे भीतर\nयह सत्य है कि प्रभु ने खेला-मैंने खेला। यही बात भगवान यहाँ समझाते हैं\n\"प्रकृत्येव च कर्माणि क्रियमाणानि सर्वशः\"। उनकी जीव प्रकृति को।\nतदनुसार, प्रकृति (त्रिगुणों) के प्रभाव में, प्राकृत पुरुष (लक्ष्मीनारायण) हमसे।\nकर्म हो गया. इसलिए, जीवन की प्रकृति के अनुसार जो शाश्वत रूप से जीवन में आया\nउसका शरीर रचा गया; तदनुरूप उस पर वातावरण के त्रिगुणों का प्रभाव; त्रिगुणों का\nउनके सभी प्रकार के कर्म प्रभाव के रूप में हैं। इन सबका कर्ता-धर्ता- देवताओं का स्वामी,\n\nलक्ष्मी के साथ नारायण.\n\nयदा भूतपृथग् भावमेकस्थमनुपश्यति।\nतत एव च ​​विस्तारं ब्रह्म संपद्यते तदा 130।\n\nयदा भूत पृथक भावं एकस्गम अनुपश्यति।\nततः एव च ​​विस्तारं ब्रह्म सम्पद्यते तदा - सभी जीव एक ही भगवान में निवास करते हैं।\nकि, जब उसे पता चलता है कि इस प्रकार का बीज उसी का है, तो वह प्रभु से जुड़ जाता है।\n\nजीवन शाश्वत है. सृजन और विनाश तो दृश्य रूप मात्र हैं। प्रजाति\nहर एक पृथक भव है। कोई भी दो प्रजातियाँ 100% समान नहीं हैं। इनमें से कई\nजीवन का समुदाय एक ही प्रभु में है। सृष्टि के समय यह प्रभु के गर्भ से निकला\nजीवन के जो रूप आकार लेते हैं वे जलप्रलय के दौरान सूक्ष्म रूप में भगवान के गर्भ में लौट आते हैं\nहमें इसे संदर्भ में लेना होगा। इस बात को कौन समझ पाता है\nयदि वह ऐसा कर सके तो मोक्ष प्राप्त कर सकता है।\n\nअनादित्वान्निर्गुणत्वात् परमात्मकायमवियः।\n\nशारिसाथोऽपि कौन्तेय करोति न लिप्यते",
  "13.31": "अनादित्वात् निर्गुणात्वत् परम आत्मा अयम् अव्ययः।",
  "13.32": "शरीरस्थः अपि कौन्तेय न करोति न लिप्यते - कौन्तेय, सर्वोच्च सत्ता जो कभी पैदा नहीं होती;\nजो गुणों से आसक्त नहीं है; इससे वह नहीं मरता. वह शरीर के अंदर जो कुछ भी है\nनहीं करता; इससे कुछ भी चिपकता नहीं है। जड़\nमैं किस बारे में बात कर रहा हूँ! वह सब कुछ करता है; कुछ भी नहीं चिपकता।]\n\nएकमात्र चीज जो निर्विकार है वह भगवान है। वह कभी भी किसी विशेष कारण से नहीं\nभगवान त्रिगुण्यवर्जिता का जन्म नहीं हुआ। इस कारण उसमें कभी परिवर्तन या कुरूपता नहीं आती। वह है\nयद्यपि वह सभी जीवित प्राणियों में अवतरित है, फिर भी उसे शरीर से कोई लगाव नहीं है। वह सब हममें से हैं\nकरता है लेकिन किसी बात पर अड़ता नहीं है. वह हर काम वैराग्य से करता है लेकिन\nउसका किसी भी चीज़ के लिए कोई दोष नहीं है। यह समझने के लिए कि यह कैसा है - कृष्ण एक हैं\nअगले श्लोक में वे उदाहरण देकर समझाते हैं।\n\nयथा सर्वगतं सौक्ष्मदकसं नोपलिप्यते।\nसर्वत्रवस्थितो देहे तथा$5त्मा नोपलिष्यते ॥302॥\n\nयथा सर्वगतम् सौक्ष्मत् आकाशम् न उपलिप्यथे |\n\nसर्वत्र अवस्थितः देहे तथा आत्मा न उपलिप्यथे - यद्यपि आकाश सर्वत्र है\nचूँकि यह अत्यंत लचीला है, यह किसी भी अन्य चीज़ से नहीं चिपकता - यहाँ तक कि सर्वोच्च सत्ता से भी नहीं\nसभी शरीर भरे हुए हैं लेकिन चिपचिपे नहीं हैं।\n\nहर जगह आसमान है. इसके बिना कोई जगह नहीं है. ऐसे आकाश में सर्वत्र कोई भी वस्तु कैसे चिपकी नहीं रह सकती\nफिर भी, भले ही भगवान सभी शरीरों में मौजूद हैं, फिर भी वे किसी भी चीज़ से अनासक्त हैं।\n\nयथा प्रकाशयत्येकः कृत्स्नं लोकमिमान रविः |\nक्षेत्रं क्षेत्रं तथा कृत्स्नं प्रकाशयति भारत",
  "13.33": "यथा प्रकाशयति एकः कृत्स म लोकं इमाम रविः।\n\nक्षेत्रं क्षेत्रं तथा कृत्स्नं प्रकाशयति भारत -भारत, एक सूर्य एदि\nअकेले भगवान, “क्षेत्रज्ञ”, ने पृथ्वी को प्रकाशित करने के लिए “क्षेत्र”, ब्रह्मांड पर प्रहार किया।\nचमकता\n\nजिस प्रकार एक ही सूर्य सम्पूर्ण ब्रह्माण्ड को प्रकाशित करता है, उसी प्रकार भगवान भी सम्पूर्ण जगत को जानने वाले हैं\nप्रकाशित करता है हमें सबसे पहले ईश्वर के प्रकाश (ज्ञान) को जानना चाहिए। तब हमारे भीतर प्रकाश\nहम समझते हैं.",
  "13.34": "क्षेत्र क्षेत्रज्ञो एवम् अन्तरं ज्ञानो चक्षुषा।\n\nभूत प्रकृति मोक्षं च ये विदुः यन्ति ते परम - क्षेत्र-क्षेत्रज्ञों के बीच का यह अंतर,\nपंचभूतों से और प्रकृति से [जीवित प्राणी को प्रकृति से] मुक्ति दिलाई।\nजो लोग ज्ञान के मार्ग पर चलते हैं वे परम को प्राप्त करते हैं।\n\nयह श्लोक इस अध्याय को समाप्त करता है। फील्ड क्या है, फील्ड एक्सपर्ट क्या है, फील्ड और फील्ड एक्सपर्ट क्या है\nइनमें क्या अंतर है; मोक्ष साधक को जीवजता जड़ से मुक्त होना चाहिए\nगुण - जो लोग इन सभी को महसूस करते हैं और उन्हें अभ्यास में लाते हैं वे सर्वोच्च भगवान रहते हैं\nशामिल हो जायेंगे\nइति त्रयोदशोऽध्यायः\nतेरहवाँ अध्याय समाप्त हो गया\n\nक्या यह सच है?\n\nअध्याय चौदह\n\nयद्यपि गीता में यत्र-तत्र उपलब्धियों का उल्लेख किया गया है, परन्तु वह ईश्वर का स्वरूप है\nमहिमा की चर्चा अक्सर होती रही है. हम भगवान की ऐसी पूजा के चेहरों का वर्णन करते हैं\nइसके बाद देखा गया. बारहवें अध्याय (श्लोक-05) में कृष्ण कहते हैं, \"श्रीतत्व की पूजा महान है\nकठिनाई, यह सीधे रास्ते को छोड़कर घूम-घूम कर ईश्वर तक यात्रा करने जैसा है, साधक यही करते हैं।\nइसे बड़ी कठिनाई से प्राप्त करना पड़ता है''-चेतावनी दी। तेरहवें अध्याय (श्लोक-26) में-\n\"जो कुछ भी सिरा और जीवित प्राणियों से पैदा हुआ है वह क्षेत्र [श्रीत्व] और क्षेत्रज्ञ [भगवान] का है।\nयह एसोसिएशन द्वारा है।” आमतौर पर जब सृष्टि की बात आती है तो ईश्वर ही सृष्टि है\nहम कहते हैं 'हो गया'। यहां लक्ष्मी का कोई जिक्र नहीं है. लेकिन पिछले अध्याय में कृष्ण\nस्पष्ट रूप से कहा गया है: \"यह सृष्टि लक्ष्मीनारायण के विवाह का फल है\"। इस रचना के कारण\nउत्पत्ति के चिंतन में एक साथ लक्ष्मीनारायण की स्तुति करना महान है। लक्ष्मी की स्तुति करते हुए\nइसके अलावा आचार्य ने कहा कि नारायण की स्तुति करनी चाहिए और लक्ष्मी की स्तुति करनी चाहिए\nयह भजन में स्पष्ट रूप से दर्शाया गया है। वहां देवी लक्ष्मी की स्तुति 'श्रीसपुति' कहती है:\nविश्वस्तिप्रथालयसर्गमहवभूति वृत्तिप्रकाशनीयमवृत्ति बंधमोक्षः |\nयस्य अपांगलवमात्रत उर्जिता स श्रीः यत्कटक्षबलवत्यजितं नमामि ॥ 1",
  "13.35": "[बन्नञ्जे गोविन्दाचार्य के भाष्य में अध्याय 13 में 34 श्लोक हैं। यह 13.35 उनके पाठ में नहीं है — पिछले श्लोक में समाहित। अध्याय 13 का सार — क्षेत्र-क्षेत्रज्ञ विभाग तथा ज्ञान से मुक्ति — इसी के साथ पूर्ण होता है।]",
  "14.1": "अर्थात, ''लक्ष्मि अपनी पैनी नजर के बल से ऐसे सृजन, संहार और संहार करती हैं।''\nलक्ष्मीपति नारायण को नमस्कार है। यहां लक्ष्मी का संपूर्ण भजन है\nऐसी लक्ष्मी के पति नारायण के रूप में वर्णित है। इसलिए\nलक्ष्मीनारायण की स्तुति लक्ष्मी स्तुति है, केवल लक्ष्मी स्तुति नहीं। इसके लिए मूल गीत\nअध्याय बारह, तेरह और चौदह। बारहवें अध्याय में केवल लक्ष्मी उपासना\nयदि चेतावनी है कि वह ओली है, तो यह संसार तेरहवें अध्याय में है\nलक्ष्मीनारायण के संयोग से निर्मित - अत: हम सब उनकी संतान हैं\nएक सन्देश है. सृष्टि की प्रक्रिया में लक्ष्मी का भगवान के साथ कैसा संबंध है?\nचौदहवाँ अध्याय स्पष्ट करता है। लक्ष्मी, श्री भू-दुर्गा इन तीन रूपों में सत्त्व-रजसु-\nतमोगुण की नियंत्रक शक्ति होने के कारण - उनके पुत्र सात्विक-राजस-तमस हैं।\nतीन प्रकार. इस अध्याय में पहली बार इस मुद्दे का उल्लेख किया गया है। पिछले में से कौन सा\nअध्याय में भी त्रिविद्या का वर्णन उतना स्पष्ट नहीं है। हम इन त्रिगुणों का विश्लेषण करते हैं\nहमारे अंदर के रजस और तमस पहलू को कैसे सात्विक तरीके से ठीक करें\nइस अध्याय में हम इस तथ्य को देख सकते हैं कि उपलब्धि प्राप्त की जा सकती है।\n\nभगवान का वचन\nपरं भूयः प्रवक्ष्यामि ज्ञानं ज्ञानमुत्तमम् |\nयज ज्ञात्वा मुनयः सर्वे परमं सिद्धिमितो गतः ॥1॥\n\nभगवान उवाच- भगवान ने कहा:\n\nपरं भूयः प्रवक्ष्यामि ज्ञानं ज्ञानं उत्तमम् |\n\nयत् ज्ञात्वा मुनयः सर्वे परम सिद्धिं इतः गतः - जानने योग्य सबसे महान वस्तु।\nमैं आपको और अधिक बताऊं; सभी ऋषियों ने इसे देखा और यहीं से परमपद प्राप्त किया।\n\nकृष्ण कहते हैं: \"मैं तुम्हें और बताऊंगा\"। यह बहुत ही महत्वपूर्ण शब्द है. आमतौर पर शिष्य\nगुरु आग्रह करने पर भी नहीं कहते. गुरु को शिष्य की ज्ञान पिपासा को देखकर बताना चाहिए\nमहसूस करना चाहिए और ख़ुशी से कहना चाहिए. तब वह ज्ञान शिष्य के लिए फलदायी होगा। इस प्रकार ज्ञान\nसच्चा ज्ञान वह ज्ञान है जो गुरु तृषा को देखकर प्रसन्न होकर बोलते हैं। यहाँ कृष्ण स्वयं अर्जुन से कहते हैं\nवह असाधारण ज्ञान बता रहे हैं. कृष्ण कहते हैं: “पूर्वोक्त क्षेत्र (प्रकृति-लक्ष्मी) और\nक्षेत्रनारायण) मैं और अधिक विस्तार से समझाऊंगा। क्योंकि इसे जानने की जरूरत है\nइस मामले में सबसे महत्वपूर्ण मुद्दा है।” इस संसार के निर्माण के पीछे माता-पिता के रूप में\nलक्ष्मी-नारायण हैं। तो सिर्फ पिता की याद, या सिर्फ माँ की याद\nकरने से बेहतर है कि माता-पिता की स्मृतियों को जानें। कृष्ण कहते हैं: “यह\nआइए आपको मामला विस्तार से बताते हैं. क्योंकि यह मोक्ष प्राप्त करने वाला व्यक्ति है\nयह अवश्य जानने योग्य बात है।\nलक्ष्मी-नारायण को सृष्टि का स्रोत माने बिना मुक्ति असंभव है। “यह साधना\nयहां तक कि वे ऋषि भी जो पृथ्वी पर पैदा हुए और ब्रह्म अनुभूति प्राप्त कर चुके हैं, जानते हैं कि यह सर्वोच्च जीवन है\nसिद्धि का मोक्ष मिल गया\" कृष्ण कहते हैं। यह अगले श्लोक में बहुत स्पष्ट है\nसमझाया.",
  "14.2": "इदं ज्ञानं अपसृत्य मम साधर्म्यं अगतः।\nसुरगे अपि न उपजायन्ते प्रलय न व्यथन्ति च - इस ज्ञान को प्राप्त करो और मुझसे छुटकारा पाओ।\nसृष्टि के समय समानताएँ उत्पन्न नहीं हुईं; इससे बाढ़ के समय कोई नुकसान नहीं होता है।\n\nइस श्लोक में 'अपाश्रित्य' शब्द का विशेष अर्थ है। \"अन्यत् सर्वम्\"।\nअपाहयाश्रयणं-अपाश्रयणः भगवान में \"दूसरा कोई नहीं है - आप ही मेरी शरण हैं\"।\nआश्रय प्राप्त करने को यहां 'अपाश्रित' कहा जाता है। जैसा कि द्वादश स्तोत्र कहता है:\n\nकुरु भूङ्क्षश च कर्म निजं नियतं हरिपदाविनाम्रधिया शतधाम |\n\nहरिरेव परो हरिरेव गुरुः हरिरेव जगत्पितृमातृगतिः ॥ 1\nयह 'अपाश्रित्य' शब्द का मूल अर्थ बताता है। यहाँ कृष्ण कहते हैं: \"लक्ष्मी-नारायण\nजो जगत् के माता-पिता के ज्ञान से मुझे भजते हैं, वे मेरे ही समान दिव्य स्वरूप हैं\nउन्हें मिलेगा।” ऐसे लोग सभी दोष खो चुके होते हैं और त्रिविध अवस्था में होते हैं\nवह भगवान से जुड़ जाता है और भगवान में ही निवास करता है। यह संसार लक्ष्मी-नारायण द्वारा रचा गया है\nऔर जाओ और उनसे जुड़ जाओ. जो इसे जानता है वह जन्म और मृत्यु से परे हो सकता है। वह कभी वापस नहीं आया\nयह पारिवारिक बंधन अटूट है. यहाँ 'उपजायते' शब्द का प्रयोग हुआ है। संस्कृत में\n\"उप\" का अर्थ है \"श्रेष्ठ\"। जर्मन\nयह भाषा में है. \"606ga\" है। कन्नड़ में उपरी का अर्थ है \"उप\" - \"ऊपर\"।\nदेता है]। तो \"उपजायते\" का अर्थ है श्रेष्ठ जन्म। यह प्रभु की जागरूकता है\nशारीरिक मुद्रा के साथ जन्म लेना ही उच्च जन्म है। आध्यात्मिक उपलब्धि से जन्म ऊंचा\n\"उपपीढ़ी\"। जिसने अपने जीवनकाल में इस सृष्टि के स्रोत का ज्ञान प्राप्त कर लिया उसका दोबारा जन्म नहीं हो सकता।\nवह भगवान में निरंतर बने रहने के सर्वोच्च शब्द को प्राप्त करता है।",
  "14.3": "मम योनिः महत् ब्रह्मा तस्मिन् गर्भं दधामि अहम्।\nसम्भवः सर्वभूतानां ततः भवति भारत - चेतना प्रकृति मेरी अर्धांगिनी है। उसमें सृजन\nबीज बोओ. भरत, समस्त प्राणियों का जन्म इसी से होता है।\n\nयहां कृष्ण बड़ी अजीब बात कहते हैं. यदि हम इस श्लोक को समझना चाहते हैं, तो हम\nपहले 'भा-रता' बनना चाहिए. 'रत' का अर्थ है दर्शन। हमें प्रभु में विश्राम करना चाहिए; ज्ञान का\nरास्ते पर होना; भक्ति के धनी बनो और पूर्ण दाता बनो; विनम्र होना। फिर\nसृष्टि का यह रहस्य समझ में आ गया।\n\nकिसी भी वस्तु के निर्माण के लिए एक से अधिक कारणों का होना आवश्यक है। अगर सुस्त है\nवहाँ दो कारण आवश्यक हैं, उदाहरण के लिए यदि एक घड़ा बनाना है तो एक जड़ है (Raw materials) वांछित और आकार देने वाला कुम्हार चाहिए। वनस्पति की रचना- जड़ के भीतर भगवान\nजीवन जोड़कर. लेकिन 'आत्मा रचना' को जो गर्भ से जन्म लेती है\nपदार्थ से निर्मित होने के लिए एक नर और एक मादा की आवश्यकता होती है। वे दोनों\nएक तीसरा संघ द्वारा निर्मित होता है।\nइस श्लोक में 'योनि' और 'ब्रह्म' 'मम योनिः महत् ब्रह्मा' में आते हैं।\nशब्द वे शब्द हैं जिनके अनेक अर्थ होते हैं। किस स्थिति में कौन सा अर्थ मेल खाता है\nयह जानकर हमें श्लोक को समझना चाहिए। योनि - कारण, जन्म स्थान, पत्नी\nआदि अर्थ देता है। इसी प्रकार ब्रह्म- जीव, चतुर्मुख, लक्ष्मी, भगवान आदि अनेक हैं\nइस श्लोक में... अर्थ बताता है. योनि का अर्थ है पत्नी; इसका अर्थ है 'महत ब्रह्मा'\nश्रीलक्ष्मी जो चतुर्मुख की माता भी हैं। कृष्ण कहते हैं, “मैं चित्त प्रकृति हूं, अपनी पत्नी हूं\n(मैं लक्ष्मीना को गर्भवती करूंगा। वह गर्भ बड़ा होगा और सभी जीवित प्राणियों का निर्माण होगा।)\nयह हमारे लिए कुछ नया है. चूँकि चतुर्मुख की रचना ऋग्वेद में इस प्रकार कही गई है:\n\nतमिद्गर्भं प्रथम दधरा आपो यत्र देवः समगच्छन्त विश्वे।\n\nअजस्य नाभावध्येकमरपितां यस्मिन्विश्वानि भुवनानि तस्तुः॥ 10.82.06\nयहाँ कहा गया है कि \"ब्रह्मा भगवान के नाभि कमल से निकले\"। चतुर्मुख से जीव\nसृष्टि का निर्माण हुआ. तो हम चारों लोकों के पिता का विचार भी जानते हैं।\nवेद में अन्यत्र (अम्ब्रिनिसुक्र) कहता है:\n\nअहं सुवे पितरमस्य मूर्धन मम योनिरप्सा\n\nततो वी तिष्ठे भुवनानु विश्वो-तमौं द्यं वर्षमाननोपा स्पृशमि | 7\nलक्ष्मी यही कहती हैं: \"मैंने इस संसार के पिता चतुर्मुख को अपने माथे पर रखा है-\nबैताले से व्युत्पन्न)। यहोवा जिसने मुझे जन्म दिया वह समुद्र में है। संपूर्ण ब्रह्मांड का\nदूसरी ओर यह भी कहा जाता है कि सृष्टि की रचना शिव ने की थी। यदि आप शास्त्र प्रक्रिया को नहीं जानते तो यह सब व्यर्थ है\nभ्रमित मोक्ष प्राप्त करने वालों को इसका बारीकी से विश्लेषण करना चाहिए - तभी यह सत्य है\nसाकार हो जायेगा.\nजीव-प्रकृति-भगवान अनादि और अनंत। सृष्टि से पूर्व सारा संसार सूक्ष्म रूप में भगवान का था\nपेट में था. यदि हम इसे और अधिक बारीकी से देखें - संपूर्ण ब्रह्मांड देवी लक्ष्मी के गर्भ में था और\nलक्ष्मी भगवान के गर्भ में थीं। भगवान लक्ष्मी के गर्भ में सभी जीवित प्राणियों का बीजारोपण होता है\nकमल स्वरूप सम्पूर्ण ब्रह्माण्ड भगवान की नाभि से लेकर लक्ष्मी की खोपड़ी तक है\nइसमें चतुर्मुख के साथ-साथ सभी देवता और जीवित प्राणी अव्यक्त रूप में हैं\nइस कारण उत्पन्न हुए लक्ष्मीनारायण ब्रह्माण्ड के माता-पिता हैं। हम यहाँ हैं\nसमझने योग्य एक महत्वपूर्ण बात यह है कि सृजन एक चरण-दर-चरण प्रक्रिया है। लक्ष्मी\n\nनारायण की सभा से जो कुछ उत्पन्न होता है वह अव्यक्त रचना ही है। फिर चतुर्गुण ब्रह्मा तो यह है\nसूक्ष्म अव्यक्त संसार (जीवित प्रजाति) को मूल स्थूल रूप दिया गया है\nउन्हें पिता जैसा महसूस हुआ. और फिर इस संसार ने शिव से पूर्ण स्वरूप प्राप्त किया। यह\nयदि हम प्रक्रिया को समझ लें तो यहां कोई भ्रम नहीं है। चतुर्मुख लक्ष्मी\nखोपड़ी से जन्मा हाँ; वह भगवान की नाभि से पैदा हुआ है; वह विश्व का पिता है\nहाँ; हाँ, इस स्थूल संसार की रचना शिव ने की है; लक्ष्मी नारायण ही सब कुछ हैं\nहाँ, जीव के माता-पिता। इसके बारे में विवरण 'महाभारत तात्पर्यं निर्णयम्' में है।\nस्पष्ट रूप से समझाया गया.\n\nएक चेतना [भूति (श्रेष्ठ) जीव] के निर्माण के लिए एक पुरुष और एक महिला का मिलन आवश्यक है।\nयह एक ऐसी परंपरा है जो सृष्टि के आरंभ से ही विकसित होती चली आ रही है। दुनिया की सारी रचना के पीछे\nलक्ष्मीनारायण पिता और माता के रूप में खड़े हैं। इस बात को कृष्ण ने और भी स्पष्ट किया है\nवह श्लोक में बताते हैं.",
  "14.4": "सर्वयोनिषु कौन्तेय मूर्तियः संभवन्ति यः।\n\nतसं ब्रह्म महत् योनिः अहं बीजप्रदः पिता-कौन्तेय, सब बसिरों में\nजो भी रूप बनते हैं- उनके लिए आत्मा ही माता है; मैं खुद ही बीज बोता हूं\nपिता\n\nसिर्फ देवदूत, सिर्फ इंसान नहीं। सभी प्राणियों के जन्म के पीछे पिता और माता के रूप में लक्ष्मी-\nनारायण हैं. प्रकृति लक्ष्मी सबकी माता-आत्मा है। नारायण वह पिता हैं जो बीज बोते हैं। धड़\nजैसा कि उपनिषद कहते हैं:\nपुमान रेतः सिंचति योपितयं बह्विः प्रजाः पुरुषात् सम्प्रसुतः ॥| 2.2.5\n\nयहां 'पुमान' का अर्थ भगवान है जो विशेष रूप से मनुष्य में मौजूद है और 'योशिता' का अर्थ है\nस्त्रियों में लक्ष्मी विशेष रूप से विद्यमान रहती हैं। जैसे ही बीज खेत में बोया जाता है, वह वहीं वास्तविक होता है\nसहनशील स्वरूप, प्रकृति के प्रशंसक, श्री लक्ष्मी में भगवान का बीजारोपण होता है।\nक्या मां लक्ष्मी उस बीज को एक आकार देती हैं. ये तरीका कितना बढ़िया है. यह\nइसी कारण से प्राचीन विद्वान गर्भवती स्त्री के शरीर को मंदिर कहते थे, उस गर्भवती स्त्री को\nजिस स्थान पर गर्भ है वह गर्भ के समान है, जो उस गर्भ के भीतर जीवन को विकसित कर रहा है।\n\nउन्हें भगवान की तरह सम्मान दिया जाता था. यह हमारे पूर्वजों के प्रत्येक कार्य में भगवान है\nभव्यता के निकट। एक महिला तब मंदिर बन जाती है जब वह गर्भवती हो जाती है। तो महिला\nसबसे बड़ा डर माँ बनने का होता है. उसकी इच्छा का अंतिम लक्ष्य मातृत्व है।\nजब वह गर्भवती होती है तो उसमें लक्ष्मी पूर्ण रूप से विद्यमान हो जाती है। इस वजह से\nविवाह लक्ष्मीनारायण की पूजा है। विवाह एक पुरुष और एक महिला का मिलन है\nलक्ष्मीनारायण समागम. यहाँ हमारा सौभाग्य है कि ईश्वर हमें एक माध्यम के रूप में उपयोग करता है\nइस तरह से निर्माण करते समय यहां कच्चे माल की एक विस्तृत श्रृंखला की आवश्यकता होती है\nइसकी व्याख्या कृष्ण ने निम्नलिखित श्लोकों में दी है।",
  "14.5": "सत्त्वं रजः तमः इति गुणाः प्रकृतिसम्भः |\nनिबधना ति महाबाहो देहे देहिनं अव्यम् - महाबाहो, सत्व-रजसु - तमस्सु\nएमबी ऐसे गुण हैं जो प्रकृति से उत्पन्न होते हैं। वे शरीर में अमर जीवन बांध देते हैं।\n\nप्रकृति - गुणत्रयमणि, इस संसार के सभी जीवित प्राणियों की माँ। तो हर एक\nयहां तक कि जब जीवन का जन्म होता है, तो वह सत्व-रजस्सु और तमस के तीन गुणों के साथ पैदा होता है\nइन गुणों के प्रभाव में आगे बढ़ें। तीन गुणों के बिना शुद्ध एकल गुण वाला कोई भी जीवन\nनहीं बनाया गया. ये तीन गुण हमें जड़ में भी मिलते हैं। सदैव उत्तर दिशा की ओर प्रकाश रखें\nदेने वाला अग्नि सार; जल, जो अंधकार का स्थान है, राजसिक है और सदैव नीचे की ओर खींचता है\nमृदा-तमसु. संसार की सभी वस्तुएँ इन तीनों का संयोजन हैं। उदाहरण के लिए सूखा.\nहमने इसे धरती (मिट्टी-तमस्सु) में बोया। वहां हमने उसे सींचा (निरु-रजसु), वह सूर्य था।\nप्रकाश (सूर्य-सत्व) को अवशोषित करके अंकुर बड़ा हुआ और फसल दी। उस फसल की कटाई करें और उसे चावल में बदल दें\nहमने किया. हमने चावल (तमस्सु) में पानी (रजस्सु) मिलाया और चावल बनाने के लिए इसे (सखा-सत्व) पकाया।\nचावल हो या भात, सब कुछ पृथ्वी, जल और अग्नि का मिश्रण है। इस प्रकार सत्त्व-रजसु तथा\nयह संपूर्ण सृष्टि तमस नामक गुणत्रयों से बनी है। प्रत्येक जीवित प्राणी जन्म लेता है\nये तीन गुण बंधनकारी हैं। इन तीनों गुणों की मात्रा हर किसी में अलग-अलग होती है\nअलग होगा. यहां तक ​​कि सबसे सात्विक मोक्षयोग्य जीवन में भी ये तीन गुण होते हैं।\nकिसी व्यक्ति में शत-प्रतिशत शुद्ध सत्त्वगुण नहीं होता। जड़ में देखा जाए तो अग्नि-सार। लेकिन\nइसके साथ ही धूम्र-रजस्सु, काष्ठ-तमस्सु। सत्त्वगुण का बोध रजस है और\n\nतमस के माध्यम से. इस प्रकार इन गुणत्रयों के बंधन के कारण, जीव-स्थूल प्रकृति में मूल नहीं है\nव्यक्ति एक शरीर के साथ पैदा होता है और उस शरीर को खोने के बाद मर जाता है। जन्म मृत्युहीन है\nमोक्ष प्राप्त करने के लिए हमें अपने साथ इन तीन आंतरिक शत्रुओं पर विजय प्राप्त करनी होगी।\n\nयहाँ व्यास ने \"महाबाहु\" विशेषण का प्रयोग किया है।\nयह महाबाहु ही हैं जो नृत्य के इन त्रिगुणों को खोदते हैं; कुसिटा को अस्वीकार करना आध्यात्मिक है\nइस विशेषण के पीछे \"शुरानगु\" की ध्वनि है।\n\nसारा ब्रह्माण्ड, हमारा यह जीवन, सब कुछ गुणत्रय की विकृति है। हमारा दिमाग, हमारी सोच, हमारी\nनिर्णय, हमारा पढ़ना, हमारा विश्वास, सभी इन गुणों से प्रभावित होते हैं। हमें सही रास्ते पर ले चलो\nये त्रिगुण हैं जो हमारा मार्गदर्शन करते हैं, और ये त्रिगुण हमें भटकाते हैं। तीन तरीकों में से कौन सा?\nहम यह निर्णय लेने में सावधानी बरतते हैं कि यदि हम मार्ग पर चलें तो अच्छा रहेगा\nअगर हम आना चाहते हैं तो हमें यह जानना होगा कि हम किस रास्ते पर जा रहे हैं। इस कारण से\nत्रिगुणों के प्रति जागरूकता हमारे लिए बहुत महत्वपूर्ण है।\n\nचार चीजें हैं जो किसी व्यक्ति को नियंत्रित करती हैं। जीव अनादिकाल से जीव के साथ है\n\"स्वभाव\" स्वरूप में सन्निहित है। सत्व, रजस्सु, तमसु - इन तीन के साथ\n'प्रभाव'. प्रकृति कभी नहीं बदलती. हमें अपने स्वभाव को पहचानना होगा।\nलेकिन हम नहीं जानते कि हमारा स्वभाव क्या है! क्योंकि इस प्रकृति पर\n'प्रभाव' ढक्कन बनकर बैठा रहता है. हम सदैव इस आवरण से प्रभावित होते हैं जो हमारा स्वभाव है\nहम भ्रमित हैं. लेकिन यह हमारा वास्तविक स्वभाव नहीं है - यह प्रभाव है। संपूर्ण\nजीवन भर हम यह नहीं जान पाते कि हमारा स्वभाव क्या है। प्रकृति क्या है\nअनजाने में हम इसके प्रभाव में आ जाते हैं और संघर्ष करते रहते हैं। इन त्रिगुणों का प्रभाव हम पर पड़ता है\nयदि हम नहीं जानते कि यह कैसे काम करता है - तो हम स्वयं को ठीक नहीं कर सकते। आज\nहम अपनी प्रकृति और सत्त्वगुण, रजस्सु और तमस को किनारे कर देते हैं\nउत्तोलन में रहना.\n\nसबसे पहले हमें खुद को ठीक करना होगा-समाज को नहीं। कितना सार है हममें; रजस तत्व\nतमस तत्व कितना है यह जानकर, अपने आचरण में सत्व तत्व का अधिक उपयोग करें,\nइसकी सामग्री को बढ़ाने का प्रयास करें. हम कहाँ हैं राजासन और अतीत में जो घटनाएँ घटीं\nहम तमस के प्रभाव में आकर भटक गये हैं। खुद पे भरोसा। आचरण, आगे. ऐसा नहीं है\nसावधान रहें. अगर हम इस मुद्दे के प्रति जागरूक हो जाएं तो हम खुद पर काफी हद तक काबू पा सकते हैं\nसुखपूर्वक रह सकते हैं.\n\nनिम्नलिखित श्लोक में कृष्ण का जीवन सत्त्व क्या है; राजस का जीवन कैसा है; तामसिक जीवन जियें\nवह बताते हैं कि यह कैसा है। जीव त्रिगुण गाँठ में फँसे, जो गाँठ\nयदि आप प्रभाव में रहना जानते हैं, तो सत्य के मार्ग पर चलने का प्रयास करें\nकृष्ण ने निम्नलिखित श्लोक में इसका बहुत सुन्दर विश्लेषण किया है।",
  "14.6": "तत्र सत्त्वं निर्मलत्वं प्रकाशकं अनामयम् |\n\nसुख संगेन बध्नति ज्ञान संगेन च अनघा - उनमें सत्त्वगुण शुद्ध है। इसलिए\nज्ञान का प्रकाश देता है; यह बीमारियों को दूर करता है. हे अनघा, वह सुख के कारण है\nऔर ज्ञान की गांठ से बंध जाता है।\n\nअपनी आँखें बंद करो और अपने अंदर देखो। आपके भीतर जो मानसिक विकास होता है,\nविचार, विचार, भावनाएँ देखें। यदि आप सत्व गुण से प्रभावित हैं-\nआप अपने भीतर एक शुद्ध, निष्कलंक, उज्ज्वल प्रकाश देखते हैं। हमारा आंतरिक अस्तित्व\nदुनिया से एक पूर्ण विद्युत कनेक्शन, एक लैंप, कई स्विच जो उस लैंप को नियंत्रित करते हैं\nक्रियान्वित किया गया। यहां लगातार बिजली की आपूर्ति हो रही है. लेकिन हमारे लिए यह स्विच कहां है?\nपता नहीं तो- सब कुछ होते हुए भी हमारे भीतर हमेशा अंधेरा ही रहता है। हम यह करते हैं\nबिल्कुल कोई फायदा नहीं. यह स्विच हमें तब मिलता है जब हमारा सत्त्वगुण जागृत होता है। उससे\nनिष्कलंक ज्ञान का प्रकाश हमारे भीतर चमकता है।\n\nजब सत्त्वगुण जागृत होता है तो हम आंतरिक आनंद से भर जाते हैं। यह अनुभव\nअधिकांश के लिए यह होगा. उदाहरण के लिए: कभी-कभी हम कहते हैं: “आज कुछ लंबा है\n\"मैं खुश हूँ।\" कोई खास वजह नहीं है. लेकिन आंतरिक आनंद बाहरी है\nयही सब हम अनुभव कर रहे हैं। यह सत्त्वगुण की जागरूकता है। ज्ञान से आ रहा है\nसभी सुख सात्विक हैं।\n\nकृष्ण यहाँ एक चेतावनी देते हैं। यदि हमारे अंदर सत्त्वगुण को जागृत करना है, तो हम\nपाप का स्पर्श होने पर सत्त्वगुण जागृत नहीं होता। उसके लिए हम पाप हैं\nदूर होना चाहिए. पाप का स्पर्श जितना बढ़ता है, सार उतना ही दूर होता जाता है।\n\nयद्यपि सत्त्वगुण मोक्ष की प्राप्ति में सहायक है, यह भी त्रिगुणों में से एक है। अत: सत्त्वगुण\nबाध्यकारी भी हो सकता है. यह हमें खुशी के बंधन और ज्ञान के बंधन से बांधता है\n\nउदाहरण के लिए रख सकते हैं: ज्ञान उपलब्धि सात्विक गुण. यहाँ वह ज्ञान है जो ईश्वर का विषय नहीं है\nयदि हम उपलब्धि के जाल में फंस जाते हैं - तो यह बंधनकारी हो जाता है। हम कुछ शोध करते हैं,\nअगर खोज में डूबे। इतना ही। हमें मोक्ष की ओर नहीं ले जा सकता. हम वही हैं\nशोध के नतीजों की खुशी में कोई भी फंस सकता है और गिरफ्तार हो सकता है.\nमोक्ष प्राप्ति में हमें सत्त्व से भी ऊपर जाना होगा। क्योंकि मोक्ष त्रिगुणात्मक है। कृष्ण यहाँ का सार हैं\nउन्होंने गुणवत्ता को \"बद्दति\" कहा क्योंकि यह बंधन एक ऐसा बंधन है जिसे आसानी से छोड़ा जा सकता है\nहमें कभी निराश मत करो. [लेकिन कृष्ण आगे कहते हैं कि रजस्सु और तमसु 'निबध्नति' हैं\nछंद में वर्णित], जो सत्त्व हमें भगवान की ओर जाने से रोक रहा है\n\nहमें उस सार से छुटकारा पाना है।",
  "14.7": "रजः रागमकम् विधि तृष्णा संग समुद्धवम्।\nतत् निबध्नति कौन्तेय कर्मसंगेन देहिनम् - रजोगुण मनोरंजन, इच्छाओं और वासनाओं का मनोरंजन करता है।\nजान लें कि यह कुछ ऐसा है जो सृजन करता है। कौन्तेय, यह जीवन को कर्म के बंधन से बांधता है।\n\nराजस्सु का अर्थ है 'राग', किसी चीज़ के प्रति लगाव, इच्छाओं की डोर - ये सब\nपाँचों इन्द्रियों की इच्छा रजोगुण के प्रभाव से उत्पन्न होती है। यह तृष्णा और संगा के लिए है\nकारण यहाँ तृष्णा का अर्थ है चाह-अचानक की प्यास। संग का अर्थ है किसी वस्तु की निरंतरता\nरजोगुण का साथ इच्छा उत्पन्न करता है। उस चाहत से साथ, उस चाहत से साथ\nइसे चिपचिपा बनाता है. इस प्रकार चरण दर चरण रजोगुण हमें अलग नहीं कर सकता\nगिरफ़्तारी (निबध्नति)। इसके प्रभाव से हम ज्ञान की इच्छा से रहित कर्मसंग हैं\nचलिए शुरू करते हैं. उदाहरण के लिए: पैसे के लिए, पैसे के लिए लड़ना। संपूर्ण जीवन\nद्वंद संसार आदि की भाँति समर्पित युद्ध करना, यह राजस का गहरा बंधन है\nप्रभाव",
  "14.8": "तमः तु अज्ञानजं विधि मोहनं सर्वदेहिनम् |\n\nप्रमदा अलस्य निद्राभिः तत् निबध्नति भारत - जो सभी प्राणियों को अज्ञान देता है,\nजो मिथ्या है-उस तमोगुण को जानो। भरत, यह विस्मृति, आलस्य और है\nनींद से नाता जोड़ देता है.\n\nकुछ भी नहीं जानना मजेदार है. तमोगुण से अज्ञान उत्पन्न होता है। यह इतना मजबूत है कि-\nयह इस ज्ञान को रोक सकता है कि मुझे कोई ज्ञान नहीं है, कि मैं अज्ञानी हूं। ये सबसे ज्यादा है\nभयानक. जैसा कि अंग्रेजी में कहा जाता है:\n8 1001\"। जिसके बारे में मैं कुछ नहीं जानता, उसका कारण यह है कि मैं कुछ भी नहीं जानता।\nयही वह गुण है जो हर किसी को भ्रम में रखता है। तमसु वे तीन हैं जिन्हें हम अलग नहीं कर सकते\nरिश्ते हमें बांधते हैं. वे हैं नींद, सुस्ती और भूल। जागते हुए भी\nजागरूकता के बिना जीना एक गलती है। गलती करना गलत नहीं है, बल्कि गलती करना और उसे सुधारना गलत नहीं है\nयह एक गलती है. यह सब हमारे स्वभाव के कारण है।",
  "14.9": "' लेकिन, हिंदी में, \"टका है। जर्मन।\"\nयह भाषा में है. \"606 ग्राम\" है। कन्नड़ में उपरि का अर्थ है 'उप' - 'ऊपर'\nदेता है]। तो \"उपजायते\" का अर्थ है श्रेष्ठ जन्म। यह प्रभु की जागरूकता है\nशारीरिक मुद्रा के साथ जन्म लेना ही उच्च जन्म है। आध्यात्मिक उपलब्धि से जन्म ऊंचा\n'पुनर्जन्म'। जिसने अपने जीवनकाल में इस सृष्टि के स्रोत का ज्ञान प्राप्त कर लिया उसका पुनर्जन्म नहीं हो सकता।\nवह भगवान में निरंतर बने रहने के सर्वोच्च शब्द को प्राप्त करता है।\n\nमम योनिर्महद् ब्रह्मा तसि तुस गर्भं दधाम्यहम् |\nसम्भवः सर्वभूतानां ततो भवति भारत ॥3॥\n\nयहां कृष्ण बड़ी अजीब बात कहते हैं. यदि हम इस श्लोक को समझना चाहते हैं, तो हम\nपहले 'भा-रता' बनना चाहिए. 'रत' का अर्थ है दर्शन। हमें प्रभु में विश्राम करना चाहिए; ज्ञान का\nरास्ते पर होना; भक्ति के धनी बनो और पूर्ण दाता बनो; विनम्र होना। फिर\nसृष्टि का यह रहस्य समझ में आ गया।\n\nकिसी भी वस्तु के निर्माण के लिए एक से अधिक कारणों का होना आवश्यक है। अगर सुस्त है\nवहाँ दो कारण आवश्यक हैं, उदाहरण के लिए यदि एक घड़ा बनाना है तो एक जड़ है (Raw materials) वांछित और आकार देने वाला कुम्हार चाहिए। वनस्पति की रचना- जड़ के भीतर भगवान\nजीवन जोड़कर. लेकिन 'आत्मा रचना' को जो गर्भ से जन्म लेती है\nपदार्थ से निर्मित होने के लिए एक नर और एक मादा की आवश्यकता होती है। वे दोनों\nएक तीसरा संघ द्वारा निर्मित होता है।\nइस श्लोक में 'योनि' और 'ब्रह्म' 'मम योनिः महत् ब्रह्मा' में आते हैं।\nशब्द वे शब्द हैं जिनके अनेक अर्थ होते हैं। किस स्थिति में कौन सा अर्थ मेल खाता है\nयह जानकर हमें श्लोक को समझना चाहिए। योनि - कारण, जन्म स्थान, पत्नी\nआदि अर्थ देता है। इसी प्रकार ब्रह्म- जीव, चतुर्मुख, लक्ष्मी, भगवान आदि अनेक हैं\nइस श्लोक में... अर्थ बताता है. योनि का अर्थ है पत्नी; इसका अर्थ है 'महत ब्रह्मा'\nश्रीलक्ष्मी जो चतुर्मुख की माता भी हैं। कृष्ण कहते हैं, “मैं चित्त प्रकृति हूं, अपनी पत्नी हूं\n(मैं लक्ष्मीना को गर्भवती करूंगा। वह गर्भ बड़ा होगा और सभी जीवित प्राणियों का निर्माण होगा।)\nयह हमारे लिए कुछ नया है. चूँकि चतुर्मुख की रचना ऋग्वेद में इस प्रकार कही गई है:\n\nतमिद्गर्भं प्रथम दधरा आपो यत्र देवः समगच्छन्त विश्वे।\n\nअजस्य नाभवध्येकमरपितं यस्मिन्विश्वानि भुवनानि तस्तुः",
  "14.10": "रजः तमः च अभिभूय सत्वं भवति भारत।\nरजः सत्वं तमः च एव तमः सत्वं रजः तथा-भारत, सत्त्वगुण रजस्सू-तमस को दूर धकेल रहा है।\nमजबूत करता है; सत्त्व तमस रजोगुण को धक्का देता है; साथ ही सत्व-रजस को धकेल कर तमोगुण।\n\nगुणत्रयों में एक विशेष शक्ति होती है। क्योंकि इन तीनों में से कोई एक हमारा है\nमन पर नियंत्रण कर लेता है और शेष दो गुणों को बंद कर देता है ।\nतीन गुणों में से एक गुण हमारे मन पर कब्ज़ा कर लेता है। तब हमारा मन उस गुण के पक्ष में होता है\nयह उसी के अनुसार काम करना शुरू कर देता है। त्रिगुणमणिनी लक्ष्मी। वह कुछ गुणवत्ता के लिए बनी रही\nवह दो गुणों से परे काम करने की शक्ति देती है। इस प्रकार एक गुण दो गुण रह जाता है\nबंद करें और काम करना शुरू करें.\n\nहमें यह पहचानना होगा कि कौन सा गुण हमारे अंदर चेतन है। फिर उस क्वालिटी का\nप्रभाव से होने वाली दुर्घटनाओं से बचा जा सकता है। इसकी पहचान के लिए कृष्ण ने जो तरीका अपनाया है\nवह तीन श्लोकों में समझाते हैं।",
  "14.11": "सर्वद्वारेषु देहे अस्मिन् प्रकाशः उपजायते।\nज्ञानं यदा तदा विद्यत् विवृद्धं सत्त्वं इति उता - इस शरीर में सभी इंद्रियों में।\nयह जानना चाहिए कि प्रकाश के प्रकाश हो जाने पर सत्त्वगुण पुष्ट हो गया है।\n\nजब सत्त्वगुण जागृत होता है, तो हम अपने भीतर हल्कापन महसूस करते हैं। यह सब हल्का यातायात है\nइंद्रियों के माध्यम से बाहर आता है. ज्ञान का आनंद इंद्रियों को भी भर देता है। सबसे ऊपर",
  "14.12": "लोभः प्रद्धितः अरामवः कर्मणां अशः स्पा एहा।\n\nराजसी क्या है? जयन्ते विवृद्दे भरतर्षभ - हे भरतर्षभा, जब रजोगुण प्रबल हो जाता है\nदेखे गए पहलू हैं: कंजूसी, उन्माद, कश्ती में लिप्तता, बेचैनी।\nऔर किनारे की चाहत.\n\nरजोगुण जागृत होने पर लालच सबसे पहले हमारे अंदर प्रकट होता है। क्या बकवास है\nकरने का विचार; कृपणता, दूसरे को एक पैसा न देना आदि।\nउदाहरण के लिए कुछ लोग अपने गृह समारोह पर लाखों खर्च करते हैं। लेकिन कोई\nयदि कोई ऐसा व्यक्ति जिसके पास भोजन न हो, आकर पूछे तो उसे एक पैसा भी दान में न मिलेगा। ये है\nलालच भवभूति ने नीति शतक में ऐसे लालची लोगों के बारे में कहा है:\n\nदानं भोगो नासः तिस्रो भवन्ति गतयो वित्तस्य|\n\nयोना ददाति नाभुन्के तस्य तृतीया गतिर्भवति।।158।\nडुड्डी के विनियोग के तीन रूप हैं: दान, भोग और विनाश। लालची लोगों के पास पैसा है\nवे दूसरों को दान नहीं देते, वे स्वयं नहीं खाते, अंततः यह एक लोमड़ी-कुत्ते का विभाजन है\nनष्ट हो जायेंगे. यह रजोगुण के प्रभाव का परिणाम है। रजोगुण का\nप्रभावित होने पर व्यक्ति हमेशा कुछ न कुछ कर गुजरता है। दूद्दू\nकरने के लिए विभिन्न व्यवसाय; चाहे कितना भी शामिल हो, असंतोष है; वह करता है\nव्यवसाय में, यदि भगवान उसे पेट भरने के लिए भी पर्याप्त दे, तो भी संतुष्टि नहीं होगी;\nभले ही वह अपने पास आने वाले वेतन पर खुशी से रह सके, यह बात से परे है\nघरेलू वेतन से कम आदि की शिकायत करना। उनका दैनिक मंत्र है \"चाहिए-चाहिए\"।\nये सभी लक्षण तब प्रकट होते हैं जब सत्त्वगुण कुचल दिया जाता है और रजोगुण खड़ा हो जाता है।\nयहाँ व्यास ने 'भरतर्षभ' विशेषण का प्रयोग किया है।\nभारत को गर्व होना चाहिए. ऐतरेय ब्राह्मण में एक कहावत है 'वैयरवव भारतः। हमेशा\nभगवान के साथ व्यस्त रहने वाले वायुदेव को 'भरत' कहा जाता है। हमें प्राणदेव को समर्पित कर दो\nरजोगुण से बचा जा सकता है।",
  "14.13": "अपराकाः अप्रवृत्तिः च प्रमदः मोहः एव च।\nतमसि एतनि जयन्ते विवृद्धे कुरुनन्दना - हे कुरुनन्दन, जब तमसु मजबूत हो जाता है\nदेखे गए तत्व हैं: अंधकार, भयावहता, जागृति और गलतफहमी।\n\nजब तमोगुण जागृत हो जाता है तो अंदर और बाहर सब कुछ अंधकारमय हो जाता है। हमेशा सोते रहना, गलत\nकरना, अज्ञान में रहना- तमोगुण के वश में होना। सुबह सूरज उगता है\nतमोगुण जल्दी जागने नहीं देता। यही गुण हमें हमेशा सोने के लिए प्रेरित करता है। यह\nगुना हमेशा आपको अंधेरा चाहता है। हमें इसके प्रभाव से बचना है\nकुरुनन्दन होना चाहिए। खुद को किसी काम में व्यस्त रखें और उसे एक आदत बना लें\nकरना चाहिए उदाहरण के लिए: सुबह सूर्योदय से पहले उठने की आदत\nजब यह आदत बन जाती है तो मन इसे छोड़ने के लिए नहीं कहता।\n\nहममें से कुछ लोग ऐसा कहते हैं. \"मेरे पास आध्यात्मिक विचार के लिए समय नहीं है।\" लेकिन इस तरह\nअधिकांश टेलर अपनी छुट्टी के दिन, खाली समय पर हैं - सुबह से शाम तक\nआलस्यपूर्वक सोना और देर तक सोना! इस प्रकार हम वैसे हैं जैसे हम नहीं हैं\nतमोगुण कब्ज़ा और नियंत्रण कर रहा है। हम किसी भी कर्तव्य में आलसी नहीं हैं\nस्वयं को संलग्न करने से हम तमोगुण के प्रभाव से बच सकते हैं।",
  "14.14": "यदा सत्वे प्रवृद्धे तु प्रलयं याति देहभृति |\nतदा उत्तमविदं लोकं अमलान प्रतिपद्य ते - जब सत्त्वगुण मजबूत हो जाता है, तो जीव\nयदि वह मर जाता है, तो उसे हिरदादा तत्त्व- ज्ञाता के परिवार में दोष रहित शरीर मिलता है।\n\nजैसा कि हम जानते हैं कि जीवन का अंतिम क्षण शरीर छोड़ना उस जीवन का अगला चरण होता है\nअंत में सात्विक विचार के साथ, आत्मा को सत्त्व के प्रभाव में छोड़ने का निर्णय लेता है\nयदि संभव हो तो, अगले जन्म में बुद्धिमानों के समुदाय में एक निर्दोष इंसान के रूप में\nहम पैदा हुए हैं. वहाँ बुद्धिमानों के बीच रहना, ज्ञान की खेती करना और फिर से ज्ञान के मार्ग पर चलना\nऊँचा चढ़ने में सक्षम। यदि हम अपने जीवनकाल में सार पर जोर देकर जियें\n\nमरते समय सत्व अवस्था में मरना संभव है। इसके अलावा ''मरते समय सात्विक\nआइए विचार के बारे में सोचें”, सत्त्व के प्रभाव में मरना असंभव है।",
  "14.15": "राजसी प्रलयं गत्वा कर्म संगीषु जयते।\nतथा प्रलिनः तमसि मूढ़ योनिषु जयते - यदि आप रजोगुण में मरते हैं तो कर्म।\nएक का जन्म क्लिंगर्स में होता है। जो व्यक्ति तमोगुण में मरता है वह अज्ञात हीनयोनियों में जन्म लेता है।\n\nरजोगुण के प्रभाव में डुड्डू-डुड्डू की तरह रहना, कर्मानुष्ठान करना जो ज्ञान का पूरक नहीं है,\nयदि आप उसी प्रभाव में मर जाते हैं, तो आपको अगले जन्म में कर्म से चिपक कर जन्म लेना होगा। अब और नहीं\nयदि आप तमोगुण के प्रभाव में जीते और मरते हैं, तो आपको अगले जन्म में हिनायोनि में जन्म लेना होगा। यहाँ\n'हिनायोनि' का अर्थ है मनुष्य भी बन सकता है। बिना किसी संस्कार के, बिना शुचिता के।\nज्ञान के बिना, मात्र मनुष्य का रूप धारण करके, मानवता की चमक के बिना मनुष्य बन जाते हैं\nजीना भी कमजोरी का जन्म है. इससे तो पशु-जन्म कितना उत्तम है। यह तमोगुण में है\nमृत्यु पर प्रभाव. [यदि कोई मृत्यु के अंतिम क्षण में रजस्सू और तमस के प्रभाव में मरता है, अर्थात\nइसका हमारे अगले जन्म पर क्या प्रभाव पड़ेगा - गजेंद्र के रूप में जन्म\nहम इंद्रद्युम और हिरण जन्मे सम्राट भरत की कहानी से सीख सकते हैं।\n5608/08/06 पुनर्जन्म पर नवीनतम शोध के बारे में जानने के लिए उनकी पुस्तकें\nऔर उनके शोध का विवरण देखें]।",
  "14.16": "कर्मणः शुक्रतस्य औः सात्विकं निर्मलं फलम्।\n\nराजसः तु फलम् दुखं अज्ञानं तमसः फलम् - एक सात्विक जो अच्छी इच्छाओं से भयभीत नहीं होता।\nजो जानते हैं वे कहते हैं फल। राजसव कज्जा से दुःख मिश्रित सुख। शरारत विशेषता है\nकज्जा फल.\n\nऐसा कुछ करना शुभ है जिससे जीवन भर दूसरों की मदद हो। हमारे बीच\nजब धन है, तो वह मेरा है - यदि तुम दुखी रहते हो, तो यह दुखी जीवन की ओर ले जाएगा\n\nयह हमारा होगा. जब हम अपनी कमाई दूसरों के दुख पर खर्च करते हैं तो यह हमें सात्विक बनाता है\nफल की ओर ले जाता है. माधवाचार्य ने अपने 'गीतात्पर्य' में इस मुद्दे पर जोर दिया है\nउन्होंने कहा: \"नाना जनस्य शुश्रुषा कर्तव्य करावनमिते\" जरूरतमंदों की सेवा करना है\nमोक्ष उपलब्धि का एक पहलू है। हममें से कुछ लोग किसी को परेशानी में देखते हैं और कहते हैं: “बस इतना ही\nउसका प्रारब्धकर्म, उसे इसका अनुभव करने दो। मुझे इसकी चिंता क्यों करनी चाहिए? इस तरह\nऐसा कहकर, हम जरूरतमंद व्यक्ति के भीतर मौजूद भगवान का तिरस्कार करते हैं।\nऐसे लोगों को कभी भी ईश्वर का एहसास नहीं होगा। हमारी आध्यात्मिक प्राप्ति में जप-\nकेवल पाप ही पर्याप्त नहीं है; यहां संकटग्रस्त लोगों की सेवा भी प्रमुख है। साधक उसका है\nगीता का आदेश है कि दैनिक अनुष्ठानों के साथ इस सेवा का भी उत्सव मनाया जाना चाहिए\nमाधवाचार्य ने पैरवी की. आपके घर में कितना खाना खाया जाता है, भूखे लोगों की भूख\nशमन - बहुत मीठा. पहले इसके लिए एक परंपरा थी. पकाना,\nइसे भगवान को अर्पित करें, करीब दस मिनट तक गेट पर रुकें, फिर खाएं।\nक्योंकि इस समय यदि कोई भूखा व्यक्ति घर की गली में आता है तो सबसे पहले वह भोजन करेगा\nपहले परोसना और फिर मालिक खाना, यह रिवाज था। इश्ते ख़ैर इससे पहले\nवे \"बलिदान\" कर रहे थे। घर के आसपास जानवरों और पक्षियों को खाना खिलाना \"बलिदान\" है।\nइस प्रकार यदि आप जीवन भर अच्छे कर्म करेंगे तो उसका परिणाम सात्विक होगा। इससे\nयदि एक जन्म में ज्ञान न मिले तो भी अगले जन्म में वह अवसर अवश्य मिलता है।\nज्ञान होते हुए भी यदि आप बुरे कर्मों में रहते हैं तो आपको हीनयोनि में दोबारा जन्म मिलेगा।\n\nहोम-हवन, दान-दक्षिणा, ब्राह्मण-पूजा - सब करो, \"वह सभी से बड़ा है\"।\nयदि अहंकार आ जाए तो वह राजसी कर्म बन जाता है। इसका फल लोभ है; एक दुखद जीवन. इससे\nअच्छे कर्म करने पर भी दुख का अनुभव करना पड़ता है। अज्ञानतावश कोई व्यक्ति तनाव पैदा करने के लिए कुछ न कुछ कर बैठता है\nकर्म से कभी ज्ञान विकसित नहीं होता। अज्ञान तमोगुण का कर्म है।\n\nहम कैसे जानते हैं कि कौन सा गुण हमारे अंदर पूरी तरह से सचेत है, इसकी व्याख्या,\nअगले श्लोक में कृष्ण निष्कर्ष के रूप में बताते हैं।",
  "14.17": "सत्वत् संजायते ज्ञानं राजसः लोबः एव च ​​|\nप्रमदा मोहौ तमसः भवतः अज्ञानम् एव च-सत्त्व का अर्थ है ज्ञान। रजस से\nकंजूसी बढ़ती है. तामसी विस्मृति, भ्रम और संभ्रम का कारण बनती है।\n\n“सत्त्वत् संजयते ज्ञानम्” – गीता की यह पंक्ति बहुत महत्वपूर्ण संदेश देती है।\nजब किसी इंसान के लिए ज्ञान बाकी सभी चीजों से ज्यादा महत्वपूर्ण है तो मैं इसके लिए कुछ भी कर सकता हूं।'\nयदि यह दृढ़ निर्णय है कि हम हारने के लिए तैयार हैं - तो हमें इसमें कोई संदेह नहीं है कि यह सत्त्वगुण है\nइसे पूर्ण चेतना के रूप में समझा जा सकता है। इसका अच्छा उदाहरण कठोपनिषद में आता है\nयम और नचिकेता के बीच यह संवाद:\n\nएततुल्यं यदि मन्यसे वरं वृनिष्ट विटं चिराजीविकं च |\n\nमहाभूमौ नचिकेतस्त्वमेधि कामनां त्वा कंभजं करोमि। 1-24 |\nये ये काम दुर्लभ मर्त्यलोकाय सर्वं कामनाश्चंदथा प्रथ्यस्व |\nइमा रामः सरथः शनिवार्य न हीद्रिशा लंभनिया मंशीनः |\nअभिरामतृत्तभि परिचरयस्व नचिकेताशो मरणं मननुप्रकाशे ॥1-25॥\n\nयहाँ जब नचिकेता ने यम से कहा कि \"मुझे आत्म-ज्ञान सिखाओ\": \"तुम भी युवा हो, वह।\"\nकोई शिक्षा नहीं. इसके बदले मैं तुम्हें पृथ्वी का सम्राट बनाऊंगा; आप चाहते हैं\nमैं इसे उपलब्ध कराऊंगा; मैं तुम्हें जीवन और धन दूँगा,'' जावरया कहते हैं। फिर\nनचिकेता कहते हैं:\n\nश्वोभव मर्त्यस्य यदन्तके तत् सर्वेन्द्रियहम जरायन्ति तेजः |\n\nअपि सर्वं जीवितमल्पमेव तवैव वहस्तव नृत्य गीते ॥1-26॥\n\nन वित्तेन तर्पणियो मनुष्यो लप्स्यमहे वित्तमद्रक्ष्म चेत्त्व |\nजीविष्यामो यावदिशिष्यसि त्वं वरस्तु मे वरानियः स एव ॥1-27॥\nअजीर्यातममृतानामुपेत्य जीर्यन्मर्त्यः क्वदस्थः प्रजानान |\nअभिध्यायं वर्णरतिप्रमोदं अतिदिर्फ़े जीविते को रामेता ॥1-28॥\nयस्मिन्निदं विचिकित्संति मृत्यो यत्सम्पराय महति ब्रुहि नास्तत् |\nयोका$यं वरो गूढ़मनुप्रविष्टो नान्यं तस्मान्नचिकेता वृनिते ॥1-29॥\n\n\"चाहे कितना भी दो, वह कम है। हमें चाहे कितना भी जीवन मिले, हमें एक दिन मरना ही है। इसलिए\nमुझे इसमें से कुछ भी नहीं चाहिए. भले ही तुम मुझे पूरी दुनिया दे दो, मुझे यह नहीं चाहिए। मुझे पता है\nवह मनोविज्ञान \"मुझे बताओ\" चाहते हैं। यह बिना किसी प्रलोभन के वास्तविक है\nसार: जो लोग वास्तव में ज्ञान के भूखे हैं वे सब कुछ खोने के लिए कैसे तैयार हो सकते हैं\nज्ञान के मार्ग पर चलने का एक अच्छा ताजा उदाहरण स्वामी राम (1925-) हैं।\n\n1996). उनकी जीवनी हमें \"Living with the Himalayan Masters\" पुस्तक में मिलती है।\nआप पढ़ और समझ सकते हैं. यदि हमें शास्त्र का सच्चा ज्ञान प्राप्त करना है तो भले ही हम शास्त्र पढ़ें, हमारे अंदर सात्विकता होनी चाहिए\nअ-कार वाच्य का ज्ञान तभी होना चाहिए जब सत्त्वगुण हो। सत्त्वगुण से परिपूर्ण\nजागृत होने पर हम सच्चे ज्ञान को जानते हैं और अन्य सभी सांसारिक चीजें ज्ञान हैं\nआगे शून्य का सच पता चलेगा.\n\"राजसो लोभ एव च\" - लालच राजसी का समर्पित गुण है । यह\nसात्विक में नहीं पाया जा सकता। किसी वस्तु के प्रति वासना, वस्तु न मिलने पर क्रोध,\nजैसे ही पाओ - लोभ। इसका न तो उपयोग किया जाता है और न ही दूसरों को दिया जाता है। दान\nयह उनके लिए बहुत दूर है! हमारे पास जो कुछ है उसे बांटकर हमें जीना चाहिए\nसार यह ईशोपनिषद में खूबसूरती से कहा गया है:\n\nईशावास्यमिदं सर्वं यत्किंच जगत्यं जगत् |\n\nतेन त्यक्षेन भुंजीथा मा गृधः कस्यस्विधानम् | 1\nभगवान हर चीज का भगवान है. उन्होंने जो दिया है उसका अनुभव अवश्य करना चाहिए। बिना धन के लिए\nइच्छा मत करो. वह प्रभु संसार की समस्त सम्पत्ति का स्वामी है। इसलिए उसने जो धन दिया है\nयह 'मेरा' है, यह सोचकर लालच में जीना ठीक नहीं है। लेकिन रजोगुण बहुत ही महत्वपूर्ण दोष है\nये लालच. यह दूसरों के प्रति करुणा के बिना है, उसने जो कमाया है उसे दूसरे को दिए बिना है।\nकभी-कभी तो यह बिना खाए भी छिप जाता है। एक ख़राब गुणवत्ता जो आमतौर पर जानवरों में नहीं पाई जाती\nये लालच. यदि हमारे अंदर लोभ का गुण है तो हम इसे रजोगुण जागरूकता कहते हैं\nजानना चाहिए\n“प्रमादमोहौ तमसो भवतोइग्नामेव च”। रजोगुण से कितना लोभी, ऐसा\nतमोगुण से मोह और मोह से उत्पात... अपने आप पर अति करना\nइसे गले लगाना, उनकी गलतियों को माफ करना, जैसा कि वे कहते हैं\nझुकना, आदि। यह इतना प्रभावशाली है कि - यह हमारे ज्ञान को भी ढक लेता है,\nहमें भटकाता है. इसका एक अच्छा उदाहरण भागवत का छठा स्कंद है\nप्रथम अध्याय में अजामिल की कथा आती है। वह सात्विक ब्राह्मण थे। वह शादीशुदा था.\nएक बार जब वह पूजा के लिए फूल और तुलसी लाने जंगल में गया तो उसके मन में एक दृश्य घूम गया\nगहरा असर हुआ. उसने जंगल में दिखी एक युवती को बहकाना शुरू कर दिया।\nउसने उसके लिए शराब-मांस का सेवन किया। उसने अपनी इच्छाएं पूरी करने के लिए चोरी की।\nजो सात्विक था वह विप्र-पूर्ण-तमसना बन गया। इस कहानी को मनोवैज्ञानिक दृष्टि से देखें तो- यह\nपता चल जाएगा कि घटना क्यों हुई। अजामिल शादीशुदा था, लेकिन उसका\nघर में लैप-मील की अनेक रस्मों के कारण वह अपने आप में अंतरंग है\n\nचाहत को जबरन दबा दिया गया. ऐसा तब होता है जब हम अपनी इच्छा को बलपूर्वक रोक लेते हैं\nएक दिन ये सामने आएगा. ऐसा शास्त्रों के अनुसार बताया गया है\n\"आध्यात्मिक उपलब्धि से पहले, यदि आपके मन में सांसारिक सुख की लालसा है, तो इसका अनुभव करें,\nअजामिल ने शास्त्र का अध्ययन तो किया था, परंतु उसे शास्त्र से प्रेम हो गया।\nइससे पीड़ित का सारा ज्ञान नष्ट हो गया। उसमें तमोगुण नहीं होना चाहिए\nगलती हो गयी. जब हमारे अंदर तमोगुण प्रबल होता है तो हम पर यही प्रभाव पड़ता है।\n\nइस श्लोक में कृष्ण स्पष्ट रूप से बताते हैं कि हमारे अंदर कौन से गुण काम कर रहे हैं\nसमझाया. इस श्लोक का सारांश इस प्रकार है: यदि ज्ञान की प्यास है, तो यह सात्विक गुण है; मैं इसे स्वयं चाहता हूं\nयदि यह लोभ हो कि बाकियों को न मिले, तो यह रहस्य है; कुछ भौतिक\nयदि अत्यधिक प्रेम और स्नेह है तो यह तमस का कार्य है।\n\nसत्त्व-रजसु-तमस के लिए। एक और चेहरा है. पूजा में नई ऊर्जाओं का जिक्र करने के बाद\nभगवान के पास जाने से पहले “सम सत्त्वय नमः-राम-रजसे नमः-तम तमसे।”\nनमः\" एक मंत्र कहता है। कुछ लोग इस मंत्र को इस प्रकार भी कहते हैं: “नहीं\nसत्त्वय श्रीयो नमः-राम राजसे भुवे नमः-तम तमसे दुर्गाय नमः।” [यह\nमंत्र नहीं, मूल मंत्र: \"सम सत्त्वय नमः -राम-रजसे नमः-तम तमसे नमः\" ] यहाँ\nसम सत्वाय नमः का अर्थ सत्त्वगुण को नमस्कार नहीं है - सत्त्व मानिनिया श्री देवी को।\nनमस्कार कहो। राम राजसे नमः का अर्थ है राजो मनिनिया की भू देवी को नमस्कार। श्रीमान\nतमसे नमः का अर्थ है तमो मनिनिया की देवी दुर्गा को नमस्कार। ये तीन लक्ष्मी हैं\nप्रपत्र. लक्ष्मी के मूल स्वरूप को 'महालक्ष्मी' कहा जाता है। इस मूल स्वरूप से तीन आवेश होते हैं\nप्रपत्र.\n\nयहां तो श्रीदेवी ही हैं जो सार जगाती हैं; भूदेवी रजस को जगाने वाली हैं;\nतमोगुण को जागृत करने वाली तमोगुणी की दुर्गा देवी हैं। “सत्त्वात् संजयते\nज्ञानम्”- इसका अर्थ है: सत्त्वगुण की प्रशंसक, लक्षि का, ज्ञानी है। नारायण का ज्ञान\nअगर आप आना चाहते हैं तो आपको श्रीदेवी की कृपा चाहिए. सब जानते हैं कि 'श्रीमान' धन देता है\nलेकिन ज्यादातर लोग यही सोचते हैं कि श्रीदेवी अथाह ज्ञान संपदा की दाता हैं\nज्ञात नहीं. हां, छोटा धन है, लेकिन ज्ञान एक महान धन है - इसे देने वाला 'श्री' ही है। हमारे भीतर\nयदि ज्ञान जागृत करना है तो सबसे पहले मां के श्री रूप की पूजा करनी चाहिए। प्रभु का\nउससे ज्ञान पर दया करने को कहा जाए.\n\nजैसा कि शास्त्री...कहते हैं...मन। ईश्वर की ओर प्रवाहित होना। पहले हम\nमनोमभिमानी की प्रार्थना करनी चाहिए। शिव.मनो$भिमानी देवता। [गरुड़-सुपर्णि, शेष-\nयद्यपि वारुणी और शिव-पार्वती मनोभिमानी हैं, विशेषतः शिव मनोभिमानी हैं।\n\nशिव वह हैं जो अंधकार को दूर करते हैं और ज्ञान चाहने वालों के मन को भर देते हैं।\nपार्वती. इस कारण हमें सबसे पहले ज्ञान के लिए प्रार्थना करनी चाहिए\nशिव तत्व. जब शिव ज्ञान देते हैं तो हम चाहते हैं कि वह मन में स्मृति के रूप में बना रहे\nप्राण शक्ति (ब्रह्म-वायु, सरस्वती-भारती) की प्रार्थना करनी चाहिए। ज्ञान जो हमारे पास आया है\nप्राण शक्ति (आंजनेय) वह मुख्य शक्ति है जो इसे अमोघ (स्थिर) बनाती है। इस तरह\nवह जो स्थिर है वह फिर ऊपर जाती है और भगवान को छूती है - हमेशा भगवान की\nसाथ में लक्ष्मी देवी. ऐसी लक्ष्मी अपने सभी रूपों में जागरूकता नहीं देती। वह उसकी है\nश्रीरूप में वह धन प्रदान करती है जो ज्ञान का रूप है। 'श्री' महालक्ष्मी के अवतारों में से एक है।\nयह वह रूप है जो सत्व पर शासन करता है और दुनिया की सुरक्षा के लिए विष्णु के साथ खड़ा है। इसलिए\nज्ञान के पथ पर चलने वालों के लिए लक्ष्मी का श्री नमक अनुग्रह महत्वपूर्ण है।\nयहां ज्ञान के मार्ग पर शिव, प्राणदेव और श्रीदेवी की कृपा से मृत्यु पहले होती है\nहमने विश्लेषण किया है कि कोई भगवान से जुड़ सकता है। भूतवा के बारे में आगे विश्लेषण करने से पहले\nआइए यहां शांति मंत्र और गणपति प्रार्थना के महत्व का संक्षेप में विश्लेषण करें। कोई भी\nधर्मग्रंथों का पाठ करने से पहले हम \"ओम शांतिः शांतिः शांतिः\" का जाप करते हैं।\nहे ज्ञान के शिखर भगवान, मुझे ज्ञान (शांति) के मार्ग में लगाओ।\nयही इस शांति मंत्र का अर्थ है. इसी प्रकार हर पूजा में सबसे पहले गणपति की प्रार्थना होती है\nक्योंकि शिव-पार्वती के पुत्र गणपति आकाश के देवता हैं। यह आकाश प्रभु का है\nनाभि से निर्मित. तो गणपति हमारे नाभि देवता हैं।\n\nनाभ्य असीदन्तरिक्षं शेष्नो द्यो संवरथा\n\nपद्भ्यं भूमिर दिश श्रोत्रथ तत् लोक अकल्पयन\nहमारी नाभि के पास तीन चक्र हैं मूलाधार, स्वाधिष्ठान और मणिपुर।\nनाभि से ऊपर की ओर हृतकमल में वास्तविक उपलब्धि का शाश्वत चक्र है। नींव,\nयदि आप स्वाधिष्ठान और मणिपुर चक्र, नाभि द्वार से परे हृदय में प्रवेश करना चाहते हैं\nगणपति को खोलना चाहिए. इसके लिए हम सबसे पहले गणपति से प्रार्थना करते हैं। प्रति\nयज्ञ से पहले गणपति मंडल को लिखें और पूजा करें, फिर यज्ञ शुरू होता है। गणपति की नाभि\nजब दरवाज़ा खुलता है तो दिल अपने आप खुल जाता है। इस स्थिति को 'वृषः' कहा जाता है।\nइस अवस्था में भगवान हमारी पूजा को वर्षा के रूप में स्वीकार करते हैं। ऐसे प्रभु\nइसे 'वृषही' के नाम से भी जाना जाता है।\n\n\"रजसो लोभ एव च\" - राजस्सु का अर्थ है भूदेवी जो रजोगुण की प्रशंसक है। यहाँ भूदेवी\nवह अठारहवीं कक्षा का देवदूत नहीं है जो पृथ्वी पर शासन करता है। उस पर भी राज करो\n\n'पृथ्वी' लक्ष्मी का अवतार है। उसी से सृजन हुआ। मनोरंजन, आकर्षण, आकर्षण, आकर्षण -\nये सभी रजोगुण के मुख हैं। तो मूलतः एक दूसरे से प्रेम करना\nवांटेड-रंजन. स्त्री-पुरुष का आकर्षण ही सृष्टि का कारण है। सृजन को आवश्यक आक्षेप दें\nरजोगुण में समान आक्षेप उत्पन्न करने और उससे विमुख करने का तत्व होता है। ऐसा है रजोगुण\nभूदेवी प्रकृति की दाता हैं। मेरी संपत्ति, मेरा घर, मेरा काम, मेरा पैसा, आदि\nयह रजोगुण से आता है।\n\n\"प्रमदा मोहौ तमसः भवतः अज्ञानम् एव च\" - हमें शारीरिक रूप से नष्ट करने के लिए।\nधारण-संहारक शक्ति, तमोगुण की उपासक..दुर्गा। वह वध की ओर अग्रसर है\nवह जाने की सलाह देती है. गलत को सही जानकर गलत करना, उससे बचना\nपतन, ज्ञान की अधिकता, ज्ञान का अभाव आदि तमोगुण के प्रभाव के कारण होते हैं।\nइस प्रकार। श्री-भू-दुर्गा, सत्व-रजसु-तमस्सिना चित्रकला के तीन तत्व हैं।\nप्रशंसकों के रूप में, हम त्रिगुणों से बंधे हैं। इसलिए चित्रकला की भावना\nतीन रूप सत्त्व-रजसु और तमस्सु हैं। [यहाँ यह अर्थ क्यों करना चाहिए?\nगाने में ही एक सुराग है. इसे आगे इस अध्याय के 19वें श्लोक में देखा जा सकता है। महालक्ष्मी\nश्री-भू-दुर्गा के स्वरूप के बारे में अधिक जानकारी के लिए महाभारत तात्पर्य देखें\n\"सर्गानुसर्ग-लय-प्रादुर्भाव निर्देश\"] पढ़ें।",
  "14.18": "ऊर्ध्वं गच्छन्ति सत्त्वस्थः मधे तिष्ठन्ति राजसः।\nजघन्यागुण वृत्तिस्थः अधः गच्छन्ति तमसः-सत्व ऊंचा होगा। राजस\nबीच में खड़े हो जाओ. 'अंतिम गुण' से प्रभावित तमस नीचे की ओर गिरता है।\n\nत्रिगुण की प्रकृति के बारे में बात करने वाले कृष्ण ने इस श्लोक में इसके प्रभाव के तीन चरणों की व्याख्या की है।\nसत्व में रहने वाले लोग मानसिक रूप से ऊपर उठते हैं। रजोगुण की कोई समृद्धि नहीं है।\nतमस में व्यक्ति मानसिक रूप से पतित हो जाता है। यहाँ 'उर्ध्व' शब्द विशेष है\nअर्थ है. जैसा कि कठोपनिषद कहता है:\n\n॥॥\nउर्ध्व का अर्थ है सर्वोपरि भगवान। सत्व में आरोहण का अर्थ है-\nईश्वर की ओर बढ़ना. जैसे-जैसे वह आगे बढ़ता गया वह भगवान के करीब होता गया\n\nजाता है लेकिन जो तमस में है वह भगवान की ओर पीठ करके चलता है। राजसा था\nवह अभी भी अनिश्चित स्थिति में है।\n\n'श्रीदेवी', वह शक्ति जो देवताओं को नियंत्रण में रखती है; मनुष्य को बंदी बनाने की शक्ति है \"भूदेवी\" और\n'दुर्गा देवी' राक्षसों को कैद में रखने की शक्ति हैं। सात्विक 'श्रीदेवी' की कृपा से सत्त्वमानिनी होते हैं\nएक पात्र के रूप में, व्यक्ति ऊपरी लोक [पृथ्वी के ऊपर के छह सूक्ष्म लोकों] को प्राप्त करता है\nऔर अंततः मोक्ष]; राजा अभी भी भूदेवी [भूमि और] की हिरासत में हैं\nअत्याचार] और तमस तमसलोक [पृथ्वी] से देवी दुर्गा के नियंत्रण में हैं\nनीचे दिए गए सात सूक्ष्म जगतों से जुड़ें]।\n\nन[5]न्यं गुणेभ्यः कर्तारं यदा दृष्टा 5नुपश्यति |\nगुणेभ्यश्च परमं वेत्रि मद्भा वाम सोइधिगच्छति ॥19॥\n\nन अन्यं गुणेभ्यः कर्तारं यदा दृष्टा अनुपश्यति।\n\nगुणेभ्यः च परम वेत्ति मत भावम् सः अधिगच्छति - त्रिगुणों के अलावा इन सभी प्रभावों के लिए।\nवह जो पाता है कि कोई अन्य कारण नहीं है [भगवान जो त्रिगुणों से अलग है वह सभी का स्रोत है\nवह जो कारण के रूप में जानता है] और वह जो भगवान को गुणों से परे जानता है [सत्य\nमनुष्य-वह] मुझमें निवास करता है।\n\nहमारे जीवन में जो कुछ भी घटित होता है वह इन तीन गुणों की प्रक्रिया है। हम स्वयं हैं\nकुछ नहीं करता. इसके बजाय सब कुछ त्रिगुणों के प्रभाव में चल रहा है। प्रकृति से आ रहा है,\nवे हमारे फॉर्मेट को बंद करके काम करते हैं. इसलिए। एक व्यक्ति की शक्ल\nआचरण से उसके वास्तविक स्वरूप को जानना संभव नहीं है। इस वजह से हम\nसंसार में होने वाली घटनाओं को वैराग्य से देखने की आदत डालनी चाहिए।\n\nसत्त्व से अभ्यस्त मन केवल उसी को देखता है जो सत्व से मेल खाता है। ऐसा व्यक्ति कदापि नहीं\nइसमें कोई भ्रम नहीं है कि 'मैंने यह किया।'\nकिसी भी चीज़ को कभी भी कर्ता नहीं कहा जाता है। अतः गुण केवल निष्क्रिय गुण नहीं है। उसके लिए\nइस कविता में प्रशंसक भावना को पहचानने का संदेश है। [श्लोक 17 में हमारे पास यह है\nके बारे में चर्चा की]। लेखकत्व के अनेक प्रकार. जहां भी कोई इच्छुक कार्य हो, वही कर्ता है। ये है\nअस्तित्व केवल आत्मा के लिए है. लेकिन सच्चा लेखकत्व एक \"स्वतंत्र स्वैच्छिक कार्य\" है। यह मौजूद है\nकेवल प्रभु में. हम सभी प्रसिद्ध कहावत \"नहं कर्ता हरिः कर्ता\" को जानते हैं।\nमोक्षधर्मपर्व में इस प्रकार कहा गया है:\n\nनहं कर्ता न कर्ता त्वं कर्तायस्तु सदा प्रभु ॥\n\nसोत्$यं पचति कालो मम वृक्षे फलं इवगतम् ॥ 12-220-84\n\"तुमने यह नहीं किया है, मैंने यह नहीं किया है - \"उसने' यह हमारे द्वारा किया है\"।\nअहंकार नहीं आ सकता. इससे कोई नफरत नहीं, कोई कड़वाहट नहीं. \"मैंने किया, नन्नी 0दायता\"\nयह सिर्फ एक भ्रम है. इस संसार में जो कुछ भी होता है वह इन तीन गुणों के प्रभाव के कारण होता है\nघटित। इसके अलावा मैंने अपने लिए कुछ नहीं किया है.' यह अहसास हमें आना चाहिए.\nत्रिगुणों का प्रभाव जड़ के साथ-साथ आत्मा में भी होता है। इसके प्रभाव में ही कार्रवाई होती है।\nयदि कोई आपको डांटता है, तो इसका मतलब है कि उस समय रजोगुण सचेत रूप से काम कर रहा है\nइसका मतलब है करना. हमें उस क्षण इस जागरूकता के साथ कार्य करना चाहिए। स्वयं श्री रामचन्द्र\nउन्होंने जीवन में चलकर दिखाया है. रामायण में वाल्मिकी कहते हैं:\n\nस हि नित्यं प्रशांतं मृदुपूर्वः च भासते |\n\nउच्चामनोअपि पौरूषं नोथरं प्रतिपद्यदा ॥अयोध्या-1.15॥\nयदि कोई उनसे झगड़ा करता तो राम कभी क्रोधित नहीं होते थे। \"चलो फिर बात करते हैं\"\nमानो जा रहा हो. क्योंकि जब किसी व्यक्ति में रजोगुण काम कर रहा होता है।\nहम उनके साथ हैं. ऐसे समय आएंगे जब आपको शालीनता से काम लेना होगा। यह बहुत\nख़तरनाक इसलिए जो लोग दुःखी हैं उनके साथ राजा न बनें। तटस्थता से बहुत दूर\nरुकें \nअगर आप चुप रहेंगे तो उनका गुस्सा बहुत जल्दी शांत हो जाएगा। इस प्रकार जब हम इन गुणों के प्रभाव को पहचानते हैं\nहमारा जीवन भी अलग होगा.\nउपरोक्त जानना पर्याप्त नहीं है. भगवान इन त्रिगुणों से परे हैं। उसे\nयह जानने से आपको त्रिगुणों से परे खड़े होने में मदद मिलेगी। मैं उस भगवान से जुड़ने के लिए यहां हूं\nहमें इस सत्य को समझना होगा कि हमें त्रिगुणों के प्रभाव से बाहर आना होगा। “ऐसे लोग\nमन मुझमें बस जाता है और इसी कारण वे आकर मुझमें मिल जाते हैं\nकृष्ण कहते हैं.\nइस श्लोक का एक और पहलू भी है. “गुणेभ्यः अन्यं कर्तारं यदा दृष्टा अनुपश्यति तदा सः\n'न' भवति''। यहाँ \"गुणेभ्यः अन्यम्\" का अर्थ है त्रिगुणमणिनि, जो गुणों से युक्त है,\nश्री-भू-दुर्गा नाम दिया गया, जो महालक्ष्मी से भी बड़ी शक्ति है। वह असली भगवान है.\nजैसा कि मुंडकोपनिषद कहता है:\n\nयदा पश्यः पश्यते रुक्कवर्णं कर्तारमीशं पुरुषं ब्रह्मयोनिम् ॥ 3-1-3\n\nचार चेहरों का पिता कौन है, चित्रकला का स्वामी कौन है, संपूर्ण कौन है\nवेदों से पढ़ें - वही सृष्टिकर्ता है। जो यह जानता है वही सच्चा मनुष्य है।\n\nकेवल शरीर - मानव शरीर - सभी आध्यात्मिक उपलब्धियों के लिए सुसज्जित है। ऐसा शरीर\nउपयोग करने के लिए तत्पर. धर्म-अर्थ-काम से वैराग्य का अर्थ है सत्त्व-रजसु-\nतमोगुण से छुटकारा पाने और भगवान से जुड़ने के लिए। यही मानव जीवन का लक्ष्य है। \"यह\nमुझमें तीन गुण काम कर चुके हैं, मुझे इस प्रभाव से छुटकारा पाना चाहिए और ऊपर उठना चाहिए।”\nजागना केवल मनुष्य के लिए है। इस जागरूकता के कारण ही उसमें ''मद्भवाम् सोद्धिगच्छति''\nअपने मन को भक्ति ज्ञान से भरकर मोक्ष प्राप्त करता है।\n\nगुणानेथनतित्य तीन देहि देहसमुद्धवन् |\nजन्ममृत्युजरादुःखैरविमुक्तो*मृतमश्नुते",
  "14.19": "सत्त्वं सुखे संजयति रजः कर्माणि भारत।\nज्ञानं अवृत्य तु तमः प्रमादे संजायति उता - सत्त्वगुण आनंदमय अवस्था में है। भरत,\nरजोगुण कर्म की नन्ती में है। तमोगुण चेतना को बंद कर देता है और उसे मंत्रमुग्ध कर देता है।\n\nइस श्लोक में कृष्ण ने तीन गुणों का सारांश दिया है। सत्व का मूल गुण\nउसके कारण, हमारे भीतर एक स्वाभाविक आनंद उमड़ता है। रजोगुण “कुछ भी\nयह करना ही होगा, नहीं तो जीवन में कोई खुशी नहीं रहेगी'', हमेशा पैसे के लिए लड़ते रहते हैं\nजीवन को पहनने योग्य बनाता है। तमसु हमारे पास मौजूद ज्ञान को अस्पष्ट कर देता है। उदाहरण के लिए:\nजरूरतमंदों की मदद करना, देने में प्रसन्नता - सत्त्वगुण।\nहमेशा खुश रहने के लिए खुशी की तलाश में रहते हैं, ऐसा न करें\nकरना और जीना रजोगुण है। आलस्य, तंद्रा, अज्ञान ये सब गलतियाँ हैं\nतमोगुण का प्रभाव. यह कृष्ण गीता द्वारा हमें बताया गया उच्चतम मनोविज्ञान है।\n\nये गुण हमें कैसे नियंत्रित करते हैं और हमें गिरा देते हैं\nकृष्ण ने जो सुनाया है वह हमने देखा है। यहां हमें संदेह हो सकता है. ये तीनो गुण एक साथ\nएक साथ काम करते हुए, केवल सात्विक विचार, केवल राजस विचार, केवल तमस\n\nसोचना कैसे संभव है? जब किसी के शरीर में तीन गुण मौजूद होते हैं, तो वह एक गुण होता है\nकाम करना कैसे संभव है? जब वे हमारे भीतर होते हैं तो तीन गुण मिश्रित होते हैं और एक अलग\nसात्विक स्वभाव, राजस स्वभाव, तमस स्वभाव की पहचान कैसे करें? इसका स्पष्टीकरण\nअगला श्लोक.\n\nरजस्तमाश्चभिभूय सत्वं भवति भारत।\n\nरजः सत्वं तमश्चैव तमः सत्वं रजस्तथा",
  "14.20": "गुणं एतां अतित्य त्र्येन देहि देहा समुद्धवान् |\nजन्म मृत्यु जरा दुक्खैः विमुक्तः अमृतं अश्नु ते-देहः ये तीन चीजें शरीर में उत्पन्न होती हैं।\nजब वह गुणों से परे हो जाता है, तो वह जन्म और मृत्यु के दुखों से मुक्त होकर अमर हो जाता है।",
  "14.21": "अर्जुन उवाच-अर्जुन ने पूछा:\n\nकैः लिंगैः त्रिने गुणन एतं अतीतः भवति प्रभो।\n\nकिं अचरः कथं च एतां त्रिने गुणन अतीवर्तते - हे भगवान, ये किस निशान से हैं\nवह सोचता है कि वह तीन गुणों से पार हो गया है? उसका व्यवहार कैसा है? इन तीनों के बारे में क्या ख्याल है?\nगुणों को पार करता है?\n\nअर्जुन हम सभी की ओर से कृष्ण से प्रश्न करते हैं। वह पूछता है: “तीन गुण\nजो व्यक्ति पार कर गया है उसे कैसे पहचानें? उसका निशान क्या है? उसका व्यवहार\nवह इन तीन गुणों को कैसे पार करता है?”\n\nयहाँ अर्जुन कृष्ण को \"प्रभो\" कहकर संबोधित करते हैं। “निश्चित रूप से मेरे प्रश्नों का उत्तर दो\n\nकोडबल्लावा-निनोब्बाने'' इस संबोधन के पीछे की आवाज और ''पूर्ण समर्पण'' है।\nभगवान अर्जुन ने इस प्रश्न का उत्तर निम्नलिखित श्लोक में विस्तार से दिया है।\n\nभगवान का वचन\nशं च प्रद्धतम च मोहमेव च पांडव।\n\nका\nन वेहति संप्रवृत्ति न निवृत्ति कांक्षति",
  "14.22": "भगवान उवाच- भगवान ने कहा:\n\nप्रकाशम् च प्रशस्तं च मोहं ईव च पांडव।\n\nन वेहति संप्रवृत्तानि न निवर्तनि कांक्षति-पांडव, न सांसारिक प्रकाश का प्रकाश न कायका।\nहुरुपन्ना गैले, भ्रांतियान्ने न तो - जब होता है तो नफरत करता है; जब वहाँ नहीं है तो मत चाहो।\n\nजो तीन गुणों को पार कर चुका है वह कुछ अवांछनीय घटित होने पर घृणा नहीं करता;\nकोई उस चीज़ की इच्छा नहीं करता जो वांछित है जब वह नहीं मिलती। “क्या आवश्यक है, क्या नहीं है\nभगवान मुझसे बेहतर जानता है. मुझे इसकी चिंता क्यों करनी चाहिए?\nवैराग्य उसमें है. वह जीवन में जो कुछ भी मिलता है उसका स्वागत करता है। व्यास\nमहाभारत के शांति पर्व में एक कहावत है:\nएवम अप्प्य अशुभं कर्म न भूतं न भभाति॥ 12-32-18॥\n\n\"जो होगा वह न तो अतीत में हुआ है और न ही भविष्य में होगा। जो होगा वह होकर रहेगा।\"\nनफरत करने का नतीजा क्या है कि मैं इसे नहीं चाहता?\"। तो जो त्रिगुण को पार कर गया है - 'नहीं' आता है।\nउससे नफरत मत करो; जो नहीं है उसकी कोई चाहत नहीं है. हर चीज़ को उदासीनता से देखना, भरा हुआ\nवह बिना दिये रहता है।\n\nसंसार में कुछ लोग तत्व में रुचि रखते हैं, जबकि कुछ लोग केवल वृत्ति में रुचि रखते हैं। और कुछ के लिए क्या\nदिलचस्पी भी नहीं - यह नहीं जानते कि अंधेरा अंधेरा है। ऐसे लोग हैं जो अंधेरे में रहते हैं। ये है\nएक बहुत ही सामान्य विचार. जो लोग त्रिगुण से परे खड़े हैं वे इसे और अपने मन को देखते हैं\nविकृत नहीं करता. \"सब कुछ उसके गुणवत्ता प्रभाव के अनुसार हो रहा है\"।\n\nवे जानबूझकर और तटस्थ होकर जीते हैं। वह वही कहता है जो उसे सत्य दिखता है। लेकिन कभी बहस नहीं की\nविवाद पैदा नहीं करता. \"सब कुछ भगवान का काम है, उसने सब कुछ व्यवस्थित किया है।\"\n\"सच्चा भक्त\" कैसा होता है इसका वर्णन करते समय गीता के बारहवें अध्याय में स्वीकार करेंगे\nइस श्लोक में कृष्ण ने वही व्याख्या दी है। इसका अर्थ है- बाह्य गुण से परे\nखड़ा रहना ही सच्ची भक्ति है.\n\nयहाँ व्यास \"पांडव\" विशेषण का प्रयोग करते हैं। पांडा का अर्थ है बुद्धिमान। पांडव का अर्थ है\nजो ज्ञान को पहचान कर झुक जाता है। \"त्रिगुणातीत बनने से पहले तुम्हें पांडव बनना होगा\"\nइस विशेषण के पीछे संदेश है.",
  "14.23": "उदासीनवत् असीनः गुणैः यः न विचल्यते।\n\nगुनाः वर्तमानं इति एवं यः अवतिष्ठति न इंगते - उदासीन रहता है। गुण\nआक्षेपों से अविचल. वह बेड़ा छोड़ देता है यह देखने के लिए कि उसमें गुण हैं या नहीं। वह उनकी धुन में है\nझुकता नहीं.\n\nवह सांसारिक मामलों से उदासीन रहता है। हमारी चाहत और जरूरतें हैं\nत्रिगुणों से. त्रिगुणातिता- \"ऐसा और वैसा\" नहीं चाहती।\nउनका विश्वास है कि \"भगवान जैसा चाहेंगे वैसा ही करेंगे\"। [यहाँ एक है\nहमें विषय को जानना होगा. दुनिया में क्या होता है यह हमारे नियंत्रण में नहीं है. हम हैं\nजो आप सोचते हैं कि नहीं होना चाहिए वह हो सकता है, जो आप सोचते हैं वह नहीं हो सकता।\nऐसे में व्यर्थ में यह कहकर दिमाग पर जोर डालने का कोई मतलब नहीं है कि ``ऐसा ही होना चाहिए'']।\nजब आप इस तरह रहते हैं, तो जो आप चाहते हैं वह न मिलने पर कोई गुस्सा नहीं होता, और कोई पलायन नहीं होता। मन प्रसन्न है.\n\nइन्द्रियाँ गुणों में हैं, इन्द्रियों के पीछे गुण हैं। लेकिन तीन गुना\nयह सब जानते हुए, बिना परेशान हुए, किसी भी क्रिया में [यहाँ तक कि अस्थायी क्रिया में भी]।\nबिना चपलता के रहता है।",
  "14.24": "सम दुःखसुखः स्वस्थः सम लोषा अश्म कांचनः।\n\nतुल्य प्रिया अप्रियः धीरा तुल्का निन्दात्मा संस्तुतिः - सुख और दुःख को समान रूप से देखता है।\nवह अपने आप में रहता है. मिट्टी, पत्थर, सोना उसके लिए एक समान हैं। उपलब्धि से मजबूत हुआ\nउसका प्रिय वही है; अप्रिया वैसी ही है. एक चुटकुला भी है. स्तुति वही है.\n\nत्रिगुणातिता सभी सुखों और दुखों को समान रूप से देखती है। क्योंकि जाहिरा तौर पर हमारे लिए\nजो सुख प्रतीत होता है, जरूरी नहीं कि वह सुख ही हो। दुःख भी वैसा ही है. यह\nजब आप जान जाते हैं तो मन में यह भावना जगती है कि सब कुछ प्रभु की लीला है। फिर सब बराबर है\nहमारी देखने की क्षमता बढ़ेगी.\nजिस प्रकार हम दर्शक के रूप में नाटक में दृश्य देखते हैं, उसी प्रकार संसार में भी\nघटनाओं को दर्शक बनकर देखने की आदत डालनी चाहिए। यह आनंदमय हो सकता है,\nदुखी हो सकते हैं-लेकिन हम हैं। मनुष्य को भगवान के प्रत्येक कार्य का आनंद लेना चाहिए।\nजीवन में अस्थायी दुःख हमारे शाश्वत सुख की ओर ले जाते हैं। लेकिन वह हमारे लिए है\nपता नहीं बस इतना ही. त्रिगुणातीतों को इसका एहसास हुआ और उन्होंने सुख और दुःख को समान रूप से देखा\nखुशी से जियो.\nकृष्ण यहाँ उन शब्दों को दोहराते हैं जो उन्होंने पहले ज्ञानियों और भक्तों के लक्षणों का वर्णन करते समय कहे थे\nवह दोहराता है. पृथ्वी त्रिगुणात्मक, अनमोल रत्न; सोना - सब कुछ वैसा ही है. उसे\nन तो सोना और न ही रत्न कीमती माने जाते हैं। उसके लिए अनमोल है केवल ज्ञान। यह\nक्योंकि उसे धन, मोती या सोने की कोई इच्छा नहीं है।\nनहीं लगता इसलिए वह सुख से रहता है। भागवत के तीसरे स्कंद में होता है\nएक श्लोक कहता है:\n\nयश्च मुधतमो लोके यश्च बुद्धे परमं गथा\n\nवौमभौ सुखमेधेते क्लिश्यतान्तरितो जनः ॥3-7-17॥|\nएक मूर्ख और दूसरा बुद्धिमान - कि ये दोनों संसार में सुखपूर्वक रह सकें। क्योंकि\nउन्हें पैसे से कोई प्यार नहीं है. लेकिन जो लोग दोनों के बीच में हैं वे जीवन का अर्थ नहीं जानते\nवे प्यार का शिकार हो जाते हैं और दुःख महसूस करते हैं।\nरामकृष्ण ने बताया कि कैसे बुद्धिमान लोग इस सिद्धांत को अपने जीवन में अपनाकर जीवन जीते हैं\nइसका एक अच्छा उदाहरण परमहंस की जीवनी है। मैसूर महाराजा के समय में सोदेमाथा\nदूसरी विश्वप्रियतीर्थों (वृन्दावनाचार्यों) द्वारा जीयी गयी जीवन शैली है जो स्वामी थे\nएक अच्छा चित्रण.\n\nइस श्लोक को दूसरी तरफ से देखने पर हमें एक और विशेष संदेश मिलता है।\nएक सच्चे भक्त (त्रिगुणातीत) की भगवद भक्ति उसके जीवन में आने वाले सुखों और दुखों से आती है।\nउतार-चढ़ाव नहीं होता. चाहे वह गरीबी में हो या गरीबी में, वह निरंतर भगवान की भक्ति में लगा रहता है।\nदूसरों का प्रेम-घृणा उसकी भक्ति की कसौटी नहीं है। इस प्रकार सभी त्रिगुणातीत हैं\nवे पद-प्रतिष्ठा में भी समानता के साथ रहते हैं।",
  "14.25": "मन अपमानयोः तुल्यः तुल्यः मित्र अरि पक्षियोः।\nसर्वारंभ परित्यागी गुणतितः सः उच्यते एक गरिमा ही है; अपमान भी वैसा ही है.\nदोस्तों का ग्रुप वही है; शत्रुओं का समूह एक ही है. वह इतना सांसारिक नहीं है\nशामिल नहीं. ऐसे व्यक्ति को 'गुणातीत' कहा जाता है।\n\nकोई त्रिगुणातिता को 'महान ऋषि' के रूप में बोल सकता है, कोई अन्य\n'आधा पागल'. उसका दुरुपयोग किया जा सकता है. लेकिन इसका उन पर कोई असर नहीं होता. इनके लिए\nन मित्रों से प्रेम है, न शत्रुओं से घृणा है। ये तो हर कोई है\nभगवान की भक्ति के विपरीत किसी भी गतिविधि में, जैसा वे उचित समझें\nवे बिना उलझे रहते हैं। वह स्वयं किसी दीर्घकालिक परियोजना में हैं\nशामिल नहीं.\n\nइस प्रकार उपरोक्त चार श्लोकों में कृष्ण ने निर्गुणों के स्वरूप का सुन्दर वर्णन किया है\nवर्णित हम उन लोगों को गुणपिता के रूप में पहचान सकते हैं जिनके पास यह स्वभाव है।\n\nअब तक कृष्ण ने अंतिम दो त्रिगुणों और त्रिगुणों की प्रकृति के बारे में बताया है\nश्लोक में उन्होंने बताया कि हम त्रिगुणातीत कैसे बन सकते हैं। हम सब\nजबकि प्रवृत्ति इन तीन गुणों की सीमा के भीतर है, यह हमारा काम है कि हम तीन गुणों से परे खड़े हों\nअकल्पनीय इसलिए यहां कृष्ण हमारे लिए त्रिगुणातीत बनने का एकमात्र तरीका हैं\nसमझाता है.",
  "14.26": "माँ च यः अव्यभिचारेण भक्तियोगेन सेवते।\n\nसः गुणं समतित्य एतं ब्रह्मभूया कल्पते - मेरे प्रति अनन्य भक्ति सहित\nउपासक इन गुणों के बंधनों को तोड़कर भगवान की भक्ति के लिए प्रकृति के समान होता है\nएक भूमिका बन जाती है। [आत्मा प्रकृति से जुड़ जाती है]।\n\nयदि हम स्वयं त्रिगुहतीत बनने का प्रयास करें तो हमें उस प्रयास में सफलता मिलेगी\nनहीं कर सकते क्योंकि हमारी सारी सोच त्रिगुण के इर्द-गिर्द घूमती है। यह एक चक्र है. यह चक्र\nमोह से बचने के लिए उस सारथी को आना ही होगा। जैसा कि द्वादशस्तोत्र कहता है:\n“त्रिगुणातिता विधारक परितो देहि सुभक्तिम”। वह जो त्रिगुणातीतों का संरक्षण करता है\nप्रभु. इसलिए तीन गुना बनने का एकमात्र तरीका उस भगवान के प्रति समर्पण करना है।\nउस भगवान के प्रति एकनिष्ठ भक्ति से जो लक्ष्मी है - लक्ष्मी द्वारा\nमृत्यु पन्द्रह बेड़ियों से सुसज्जित होकर संसार में आई और इन सभी बेड़ियों को छीन लिया\nमाँ की गोद में लौट सकता हूँ.",
  "14.27": "ब्राह्मणः हि प्रतिष्ठा अहं अमृतस्य अव्ययस्य च |\nशवस्थस्य च धर्मस्य सुखस्य इकांतिकस्य च -मैं स्वयं प्रकृति की शाश्वत और अपरिवर्तनीय छवि का आधार हूं-\n\nसनातन धर्म का आधार और आनंदमय मोक्ष का भी।\n\nत्रिगुण से परे खड़े होकर जीवन का स्वाभाविक-शाश्वत धर्म व्यक्त होता है। इस हालत में\nचित प्रकृति, ब्रह्मत्व (श्री लक्ष्मी भी उस प्रभु का समर्थन करती हैं) को मोक्ष में जोड़ा जा सकता है।\n\nइति चतुर्दशोऽध्यायः\nचौदहवाँ अध्याय समाप्त हो गया\n\nक्या यह सच है?\n\nअध्याय ग्यारह\n\nयह अध्याय गीता का सबसे छोटा अध्याय है। यहाँ फलश्रुति के दो श्लोकों को छोड़कर,\nइसमें अठारह श्लोक हैं जो परिसर का हिस्सा बताते हैं। इन अठारह श्लोकों में कृष्ण ही संपूर्ण संसार हैं\nउन्होंने राज खोल दिया है. यदि महाभारत भारतीय दर्शन का प्रतीक है, तो भगवद गीता है\nमहाभारत का सार. ऐसी भगवद्गीता का सार है यह पन्द्रहवाँ अध्याय। इस अध्याय को समझें\nयदि आप ऐसा करेंगे तो आप न केवल संपूर्ण गीता, बल्कि संपूर्ण भारतीय दर्शन को समझ जायेंगे।\nइस अध्याय पर भाष्य लिखते हुए शंकराचार्य कहते हैं: “न केवलं गीतार्थः, तथास्तु\nसर्वोपि शास्त्रतः अत्र पर्यवसितः।'' ''यह सिर्फ गीता का सार नहीं है। सभी धर्मग्रंथ\nवे जो कुछ भी कहते हैं वह इस अध्याय में है।\" The quintessence of entire Indian Philosophy is 15th Chapter of Bhagavad Gita. माधवाचार्य अपने अधिकांश लेखों में\nउन्होंने अध्याय के तीन श्लोकों (16, 17, 18) का उल्लेख किया है। क्योंकि इन श्लोकों में\nआचार्यों के सभी सिद्धांतों में सार समाहित है।\n\nअतीत में एक परंपरा थी. जब खाने के लिए बैठें, तो यह भोजन शुरू करने से पहले होता है\nअध्याय का श्लोक पढ़कर फिर भोजन करना। “भोजन पत्र से पहले संपूर्ण शास्त्र\n'हम पहुंचे सार के पास' उस परंपरा का कारण यही है।\nतेरहवें अध्याय में कृष्ण ने क्षेत्र और क्षेत्र विशेषज्ञों के बारे में बताया। विश्व और विश्व निर्देशक\nइस अध्याय में कृष्ण एक और पहलू के साथ, भगवान के विषय को और भी अधिक स्पष्ट करते हैं\nसमझाता है. प्रकृति और प्राकृत ब्रह्मांड, उस ब्रह्मांड और अंततः संपूर्ण को पार करने का साधन\nइस अध्याय में दर्शनशास्त्र का संग्रह है। एक अनोखा संज्ञानात्मक संदेश जिसे हमें जानना आवश्यक है\nकृष्ण ने इस अध्याय के माध्यम से बताया है.\n\nचेनानाचेतन विश्व-क्षरा'। उससे आगे चित्र है-'अक्षर'। उससे परे सब कुछ\nनियमका भगवंत-'पुरुषोत्तम'। जैसा कि बारहवें अध्याय-पंद्रह के आरंभ में बताया गया है\nबाड़ों से घिरा सोलहवाँ जीवन। उसने इस पन्द्रह को सोलह के आसपास कस लिया\nसत्रहवीं श्रीलक्ष्मी हैं। जो हमें इस बाड़ से मुक्त कर मोक्ष प्रदान करें\nपुरूषोत्तम, अठारहवाँ। [इन पंद्रह बाड़ों के बारे में विस्तार से जानने के लिए\nप्रश्नोत्तरी का छठा प्रश्न देखें। श्रद्धां खं वायुः ज्योतिः आपः पृथिवी इन्द्रियम्\nमनः | अन्नमन्नादि वीर्यं तपो मन्त्रः कर्म लोकः लोकेषु च नाम च ॥ 6-4 ये हैं\nवे पंद्रह बाड़ें]।\n\n\"अठारह' एक संख्या है जो हमारे सामने दर्शनशास्त्र का सार प्रस्तुत करती है। इस अध्याय में\nअठारह श्लोकों के माध्यम से, कृष्ण ने हमारे सामने सभी विज्ञानों का सार खोल दिया है। चलो\nआइए कृष्ण से सुनें अनोखा अध्याय.\n\nभगवान का वचन\nउर्द्वमूलमदहशखमश्वत्थं प्राहुरव्ययम् |\nछन्दमसि यस्य पर्णानि यस्तं वेद स वेदवित् ॥1॥",
  "15.1": "भगवान उवाच- भगवान ने कहा:\n\nऊर्ध्वमूलं अधः शाखां अश्वत्थं प्राहुः अव्यम् |\n\nछंदंसि यस्य पर्णानि यस्तं वेद सः वेदवित् - ऊपर भगवान और ब्रह्मांड में प्रकृति।\nजनजाति। निम्नलिखित जीव-जड़ इसके शाखाएँ और टहनियाँ हैं। यह सदैव विद्यमान है, [अश्वत्थ - आज\nजैसे कि कोई कल नहीं है], [अश्वत्थ-निरंतर गति वाला घोड़ा] एक खिलता हुआ पेड़ है। वेद\nइसकी पत्तियाँ. जो यह जानता है वह वेदों को जानता है।\n\nयह श्लोक इस बात का प्रमाण है कि भगवत गीता ही उपनिषद का सार है। कठोपनिषद में कहा गया है:\n\"उर्ध्वमूलो अवाक शाखाः एशो अश्वत्थः सनातनः\"। यहाँ इसे “ऊर्ध्वमूलम्” कहा जाता है\nअधः शाखां अश्वत्थं प्राहुः अव्ययम्”। यह एक पंक्ति है जिसमें सामग्री शामिल है.\nयहां के एक-एक शब्द में बहुत सारा दर्शन छिपा हुआ है।\n\nयदि इस पंक्ति का सीधे कन्नड़ में अनुवाद किया जाए तो, \"यह संसार एक खिलता हुआ वृक्ष है\nऊपर क्या है, शाखाएँ और टहनियाँ नीचे है”। जाहिर तौर पर यह पंक्ति\nहमारे लिए देखने का कोई मतलब नहीं है. \"खिलता हुआ पेड़\" - यह क्या है? विशेष रूप से\nकृष्ण ने अश्वत्थ वृक्ष क्यों कहा? उस पर फल नहीं आता, उस पर फूल नहीं आते, वह घर में काम नहीं आता\nयह",
  "15.2": "अधश्चोर्ध्वं प्रसृतास्तस्य शाखा गुणप्रवृद्धा विषयप्रवालाः ।\nअधश्च मूलान्यनुसन्ततानि कर्मानुबन्धीनि मनुष्यलोके ॥\n\nत्रिगुणों से पुष्ट इस वृक्ष की शाखाएँ ऊपर और नीचे दोनों ओर फैली हैं। शब्द-स्पर्श-रूप-रस-गन्ध — ये पाँचों विषय इसके नव-पल्लव हैं जो जीवों को निरन्तर आकर्षित करते हैं।\n\nअधः मूलानि — जीवों के कर्मानुसार अधोलोकों में भी जड़ें फैली हैं। हमारे अपने शरीर में भी — सहस्रार से लेकर नीचे तक — भगवान् व्याप्त हैं, त्रिगुण शाखावत् और पाँच विषय पल्लववत् हैं।\n\nमनुष्यलोक ही साधनाभूमि है। अतः कर्मबन्धन काटकर मूलच्छेद करना कर्तव्य है।",
  "15.3": "न रूपमस्येह तथोपलभ्यते नान्तो न चादिर्न च सम्प्रतिष्ठा ।\nअश्वत्थमेनं सुविरूढमूलम् असङ्गशस्त्रेण दृढेन छित्त्वा ॥\n\nसंसार में रहते हुए संसार का सम्पूर्ण स्वरूप नहीं देखा जा सकता — न अन्त, न आदि, न प्रतिष्ठा। जैसे समुद्रतट पर बैठा मेंढक समुद्र की गहराई नहीं जान सकता।\n\nइस दृढ़मूल अश्वत्थ को असङ्ग के तीक्ष्ण खड्ग से — वैराग्य से — काटकर परमपद की खोज करनी चाहिए।",
  "15.4": "ततः पदं तत् परिमार्गितव्यं यस्मिन् गता न निवर्तन्ति भूयः ।\nतमेव चाद्यं पुरुषं प्रपद्ये यतः प्रवृत्तिः प्रसृता पुराणी ॥\n\nउस वैराग्यखड्ग से संसारवृक्ष काटकर वह परमपद खोजना चाहिए — जहाँ पहुँचने के बाद लौटना नहीं होता। वही मोक्ष है।\n\n'आद्यं पुरुषं प्रपद्ये' — जिनसे यह पुरातन सृष्टिप्रवाह आरम्भ हुआ, उन्हीं आद्यपुरुष लक्ष्मीनारायण की शरण लेनी चाहिए। ईश्वर-शरणागति ही संसारछेद का उपाय है।",
  "15.5": "निर्मानमोहा जितसङ्गदोषा अध्यात्मनित्या विनिवृत्तकामाः ।\nद्वन्द्वैर्विमुक्ताः सुखदुःखसञ्ज्ञैर्गच्छन्त्यमूढाः पदमव्ययं तत् ॥\n\nपरमपद के अधिकारी कौन? — जो अहंकार-ममकार से रहित हैं; जिन्होंने आसक्ति जीत ली; जो निरन्तर भगवत्चिन्तन में रत हैं; जिन्होंने सभी भोग-कामनाएँ छोड़ दी हैं; जो सुख-दुःख में समभाव से स्थित हैं।\n\nलौकिक आशा ही निराशा का मूल है। जैसे दिन-रात समभाव से स्वीकार करते हैं, वैसे ही सुख-दुःख सहते हुए अमूढ़ जन उस अव्यय पद को प्राप्त करते हैं।\n\nइस अध्याय में कृष्ण जीव-जगत्-भगवत् की त्रिपुटी का रोचक वर्णन करते हैं। भगवत्चिन्तनशील जनों के लिए आगे के श्लोक विशेष महत्त्वपूर्ण हैं।",
  "15.6": "न तद्भासयते सूर्यो न शशाङ्को न पावकः ।\nयद्गत्वा न निवर्तन्ते तद्धाम परमं मम ॥\n\nवह परमधाम — जहाँ सूर्य नहीं चमकता, चन्द्रमा नहीं, अग्नि भी नहीं — वही भगवान् का परमनिलय है। सूर्य-चन्द्र-अग्नि स्वयं तेजस्वी हैं, किन्तु भगवान् के तेज से ही प्रकाशित हैं — 'तमेव भान्तमनुभाति सर्वम्' (कठो०)।\n\nसूर्य में गायत्री-उपासना, चन्द्र में धन्वन्तरि-उपासना, अग्नि में भगवत्-यजन — ये सब भगवत्-प्रतीक मात्र हैं। आत्मज्योति जागृत कर अन्तर्यामी भगवान् का आश्रय लेने वाले को ही परमधाम की प्राप्ति होती है।\n\nबृहदारण्यक में जनक-याज्ञवल्क्य-संवाद — सूर्य, चन्द्र, अग्नि, वाक् — क्रमशः प्रकाश; अन्ततः 'आत्मैवास्य ज्योतिः' — आत्मज्योति ही परमप्रकाश है।",
  "15.7": "ममैवांशो जीवलोके जीवभूतः सनातनः ।\nमनःषष्ठानीन्द्रियाणि प्रकृतिस्थानि कर्षति ॥\n\nजीव — भगवान् का सनातन अंश है। यह अंश दो प्रकार का है — स्वरूपांश (ज्ञानानन्दस्वभाव की दृष्टि से) और भिन्नांश (प्रतिबिम्बरूप से)। भगवान् महाज्योति हैं, जीव उनका अंश-प्रकाश। भगवान् बिम्ब हैं, जीव प्रतिबिम्ब।\n\nजीव पाँच ज्ञानेन्द्रियों और छठे मन के साथ विषयों की ओर खिंचता है। किन्तु यह कर्षण अन्तर्यामी भगवान् के नियमन से ही होता है — जीव स्वतन्त्र नहीं।\n\nकठोपनिषत् — 'अङ्गुष्ठमात्रः पुरुषोऽन्तरात्मा सदा जनानां हृदये सन्निविष्टः।' मध्वाचार्य — 'सर्वप्राणिहृदिस्थाय वामनाय नमो नमः।'",
  "15.8": "शरीरं यदवाप्नोति यच्चाप्युत्क्रामतीश्वरः ।\nगृहीत्वैतानि संयाति वायुर्गन्धानिवाशयात् ॥\n\nईश्वर जीव के प्रवेश और निर्गमन दोनों के नियन्ता हैं। 'अव-आप्नोति' — देहप्रवेश जीव का बन्धन है, ऊर्ध्वगमन से पूर्व अधःपात। 'उत्क्रामति' — 'उत्' उपसर्ग से मङ्गल-गमन सूचित होता है; मृत्यु अमङ्गल नहीं — ईश्वर द्वारा जीव का स्थूलशरीर से उत्क्रमण है।\n\n'संयाति' — सं = स्वेच्छा से। सब कुछ भगवान् के अधीन है, जीव न जन्म लेता है न मरता है अपने आप।\n\nजैसे वायु फूल से गन्ध अदृश्यरूप से वहन करती है, वैसे ईश्वर षड्इन्द्रियसहित जीव को देह में प्रवेश कराते और निकालते हैं। जीव की गति अदृश्य पर सत्य है।",
  "15.9": "श्रोत्रं चक्षुः स्पर्शनं च रसनं घ्राणमेव च ।\nअधिष्ठाय मनश्चायं विषयानुपसेवते ॥\n\nभगवान् प्रत्येक इन्द्रिय में विशेष रूप से अधिष्ठित हैं। 'अधिष्ठाय' — ऊपर स्थित होकर, दुःखकलङ्क से रहित। जीव सुख-दुःख में डूबकर विषय भोगता है; भगवान् 'उपसेवते' — ऊपर स्थित होकर, समस्त विषयों को निर्लिप्त भाव से अनुभव करते हैं।\n\n'एव' और 'च' दोनों एक साथ — 'एवच' — सर्वदोषरहित, सर्वकल्याणगुणपूर्ण, ज्ञानानन्दमय भगवान् का विशेषण है।",
  "15.10": "उत्क्रामन्तं स्थितं वापि भुञ्जानं वा गुणान्वितम् ।\nविमूढा नानुपश्यन्ति पश्यन्ति ज्ञानचक्षुषः ॥\n\n'गुणान्वितम्' — सर्वकल्याणगुणसमन्वित — यह शब्द स्पष्ट करता है कि यह श्लोक भगवान् के विषय में है, जीव के नहीं।\n\nजीव को देह में लाने वाले, जाग्रत्-स्वप्न-सुषुप्ति में अनुभव देने वाले, देह से निकालने वाले — सब कुछ भगवान् करते हैं। विमूढ — विपरीतज्ञानी — उन्हें नहीं देखते। ज्ञानचक्षुष् — शास्त्रपूत अन्तर्दृष्टि सम्पन्न — उन्हें आत्मा में ही देखते हैं।",
  "15.11": "यतन्तो योगिनश्चैनं पश्यन्त्यात्मन्यवस्थितम् ।\nयतन्तोऽप्यकृतात्मानो नैनं पश्यन्त्यचेतसः ॥\n\nभगवद्दर्शन के लिए केवल शास्त्राभ्यास पर्याप्त नहीं — ज्ञानपूर्वक निरन्तर ध्यानयोग-साधना आवश्यक है। जैसे किसान खेत जोतकर बीज बोता है, पर वर्षा दैव-अधीन है — वैसे प्रयत्न के साथ भगवदनुग्रह भी चाहिए।\n\nवसुदेव — शुद्धसात्त्विक मन; उसमें वासुदेव प्रकट होते हैं।\n\nअकृतात्मानः — अशुद्धबुद्धि — प्रयत्न करने पर भी भगवान् को नहीं देख पाते। 'एनम्' — आपके अत्यन्त समीप, जीवस्वरूप के अन्तर में बिम्बरूप भगवान् को — देखें। वे बाहर नहीं, भीतर ही खोजने योग्य हैं।",
  "15.12": "यदादित्यगतं तेजो जगद्भासयतेऽखिलम् ।\nयच्चन्द्रमसि यच्चाग्नौ तत्तेजो विद्धि मामकम् ॥\n\nपहले कहा था — सूर्य, चन्द्र, अग्नि मुझे प्रकाशित नहीं कर सकते; अब कृष्ण कहते हैं — सूर्य का तेज, चन्द्र का प्रकाश, अग्नि का ज्वलन — सब मेरे तेज से उत्पन्न हैं।\n\nसमस्त ज्योतियों का आदिस्रोत भगवान् हैं। वही तेज अणु-रूप में हमारे स्वरूप में स्थित होकर हमें नियमित करता है और महत्-रूप में समग्र ब्रह्माण्ड को प्रकाशित करता है।\n\nउपासना की दृष्टि से — सूर्यस्थ तेज नारायण का, चन्द्रस्थ धन्वन्तरि का, अग्निस्थ परशुराम का। प्रत्येक प्रकाशस्रोत भगवन्नाम मात्र है।",
  "15.13": "गामाविश्य च भूतानि धारयाम्यहमोजसा ।\nपुष्णामि चौषधीः सर्वाः सोमो भूत्वा रसात्मकः ॥\n\n'गाम् आविश्य' — पृथ्वी में प्रवेश करके भगवान् ओजस् से — सङ्कर्षण-शेष-शक्ति से — धारण करते हैं। वराहावतार — हिरण्याक्ष द्वारा कक्षाभ्रष्ट पृथ्वी को भगवान् ने वराहरूप में पुनः स्थापित किया। उपनिषत् — 'यः पृथिवीम् अन्तरो यमयति एष आत्मा अन्तर्यामी अमृतः।'\n\n'सोमो भूत्वा रसात्मकः' — भगवान् सोमरूप से चन्द्र में स्थित होकर वनस्पतियों का जीवनरस पोषित करते हैं। संध्यावन्दन में चन्द्रमण्डलस्थ धन्वन्तरि के अमृतकलश का स्मरण — अन्तर्मलशुद्धि के लिए — यही है।",
  "15.14": "अहं वैश्वानरो भूत्वा प्राणिनां देहमाश्रितः ।\nप्राणापानसमायुक्तः पचाम्यन्नं चतुर्विधम् ॥\n\nभगवान् वैश्वानर रूप से प्राणियों के उदर में स्थित होकर — प्राण-अपान से युक्त होकर — चतुर्विध अन्न पचाते हैं। भक्ष्य, भोज्य, लेह्य, चोष्य — ये चार प्रकार।\n\nआहार का त्रिधा विभाजन — मिट्टी का सूक्ष्म भाग मस्तिष्क, मध्य माँस-त्वचा, स्थूल मल; जल का सूक्ष्म प्राण, मध्य रक्त, स्थूल मूत्र; अग्नि का सूक्ष्म वाक्शक्ति, मध्य अस्थिमज्जा, स्थूल दाँत-हड्डी — इस प्रकार सोने की खान से भी कठिन यह कार्य भगवान् वामनरूप से हृदय में स्थित होकर सम्पन्न करते हैं।\n\nकठो० — 'मध्ये वामनमासीनं विश्वे देवा उपासते।'",
  "15.15": "सर्वस्य चाहं हृदि सन्निविष्टो मत्तः स्मृतिर्ज्ञानमपोहनं च ।\nवेदैश्च सर्वैरहमेव वेद्यो वेदान्तकृद्वेदविदेव चाहम् ॥\n\n'सर्वस्य च अहम् हृदि' — भगवान् 'अहम्' शब्द-वाच्यरूप से सबके हृदय में सन्निविष्ट हैं। बाहर का रूप 'अहः', भीतर का 'अहम्'। स्मृति, ज्ञान, अपोहन (विस्मृति) — सब मुझसे।\n\n'वेदान्तकृत्' — ब्रह्मसूत्र, जो समग्र वेद का निर्णय है — उसका कर्ता मैं हूँ। 'वेदान्त' = उपनिषत् ही नहीं, 'वेद का अन्तिम निर्णय' = ब्रह्मसूत्र।\n\nभागवत उद्धवगीता में — 'माम् अभिधत्ते, माम् विधत्ते — एतावान् सर्ववेदार्थः।' वेद का प्रत्येक शब्द भगवान् को ही कहता है। मध्वाचार्य — 'सर्वप्राणिहृदिस्थाय वामनाय नमो नमः।'",
  "15.16": "द्वाविमौ पुरुषौ लोके क्षरश्चाक्षर एव च ।\nक्षरः सर्वाणि भूतानि कूटस्थोऽक्षर उच्यते ॥\n\nचेतनजगत् में दो प्रकार के पुरुष — क्षर और अक्षर।\n\nक्षर — जिसका शरीर कभी नष्ट होता है। ब्रह्मा भी क्षर हैं — एक कल्पकाल के बाद उनका शरीर भी भस्म। ईशोपनिषत् — 'वायुरनिलममृतं अथेदं भस्मान्तं शरीरम्।' समस्त देवता, सभी जीव — क्षरपुरुष।\n\nअक्षर — कूटस्था श्रीलक्ष्मी। 'कूटस्थ' — जीव और शरीर के संयोग की हेतु। नित्यमुक्ता, ज्ञानानन्दस्वरूपदेहा, निर्लिप्ता — वे सदा अक्षरा हैं। मोक्ष में क्षर भी अक्षर हो जाते हैं, लक्ष्मी तो सदैव अक्षरा हैं।",
  "15.17": "उत्तमः पुरुषस्त्वन्यः परमात्मेत्युदाहृतः ।\nयो लोकत्रयमाविश्य बिभर्त्यव्यय ईश्वरः ॥\n\nक्षर और अक्षर दोनों से परे — उत्तमपुरुष — वे ही परमात्मा हैं, वही भगवान् विष्णु। जो त्रैलोक्य में प्रवेश करके सब कुछ धारण करते, पोषित करते, रक्षित करते हैं — वह अव्यय ईश्वर।",
  "15.18": "यस्मात्क्षरमतीतोऽहमक्षरादपि चोत्तमः ।\nअतोऽस्मि लोके वेदे च प्रथितः पुरुषोत्तमः ॥\n\nक्षर से 'अतीत' — कक्षा के भीतर क्षर, भगवान् कक्षातीत। अक्षर से 'उत्तम' — लक्ष्मी से भी भगवान् सर्वोत्तम। 'अपि च' — दोनों पद मिलकर निरतिशय श्रेष्ठत्व को कहते हैं।\n\nमध्वाचार्य विष्णुतत्त्वनिर्णय-मङ्गल में — 'सदागमैकविज्ञेयं समतीतक्षराक्षरं नारायणं सदा वन्दे निर्दोषाशेषसद्गुणम्।'\n\n'लोके च वेदे च प्रथितः' — लोके = रामायण-महाभारत-पुराण-पञ्चरात्रादि में; वेदे = श्रुति में — दोनों में 'पुरुषोत्तम' नाम केवल भगवान् के लिए ही है।",
  "15.19": "यो मामेवमसम्मूढो जानाति पुरुषोत्तमम् ।\nस सर्ववित्भजति मां सर्वभावेन भारत ॥\n\nअसम्मूढ — अहंकार-क्रोध-मोहरहित शुद्धमनस्क — जो पुरुषोत्तम भगवान् को जानता है, वह सर्वविद् है। भगवद्ज्ञान समस्त ज्ञान का मूल है।\n\nपहले आत्मसाक्षात्कार — जड से भिन्न 'मैं' चेतन इस देह में हूँ; फिर जीवबिम्ब में परमात्मसाक्षात्कार। जो ऐसे जानता है वह सर्वभाव से भजता है।\n\n'भारत' — भरत-वंशज, किन्तु अर्थ — ज्ञानतृष्णा, ज्ञानिभक्ति, प्राणदेव-निष्ठा — इनसे युक्त।",
  "15.20": "इति गुह्यतमं शास्त्रमिदमुक्तं मयाऽनघ ।\nएतद्बुद्ध्वा बुद्धिमान्स्यात्कृतकृत्यश्च भारत ॥\n\nअनघ — निष्पाप अर्जुन को — गुह्यतम शास्त्र कहा। शास्त्र सड़क पर उद्घाटित नहीं करना — जिसमें ग्रहण की योग्यता, रुचि, श्रद्धा, भक्ति हो उसी को कहना।\n\nक्षर-अक्षर-पुरुषोत्तम का त्रित्वज्ञान — यही समस्त शास्त्र का सार है। इसे जानकर — बुद्धिमान् बनता है — वेदार्थज्ञ; कृतकृत्य — जिसका कर्तव्य पूर्ण हुआ। भगवद्ज्ञान ही जीवन की सार्थकता है।\n\nइति पञ्चदशोऽध्यायः — पुरुषोत्तमयोगः।",
  "16.1": "अहिंसा सत्यमक्रोधस्यागः शनैरिर्पैशुनम् |\nदया भूतेष्ठालोलुत्वमर्दवं ह्रीराचपलम्",
  "16.2": "",
  "16.3": "भगवान् उवाच —\nअभयं सत्त्वसंशुद्धिः ज्ञानयोगव्यवस्थितिः ।\nदानं दमश्च यज्ञश्च स्वाध्यायस्तप आर्जवम् ॥\nअहिंसा सत्यमक्रोधस्त्यागः शान्तिरपैशुनम् ।\nदया भूतेष्वलोलुप्त्वं मार्दवं ह्रीरचापलम् ॥\nतेजः क्षमा धृतिः शौचमद्रोहो नातिमानिता ।\nभवन्ति सम्पदं दैवीमभिजातस्य भारत ॥\n\nहे भारत, दैवी सम्पत् से उत्पन्न जन में ये गुण होते हैं — अभय, अन्तःकरणशुद्धि, ज्ञानयोगनिष्ठा, दान, दम, यज्ञ, स्वाध्याय, तप, आर्जव, अहिंसा, सत्य, अक्रोध, त्याग, शान्ति, अनिन्दा, दया, अलोलुपता, मार्दव, लज्जा, अचपलता, तेज, क्षमा, धृति, शौच, अद्रोह और अनतिमानिता — ये 26 दैवी गुण।\n\nकृष्ण यहाँ दैवी-आसुरी सम्पत् का वर्णन करते हैं। दैवी सम्पत् = मोक्षदायी गुण।",
  "16.4": "दम्भः दर्पः अभिमानः च क्रोधः पौरूष्यम एवच।\nअज्ञानं च अभिजातस्य पार्थ संपदाम आसुरीम्- पार्थ, आसुरी संपदा [बुरा आचरण]\nजातक के गुण हैं: पाखंड, अहंकार, ईर्ष्या, क्रोध, अशिष्टता और अशिष्टता।\n\nऊपर वर्णित छब्बीस दैवीय गुणों के विपरीत, इस श्लोक में कृष्ण में छह आसुरी गुण हैं\nकहा:\n\n(1) दंभ (जो चीज़ नहीं है उसका दिखावा करना): मानो जो नहीं है वह अंदर है\nअच्छाई का प्रदर्शन; अपने अंदर की बुराई को छुपाते हुए एक बहुत अच्छे इंसान की तरह व्यवहार करना\nआदि करना धृष्टता प्रतीत होता है। यह ऊपर वर्णित आर्जवम का विपरीत गुण है।\n(2) दर्प: कुछ भी गलत करने से घृणा करने की भावना। यह ह्रीं गुण के विपरीत है।\n\n(3) अतिमान : स्वयं के बारे में अत्यधिक विचार; मैं बड़ा आदमी हूं\nदूसरे के प्रति भ्रमित और अनादरपूर्ण होना; कि हर किसी को उसका पैर पकड़ना चाहिए\nइच्छाएँ- ये अतिमानवीय हैं।\n\n(4) क्रोध : क्रोध एक ऐसा दुर्गुण है जिसे व्यक्ति छोड़ना भी चाहे तो नहीं छोड़ सकता। यह ऐसा है जैसे हम नहीं जानते\nएक बुराई जो हमें भटकाती है।\n\n(5) पौरूष्य: उग्र, बुरा भाषण; दूसरे के बारे में दयालुता से बात करना,\nआदि। पौरुष्य का उदाहरण।\n\n(6) अज्ञान : उपरोक्त सभी विकारों का शासक अज्ञान है। एक सच्चा साधु कभी इतना बुरा नहीं होता\nगुणों के गुलाम मत बनो.\n\nये सभी आसुरी गुण हमारे अंदर अपना घर बना लेते हैं और हमें बाहर निकाल देते हैं। तो ये\nसबसे पहले हमें विकारों से छुटकारा पाना होगा। कुरान में यह है - \"Drive them out from where\nyou have been driven out” खूबसूरती से कहा गया है। अपने आप को बाहर फेंको, अपने अंदर बैठो\nवे कहते हैं कि पहले इन बुराइयों से छुटकारा पाओ जो तुम्हें बर्बाद कर रही हैं। वेद यही कहते हैं\nइस प्रकार कहा: \"यो अस्मां वेति यं वयं द्विष्टिः\" ..|[अथर्व 3-27-2|- अर्थात-\n“वह जो हमसे नफरत करता है, वह दुश्मन जिससे हम नफरत करते हैं\nइसका मतलब है धक्का देना।” यहाँ शत्रु हमारे आंतरिक शत्रु हैं, ये विकार हैं।\n\nइस श्लोक में 'पार्थ' विशेषण का प्रयोग हुआ है। \"हम बुराइयों से दूर हो जाते हैं,\nयही संदेश है कि ज्ञान के मार्ग पर चलकर सच्चा जीवन जीना चाहिए\nविशेषण के पीछे है.",
  "16.5": "दिव्य सम्पत विमोक्षय निबन्धाय आसुरी माता |\n\nमा शुचः संपदां दैवीम अभिजातः असि पांडव - अच्छा आचरण ही मुक्ति का मार्ग है।\nबुरा तमस की कैद का रास्ता. विलाप मत करो, पांडव। आप सही रास्ते पर हैं\nजो आत्मसात हो गया हो।\n\nयह समझाते हुए कि हमें दैवी संपदा का उपयोग क्यों करना चाहिए, कृष्ण कहते हैं: “दिव्य\nधन मुक्ति की ओर ले जाता है, दुष्ट स्वभाव निर्वाण की ओर ले जाता है”। यहाँ कृष्ण हैं\nउन्होंने विशेष रूप से 'वी-मोक्ष' और 'नि-बंध' का उल्लेख किया है। वी-मोक्ष उनकी प्राप्ति के लिए है\n\nतदनुसार भिन्न-भिन्न स्थानों में व्यक्तित्व का विकास एवं मोक्ष। 'नि-बंध' का अर्थ संसार बंध नहीं है। यह मतलबी है\nबंधन एक ऐसा बंधन जो हमें अंधकार में ले जाता है।\n\nकृष्ण अर्जुन के बारे में कहते हैं: “तू दैवी संपदा का आदर्श अवतार है\nआप दैवी संपदा के घर, अपने स्वभाव और जिस परिवार में पैदा हुए थे, उसकी तलाश में पैदा हुए थे\nप्रभाव एक दूसरे के पूरक हैं, इसकी चिंता मत करो।\n\nद्वौ भूत्सर्गौ लोकेहस्मिन् दैव असुर एव च ​​|\n16\n\nद्वौ भूत्सर्गौ लोके अस्मिन् दैवः असुरः एव च ​​|\n\nदैवः विस्तारश प्रोक्तः असुरं पार्थ मे श्रृणु - इस ब्रह्मांड में दो प्रकार के जीव हैं:\nदैव [बुरा] और असुर [बुरा]। कार्रवाई का तरीका बताया और कहा,\nहे पार्थ, मुझ से उस दुष्ट की कथा सुनो।\n\nइस संसार में मूल रूप से दो प्रकार के मनुष्य हैं: वे जो ईश्वर की ओर चलते हैं\nदिव्य पथ पर चलने वाले और राक्षसी पथ पर चलने वाले जो भगवान से मुंह मोड़ लेते हैं। ये दो\nअब तक के अनुभाग में हमने दैवीय प्रकृति पर विस्तार से विचार किया है। हमारा आंतरिक और\nकृष्ण ने सामाजिक व्यवहार का विस्तृत वर्णन करने के बाद यहाँ आसुरी स्वभाव का व्यवहार-\nवह शब्दों के बारे में बताते हैं. इसके माध्यम से कृष्ण हमें बताते हैं कि हमें कैसा नहीं होना चाहिए\nबताता है.",
  "16.6": "दैवी सम्पत् विमोक्षाय निबन्धाय आसुरी मता |\\\\\n\\\\\nमा शुचः सम्पदं दैवीम् अभिजातः असि पाण्डव - अच्छा आचरण मुक्ति का मार्ग है। बुरा आचरण तमस की बंधन का मार्ग। पाण्डव, शोक मत करो। तुम दैवी सम्पद के मार्ग पर चलने वाले हो।\\\\\n\\\\\nकृष्ण समझाते हैं: \"दैवी सम्पत्ति विमोक्ष की ओर ले जाती है, आसुरी स्वभाव निबन्ध की ओर।\" वि-मोक्ष अर्थात् साधना के अनुरूप विभिन्न स्तरों पर व्यक्तित्व विकास और मोक्ष। 'नि-बन्ध' नीचे की ओर खींचने वाला बन्धन है जो हमें तमस के अंधकार में धकेलता है।\\\\\n\\\\\nद्वौ भूतसर्गौ लोके अस्मिन् दैवः आसुरः एव च | दैवः विस्तरशः प्रोक्तः आसुरम् पार्थ मे श्रृणु - इस संसार में दो प्रकार की जीव-सृष्टियाँ हैं: दैवी और आसुरी। दैवी स्वभाव का विस्तार से वर्णन हो चुका है; अब पार्थ, मुझसे आसुरी स्वभाव का वर्णन सुनो।\\\\\n\\\\\nकृष्ण अब आसुरी स्वभाव वालों के आचरण का वर्णन करते हैं - ताकि हम जान सकें कि हमें कैसा नहीं होना चाहिए।",
  "16.7": "प्रद्धितं च निवृत्तं च जनः न विदुः असुरः।\n\nन शौचं न अपि च आचारः न सत्यं तेषु विद्यते - दुष्ट लोग किस मार्ग से जाते हैं\nजानें कि क्या पकड़ना है और क्या छोड़ना है। कोई तह नहीं; अच्छा कदम नहीं; उनमें से सबसे बहादुर\nकोई शब्द नहीं.\n\nयहाँ कृष्ण राक्षसों के सामाजिक व्यवहार का वर्णन करते हैं। आसुरी प्रकृति वालों के लिए\nक्या करना है और क्या नहीं करना है, इसकी कोई जागरूकता नहीं है। इससे वे\n\nवे वही कर रहे हैं जो नहीं करना चाहिए. न्याय और अन्याय उनके लिए कोई मायने नहीं रखते. पैसा कमाना\nऔर उनकी मूल इच्छा एक विशिष्ट व्यक्ति का दर्जा अर्जित करना है। इस पैसे की वजह से\nउन्हें इसकी परवाह नहीं कि संपादन में न्याय का चेहरा होना चाहिए।\n\nमूलतः असुर प्रकृति के लोगों में स्वच्छता का अभाव होता है। एक अच्छा शब्द, एक अच्छा विचार,\nस्वच्छ शरीर उनमें से नहीं है. वह बाहर से बहुत साफ-सुथरा होने का दिखावा करता था\nजी रहे हैं वे कभी ईमानदार नहीं होते. जो भी किया जाता है दिखावे के लिए किया जाता है.\nकृष्ण की गीता में वर्णित गुणों में से एक का उदाहरण महाभारत में मिलता है।\nइसके लिए गीता को महाभारत का सार कहा जाता है। राक्षसी स्वभाव का उत्कृष्ट उदाहरण\n\"दुर्योधन\"।\n\nये राक्षसी लोग कैसे बन जाते हैं समाज कंटक, क्या है इनकी समझ? यह\nअध्याय के अगले भाग में, कृष्ण विस्तार से बताते हैं।",
  "16.8": "",
  "16.9": "असत्यम् अप्रतिष्ठम् ते जगत् औः अनिश्वरम् |\n\nअपरस्परा संबुतम् किम अन्यत कामहैथुकम - वह भगवान है जो यह सार्वभौमिक वास्तविकता है।\nवे कहते हैं कि यह कोई योगदान नहीं है [यह झूठ है]। यह ईश्वर में स्थित नहीं है [है]\nनहीं] कहते हैं. ऐसा कहा जाता है कि ऐसा कोई सर्वशक्तिमान नहीं है जो इसे नियंत्रित कर सके। क्रमशः एक से दूसरे\nमैं इस बात से सहमत नहीं हूं कि इसका जन्म हुआ. और क्या उनकी नजर में ये एक अलग तरह का मामला है. ये है\nवासना का दूध-मायाशस्का शिति।\n\nअसुर दो प्रकार के होते हैं. संसार के पास कोई सत्य नहीं है, संसार के पास कोई और प्रतिष्ठा नहीं है, संसार के पास और कोई प्रतिष्ठा नहीं है\nउनकी नास्तिक समझ है कि कोई ईश्वर नहीं है। संसार को सृजन-अवस्था-विनाश के अधीन करना\nवह जानता है कि कोई शक्ति (सत्य) नहीं है। इसलिए, वह ईश्वर रहित इस संसार का आधार है\nउनका तर्क है कि इस दुनिया को नियंत्रित करने वाला कोई भगवान नहीं है, सब कुछ एक भ्रम है। सृष्टि चक्र एक है\nउनकी मान्यता मुर्बताना का सिद्धांत है।\n\nअसुरों का दूसरा प्रकार यह है कि हम इस संसार में जो कुछ भी देखते हैं वह केवल हमारा भ्रम है\nअशक्त करने वाले। सिवाय इसके कि यह संसार हमारी इच्छाओं से विकसित हो रहा है\nउनका मानना है कि यह किसी दूसरी शक्ति का नहीं है.\n\nएतं दृष्टि मावष्टा भया अंतात्मानोल्ब बुद्धयः |\nप्रभावन्त्युग्रकर्मणः क्षय जगतोहितः ॥19॥\n\nएतं दृष्टिं अवस्ताभ्य हानि आत्मनः अल्पबुद्धयः |\nप्रभावन्ति उग्रकर्मणः क्षय जगतः अहितः - ऐसे रुख पर आधारित, विवेका\nखोये हुए बेवकूफ-जाति के कमीने। ऐसा कठोर कदम दुनिया को नष्ट कर देगा\n\nकारण बनेगा\n\nजो लोग बुरी मानसिकता विकसित कर लेते हैं वे अपने जीवन में दुख लाते हैं और खुद को नष्ट कर लेते हैं\nवे स्वयं इसका कारण बनेंगे। यह उनका विश्वास ही है जो उन्हें नष्ट कर रहा है, वे अंधकार हैं\nवे इस बात का एहसास किए बिना ही उग्रवादी (उग्रकर्मणः) बन जाते हैं कि वे रास्ते पर चल रहे हैं। इस का\nपरिणामस्वरूप, वे संसार के शत्रु बन जाते हैं और संसार के विनाश का कारण बनते हैं। इस प्रकार की मानसिकता है-\nहमारे बीच जो लोग हैं वे असुर हैं।",
  "16.10": "कामम अश्रित्य दुष्बुरं दंभ मन मद अन्विताः।\n\nमोहत् गृहित्वा असत् ग्रहण प्रवर्तन्ते आशुचि व्रतः - अक्षय इच्छा की रीढ़\nपाखंड, अभिमान और अहंकार. ये लोग गंदे कर्मों के दोषी हैं\nवे धारणाओं के आधार पर जीते हैं।\n\nआसुरी मनुष्य की इच्छाओं का कोई अंत नहीं है। कितना भी आये, अभी और भी है। उदाहरण के लिए काम ही\nयदि नहीं, तो वह नौकरी चाहता है, जब उसे नौकरी मिलती है, तो वह अधिक वेतन चाहता है, जब उसे वेतन मिलता है, तो वह वेतन उसका होता है\nअगले दरवाजे वाले पड़ोसी से भी कम - अधिक वेतन, बड़ा पद वगैरह चाहने के लिए\nअगर मिल भी जाए तो भी आप संतुष्ट नहीं होते. यह प्यास तृप्त नहीं हो सकती. जैसा कि किंवदंती कहती है, कैसे\nजिस प्रकार मनुष्य की इच्छा पूरी करने के लिए पाताल को गंदगी से नहीं ढका जा सकता\nहमें कितना भी पैसा क्यों न मिल जाए, हम उसके दाहिनी ओर एक शून्य होते हैं\nहमें दुख है कि इसे शामिल करने से यह कम हो गया। और ख़ुशी को भूल जाओ.\nकठोपनिषद में - जब यम कहते हैं, \"मैं तुम्हें उतना धन दूंगा जितना तुम चाहोगे\",\nनचिकेता कहते हैं: \"न वित्तेण तर्पणियो मनुष्यिनः\"। इसका अर्थ है “मनुष्य का धन।”\n\nइच्छा कोई पूरी नहीं कर सकता।” पर्याप्त है दैवी स्वभाव, आवश्यकता\nयह राक्षसी स्वभाव है. इस प्रकार आसुरी प्रकृति इच्छाओं की पीठ है, उस किनारे की इच्छा है\nबदला लेने के लिए वे वही करते हैं जो उन्हें नहीं करना चाहिए। उनका जीवन पाखंड है. बिगुमना,\nअहंकार, नाटकीय जीवन से दूसरों को धोखा देना। ऐसे चलो\nस्वच्छता के बिना गंदा जीवन उनका है।",
  "16.11": "चिन्ताम् अपरिमेयं च प्रलयन्तम् उपाश्रितः।\n\nकाम उपभोग परमह एतवत इति शेषिकाः - मृत्यु के साथ नाश होने वाला, अपरिमेय।\nचिंतित। वासना ही जीवन का सब कुछ और अंत है। बस यही तो जीवन है\nआस्तिक\n\nउसके रोने का कोई अंत नहीं है. वह अपना पूरा जीवन उस चीज़ को पाने की तलाश में बिता देता है जो उसके पास नहीं है\nखर्च कर देंगे वे चिंता के गुलाम बन जाते हैं। उनकी चिंताएँ प्रलयंकारी हैं - यहाँ तक कि उनकी मृत्यु तक\nबिना पीछे मुड़े भूतिया। वह भोग का गुलाम है, कोई उसे छोड़ नहीं सकता\nअधीनता में, व्यक्ति यह जानते हुए जीता है कि जीवन का यही मतलब है।",
  "16.12": "आशापाशा शतैः बद्दः कामक्रोधपरायः।\n\nयह कामभोगार्थ अन्ययेन का अर्थसंचयन है--। सैकड़ों ख्वाहिशों में फँसा हुआ\nजो पकड़े गए हैं, जिन्होंने खुद को पागल जुनून के आगे बेच दिया है। बाजार को भुगतान करना गलत है\nजो लोग सड़क से राख के ढेर हटाना चाहते हैं।\n\nवे संतुष्टि की खातिर खुद को इच्छाओं के जाल में फंसा लेते हैं\nअपने आप को वासनापूर्ण क्रोध के लिए बेचकर, वासनापूर्ण क्रोध बनकर जी रहे हैं\nइसका एक अच्छा उदाहरण पौंड्रक वासुदेव हैं। उन्होंने कहा कि उन्हें स्वयं भगवान बन जाना चाहिए\nवासना'. इसी वासना के कारण उन दार्शनिकों पर क्रोध आता है जो इसे ग़लत कहते हैं।\n\nउन्हें अपने सुखों के लिए अन्यायपूर्ण तरीकों से धन इकट्ठा करना पड़ता है\nचारों ओर प्रयास किया। वे धर्मग्रंथों में लिखी बातों को अपने हिसाब से तोड़-मरोड़ कर पेश करते हैं\nस्वेच्छा से उपलब्धि में संलग्न रहता है।",
  "16.13": "इदमद्य मया लब्धमिमं प्राप्स्ये मनोरथम् ।\nइदमस्तीदमपि मे भविष्यति पुनर्धनम् ॥\n\n'यह आज मुझे मिला, यह मनोरथ भी पाऊँगा, यह धन है, यह भी होगा —'\n\nआसुरी स्वभाव वाले का मनोभाव — संचय, अहंकार, भोग की अतृप्त प्यास। 'इदमद्य लब्धम्' — आज यह मिला। 'मनोरथ प्राप्स्ये' — यह इच्छा भी पाऊँगा। यह संग्रहवृत्ति आसुरी सम्पत् का लक्षण।",
  "16.14": "असौ मया हतः शत्रुः हनिष्ये चापरानपि ।\nईश्वरोऽहमहं भोगी सिद्धोऽहं बलवान् सुखी ॥\n\n'वह शत्रु मैंने मारा, और भी मारूँगा। मैं ईश्वर हूँ, मैं भोगी हूँ, मैं सिद्ध हूँ, मैं बलवान् हूँ, मैं सुखी हूँ।'\n\nआसुरी अहंकार का चित्र — स्वयं को सर्वशक्तिमान् मानना। 'अहम् ईश्वरः' — मैं ही ईश्वर हूँ। 'अहम् भोगी' — मैं भोगी हूँ। यह अहंकार ही पतन का मूल।",
  "16.15": "इदं अद्या मया लब्धं इमं प्रोप्स्ये मनोरथम्।\n\nइदं अस्ति इदं अपि मेइ भैवती पुर्नराधनम् ॥\n\nअसौ माया हतः शत्रुह हानिष्ये च आपा रन अपि।\n\nईश्वरः अहं अहं भोगी सिद्ध अहं बलवान सुखी॥\n\nअध्यो अभिजावन अस्मि कह अन्यः अस्ति सदृशः मया |\n\nयक्ष्ये दास्यामि मोदिष्ये इति अज्ञान विमोहिताः - उन्होंने अज्ञानतावश ऐसा कहा\nगरीब आदमी: मुझे यह अब मिल गया; ये ख्वाहिश आगे भी पूरी करूंगा; ये भी\nवहाँ है; फिर ये मेरा होगा; इस नफरत को मार डाला; बाकी भी ख़त्म कर दूंगा; मैं हूँ\nसर्वशक्तिमान; मैं भोगी हूं; मैं वह हूं जिसे वह सब कुछ मिला जो मैं चाहता था; शक्तिशाली और खुश;\nमैं बीमार हूं; मैं कुलीन हूँ; मेरी तुलना किससे की जाती है? मैं यज्ञ करूंगा. दान\nमैं दूँगा, मुझे खुशी है।\n\nइन तीन श्लोकों में कृष्ण हमें बताते हैं कि राक्षसों के विचार कैसे होते हैं\nसमझाया. विचार यह है कि उन्हें सदैव धन संग्रह करना चाहिए। जब उसे यह मिल गया, तो उसने कहा, “आज के लिए बस इतना ही\nसमझ गया, कल इतना कमा लूँगा।' पैसा इकट्ठा करना उनके लिए एक लत है. खुद को\nयह विचार कि जो नहीं बना उसे मैंने ख़त्म कर दिया, जो नहीं बनेगा उसे ख़त्म कर दूँगा। मैं सर्वशक्तिमान हूँ,\nमेरे कारण इस संसार में क्या है? मेरा जन्म खुश रहने के लिए हुआ है-दुखी होने के लिए नहीं; मेरी ख़ुशी के लिए\nमैं कुछ भी करूंगा; जो लोग इसे पार करेंगे उन्हें मैं ख़त्म कर दूँगा; मैं एक तैयार आदमी हूँ;\n\nमैं अपनी सफलता के लिए जिम्मेदार हूं; मेरा जन्म खुश रहने के लिए हुआ है, जन-धन-बल\nमेरे पास है; जैसी मेरी इच्छा. मेँ चलता हूँ; पैसे से कुछ खरीदा जा सकता है; मेरे लिए\nमिलान इस दुनिया में कौन है? - आदि उनके विचार. दिखावे के लिए एक बलिदान\nयज्ञादि करना और दान देना उनका नित्य कर्म है। यह अज्ञान का नृत्य है।\nवे नहीं जानते कि यह उनके विनाश का द्वार है। वही भव्यता, वही शुभता\n\nवे इस भ्रम में रहते हैं कि",
  "16.16": "अनेक चित्त विभ्रान्तः मोहजला समावृतः।\n\nवर्तमान समय में यौन इच्छा कम हो जाती है। नारके असुचौ - अनेक। विभिन्न विचारों से\nभ्रमित; मोह के जाल में फँसे हुए लोग; वासना में खोया हुआ. वे हैं\nगंदगी नरक में गिरती है और पीड़ा भोगती है।\n\nवे अपने जीवन की पिछली घटनाओं को याद करके हमेशा भ्रमित रहते हैं।\nउन्हें अपनी गलतियों पर कभी पछतावा नहीं होता। सात्विक पछताते हैं, पश्चात्ताप करते हैं\nसही है, लेकिन. वह सदैव भयानक अज्ञान-मामाकार से प्रेम करता है\nजाल में फंसकर वे और अधिक भ्रमित हो जाते हैं - स्थिर नहीं। वे चाहते थे\nचीजों में लिप्त रहना और उनसे संतुष्ट हुए बिना उन्हें संग्रहित करना\nउन्हें गंदे नरक में संघर्ष करना पड़ेगा।",
  "16.17": "आत्मसम्भावितः स्वभावः धन मनम मद अन्विताः |\n\nयजन्ते नमयज्ञैः ते दंभेन अविधि पूर्वकं- जो स्वधर्मी है। सिरी\nजो मान-सम्मान के अहंकार से बंधे हैं। वे यज्ञ भी करते हैं: पाखंडपूर्वक, वैज्ञानिक ढंग से\nक्रम टूट गया.\n\nउन्हें खुद पर गर्व है. “अविद्यायां अंतरे वर्तमानमनः स्वयं धीरा पंडितम्\nमैं नहीं जानता कि बाकियों के मन में उनके लिए सम्मान है या नहीं, लेकिन अपने लिए\n\nवह आत्म-महत्व का ज्ञान विकसित करता है और उससे डरता है। उनके इस बिगुमना के लिए\nइसका कारण ज्ञान नहीं, बल्कि हाथ में पैसा है; जो सम्मान लोग उन डुग्गीगोस्करों का करते हैं. वह है\nपाखंड के लिए, वैभव प्रदर्शन के लिए-बलिदान किए जाते हैं। विज्ञान है\nजागरूक नहीं; प्रभु को प्रसन्न करने के इरादे के बिना, प्रभु को भूल जाओ\nवही पूजा होगी.",
  "16.18": "अहंकारं बलं दर्पं कामां क्रोधं च संमृतः |\n18.\n\nअहंकारं बलं दर्पं कामां क्रोधं च संमृतः |\n\nमम आत्मा परदेहेषु प्रद्विशान्तः अभ्यसूयः - इच्छा, बल, अहंकार, अभिलाषा,\nक्षोभों का निवास. जो लोग अपने और दूसरों के शरीर में मुझ पर विश्वास नहीं करते और इसका खंडन करते हैं।\nजो लोग दूसरों की समृद्धि से उत्साहित होते हैं।\n\nइनके मूल गुण अहंकार, लोभ, वासना और क्रोध हैं। कौन मुझसे आगे निकल सकता है?\nयह अभिमान कि मैं बड़ा आदमी हूं। इसे धन और शक्ति का समर्थन प्राप्त है। इससे\nदारपा दूसरे की ओर देखता है। किनारे की ख्वाहिशें, पूरी न होने का गुस्सा-\nयही उनका अस्तित्व है. कृष्ण कहते हैं: “वे हर किसी के भीतर ``मैं'' को नकारते हैं।\nयह किसी कारण से अस्थायी तौर पर ईश्वर को नकारना नहीं है, बल्कि प्रकृति को नकारना है\nईश्वर को नकारना. ये लोग हमेशा दूसरों के ज्ञान और धन पर नजर रखते हैं\nवे ईर्ष्यालु हैं.\n\nइस प्रकार कृष्ण ने राक्षसी लोगों की प्रकृति, उनके विचारों, उनके व्यवहार को अच्छी तरह से समझा\nवर्णित है भगवान श्रीकृष्ण ऐसे राक्षसी लोगों का क्या करेंगे? उनकी गति क्या होगी?\nवह उसका वर्णन करता है।\n\nतनाहं दविषतः क्रूरं संसारेषु नराधमन् |\n\n19.\n\nतं अहम् दविषतः क्रूरं संसारेषु नारा अधमन्।\n\nक्षेपमि अजस्रम् अशुभं आसुरीषु एव योनिषु - परतत्व से घृणा करने वाला, निर्दयी।\nमैं निरंतर अँधेरे में रहता हूँ, ऐसे नीच मनुष्य\nमैं नालों में टूट जाऊंगा.\n\nईश्वर जीवन नहीं बनाता; जीवन का सार और जीवन का स्वरूप शाश्वत है\nहम पहले से जानते हैं. असुराई प्रकृति मूलतः जीवन प्रकृति है। कैसा करेला\nइन आसुरी लोगों का जीवन स्वभाव तमस है। भगवान इसे नहीं बदलेगा. इसके बजाय\nजीवन की गति जीवन की प्रकृति के अनुसार निर्मित होती है। जो प्रभु से बैर रखते हैं,\nईश्वर इन क्रूर लोगों का एक निरंतर परिवार है जो मानव जाति से नफरत करते हैं, जो दुनिया से नफरत करते हैं\nवह उसे समुद्र में डाल देता है। इससे उन्हें दोबारा गरीब परिवार में जन्म लेना पड़ेगा।\n\nआसुरीम योनिमापन्ना मुधा जन्मनिजमानी |\nमावप्रापयिव कौन्तेय ततो यन्त्यधामं गतिम्",
  "16.19": "एतं दृष्टिं अवस्ताभ्य हानि आत्मनः अल्पबुद्धयः |\nप्रभावन्ति उग्रकर्मणः क्षय जगतः अहितः - ऐसे रुख पर आधारित, विवेका\nखोये हुए बेवकूफ-जाति के कमीने। ऐसा कठोर कदम दुनिया को नष्ट कर देगा\n\nकारण बनेगा\n\nजो लोग बुरी मानसिकता विकसित कर लेते हैं वे अपने जीवन में दुख लाते हैं और खुद को नष्ट कर लेते हैं\nवे स्वयं इसका कारण बनेंगे। यह उनका विश्वास ही है जो उन्हें नष्ट कर रहा है, वे अंधकार हैं\nवे इस बात का एहसास किए बिना ही उग्रवादी (उग्रकर्मणः) बन जाते हैं कि वे रास्ते पर चल रहे हैं। इस का\nपरिणामस्वरूप, वे संसार के शत्रु बन जाते हैं और संसार के विनाश का कारण बनते हैं। इस प्रकार की मानसिकता है-\nहमारे बीच जो लोग हैं वे असुर हैं।",
  "16.20": "असुरिम योनिम अपन्ना ह मुदः जन्मनिजमानी |\nमम अप्राप्य एव कौन्तेय ततः यन्ति अधमं गतिम्-कौन्तेय, कदुनदेय\nवे कमीने जो झाड़ियों में फिर से पैदा हुए थे, आख़िरकार वहाँ से फिर मेरे साथ नहीं आए\n\nअपमानित हो जाओ.\n\nइस प्रकार बुरे कुल में जन्म लेने वाले ये दुष्ट लोग हर जन्म में अंधे ही बनते हैं\nहर जन्म में भगवान के प्रति उनकी नफरत चरम सीमा पर पहुंच जाती है। अभिमान,\nमदा, दर्प, काम क्रोध अत्यधिक होते हैं और वे स्वयं भ्रष्ट हो जाते हैं। इनमें से कोई भी नहीं\nप्रभु का नहीं है. वह अपने जीवन की गति के अनुसार तमसलोक है\n\nशामिल हो जायेंगे\n\nकृष्ण ने राक्षसों के जीवन स्वभाव, उनके आचरण, वाणी, विचार और क्रियाकलापों की सुन्दर व्याख्या की।\nतो हमारे पास दुनिया में लोककंटक क्यों हैं? उन्हें आगे क्या गति मिलती है?\nविचार समझ में आ गया. हम जानते हैं कि हमारे बिना कब आसुरी गुणों का आक्रमण हम पर होता है\nयह अध्याय हमें जागरूकता और इससे मुक्त होने की इच्छा के साथ भगवान को पुकारने में मदद करता है।\nजीवन का स्वभाव कभी नहीं बदलता. जीवन का कोई स्वतंत्र लेखकत्व नहीं है। लेकिन जीने को तैयार हूं\nएक काम है. तदनुसार, एक निरंतर दिव्य प्रकृति - भगवान के प्रति लगाव - को विकसित करके\nहमें प्रयास करना होगा. यह प्रभु की इच्छा है कि वह फल लाए - हम इसी लिए हैं\nपरेशान मत होइए. जो अच्छा है उससे प्यार करो, जो अच्छा है उसमें संतुष्ट रहो। आपका\nसुरक्षा का भार प्रभु का है, वह आपकी रक्षा करेगा और आपकी रक्षा करेगा।",
  "16.21": "त्रिविधं नरकस्य इदं द्वारं नाशनं आत्मानः |\nकामः क्रोधः तथा लोभः तस्मात् एतत् त्र्यम् त्यजेत - ये आत्मा के नाश के तीन मार्ग हैं,\nनरक के द्वार: वासना, क्रोध और लालच। इसलिए इन तीनों से बचना चाहिए।\n\nयह श्लोक एक बहुत ही महत्वपूर्ण संदेश देता है। यह श्लोक विदुरनीति में भी है\nमहाभारत में इसका सामाजिक एवं आध्यात्मिक दृष्टि से उल्लेख मिलता है। यहाँ कृष्ण हैं\nउन्होंने आत्महत्या की ओर ले जाने वाले तीन कारकों के बारे में बताया। ये हैं काम-क्रोध-लोभ।\nकृष्ण कहते हैं, ये \"मानव नरक के द्वार\" हैं। क्रोध वासना की संतान है. हम गुस्से में हैं\nआने का मतलब है कि हमारे अंदर कई इच्छाएं अंतर्निहित हैं। हमारे लिए जब यह पूरा नहीं होता\nक्रोध महाभारत के अनुशासन पर्व में एक कथा है। एक ब्राह्मण स्त्री; उसका नाम है\nगौतमी. उसका एक ही बेटा है. एक दिन साँप के काटने से उसकी मृत्यु हो जाती है। एक एयरमैन को यह मिला,\nकूनेले ने उस सांप को पकड़ लिया और उसके सामने लाई: “मुझे बताओ, इस सांप ने तुम्हारे बेटे को काट लिया और उसे मार डाला\n\"तुम्हें कैसे मारना पसंद है?\" वह पूछता है. फिर वह कहती है: “नहीं\nब्राह्मणानं कोपोइसति कृतः कोपचा च यतना...\" 13-01-20|. \"हम ब्राह्मण हैं,\nब्राह्मण क्रोध नहीं करता, यदि क्रोध करता है तो वह ब्राह्मण नहीं है।” साँप को मारने से मुर्दा\nबेटा दोबारा जीवित नहीं रह सकता. मेरे पुत्र की मृत्यु उसके कर्मों के अनुसार हुई। क्योंकि क्रोध दुःख नहीं लाता,\n\"उस साँप को छोड़ दो,\" उसने कहा। जिनके पास यह समझ है, उनके पास कोई इच्छा-क्रोध नहीं है\nनहीं आता वह सच्चा ब्राह्मण है। \"काम-क्रोध-लोभ ने हमें इससे छुटकारा दिलाया\nनरक के तीन द्वार जो विनाश की ओर ले जाते हैं, उनसे दूर रहें, ”कृष्ण ने हमें यहां बताया\nचेतावनी दी. ये वे मूल शत्रु हैं जो हमारे व्यक्तित्व को नष्ट कर देते हैं। अन्य सभी विकार\nउनके युवा. मनुष्य इन तीन विकारों से अपना नरक स्वयं निर्मित करता है। यह\n\nतीन के अलावा इसमें भी सुख है और सुख-परा में भी।",
  "16.22": "एतैः विमुक्तः कौन्तेय तम; द्वारैः त्रिबिः नाराः।\n\nअचरति आत्मानः श्रेयः ततः याति परम गतिम्-। कौन्तेय, भाड़ में जाए ये तीन\nगेट से भागकर, नारा वह करने में सक्षम हो जाता है जो उसके लिए अच्छा है। उससे\nवह भी बेहतर हो जाता है.\n\nमानव मेधावी आत्मा नरक के इन तीन द्वारों से बच निकली। वह मोक्ष का मार्ग है\nचिकना हो जाता है. उसे अच्छी गति मिलती है. यहां कृष्ण का अर्थ है 'मुक्त'\nइसका अर्थ सभी इच्छाओं, रजस को त्यागना नहीं है जो हमारे जीवन का अभिशाप है\nऔर तमस का अर्थ है इच्छाओं का त्याग करना। उदाहरण के लिए व्यक्ति को प्रभु से जुड़ना चाहिए\nवह एक इच्छा है. यह नरक का द्वार नहीं है. इसे छोड़ने की कोई जरूरत नहीं है. वासना के बिना कोई जीवन नहीं है.\nइसलिए यहां हमें केवल राजस और तमस पहलू को छोड़ना होगा। यह\nयह सुझाव देने के लिए 'मुक्त' के बजाय 'वी-मुक्त' कहता है।\n\nयहाँ 'काउंटी' विशेषण का प्रयोग हुआ है। “अगर हमें ज्ञान के पथ पर आगे बढ़ना है\nसंदेश एक काउंटेस बनने का है जो इस बुरी वासना-क्रोध-लोभ से घृणा करती है।\nइस विशेषण के पीछे की ध्वनि.\n\nहममें से कुछ लोगों को शास्त्र की कर्मकांडीय पद्धति की आवश्यकता क्यों है, क्या आत्म-साक्षी द्वारा जीना पर्याप्त है? सवाल यह है\nअगले श्लोक में कृष्ण शास्त्र के अनुष्ठानों के पालन के महत्व को बताते हैं।",
  "16.23": "यः शास्त्रविधिम् उत्स ज्या वर्तते कामकारतः |\nनासः सिद्धिं अवाप्नो ति न सुखम्ना परम गतिम् - जैसा कि विज्ञान की सीमाओं से परे कोई पसंद करता है।\nचलने वाला सिद्धि प्राप्त नहीं कर सकता। वह खुश नहीं है; कोई अतिक्रमण नहीं है.\n\nहम शास्त्र की आज्ञा के बिना ईमानदारी से नहीं जी सकते। क्योंकि\nहमें इस बात का कोई एहसास नहीं है कि क्या सही है और क्या ग़लत है। हमें जो पसंद है वही सही है\nहमें पता चल जाएगा. शास्त्र वही हैं जो हमें समझ देते हैं। दुनिया में बहुत से\nहमारे कार्यान्वयन में तथ्यों को शामिल करने के लिए केवल इच्छाशक्ति और ईमानदारी पर्याप्त नहीं है।\nयह सही है या गलत इसका निर्णय करने के लिए शास्त्रों की आवश्यकता है। हम अपने अनुभव से\n\nसम्पूर्ण विश्व को समझा नहीं जा सकता। हमारी बुद्धि सीमित है, हमारा तर्क सीमित है, हमारा विवेक सीमित है\nसीमित, हमारी ईमानदारी सीमित है. इसलिए हमारे पास पूरी दुनिया का अनुभव सीमित है\nसत्य को जाना नहीं जा सकता. इस कारण प्रभु; वेदादि शास्त्र जो उन्होंने संसार को दिये; वह\nहम बुद्धिमान व्यक्ति हैं जो धर्मग्रंथों को समझते हैं और उस ईश्वर को जानते हैं जिसने हमें बताया है\nसच जानिए. अन्यथा कोई सिद्धि नहीं है.",
  "16.24": "आर\nतस्मात् शास्त्रं प्रमाणं ते कार्य अकार्य समस्तमौ |\nज्ञात्वा शास्त्र विधि उक्तं कर्म कर्तुम् एह अरहसि - उससे इच्छाओं और जरूरतों के निष्कर्ष तक।\nविनय शास्त्र आदर्श है। आइए यहां शास्त्र के नियमानुसार कर्म करें।\n\nशास्त्र सभी इच्छाओं और आवश्यकताओं का आदर्श है। ऐसा पहले हम शास्त्रों में कहते हैं\nविश्वास करना चाहिए. तब पता चल सकेगा. शास्त्र में यह करें और वह न करें\nजिन्होंने कहा है- वे बुद्धिमान हैं जिन्होंने इसके प्रभाव को जान लिया है। तो कर्म\nकृष्ण कहते हैं कि क्रम के अनुसार कर्म करो।\n\nयहाँ शास्त्र का अर्थ है चार वेद और उनके पूरक पंचरात्र, महाभारत,\nमूलरामायण, और अठारह पुराण। इसके अलावा और कुछ भी पूर्ण नहीं है\n\nपरिमाणित नहीं किया जा सकता.\n\nइति षोडशोऽध्यायः\nसोलहवाँ अध्याय समाप्त हो गया\n\nक्या यह सच है?\n\nअध्याय सत्रह\n\nकृष्ण ने गीता की शुरुआत में कर्म का वर्णन किया है: “फल के बंधन को त्यागकर भगवान की पूजा करो।\nउन्होंने \"कर्म करो\" का संदेश दिया। कर्म करते समय हमें एक बात जानने की आवश्यकता है\nएक बहुत ही महत्वपूर्ण मुद्दा यह है: क्या अच्छा है और क्या बुरा है। ख़राब\nकाम और अच्छा काम उतना सरल नहीं है जितना हम जानते हैं। हमारे लिए\nऊपर जो अच्छा काम पाया जाता है वह ख़राब काम या ख़राब काम हो सकता है\nअच्छा काम लगता है. यहां कार्य के पीछे की भावना महत्वपूर्ण हो जाती है। एक ही क्रिया\nयह अपने पूर्व भाव के अनुसार अच्छा या बुरा हो सकता है।\nउदाहरणार्थ: महाभारत युद्ध। इस युद्ध में कौरवों की तरह पांडवों ने भी भाग लिया था\nभाग लिया। पांडव सात्विक मानसिकता के थे। वे कभी भी सामाजिक रूप से स्वयं नहीं होते\nमहान पद प्राप्त करने के लिए (राजस भावना), कौरवों को नष्ट करने के लिए (तमस भावना)\nउसने भावना के कारण युद्ध नहीं किया। लेकिन दुर्योधन में केवल रजस और तमस था\nइस कारण से, पांडवों द्वारा किया गया युद्ध सात्विक युद्ध था, जबकि कौरवों द्वारा किया गया युद्ध सात्विक युद्ध था।\nतमस का युद्ध था. तो हम जानते हैं कि सत्कर्म क्या है और बुरा क्या है\nज्ञान प्राप्त करना और कर्म करना बहुत महत्वपूर्ण है। कर्म सत्व है, रजस है,\nयह तीन प्रकार के त्रिगुणों की सीमाओं के भीतर होता है जिन्हें तमस कहा जाता है। हमारा बलिदान, दान,\nतपस्या; हम जो भी भोजन खाते हैं वह इन गुणों से प्रभावित होता है। यह\nजितना संभव हो सके यह जानना कि गुण हमारे कर्म को कैसे प्रभावित करते हैं,\nकर्म सत्त्व की सीमा में रहकर करना चाहिए। यह अध्याय मुख्यतः किस दृष्टिकोण से है\nजब कर्म किया जाता है तो वह कर्म सात्विक, राजस या तामस कर्म हो जाता है\nसमझाता है.\n\nपिछले अध्याय के अंत में, कृष्ण ने कहा, \"वह जो शास्त्र के नियमों से परे जाता है वह एक सिद्धि है\nवह इसे प्राप्त नहीं कर सकता, उसके पास कोई खुशी नहीं है, कोई पूर्णता नहीं है।\" यहाँ हमारे लिए एक प्रश्न है\nजो लोग शास्त्र के नियमों को नहीं जानते - श्रद्धापूर्वक कर्म करते हैं उनकी क्या स्थिति है? वह है।\nयह अध्याय अर्जुन द्वारा हमारी ओर से कृष्ण से यह प्रश्न पूछने से प्रारंभ होता है।\nआइए हम अर्जुन के साथ जुड़ें और भगवान की शिक्षाओं को सुनें।\n\nअर्जुन का भाषण.",
  "17.1": "अर्जुन उवाच- अर्जुन ने पूछा:\n\nये शास्त्रविधिम् उत्सा ज्य यजन्ते श्रद्धया अन्वितः |\n\nतेषाम् निष्ठा तु का कृष्ण सत्त्रं अहो राजः तमः - भले ही कुछ लोग शास्त्र के आदेशों को नहीं जानते हों।\nवे विश्वास से चलते हैं. कृष्ण उनका निवास स्थान क्या है? सत्त्व, रजसे या\nक्या आप हैं?\n\nहमने वेदों का अध्ययन नहीं किया है, हम शास्त्र के विधान को नहीं जानते, बल्कि इसलिये कि हम शास्त्र को नहीं जानते\nपछतावा है; शास्त्र के प्रति समर्पण है, उसके अनुसार जीने की चाहत है। जो जानते हैं\nकहते हैं: \"यदेव विद्याया करोति श्रद्धेय..'' अर्थात \"जो कुछ भी करो, सोच-समझकर करो।\nज्ञान से किया गया कर्म सफल होता है। अन्यथा यह व्यर्थ है।” जब कोई ऐसा हो\nक्या मेहनत व्यर्थ है? यह अर्जुन का प्रश्न है.\n\nयहां \"श्रद्धा\" का अर्थ है- उस अदृश्य शक्ति के बारे में जो पारलौकिक होने के कारण हमें नियंत्रित करती है\nहमारा जो विश्वास है. अर्थ: ईश्वर में विश्वास, शास्त्र में विश्वास, पाप-पुण्य\nविश्वास वह विश्वास है कि एक सर्वोच्च शक्ति है जो सब कुछ नियंत्रित करती है। जैसा कि महाभारत कहता है:\n'कर्म का फल अवश्य होता है। विश्वास ही मानव जीवन का आधार है...जबकि यही बात है\nआस्था के साथ ईमानदारी हो और विज्ञान की समझ न हो तो उनकी जगह क्या है? “सभी को ट्रैक करो\nकर्ता (कृष्ण) ऐसे लोगों को कहाँ घसीटते हो? उनकी निष्ठा सात्विक है,\nराजस या तमसा?” अर्जुन, आप सभी के इस भ्रमित करने वाले प्रश्न पर\nकृष्ण पूछते हैं।\nभगवान का वचन",
  "17.2": "भगवान उवाच - भगवान ने कहा:\nत्रिविधा भवति श्रद्धा देहिनं स सभावजा।\nसात्विकी राजसी च एव तमसे च इति तम श्रृणु - यह जो जीवित प्राणियों के स्वभाव से उत्पन्न होता है।\n\nआस्था तीन प्रकार की होती है: सात्विक, राजस और तमस। इसके बारे में सोचो.\n\nसाधना शरीर में जीव मूलतः तीन प्रकार के होते हैं। यह सात्विक, राजस है\nऔर तमस. इस पर हम फिर से पर्यावरण और परिवार से मनोवैज्ञानिक रूप से प्रभावित होते हैं\nहम तीन गुना परिश्रम का उपयोग करते हैं। अतः वह स्वभाव से सात्विक होते हुए भी सात्विक है\nमानसिक रूप से यह राजसिक या तामसिक हो सकता है। उदाहरण के लिए प्रारूप द्वारा\nगर्गाचार्य, जो सात्विक थे, को एक ऐसा पुत्र पैदा करना चाहिए जो तमस के प्रभाव में कृष्ण को हरा दे\nहमने तपस्या की कहानी देखी है. मानसिक रूप से आने वाला यह बाह्य प्रयास ही जन्म है\nजन्म से नहीं. लेकिन स्वरूपा श्रद्धा हर जन्म में जीवन के साथ रहती है। यह\nस्पष्टीकरण के लिए इस श्लोक में 'इवा' और 'चा' का एक साथ प्रयोग किया गया है।\nसात्विकेवा, राजसेवा या तमसेवा - यह नहीं बदलता है। इस प्रारूप के लिए बाहरी\nश्रद्धा- सात्विकेचा, राजसेचा, तमसेचा-प्रभाव से अधिकतम एक जन्म तक आती है।\nसमर्पित। कृष्ण ने अर्जुन से कहा, \"इन तीन प्रकार की भक्ति के बारे में सोचो।\"\nकहते हैं",
  "17.3": "सत्व अनोरूपा सर्वस्य श्रद्धा भवति भारत।\n\nश्रद्धा मयाः अयं पुरुषः यः यत् श्रद्धा सः एव सः - भारत, सबकी प्रकृति के अनुसार\nआस्था भी है. यह जीवन आस्था का स्वरूप है। वह वही है जो उसका विश्वास है।\n\nजीवन के स्वभाव के अनुसार मूल भक्ति है। लेकिन कई बार ये व्यक्त नहीं हो पाता\nहो सकता है जब यह प्रकट न हो तो मन में जो भी बाहरी प्रभाव सक्रिय हो वह उसका हो\nविश्वास करना. मनुष्य ईमानदारी की कठपुतली है. जिसकी भक्ति का स्वरूप सात्विक है, वह सात्विक है;\nजिसकी भक्ति का स्वरूप राजस है, वह राजस है; जिसकी भक्ति का स्वरूप तमस है वह तमस है।\nतो जीव तीन प्रकार के होते हैं: सात्विक भक्ति वाला जीव - सात्विक जीव; राजस श्रद्धा का जीवन-\nराजसा जीव; तमसा जीव जिसमें श्रद्धा है - तमसा जीव। हम अभी भी ध्यान के साथ मन,\nजब तूरी अवस्था आ जाती है तो बाह्य श्रद्धा लुप्त हो जाती है और केवल स्वरूप श्रद्धा प्रकट होती है।",
  "17.4": "यजन्ते सात्विकः देवां यक्षारक्षणसि राजसः |\nप्रेतं भूतगणां च अन्ये यजन्ते तमसा जनः - सात्त्विक पूजा का श्रेय देवताओं को दिया जाता है,\nराजाओं और राक्षसों के लिए. तमस की पूजा का श्रेय भूतों और भूतगणों को दिया जाता है।\n\nअगर हम ऊपर देखें तो इस श्लोक का कोई मतलब नहीं बनता। ऊपर, “सात्विक\nदेवताओं की पूजा होती है; रजस यक्ष-राक्षस हैं और तमस भूत-प्रेत हैं\nइसे पूजा के रूप में देखा जाएगा. लेकिन यहां जो अंतर्निहित अर्थ छिपा है वह अलग है। हमारे लिए\nजैसा कि आप जानते हैं, सात्विक, राजसरस, तमसरस - वे भगवान की पूजा करते हैं।\nया देवदूत. जादू-टोना करने वालों को छोड़कर और कोई भूत-प्रेत नहीं होता-\nराक्षसों की पूजा नहीं की जाती. इसलिए यदि हम यहां मूल संदेश को समझना चाहते हैं, तो हम\nश्लोक का गहराई से विश्लेषण करना चाहिए. यहां 'देवन्' का अर्थ है: भगवान के अनेक रूप तथा\nइसका अर्थ है 'भगवान के अनुचर देवदूत'। \"यजन्ते सात्विक देवन्\" का अर्थ है - सात्विक\nइसका अर्थ है कि भगवान के दृष्टिकोण से की गई पूजा देवताओं से जुड़ जाती है। उसी प्रकार\n\"यक्षरक्षमसि राजसः\" अर्थात- राजाओं द्वारा की जाने वाली पूजा यक्ष-राक्षसों की होती है।\nराजा आमतौर पर भगवान की सर्वोच्चता से अनजान होते हैं, डर के मारे देवता हम हैं\nवह कष्ट न देने की भावना से पूजा करता है। ऐसे करें पूजा\nजब हम भगवान की पूजा करते हैं तो देवता कहे जाने वाले यक्ष-राक्षस आते हैं\nतीसरा वर्ग तमस है। वे जिसकी पूजा करते हैं वह उनकी स्थिति है\nदिखावे के लिए. उदाहरण के लिए दुर्योधन ने पांडवों द्वारा किया गया अश्वमेध यज्ञ किया\nजिस पर काबू पाने के लिए पुण्डरीक यज्ञ किया गया। इस प्रकार द्वेष के साथ तमस करना\nजो लोग आते हैं और पूजा प्राप्त करते हैं वे देवताओं के नाम पर भूत हैं।\n\nपूजा में केवल भक्ति ही मायने नहीं रखती, बल्कि यह भी महत्वपूर्ण है कि भक्ति किस प्रकार की है। भले ही आप शास्त्र न जानते हों\nसाथ ही, सात्विक निष्ठा के साथ: “हे प्रभु, मैं कुछ नहीं जानता, मैं भक्तिपूर्वक आपकी पूजा करता हूं।\nमैं ऐसा करूंगा, मेरी गलती माफ कर दो'' तो उसने समर्पण कर दिया और खुद ही पूजा करने को कहा\nभगवान स्वयं आकर स्वीकार करते हैं। परन्तु राजस स्वार्थ, अभिमान और अहंकार से होता है\nया तमसा पूजा भगवान या उनके देवताओं के अनुचर द्वारा स्वीकार नहीं की जाती है।\n\nहमारा कर्म निष्काम होना चाहिए। यहां वासना का मतलब वासना है. चाहत में कभी नहीं\nनिःस्वार्थ। हमें इस संकीर्ण भावना को त्याग देना चाहिए कि मेरे लिए क्या अच्छा है।\n\nपुणस्कार पूजा करते समय हमें किसी संकीर्ण इरादे से पूजा नहीं करनी चाहिए।\nउदाहरण के लिए: \"मेरे व्यवसाय में समृद्धि के लिए बलिदान; बेटी के लिए अच्छा दहेज।\"\nपूजा आदि करना। इस प्रकार हम अपनी इच्छाओं को भगवान में सूचीबद्ध करते हैं\nमत दो. भगवान जाने क्या होगा. क्या अच्छा है, क्या है\nकेवल वही जानता है कि क्या बुरा है। वह दे देगा. जबकि मामला यही है\nत्रासदी तब होती है जब हम अपनी इच्छाओं की इतनी संकीर्ण सूची को पकड़कर कर्म करते हैं\nअत्याचारी हम किसी कामना से भगवान की पूजा करते हैं। उस पूजा में पैसे का खर्च\nलेकिन वह इच्छा पूरी नहीं होती. फिर हमने परमेश्‍वर से नफरत की और पैसा बर्बाद किया\nवह परेशान है. तब हमारी पूजा एक व्यवसाय बन जाती है और वह है भूत-प्रेत\nभगवान की पूजा करना व्यवसाय नहीं है।\nअसस्त्रविहितं घोरं तप्यन्ते ये तपो जनः।\n\nदंभहंकारसंयुक्तः कामरागबलन्वितः",
  "17.5": "",
  "17.6": "अस्त्र विहितं घोरं तप्यन्ते ये तपः जनः |\n\nदंभ अहंकार संयुक्तः काम राग बाला अन्विताः\n\nकर्षयन्तः शरीरस्तं भूतग्रामम् अचेतसः।\n\nमाम् च एव अन्तः शरीयस्तं तं विद्धि असुरनिश्चयन् -- कुछ लोग शास्त्र के आदेशों से परे चले जाते हैं।\nबुरे पाप करो; पाखंडी और अपमानजनक ढंग से. इच्छाएँ और रुचियाँ ही उनकी उपलब्धि हैं\nसमर्थन. ऐसे शरारती लोग अपने शरीर [शरीर] में भूत क्षमा का शासन करते हैं।\nदेवतागण] की उपेक्षा की जाती है। वे शरीर के भीतर मेरी महानता को नकारते हैं। ऐसे\nजान लें कि वे तमस प्रकृति के हैं।\n\nयहां कृष्ण बताते हैं कि भक्ति का निम्नतम रूप तमसा श्रद्धा क्या है।\nकुछ लोग शास्त्र के आदेशों से परे तपस्या करते हैं। उस तपस्या के पीछे का उद्देश्य भयंकर है। यहाँ\nतपस्सु केवल ख़ुशी-मुनियों द्वारा की जाने वाली तपस्या नहीं है। जो लगन से किया जाता है\nकर्म भी तप बन सकता है [इस पर अधिक विवरण इस अध्याय के अगले भाग (श्लोक) में है\n14-19)]। तपस्या करें ताकि तपस्या करते समय हमें अच्छा महसूस हो\nसंसार की भलाई के लिए तपस्या कर सकते हैं या कर सकते हैं। उदाहरण के लिए गायत्री:\n\nयहाँ \"धियो योनः प्रचोदयात्\" में है \"हे भगवान, हम सभी को अच्छी बुद्धि दे।\"\nसात्विक भक्ति है. सात्विक संसार में सभी का भला करने की तपस्या है\nप्रायश्चित यह छोड़ो. \"मुझे केवल अच्छा दो\" राजस की पूजा है।\n\"दूसरा बिगड़े-मैं अच्छा बनूँ\" यही उपासना है। तमस ये हैं\nएक विश्व-विध्वंसक क्रूरता।\n\nशास्त्रीय तपस्या का अर्थ है: भगवान की सर्वोच्चता का एहसास करना, दूसरों के बारे में बुरा सोचना।\nबिना कुछ किये संसार में सबका भला करना ही तपस्या है। 'सर्वोत्कर्षे देवा देवस्य।'\n'विष्णो महा तत्पर्यम्' - सभी शास्त्रों में से तात्मार्यम् - का अर्थ है 'सर्वोच्च भगवान'।\nसहमत न होना शास्त्र विरुद्ध है। भावना यह है कि इसे स्वीकार करना दुनिया के लिए बुरा होगा\nमन में उठे तो अनैतिक भी हो जाता है। जो अशास्त्रीय नहीं है\nभगवान को प्रिय नहीं. स्वार्थवश दूसरे का बुरा चाहने से किया गया एक कर्म संबंधी 'जघन्य कार्य'।\nकृष्ण ने यहां चेतावनी दी है कि ऐसा लगेगा. ऐसी हरकत के पीछे पाखंड है और\nअहंकार है. यह देवताओं द्वारा कभी स्वीकार नहीं किया जाता।\n\nकुछ लोग अपने शारीरिक बल से दूसरों को वश में करने की बुरी मंशा रखते हैं\nवे पाप करते हैं. वह जो अपनी इच्छाओं, अपनी इच्छाओं में बाधा डालता है\nयदि वे उत्तर नहीं देते तो उनके मन में यह बुरा विचार आता है कि उन्हें समाप्त कर देना चाहिए। इस प्रकार\nजो लोग अभिमान, अहंकार, संकीर्ण वासना, स्वार्थ, लालच से कार्य करते हैं\nमैकरोन्स वे अपने शरीर को दंडित करते हैं और तपस्या करते हैं। लेकिन उनके लिए, उनका\nशरीर में भूतग्राम (देवताओं का समूह) का ज्ञान नहीं रहता। सारी मंडली\nउपेक्षा करो, देवताओं के भीतर भगवान की उपेक्षा करो, और एक शरीर बन जाओ\nजो क्रियान्वित करता है वह राक्षस है। उन्होंने कहा, 'इंद्रिय कर्म ही सब कुछ है-उससे परे\nवे जानते हैं कि कुछ भी नहीं है.\n\nकृष्ण का यह वर्णन देखकर हमारे-आपके भीतर (प्रभाव से पला हुआ) यह असुर\nहम जानते हैं कि कट्टरता कितनी भयानक होती है. हम अपने-अपने यहां ऐसा करते हैं\nइसे पहचाना जाना चाहिए और कार्रवाई में सुधार किया जाना चाहिए। इसके लिए कृष्ण ने निम्नलिखित श्लोक में भोजन, तप,\nदाना आदि में वे बताते हैं कि सात्विक, राजस और तमस प्रकार कैसे होते हैं।",
  "17.7": "अथरः तु अपि सर्वस्य त्रिविधः भवति प्रियाः।\nयज्ञः तपः तथा दानं तेषाम् भेदं इमाम श्रृणु - तीन खाद्य पदार्थ जो हर कोई खाता है\nतेरानागी पसंदीदा बन गया। यज्ञ भी, तप भी, दान भी। इन्हें ऐसे समझें.\n\nहम जो भोजन करते हैं वह भी त्रिगुणात्मक होता है। सात्विक, राजस और तामस भोजन। “अन्नाम\nअशीतम् त्रेधा विध्याय” (छान्दोग्योपनिषत्-5-1) के अनुसार हम जो भोजन करते हैं।\nहमारे भीतर के प्राण और वैष्णव को तीन प्रकार (सूक्ष्म, मध्य और स्थूल) में विभाजित करें।\nइसकी आपूर्ति शरीर के विभिन्न हिस्सों में की जाती है। सीधे हमारे भोजन और दिमाग पर\nएक रिश्ता है. हमारे पूर्वज यह जानते थे। इसका असर दिमाग पर पड़ता है\nउसने खाना खाने से मना कर दिया. उदाहरण के लिए लहसुन. यह एक औषधीय पदार्थ है. लेकिन ये रूटीन है\nभोजन में उपयोग के लिए निषिद्ध. क्योंकि यह हमारे बौद्धिक विकास के लिए अनुकूल नहीं है। यही तो है\nजैसे जायफल, गोरस आदि। यह अध्ययन करने वालों के लिए (औषधि के रूप में) वर्जित है\nइस्तेमाल किया जा सकता है)। इस प्रकार, पहली बार, किस प्रकार का भोजन मानव बुद्धि के लिए उपयुक्त है\nकृष्ण ने दुनिया को दिया.\n\nभोजन के साथ-साथ हमारी ईश्वर आराधना, तप, हमारी विचार प्रक्रिया, दान, जीवनचर्या,\nइन तीन प्रकारों को सभी भाषणों में पहचाना जा सकता है। अगले श्लोक में कृष्ण भोजन,\nवह बताते हैं कि त्याग, तपस्या और दान इन तीन प्रकारों को कैसे पहचाना जाए।",
  "17.8": "आयुः सत्त्व बल स्वास्थ्य सुख प्रेम विवर्धनः।",
  "17.9": "रस्यः स्निगः नथिरा हृदयः आहारः सात्विक प्रियः - ये सात्विक लोगों द्वारा पसंद किये जाने वाले खाद्य पदार्थ हैं:\nदीर्घायु, अच्छाई, सहनशक्ति, स्वास्थ्य बढ़ाता है; लंबे समय से पसंदीदा;\nइसे खाना अच्छा लगता है; स्वादिष्ट; जैसा कि दीर्घकालिक प्रभाव में होता है\n\nजैसे बार-बार वे मनमोहक होते हैं।\n\nइस श्लोक में कृष्ण सात्विक भोजन के बारे में बताते हैं। हमारी उम्र बढ़ाने के लिए क्या खाना चाहिए?\nपूरक; कौन सा भोजन हमें सौम्यता देता है; शरीर के लिए कौन सा भोजन है\n\nपोषण प्रदान करता है; कोई भी भोजन जो स्वास्थ्य प्रदान करता है वह सात्विक है\nभोजन इस भोजन को देखकर हमें बुरा नहीं लगता। यह रसदार है,\nइसका स्वाद अच्छा है. इसे खाने से हमारा पेट भर जाता है और हमें तुरंत भूख नहीं लगती।\nयह देखने में दिल को छू लेने वाला और खाने में यादगार है।\n\nएक सच्चा सात्विक जो खाता है वह सात्विक भोजन है। प्रकृति प्राकृतिक है,\nरसीला, स्वादिष्ट, फल-हंपालु, कंद-आलू, दाल-अनाज, कन्दा-जड़ें आमतौर पर\nसात्विक भोजन. शुद्ध घी (संयमित मात्रा में उपयोग करने पर) एक सात्विक भोजन है जो जीवन को बढ़ाता है।\n\nकत्तमसलवनत्युष्टतिक्षारुक्षविदहिनः।\n\nअधारा राजसाशेषत् ॥॥19॥\n\nकड़वे अम्ल लवण अति गरम तीक्ष्ण रुक्षा विदेहिनः।\n\nअधारः राजसस्य इष्टः दुःख शोक अमाय प्रदः - ये राजस के पसंदीदा भोजन हैं:\nअत्यधिक नमकीन, खट्टा, नमकीन, बहुत गर्म, तीखा, उबाऊ और आग लगाने वाला; दुखद-\nमतली और बीमारी.\n\nयहाँ कृष्ण ने राजस भोजन का वर्णन किया है। बहुत नमकीन, बहुत खट्टा, बहुत नमकीन,\nराजसा भोजन जैसा दिखता है। बहुत अधिक गर्मी पीना; ज़ोरदार और उबाऊ\nखाना खाना; हृदय को जलाने वाले भोजन का सेवन करना- ये रजस के लक्षण हैं। ये खाना\nइसके सेवन से मानसिक और शारीरिक कष्ट बढ़ता है। यह एक ऐसा भोजन है जो बीमारी ला सकता है।\n\nमिर्च की फली सीधे खाना, इमली का फल हमेशा अधिक खाना\nबहुत अधिक नमक का उपयोग करना, गले को जलाने वाली कॉफी पीना, बहुत अधिक सरसों और मसालों का सेवन करना\nउपयोग, बिना रस वाले भोजन का सेवन (Tasteless food); आदि कुछ राजाओं के आहार के लिए\nउदाहरण\nयह रोगी को सात्विक भोजन लगता है]।",
  "17.10": "यथायमं गतरसं पुति पर्युषितं च यत् |\nउच्छिष्टम अपि च अमेध्यं भोजनं तमसा प्रियम् - यह तमसारि का पसंदीदा व्यंजन है: अत्तु\nबासी, बेस्वाद, बासी, बासी, बचा हुआ और गंदा।\n\nतमसारि के लिए जीवन में सबसे बड़ी चीज भोजन है। वह भगवान का भोजन है\nवे बिना समर्पण के उपभोग करते हैं। नीरस, बासी, दुर्गंधयुक्त, बेस्वाद भोजन\nतमसारी को यह पसंद है. उन्हें बचा हुआ खाना बहुत पसंद है. [उदाहरण के लिए एक ही प्लेट पर कई\nलोग बचा हुआ खाना बाँटकर खाते हैं]।\n\nइस प्रकार भोजन से किसी व्यक्ति की पहचान कैसे की जा सकती है, इसकी विधि भी कृष्ण ने आगे बताई\nवह हमारे अनुष्ठानों (यज्ञ, तपस्या, दान) के माध्यम से व्यक्ति के स्वभाव को जानने की विधि बताते हैं।",
  "17.11": "अफला आकांक्षिबिह यज्ञः विद्धिदृष्टो हाँ इज्यते |\nयश्तव्यं एव इति मनः समाधाय सः सात्त्विक; -विज्ञान के नियमों के अनुसार फल की चिंता किये बिना,\nकर्तव्य की भावना से मन को प्रसन्न करने वाला यज्ञ सात्विक यज्ञ है।\n\nयज्ञ करने वाले सभी लोग सात्विक नहीं होते। यज्ञ में तीन प्रकार के सात्विक राजस और तमस होते हैं\nविविधता है. इस श्लोक में कृष्ण ने बताया है कि सात्विक यज्ञ कैसा होता है। यज्ञ का अर्थ है\nसिर्फ अग्निकुंड में की गई पूजा ही नहीं. पीठ पर भगवान की पूजा करना भी यज्ञ है,\nमानसिक रूप से ईश्वर का ध्यान करना भी एक यज्ञ है। फल की इच्छा रहित, भगवन्\nप्रसन्ना - उनकी कृपादृष्टि मुझ पर बनी रहे, कर्मकाण्ड सात्विक होता है।\nयह एक बलिदान जैसा लगता है. यंत्रवत्, मन्त्र का अर्थ जाने बिना, किसी संकीर्ण स्वार्थवश\n\nई. एम\n\nयदि पूजा की जायेगी तो वह सात्विक यज्ञ नहीं होगा।\n\nयहाँ 'समारोहपूर्वक' कहा गया है। यह बहुत ही महत्वपूर्ण मुद्दा है. उदाहरण के लिए हम\nपूजा करते समय हम घंटियाँ बजाएँगे; शंख चलेगा. ऐसी कोई पूजा नहीं\nयदि कोई विधि है भी, तो उसे करने से पहले हमें यह समझने की आवश्यकता है कि हम ऐसा क्यों कर रहे हैं\n\nआवश्यक घंटी एक साथ जोर से नहीं बजानी चाहिए। घंटी\nइसे बनाते वक्त इसमें से ओमकारा बाहर आना चाहिए।' जब ओंकार नाद इस प्रकार उभरता है-\nजिस क्षेत्र में वह नाड़ा सुनाई देता है वहां की सभी बुरी आत्माएं और यह नाड़ा भाग जाती हैं\nदिव्य ऊर्जाओं को आकर्षित करता है. इससे पूजा के लिए स्वच्छ वातावरण तैयार होता है।\nयहां घंटी बजाकर बुरी आत्माओं के चले जाने, दैवीय आत्माओं के आने की ईमानदारी से प्रार्थना की जाती है\nओंकारण निवारण अत्यंत महत्वपूर्ण है। घंटी से अपस्वर कभी नहीं आना चाहिए। घंटी को\nएक धुन है. सप्त स्वरों में सप्त स्वर घंटियाँ होती हैं। इसे सौहार्दपूर्ण ढंग से खेला जाना चाहिए।' ये है\nओमकारा से वातावरण को शुद्ध करने की अद्भुत प्रक्रिया। यह सिर्फ एक उदाहरण है।\nइस प्रकार हमें अपना प्रत्येक कार्य सचेतन रूप से करना चाहिए; कर रहा है\nहमें कर्म में प्रसन्न रहना चाहिए। इस प्रकार किये जाने पर ही वह सात्विक यज्ञ कहलाता है।",
  "17.12": "अभिसन्धाय तु फलं दम्भ अर्थं अपि च एव यत् |\nइज्यते भरतश्रेष्ठ तम यज्ञं विद्धि राजसम - हे भरतश्रेष्ठ, फल की इच्छा से या\nपाखंड के लिए किया जाने वाला यज्ञ राजस कहलाता है।\n\nस्वार्थवश विशेष फल की चाह से, कपट भाव से किया गया यज्ञ राजस यज्ञ है\nऐसा प्रतीत होता है कि यदि हमें भगवान से जुड़ने के लिए कोई यज्ञ करना है तो उसे भक्ति भाव से करना चाहिए।\nहमें भगवान के प्रति समर्पित लोगों में सबसे महान (भरतश्रेष्ठ) के रूप में कार्य करना चाहिए। इसके बिना प्रमोशन के लिए\nकिया गया यज्ञ राजस यज्ञ बन जाता है।",
  "17.13": "विधिहीनं अश्रृष्टा अन्नं मंत्र हीनं दक्षिणम्।\nश्रद्धा विरथिम् यज्ञं तमसं परीचक्षते शास्त्र सम्मत नहीं है; कोई भोजन दान नहीं; कोई मंत्र नहीं है;\nकोई दक्षिणा नहीं; करने में कोई आस्था नहीं है. ऐसा यज्ञ तामस कहलाता है।\n\nमंत्र का गलत उच्चारण, क्रम से मंत्र का उच्चारण, शब्द उच्चारण\nक्या सही नहीं है- ये सब नाजायज हैं. इस प्रकार किया गया यज्ञ तामसी यज्ञ है। कोई भी\nयज्ञ में भी इसी प्रकार मूर्ति और अग्नि के माध्यम से पूजा की जाती है\nमूर्ति पूजा का बहुत महत्व है. भोजन देने से यह सबके अंदर है\nभगवान की पूजा इस चारमूर्ति की पूजा है। इस प्रकार अन्नदान, दक्षिणा के बिना (वैदिकों के लिए उनका जीवन)।\n(जो सेवा हम भरण-पोषण के लिए करते हैं) उसके बिना किया गया यज्ञ तामस यज्ञ है। इन सब से ऊपर\nपरिश्रम ही कुंजी है. भगवान के प्रति अटूट सर्वोच्च भक्ति के बिना किया गया कोई भी कार्य\nएक यज्ञ होने दो—यह हर जगह एक तमस यज्ञ बन जाता है।\n\nभोजन और यज्ञ के बाद, कृष्ण निम्नलिखित श्लोक में तीन प्रकार की तपस्या बताते हैं।\nतप मूलत: तीन प्रकार के होते हैं। हमारे आचरण में अनुशासन लाना-तपस्या;\nगहन विचार-तपस्या; मन की शुद्धि के लिए तपस्या भी एक शारीरिक दंड है। तपस्या करना\nजंगल जाने की जरूरत नहीं. आप घर पर ही तपस्या कर सकते हैं। सात्विक, राजस और तमस\nतपस्या की व्याख्या करने से पहले यहां कृष्ण के तीन मूल तत्व शरीर, वाणी और मन हैं\nअगले तीन श्लोकों में वे तपस्या की व्याख्या करते हैं।",
  "17.14": "देवा द्विज गुरु प्रज्ञा पूजनं शौचं आर्जवम् |\n\nब्रह्मचर्यम अहिंसा च शरीरं तपः उच्यते - देवता, चेतना से पुनर्जन्म लेते हैं।\nसिद्धि प्राप्त करने वालों, गुरुओं और उन लोगों का सम्मान करना जो सर्वोत्तम, स्वच्छता, सीधा चलना जानते हैं।\nब्रह्मचर्य और दूसरों को कष्ट न देना शरीर का तप माना गया है।\n\nजहां भी भगवान का प्रतीक दिखे, वहां झुकना; बुद्धिमानों को सम्मान देना; बृहस्पति के लिए\nउन अनुभवी लोगों को प्रणाम करें जिन्होंने भगवद्भूति के माध्यम से भगवान का अनुभव किया है\nश्रद्धा- ये सब शरीर तप माने गये हैं। साथ ही साफ-सफाई भी बनाए रखें\nजियो, सीधा बोलो, ब्रह्मचर्य का पालन करो। और दूसरे को. हम से\nबिना कष्ट के जीना शरीर की तपस्या है। [इस श्लोक में शौचम्, आर्जवम् का उल्लेख है\nऔर अहिंसा-सोलहवें अध्याय के शुरुआती श्लोक में इन गुणों का पूरा विवरण है\nवर्णित]। यहां ब्रह्मचर्य पालने का अर्थ है मन को भगवान पर स्थिर करना; उसके लिए\n\nवेदों का पूरक अध्ययन और शारीरिक ब्रह्मचर्य का पालन।\nशारीरिक रूप से पूर्ण ब्रह्मचर्य केवल भिक्षुओं और ब्रह्मचारियों पर लागू होता है।\nग्रह इस तरह नहीं रह सकते. अतः ग्रहों में ब्रह्मचर्य का अर्थ है-\nइसका मतलब यह है कि वे व्यभिचारी नहीं बनते बल्कि ग्रहधर्म के दायरे में रहते हैं। इस प्रकार\nप्रभु में समर्पण करो; ज्ञानी, गुरु, प्रज्ञा, स्वच्छता का सम्मान करना\nअहिंसा का पालन करना, खरा बोलना, ब्रह्मचर्य का पालन करना और जीवन जीना-\nशारीरिक तपस्या. हमें सामाजिक रूप से सभ्य जीवन जीने के लिए यह तपस्या आवश्यक है।\nये शारीरिक नैतिकताएं हैं जिनका मनुष्य को पालन करना चाहिए",
  "17.15": "अनुद्वेगा करं वाक्यं सत्यं प्रिय हितं च यत्।\nस्वाध्याय अभ्यासनं च एव वाज्मयं तपः उच्यते-चिड़चिड़ा, निर्भीक, श्रवण की सराहना करने वाला\nऔर जीवन के लिए अच्छे शब्द और ग्रंथ पढ़ना शब्दों की तपस्या के समान है।\n\nजैसा कि पिछले अध्याय में चर्चा की गई है, चीजों को वैसे ही कहना सच नहीं है जैसे वे हैं। सच क्या है?\nइस श्लोक के माध्यम से कृष्ण ने हमें स्पष्टीकरण दिया है। सच्ची सज्जनता कहाँ है-\nइसकी प्रशंसा करना, इसे पूरक बनाना, इस तरह से जिससे दूसरों को ठेस पहुँचाए बिना प्रसन्न हो\nबोलना वाणी का तप है। दूसरों को प्रिय और सुखद लगने वाले शब्दों का प्रयोग करना बहुत जरूरी है\nकठिन क्योंकि अधिकतर मामलों में जो प्रिय होता है वह सुखद नहीं होता। ऐसे मामलों में चुप्पी\nकृष्ण की कथा पढ़ते समय कई बार कृष्ण ने हमसे झूठ बोला, हमें धोखा दिया\nप्रकट होगा लेकिन यह हमारे लिए है जब हम उस कार्य के पीछे की दयालुता और परोपकार को देखते हैं\nमालूम हो गया कि ये झूठ नहीं है. जब हम अपने दैनिक जीवन में बात करते हैं तो कृष्ण हम हैं\nश्लोक में उल्लिखित संदेश से अवगत होना चाहिए। बिना बोले चुप रहना ठीक है—लेकिन कुछ तो\nबोलने और फिर पछताने से कोई फायदा नहीं है. “खेले गए शब्द के पीछे जाने के लिए\nनहीं कर सकते; घायल मन को ठीक करने के लिए हमारे पास कोई दवा नहीं है।” तो एक और\nकभी भी आहत करने वाले शब्द न बोलें। व्यर्थ की बकवास में दिन न बिताकर वेदों का अर्थ,\nगीता का ध्यान, विष्णुसहस्रनाम का पाठ आदि वाणी का तप है।",
  "17.16": "मनः प्रसादः सौम्यत्वं मौनं आत्मविनिग्रहः।\nभवसंशुद्धि इति एतत् तपः मनसं उच्यते -- अपने ऊपर मन, मन, मन का प्रकार\nसंयम करो और कल्याण करो- इसे मन की तपस्या कहा जाता है।\n\nऊपर बताये गये दो प्रकार के तपों में से जो महान तप है वह मन का तप है। शरीर\nऔर वाणी की तपस्या मन की तपस्या की पूरक होती है। हमारा मन सदैव प्रसन्न रहना चाहिए।\nइसे बुरे विचारों से भर दो। सीमित नहीं होना चाहिए. वह वहां हल्का होना चाहिए\nकोई क्रूरता नहीं होनी चाहिए. किसी एक विषय पर निष्कर्ष पर पहुंचने से पहले गहनता से विचार करें\nआपको सोचना होगा. किसी एक बात, एक व्यक्ति पर जल्दबाजी में प्रतिक्रिया नहीं देनी चाहिए. मन\nकरो, सोचो और बोलो. यदि हमें इस प्रकार ध्यान करना है तो हमें आत्मसंयम का अभ्यास करना होगा\nहासिल किया जाना चाहिए (अधिक विवरण के लिए ए-13, श्लो-7 देखें)। शुद्ध क्रूरता मुक्त मन के लिए\nइंद्रियों पर नियंत्रण होता है. ऐसे मन को बुरा नहीं लगता। एक हमारे बारे में है\nयदि हम बुरा भी बोलते हैं तो भी हमारे मन में उनके प्रति घृणा या क्रोध नहीं आता। ऐसा मन करो\nनियंत्रण करना मन की तपस्या है।\n\nयहां वर्णित तीन प्रकार के तपों में से प्रत्येक के फिर से तीन प्रकार हैं। सात्विक, राजस और\nतमस इसे अगले तीन श्लोकों में समझाया गया है।",
  "17.17": "श्रद्धया पराय तपं तपः तत् त्रिविधं नारैः |\nअपला आकांक्षिभिः युक्तेः सात्विकं परीक्षते - ये तीन प्रकार के तप श्रद्धा से परिपूर्ण हैं,\nइसे सात्विक तप कहा जाता है जब इसे फल की इच्छा किए बिना ईश्वर की भक्ति के साथ किया जाता है।\n\nयदि किसी तप के पीछे अत्यधिक लगन हो तो वह सात्विक तप है। प्रभु का\nसब कुछ परमेश्वर की जागरूकता के साथ किया जाता है, इस इरादे से कि भगवान को प्यार किया जाएगा\nक्रिया- सात्विक क्रिया। उदाहरण के लिए, जब किसी गुरु को प्रणाम किया जाता है, तो वह गुरु का होता है\nअनुसन्धान कि मैं अन्तर्निहित भगवान को प्रणाम कर रहा हूँ। इस प्रकार हम में से प्रत्येक\n\nकर्म के पीछे भगवदर्पण बुद्धि होनी चाहिए। मन्त्र यही कहते हैं. “हे प्रभु\nजब हम गोपालकृष्ण प्रियतः-श्रीकृष्णार्पणमस्तु कहते हैं, तो हमारा भी पूर्ण समर्पण होता है\nभावना से भरपूर होना चाहिए. ऐसा तप सात्विक तप है।",
  "17.18": "सत्कार मन पूजा अर्थं तपः दम्बेन च एव यत्।\nक्रियते तत् इहा प्रोक्तम् राजसम चलम् अध्रुवम् - धन्यवाद, प्रशंसा और सम्मान के लिए\nपाखंडपूर्वक किया गया तप, जिसका कोई आधार न हो, राजस कहलाता है।\n\nभगवान से परामर्श किए बिना, वह लोगों द्वारा सम्मान पाने की इच्छा से ऐसा करता है\nसभी तप राजस तप हैं। इस प्रकार कपटपूर्वक किया गया तप स्वर्ग के योग्य नहीं है।\nइतनी मेहनत का नतीजा यहां भी स्थाई नहीं होता.\n\nइस श्लोक में ईवा और चा-कारा एक साथ आते हैं। यह हमें एक खास संदेश देता है.\nयदि सुख, सम्मान और प्रतिष्ठा के लिए किया गया कार्य राजस कहलाता है; भगवदर्पण\nमन से करो तो इनाम पाओ, समझ पाने के लिए चार लोगों को ज्ञान दो\nयदि आप भावना से उपदेश देंगे तो वह राजसिक नहीं होगा। यह बताने के लिए यहां चौ\nऔर किसके द्वारा उपयोग किया जाता है।",
  "17.19": "कड़वे अम्ल लवण अति गरम तीक्ष्ण रुक्षा विदेहिनः।\n\nअधारः राजसस्य इष्टः दुःख शोक अमाय प्रदः - ये राजस के पसंदीदा भोजन हैं:\nअत्यधिक नमकीन, खट्टा, नमकीन, बहुत गर्म, तीखा, उबाऊ और आग लगाने वाला; दुखद-\nमतली और बीमारी.\n\nयहाँ कृष्ण ने राजस भोजन का वर्णन किया है। बहुत नमकीन, बहुत खट्टा, बहुत नमकीन,\nराजसा भोजन जैसा दिखता है। बहुत अधिक गर्मी पीना; ज़ोरदार और उबाऊ\nखाना खाना; हृदय को जलाने वाले भोजन का सेवन करना- ये रजस के लक्षण हैं। ये खाना\nइसके सेवन से मानसिक और शारीरिक कष्ट बढ़ता है। यह एक ऐसा भोजन है जो बीमारी ला सकता है।\n\nमिर्च की फली सीधे खाना, इमली का फल हमेशा अधिक खाना\nबहुत अधिक नमक का उपयोग करना, गले को जलाने वाली कॉफी पीना, बहुत अधिक सरसों और मसालों का सेवन करना\nउपयोग, बिना रस वाले भोजन का सेवन (Tasteless food); आदि कुछ राजाओं के आहार के लिए\nउदाहरण\nयह रोगी को सात्विक भोजन लगता है]।\n\nयथायमं गतरसं पुति पर्युषितं च यत् |\nउच्छिष्ट मपि चामेध्यं भोजनं तमसाप्रियम्",
  "17.20": "दाताव्यं इति यत् दानं दीयते अनुपकारिणे।\nदेशे काले च पात्रे च तत् दानं सात्विकम् स्मृतम् - कर्तव्य भी प्रत्युपकार के लिए।\nदूरदृष्टि से दिया गया दान, सही देश और समय में सही व्यक्ति को दिया गया दान सात्विक होता है।\n\nबिना किसी प्रत्युत्तर की आशा के, आत्मा आनंदपूर्वक, पूरे हृदय से, प्रेमपूर्वक,\nसही व्यक्ति को, सही समय पर, सही स्थान पर देना; यह मेरा कर्तव्य है\nदूरदर्शितापूर्वक दान करना सात्विक दान है [[अधिक व्याख्या: अध्याय सोलह का आरंभिक श्लोक]।",
  "17.21": "यत् तु प्रत्युपकारार्थं फलं उद्दिष्य वा रे।\nदीते च परिक्षित 0 तत् राजसम उदाहृतम् - प्रत्युत्तर या फल की इच्छा के लिए,\nजो दान नहीं देना चाहिए वह राजसिक लगता है।\n\nदूसरे को भविष्य में हम पर उपकार करने दें या अतीत में किए गए उपकार के बदले में।\nजैसा देना चाहिए वैसा ही देना। दान करते समय फल की इच्छा से देना राजस दान है।",
  "17.22": "आदेश काले यत् दानं अप्रत्रेभ्यः च दीयते।\nअसत् कृतं अवज्ञातम तत् तमसं उदाहृतम् - चातुर्यहीन की भूमि-काल में,\nअयोग्य व्यक्तियों को अंधाधुंध दान देना तामस के समान लगता है।\n\nवह देना जो हम किसी और को नहीं देना चाहते; अयोग्य को दोष दो,\nताना देना, अपमानित करना और देना - तमसा दाना।\n\nइस अध्याय में अगला 'अर्थवाड़ा' है जो कृष्ण द्वारा अब तक वर्णित सात्विक कर्म के महत्व को बताता है\nभाग 'अर्थवाद' का अर्थ सात्विक कर्म के महत्व का प्रतिपादन है।",
  "17.23": "ॐ तत् सत् इति निर्देशः ब्राह्मणः त्रिविधः स्मृतः |\n\nब्राह्मणः तेन वेदः च यज्ञः च विहितः पुरा - ओम [संसार का वाहक और\nवह जो विश्व में व्याप्त है], तत् (वेदों के माध्यम से, केवल अप्रत्यक्ष रूप से जाना जाता है)।\nवह जो सक्षम है] शनि। [वह जो सभी शुभ गुणों से परिपूर्ण है] - ये भगवान के तीन हैं\nनाम. उन भगवान् ने ही वेद, वेदांग और यज्ञों को तैयार किया।\n\nॐ, तत् और सत् ये तीन नाम ईश्वर के हैं। प्रभु, प्रभु की याद के लिए\nइस प्रकार अनुसन्धान का उपयोग ऋषियों द्वारा आह्वान के लिए किया जाता था। प्रभु का नाम हमारा है\nनाम जैसा नहीं. उसका नाम उसका विशेषण है। ओम' भगवान को समर्पित \nनाम यह तीन अक्षरों (ए, यू, एम) में मानव जीवन के सभी पहलुओं को बताता है।\nजिसमें सारा संसार पढ़ा जाता है, जिसमें सारा संसार गुँथा हुआ है - वही ॐ है।\nओमकारा यह कहने के लिए कि हम जो भी कर्म करते हैं वह उसे समर्पित है\nउपयोग यदि शुरुआत में 'हरिः ॐ' कहा जाए - \"आगे बस मुझे ही करना है।\"\nभगवान को समर्पित” जैसा कहा गया है। [ओमकारा के बारे में अधिक व्याख्या के लिए अध्याय-7\nश्लोक 8-9 देखें)।\n\n'ततः' का अर्थ है जो पूर्ण है। भगवान सभी गुणों के स्वामी हैं। जो पूर्ण है वही सब कुछ है\nवेदों से परिपूर्ण है. तो वह \"तत्\" है और \"सत्\" का अर्थ है दोष रहित\nॐ-तत्-सत् वैदिक काल के नाम हैं। अच्युतायनम् हम आज कहते हैं;,\nअनंतायनमः, गोविंदाय नमः भी यही अर्थ देता है। अ-च्युत का अर्थ है जो\nइसका मतलब यह है कि वह स्वभाव से ही भ्रष्ट नहीं है। उसके अतिरिक्त इस संसार का कोई अस्तित्व नहीं है। वह सब कुछ है\nसंसार का आधार. और दूसरा नाम - अनंता. जो बाहर है वह अनंत है। जिनके गुणों का अंत\nअन्यथा वह अनंत है. तीसरा नाम है गोविंदा. गो- अर्थात् वेद। संपूर्ण वेदों से\nप्रतिपद्य प्रभु-गोविन्द। यहाँ संक्षेप में - ॐ तत् सत् का अर्थ है\n“जगदाधर, समस्त गुणपूर्ण, समस्त वेद प्रतिपद्य, समस्त दोष दोरोना\n\nइसका अर्थ है 'भगवान'. ऐसे भगवान ने वेदों की रचना की, जिससे 'ज्ञानी बने'\nउन्होंने ज्ञान से कर्म करने के लिये वेदयज्ञ की रचना की और यज्ञ की रचना की।\n\nहममें से कुछ लोग इसे वेद-'पौरुषेय' कहते हैं, और अन्य वेद-'अपौरुषेय' कहते हैं।\nऐसे लोग हैं जो बहस करते हैं। सृष्टि से पहले भगवान के सर्वोच्च व्यक्तित्व द्वारा उच्चारित वैदिक पौरुषेय; ये है\nभगवान द्वारा प्रत्येक कल्प में अनन्त काल तक अपौरुषेय का उच्चारण किया जाता है।\nहाँ भी. इसलिए इस पर बहस करना व्यर्थ है.",
  "17.24": "",
  "17.25": "तस्मात् ॐ इति उदाहृत्य यज्ञ दान तपः क्रियाः |\n\nप्रवर्तन्ते विधान उक्तः सदातम् ब्रह्मवादिनम् अत: शास्त्र आज्ञा के अनुसार,\nब्रह्मा के भक्तों के यज्ञ, दान और तपस्या में सदैव भगवान का नाम 'ओम' होता है।\nवे स्मृति से जुड़ते हैं।\n\nयहां कृष्ण कर्म में ओंकार के उपयोग के महत्व को बताते हैं। एक जैसा कि हम जानते हैं\nयदि वह वेदज्जा बनना चाहता है, तो उसे ओंकार की शिक्षा देनी होगी; यज्ञ के आरंभ और अंत में ओंकार\nकहना चाहिए; वैदिक जप के आरंभ और अंत में ओंकार होना चाहिए। यह सब अतीत से आता है\nअनुष्ठान. हम जो भी काम करते हैं, उसे शुरू करते समय, \"यह भगवान का है।\"\nइसे पूजा के रूप में करने का संकल्प लेना” और अंत में “मैं\nजो किया गया है उसे भगवान स्वीकार करें'' यही इसका मूल उद्देश्य है। ऐसा ओमकारा ने कहा\nकर्म करने की प्रथा अतीत से बढ़ी है। इस दृष्टिकोण से हमारे पास कोई नहीं है\nयदि कोई पारायण, होम, हवन, यज्ञ, तप, दान करता है तो भी यह सात्विक कर्म माना जाता है।\n\nतात्यानाभिसन्धाय फलं यज्ञतपहक्रियाः।\nदानक्रियाश्च विद्याः क्रियन्ते मोक्षकांक्षिभिः 125।\n\nतत् इति अनाभिसंध्या फलम् यज्ञ तपः क्रियाः |\nदान क्रियाः च विविधः क्रियन्ते मोक्षकांक्षीभिः - फल की इच्छा किये बिना मोक्ष चाहने वाले सज्जन लोग,\n\"तत्\" नामक भगवान के लिए विभिन्न यज्ञ, दान और तपस्या की जाती है।\n\nहमने पहले देखा है कि 'तत्' भगवान को संदर्भित करता है जो संपूर्ण वैदिक पाठ है।\nयहां कृष्ण बताते हैं कि हम जो कर्म करते हैं उसमें \"तत्\" का क्या अर्थ है।\nवेदमाता गायत्री का संक्षिप्त रूप है (Abbreviation; प्रथम और अंतिम अक्षर)।\nइस प्रकार यह भगवान का मुख्य नाम गायत्री वाच्य है। कर्म में 'तत्' है\nइसमें कहा गया है कि भगवान जो फल देते हैं। 'तत्' का अर्थ है किसी भी सांसारिक फल की इच्छा न करना,\nकर्म भगवान के प्रेम के लिए किया जाता है जो बंधन से मुक्त करता है और मोक्ष देता है। बस इतना ही\nत्याग, तपस्या या दान हो सकता है। यहाँ तक कि जब बुद्धिमान लोग दान देते हैं\nवह किसी सांसारिक फल की इच्छा किये बिना दान देता है। उदाहरण के लिए अन्नदान: चावल का प्रशंसक\nलक्ष्मी; अन्नदान का अर्थ है लक्ष्मी से नारायण, दाता के भीतर वैश्वान का रूप\nसमर्पण. इसी प्रकार कन्यादान: कन्यादान के दौरान दूल्हे की संपत्ति, स्थिति,\nदान करना वेतन के बारे में नहीं है. लड़के के अंदर लड़की के बजाय लक्ष्मी\nनारायण को अर्पण करने के भाव से देना। इस प्रकार उद्धारकर्ता\n\"ईश्वर सभी चीजों का कर्ता है-उसकी पूजा ही उसका उद्देश्य है\" की कोई सांसारिक इच्छा नहीं है।\nबिना क्रिया किये. यह \"तत्' है,",
  "17.26": "सत् भवे साधुभावे च सत् इति एतत् प्रयुज्यते |\nप्रशस्ते कर्माणि तथा सत् शब्दः पार्थ युज्यते - पार्थ, 'जन्म' और 'अच्छाई'।\nसत् शब्द का प्रयोग सत् के अर्थ में किया जाता है। सत् शब्द का प्रयोग अच्छे कार्य के अर्थ में भी किया जाता है।\n\n'सत्' का एक अर्थ है. सत्-भाव का अर्थ है विनम्र होना। यह दुनिया में है\nकिसी व्यक्ति के लिए प्रयुक्त मुहावरा। जब इसका उपयोग कर्म में किया जाता है तो यह सत्-कर्म बन जाता है। ओंकार वाच्य\n'सत्'-कर्म भगवान की भक्ति में बिना किसी फल की इच्छा के किया गया कर्म है।\nभगवान के लिए जो भी कर्म किया जाए वह कर्म उत्कृष्ट होना चाहिए। वह है\nयदि यह स्वार्थ के लिए किया जायेगा तो लोग इसकी सराहना नहीं करेंगे। बल्कि त्याग द्वारा किया गया कर्म प्रशस्त है\nकर्म जैसा लगता है. इस प्रकार हम प्रत्येक शब्द का अर्थ जानते हैं और उसका ध्यान रखते हैं\nकृष्ण का संदेश है पार्थ बनो। सत् शब्द का अर्थ आगे विस्तार से बताया जायेगा\nकृष्ण श्लोक में बताते हैं.",
  "17.27": "यज्ञे तपसी दाने च सत्तीः सत् इति च उच्यते |\nकर्म च एव तत् अर्थ्यं सत् इति एव अभिधीयते - यज्ञ-दान-तपस्या में निष्ठा।\nइसे \"सत्\" कहा जाता है। भगवान के लिए किये गये कर्म को \"सत्\" भी कहा जाता है।\n\n\"सत्\" का अर्थ है यज्ञ, दान और तपस्या के माध्यम से \"सत्\" शब्द वाले भगवान की पूजा करना। इस प्रकार\nभगवान भी सत् हैं; उनके कर्म भी सत् हैं; उनके कर्म भी सत् हैं\nकर्ता भी सत् है। हम निष्काम, भगवदर्पण, भगवान से परिचित हैं\nसत-कर्म वे सभी कर्म हैं जो भगवान को प्रसन्न करने के लिए भाव से किए जाते हैं।",
  "17.28": "अश्रद्धया हुतं दत्तं तपः तप्तं कृतं चयत् |\n\nअसत् इति उच्यते पार्थ न च तत् प्रेत न इहा - कर्म करने में परिश्रम के बिना,\nप्रभु में ईमानदारी के बिना, किसी की मजबूरी या डर के बिना, पूर्ण विश्वास के बिना\nकरने का कार्य व्यर्थ है। बिना श्रद्धा के किया गया ऐसा दान, तप, यज्ञ अथवा अन्य कोई कार्य\n\nइसमें कर्म का कोई फल नहीं, परा में कोई फल नहीं।\n\nइति सप्तदशो$ध्यायः\nसत्रहवाँ अध्याय समाप्त हो गया",
  "18.1": "क्या यह सच है?\n\nअध्याय अठारह\n\nपिछले सत्रह अध्यायों में कृष्ण ने बताया कि हमारी उपलब्धि कैसी होनी चाहिए, वह यहाँ है\nउन्होंने उपलब्धि का संदेश संग्रह के रूप में हमारे सामने प्रस्तुत किया है। इस अध्याय के अतिरिक्त\nउपलब्धि के त्रय की एक और व्याख्या भी है जो सत्रह में नहीं बताई गई है।\nयही गीत का निष्कर्ष है. यह अध्याय अर्जुन के प्रश्न से प्रारंभ होता है।\n\nअर्जुन उवाच |\nसंन्यासस्य महाबाहो तत्त्वमिच्छामि वेदितुम |\nत्यागस्य च हृषीकेश पृथक केशिनिसुदाना ॥1॥\n\nअर्जुन उवाच-अर्जुन ने पूछा:\n\nसंन्यासस्य महाबाहो तत्वं इच्छामि वेदितुम।\n\nत्यागस्य च हृषीकेश पृथक केशिनिसुदाना - महाबाहो, तप और त्याग का।\nदूरी कितनी है हे हृषिकेश, मुझे इसकी सच्चाई बताओ, हे केशिनिसुदन।\n\nकृष्ण ने पहले वैराग्य के बारे में कहा था; फिर पिछले अध्याय में यज्ञ, दान, तप\nकर्म कहा. यहां हम थोड़ा भ्रमित हो जाते हैं. तो अर्जुन कृष्ण में कर्मत्यागा\nऔर कर्मसंन्यास पूछता है कि दोनों के बीच कितनी दूरी है? त्याग और तपस्या\nयद्यपि उपरोक्त दोनों शब्दों का अर्थ एक ही प्रतीत होता है, परंतु वे भिन्न हैं।\nसंन्यास और त्याग का मूल अर्थ क्या है 9 इनकी अलग-अलग व्याख्या कैसे करें\nवह अर्जुन का प्रश्न है।\n\nयहां अर्जुन कृष्ण का प्रतिनिधित्व महाबाहो, हृषिकेश और केशिनिसुदन नामक तीन दिव्यांगों द्वारा किया गया है।\nनामों से सम्बोधित किया जाता है। यह केवल उनमें और कृष्ण में गुरुभक्ति को संदर्भित करता है\nयह प्रश्न यहाँ यह समझकर पूछा गया है कि वह वासुदेव का पुत्र नहीं है, बल्कि भगवान का पुत्र है\nयह स्पष्ट है. \"महाबाहु' का अर्थ है लंबे समय तक, कठोर, शत्रुओं का सामना करना\nतोलुगुलुल्लावा का मतलब सतही होता है। बुराई को दबाना और सभ्य की रक्षा करना, सबके अंदर\nइस दिव्य नाम के पीछे मूल अर्थ अज्ञान का नाश करने वाला, जगत का रक्षक है।\nअब 'हृषिका' का अर्थ है इन्द्रियाँ। पिंडदान के भीतर सभी इंद्रियों का नियंत्रण है\nभगवान हृषिकेश. \"केसी' का अर्थ है सूर्य की किरण; वायु देवता ।\n\nसौरमंडल में; प्राणदेव में ही उनका अंतरतम भक्त है; हमारी इच्छाओं को पूरा करना,\n\n“केशिनीसुदन” भगवान हैं जो हमें शक्ति से भर देते हैं। वह ब्रह्मांड और पिंडदान के भीतर संपूर्ण है\nवह महाशक्ति जो ब्रह्मांड को नियंत्रित करती है। (ज्यादातर जगहों पर 'केशिनीशुदाना' शब्द का प्रयोग किया जाता है, लेकिन\nसही शब्द केशिनिसुदन है)।\nभगवान का वचन\nकाम्यानं कर्मं न्यासं संन्यासं कवयो विदुः।\n\nभ्र भ्र\nसर्वकर्मफलत्यागं प्राहुस्वगं विचक्षणः ॥2॥\n\nभगवान उवाच - भगवान ने कहा:\nकाम्यानं कर्मं न्यासं संन्यासं कवयः विदुः |\nसर्वकर्मफल त्यागम् प्राहुः त्यागम् विचक्षणः - जो वासनापूर्ण कर्मों को त्यागना जानता है।\nइसे 'संन्यास' कहा जाता है। जो सभी कर्मों के फल को ही छोड़ना जानता है उसे \"त्याग\" कहते हैं।\nयहां उल्लिखित संन्यास गृहस्थों सहित सभी साधकों पर लागू होने वाला संन्यास है।\nतप दो प्रकार का होता है. एक है कर्म का फल, दूसरा है इच्छाओं से प्रेरित\nकर्म का ही त्याग करना। यहां त्याग का अर्थ कर्म का त्याग करना नहीं है, बल्कि क्या है\nकर्म जो भी हो, करो - बिना कोई परिणाम चाहे। अत: कर्मत्याग\nअर्थात: वेदाध्ययन का त्याग, संध्यावंदन का त्याग, वृतानुष्ठान का त्याग आदि।\nऐसा नहीं बल्कि इसका अर्थ है अच्छे कर्म करना और उसका फल न चाहना। जो\nजो भी कर्म करो, भगवत्प्रेम से करो - फल की इच्छा से नहीं।\nयहाँ दो विशेष शब्दों का प्रयोग हुआ है काव्यः और विचक्षणा। शब्दार्थ\nजो रिश्ते को जानते हैं—कवि; जो अर्थ को जानते हैं, अनुभव करते हैं और मनाते हैं\nटोही. \"कवि और संत तप और त्याग का यही वर्णन करते हैं\"\nकृष्ण ने कहा.",
  "18.2": "भगवान् उवाच —\nकाम्यानां कर्मणां न्यासं संन्यासं कवयो विदुः ।\nसर्वकर्मफलत्यागं प्राहुस्त्यागं विचक्षणाः ॥\n\n'कामना-पूर्ण कर्मों का त्याग — विद्वान् संन्यास कहते हैं। सभी कर्मफलों का त्याग — विचक्षण (विद्वान्) त्याग कहते हैं।'\n\nदो भेद — (१) संन्यास: कामना-प्रेरित कर्मों को छोड़ना — कर्म छोड़ना; (२) त्याग: कर्म करते हुए फलों की आसक्ति छोड़ना — फल छोड़ना। गीता का मत — त्याग श्रेयस्कर।",
  "18.3": "कुछ कहते हैं — दोष है इसलिए कर्म छोड़ना चाहिए। दूसरे कहते हैं — यज्ञ-दान-तप-कर्म नहीं छोड़ना चाहिए।\n\nदो दृष्टिकोण — (१) कर्म दोषयुक्त है इसलिए छोड़ो; (२) यज्ञ-दान-तप मत छोड़ो। कृष्ण दोनों को सुनकर निर्णय देंगे।",
  "18.4": "हे पुरुषव्याघ्र, त्याग के बारे में मेरा यह निश्चित मत सुनो — त्याग तीन प्रकार का कहा गया है।\n\n'पुरुषव्याघ्र' — पुरुषों में सिंह। तीन प्रकार के त्याग — सात्त्विक, राजसिक, तामसिक — का वर्णन होगा। प्रथम कृष्ण का स्वयं का मत प्रस्तुत करते हैं।",
  "18.5": "यज्ञ, दान और तप — ये कर्म छोड़ने योग्य नहीं। यज्ञ, दान, तप — बुद्धिमानों को पवित्र करते हैं।\n\n'न त्याज्यम्' — यज्ञ-दान-तप कभी नहीं छोड़ने चाहिए। 'मेधाविनाम् अपि पावनानि' — बुद्धिमानों को भी पवित्र करते हैं। यह कृष्ण का स्पष्ट मत — केवल फलकामना छोड़नी है, कर्म नहीं।",
  "18.6": "किन्तु हे पार्थ, इन कर्मों को भी आसक्ति और फल छोड़कर करना चाहिए — यही मेरा उत्तम निश्चित मत है।\n\n'एतान्यपि' — इन यज्ञ-दान-तप को भी। 'सङ्गं त्यक्त्वा' — आसक्ति छोड़कर। 'फलानि च' — और फल भी। यही '",
  "18.7": "नियत (विहित) कर्म का संन्यास उचित नहीं। मोह से उसका त्याग तामसिक कहा गया है।\n\n'नियतस्य' — शास्त्रविहित कर्म का। 'संन्यासः' — त्याग। 'मोहात्' — अज्ञान से। 'तामस उदाहृतः' — तामसिक त्याग। मोह से — 'यह कठिन है', 'देह को कष्ट होगा' — ऐसा मानकर कर्म छोड़ना तामस है।",
  "18.8": "दुःखरूप है इसलिए — या देहपीड़ा के भय से — जो कर्म छोड़ता है — वह राजसिक त्याग करता है — उसे त्याग का फल नहीं मिलता।\n\n'दुःखम् इति' — कर्म दुःखदायक है इसलिए। 'देहपीड़ां भयात्' — शारीरिक कष्ट के डर से। यह राजसिक त्याग — 'मुझे कष्ट है' — इस कारण छोड़ना। न सात्त्विक, न तामसिक — राजसिक।",
  "18.9": "हे अर्जुन! कर्तव्य मानकर जो नियत कर्म किया जाता है, संग और फल का त्याग करके, वही",
  "18.10": "सात्त्विक त्याग माना गया है।\n\nनियत कर्म को न करने की स्थिति तक हमारा मन पहुँचना चाहिए। जब सत्त्वगुण मन में भर जाता है, तो किसी भी कर्म को छोड़ने का मन नहीं करता। सदा भगवदर्पण भाव से प्रसन्नतापूर्वक कर्म करना, कोई अहंकार न होना, सभी कर्मों का महत्व समझकर नियत रूप से कर्म करना ही सात्त्विक त्याग है। यहाँ त्याग कर्म का नहीं, बल्कि कर्मफल का किया जाता है।",
  "18.11": "देहधारी के लिए कर्मों का पूर्णतः त्याग सम्भव नहीं। जो कर्मफल का त्यागी है — वही त्यागी कहलाता है।\n\n'अशक्यम्' — शरीर में रहते हुए कर्म छोड़ना असम्भव। 'कर्मफलत्यागी' — जो फल की आसक्ति छोड़ता है — वही वास्तविक त्यागी। कर्म अनिवार्य — फलासक्ति ऐच्छिक।",
  "18.12": "त्याग न करने वालों को मृत्यु के बाद कर्म के तीन प्रकार के फल मिलते हैं — अनिष्ट, इष्ट और मिश्र। संन्यासियों को कहीं भी नहीं।\n\n'अत्यागिनाम्' — जो त्यागी नहीं। 'प्रेत्य' — मृत्यु के बाद। तीन प्रकार — अनिष्ट (बुरा), इष्ट (अच्छा), मिश्र (दोनों)। 'संन्यासिनाम् क्वचित्' — वास्तविक संन्यासियों को कभी नहीं — वे फलातीत।",
  "18.13": "हे महाबाहो, सभी कर्मों की सिद्धि के लिए सांख्यशास्त्र में ये पाँच कारण बताए गए हैं — उन्हें जानो।\n\n'पञ्च एतानि' — पाँच कारण। सांख्यशास्त्र — ब्रह्मसूत्र। 'सर्वकर्मणाम्' — सभी कर्मों की सिद्धि के लिए। ये पाँच — अगले श्लोक में बताए जाएंगे।",
  "18.14": "अधिष्ठान, कर्ता, करण, विभिन्न चेष्टाएँ और पाँचवाँ दैव — ये पाँच कारण हैं।\n\nपाँच कारण — (१) अधिष्ठान (शरीर — कर्म का स्थान); (२) कर्ता (जीव — करने वाला); (३) करण (इन्द्रियाँ — साधन); (४) विभिन्न चेष्टाएँ (प्राण-वायु — विभिन्न क्रियाएँ); (५) दैव (भगवान् — पाँचवाँ, सर्वोपरि)। इनमें 'दैव' = भगवान् — सर्वनियन्ता।",
  "18.15": "मनुष्य शरीर, वाक्, मन से — जो भी न्याय्य या विपरीत कर्म आरम्भ करता है — उसके ये पाँच कारण हैं।\n\n'कायेन वाचा मनसा' — तीन करण। 'न्याय्यं वा विपरीतं वा' — उचित या अनुचित — किसी भी कर्म के ये पाँच कारण। अतः अकेले जीव को कर्ता नहीं माना जा सकता — दैव (भगवान्) का योगदान अनिवार्य।",
  "18.16": "ऐसा होने पर भी जो इस (जगत्) में केवल अपने को कर्ता देखता है — वह दुर्मति अशुद्धबुद्धि के कारण नहीं देख पाता।\n\n'अकृतबुद्धित्वात्' — अशुद्धबुद्धि के कारण। 'न सः पश्यति' — वह नहीं देख पाता। जो केवल जीव को कर्ता मानता है — वह अज्ञानी है। पाँचों कारण देखने वाला — यथार्थदर्शी।",
  "18.17": "जिसका भाव अहंकारयुक्त नहीं, जिसकी बुद्धि लिप्त नहीं — वह इन लोगों को मारकर भी न मारता है, और बँधता भी नहीं।\n\n'यस्य नाहंकृतो भावः' — जिसमें 'मैंने किया' का भाव नहीं। 'बुद्धिर्न लिप्यते' — बुद्धि कर्मफल से नहीं लिपती। ऐसा व्यक्ति कर्म करते हुए भी — निर्लिप्त। यही गीता का कर्मयोगी।",
  "18.18": "ज्ञान, ज्ञेय और परिज्ञाता — ये तीन कर्म की प्रेरणा हैं। करण, कर्म और कर्ता — ये तीन कर्म का संग्रह हैं।\n\n'ज्ञानम्' — ज्ञान (कर्म का उद्देश्य); 'ज्ञेयम्' — जानने योग्य वस्तु; 'परिज्ञाता' — जानने वाला। ये तीन प्रेरणा। 'करणम्' — साधन; 'कर्म' — क्रिया; 'कर्ता' — करने वाला। ये तीन कर्म-संग्रह।",
  "18.19": "गुणसंख्यान शास्त्र में — ज्ञान, कर्म और कर्ता भी तीन-तीन प्रकार के गुणभेद से कहे गए हैं — उन्हें सुनो।\n\n'गुणसंख्यान' — गुणों की संख्या बताने वाला शास्त्र। ज्ञान, कर्म, कर्ता — तीनों त्रिगुणात्मक। सात्त्विक, राजसिक, तामसिक — यह विभाजन आगे होगा।",
  "18.20": "जिस ज्ञान से — विभक्त सभी भूतों में — एक अविभक्त परमतत्त्व दीखता है — वह सात्त्विक ज्ञान जानो।\n\n'अविभक्तं विभक्तेषु' — विभिन्न प्राणियों में एक अविभक्त ब्रह्म (भगवान्) देखना। यह सात्त्विक ज्ञान — सर्वत्र भगवद्व्याप्ति दर्शन। मध्वमत में — 'अविभक्त' = भगवान् (एकः), 'विभक्त' = अनेक जीव।",
  "18.21": "जो ज्ञान सभी भूतों में अलग-अलग भिन्न तत्त्व देखता है — वह राजसिक ज्ञान जानो।\n\n'पृथक्त्वेन तु' — पृथकरूप से। 'नाना भावान् पृथग्विधान्' — अनेक भिन्न-भिन्न तत्त्व। 'सर्वेषु भूतेषु' — सब जीवों में। यह राजसिक ज्ञान — भिन्नता देखता है, किन्तु मूल एकता (भगवान्) नहीं।",
  "18.22": "जो ज्ञान एक कार्य में — जैसे सब कुछ — अकारण, अतत्त्वार्थक और अल्प हो — वह तामसिक कहा गया है।\n\n'एकस्मिन् कार्ये' — एक छोटी वस्तु में। 'सक्तम्' — आसक्त। 'अकारणवत्' — कारणहीन। 'अतत्त्वार्थवत्' — सत्य से रहित। 'अल्पं च' — अल्प। तामसज्ञान — संकुचित, अयुक्तिपूर्ण, अवास्तविक।",
  "18.23": "जो कर्म नियत है, आसक्ति-रहित, राग-द्वेष के बिना, फल की इच्छा के बिना किया जाए — वह सात्त्विक कहा जाता है।\n\nसात्त्विक कर्म — 'नियतम्' (शास्त्रविहित), 'संग-रहित', 'अनुद्वेग', 'निराशी' (फलेच्छा-रहित)। ये चार लक्षण। कर्तव्यभावना से निःसंग होकर किया गया कर्म — सात्त्विक।",
  "18.24": "जो कर्म फलकामना से, या अहंकार से, बहुत परिश्रम से किया जाए — वह राजसिक कहा गया है।\n\n'यत्तु कामेप्सुना' — फल की चाहत से। 'अहंकारेण' — अहंकार से। 'बहुलायासम्' — बहुत परिश्रम से। राजसिक कर्म — फलकामना और अहंकार दोनों से प्रेरित।",
  "18.25": "अनुभव न सोचकर, हानि-बन्धन-सामर्थ्य की परवाह न करके, मोह से जो कर्म आरम्भ किया जाए — वह तामसिक कहा जाता है।\n\n'मोहात्' — मोह से आरम्भ। 'हिंसाम् अनपेक्ष्य' — हिंसा-परिणाम सोचे बिना। 'पौरुषम् अनपेक्ष्य' — अपनी सामर्थ्य सोचे बिना। तामसिक कर्म — मूढ़तापूर्ण, परिणाम-अनालोचित।",
  "18.26": "जो सक्त नहीं, अहंकारशून्य बोलने वाला नहीं, धैर्य और उत्साहयुक्त, सिद्धि-असिद्धि में निर्विकार — वह सात्त्विक कर्ता कहा जाता है।\n\nसात्त्विक कर्ता के लक्षण — (१) असक्त; (२) अनहंवादी (मैं करता हूँ — नहीं कहता); (३) धृतियुत; (४) उत्साहयुत; (५) सिद्धि-असिद्धि में निर्विकार। यही आदर्श कर्मयोगी।",
  "18.27": "जो आसक्त, फल का लालची, लोभी, हिंसक स्वभाव, अशुद्ध, हर्ष-शोक से युक्त है — वह राजसिक कर्ता कहा जाता है।\n\nराजसिक कर्ता — आसक्त, फलार्थी, लोभी, हिंसक, अशुद्ध, हर्ष-शोक में डोलने वाला। इस कर्ता में सात्त्विक कर्ता के सभी गुणों का अभाव।",
  "18.28": "जो अयुक्त, असंस्कृत, हठी, धूर्त, दूसरों की जीविका नष्ट करने वाला, आलसी, विषादी और दीर्घसूत्री है — वह तामसिक कर्ता है।\n\n'अयुक्त' — योगहीन। 'असंस्कृत' — सुसंस्कारहीन। 'शठ' — धूर्त। 'नैष्कृतिक' — दूसरों की जीविका छीनने वाला। 'आलसी, विषादी, दीर्घसूत्री' — तीन अतिरिक्त दोष। तामस कर्ता — समाज को हानिकारक।",
  "18.29": "हे धनञ्जय, बुद्धि और धृति भी — गुणों के अनुसार — तीन प्रकार की हैं — उन्हें मैं अलग-अलग सम्पूर्णतः कहूँगा।\n\n'बुद्धेः भेदम् धृतेश्च' — बुद्धि और धृति दोनों के भेद। 'गुणतः' — गुणों के अनुसार। 'पृथक्त्वेन' — अलग-अलग। यह त्रिगुण विश्लेषण का अगला चरण।",
  "18.30": "हे पार्थ! जो बुद्धि प्रवृत्ति और निवृत्ति, कर्तव्य और अकर्तव्य, भय और अभय तथा बंधन और मोक्ष को ठीक से जानती है, वह बुद्धि सात्त्विकी है।\n\n'प्रवृत्तिं च निवृत्तिं च' — संसार में प्रवृत्त होने का मार्ग और उससे निवृत्त होने का मार्ग। सात्त्विक बुद्धि उचित और अनुचित का भेद स्पष्ट रूप से जानती है।",
  "18.31": "हे पार्थ! जिस बुद्धि से मनुष्य धर्म और अधर्म को, तथा कर्तव्य और अकर्तव्य को ठीक से नहीं समझ पाता, वह बुद्धि राजसी है।\n\n'यया धर्ममधर्मं च' — जिस बुद्धि से धर्म और अधर्म को। 'अयथावत् प्रजानाति' — ठीक से नहीं समझ पाता। उचित और अनुचित के निर्णय में भ्रमित होना ही राजस बुद्धि है।",
  "18.32": "हे पार्थ, जो बुद्धि — अधर्म को धर्म समझती है, और सब अर्थों को विपरीत देखती है — तमोगुण से ढकी हुई — वह तामसिक बुद्धि है।\n\n'तमसा आवृता' — तमोगुण से ढकी। 'सर्वार्थान् विपरीतान्' — सभी अर्थों को उलटा देखती है। 'अधर्मम् धर्मम् इति' — अधर्म को धर्म समझती है। तामसिक बुद्धि — सर्वथा विपरीत।",
  "18.33": "हे पार्थ! जिस अचल योग-शक्ति से मनुष्य मन, प्राण और इन्द्रियों की क्रियाओं को धारण करता है, वह धृति सात्त्विकी है।\n\n'अव्यभिचारिण्या योगेन' — जो कभी विचलित न हो। सात्त्विक धृति मन, प्राण और इन्द्रियों को सन्मार्ग पर लगाए रखती है।",
  "18.34": "हे पार्थ, जिस धृति से — फलकांक्षी व्यक्ति — धर्म, अर्थ, काम को आसक्ति से धारण करता है — वह राजसिक धृति है।\n\n'फलाकांक्षी' — फल की इच्छा वाला। 'प्रसङ्गेन' — आसक्ति से। 'धर्म-काम-अर्थ' — तीन पुरुषार्थ (मोक्ष छोड़कर)। राजसिक धृति — तीन पुरुषार्थों में, मोक्ष नहीं।",
  "18.35": "हे पार्थ, दुर्मेधा व्यक्ति जिस धृति से — निद्रा, भय, शोक, विषाद, मद — इन्हें नहीं छोड़ता — वह तामसिक धृति है।\n\n'दुर्मेधाः' — बुरी बुद्धि वाला। 'न विमुञ्चति' — नहीं छोड़ता। निद्रा-भय-शोक-विषाद-मद — ये पाँच तामसिक बन्धन। तामसिक धृति — इन्हें पकड़े रखती है।",
  "18.36": "हे भरतर्षभ, अब तीन प्रकार के सुख सुनो — जिसमें अभ्यास से रमण होता है और जहाँ दुःख का अन्त होता है।\n\n'त्रिविधं सुखम्' — तीन प्रकार के सुख। 'अभ्यासात् रमते' — अभ्यास से आनन्द मिलता है। 'दुःखस्यान्तं' — दुःख का अन्त। सुख का वर्गीकरण — अनुभव और परिणाम दोनों पर आधारित।",
  "18.37": "जो आरम्भ में विष जैसा लगे और परिणाम में अमृत जैसा हो — वह सुख सात्त्विक कहा जाता है, जो आत्मबुद्धि के प्रसाद से उत्पन्न।\n\n'आदौ विषमिव' — शुरू में कठिन। 'परिणामे अमृतवत्' — अन्त में मधुर। 'आत्मबुद्धिप्रसादजम्' — आत्मज्ञान और बुद्धिशुद्धि से उत्पन्न। सात्त्विक सुख — साधना की कठिनाई के बाद का आनन्द — मोक्षसुख।",
  "18.38": "जो सुख विषय-इन्द्रिय-संयोग से उत्पन्न होता है — आरम्भ में अमृत जैसा, परिणाम में विष जैसा — वह राजसिक कहा गया है।\n\n'विषयेन्द्रियसंयोगात्' — विषय और इन्द्रिय के संयोग से। 'आदौ अमृतोपमम्' — शुरू में मधुर। 'परिणामे विषम् इव' — अन्त में कड़वा। राजसिक सुख — सांसारिक भोग — पहले आकर्षक, बाद में पीड़ाजनक।",
  "18.39": "जो सुख आरम्भ में भी और परिणाम में भी आत्मा को मोहित करे — निद्रा, आलस्य, प्रमाद से उत्पन्न — वह तामसिक कहा गया है।\n\n'आदौ च अन्ते च' — शुरू में भी अन्त में भी। 'आत्मनः मोहनम्' — आत्मा को मोहित करता है। निद्रा-आलस्य-प्रमाद — तीन उत्स। तामसिक सुख — हमेशा नुकसानदेह।",
  "18.40": "पृथ्वी पर, या स्वर्ग में देवों में — कोई भी प्राणी प्रकृतिजन्य इन तीन गुणों से मुक्त नहीं।\n\n'भूमौ वा' — पृथ्वी पर। 'दिवि देवेषु' — स्वर्ग में देवों में। 'तत्त्वम् यत् एभिः तिसृभिः गुणैः मुक्तम्' — जो इन तीन गुणों से मुक्त हो — ऐसा कोई नहीं। त्रिगुण का सर्वव्यापी प्रभाव — केवल भगवान् गुणातीत।",
  "18.41": "हे परन्तप, ब्राह्मण, क्षत्रिय, वैश्य और शूद्रों के कर्म — स्वभावप्रभव गुणों से विभक्त किए गए हैं।\n\n'स्वभावप्रभवैः गुणैः' — स्वभाव से उत्पन्न गुणों द्वारा। 'प्रविभक्तानि' — विभाजित। चारों वर्णों के कर्म — जन्म से नहीं, स्वभाव और गुण से निर्धारित। गीता का वर्ण-सिद्धान्त — गुणकर्मविभागशः।",
  "18.42": "शम, दम, तप, शौच, क्षमा, आर्जव, ज्ञान, विज्ञान, आस्तिक्य — ये ब्राह्मण के स्वभावज कर्म हैं।\n\n'शमः' — मनोनिग्रह। 'दमः' — इन्द्रियनिग्रह। 'तपः' — तपस्या। 'शौचम्' — पवित्रता। 'क्षान्तिः' — क्षमा। 'आर्जवम्' — सरलता। 'ज्ञानम्' — शास्त्रज्ञान। 'विज्ञानम्' — अनुभवज्ञान। 'आस्तिक्यम्' — ईश्वर पर विश्वास। ब्राह्मण का काम — ज्ञान-प्रसार।",
  "18.43": "शौर्य, तेज, धृति, दक्षता, युद्ध से न भागना, दान, ईश्वरभाव — ये क्षत्रिय के स्वभावज कर्म हैं।\n\n'शौर्यम्' — वीरता। 'तेजः' — प्रताप। 'धृतिः' — दृढ़ता। 'दाक्ष्यम्' — कुशलता। 'युद्धे अपलायनम्' — युद्ध से न भागना। 'दानम्' — उदारता। 'ईश्वरभावः' — शासन-कौशल। क्षत्रिय का कर्म — रक्षण और शासन।",
  "18.44": "कृषि, गोपालन, वाणिज्य — वैश्य के स्वभावज कर्म हैं। परिचर्यात्मक (सेवा) कर्म — शूद्र का स्वभावज कर्म है।\n\n'कृषि-गोरक्ष-वाणिज्यम्' — कृषि, गोपालन, व्यापार। 'परिचर्यात्मकम्' — सेवाकार्य। चारों वर्णों के कर्म — गुणों से निर्धारित। समाज के चार कार्य — ज्ञान, रक्षण, उत्पादन, सेवा।",
  "18.45": "अपने-अपने कर्म में तत्पर मनुष्य — सिद्धि कैसे प्राप्त करता है — वह सुनो।\n\n'स्वकर्मनिरतः' — अपने कर्म में लीन। 'सिद्धिं विन्दति' — सिद्धि पाता है। यहाँ से भगवत्-पूजा के माध्यम से सिद्धि का मार्ग बताया जाएगा।",
  "18.46": "जिससे सभी प्राणियों की उत्पत्ति है, जो यह सब व्याप्त है — उस परमात्मा की अपने कर्म से पूजा करके मनुष्य सिद्धि पाता है।\n\n'यतः प्रवृत्तिः भूतानाम्' — जिनसे सब प्राणियों की उत्पत्ति। 'येन सर्वमिदम् ततम्' — जिनसे यह सब व्याप्त। 'स्वकर्मणा अभ्यर्च्य' — अपने कर्म से पूजा करके। यही कर्मयोग का सर्वोच्च सत्य — प्रत्येक कर्म भगवत्पूजा।",
  "18.47": "अच्छी तरह किए गए परधर्म से — अपना स्वधर्म — दोषयुक्त होने पर भी — श्रेयस्कर है। स्वभाव से नियत कर्म करने से पाप नहीं लगता।\n\n'स्वधर्म' — अपना धर्म। 'परधर्म' — दूसरे का धर्म। 'विगुणोऽपि' — दोषयुक्त होने पर भी। 'स्वभावनियतम्' — स्वभाव से नियत। यह गीता का महत्त्वपूर्ण सिद्धान्त — स्वधर्म में दोष होने पर भी परधर्म से उत्तम।",
  "18.48": "हे कौन्तेय, दोष होने पर भी अपने स्वभावजन्य कर्म नहीं छोड़ना चाहिए — क्योंकि सभी कर्म धुएँ से अग्नि की तरह दोष से ढके हैं।\n\n'सहजं कर्म' — स्वभाव से उत्पन्न कर्म। 'न त्यजेत्' — नहीं छोड़ना। 'दोषेण' — दोषयुक्त होने पर भी। 'धूमेन अग्निः इव' — जैसे अग्नि धुएँ से ढकी। कोई भी कर्म पूर्णतः निर्दोष नहीं — फिर भी करना आवश्यक।",
  "18.49": "जिसकी बुद्धि सर्वत्र अनासक्त है, जिसने अपने को जीत लिया है, जो स्पृहारहित है — वह संन्यास से नैष्कर्म्यसिद्धि प्राप्त करता है।\n\n'असक्तबुद्धिः' — आसक्तिरहित बुद्धि। 'जितात्मा' — आत्मविजयी। 'विगतस्पृहः' — स्पृहारहित। 'नैष्कर्म्यसिद्धिम्' — कर्मातीतता की सिद्धि — नैष्कर्म्य = कर्मफलरहितावस्था।",
  "18.50": "हे कुन्तीपुत्र, जो नैष्कर्म्यसिद्धि है — उसे कैसे प्राप्त करके ब्रह्म तक पहुँचता है — वह सुनो — यह ज्ञान की परम भूमिका है।\n\n'नैष्कर्म्यसिद्धिम् प्राप्य' — नैष्कर्म्य प्राप्त करके। 'ब्रह्म अधिगच्छति' — ब्रह्म (श्रीतत्त्व/लक्ष्मी) तक पहुँचता है। 'ज्ञानस्य निष्ठा' — ज्ञान की परम अवस्था। मध्वमत में ब्रह्म = श्रीलक्ष्मी (अक्षर)।",
  "18.51": "शुद्ध बुद्धि से युक्त, दृढ़ आत्मसंयम से, शब्दादि विषयों को त्यागकर, राग-द्वेष छोड़कर।\n\n'विशुद्धबुद्धिः' — शुद्धबुद्धि। 'धृत्या आत्मानम् नियम्य' — धृति से आत्मसंयम। 'शब्दादीन् विषयान् त्यक्त्वा' — शब्दादि विषयत्याग। 'रागद्वेषौ व्युदस्य' — राग-द्वेष त्याग। यह मोक्षमार्ग के लक्षण हैं।",
  "18.52": "एकान्त में रहकर, मितभोजी, वाक्-शरीर-मन को संयमित, नित्य ध्यानयोगपर, वैराग्यसमाश्रित।\n\n'विविक्तसेवी' — एकान्तप्रिय। 'लघ्वाशी' — मितभोजी। 'यतवाक्कायमानसः' — वाक्-काय-मन संयमित। 'ध्यानयोगपरः' — ध्यानयोग में तत्पर। 'वैराग्यम् समुपाश्रितः' — वैराग्य के आश्रित। ये सब साधनामार्ग के उपाय।",
  "18.53": "अहंकार, बल, दर्प, काम, क्रोध, परिग्रह को छोड़कर — निर्मम, शान्त — ब्रह्मभाव के योग्य।",
  "18.54": "ब्रह्मभूत होकर — प्रसन्नात्मा — न शोक करता है न काँक्षा करता है। सभी प्राणियों में समभाव से — मुझ (भगवान्) में परा भक्ति प्राप्त करता है।\n\n'ब्रह्मभूतः' — ब्रह्मभाव में स्थित। 'प्रसन्नात्मा' — प्रसन्न चित्त। 'न शोचति न काँक्षति' — शोक-कामना से रहित। 'सर्वभूतेषु समः' — समभाव। 'मद्भक्तिं लभते परां' — परमभक्ति प्राप्त होती है। मध्वमत — ब्रह्मभूत = श्रीतत्त्वप्राप्त।",
  "18.55": "भक्ति से मुझे तत्त्वतः जानता है — मैं कौन हूँ और कितना हूँ — फिर मुझे तत्त्वतः जानकर प्रवेश करता है।\n\n'भक्त्या माम् अभिजानाति' — भक्ति से ही भगवान् को जानना सम्भव। 'यावान् यश्च अस्मि तत्त्वतः' — कितना और कैसा हूँ — तत्त्वतः। 'ततः माम् तत्त्वतः ज्ञात्वा विशते' — जानकर प्रवेश करता है। यही भागवतीभक्ति का चरम।",
  "18.56": "सभी कर्म करते हुए — मेरी शरण में रहने वाला — मेरी कृपा से शाश्वत अव्यय पद प्राप्त करता है।\n\n'मत्प्रसादात्' — मेरी कृपा से। 'शाश्वतम् अव्ययम् पदम्' — शाश्वत और अव्यय पद = मोक्ष। 'सर्वकर्माण्यपि' — सभी कर्म करते हुए भी। यही भक्तियोग का सार — कर्म करते हुए भगवत्शरण।",
  "18.57": "मन से सभी कर्म मुझे अर्पण करके, मत्परायण, बुद्धियोग के आश्रय से — सदा मुझमें चित्त लगाओ।\n\n'चेतसा सर्वकर्माणि मयि संन्यस्य' — मन से सब कर्म मुझे समर्पित। 'मत्परः' — मुझे परम मानकर। 'बुद्धियोगम् उपाश्रित्य' — बुद्धियोग के आश्रय से। 'मत्चित्तः' — मुझमें चित्त। यह कर्मसंन्यास + बुद्धियोग + भक्ति का समन्वय।",
  "18.58": "मत्चित्त होने से — मेरी कृपा से — सभी बाधाएँ पार करोगे। लेकिन यदि अहंकार से नहीं सुनोगे — विनाश होगा।\n\n'मत्चित्त' — मुझमें चित्त। 'मत्प्रसादात्' — मेरी कृपा से। 'सर्वदुर्गाणि तरिष्यसि' — सभी कठिनाइयाँ पार। 'अथ चेत् अहंकारात् न श्रोष्यसि' — अहंकार से न सुनो तो 'विनंक्ष्यसि' — नष्ट होगे।",
  "18.59": "'मैं नहीं लड़ूँगा' — यह जो संकल्प तुम अहंकार से कर रहे हो — वह मिथ्या है। तुम्हारी प्रकृति तुम्हें (लड़ने के लिए) नियोजित करेगी।\n\n'मिथ्या एषः व्यवसायः' — यह संकल्प मिथ्या। 'अहंकारात्' — अहंकार से। 'प्रकृतिः त्वां नियोक्ष्यति' — तुम्हारी प्रकृति तुम्हें नियोजित करेगी। जीव अस्वतन्त्र — भगवत्-प्रकृतिनियन्त्रित।",
  "18.60": "हे कौन्तेय, जो कर्म तुम मोह से नहीं करना चाहते — वह भी तुम अपनी स्वाभाविक प्रकृति से विवश होकर करोगे।\n\n'स्वभावजेन नियतम्' — स्वाभाविक प्रकृति से नियत। 'मोहात्' — मोह से। 'अवशः अपि' — विवश होकर भी। कर्म अनिवार्य — केवल उसके भाव का प्रश्न। भगवत्शरण में करो — या मोह में करो।",
  "18.61": "हे अर्जुन, सभी प्राणियों के हृदय में ईश्वर स्थित है — उन्हें माया से यन्त्रारूढ़ सब भूतों को भ्रमाता हुआ।\n\n'सर्वभूतानां हृदेशे' — सब प्राणियों के हृदय में। 'तिष्ठति' — स्थित है। 'भ्रामयन्' — घुमाता हुआ। 'यन्त्रारूढानि माययाः' — माया से यन्त्र (शरीर) पर आरूढ़। यह भगवान् का अन्तर्यामित्व — हृदयस्थ ईश्वर — जीव का वास्तविक नियन्ता।",
  "18.62": "हे भारत, सब प्रकार से उसी की शरण जाओ — उसकी कृपा से परम शान्ति और शाश्वत धाम प्राप्त करोगे।\n\n'सर्वभावेन' — सब प्रकार से। 'तम् एव शरणं गच्छ' — उसी की शरण। 'तत्प्रसादात्' — उसकी कृपा से। 'परां शान्तिम्' — परम शान्ति। 'शाश्वतम् स्थानम्' — शाश्वत धाम। यह गीता का केन्द्रीय सन्देश — भगवत्शरण।",
  "18.63": "इस प्रकार मैंने तुम्हें गुह्यतर से भी अधिक गुह्य ज्ञान दिया है — इसे पूर्णतः विचार करके जैसी इच्छा हो वैसा करो।\n\n'गुह्यात् गुह्यतरम्' — गुह्य से भी अधिक गुह्य। 'विमृश्य' — पूर्णतः विचार करके। 'यथेच्छसि तथा कुरु' — जैसी इच्छा वैसा करो। भगवान् स्वतन्त्रता देते हैं — थोपते नहीं। यही भगवान् का महान् उदारत्व।",
  "18.64": "सभी गुह्यों में परम गुह्य मेरे इस परम वचन को फिर सुनो — तुम मुझे अत्यन्त प्रिय हो — इसलिए हितकारी बात कहता हूँ।\n\n'सर्वगुह्यतमम्' — सभी गुह्यों में सबसे गुह्य। 'परमं वचः' — परम वचन। 'दृढम् इष्टः असि मे' — तुम मुझे दृढ़तापूर्वक प्रिय हो। 'तततः वक्ष्यामि ते हितम्' — इसलिए हितकारी कहता हूँ। प्रेम से ही परम गुह्य।",
  "18.65": "मत्परायण हो, मेरा भक्त बनो, मुझे पूजो, मुझे नमस्कार करो — मेरी प्रतिज्ञा, तुम मुझे ही प्राप्त होगे — तुम मुझे प्रिय हो।\n\n'मन्मना भव' — मन मुझमें। 'मद्भक्त' — मेरा भक्त। 'मद्याजी' — मेरा पूजक। 'मां नमस्कुरु' — मुझे नमस्कार। 'माम् एव एष्यसि' — मुझे ही प्राप्त होगे। 'सत्यम् प्रतिजाने' — यह मेरी प्रतिज्ञा। 'प्रियः असि मे' — तुम मुझे प्रिय हो।",
  "18.66": "सभी धर्मों को त्यागकर — केवल मेरी शरण आओ। मैं तुम्हें सभी पापों से मुक्त करूँगा — शोक मत करो।\n\nगीता का 'चरम-श्लोक' — 'सर्वधर्मान् परित्यज्य' = सभी उपधर्मों को (स्वधर्म नहीं) छोड़कर — 'माम् एकं शरणं व्रज' = केवल हरि की शरण। 'सर्वपापेभ्यः मोक्षयिष्यामि' — सब पापों से मुक्त करूँगा। 'मा शुचः' — शोक मत करो।\n\nमध्वमत में 'सर्वधर्मान्' = उपसाधन-धर्म; 'माम् एकम्' = भगवान् विष्णु एकमात्र। यही गीता का परमसन्देश।",
  "18.67": "यह — न तपस्वी को, न भक्तिहीन को — कभी नहीं कहना। जो सुनना नहीं चाहता उसे नहीं, और जो मेरे प्रति द्वेष करता है उसे तो कभी नहीं।\n\nकृष्ण ज्ञान-परम्परा की रक्षा के विषय में बताते हैं — किसे यह गुह्यतम ज्ञान देना। चार अयोग्य व्यक्ति — (१) अतपस्क (अनुशासनहीन); (२) अभक्त; (३) अशुश्रूषु (सुनने की इच्छाहीन); (४) द्वेषी। इनको यह उपदेश न दें।",
  "18.68": "जो इस परम गुह्य को मेरे भक्तों में कहेगा — मुझमें परम भक्ति करके — वह निःसंशय मुझे ही प्राप्त होगा।\n\n'परमं गुह्यम्' — परम रहस्य। 'मद्भक्तेषु' — मेरे भक्तों में। 'परां भक्तिं कृत्वा' — परम भक्ति करके। ज्ञान का प्रसार करना — स्वयं परम भक्ति है। गीताज्ञान देने वाला स्वयं मोक्ष पाता है।",
  "18.69": "मनुष्यों में उससे अधिक मेरा प्रिय कार्य करने वाला कोई नहीं है — और न भविष्य में उससे अधिक प्रिय कोई होगा।\n\n'प्रियकृत्तमः' — सर्वाधिक प्रिय कार्य करने वाला। जो गीता को समझकर भक्तजनों तक पहुँचाता है — वह मनुष्यों में भगवान् को सर्वाधिक प्रिय है। यह गीताशिक्षण का महत्त्व।",
  "18.70": "जो इस हम दोनों के धर्मपूर्ण संवाद का अध्ययन करेगा — उसके द्वारा ज्ञानयज्ञ से मैं पूजित होऊँगा — ऐसा मेरा मत है।\n\n'धर्म्यं संवादम्' — धर्मपूर्ण संवाद = गीता। 'अध्येष्यते' — अध्ययन करेगा। 'ज्ञानयज्ञेन' — ज्ञानयज्ञ से। 'इष्टः स्याम्' — पूजित होऊँगा। गीताध्ययन = ज्ञानयज्ञ = भगवत्पूजा।",
  "18.71": "श्रद्धावान्, द्वेषरहित जो मनुष्य सुने भी — वह भी पाप से मुक्त होकर पुण्यकर्मियों के शुभलोकों को प्राप्त करेगा।\n\n'श्रद्धावान् अनसूयः' — श्रद्धा और द्वेषरहितता — यही सुनने के लिए न्यूनतम योग्यता। 'मुक्तः शुभान् लोकान्' — पाप से मुक्त होकर शुभलोकों को। गीतासश्रवण की न्यूनतम फल।",
  "18.72": "हे पार्थ, क्या यह एकाग्र चित्त से सुना गया? हे धनञ्जय, क्या तुम्हारा अज्ञानजन्य मोह नष्ट हुआ?\n\nयह गीता में कृष्ण का अन्तिम प्रश्न। 'एकाग्रेण चेतसा' — एकाग्र चित्त से। शिक्षक शिष्य से पूछता है — समझ आई? 'अज्ञानसम्मोहः' — अज्ञान से उत्पन्न मोह। 'प्रणष्टः' — नष्ट हुआ? यह गीता का परीक्षण-क्षण।",
  "18.73": "अर्जुन उवाच —\nनष्ट मोहः, स्मृति लब्धा — आपकी कृपा से, हे अच्युत। स्थित हूँ, संशयरहित। आपके वचनानुसार करूँगा।\n\n'नष्टः मोहः' — मोह नष्ट। 'स्मृतिः लब्धा' — स्मृति (यथार्थज्ञान) पुनः मिली। 'त्वत्प्रसादात्' — आपकी कृपा से। 'गतसन्देहः' — संशयमुक्त। 'करिष्ये वचनम् तव' — आपके वचन के अनुसार करूँगा।\n\nयह गीता की परिणति। अर्जुन का परिवर्तन — शोकग्रस्त से ज्ञानयुक्त। 'अच्युत' — कभी न चूकने वाले — भगवान् ने अपना वचन निभाया।",
  "18.74": "संजय उवाच —\nइस प्रकार महात्मा वासुदेव और महात्मा पार्थ के इस अद्भुत, रोमाञ्चकारी संवाद को मैंने सुना।\n\n'अद्भुतं रोमहर्षणम्' — अद्भुत और रोमाञ्चकारी। संजय — जो अपनी दिव्यदृष्टि से देख रहा था — इस संवाद से स्वयं विस्मित। 'वासुदेवस्य पार्थस्य' — दो महात्माओं का संवाद।",
  "18.75": "व्यास की कृपा से मैंने यह परम गुह्य योग — योगेश्वर कृष्ण के सीधे मुख से स्वयं कहते हुए — सुना।\n\n'व्यासप्रसादात्' — व्यास की कृपा से। 'परमम् गुह्यम् योगम्' — परम गुह्य योग = गीता। 'योगेश्वरात् कृष्णात् साक्षात् कथयतः' — योगेश्वर कृष्ण के सीधे मुख से। संजय का सौभाग्य — व्यास के अनुग्रह से प्रत्यक्ष श्रवण।",
  "18.76": "हे राजन्, केशव और अर्जुन के इस पवित्र अद्भुत संवाद को बार-बार स्मरण करके — मैं पुनः-पुनः हर्षित होता हूँ।\n\n'संस्मृत्य संस्मृत्य' — बार-बार स्मरण करके। 'पुण्यम् अद्भुतम्' — पवित्र और अद्भुत। 'हृष्यामि च मुहुः मुहुः' — पुनः-पुनः हर्षित होता हूँ। संजय का अनुभव — गीता की स्मृति मात्र से आनन्द।",
  "18.77": "हे राजन्, हरि के उस अत्यद्भुत रूप को बार-बार स्मरण करके — मुझे महान् विस्मय होता है और पुनः-पुनः हर्षित होता हूँ।\n\n'हरेः रूपम् अत्यद्भुतम्' — हरि का अत्यद्भुत रूप = विश्वरूप। 'संस्मृत्य संस्मृत्य' — बार-बार। 'विस्मयः मे महान्' — महान् विस्मय। संजय को विश्वरूपदर्शन मिला था — उसकी स्मृति से भी रोमाञ्च।",
  "18.78": "जहाँ योगेश्वर कृष्ण हैं, जहाँ धनुर्धर पार्थ हैं — वहाँ श्री, विजय, विभूति और ध्रुव नीति है — यही मेरा मत है।\n\nगीता का अन्तिम श्लोक। 'योगेश्वरः कृष्णः' — योगशक्तियों के स्वामी। 'पार्थः धनुर्धरः' — धनुर्धारी पार्थ = नर-नारायण। 'श्री-विजय-भूति-ध्रुवा-नीतिः' — लक्ष्मी, विजय, ऐश्वर्य, स्थिरनीति। जहाँ भगवान् हैं और भक्त है — वहाँ सब है।\n\nमध्वाचार्य — 'नर-नारायण' — जहाँ नारायण हैं और उनका भक्त नर है — वहाँ सर्वसम्पत्।\n\nइति अष्टादशोऽध्यायः — मोक्षसंन्यासयोगः।\nइति श्रीमद्भगवद्गीतासूपनिषत्सु ब्रह्मविद्यायां योगशास्त्रे श्रीकृष्णार्जुनसंवादे मोक्षसंन्यासयोगो नामाष्टादशोऽध्यायः।"
};

if (typeof module !== 'undefined') {
  module.exports = window.BANNANJE_VERSE_MEANINGS_HI;
}
